    def insert_policy_acceptance(
        self,
        user_id,
        company_id,
        policy_type,
        policy_version,
        ip_address=None,
        user_agent=None
    ):
        return self.execute_sql(
            """
            INSERT INTO public.legal_policy_acceptances
                (user_id, company_id, policy_type, policy_version, ip_address, user_agent)
            VALUES (%s, %s, %s, %s, %s, %s)
            RETURNING id;
            """,
            (user_id, company_id, policy_type, policy_version, ip_address, user_agent),
        )

    def create_company_relationship(
        self,
        *,
        parent_company_id: int,
        child_company_id: int,
        relationship_type: str,
        ownership_percent=None,
        voting_percent=None,
        control_basis=None,
        consolidation_method=None,
        effective_from=None,
        notes=None,
    ):
        with self._conn_cursor() as (_conn, cur):
            cur.execute("""
                INSERT INTO public.company_relationships (
                    parent_company_id,
                    child_company_id,
                    relationship_type,
                    ownership_percent,
                    voting_percent,
                    control_basis,
                    consolidation_method,
                    effective_from,
                    notes
                )
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s)
                RETURNING id
            """, (
                parent_company_id,
                child_company_id,
                relationship_type,
                ownership_percent,
                voting_percent,
                control_basis,
                consolidation_method,
                effective_from,
                notes,
            ))
            row = cur.fetchone()
            return row["id"] if row else None
        
    def create_company_invite(
        self, *,
        company_id: int,
        email: str,
        role: str,
        access_scope: str,
        note: str | None,
        created_by: int | None,
        ttl_seconds: int
    ) -> dict:
        token = secrets.token_urlsafe(32)
        expires_at = datetime.now(timezone.utc) + timedelta(seconds=int(ttl_seconds))

        with self._conn_cursor() as (conn, cur):
            cur.execute("""
                INSERT INTO public.company_invites
                    (token, company_id, email, role, access_scope, note, created_by, expires_at)
                VALUES (%s,%s,%s,%s,%s,%s,%s,%s)
                RETURNING token, company_id, email, role, access_scope, expires_at;
            """, (
                token,
                int(company_id),
                email.lower().strip(),
                role.strip().lower(),
                (access_scope or "core").strip().lower(),
                note,
                created_by,
                expires_at
            ))

            row = cur.fetchone()
            conn.commit()
            return dict(row) if row else {}

    def get_company_invite_by_token(self, token:str) -> dict|None:
        return self.fetch_one("""
        SELECT i.*, c.name AS company_name
        FROM public.company_invites i
        JOIN public.companies c ON c.id = i.company_id
        WHERE i.token=%s
        LIMIT 1;
        """, (token.strip(),))

    def mark_invite_accepted(self, *, token:str, user_id:int) -> None:
        self.execute_sql("""
        UPDATE public.company_invites
        SET accepted_at=NOW(), accepted_by_user_id=%s
        WHERE token=%s AND accepted_at IS NULL AND revoked_at IS NULL;
        """, (int(user_id), token.strip()))

    def upsert_company_user(
        self,
        *,
        company_id: int,
        user_id: int,
        role: str,
        access_scope: str = "core",
        membership_kind: str = "secondary",
        is_primary: bool = False,
    ):
        scope = (access_scope or "core").strip().lower()
        if scope not in ("core", "assignment"):
            scope = "core"

        norm_role = validate_role_for_scope(role, scope)
        kind = (membership_kind or "secondary").strip().lower()

        if scope not in ("core", "assignment"):
            scope = "core"

        if kind not in ("primary", "secondary"):
            kind = "secondary"

        # only one primary per user
        if is_primary:
            self.execute_sql(
                """
                UPDATE public.company_users
                SET is_primary = FALSE
                WHERE user_id = %s
                AND is_primary = TRUE
                """,
                (int(user_id),)
            )

        self.execute_sql(
            """
            INSERT INTO public.company_users
                (
                    company_id,
                    user_id,
                    role,
                    access_scope,
                    membership_kind,
                    is_primary,
                    joined_at,
                    is_active
                )
            VALUES (%s, %s, %s, %s, %s, %s, NOW(), TRUE)
            ON CONFLICT (company_id, user_id) DO UPDATE
            SET
                role = EXCLUDED.role,
                access_scope = EXCLUDED.access_scope,
                membership_kind = EXCLUDED.membership_kind,
                is_primary = EXCLUDED.is_primary,
                is_active = TRUE,
                joined_at = COALESCE(public.company_users.joined_at, NOW());
            """,
            (
                int(company_id),
                int(user_id),
                norm_role,
                scope,
                kind,
                bool(is_primary),
            )
        )

