    def insert_user(
        self,
        email: str,
        password_hash: str,
        user_type: str,
        first_name: str,
        last_name: str,
        user_role: str,
        is_confirmed: bool,
        confirmation_token: Optional[str],
        trial_start_date: Optional[Union[str, date]],
        trial_end_date: Optional[Union[str, date]],
        company_id: Optional[int] = None,
        confirmation_token_expires_at: Optional[datetime] = None,  # ✅ NEW
    ) -> Optional[int]:
        access_level = 'PRACTITIONER_ADMIN' if user_type == 'Practitioner' else 'ADMIN'

        sql = """
        INSERT INTO public.users
            (email, password_hash, user_type, first_name, last_name, user_role,
            is_confirmed, confirmation_token, confirmation_token_expires_at,
            trial_start_date, trial_end_date, company_id, access_level)
        VALUES
            (%s, %s, %s, %s, %s, %s,
            %s, %s, %s,
            %s, %s, %s, %s)
        RETURNING id;
        """

        params = (
            email, password_hash, user_type, first_name, last_name, user_role,
            is_confirmed, confirmation_token, confirmation_token_expires_at,
            trial_start_date, trial_end_date, company_id, access_level
        )

        return self.execute_sql(sql, params)

    def set_company_owner(self, company_id: int, owner_user_id: int) -> None:
        self.execute_sql(
            """
            UPDATE public.companies
            SET owner_user_id = %s
            WHERE id = %s
            """,
            (owner_user_id, company_id),
        )

    def update_user(self, user_id: int, **kwargs: Any) -> bool:
        if not kwargs:
            return True
        set_clauses = [f"{k} = %s" for k in kwargs.keys()]
        sql = f"""
        UPDATE public.users SET {', '.join(set_clauses)}
        WHERE id = %s;
        """
        params = tuple(kwargs.values()) + (user_id,)
        try:
            with self._conn_cursor() as (_c, cur):
                cur.execute(sql, params)
                return cur.rowcount > 0
        except Exception as e:
            print(f"Error updating user {user_id}: {e}")
            return False

    def get_user_by_id(self, user_id: int) -> Optional[Dict[str, Any]]:
        sql = """
        SELECT id, email, password_hash, user_type, company_id, access_level, is_confirmed,
            password_reset_token, token_expiry, first_name, last_name, user_role,
            is_active
        FROM public.users
        WHERE id = %s
        LIMIT 1;
        """
        return self.fetch_one(sql, (user_id,))

    def get_user_context(
        self,
        *,
        user_id: int,
        company_id: int | None,
        delegated_fallback: dict | None = None,
    ) -> Optional[dict]:
        """
        Returns the authenticated user with the correct per-company role applied.

        Source of truth:
        - direct membership: public.company_users.role
        - delegated access: delegated_fallback supplied by require_auth
        """
        u = self.get_user_by_id(int(user_id))
        if not u:
            return delegated_fallback if delegated_fallback else None

        # no company context
        if not company_id:
            if delegated_fallback:
                merged = {**u, **delegated_fallback}
                return merged
            return u

        mem = self.fetch_one(
            """
            SELECT company_id, role, access_level, access_scope, is_active
            FROM public.company_users
            WHERE company_id=%s AND user_id=%s
            LIMIT 1;
            """,
            (int(company_id), int(user_id)),
        )

        # direct membership path
        if mem:
            if not bool(mem.get("is_active", True)):
                return None

            u["company_id"] = int(company_id)

            r = (mem.get("role") or "").strip()
            u["user_role"] = normalize_role(r) if r else "other"
            u["company_role"] = u["user_role"]

            if mem.get("access_level"):
                u["access_level"] = mem.get("access_level")

            if mem.get("access_scope"):
                u["access_scope"] = str(mem.get("access_scope")).strip().lower()

            u["is_native_company_member"] = True
            u["is_delegated_company_access"] = False
            return u

        # delegated fallback path
        if delegated_fallback:
            merged = {**u, **delegated_fallback}
            merged["company_id"] = int(company_id)
            merged["is_native_company_member"] = False
            merged["is_delegated_company_access"] = True

            role_raw = (
                merged.get("user_role")
                or merged.get("company_role")
                or merged.get("role")
                or "viewer"
            )
            merged["user_role"] = normalize_role(str(role_raw).strip())
            merged["company_role"] = merged["user_role"]

            if merged.get("access_scope"):
                merged["access_scope"] = str(merged["access_scope"]).strip().lower()

            return merged

        return None

    def build_delegated_workspace_permissions(
        self,
        *,
        user_id: int,
        source_company_id: int,
        target_company_id: int,
        engagement_id: int,
        base_payload: dict | None = None,
        role: str = "viewer",
    ) -> dict:
        base_payload = base_payload or {}
        incoming = base_payload.get("permissions") or {}
        role = normalize_role(role)

        # local dashboard-role sets to avoid circular imports
        enterprise_roles = {
            "owner",
            "admin",
            "cfo",
            "manager",
            "senior",
            "accountant",
            "clerk",
        }

        practitioner_roles = {
            "bookkeeper",
            "fs_compiler",
            "audit_staff",
            "senior_associate",
            "audit_manager",
            "client_service_manager",
            "reviewer",
            "audit_partner",
            "engagement_partner",
            "quality_control_reviewer",
        }

        dual_dashboard_roles = {
            "owner",
            "audit_partner",
            "engagement_partner",
            "audit_manager",
            "client_service_manager",
        }

        preparer_roles = {
            "bookkeeper",
            "accountant",
            "clerk",
            "fs_compiler",
            "audit_staff",
            "senior_associate",
            "reviewer",
            "quality_control_reviewer",
        }

        manager_roles = {
            "manager",
            "audit_manager",
            "client_service_manager",
            "cfo",
        }

        executive_roles = {
            "owner",
            "admin",
            "audit_partner",
            "engagement_partner",
        }

        perms = {
            "can_view_dashboard": True,
            "can_view_reports": True,
            "can_manage_ar": False,
            "can_manage_ap": False,
            "can_manage_banking": False,
            "can_post_journals": False,
            "can_prepare_financials": False,
            "can_manage_fixed_assets": False,
            "can_approve": False,
            "can_view_control_room": False,
            "can_view_ar_ap_controls": False,

            "can_manage_users": False,
            "can_manage_company_setup": False,
            "can_edit_tax_settings": False,
            "can_lock_periods": False,

            # new engagement / interpretation permissions
            "can_view_engagements": False,
            "can_manage_engagements": False,
            "can_view_statement_interpretation": False,
            "can_manage_loans": False,

            # delegated workspace shell
            "can_access_enterprise_dashboard": False,
            "can_access_practitioner_dashboard": False,
            "can_access_delegated_posting_workspace": True,
        }

        # dashboard access model for delegated workspace
        if role in dual_dashboard_roles:
            perms["can_access_enterprise_dashboard"] = True
            perms["can_access_practitioner_dashboard"] = True
        else:
            perms["can_access_enterprise_dashboard"] = role in enterprise_roles
            perms["can_access_practitioner_dashboard"] = role in practitioner_roles

        # preparers / reviewers
        if role in preparer_roles:
            perms["can_manage_ar"] = True
            perms["can_manage_ap"] = True
            perms["can_post_journals"] = True
            perms["can_manage_loans"] = True  # ✅ add
            perms["can_view_ar_ap_controls"] = True
            perms["can_prepare_financials"] = True
            perms["can_manage_fixed_assets"] = True
            perms["can_view_engagements"] = True
            perms["can_view_statement_interpretation"] = True

        # managers / controllers
        if role in manager_roles:
            perms["can_manage_ar"] = True
            perms["can_manage_ap"] = True
            perms["can_manage_banking"] = True
            perms["can_post_journals"] = True
            perms["can_prepare_financials"] = True
            perms["can_manage_fixed_assets"] = True
            perms["can_approve"] = True
            perms["can_manage_company_setup"] = True
            perms["can_edit_tax_settings"] = True
            perms["can_view_control_room"] = True
            perms["can_view_ar_ap_controls"] = True
            perms["can_view_engagements"] = True
            perms["can_manage_engagements"] = True
            perms["can_view_statement_interpretation"] = True
            perms["can_manage_loans"] = True

        # executive / partner level
        if role in executive_roles:
            perms["can_manage_ar"] = True
            perms["can_manage_ap"] = True
            perms["can_manage_banking"] = True
            perms["can_post_journals"] = True
            perms["can_prepare_financials"] = True
            perms["can_manage_fixed_assets"] = True
            perms["can_view_reports"] = True
            perms["can_approve"] = True
            perms["can_manage_company_setup"] = True
            perms["can_edit_tax_settings"] = True
            perms["can_lock_periods"] = True
            perms["can_view_control_room"] = True
            perms["can_view_ar_ap_controls"] = True
            perms["can_view_engagements"] = True
            perms["can_manage_engagements"] = True
            perms["can_view_statement_interpretation"] = True
            perms["can_manage_loans"] = True

        # dual-dashboard roles should behave like enterprise executives in delegated workspace
        if role in dual_dashboard_roles:
            perms["can_view_statement_interpretation"] = True
            perms["can_view_reports"] = True
            perms["can_prepare_financials"] = True

        # safety: anyone who can prepare or approve can view interpretation
        if perms["can_prepare_financials"] or perms["can_approve"]:
            perms["can_view_statement_interpretation"] = True

        bounded_keys = [
            "can_view_dashboard",
            "can_view_reports",
            "can_manage_ar",
            "can_manage_ap",
            "can_manage_banking",
            "can_post_journals",
            "can_manage_loans",
            "can_prepare_financials",
            "can_manage_fixed_assets",
            "can_approve",
            "can_view_control_room",
            "can_view_ar_ap_controls",
            "can_manage_users",
            "can_manage_company_setup",
            "can_edit_tax_settings",
            "can_lock_periods",
            "can_view_engagements",
            "can_manage_engagements",
            "can_view_statement_interpretation",
            "can_access_enterprise_dashboard",
            "can_access_practitioner_dashboard",
            "can_access_delegated_posting_workspace",
        ]

        for key in bounded_keys:
            if key in incoming:
                perms[key] = bool(perms[key] and incoming.get(key))

        perms["_delegated_meta"] = {
            "user_id": int(user_id),
            "source_company_id": int(source_company_id),
            "target_company_id": int(target_company_id),
            "engagement_id": int(engagement_id),
            "role": role,
            "dashboard_access": {
                "enterprise": bool(perms["can_access_enterprise_dashboard"]),
                "practitioner": bool(perms["can_access_practitioner_dashboard"]),
            },
        }

        return perms
    
    def get_delegated_workspace_for_engagement(
        self,
        cur,
        *,
        company_id: int,
        engagement_id: int,
        user_id: int,
    ) -> Optional[dict]:
        schema = self.company_schema(company_id)

        sql = f"""
            SELECT
                e.id,
                e.company_id,
                e.target_company_id,
                e.engagement_name,
                e.workspace_status,
                e.is_active,
                et.role_on_engagement,
                c.name AS target_company_name
            FROM {schema}.engagements e
            JOIN {schema}.engagement_team et
            ON et.engagement_id = e.id
            AND et.company_id = e.company_id
            LEFT JOIN public.companies c
            ON c.id = e.target_company_id
            WHERE e.company_id = %s
            AND e.id = %s
            AND et.user_id = %s
            AND COALESCE(et.is_active, TRUE) = TRUE
            AND COALESCE(e.is_active, TRUE) = TRUE
            AND LOWER(COALESCE(e.workspace_status, '')) = 'provisioned'
            LIMIT 1
        """
        cur.execute(sql, (int(company_id), int(engagement_id), int(user_id)))
        return cur.fetchone()

