    def list_company_ids(self) -> list[int]:
        """Return all company IDs from the master companies table."""
        with self._conn_cursor() as (conn, cur):
            cur.execute("SELECT id FROM public.companies ORDER BY id;")
            rows = cur.fetchall() or []
            # RealDictCursor -> rows are dicts like {"id": 6}
            return [int(r["id"]) for r in rows if r and r.get("id") is not None]

