            purchases_discount_code = COALESCE(NULLIF(public.company_account_settings.purchases_discount_code,''), EXCLUDED.purchases_discount_code),

            inventory_control_code = COALESCE(NULLIF(public.company_account_settings.inventory_control_code,''), EXCLUDED.inventory_control_code),

