            ppv_control_code  = COALESCE(NULLIF(public.company_account_settings.ppv_control_code,''),  EXCLUDED.ppv_control_code),

            unallocated_receipts_code = COALESCE(NULLIF(public.company_account_settings.unallocated_receipts_code,''), EXCLUDED.unallocated_receipts_code),
            unallocated_payments_code = COALESCE(NULLIF(public.company_account_settings.unallocated_payments_code,''), EXCLUDED.unallocated_payments_code),

            wht_payable_code = COALESCE(NULLIF(public.company_account_settings.wht_payable_code,''), EXCLUDED.wht_payable_code),

