    def list_workspace_companies_for_user(self, user_id: int) -> List[Dict[str, Any]]:
        sql = """
        SELECT
            c.id,
            c.name,
            c.client_code,
            c.industry,
            c.sub_industry,
            c.currency,
            c.fin_year_start,
            c.company_reg_date,
            c.is_active,
            c.owner_user_id,
            c.country,
            c.company_reg_no,
            c.tin,
            c.vat,
            c.company_email,
            c.created_at,
            cu.role,
            cu.is_active AS membership_active,
            cu.access_scope,
            CASE WHEN c.owner_user_id = %s THEN TRUE ELSE FALSE END AS is_owner
        FROM public.company_users cu
        JOIN public.companies c
        ON c.id = cu.company_id
        WHERE cu.user_id = %s
        AND cu.is_active = TRUE
        AND c.is_active = TRUE
        ORDER BY
        CASE WHEN cu.access_scope = 'core' THEN 0 ELSE 1 END,
        c.created_at DESC;
        """
        return self.fetch_all(sql, (int(user_id), int(user_id)))

