    def get_default_account_by_family(self, company_id: int, family: str) -> Optional[str]:
        schema = f"company_{company_id}"
        row = self.fetch_one(
            f"""
            SELECT code
            FROM {schema}.coa
            WHERE code_family = %s
            ORDER BY code_numeric NULLS LAST, code ASC
            LIMIT 1
            """,
            (family,),
        )
        if not row:
            return None
        return row["code"] if isinstance(row, dict) else row[0]


    def get_default_account_by_bucket(self, company_id: int, bucket: str) -> Optional[str]:
        schema = f"company_{company_id}"

        rows = self.fetch_all(
            f"""
            SELECT code, category, section, subcategory, standard, name
            FROM {schema}.coa
            WHERE posting = TRUE
            ORDER BY code_numeric NULLS LAST, code ASC
            """
        ) or []

        for r in rows:
            fam = _bucket_from_category_section(
                r.get("category"),
                r.get("section"),
                r.get("subcategory") or "",
                r.get("standard") or "",
            )
            if fam == bucket:
                return str(r.get("code"))
        return None


