    def insert_ledger(
        self,
        company_id: int,
        journal_id: int,
        je_date,
        line: dict,
        ref: Optional[str] = None,
        customer_id: Optional[int] = None,
        vendor_id: Optional[int] = None,
        source: Optional[str] = None,
        source_id: Optional[int] = None,
        cur=None,
    ) -> None:
        schema = f"company_{company_id}"

        # -------------------------
        # 1) Determine account CODE
        # -------------------------
        raw = (line.get("account_code") or line.get("account") or "").strip()
        if not raw:
            raise ValueError("Ledger line missing account_code/account")

        account_code = raw

        # If it's NOT a code, try resolve name -> code (prevents mixing)
        if not CODE_RE.match(account_code):
            # Try resolve by COA name (exact, case-insensitive)
            row = self.fetch_one(
                f"""
                SELECT code
                FROM {schema}.coa
                WHERE company_id=%s AND LOWER(name)=LOWER(%s)
                LIMIT 1
                """,
                (int(company_id), account_code),
                cur=cur,
            )
            if row and row.get("code"):
                account_code = (row["code"] or "").strip()

        # Still not a code? Block.
        if not CODE_RE.match(account_code):
            raise ValueError(f"Ledger account must be COA code (got '{raw}')")

        # Optional: ensure it exists in COA
        chk = self.fetch_one(
            f"""
            SELECT 1
            FROM {schema}.coa
            WHERE company_id=%s AND code=%s
            LIMIT 1
            """,
            (int(company_id), account_code),
            cur=cur,
        )
        if not chk:
            raise ValueError(f"Account code '{account_code}' not found in COA")

        # -------------------------
        # 2) Dimensions
        # -------------------------
        if customer_id is None:
            customer_id = line.get("customer_id")
        if vendor_id is None:
            vendor_id = line.get("vendor_id")

        # -------------------------
        # 3) Date normalize
        # -------------------------
        if hasattr(je_date, "isoformat"):
            je_date = je_date.isoformat()[:10]
        else:
            je_date = str(je_date)[:10]

        # -------------------------
        # 4) Amount normalize
        # supports either:
        #   (a) debit/credit
        #   (b) dc + amount
        # -------------------------
        debit = float(line.get("debit") or 0.0)
        credit = float(line.get("credit") or 0.0)

        if debit == 0.0 and credit == 0.0 and ("dc" in line or "amount" in line):
            amt = float(line.get("amount") or 0.0)
            dc = (line.get("dc") or "").upper().strip()
            if dc == "D":
                debit = amt
                credit = 0.0
            elif dc == "C":
                debit = 0.0
                credit = amt
            else:
                # If amount provided without dc, block
                if amt != 0:
                    raise ValueError("Ledger line has amount but missing dc (D/C)")

        sql = f"""
        INSERT INTO {schema}.ledger (
            company_id, journal_id, date, ref, account,
            debit, credit, source, source_id, memo,
            customer_id, vendor_id
        )
        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s);
        """

        params = (
            int(company_id),
            int(journal_id),
            je_date,
            (ref or line.get("ref")),
            account_code,
            float(debit),
            float(credit),
            (source or line.get("source")),
            (source_id or line.get("source_id")),
            (line.get("memo") or line.get("description") or ""),
            int(customer_id) if customer_id is not None else None,
            int(vendor_id) if vendor_id is not None else None,
        )

        if cur is not None:
            cur.execute(sql, params)
        else:
            self.execute_sql(sql, params)


    def get_ledger_for_account(
        self,
        company_id: int,
        account_code: str,
        date_from=None,
        date_to=None,
    ):
        schema = self.company_schema(company_id)

        params = [account_code]
        date_filter = ""
        if date_from:
            date_filter += " AND l.date >= %s"
            params.append(date_from)
        if date_to:
            date_filter += " AND l.date <= %s"
            params.append(date_to)

        sql = f"""
            SELECT
                l.id,
                l.date,
                l.ref,
                l.account,
                c.name AS account_name,
                c.section AS account_section,
                c.category AS account_category,
                c.subcategory AS account_subcategory,
                c.role AS account_role,
                c.reporting_description AS account_reporting_description,
                l.debit,
                l.credit,
                l.memo,
                l.journal_id,
                j.description AS journal_description
            FROM {schema}.ledger l
            LEFT JOIN {schema}.journal j
                ON j.id = l.journal_id
            LEFT JOIN {schema}.coa c
                ON c.company_id = l.company_id
            AND c.code = l.account
            WHERE l.account = %s
            {date_filter}
            ORDER BY l.date ASC, l.id ASC;
        """
        return self.fetch_all(sql, tuple(params))

