    def upsert_vat_filing_prepared(
        self,
        company_id: int,
        *,
        period_start,
        period_end,
        period_label=None,
        due_date=None,
        input_total=0,
        output_total=0,
        net_vat=0,
        notes=None,
        prepared_by_user_id=None,
        source="api",
        source_id=None,
        source_company_id=None,
        engagement_company_id=None,
        engagement_id=None,
        created_by_user_id=None,
        updated_by_user_id=None,
    ):
        schema = self.company_schema(company_id)

        sql = f"""
        INSERT INTO {schema}.vat_filings (
            company_id,
            period_start,
            period_end,
            period_label,
            due_date,
            input_total,
            output_total,
            net_vat,
            status,
            notes,
            prepared_at,
            prepared_by_user_id,
            source,
            source_id,
            source_company_id,
            engagement_company_id,
            engagement_id,
            created_by_user_id,
            updated_by_user_id,
            created_at,
            updated_at
        )
        VALUES (
            %s, %s, %s, %s, %s,
            %s, %s, %s,
            'prepared',
            %s,
            NOW(),
            %s,
            %s,
            %s,
            %s,
            %s,
            %s,
            %s,
            %s,
            NOW(),
            NOW()
        )
        ON CONFLICT (company_id, period_start, period_end)
        DO UPDATE SET
            period_label = EXCLUDED.period_label,
            due_date = EXCLUDED.due_date,
            input_total = EXCLUDED.input_total,
            output_total = EXCLUDED.output_total,
            net_vat = EXCLUDED.net_vat,
            status = 'prepared',
            notes = COALESCE(EXCLUDED.notes, {schema}.vat_filings.notes),
            prepared_at = NOW(),
            prepared_by_user_id = EXCLUDED.prepared_by_user_id,
            source = EXCLUDED.source,
            source_id = EXCLUDED.source_id,
            source_company_id = COALESCE(EXCLUDED.source_company_id, {schema}.vat_filings.source_company_id),
            engagement_company_id = COALESCE(EXCLUDED.engagement_company_id, {schema}.vat_filings.engagement_company_id),
            engagement_id = COALESCE(EXCLUDED.engagement_id, {schema}.vat_filings.engagement_id),
            updated_by_user_id = EXCLUDED.updated_by_user_id,
            updated_at = NOW()
        RETURNING id
        """

        params = (
            int(company_id),          # company_id
            period_start,            # period_start
            period_end,              # period_end
            period_label,            # period_label
            due_date,                # due_date
            float(input_total or 0), # input_total
            float(output_total or 0),# output_total
            float(net_vat or 0),     # net_vat
            notes,                   # notes
            int(prepared_by_user_id) if prepared_by_user_id else None,
            source,
            source_id,
            int(source_company_id) if source_company_id else None,
            int(engagement_company_id) if engagement_company_id else None,
            int(engagement_id) if engagement_id else None,
            int(created_by_user_id) if created_by_user_id else None,
            int(updated_by_user_id) if updated_by_user_id else None,
        )

        with self._conn_cursor() as (conn, cur):
            cur.execute(sql, params)
            row = cur.fetchone() or {}
            conn.commit()
            return int(row.get("id") if isinstance(row, dict) else row[0])

