    def insert_lease(
        self,
        company_id: int,
        result: "LeaseScheduleResult",
        *,
        lessor_id: int,
        engagement_company_id: int | None = None,
        engagement_id: int | None = None,
        created_by_user_id: int | None = None,
    ) -> int:
        """
        Persist lease master + schedule into company_{id}.leases and company_{id}.lease_schedule.
        Returns lease_id.
        """
        schema = f"company_{company_id}"
        lease = result.lease_input

        with self._conn_cursor() as (conn, cur):
            # Insert master lease row
            cur.execute(
                f"""
                INSERT INTO {schema}.leases (
                    company_id,
                    lessor_id,
                    lease_name,
                    role,
                    start_date,
                    end_date,
                    payment_amount,
                    payment_frequency,
                    payment_timing,
                    annual_rate,
                    initial_direct_costs,
                    residual_value,
                    vat_rate,
                    opening_lease_liability,
                    opening_rou_asset
                )
                VALUES (
                    %(company_id)s,
                    %(lessor_id)s,
                    %(lease_name)s,
                    %(role)s,
                    %(start_date)s,
                    %(end_date)s,
                    %(payment_amount)s,
                    %(payment_frequency)s,
                    %(payment_timing)s,
                    %(annual_rate)s,
                    %(initial_direct_costs)s,
                    %(residual_value)s,
                    %(vat_rate)s,
                    %(opening_lease_liability)s,
                    %(opening_rou_asset)s
                )
                RETURNING id;
                """,
                {
                    "company_id": int(company_id),
                    "lessor_id": int(lessor_id),
                    "lease_name": lease.lease_name,
                    "role": lease.role,
                    "start_date": lease.start_date,
                    "end_date": lease.end_date,
                    "payment_amount": lease.payment_amount,
                    "payment_frequency": lease.payment_frequency,
                    "payment_timing": lease.payment_timing,
                    "annual_rate": lease.annual_rate,
                    "initial_direct_costs": lease.initial_direct_costs,
                    "residual_value": lease.residual_value,
                    "vat_rate": lease.vat_rate,
                    "opening_lease_liability": result.opening_lease_liability,
                    "opening_rou_asset": result.opening_rou_asset,
                },
            )

            lease_id_row = cur.fetchone()
            lease_id = lease_id_row["id"] if isinstance(lease_id_row, dict) else lease_id_row[0]

            version_no = 1
            for p in result.periods:
                cur.execute(
                    f"""
                    INSERT INTO {schema}.lease_schedule (
                        lease_id,
                        company_id,
                        version_no,
                        is_active,
                        modification_id,
                        period_no,
                        period_start,
                        period_end,
                        opening_liability,
                        interest,
                        payment,
                        principal,
                        closing_liability,
                        depreciation,
                        vat_portion,
                        net_payment,
                        payment_timing
                    )
                    VALUES (
                        %(lease_id)s,
                        %(company_id)s,
                        %(version_no)s,
                        %(is_active)s,
                        %(modification_id)s,
                        %(period_no)s,
                        %(period_start)s,
                        %(period_end)s,
                        %(opening_liability)s,
                        %(interest)s,
                        %(payment)s,
                        %(principal)s,
                        %(closing_liability)s,
                        %(depreciation)s,
                        %(vat_portion)s,
                        %(net_payment)s,
                        %(payment_timing)s
                    )
                    """,
                    {
                        "lease_id": int(lease_id),
                        "company_id": int(company_id),
                        "version_no": int(version_no),
                        "is_active": True,
                        "modification_id": None,
                        "period_no": p.period_no,
                        "period_start": p.period_start,
                        "period_end": p.period_end,
                        "opening_liability": p.opening_liability,
                        "interest": p.interest,
                        "payment": p.payment,
                        "principal": p.principal,
                        "closing_liability": p.closing_liability,
                        "depreciation": p.depreciation,
                        "vat_portion": p.vat_portion,
                        "net_payment": p.net_payment,
                        "payment_timing": lease.payment_timing,
                    },
                )

            if engagement_company_id and engagement_id:
                self.upsert_engagement_posting_activity(
                    cur,
                    company_id=int(engagement_company_id),
                    engagement_id=int(engagement_id),
                    posting_date=lease.start_date,
                    module_name="leases",
                    event_type="draft",
                    reference_no=f"LEASE-{lease_id}",
                    description=f"Lease created - {lease.lease_name}",
                    prepared_by_user_id=created_by_user_id,
                    reviewer_user_id=None,
                    status="draft",
                    amount=float(result.opening_lease_liability or 0.0),
                    currency_code="USD",
                    source_table="leases",
                    source_id=int(lease_id),
                    notes="Lease master and initial schedule created",
                    created_by_user_id=created_by_user_id,
                    updated_by_user_id=created_by_user_id,
                )
                
            return lease_id


    def post_lease_direct_cost_paid(
        self,
        *,
        company_id: int,
        lease_id: int,
        payment_date,
        bank_account_id: int,
        amount: float,
        vat_rate: float = 0.0,
        rou_asset_account: str = "BS_NCA_1610",
        reference: str | None = None,
        description: str | None = None,
        user_id: int | None = None,
    ):
        schema = self.company_schema(company_id)

        with self._conn_cursor() as (conn, cur):
            try:
                # 1) Validate lease exists
                cur.execute(
                    f"""
                    SELECT id, lease_name
                    FROM {schema}.leases
                    WHERE id = %s
                    """,
                    (lease_id,),
                )
                lease = cur.fetchone()
                if not lease:
                    raise ValueError("Lease not found")

                lease_name = lease.get("lease_name") if isinstance(lease, dict) else lease[1]

                # 2) Validate bank account + linked ledger account
                cur.execute(
                    f"""
                    SELECT id, bank_name, account_name, ledger_account_code
                    FROM {schema}.company_bank_accounts
                    WHERE id = %s
                    """,
                    (bank_account_id,),
                )
                bank = cur.fetchone()
                if not bank:
                    raise ValueError("Bank account not found")

                bank_gl = bank.get("ledger_account_code") if isinstance(bank, dict) else bank[3]
                if not bank_gl:
                    raise ValueError("Selected bank account is not linked to a ledger account")

                gross = Decimal(str(amount or 0)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
                if gross <= 0:
                    raise ValueError("Amount must be greater than zero")

                rate = Decimal(str(vat_rate or 0))
                # Frontend passes 0.15, not 15
                if rate > 1:
                    rate = rate / Decimal("100")

                if rate > 0:
                    net = (gross / (Decimal("1.0") + rate)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
                    vat = (gross - net).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
                else:
                    net = gross
                    vat = Decimal("0.00")

                je_desc = description or f"Lease initial direct cost paid - {lease_name}"
                je_ref = (reference or "").strip() or f"LEASE-DC-{lease_id}"

                lines = [
                    {
                        "account_code": rou_asset_account or "BS_NCA_1610",
                        "debit": float(net),
                        "credit": 0.0,
                        "memo": f"{je_desc} - ROU asset component",
                    }
                ]

                if vat > 0:
                    lines.append({
                        "account_code": "BS_CA_1410",
                        "debit": float(vat),
                        "credit": 0.0,
                        "memo": f"{je_desc} - VAT input",
                    })

                lines.append({
                    "account_code": bank_gl,
                    "debit": 0.0,
                    "credit": float(gross),
                    "memo": f"{je_desc} - paid from bank",
                })

                entry = {
                    "date": payment_date.isoformat() if hasattr(payment_date, "isoformat") else str(payment_date),
                    "ref": je_ref,
                    "description": je_desc,
                    "source": "lease_direct_cost_paid",
                    "source_id": int(lease_id),
                    "created_by_user_id": user_id,
                    "updated_by_user_id": user_id,
                    "gross_amount": float(gross),
                    "currency": "USD",
                    "lines": lines,
                }

                journal_id = self.post_journal_with_overdraft(company_id, entry)

                # Optional but recommended:
                # store capture status back on lease if columns exist
                try:
                    cur.execute(
                        f"""
                        UPDATE {schema}.leases
                        SET
                            direct_cost_capture_status = %s,
                            direct_cost_capture_journal_id = %s,
                            direct_cost_capture_bank_account_id = %s,
                            updated_at = NOW()
                        WHERE id = %s
                        """,
                        ("paid", journal_id, bank_account_id, lease_id),
                    )
                except Exception:
                    # ignore if columns do not exist yet
                    pass

                conn.commit()

                return {
                    "lease_id": int(lease_id),
                    "journal_id": int(journal_id),
                    "bank_account_id": int(bank_account_id),
                    "bank_gl_account_code": bank_gl,
                    "gross_amount": float(gross),
                    "net_amount": float(net),
                    "vat_amount": float(vat),
                    "status": "paid",
                }

            except Exception:
                conn.rollback()
                raise

    def list_lease_schedule_for_month(self, company_id: int, as_of: date, cur=None):
        schema = f"company_{company_id}"

        month_start = as_of.replace(day=1)
        if month_start.month == 12:
            next_month_start = month_start.replace(year=month_start.year + 1, month=1, day=1)
        else:
            next_month_start = month_start.replace(month=month_start.month + 1, day=1)

        has_posted_cols = bool(self.fetch_one(
            """
            SELECT 1
            FROM information_schema.columns
            WHERE table_schema=%s
            AND table_name='lease_schedule'
            AND column_name IN ('posted_journal_id','posted_at')
            LIMIT 1
            """,
            (schema,),
            cur=cur,
        ))

        posted_expr = (
            "COALESCE(s.posted_journal_id, 0) > 0"
            if has_posted_cols
            else f"""EXISTS (
                SELECT 1
                FROM {schema}.journal j
                WHERE j.source = 'lease_monthly'
                AND j.source_id = s.id
            )"""
        )

        sql = f"""
        SELECT
            s.id AS schedule_id,
            s.company_id,
            s.lease_id,
            s.period_no,
            s.period_start,
            s.period_end,
            s.interest,
            s.principal,
            s.payment,
            s.depreciation,
            s.vat_portion,
            s.net_payment,

            l.lease_name,
            l.lessor_id,
            ls.name AS lessor_name,

            {posted_expr} AS posted,

        EXISTS (
            SELECT 1
            FROM {schema}.lease_payments p
            WHERE p.company_id = s.company_id
            AND p.lease_id = s.lease_id
            AND p.schedule_id = s.id
            AND COALESCE(p.status, '') IN ('draft','posted')
        ) AS paid,

        (
            SELECT p.id
            FROM {schema}.lease_payments p
            WHERE p.company_id = s.company_id
            AND p.lease_id = s.lease_id
            AND p.schedule_id = s.id
            ORDER BY p.id DESC
            LIMIT 1
        ) AS payment_id,

        (
            SELECT p.status
            FROM {schema}.lease_payments p
            WHERE p.company_id = s.company_id
            AND p.lease_id = s.lease_id
            AND p.schedule_id = s.id
            ORDER BY p.id DESC
            LIMIT 1
        ) AS payment_status,

        (
            SELECT p.posted_journal_id
            FROM {schema}.lease_payments p
            WHERE p.company_id = s.company_id
            AND p.lease_id = s.lease_id
            AND p.schedule_id = s.id
            ORDER BY p.id DESC
            LIMIT 1
        ) AS payment_journal_id

        FROM {schema}.lease_schedule s
        JOIN {schema}.leases l
            ON l.id = s.lease_id
        AND l.company_id = %s
        LEFT JOIN {schema}.lessors ls
            ON ls.id = l.lessor_id
        WHERE s.company_id = %s
        AND COALESCE(s.is_active, TRUE) = TRUE
        AND s.period_end >= %s
        AND s.period_end < %s
        ORDER BY s.period_end ASC, l.id ASC
        """

        return self.fetch_all(
            sql,
            (int(company_id), int(company_id), month_start, next_month_start),
            cur=cur
        )

    def build_monthly_lease_journal_lines(
        self,
        company_id: int,
        *,
        lease_id: int,
        schedule_id: int,
        cur=None,
    ):
        schema = f"company_{company_id}"

        s = self.fetch_one(
            f"""
            SELECT
                s.*,
                l.lease_name,
                l.bank_account_code,
                l.post_payment
            FROM {schema}.lease_schedule s
            JOIN {schema}.leases l ON l.id = s.lease_id
            WHERE s.id=%s AND s.lease_id=%s
            """,
            (int(schedule_id), int(lease_id)),
            cur=cur,
        )
        if not s:
            return []

        def _resolve_posting_code(candidate: str | None) -> str | None:
            cand = (candidate or "").strip()
            if not cand:
                return None

            # ✅ FIX: get_account_row_for_posting does not take cur=
            row = self.get_account_row_for_posting(company_id, cand)

            if not row:
                return None

            # row is a tuple from get_account_row_for_posting
            return (row[1] if not isinstance(row, dict) else row.get("code"))

        # ensure defaults exist
        self.ensure_company_account_settings(company_id)
        self.ensure_company_lease_defaults(company_id)

        settings = self.fetch_one(
            """
            SELECT
                lease_liability_current_code,
                lease_liability_non_current_code,
                lease_interest_expense_code,
                lease_amortization_code,
                lease_accumulated_depreciation_code
            FROM public.company_account_settings
            WHERE company_id=%s
            LIMIT 1;
            """,
            (int(company_id),),
            cur=cur,
        ) or {}

        liab_cur = _resolve_posting_code(settings.get("lease_liability_current_code"))
        liab_non = _resolve_posting_code(settings.get("lease_liability_non_current_code")) or liab_cur
        int_exp  = _resolve_posting_code(settings.get("lease_interest_expense_code"))
        depr_exp = _resolve_posting_code(settings.get("lease_amortization_code"))
        acc_depr = _resolve_posting_code(settings.get("lease_accumulated_depreciation_code"))

        interest     = float(s.get("interest") or 0.0)
        depreciation = float(s.get("depreciation") or 0.0)
        period_no    = int(s.get("period_no") or 0)

        missing = []
        if interest > 0:
            if not int_exp:
                missing.append("lease_interest_expense_code")
            if not (liab_non or liab_cur):
                missing.append("lease_liability_non_current_code")
                
        if depreciation > 0:
            if not depr_exp: missing.append("lease_amortization_code")
            if not acc_depr: missing.append("lease_accumulated_depreciation_code")

        if missing:
            raise ValueError("LEASE_ACCOUNTS_MISSING|" + ",".join(sorted(set(missing))))

        lines = []

        line_meta = {
            "source": "leases",
            "source_id": int(lease_id),
        }

        # Interest accrual
        if interest > 0:
            amt = round(interest, 2)

            lines.append({
                "account_code": int_exp,
                "debit": amt,
                "credit": 0.0,
                "memo": f"IFRS16 interest – P{period_no}",
                **line_meta,
            })

            lines.append({
                "account_code": liab_cur,
                "debit": 0.0,
                "credit": amt,
                "memo": f"IFRS16 interest accrual – P{period_no}",
                **line_meta,
            })

        # Depreciation
        if depreciation > 0:
            amt = round(depreciation, 2)
            lines.append({
                "account_code": depr_exp,
                "debit": amt,
                "credit": 0.0,
                "memo": f"ROU depreciation – P{period_no}",
                **line_meta,
            })       

            lines.append({
                "account_code": acc_depr,
                "debit": 0.0,
                "credit": amt,
                "memo": f"Accum dep (ROU) – P{period_no}",
                **line_meta,
            })

        return [ln for ln in lines if (ln.get("debit") or 0) != 0 or (ln.get("credit") or 0) != 0]

    def delete_lease(self, company_id: int, lease_id: int) -> None:
        schema = self.company_schema(company_id)
        with self._conn_cursor() as (conn, cur):
            cur.execute(
                f"DELETE FROM {schema}.lease_schedule WHERE lease_id = %s",
                (int(lease_id),),
            )
            cur.execute(
                f"DELETE FROM {schema}.leases WHERE id = %s",
                (int(lease_id),),
            )
            
