    def ensure_company_lease_defaults(self, company_id: int) -> None:
        self.ensure_company_account_settings(company_id)

        self.execute_sql("""
        UPDATE public.company_account_settings
        SET
        roa_code = COALESCE(NULLIF(roa_code,''), %s),
        lease_liability_current_code = COALESCE(NULLIF(lease_liability_current_code,''), %s),
        lease_liability_non_current_code = COALESCE(NULLIF(lease_liability_non_current_code,''), %s),
        lease_interest_expense_code = COALESCE(NULLIF(lease_interest_expense_code,''), %s),
        lease_amortization_code = COALESCE(NULLIF(lease_amortization_code,''), %s),
        lease_accumulated_depreciation_code = COALESCE(NULLIF(lease_accumulated_depreciation_code,''), %s),
        vat_input_code = COALESCE(NULLIF(vat_input_code,''), %s),  -- ✅ add
        updated_at = NOW()
        WHERE company_id=%s;
        """, (
            REQUIRED_CONTROL_TEMPLATES["1610"]["code"],
            REQUIRED_CONTROL_TEMPLATES["2610"]["code"],
            REQUIRED_CONTROL_TEMPLATES["2620"]["code"],
            REQUIRED_CONTROL_TEMPLATES["7110"]["code"],
            REQUIRED_CONTROL_TEMPLATES["6119"]["code"],
            REQUIRED_CONTROL_TEMPLATES["1590"]["code"],
            REQUIRED_CONTROL_TEMPLATES["1410"]["code"],   # ✅ VAT input
            int(company_id),
        ))

    def list_lessors(
        self,
        company_id: int,
        *,
        active: bool | None = True,   # True = only active, False = only inactive, None = all
        q: str | None = None,
        limit: int = 500,
        offset: int = 0,
        cur=None
    ):
        schema = f"company_{company_id}"

        sql = f"""
        SELECT id, company_id, name, reg_no, vat_no, email, phone, address,
            is_related_party, active, created_at
        FROM {schema}.lessors
        WHERE company_id=%s
        """
        params = [company_id]

        # active filter
        if active is True:
            sql += " AND active = TRUE"
        elif active is False:
            sql += " AND active = FALSE"
        # if active is None -> no filter

        # search
        if q:
            sql += " AND lower(trim(name)) LIKE %s"
            params.append(f"%{q.strip().lower()}%")

        sql += " ORDER BY lower(trim(name)) ASC, id ASC"

        # pagination
        limit = int(limit or 500)
        offset = int(offset or 0)
        if limit < 1:
            limit = 500
        if offset < 0:
            offset = 0

        sql += " LIMIT %s OFFSET %s"
        params.extend([limit, offset])

        return self.fetch_all(sql, tuple(params), cur=cur)

    def get_lessor(self, company_id: int, lessor_id: int, cur=None):
        schema = f"company_{company_id}"
        sql = f"SELECT * FROM {schema}.lessors WHERE company_id=%s AND id=%s"
        return self.fetch_one(sql, (company_id, lessor_id), cur=cur)


    def insert_lessor(self, company_id: int, payload: dict, cur=None) -> int:
        schema = f"company_{company_id}"
        sql = f"""
        INSERT INTO {schema}.lessors
            (company_id, name, reg_no, vat_no, email, phone, address, is_related_party, active)
        VALUES
            (%s,%s,%s,%s,%s,%s,%s,%s,%s)
        RETURNING id
        """
        params = (
            company_id,
            (payload.get("name") or "").strip(),
            payload.get("reg_no"),
            payload.get("vat_no"),
            payload.get("email"),
            payload.get("phone"),
            payload.get("address"),
            bool(payload.get("is_related_party") or False),
            bool(payload.get("active") if payload.get("active") is not None else True),
        )
        if cur is not None:
            cur.execute(sql, params)
            row = cur.fetchone()
            return int((row.get("id") if isinstance(row, dict) else row[0]) or 0)
        return int(self.execute_sql(sql, params) or 0)


    def update_lessor(self, company_id: int, lessor_id: int, **fields) -> bool:
        schema = f"company_{company_id}"
        allowed = {
            "name", "reg_no", "vat_no", "email", "phone", "address",
            "is_related_party", "active"
        }
        sets = []
        params = []

        for k, v in fields.items():
            if k not in allowed:
                continue
            if k == "name":
                v = (v or "").strip()
            sets.append(f"{k}=%s")
            params.append(v)

        if not sets:
            return False

        sets.append("updated_at = NOW()")  # only if you added updated_at, otherwise remove
        sql = f"""
        UPDATE {schema}.lessors
        SET {", ".join(sets)}
        WHERE company_id=%s AND id=%s
        """
        params.extend([company_id, lessor_id])
        self.execute_sql(sql, tuple(params))
        return True


