    def pos_get_receipt_settings(self, company_id: int) -> dict:
        schema = self.company_schema(company_id)

        company = self.get_company(company_id)
        vat_registered = bool(company and company.get("vat_registered"))

        row = self.fetch_one(
            f"""
            SELECT *
            FROM {schema}.pos_receipt_settings
            WHERE company_id = %s
            AND is_active = TRUE
            ORDER BY id DESC
            LIMIT 1
            """,
            (int(company_id),)
        )
        if row:
            row["vat_registered"] = vat_registered

            if not vat_registered:
                row["pricing_tax_mode"] = "no_vat"
                row["receipt_tax_display"] = "none"
                row["tax_invoice_wording"] = "Receipt"
                row["show_vat_no"] = False

            return row

        return {
            "company_id": int(company_id),
            "vat_registered": vat_registered,

            "receipt_title": "Tax Invoice / Receipt" if vat_registered else "Receipt",
            "footer_message": "Thank you for your business.",
            "returns_policy": "Returns accepted within 7 days with original receipt. Items must be unused and in original condition.",
            "refund_policy": "Refunds are issued via the original payment method. Management reserves the right to refuse non-compliant returns.",

            "vat_note": (
                "This document is not a tax invoice unless VAT details are displayed."
                if vat_registered
                else "No VAT charged."
            ),

            "show_vat_no": vat_registered,
            "show_cashier_name": True,
            "show_customer_name": True,
            "is_active": True,

            "pricing_tax_mode": "inclusive" if vat_registered else "no_vat",
            "receipt_tax_display": "vat_line" if vat_registered else "none",
            "tax_invoice_wording": "Tax Invoice / Receipt" if vat_registered else "Receipt",

            "slip_template": "classic",
            "order_template": "restaurant_order",
            "kitchen_ticket_template": "kitchen_ticket",

            "show_logo": True,
            "logo_position": "top_center",
            "company_motto": "",
            "show_motto": True,
            "show_socials": False,
            "whatsapp_number": "",
            "facebook_handle": "",
            "instagram_handle": "",
        }

    def pos_save_receipt_settings(self, company_id: int, data: dict) -> dict:
        schema = self.company_schema(company_id)
        data = self._normalise_pos_tax_settings(company_id, data)
        row = self.fetch_one(f"""
            INSERT INTO {schema}.pos_receipt_settings
            (
                company_id,
                receipt_title,
                footer_message,
                returns_policy,
                refund_policy,
                vat_note,
                show_vat_no,
                show_cashier_name,
                show_customer_name,
                pricing_tax_mode,
                receipt_tax_display,
                tax_invoice_wording,
                slip_template,
                order_template,
                kitchen_ticket_template,
                is_active
            )
            VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,TRUE)
            ON CONFLICT (company_id)
            WHERE is_active = TRUE
            DO UPDATE SET
                receipt_title = EXCLUDED.receipt_title,
                footer_message = EXCLUDED.footer_message,
                returns_policy = EXCLUDED.returns_policy,
                refund_policy = EXCLUDED.refund_policy,
                vat_note = EXCLUDED.vat_note,
                show_vat_no = EXCLUDED.show_vat_no,
                show_cashier_name = EXCLUDED.show_cashier_name,
                show_customer_name = EXCLUDED.show_customer_name,
                pricing_tax_mode = EXCLUDED.pricing_tax_mode,
                receipt_tax_display = EXCLUDED.receipt_tax_display,
                tax_invoice_wording = EXCLUDED.tax_invoice_wording,
                slip_template = EXCLUDED.slip_template,
                order_template = EXCLUDED.order_template,
                kitchen_ticket_template = EXCLUDED.kitchen_ticket_template,
                updated_at = NOW()
            RETURNING *
        """, (
            int(company_id),
            data.get("tax_invoice_wording")
                or data.get("receipt_title")
                or "Tax Invoice / Receipt",
            data.get("footer_message"),
            data.get("returns_policy"),
            data.get("refund_policy"),
            data.get("vat_note"),
            bool(data.get("show_vat_no", True)),
            bool(data.get("show_cashier_name", True)),
            bool(data.get("show_customer_name", True)),
            data.get("pricing_tax_mode", "no_vat"),
            data.get("receipt_tax_display", "none"),
            data.get("tax_invoice_wording",
            data.get("receipt_title", "Receipt")),

            data.get("slip_template", "classic"),
            data.get("order_template", "restaurant_order"),
            data.get("kitchen_ticket_template", "kitchen_ticket"),
        ))

        return row

    def _company_is_vat_registered(self, company_id: int) -> bool:
        company = self.get_company(company_id)

        if not company:
            return False

        return bool(str(company.get("vat") or "").strip())

    def _normalise_pos_tax_settings(self, company_id: int, data: dict) -> dict:
        data = dict(data or {})

        is_vat_registered = self._company_is_vat_registered(company_id)

        if not is_vat_registered:
            data["pricing_tax_mode"] = "no_vat"
            data["receipt_tax_display"] = "none"
            data["tax_invoice_wording"] = "Receipt"
            data["show_vat_no"] = False
            data["vat_note"] = "No VAT charged."

        else:
            if data.get("pricing_tax_mode") not in ("inclusive", "exclusive"):
                data["pricing_tax_mode"] = "inclusive"

            if data.get("receipt_tax_display") not in ("total_only", "vat_line", "cost_vat_total"):
                data["receipt_tax_display"] = "vat_line"

            if not data.get("tax_invoice_wording"):
                data["tax_invoice_wording"] = "Tax Invoice / Receipt"

        return data

    def pos_update_receipt_settings(self, company_id: int, data: dict) -> dict:
        existing = self.pos_get_receipt_settings(company_id)

        merged = {
            "receipt_title": data.get("receipt_title", existing.get("receipt_title")),
            "footer_message": data.get("footer_message", existing.get("footer_message")),
            "returns_policy": data.get("returns_policy", existing.get("returns_policy")),
            "refund_policy": data.get("refund_policy", existing.get("refund_policy")),
            "vat_note": data.get("vat_note", existing.get("vat_note")),
            "show_vat_no": data.get("show_vat_no", existing.get("show_vat_no", True)),
            "show_cashier_name": data.get("show_cashier_name", existing.get("show_cashier_name", True)),
            "show_customer_name": data.get("show_customer_name", existing.get("show_customer_name", True)),

            # Receipt templates
            "slip_template": data.get(
                "slip_template",
                existing.get("slip_template", "classic"),
            ),

            "order_template": data.get(
                "order_template",
                existing.get("order_template", "restaurant_order"),
            ),

            "kitchen_ticket_template": data.get(
                "kitchen_ticket_template",
                existing.get("kitchen_ticket_template", "kitchen_ticket"),
            ),

            # Tax settings
            "pricing_tax_mode": data.get(
                "pricing_tax_mode",
                existing.get("pricing_tax_mode", "inclusive"),
            ),

            "receipt_tax_display": data.get(
                "receipt_tax_display",
                existing.get("receipt_tax_display", "vat_line"),
            ),

            "tax_invoice_wording": data.get(
                "tax_invoice_wording",
                existing.get(
                    "tax_invoice_wording",
                    existing.get("receipt_title", "Tax Invoice / Receipt"),
                ),
            ),
        }

        return self.pos_save_receipt_settings(company_id, merged)

    # =========================
    # POS RESTAURANT TABLE SECTIONS / TABLES
    # =========================

    def pos_list_table_sections(self, company_id: int, active_only: bool = False) -> list[dict]:
        schema = self.company_schema(company_id)

        return self.fetch_all(f"""
            SELECT
                s.*,
                COUNT(t.id) AS table_count
            FROM {schema}.pos_table_sections s
            LEFT JOIN {schema}.pos_tables t
                ON t.section_id = s.id
                AND t.company_id = s.company_id
                AND t.is_active = TRUE
            WHERE s.company_id = %s
            AND (%s = FALSE OR s.is_active = TRUE)
            GROUP BY s.id
            ORDER BY s.sort_order ASC, s.section_name ASC
        """, (int(company_id), bool(active_only)))


    def pos_create_table_section(self, company_id: int, data: dict) -> int:
        schema = self.company_schema(company_id)

        section_name = (data.get("section_name") or data.get("name") or "").strip()
        section_code = (data.get("section_code") or section_name).strip().upper().replace(" ", "_")

        if not section_name:
            raise ValueError("section_name is required")

        row = self.fetch_one(f"""
            INSERT INTO {schema}.pos_table_sections
            (
                company_id, section_code, section_name,
                sort_order, is_active
            )
            VALUES (%s,%s,%s,%s,%s)
            ON CONFLICT (company_id, lower(trim(section_code)))
            DO UPDATE SET
                section_name = EXCLUDED.section_name,
                sort_order = EXCLUDED.sort_order,
                is_active = EXCLUDED.is_active
            RETURNING id
        """, (
            int(company_id),
            section_code,
            section_name,
            int(data.get("sort_order") or 0),
            bool(data.get("is_active", True)),
        ))

        return int(row["id"])


    def pos_update_table_section(self, company_id: int, section_id: int, data: dict) -> dict | None:
        schema = self.company_schema(company_id)

        allowed = {
            "section_code",
            "section_name",
            "sort_order",
            "is_active",
        }

        sets, params = [], []

        for k, v in (data or {}).items():
            if k in allowed:
                sets.append(f"{k}=%s")
                params.append(v)

        if not sets:
            return self.fetch_one(f"""
                SELECT *
                FROM {schema}.pos_table_sections
                WHERE company_id=%s AND id=%s
            """, (int(company_id), int(section_id)))

        params.extend([int(company_id), int(section_id)])

        return self.fetch_one(f"""
            UPDATE {schema}.pos_table_sections
            SET {", ".join(sets)}
            WHERE company_id=%s AND id=%s
            RETURNING *
        """, tuple(params))


    def pos_list_tables(self, company_id: int, active_only: bool = False, section_id: int | None = None) -> list[dict]:
        schema = self.company_schema(company_id)

        where = ["t.company_id=%s"]
        params = [int(company_id)]

        if active_only:
            where.append("t.is_active=TRUE")

        if section_id:
            where.append("t.section_id=%s")
            params.append(int(section_id))

        return self.fetch_all(f"""
            SELECT
                t.*,
                s.section_name,
                s.section_code,
                COALESCE(o.open_balance, 0) AS open_balance,
                COALESCE(o.open_orders, 0) AS open_orders
            FROM {schema}.pos_tables t
            LEFT JOIN {schema}.pos_table_sections s
                ON s.id = t.section_id
                AND s.company_id = t.company_id
            LEFT JOIN (
                SELECT
                    table_no,
                    COUNT(*) AS open_orders,
                    SUM(COALESCE(gross_amount, 0)) AS open_balance
                FROM {schema}.pos_orders
                WHERE company_id=%s
                AND status NOT IN ('completed', 'cancelled', 'void')
                AND table_no IS NOT NULL
                GROUP BY table_no
            ) o ON lower(trim(o.table_no)) = lower(trim(t.table_code))
            WHERE {" AND ".join(where)}
            ORDER BY s.sort_order ASC NULLS LAST, s.section_name ASC, t.table_name ASC
        """, tuple([int(company_id)] + params))


    def pos_create_table(self, company_id: int, data: dict) -> int:
        schema = self.company_schema(company_id)

        table_name = (data.get("table_name") or data.get("name") or "").strip()
        table_code = (data.get("table_code") or table_name).strip().upper().replace(" ", "_")

        if not table_name:
            raise ValueError("table_name is required")

        row = self.fetch_one(f"""
            INSERT INTO {schema}.pos_tables
            (
                company_id, section_id, table_code, table_name,
                capacity, status, waiter_user_id, is_active
            )
            VALUES (%s,%s,%s,%s,%s,%s,%s,%s)
            ON CONFLICT (company_id, lower(trim(table_code)))
            DO UPDATE SET
                section_id = EXCLUDED.section_id,
                table_name = EXCLUDED.table_name,
                capacity = EXCLUDED.capacity,
                status = EXCLUDED.status,
                waiter_user_id = EXCLUDED.waiter_user_id,
                is_active = EXCLUDED.is_active
            RETURNING id
        """, (
            int(company_id),
            data.get("section_id"),
            table_code,
            table_name,
            int(data.get("capacity") or 4),
            data.get("status") or "available",
            data.get("waiter_user_id"),
            bool(data.get("is_active", True)),
        ))

        return int(row["id"])


    def pos_update_table(self, company_id: int, table_id: int, data: dict) -> dict | None:
        schema = self.company_schema(company_id)

        allowed = {
            "section_id",
            "table_code",
            "table_name",
            "capacity",
            "status",
            "waiter_user_id",
            "is_active",
        }

        sets, params = [], []

        for k, v in (data or {}).items():
            if k in allowed:
                sets.append(f"{k}=%s")
                params.append(v)

        if not sets:
            return self.fetch_one(f"""
                SELECT *
                FROM {schema}.pos_tables
                WHERE company_id=%s AND id=%s
            """, (int(company_id), int(table_id)))

        params.extend([int(company_id), int(table_id)])

        return self.fetch_one(f"""
            UPDATE {schema}.pos_tables
            SET {", ".join(sets)}
            WHERE company_id=%s AND id=%s
            RETURNING *
        """, tuple(params))


    def pos_delete_table(self, company_id: int, table_id: int) -> dict | None:
        schema = self.company_schema(company_id)

        return self.fetch_one(f"""
            UPDATE {schema}.pos_tables
            SET is_active = FALSE,
                status = 'out_of_service'
            WHERE company_id=%s AND id=%s
            RETURNING *
        """, (int(company_id), int(table_id)))

    def pos_create_staff_member(self, company_id: int, data: dict) -> dict:
        full_name = (data.get("full_name") or "").strip()
        email = (data.get("email") or "").strip().lower()
        phone = (data.get("phone") or "").strip()
        pos_role = (data.get("role") or data.get("pos_role") or "cashier").strip().lower()
        pin = str(data.get("pin") or "").strip()

        if not full_name:
            raise ValueError("full_name is required")
        if not email:
            raise ValueError("email is required")
        if not pin:
            raise ValueError("PIN is required")

        parts = full_name.split(" ", 1)
        first_name = parts[0]
        last_name = parts[1] if len(parts) > 1 else "-"

        employee_code = (
            data.get("employee_code")
            or f"POS-{secrets.token_hex(3).upper()}"
        )

        access_code = (
            data.get("access_code")
            or data.get("pos_access_code")
            or str(secrets.randbelow(9000) + 1000)
        )

        pin_hash = generate_password_hash(pin)

        with self._conn_cursor() as (conn, cur):
            user = self.fetch_one("""
                INSERT INTO public.users
                (
                    email,
                    password_hash,
                    user_type,
                    first_name,
                    last_name,
                    user_role,
                    access_level,
                    is_confirmed,
                    is_active,
                    company_id
                )
                VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
                ON CONFLICT (email) DO UPDATE
                SET
                    is_active = TRUE,
                    first_name = EXCLUDED.first_name,
                    last_name = EXCLUDED.last_name,
                    user_role = EXCLUDED.user_role,
                    access_level = EXCLUDED.access_level
                RETURNING id
            """, (
                email,
                generate_password_hash(secrets.token_urlsafe(16)),
                "company_user",
                first_name,
                last_name,
                pos_role,
                "pos",
                True,
                True,
                int(company_id),
            ), cur=cur)

            user_id = int(user["id"])

            row = self.fetch_one("""
                INSERT INTO public.company_users
                (
                    company_id,
                    user_id,
                    role,
                    access_level,
                    access_scope,
                    assignment_role,
                    membership_kind,
                    is_active,
                    joined_at,
                    pos_role,
                    pos_permissions,
                    pos_is_active,
                    employee_code,
                    pos_access_code,
                    pin_hash,
                    pos_display_name,
                    phone
                )
                VALUES
                (
                    %s,%s,%s,%s,%s,%s,%s,
                    TRUE,NOW(),
                    %s,%s::jsonb,TRUE,
                    %s,%s,%s,%s,%s
                )
                ON CONFLICT (company_id, user_id) DO UPDATE
                SET
                    role = EXCLUDED.role,
                    access_level = EXCLUDED.access_level,
                    access_scope = EXCLUDED.access_scope,
                    assignment_role = EXCLUDED.assignment_role,
                    is_active = TRUE,
                    pos_role = EXCLUDED.pos_role,
                    pos_permissions = EXCLUDED.pos_permissions,
                    pos_is_active = TRUE,
                    employee_code = EXCLUDED.employee_code,
                    pos_access_code = EXCLUDED.pos_access_code,
                    pin_hash = EXCLUDED.pin_hash,
                    pos_display_name = EXCLUDED.pos_display_name,
                    phone = EXCLUDED.phone
                RETURNING
                    id,
                    company_id,
                    user_id,
                    employee_code,
                    pos_access_code,
                    pos_display_name,
                    pos_role,
                    phone,
                    pos_is_active
            """, (
                int(company_id),
                user_id,
                pos_role,
                "pos",
                "pos",
                pos_role,
                "secondary",
                pos_role,
                "{}",
                employee_code,
                access_code,
                pin_hash,
                full_name,
                phone,
            ), cur=cur)

            conn.commit()
            return dict(row)

    def pos_list_staff_members(self, company_id: int) -> list[dict]:
        return self.fetch_all("""
            SELECT
                cu.id,
                cu.company_id,
                cu.user_id,
                cu.employee_code,
                cu.pos_access_code,
                cu.phone,
                cu.pos_display_name AS full_name,
                cu.pos_role AS role,
                cu.pos_permissions,
                cu.pos_is_active AS is_active,
                u.email,
                u.first_name,
                u.last_name
            FROM public.company_users cu
            JOIN public.users u ON u.id = cu.user_id
            WHERE cu.company_id = %s
            AND cu.access_scope = 'pos'
            ORDER BY cu.pos_is_active DESC, cu.pos_display_name ASC
        """, (int(company_id),))

    def pos_update_staff_member(self, company_id: int, staff_id: int, data: dict) -> dict | None:
        allowed = {
            "pos_role",
            "pos_permissions",
            "pos_is_active",
            "employee_code",
            "pos_access_code",
            "pos_display_name",
            "phone",
            "is_active",
        }

        sets = []
        params = []

        for key, value in (data or {}).items():
            db_key = key

            if key == "role":
                db_key = "pos_role"
            if key == "full_name":
                db_key = "pos_display_name"
            if key == "access_code":
                db_key = "pos_access_code"
            if key == "phone":
                db_key = "phone"
            if key == "is_active":
                db_key = "pos_is_active"

            if db_key in allowed:
                sets.append(f"{db_key} = %s")
                params.append(value)

        pin = str(data.get("pin") or "").strip()
        if pin:
            sets.append("pin_hash = %s")
            params.append(generate_password_hash(pin))

        if not sets:
            return None

        params.extend([int(company_id), int(staff_id)])

        return self.fetch_one(f"""
            UPDATE public.company_users
            SET {", ".join(sets)}
            WHERE company_id = %s
            AND id = %s
            AND access_scope = 'pos'
            RETURNING *
        """, tuple(params))

