    def insert_vendor(self, company_id: int, data: Dict[str, Any]) -> int:
        schema = f"company_{company_id}"

        def pick(*keys, default=None):
            for k in keys:
                v = data.get(k)
                if v not in (None, ""):
                    return v
            return default

        sql = f"""
        INSERT INTO {schema}.vendors (
            company_id,
            external_code,
            name,
            email,
            phone,
            remit_address,
            country,
            tax_number,
            vat_number,
            registration_no,
            wht_percent,
            payment_terms,
            vendor_status,
            on_hold,
            notes,
            tags,
            contacts,
            is_active,
            approved_by_user_id,
            approved_at,

            bank_name,
            branch_code,
            account_name,
            account_number,
            account_type,
            bank_currency,
            swift_code,

            compliance_status,
            compliance_required,
            missing_docs,
            compliance_updated_at
        )
        VALUES (
            %s,%s,%s,%s,%s,%s,%s,%s,%s,%s,
            %s,%s,%s,%s,%s,%s,%s,%s,%s,%s,
            %s,%s,%s,%s,%s,%s,%s,
            %s,%s,%s,NOW()
        )
        RETURNING id;
        """

        # numbers
        wht_raw = pick("wht", "wht_percent", "whtPercent")
