    # =========================
    # DB: Allocate payment to invoice
    # =========================
    def allocate_payment_to_invoice(
        self,
        *,
        company_id: int,
        invoice_id: int,
        amount: Decimal,
        payment_date: date,
        bank_account_id: int | None,
        reference: str | None,
        description: str | None,
        user_id: int | None,
        ar_ledger_code: str | None = None,
    ) -> dict:
        from decimal import Decimal

        inv = self.get_invoice_by_id(company_id, invoice_id)

        if inv and not inv.get("posted_journal_id"):
            row = self.fetch_one(
                f"""
                SELECT posted_journal_id
                FROM company_{company_id}.invoices
                WHERE id=%s
                LIMIT 1
                """,
                (int(invoice_id),),
            ) or {}

            inv["posted_journal_id"] = row.get("posted_journal_id")
            
        if not inv:
            raise ValueError("Invoice not found")

        posted_journal_id = inv.get("posted_journal_id")

        if not posted_journal_id:
            raise ValueError(
                "Cannot allocate payment to invoice that has not been posted to GL"
            )

        amount = Decimal(str(amount or "0")).quantize(Decimal("0.01"))
        if amount <= Decimal("0.00"):
            raise ValueError("Amount must be > 0")

        cust_id = int(inv.get("customer_id") or 0)
        if not cust_id:
            raise ValueError("Invoice missing customer_id")

        # choose bank account
        bank_account_id = bank_account_id or inv.get("bank_account_id")
        if not bank_account_id:
            raise ValueError("No bank account selected (and invoice has no bank_account_id).")

        bank = self.get_company_bank_account(company_id, int(bank_account_id))
        if not bank:
            raise ValueError("Bank account not found")

        bank_ledger_code = (bank.get("ledger_account_code") or "").strip()
        if not bank_ledger_code:
            raise ValueError("Selected bank account has no ledger_account_code")

        # AR control code
        if ar_ledger_code:
            row = self.get_account_row_for_posting(company_id, ar_ledger_code)
            if not row:
                raise ValueError(f"AR ledger code '{ar_ledger_code}' not found in COA")
            ar_code = (row[1] or "").strip()
        else:
            ar_code = (self._resolve_ar_control_posting(company_id) or "").strip()

        if not ar_code:
            raise ValueError("AR control posting account could not be resolved")

        schema = self.company_schema(company_id)

        ar_exists = self.fetch_one(
            f"""
            SELECT COALESCE(SUM(
                COALESCE(jl.debit,0) - COALESCE(jl.credit,0)
            ),0) AS ar_balance
            FROM {schema}.journal_lines jl
            JOIN {schema}.journal j
              ON j.id = jl.journal_id
            WHERE j.id = %s
              AND jl.account_code = %s
            """,
            (int(posted_journal_id), ar_code),
        ) or {}

        ar_balance = Decimal(
            str(ar_exists.get("ar_balance") or "0")
        ).quantize(Decimal("0.01"))

        if ar_balance <= Decimal("0.00"):
            raise ValueError(
                "Invoice has no valid AR debit posted in GL"
            )

        # ✅ Unallocated receipts liability
        unalloc_code = (self._resolve_unallocated_receipts_liability(company_id) or "").strip()
        if not unalloc_code:
            raise ValueError("Unallocated receipts liability posting account could not be resolved")

        total = Decimal(str(inv.get("total_amount") or "0")).quantize(Decimal("0.01"))
        paid_so_far = Decimal(str(self.get_invoice_allocated_total(company_id, invoice_id) or "0")).quantize(Decimal("0.01"))
        remaining = (total - paid_so_far).quantize(Decimal("0.01"))

        alloc = Decimal("0.00") if remaining <= Decimal("0.00") else min(amount, remaining)
        alloc = alloc.quantize(Decimal("0.01"))

        remainder = (amount - alloc).quantize(Decimal("0.01"))

        # 1) Create receipt for FULL amount
        receipt_row = self.create_receipt(
            company_id=company_id,
            customer_id=cust_id,
            receipt_date=payment_date,
            amount=amount,
            currency=inv.get("currency"),
            bank_account_id=int(bank_account_id),
            bank_ledger_code=bank_ledger_code,
            ar_ledger_code=ar_code,  # informational; GL entry below is truth
            reference=reference,
            description=description or f"Payment received for invoice {inv.get('number')}",
            created_by=user_id,
        )
        receipt_id = int(receipt_row["id"])

        # 2) Allocate ONLY alloc part
        if alloc > Decimal("0.00"):
            self.allocate_receipt_to_invoice(
                company_id=company_id,
                receipt_id=receipt_id,
                invoice_id=int(invoice_id),
                amount=alloc,
            )

        # 3) Journal: Bank Dr full; AR Cr alloc; Unallocated Cr remainder
        lines = [
            {"account_code": bank_ledger_code, "debit": float(amount), "credit": 0.0, "memo": "Receipt to bank"},
        ]

        if alloc > Decimal("0.00"):
            lines.append({
                "account_code": ar_code,
                "debit": 0.0,
                "credit": float(alloc),
                "memo": "Reduce AR (allocated to invoice)",
                "customer_id": cust_id,
            })

        if remainder > Decimal("0.00"):
            lines.append({
                "account_code": unalloc_code,
                "debit": 0.0,
                "credit": float(remainder),
                "memo": "Customer overpayment (unallocated)",
                "customer_id": cust_id,
            })

        entry = {
            "date": payment_date.isoformat(),
            "ref": reference or f"RCPT-{receipt_id}",
            "description": description or f"Receipt for invoice {inv.get('number')} (alloc {alloc}, unalloc {remainder})",
            "gross_amount": float(amount),
            "net_amount": float(amount),
            "vat_amount": 0.0,
            "source": "receipt",
            "source_id": int(receipt_id),
            "lines": lines,
        }

        entry = self._apply_engagement_bridge_to_entry(
            entry,
            row=inv,
        )

        entry["module_name"] = "receipts"
        entry["event_type"] = "posted"
        entry["source_table"] = "receipts"
        entry["created_by_user_id"] = user_id
        entry["updated_by_user_id"] = user_id
        entry["prepared_by_user_id"] = user_id

        journal_id = (
            self.post_journal_with_overdraft(company_id, entry)
            if hasattr(self, "post_journal_with_overdraft")
            else self.post_journal(company_id, entry)
        )
        journal_id = int(journal_id or 0)
        if journal_id <= 0:
            raise ValueError("Failed to post receipt journal")

        self.set_receipt_journal(company_id, receipt_id, journal_id)

        # 4) Update invoice status based on allocation only
        new_paid = (paid_so_far + alloc).quantize(Decimal("0.01"))
        new_remaining = (total - new_paid).quantize(Decimal("0.01"))

        if new_remaining <= Decimal("0.00"):
            self.set_invoice_status(company_id, int(invoice_id), "paid")
        elif alloc > Decimal("0.00"):
            self.set_invoice_status(company_id, int(invoice_id), "partial")

        self.sync_lessor_receipt_from_invoice(
            company_id,
            int(invoice_id),
        )

        return {
            "receipt_id":receipt_id,
            "journal_id":journal_id,
            "received":str(amount),
            "allocated":str(alloc),
            "unallocated":str(remainder),

            "invoice_id":int(invoice_id),
            "invoice_number":inv.get("number"),
            "invoice_total":str(total),
            "invoice_status":(
                "paid"
                if new_remaining<=Decimal("0.00")
                else "partial"
                if alloc>Decimal("0.00")
                else str(inv.get("status") or "")
            ),

            "paid_before":str(paid_so_far),
            "paid_after":str(new_paid),
            "remaining_after":str(new_remaining),

            "bank_ledger_code":bank_ledger_code,
            "ar_ledger_code":ar_code,
            "unallocated_liability_code":unalloc_code,
            "customer_id":cust_id,

            "source":inv.get("source"),
            "source_id":inv.get("source_id"),
            "module_name":inv.get("module_name"),
            "posting_mode":inv.get("posting_mode"),

            "lessor_lease_id":inv.get("lessor_lease_id"),
            "lessor_schedule_id":inv.get("lessor_schedule_id"),
            "lease_classification":inv.get("lease_classification"),
            "accounting_treatment":inv.get("accounting_treatment"),
        }

    def get_receipt_allocated_total(self, company_id: int, receipt_id: int):
        schema = self.company_schema(company_id)
        row = self.fetch_one(
            f"SELECT COALESCE(SUM(amount),0)::numeric(18,2) AS s FROM {schema}.receipt_allocations WHERE company_id=%s AND receipt_id=%s;",
            (company_id, receipt_id),
        )
        return row["s"] if row else 0



    def get_receipt_unallocated_balance(self, company_id: int, receipt_id: int):
        schema = self.company_schema(company_id)
        r = self.fetch_one(
            f"SELECT amount FROM {schema}.receipts WHERE company_id=%s AND id=%s LIMIT 1;",
            (company_id, receipt_id),
        )
        if not r:
            return Decimal("0.00")

        total = Decimal(str(r["amount"] or "0")).quantize(Decimal("0.01"))
        alloc = Decimal(str(self.get_receipt_allocated_total(company_id, receipt_id) or "0")).quantize(Decimal("0.01"))
        bal = (total - alloc).quantize(Decimal("0.01"))
        return bal if bal > 0 else Decimal("0.00")

    def get_receipt_by_id(self, company_id: int, receipt_id: int) -> Optional[Dict[str, Any]]:
        schema = self.company_schema(company_id)
        return self.fetch_one(
            f"""
            SELECT
                r.id, r.customer_id, r.receipt_date, r.amount, r.currency,
                r.bank_account_id, r.reference, r.description,
                r.created_at,
                c.name AS customer_name,
                c.email AS customer_email,
                co.name AS company_name,
                co.company_email AS company_email,
                co.company_phone,
                co.physical_address,
                co.postal_address,
                co.logo_url
            FROM {schema}.receipts r
            JOIN {schema}.customers c ON c.id = r.customer_id
            LEFT JOIN public.companies co ON co.id = %s
            WHERE r.id = %s
            LIMIT 1;
            """,
            (company_id, receipt_id),
        )

    def list_receipt_allocations(self, company_id: int, receipt_id: int) -> List[Dict[str, Any]]:
        schema = self.company_schema(company_id)
        return self.fetch_all(
            f"""
            SELECT
                a.id,
                a.invoice_id,
                a.amount,
                i.number AS invoice_number,
                i.invoice_date,
                i.due_date,
                i.total_amount
            FROM {schema}.receipt_allocations a
            JOIN {schema}.invoices i ON i.id = a.invoice_id
            WHERE a.receipt_id = %s
            ORDER BY a.id ASC;
            """,
            (receipt_id,),
        ) or []

    def _insert_quote_with_lines_cur(self, company_id: int, header: dict, lines: list, cur) -> int:
        schema = self.company_schema(company_id)

        status = (header.get("status") or "draft").strip().lower()

        # Draft-friendly number (same logic as invoices)
        if status == "draft":
            header["number"] = None
        else:
            status = (header.get("status") or "draft").strip().lower()

            # ✅ Only assign invoice number when NOT draft
            if status != "draft":
                if not (header.get("number") or "").strip():
                    header["number"] = self.next_invoice_number_cur(company_id, cur)
            else:
                # keep drafts numberless (NULL/blank)
                header["number"] = None

        # ---------- line totals (gross before HEADER discount) ----------
        subtotal_gross = 0.0
        line_discount_total = 0.0
        vatable_gross = 0.0
        prepared_lines = []

        for idx, ln in enumerate(lines or [], start=1):
            qty = float(ln.get("quantity") or 0)
            price = float(ln.get("unit_price") or 0)

            disc_line = money(ln.get("discount_amount") or 0)
            vat_rate = float(ln.get("vat_rate") or 0)

            line_net_gross = max(0.0, (qty * price) - disc_line)
            line_vat_gross = line_net_gross * (vat_rate / 100.0)
            line_total_gross = line_net_gross + line_vat_gross

            line_net_gross = money(line_net_gross)
            line_vat_gross = money(line_vat_gross)
            line_total_gross = money(line_total_gross)

            subtotal_gross = money(subtotal_gross + line_net_gross)
            line_discount_total = money(line_discount_total + disc_line)

            if vat_rate > 0:
                vatable_gross = money(vatable_gross + line_net_gross)

            prepared_lines.append({
                "line_no": idx,
                "item_name": (ln.get("item_name") or ln.get("itemName") or "").strip(),
                "description": (ln.get("description") or "").strip(),
                "account_code": ln.get("account_code"),
                "quantity": qty,
                "unit_price": price,
                "discount_amount": disc_line,
                "net_amount": line_net_gross,
                "vat_rate": vat_rate,
                "vat_amount": line_vat_gross,
                "total_amount": line_total_gross,
            })

        # ---------- HEADER discount (percent) ----------
        disc_rate = header.get("discount_rate")
        if disc_rate is None:
            disc_rate = header.get("discount")  # legacy support if UI sends discount
        try:
            disc_rate = float(disc_rate or 0.0)
        except Exception:
            disc_rate = 0.0
        disc_rate = max(0.0, min(1.0, disc_rate))

        header_discount_amt = money(subtotal_gross * disc_rate)

        # allocate header discount proportionally to VATable base
        disc_on_vatable = money(header_discount_amt * (vatable_gross / subtotal_gross)) if subtotal_gross > 0 else 0.0
        vatable_after = max(0.0, money(vatable_gross - disc_on_vatable))

        # recompute VAT totals AFTER header discount
        vat_total = money(vatable_after * 0.15) if vatable_gross > 0 else 0.0

        subtotal_after = money(max(0.0, subtotal_gross - header_discount_amt))
        grand_total = money(subtotal_after + vat_total)

        # store combined discount amount (line + header)
        discount_total = money(line_discount_total + header_discount_amt)

        # defaults
        header.setdefault("currency", None)
        header.setdefault("notes", None)
        header.setdefault("terms", None)
        header.setdefault("valid_until", None)
        header.setdefault("quotation_date", None)
        header.setdefault("status", "draft")

        # If issuing at insert time, you can set issued_at/by
        issued_at = header.get("issued_at")
        issued_by = header.get("issued_by")

        cur.execute(
            f"""
            INSERT INTO {schema}.quotations (
                company_id,
                customer_id,
                number,
                quotation_date,
                valid_until,
                currency,
                subtotal_amount,
                discount_amount,
                discount_rate,
                vat_amount,
                total_amount,
                status,
                notes,
                terms,
                issued_at,
                issued_by
            )
            VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
            RETURNING id;
            """,
            (
                company_id,
                int(header["customer_id"]),
                header.get("number"),
                header.get("quotation_date"),
                header.get("valid_until"),
                header.get("currency"),
                subtotal_after,
                discount_total,
                disc_rate,
                vat_total,
                grand_total,
                status,
                header.get("notes"),
                header.get("terms"),
                issued_at,
                issued_by,
            ),
        )
        row = cur.fetchone()
        quote_id = row["id"] if isinstance(row, dict) else row[0]

        # Insert lines
        for pl in prepared_lines:
            cur.execute(
                f"""
                INSERT INTO {schema}.quotation_lines (
                    company_id,
                    quotation_id,
                    line_no,
                    item_name,
                    description,
                    account_code,
                    quantity,
                    unit_price,
                    discount_amount,
                    net_amount,
                    vat_rate,
                    vat_amount,
                    total_amount
                )
                VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s);
                """,
                (
                    company_id,
                    quote_id,
                    pl["line_no"],
                    pl.get("item_name"),
                    pl["description"],
                    pl["account_code"],
                    pl["quantity"],
                    pl["unit_price"],
                    pl["discount_amount"],
                    pl["net_amount"],
                    pl["vat_rate"],
                    pl["vat_amount"],
                    pl["total_amount"],
                ),
            )

        return int(quote_id)

    def insert_quote_with_lines(self, company_id: int, header: dict, lines: list) -> int:
        with self._conn_cursor() as (conn, cur):
            quote_id = self._insert_quote_with_lines_cur(company_id, header, lines, cur)
            conn.commit()
            return quote_id

    def update_quote_with_lines(self, company_id: int, quote_id: int, header: dict, lines: list) -> None:
        schema = self.company_schema(company_id)

        status = (header.get("status") or "draft").strip().lower()

        # draft-friendly numbering
        if status == "draft":
            header["number"] = None
        else:
            if not (header.get("number") or "").strip():
                header["number"] = self.next_invoice_number(company_id, key="quote")

        # ---------- line totals (gross before HEADER discount) ----------
        subtotal_gross = 0.0
        line_discount_total = 0.0
        vatable_gross = 0.0
        prepared = []

        for idx, ln in enumerate(lines or [], start=1):
            qty = float(ln.get("quantity") or 0)
            price = float(ln.get("unit_price") or 0)

            disc_line = money(ln.get("discount_amount") or 0)
            vat_rate = float(ln.get("vat_rate") or 0)

            line_net_gross = max(0.0, (qty * price) - disc_line)
            line_vat_gross = line_net_gross * (vat_rate / 100.0)
            line_total_gross = line_net_gross + line_vat_gross

            line_net_gross = money(line_net_gross)
            line_vat_gross = money(line_vat_gross)
            line_total_gross = money(line_total_gross)

            subtotal_gross = money(subtotal_gross + line_net_gross)
            line_discount_total = money(line_discount_total + disc_line)

            if vat_rate > 0:
                vatable_gross = money(vatable_gross + line_net_gross)

            prepared.append({
                "line_no": idx,
                "item_name": (ln.get("item_name") or ln.get("itemName") or "").strip(),
                "description": (ln.get("description") or "").strip(),
                "account_code": ln.get("account_code"),
                "quantity": qty,
                "unit_price": price,
                "discount_amount": disc_line,
                "net_amount": line_net_gross,
                "vat_rate": vat_rate,
                "vat_amount": line_vat_gross,
                "total_amount": line_total_gross,
            })

        # ---------- HEADER discount (percent) ----------
        disc_rate = header.get("discount_rate")
        if disc_rate is None:
            disc_rate = header.get("discount")
        try:
            disc_rate = float(disc_rate or 0.0)
        except Exception:
            disc_rate = 0.0
        disc_rate = max(0.0, min(1.0, disc_rate))

        header_discount_amt = money(subtotal_gross * disc_rate)

        disc_on_vatable = money(header_discount_amt * (vatable_gross / subtotal_gross)) if subtotal_gross > 0 else 0.0
        vatable_after = max(0.0, money(vatable_gross - disc_on_vatable))

        vat_total = money(vatable_after * 0.15) if vatable_gross > 0 else 0.0
        subtotal_after = money(max(0.0, subtotal_gross - header_discount_amt))
        grand_total = money(subtotal_after + vat_total)

        discount_total = money(line_discount_total + header_discount_amt)

        # if status is issued and issued_at not provided, you can set it automatically
        issued_at = header.get("issued_at")
        issued_by = header.get("issued_by")

        with self._conn_cursor() as (conn, cur):
            try:
                cur.execute(
                    f"""
                    UPDATE {schema}.quotations
                    SET
                        customer_id      = %s,
                        number           = %s,
                        quotation_date   = %s,
                        valid_until      = %s,
                        currency         = %s,
                        subtotal_amount  = %s,
                        discount_amount  = %s,
                        discount_rate    = %s,
                        vat_amount       = %s,
                        total_amount     = %s,
                        status           = %s,
                        notes            = %s,
                        terms            = %s,
                        issued_at        = COALESCE(%s, issued_at),
                        issued_by        = COALESCE(%s, issued_by),
                        updated_at       = NOW()
                    WHERE company_id = %s
                    AND id = %s;
                    """,
                    (
                        int(header["customer_id"]),
                        header.get("number"),
                        header.get("quotation_date"),
                        header.get("valid_until"),
                        header.get("currency"),
                        subtotal_after,
                        discount_total,
                        disc_rate,
                        vat_total,
                        grand_total,
                        status,
                        header.get("notes"),
                        header.get("terms"),
                        issued_at,
                        issued_by,
                        int(company_id),
                        int(quote_id),
                    ),
                )

                cur.execute(
                    f"DELETE FROM {schema}.quotation_lines WHERE company_id=%s AND quotation_id=%s;",
                    (int(company_id), int(quote_id)),
                )

                for pl in prepared:
                    cur.execute(
                        f"""
                        INSERT INTO {schema}.quotation_lines (
                            company_id,
                            quotation_id,
                            line_no,
                            item_name,
                            description,
                            account_code,
                            quantity,
                            unit_price,
                            discount_amount,
                            net_amount,
                            vat_rate,
                            vat_amount,
                            total_amount
                        )
                        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s);
                        """,
                        (
                            int(company_id),
                            int(quote_id),
                            pl["line_no"],
                            pl["item_name"],
                            pl["description"],
                            pl["account_code"],
                            pl["quantity"],
                            pl["unit_price"],
                            pl["discount_amount"],
                            pl["net_amount"],
                            pl["vat_rate"],
                            pl["vat_amount"],
                            pl["total_amount"],
                        ),
                    )

                conn.commit()
            except Exception:
                conn.rollback()
                raise


    def convert_quote_to_invoice(self, company_id: int, quote_id: int, user_id: int) -> int:
        schema = self.company_schema(company_id)

        with self._conn_cursor() as (conn, cur):
            cur.execute("SELECT pg_advisory_xact_lock(%s);", (int(company_id),))

            # lock quote
            cur.execute(f"""
            SELECT *
            FROM {schema}.quotations
            WHERE company_id=%s AND id=%s
            FOR UPDATE
            """, (company_id, quote_id))
            q = cur.fetchone()
            if not q:
                raise ValueError("Quote not found")

            # idempotent
            if isinstance(q, dict) and q.get("invoice_id"):
                conn.commit()
                return int(q["invoice_id"])

            status = (q.get("status") if isinstance(q, dict) else None) or "draft"
            status = str(status).strip().lower()

            if status == "converted" and not q.get("invoice_id"):
                raise ValueError("Quote marked converted but invoice_id missing")

            if status not in ("issued", "accepted"):
                raise ValueError(f"Quote must be issued before converting (status={status})")

            valid_until = q.get("valid_until") if isinstance(q, dict) else None
            if valid_until and date.today() > valid_until:
                cur.execute(f"""
                UPDATE {schema}.quotations
                SET status='expired', updated_at=NOW()
                WHERE company_id=%s AND id=%s
                """, (company_id, quote_id))
                conn.commit()
                raise ValueError("Quotation expired")

            # get quote lines
            cur.execute(f"""
            SELECT *
            FROM {schema}.quotation_lines
            WHERE company_id=%s AND quotation_id=%s
            ORDER BY line_no ASC, id ASC
            """, (company_id, quote_id))
            qlines = cur.fetchall() or []
            if not qlines:
                raise ValueError("Quotation has no lines")

            inv_header = {
                "customer_id": q["customer_id"],
                "status": "draft",
                "invoice_date": date.today(),
                "due_date": q.get("valid_until"),   # ✅ simple improvement
                "currency": q.get("currency"),
                "notes": q.get("notes"),
                "bank_account_id": None,

                # ⚠️ depends on how you fix discount storage/posting later
                "discount_rate": float(q.get("discount_rate") or 0),
                "other": 0,
            }

            inv_lines = []
            for ln in qlines:
                inv_lines.append({
                    "item_name": ln.get("item_name"),
                    "description": ln.get("description"),
                    "account_code": ln.get("account_code"),
                    "quantity": ln.get("quantity"),
                    "unit_price": ln.get("unit_price"),
                    "discount_amount": ln.get("discount_amount"),
                    "vat_rate": ln.get("vat_rate"),
                })

            invoice_id = self._insert_invoice_with_lines_cur(company_id, inv_header, inv_lines, cur)

            cur.execute(f"""
            UPDATE {schema}.quotations
            SET status='converted',
                invoice_id=%s,
                converted_at=NOW(),
                accepted_at=COALESCE(accepted_at, NOW()),
                accepted_by=COALESCE(accepted_by, %s),
                updated_at=NOW()
            WHERE company_id=%s AND id=%s
            """, (invoice_id, user_id, company_id, quote_id))

            conn.commit()
            return int(invoice_id)

    def get_quote_full(self, company_id: int, quote_id: int) -> Optional[Dict[str, Any]]:
        header = self.get_quote_with_relations(company_id, quote_id)
        if not header:
            return None

        schema = self.company_schema(company_id)
        lines_sql = f"""
        SELECT *
        FROM {schema}.quotation_lines
        WHERE company_id = %s
        AND quotation_id = %s
        ORDER BY line_no ASC, id ASC;
        """
        header["lines"] = self.fetch_all(lines_sql, (int(company_id), int(quote_id)))
        return header


    def get_quote_with_relations(self, company_id: int, quote_id: int) -> Optional[Dict[str, Any]]:
        schema = self.company_schema(company_id)

        sql = f"""
        SELECT
            q.id,
            q.company_id,
            q.customer_id,

            q.number,
            q.quotation_date,
            q.valid_until,
            q.currency,

            q.subtotal_amount,
            q.discount_amount,
            q.vat_amount,
            q.total_amount AS total,
            q.status,

            q.notes,
            q.terms,

            q.discount_rate,

            q.invoice_id,
            q.converted_at,

            q.issued_at,
            q.issued_by,
            q.accepted_at,
            q.accepted_by,

            -- customer details
            c.name             AS customer_name,
            c.email            AS customer_email,
            c.phone            AS customer_phone,
            c.billing_address  AS customer_address,
            c.shipping_address AS customer_shipping_address,
            c.country          AS customer_country,
            c.tax_number       AS customer_tax_number,
            c.vat_number       AS customer_vat_number,
            c.contacts         AS customer_contacts,

            -- company details (public.companies)
            co.name            AS company_name,
            co.company_email   AS company_email,
            co.company_reg_no  AS company_reg_no,
            co.tin             AS company_tin,
            co.vat             AS company_vat,
            co.country         AS company_country,
            co.currency        AS company_currency,

            -- branding (public.company_branding)
            cb.logo_url        AS branding_logo_url,
            cb.footer_text     AS branding_footer_text,
            cb.contact_phone   AS branding_contact_phone,
            cb.contact_email   AS branding_contact_email,
            cb.website         AS branding_website,
            cb.address         AS branding_address,
            cb.vat_no          AS branding_vat_no,
            co.company_reg_no  AS branding_reg_no

        FROM {schema}.quotations q
        JOIN {schema}.customers c
            ON c.id = q.customer_id
        AND c.company_id = q.company_id

        JOIN public.companies co
            ON co.id = %s

        LEFT JOIN public.company_branding cb
            ON cb.company_id = co.id

        WHERE q.company_id = %s
        AND q.id = %s
        LIMIT 1;
        """

        return self.fetch_one(sql, (int(company_id), int(company_id), int(quote_id)))


    def _row_to_dict(self, row, cols: List[str]) -> Dict[str, Any]:
        if not row:
            return {}
        if isinstance(row, dict):
            return row
        return {cols[i]: row[i] for i in range(min(len(cols), len(row)))}

    # --------------------------------------------------
    # AUDIT TRAIL
    # --------------------------------------------------
    def audit_log(
        self,
        company_id: int,
        *,
        actor_user_id: int,
        module: str,
        action: str,
        severity: str = "info",
        entity_type: str,
        entity_id: str,
        entity_ref: Optional[str] = None,
        journal_id: Optional[int] = None,
        customer_id: Optional[int] = None,
        vendor_id: Optional[int] = None,
        approval_request_id: Optional[int] = None,
        amount: float = 0.0,
        currency: Optional[str] = None,
        before_json: Optional[dict] = None,
        after_json: Optional[dict] = None,
        message: Optional[str] = None,
        source: Optional[str] = "api",
        cur=None,
    ) -> int:
        schema = self.company_schema(company_id)

        before_json = before_json if isinstance(before_json, dict) else {}
        after_json = after_json if isinstance(after_json, dict) else {}

        sql = f"""
        INSERT INTO {schema}.audit_trail
        (
            company_id,
            occurred_at,
            actor_user_id,
            module, action, severity,
            entity_type, entity_id, entity_ref,
            journal_id, customer_id, vendor_id, approval_request_id,
            amount, currency,
            before_json, after_json,
            message, source,
            created_at
        )
        VALUES
        (
            %s,
            NOW(),
            %s,
            %s, %s, %s,
            %s, %s, %s,
            %s, %s, %s, %s,
            %s, %s,
            %s::jsonb, %s::jsonb,
            %s, %s,
            NOW()
        )
        RETURNING id;
        """
        params = (
            int(company_id),
            int(actor_user_id),
            str(module).strip().lower(),
            str(action).strip().lower(),
            str(severity).strip().lower(),
            str(entity_type).strip().lower(),
            str(entity_id).strip(),
            (str(entity_ref).strip() if entity_ref else None),
            int(journal_id) if journal_id is not None else None,
            int(customer_id) if customer_id is not None else None,
            int(vendor_id) if vendor_id is not None else None,
            int(approval_request_id) if approval_request_id is not None else None,
            float(amount or 0.0),
            (str(currency).strip().upper() if currency else None),
            self._json(before_json),
            self._json(after_json),
            message,
            source,
        )

        if cur is not None:
            cur.execute(sql, params)
            row = cur.fetchone()
            return int((row.get("id") if isinstance(row, dict) else row[0]) or 0)

        return int(self.execute_sql(sql, params) or 0)

    def list_audit_trail(
            self,
            company_id: int,
            *,
            limit: int = 100,
            offset: int = 0,
            module: Optional[str] = None,
            severity: Optional[str] = None,
            entity_type: Optional[str] = None,
            entity_id: Optional[str] = None,
            actor_user_id: Optional[int] = None,
            from_ts: Optional[str] = None,  # ISO string
            to_ts: Optional[str] = None,    # ISO string
            cur=None,
        ) -> List[Dict[str, Any]]:
            schema = self.company_schema(company_id)

            # We add "at." prefix to ensure SQL knows we mean the Audit Trail table
            where = ["at.company_id=%s"]
            params: List[Any] = [int(company_id)]

            if module:
                where.append("at.module=%s")
                params.append(str(module).strip().lower())

            if severity:
                where.append("at.severity=%s")
                params.append(str(severity).strip().lower())

            if entity_type:
                where.append("at.entity_type=%s")
                params.append(str(entity_type).strip().lower())

            if entity_id:
                where.append("at.entity_id=%s")
                params.append(str(entity_id).strip())

            if actor_user_id:
                where.append("at.actor_user_id=%s")
                params.append(int(actor_user_id))

            if from_ts:
                where.append("at.occurred_at >= %s")
                params.append(from_ts)

            if to_ts:
                where.append("at.occurred_at <= %s")
                params.append(to_ts)

            # UPDATED SQL:
            # 1. We alias audit_trail as 'at'
            # 2. We LEFT JOIN public.users as 'u'
            # 3. We pull u.name (or u.full_name) as actor_name
            sql = f"""
            SELECT
                at.id, at.company_id, at.occurred_at,
                at.actor_user_id, 
                TRIM(u.first_name || ' ' || u.last_name) as actor_name,
                at.module, at.action, at.severity,
                at.entity_type, at.entity_id, at.entity_ref,
                at.journal_id, at.customer_id, at.vendor_id, at.approval_request_id,
                at.amount, at.currency,
                at.before_json, at.after_json,
                at.message, at.source, at.created_at
            FROM {schema}.audit_trail at
            LEFT JOIN public.users u ON at.actor_user_id = u.id
            WHERE {" AND ".join(where)}
            ORDER BY at.occurred_at DESC, at.id DESC
            LIMIT %s OFFSET %s
            """
            params.extend([int(limit), int(offset)])
            return self.fetch_all(sql, tuple(params), cur=cur)

    # --------------------------------------------------
    # tiny helper so we can pass jsonb safely
    # --------------------------------------------------
    def _json(self, obj) -> str:
        obj = obj if isinstance(obj, dict) else {}

        def default(o):
            # dates from DB or your code
            if isinstance(o, (date, datetime)):
                return o.isoformat()

            # money values sometimes come as Decimal
            if isinstance(o, Decimal):
                return float(o)

            # last-resort safe conversion for audit logs
            return str(o)

        return json.dumps(obj, ensure_ascii=False, default=default)


    # --------------------------------------------------
    # APPROVAL REQUESTS
    # --------------------------------------------------
    def create_approval_request(
        self,
        company_id: int,
        *,
        entity_type: str,
        entity_id: str,
        module: str,
        action: str,
        requested_by_user_id: int,
        amount: float = 0.0,
        currency: Optional[str] = None,
        risk_level: str = "low",
        entity_ref: Optional[str] = None,
        dedupe_key: Optional[str] = None,
        payload_json: Optional[dict] = None,
        cur=None,
    ) -> Dict[str, Any]:
        """
        Creates a pending approval request.

        ✅ Dedupe-safe:
        - If UNIQUE(company_id, dedupe_key) collides, returns the existing row.
        - Adds `_deduped: True|False` to the returned dict so callers can decide 201 vs 200.
        """
        schema = self.company_schema(company_id)
        payload_json = payload_json if isinstance(payload_json, dict) else {}

        sql = f"""
        INSERT INTO {schema}.approval_requests
        (
            company_id,
            entity_type, entity_id, entity_ref,
            module, action,
            requested_by_user_id,
            status,
            amount, currency, risk_level,
            dedupe_key,
            payload_json,
            created_at, updated_at
        )
        VALUES
        (
            %s,
            %s, %s, %s,
            %s, %s,
            %s,
            'pending',
            %s, %s, %s,
            %s,
            %s::jsonb,
            NOW(), NOW()
        )
        RETURNING id;
        """

        params = (
            int(company_id),
            str(entity_type).strip().lower(),
            str(entity_id).strip(),
            (str(entity_ref).strip() if entity_ref else None),
            str(module).strip().lower(),
            str(action).strip().lower(),
            int(requested_by_user_id),
            float(amount or 0.0),
            (str(currency).strip().upper() if currency else None),
            str(risk_level).strip().lower() or "low",
            (str(dedupe_key).strip() if dedupe_key else None),
            self._json(payload_json),
        )

        def _fetch_existing(_cur):
            if not dedupe_key:
                return None
            _cur.execute(
                f"""
                SELECT id
                FROM {schema}.approval_requests
                WHERE company_id=%s AND dedupe_key=%s
                ORDER BY id DESC
                LIMIT 1
                """,
                (int(company_id), str(dedupe_key).strip()),
            )
            r = _cur.fetchone()
            rid0 = int((r.get("id") if isinstance(r, dict) else r[0]) or 0) if r else 0
            if rid0 <= 0:
                return None
            item = self.get_approval_request(company_id, rid0, cur=_cur) or {"id": rid0}
            item["_deduped"] = True
            return item

        # -------------------------
        # If caller passed a cursor, we must not open our own txn.
        # -------------------------
        if cur is not None:
            try:
                cur.execute(sql, params)
                row = cur.fetchone()
                rid = int((row.get("id") if isinstance(row, dict) else row[0]) or 0)
                item = self.get_approval_request(company_id, rid, cur=cur) or {"id": rid}
                item["_deduped"] = False
                return item
            
            except psycopg2.Error as e:
                if getattr(e, "pgcode", None) == errorcodes.UNIQUE_VIOLATION:
                    existing = _fetch_existing(cur)
                    if existing:
                        return existing
                raise

        # -------------------------
        # No cursor provided: use our own connection context.
        # -------------------------
        with self._conn_cursor() as (conn, cur2):
            try:
                cur2.execute(sql, params)
                row = cur2.fetchone()
                rid = int((row.get("id") if isinstance(row, dict) else row[0]) or 0)
                conn.commit()

                item = self.get_approval_request(company_id, rid) or {"id": rid}
                item["_deduped"] = False
                return item

            except psycopg2.Error as e:
                try:
                    conn.rollback()
                except Exception:
                    pass

                if getattr(e, "pgcode", None) == errorcodes.UNIQUE_VIOLATION:
                    existing = _fetch_existing(cur2)
                    if existing:
                        return existing

                raise

    def get_approval_request(self, company_id: int, request_id: int, cur=None) -> Optional[Dict[str, Any]]:
        schema = self.company_schema(company_id)
        sql = f"""
        SELECT
            id, company_id,
            entity_type, entity_id, entity_ref,
            module, action,
            requested_by_user_id, requested_at,
            status, decided_by_user_id, decided_at, decision_note,
            amount, currency, risk_level,
            dedupe_key, payload_json,
            created_at, updated_at
        FROM {schema}.approval_requests
        WHERE company_id=%s AND id=%s
        LIMIT 1
        """
        return self.fetch_one(sql, (int(company_id), int(request_id)), cur=cur)


    
    def list_approval_requests(
        self,
        company_id: int,
        *,
        status: Optional[str] = None,
        module: Optional[str] = None,
        entity_type: Optional[str] = None,
        entity_id: Optional[str] = None,
        requested_by_user_id: Optional[int] = None,
        decided_by_user_id: Optional[int] = None,
        limit: int = 50,
        offset: int = 0,
        cur=None,
    ) -> List[Dict[str, Any]]:
        schema = self.company_schema(company_id)

        where = ["company_id=%s"]
        params: List[Any] = [int(company_id)]

        if status:
            where.append("status=%s")
            params.append(str(status).strip().lower())

        if module:
            where.append("module=%s")
            params.append(str(module).strip().lower())

        if entity_type:
            where.append("entity_type=%s")
            params.append(str(entity_type).strip().lower())

        if entity_id:
            where.append("entity_id=%s")
            params.append(str(entity_id).strip())

        if requested_by_user_id:
            where.append("requested_by_user_id=%s")
            params.append(int(requested_by_user_id))

        if decided_by_user_id:
            where.append("decided_by_user_id=%s")
            params.append(int(decided_by_user_id))

        sql = f"""
        SELECT
            id, company_id,
            entity_type, entity_id, entity_ref,
            module, action,
            requested_by_user_id, requested_at,
            status, decided_by_user_id, decided_at, decision_note,
            amount, currency, risk_level,
            dedupe_key, payload_json,
            created_at, updated_at
        FROM {schema}.approval_requests
        WHERE {" AND ".join(where)}
        ORDER BY requested_at DESC, id DESC
        LIMIT %s OFFSET %s
        """
        params.extend([int(limit), int(offset)])

        return self.fetch_all(sql, tuple(params), cur=cur)
    
    def decide_approval_request(
        self,
        company_id: int,
        request_id: int,
        *,
        decision: str,
        decided_by_user_id: int,
        note: Optional[str] = None,
        meta_json: Optional[dict] = None,
    ) -> Dict[str, Any]:
        """
        decision: approve|reject|comment|cancel|reassign

        Rules:
        - Only PENDING requests can be decided (including comment/reassign).
        - Concurrency-safe: status update uses WHERE status='pending' so 2 deciders can't both win.
        - Always writes approval_decisions history.
        - approve/reject/cancel set decided_by/decided_at + change status.
        - comment keeps pending (history only, bump updated_at).
        - reassign keeps pending (history + bump updated_at). Meta should include target info.
        """
        schema = self.company_schema(company_id)
        meta_json = meta_json if isinstance(meta_json, dict) else {}
        d = (decision or "").strip().lower()

        allowed = {"approve", "reject", "comment", "cancel", "reassign"}
        if d not in allowed:
            raise ValueError("Invalid decision")

        decided_by_user_id = int(decided_by_user_id or 0)
        if decided_by_user_id <= 0:
            raise ValueError("decided_by_user_id is required")

        # status transition
        status_map = {
            "approve": "approved",
            "reject": "rejected",
            "cancel": "cancelled",
            "comment": "pending",
            "reassign": "pending",
        }
        new_status = status_map[d]
        decision_note = (note or None)

        with self._conn_cursor() as (conn, cur):
            # ---- Load current request (FOR audit + validation) ----
            req = self.get_approval_request(company_id, request_id, cur=cur)
            if not req:
                raise ValueError("Approval request not found")

            prev_status = (req.get("status") or "").strip().lower()
            if prev_status != "pending":
                # ✅ hard block: no decisions once not pending
                raise ValueError(f"Request is not pending ({prev_status})")

            # ---- Always write decision history first ----
            self.insert_approval_decision(
                company_id,
                approval_request_id=int(request_id),
                decision=d,
                decided_by_user_id=decided_by_user_id,
                note=decision_note,
                meta_json=meta_json,
                cur=cur,
            )

            # ---- Update request row (CONCURRENCY SAFE) ----
            # approve/reject/cancel => stamp decided fields
            if d in {"approve", "reject", "cancel"}:
                cur.execute(
                    f"""
                    UPDATE {schema}.approval_requests
                    SET
                        status=%s,
                        decided_by_user_id=%s,
                        decided_at=NOW(),
                        decision_note=COALESCE(%s, decision_note),
                        updated_at=NOW()
                    WHERE company_id=%s
                    AND id=%s
                    AND status='pending'
                    RETURNING id;
                    """,
                    (
                        new_status,
                        decided_by_user_id,
                        decision_note,
                        int(company_id),
                        int(request_id),
                    ),
                )
                row = cur.fetchone()
                if not row:
                    # someone else already decided it
                    raise ValueError("Request is not pending (already decided)")
            else:
                # comment / reassign => keep pending, but bump updated_at
                cur.execute(
                    f"""
                    UPDATE {schema}.approval_requests
                    SET updated_at=NOW()
                    WHERE company_id=%s
                    AND id=%s
                    AND status='pending'
                    RETURNING id;
                    """,
                    (int(company_id), int(request_id)),
                )
                row = cur.fetchone()
                if not row:
                    raise ValueError("Request is not pending (already decided)")

            # ---- Best-effort audit log ----
            try:
                sev = "info"
                if d in {"reject", "cancel"}:
                    sev = "warn"

                after_status = prev_status if d in {"comment", "reassign"} else new_status

                self.audit_log(
                    company_id,
                    actor_user_id=decided_by_user_id,
                    module=str(req.get("module") or "approvals"),
                    action=f"approval_{d}",
                    severity=sev,
                    entity_type=str(req.get("entity_type") or "entity"),
                    entity_id=str(req.get("entity_id") or ""),
                    entity_ref=req.get("entity_ref"),
                    approval_request_id=int(request_id),
                    amount=float(req.get("amount") or 0.0),
                    currency=req.get("currency"),
                    before_json={"status": prev_status},
                    after_json={"status": after_status},
                    message=decision_note,
                    source="api",
                    cur=cur,
                )
            except Exception:
                pass

            conn.commit()
            return self.get_approval_request(company_id, request_id, cur=cur) or {}

    def list_approval_decisions(
        self,
        company_id: int,
        *,
        approval_request_id: int,
        limit: int = 100,
        offset: int = 0,
        cur=None,
    ):
        schema = self.company_schema(company_id)

        sql = f"""
        SELECT
        d.*,
        u.name  AS decided_by_name,
        u.email AS decided_by_email
        FROM {schema}.approval_decisions d
        LEFT JOIN public.users u ON u.id = d.decided_by_user_id
        WHERE d.company_id=%s
        AND d.approval_request_id=%s
        ORDER BY d.decided_at DESC
        LIMIT %s OFFSET %s;
        """

        return self.fetch_all(
            sql,
            (int(company_id), int(approval_request_id), int(limit), int(offset)),
            cur=cur,
        )

    # ==================================================
    # APPROVAL DECISIONS (history)
    # ==================================================
    def insert_approval_decision(
        self,
        company_id: int,
        *,
        approval_request_id: int,
        decision: str,
        decided_by_user_id: int,
        note: Optional[str] = None,
        meta_json: Optional[dict] = None,
        cur=None,
    ) -> int:
        schema = self.company_schema(company_id)
        meta_json = meta_json if isinstance(meta_json, dict) else {}

        sql = f"""
        INSERT INTO {schema}.approval_decisions
        (company_id, approval_request_id, decision, decided_by_user_id, decided_at, note, meta_json)
        VALUES (%s, %s, %s, %s, NOW(), %s, %s::jsonb)
        RETURNING id;
        """
        params = (
            int(company_id),
            int(approval_request_id),
            str(decision).strip().lower(),
            int(decided_by_user_id),
            note,
            self._json(meta_json),
        )

        if cur is not None:
            cur.execute(sql, params)
            row = cur.fetchone()
            return int((row.get("id") if isinstance(row, dict) else row[0]) or 0)

        return int(self.execute_sql(sql, params) or 0)


    def post_asset_acquisition_to_gl(self, company_id: int, *, acq_id: int, cur) -> int:
        """
        Posts an asset acquisition to GL (idempotent by asset_acquisitions.posted_journal_id).

        Credit logic:
        1) If asset_grni_links exist for this asset -> Cr GRNI
        2) Else if funding_source in ('bank','cash','bank_cash') -> Cr Bank/Cash (bank_account_code)
        3) Else if funding_source in ('ap','vendor_credit') -> Cr AP control
        4) Else -> Cr credit_account_code
        """

        def money(x) -> float:
            return float(Decimal(str(x or 0)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))

        def resolve_posting_code(raw: str, label: str) -> str:
            k = (raw or "").strip()
            if not k:
                raise ValueError(f"{label}_NOT_SET")
            row = self.get_account_row_for_posting(company_id, k, cur=cur)
            if not row:
                raise ValueError(f"{label}_NOT_FOUND_IN_COA|{k}")
            code = (row[1] or "").strip()   # ✅ posting code is tuple index 1
            if not code:
                raise ValueError(f"{label}_RESOLVED_BLANK|{k}")
            return code

        schema = f"company_{int(company_id)}"

        # 1) lock acquisition row (prevents double-post)
        cur.execute(
            f"""
            SELECT *
            FROM {schema}.asset_acquisitions
            WHERE company_id=%s AND id=%s
            FOR UPDATE
            """,
            (int(company_id), int(acq_id)),
        )
        acq = cur.fetchone() or {}
        if not acq:
            raise ValueError(f"ASSET_ACQ_NOT_FOUND|acq_id={acq_id}")

        if acq.get("posted_journal_id"):
            return int(acq["posted_journal_id"])

        status = (acq.get("status") or "draft").strip().lower()
        if status in ("void", "reversed"):
            raise ValueError(f"ACQ_STATUS_NOT_POSTABLE|status={status}")

        asset_id = int(acq.get("asset_id") or 0)
        if asset_id <= 0:
            raise ValueError("ASSET_ID_MISSING_ON_ACQUISITION")

        acq_date = str(acq.get("acquisition_date") or "")[:10]
        if not acq_date:
            raise ValueError("ACQUISITION_DATE_MISSING")

        amount = money(acq.get("amount") or 0)
        if amount <= 0:
            raise ValueError("ACQUISITION_AMOUNT_INVALID")

        funding = (acq.get("funding_source") or "cash").strip().lower()

        # 2) load asset mapping (PPE account)
        cur.execute(
            f"""
            SELECT id, asset_name, asset_account_code, supplier_id
            FROM {schema}.assets
            WHERE company_id=%s AND id=%s
            LIMIT 1
            """,
            (int(company_id), int(asset_id)),
        )
        asset = cur.fetchone() or {}
        if not asset:
            raise ValueError(f"ASSET_NOT_FOUND|asset_id={asset_id}")

        asset_acct_raw = (asset.get("asset_account_code") or "").strip()
        if not asset_acct_raw:
            raise ValueError("ASSET_ACCOUNT_CODE_MISSING_ON_ASSET")

        PPE = resolve_posting_code(asset_acct_raw, "PPE_ACCOUNT")

        vendor_id = int(asset.get("supplier_id") or 0) or None  # optional trace

        # 3) controls
        settings = self.get_company_account_settings(company_id, cur=cur) or {}

        ap_raw = (settings.get("ap_control_code") or "").strip()
        grni_raw = (settings.get("grni_control_code") or settings.get("ppv_control_code") or "").strip()

        AP = resolve_posting_code(ap_raw, "AP_CONTROL") if ap_raw else None
        GRNI = resolve_posting_code(grni_raw, "GRNI_CONTROL") if grni_raw else None

        # 4) detect GRNI links for this asset (sum)
        # (Make sure you created company_{id}.asset_grni_links)
        cur.execute(
            f"""
            SELECT COALESCE(SUM(amount),0)::numeric(18,2) AS linked
            FROM {schema}.asset_grni_links
            WHERE company_id=%s AND asset_id=%s
            """,
            (int(company_id), int(asset_id)),
        )
        lr = cur.fetchone() or {}
        grni_linked = money(lr.get("linked") or 0)

        # 5) pick credit account
        credit_acct = None
        credit_memo = None

        if grni_linked > 0 and funding == "grni":
            if not GRNI:
                raise ValueError("GRNI_NOT_CONFIGURED|set grni_control_code in company_account_settings")

            supplier_id = int(asset.get("supplier_id") or 0)
            if supplier_id <= 0:
                raise ValueError("ASSET_VENDOR_REQUIRED_FOR_GRNI|set assets.supplier_id")

            linked = self.sum_asset_grni_links(company_id, int(acq_id), cur=cur)  # acquisition-level sum
            if linked <= 0:
                raise ValueError("GRNI_LINKS_REQUIRED|link receipt(s) before posting")
            if abs(linked - amount) > 0.01:
                raise ValueError(f"GRNI_LINKS_MUST_MATCH_ACQ|linked={linked}|acq_amount={amount}")

            # optional but best: validate each linked receipt vendor matches supplier_id (do it inside sum fn or here)
            # self.validate_asset_grni_receipts_vendor(company_id, acq_id, supplier_id, cur=cur)

            credit_acct = GRNI
            credit_memo = "GRNI clearing (capitalise asset from receipt)"

        elif funding in ("bank", "cash", "bank_cash"):
            bank_raw = (acq.get("bank_account_code") or "").strip()
            if not bank_raw:
                raise ValueError("BANK_ACCOUNT_CODE_REQUIRED_FOR_BANK_CASH")
            credit_acct = resolve_posting_code(bank_raw, "BANK_ACCOUNT")
            credit_memo = "Paid from bank/cash"

        elif funding in ("ap", "vendor_credit"):
            if not AP:
                raise ValueError("AP_CONTROL_NOT_CONFIGURED|set ap_control_code in company_account_settings")
            credit_acct = AP
            credit_memo = "Asset on credit (AP)"

        else:
            other_raw = (acq.get("credit_account_code") or "").strip()
            if not other_raw:
                raise ValueError("CREDIT_ACCOUNT_CODE_REQUIRED_FOR_OTHER_FUNDING")
            credit_acct = resolve_posting_code(other_raw, "CREDIT_ACCOUNT")
            credit_memo = "Asset funded (other)"

        # 6) create journal header
        ref = (acq.get("reference") or f"ASSET-ACQ-{acq_id}").strip()
        asset_name = (asset.get("asset_name") or "").strip()
        memo = f"Asset acquisition #{acq_id}" + (f" • {asset_name}" if asset_name else "")

        journal_id = int(self.create_journal_header(
            company_id=int(company_id),
            je_date=acq_date,
            ref=ref,
            memo=memo,
            source="asset_acquisition",
            source_id=int(acq_id),
            gross_amount=amount,
            net_amount=amount,
            vat_amount=0.0,
            cur=cur,
        ) or 0)
        if journal_id <= 0:
            raise ValueError("FAILED_TO_CREATE_ASSET_ACQ_JOURNAL")

        # 7) insert ledger lines
        self.insert_ledger(
            company_id=int(company_id),
            journal_id=int(journal_id),
            je_date=acq_date,
            line={"account_code": PPE, "debit": amount, "credit": 0.0, "memo": "Capitalise asset cost"},
            ref=ref,
            vendor_id=vendor_id,
            source="asset_acquisition",
            source_id=int(acq_id),
            cur=cur,
        )
        self.update_trial_balance(int(company_id), {"account_code": PPE, "debit": amount, "credit": 0.0}, cur=cur)

        self.insert_ledger(
            company_id=int(company_id),
            journal_id=int(journal_id),
            je_date=acq_date,
            line={"account_code": credit_acct, "debit": 0.0, "credit": amount, "memo": credit_memo},
            ref=ref,
            vendor_id=vendor_id,
            source="asset_acquisition",
            source_id=int(acq_id),
            cur=cur,
        )
        self.update_trial_balance(int(company_id), {"account_code": credit_acct, "debit": 0.0, "credit": amount}, cur=cur)

        # 8) stamp acquisition as posted
        cur.execute(f"""
            SELECT COALESCE(SUM(amount),0)::numeric(18,2) AS linked
            FROM {schema}.asset_grni_links
            WHERE company_id=%s AND acquisition_id=%s
        """, (int(company_id), int(acq_id)))
        grni_linked = money((cur.fetchone() or {}).get("linked") or 0)

        return int(journal_id)


    def replace_asset_grni_links(self, company_id: int, asset_id: int, links: list[dict], cur=None) -> None:
        schema = self.company_schema(company_id)

        def _norm_amt(x):
            try:
                return float(str(x or 0).replace(",", "").strip() or 0)
            except Exception:
                return 0.0

        links = links if isinstance(links, list) else []

        def _run(_cur):
            # 0) load asset supplier (vendor)
            _cur.execute(
                f"SELECT supplier_id FROM {schema}.assets WHERE company_id=%s AND id=%s LIMIT 1",
                (int(company_id), int(asset_id)),
            )
            a = _cur.fetchone() or {}
            asset_vendor_id = int((a.get("supplier_id") if isinstance(a, dict) else a[0]) or 0)
            if asset_vendor_id <= 0:
                raise ValueError("ASSET_NOT_FOUND_OR_SUPPLIER_MISSING")

            # 1) wipe existing links
            _cur.execute(
                f"DELETE FROM {schema}.asset_grni_links WHERE company_id=%s AND asset_id=%s",
                (int(company_id), int(asset_id)),
            )

            # 2) insert new links with validation
            for ln in links:
                tx_id = int(ln.get("receipt_tx_id") or 0)
                amt = _norm_amt(ln.get("amount"))
                if tx_id <= 0 or amt <= 0:
                    continue

                # A) validate receipt belongs to same vendor + is posted receipt
                _cur.execute(
                    f"""
                    SELECT id, vendor_id, tx_type, status
                    FROM {schema}.inventory_tx
                    WHERE company_id=%s AND id=%s
                    LIMIT 1
                    """,
                    (int(company_id), int(tx_id)),
                )
                r = _cur.fetchone() or {}
                r_vendor = int(r.get("vendor_id") or 0)
                tx_type = (r.get("tx_type") or "").lower()
                status = (r.get("status") or "").lower()

                if r_vendor != asset_vendor_id:
                    raise ValueError(f"RECEIPT_VENDOR_MISMATCH|tx_id={tx_id}")
                if tx_type not in ("receipt", "receive"):
                    raise ValueError(f"INVALID_RECEIPT_TX_TYPE|tx_id={tx_id}|tx_type={tx_type}")
                if status != "posted":
                    raise ValueError(f"RECEIPT_NOT_POSTED|tx_id={tx_id}|status={status}")

                # B) compute receipt total and remaining (subtract what’s linked to bills AND assets)
                _cur.execute(
                    f"""
                    SELECT COALESCE(SUM(qty*unit_cost),0)::numeric(18,2) AS tot
                    FROM {schema}.inventory_tx_lines
                    WHERE company_id=%s AND tx_id=%s
                    """,
                    (int(company_id), int(tx_id)),
                )
                receipt_total = float((_cur.fetchone() or {}).get("tot") or 0)

                _cur.execute(
                    f"""
                    SELECT
                    (SELECT COALESCE(SUM(amount),0)::numeric(18,2)
                    FROM {schema}.bill_grni_links
                    WHERE company_id=%s AND receipt_tx_id=%s) +
                    (SELECT COALESCE(SUM(amount),0)::numeric(18,2)
                    FROM {schema}.asset_grni_links
                    WHERE company_id=%s AND receipt_tx_id=%s)
                    AS linked
                    """,
                    (int(company_id), int(tx_id), int(company_id), int(tx_id)),
                )
                linked_total = float((_cur.fetchone() or {}).get("linked") or 0)

                remaining = max(0.0, receipt_total - linked_total)
                if amt > remaining + 0.0001:
                    raise ValueError(f"GRNI_OVERLINK|tx_id={tx_id}|amt={amt}|remaining={remaining}")

                _cur.execute(
                    f"""
                    INSERT INTO {schema}.asset_grni_links (company_id, asset_id, receipt_tx_id, amount)
                    VALUES (%s,%s,%s,%s)
                    ON CONFLICT (company_id, asset_id, receipt_tx_id)
                    DO UPDATE SET amount=EXCLUDED.amount
                    """,
                    (int(company_id), int(asset_id), int(tx_id), float(amt)),
                )

        if cur is not None:
            return _run(cur)

        with self._conn_cursor() as (conn, _cur):
            _run(_cur)
            conn.commit()

    def list_open_grni_receipts_for_asset(self, company_id: int, *, asset_id: int, q: str = "", limit: int = 50, offset: int = 0):
        schema = self.company_schema(company_id)
        q = (q or "").strip()

        # load asset supplier
        asset = self.fetch_one(
            f"SELECT supplier_id FROM {schema}.assets WHERE company_id=%s AND id=%s LIMIT 1",
            (int(company_id), int(asset_id)),
        ) or {}
        vendor_id = int(asset.get("supplier_id") or 0)
        if vendor_id <= 0:
            return []

        where = [
            "t.company_id=%s",
            "t.vendor_id=%s",
            "lower(t.status)=lower('posted')",
            "lower(t.tx_type) IN ('receive','receipt')",
        ]
        params = [int(company_id), int(vendor_id)]

        if q:
            where.append("""
            (
            lower(coalesce(t.ref,''))   LIKE lower(%s)
            OR lower(coalesce(t.notes,'')) LIKE lower(%s)
            )
            """)
            params += [f"%{q}%", f"%{q}%"]

        sql = f"""
        WITH receipt_totals AS (
        SELECT l.tx_id,
                COALESCE(SUM(COALESCE(l.qty,0) * COALESCE(l.unit_cost,0)),0)::numeric(18,2) AS receipt_total
        FROM {schema}.inventory_tx_lines l
        WHERE l.company_id=%s
        GROUP BY l.tx_id
        ),
        linked AS (
        SELECT receipt_tx_id AS tx_id,
                COALESCE(SUM(amount),0)::numeric(18,2) AS linked_total
        FROM (
            SELECT company_id, receipt_tx_id, amount FROM {schema}.bill_grni_links
            UNION ALL
            SELECT company_id, receipt_tx_id, amount FROM {schema}.asset_grni_links
        ) u
        WHERE company_id=%s
        GROUP BY receipt_tx_id
        )
        SELECT
        t.id AS id,
        t.id AS receipt_tx_id,
        t.tx_date,
        t.ref,
        t.notes,
        COALESCE(rt.receipt_total,0)::numeric(18,2) AS receipt_total,
        COALESCE(li.linked_total,0)::numeric(18,2)  AS linked_total,
        (COALESCE(rt.receipt_total,0) - COALESCE(li.linked_total,0))::numeric(18,2) AS open_amount
        FROM {schema}.inventory_tx t
        LEFT JOIN receipt_totals rt ON rt.tx_id=t.id
        LEFT JOIN linked li ON li.tx_id=t.id
        WHERE {" AND ".join(where)}
        AND (COALESCE(rt.receipt_total,0) - COALESCE(li.linked_total,0)) > 0
        ORDER BY t.tx_date DESC, t.id DESC
        LIMIT %s OFFSET %s
        """

        params2 = [int(company_id), int(company_id)] + params + [int(limit), int(offset)]
        return self.fetch_all(sql, tuple(params2)) or []

    def list_asset_grni_links(self, company_id: int, acq_id: int, cur=None):
        schema = self.company_schema(company_id)
        sql = f"""
        SELECT *
        FROM {schema}.asset_grni_links
        WHERE company_id=%s AND acquisition_id=%s
        ORDER BY id ASC
        """
        return self.fetch_all(sql, (int(company_id), int(acq_id)), cur=cur) or []

    def sum_asset_grni_links(self, company_id: int, acq_id: int, cur=None) -> float:
        schema = self.company_schema(company_id)
        sql = f"""
        SELECT COALESCE(SUM(amount),0)::numeric(18,2) AS s
        FROM {schema}.asset_grni_links
        WHERE company_id=%s AND acquisition_id=%s
        """
        r = self.fetch_one(sql, (int(company_id), int(acq_id)), cur=cur) or {}
        return float(r.get("s") or 0.0)

    def post_lease_monthly_by_schedule_id(self, company_id: int, schedule_id: int, *, user_id: int) -> dict:
        schema = self.company_schema(company_id)
        with self._conn_cursor() as (conn, cur):
            try:
                row = self.fetch_one(
                    f"""
                    SELECT id, lease_id, period_no, period_end, payment, posted_journal_id
                    FROM {schema}.lease_schedule
                    WHERE company_id=%s AND id=%s
                    LIMIT 1
                    FOR UPDATE;
                    """,
                    (int(company_id), int(schedule_id)),
                    cur=cur,
                ) or {}
                if not row:
                    raise ValueError("Schedule not found")

                if row.get("posted_journal_id"):
                    conn.commit()
                    return {"journal_id": int(row["posted_journal_id"]), "idempotent": True}

                # reuse your existing builder
                lines = self.build_monthly_lease_journal_lines(company_id, lease_id=int(row["lease_id"]), schedule_id=int(schedule_id), cur=cur)
                if not lines:
                    raise ValueError("Cannot build monthly lease journal lines")

                # journal header
                j_date = row.get("period_end")
                lease = self.get_lease(company_id, int(row["lease_id"])) or {}
                desc = f"IFRS 16 monthly posting – {lease.get('lease_name') or 'Lease ' + str(row['lease_id'])} – P{row['period_no']}"

                entry = {
                    "date": j_date,
                    "ref": f"LEASE-{row['lease_id']}-P{row['period_no']}",
                    "description": desc,
                    "gross_amount": float(row.get("payment") or 0.0),
                    "net_amount": float(row.get("payment") or 0.0),
                    "vat_amount": 0.0,
                    "source": "lease_monthly",
                    "source_id": int(schedule_id),
                }
                entry = {
                    "date": j_date,
                    "ref": f"LEASE-{row['lease_id']}-P{row['period_no']}",
                    "description": desc,
                    "gross_amount": float(row.get("payment") or 0.0),
                    "net_amount": float(row.get("payment") or 0.0),
                    "vat_amount": 0.0,
                    "source": "lease_monthly",
                    "source_id": int(schedule_id),
                    "module_name": "leases",
                    "event_type": "posted",
                    "source_table": "lease_schedule",
                    "created_by_user_id": user_id,
                    "updated_by_user_id": user_id,
                    "prepared_by_user_id": user_id,
                    "lines": lines,
                }

                entry = self._apply_engagement_bridge_to_entry(
                    entry,
                    row=lease,
                )

                journal_id = int(self.post_journal(company_id, entry, cur=cur) or 0)
                # stamp schedule
                try:
                    cur.execute(
                        f"""
                        UPDATE {schema}.lease_schedule
                        SET posted_journal_id=%s, posted_at=NOW()
                        WHERE company_id=%s AND id=%s;
                        """,
                        (int(journal_id), int(company_id), int(schedule_id)),
                    )
                except Exception:
                    pass

                conn.commit()
                return {"journal_id": int(journal_id), "schedule_id": int(schedule_id), "posted": True}
            except Exception:
                conn.rollback()
                raise

    def get_ppe_gl_carrying_amount(self, cur, company_id: int, end_date):
        schema = self.company_schema(company_id)

        ppe_roles = (
            "ppe_cost",
            "ppe_land",
            "ppe_buildings",
            "ppe_plant_machinery",
            "ppe_motor_vehicles",
            "ppe_computer_equipment",
            "ppe_furniture_fittings",
            "ppe_office_equipment",
            "ppe_tools",
            "ppe_construction_equipment",
            "ppe_accumulated_depreciation",
            "accumulated_depreciation_buildings",
            "accumulated_depreciation_motor_vehicles",
            "accumulated_depreciation_computer_equipment",
            "accumulated_depreciation_office_equipment",
            "accumulated_depreciation_office_furniture",
            "accumulated_depreciation_tools",
            "accumulated_depreciation_ppe",
        )

        cur.execute(f"""
            SELECT COALESCE(SUM(l.debit - l.credit), 0)::numeric(18,2) AS balance
            FROM {schema}.ledger l
            JOIN {schema}.coa c 
                ON c.code = l.account
            WHERE l.date <= %s
            AND COALESCE(c.section, '') ILIKE '%%asset%%'
            AND (
                    c.role = ANY(%s)
                OR UPPER(TRIM(COALESCE(c.standard, ''))) = 'IAS 16'
            )
            AND NOT (
                    c.name ILIKE '%%right-of-use%%'
                OR c.name ILIKE '%%ROU%%'
                OR c.name ILIKE '%%intangible%%'
                OR c.name ILIKE '%%software%%'
            )
        """, (end_date, list(ppe_roles)))

        row = cur.fetchone()
        return row["balance"] if isinstance(row, dict) else row[0]

    def ensure_ppe_reporting_views(self,cur, company_id: int) -> None:
        """
        Creates / refreshes PPE reporting views in the tenant schema.
        Requires:
        - assets.accumulated_impairment
        - asset_disposals.cost_removed / accum_dep_removed / impairment_removed
        - asset_held_for_sale.cost_transferred / accum_dep_transferred / impairment_transferred
        """
        schema = self.company_schema(company_id)

        cur.execute(f"""
            DROP VIEW IF EXISTS {schema}.vw_ppe_disclosure_by_class;
            DROP VIEW IF EXISTS {schema}.vw_ppe_movements;
        """)

        sql = f"""
        -- =========================================================
        -- PPE MOVEMENTS VIEW
        -- Normalises PPE events into one reporting stream
        -- =========================================================
        CREATE VIEW {schema}.vw_ppe_movements AS
        WITH asset_base AS (
            SELECT
                a.company_id,
                a.id AS asset_id,
                a.asset_code,
                a.asset_name,
                a.asset_class,
                a.category,
                a.acquisition_date,
                a.available_for_use_date,
                a.measurement_basis,
                a.status AS asset_status,

                COALESCE(a.opening_cost, 0)::numeric(18,2)         AS opening_cost,
                COALESCE(a.opening_accum_dep, 0)::numeric(18,2)    AS opening_accum_dep,
                COALESCE(a.opening_impairment, 0)::numeric(18,2)   AS opening_impairment,
                COALESCE(a.accumulated_impairment, 0)::numeric(18,2) AS current_accumulated_impairment,
                COALESCE(a.cost, 0)::numeric(18,2)                 AS current_cost,
                COALESCE(a.residual_value, 0)::numeric(18,2)       AS residual_value
            FROM {schema}.assets a
            WHERE LOWER(REPLACE(COALESCE(a.accounting_standard, ''), ' ', '')) IN ('ias16', 'ias16ppe')
              AND COALESCE(a.is_component_group, FALSE) = FALSE
        ),
        opening_rows AS (
            SELECT
                ab.company_id,
                ab.asset_id,
                ab.asset_code,
                ab.asset_name,
                ab.asset_class,
                ab.category,
                NULL::date AS period_start,
                NULL::date AS period_end,
                DATE '1900-01-01' AS event_date,

                'opening'::text AS movement_type,
                'assets'::text  AS source_table,
                ab.asset_id::bigint AS source_id,

                ab.measurement_basis,
                NULL::text AS narrative,

                ab.opening_cost::numeric(18,2)         AS cost_delta,
                ab.opening_accum_dep::numeric(18,2)    AS accum_dep_delta,
                ab.opening_impairment::numeric(18,2)   AS impairment_delta,
                0::numeric(18,2)                       AS revaluation_reserve_delta,

                (
                    ab.opening_cost
                    - ab.opening_accum_dep
                    - ab.opening_impairment
                )::numeric(18,2) AS carrying_delta
            FROM asset_base ab
            WHERE
                ab.opening_cost <> 0
                OR ab.opening_accum_dep <> 0
                OR ab.opening_impairment <> 0
        ),

        acquisition_rows AS (
            SELECT
                a.company_id,
                a.id AS asset_id,
                a.asset_code,
                a.asset_name,
                a.asset_class,
                a.category,
                NULL::date AS period_start,
                NULL::date AS period_end,
                ac.acquisition_date AS event_date,
                'addition'::text AS movement_type,
                'asset_acquisitions'::text AS source_table,
                ac.id::bigint AS source_id,
                a.measurement_basis,
                COALESCE(ac.reference, ac.notes)::text AS narrative,
                amount.capitalised_cost AS cost_delta,
                0::numeric(18,2) AS accum_dep_delta,
                0::numeric(18,2) AS impairment_delta,
                0::numeric(18,2) AS revaluation_reserve_delta,
                amount.capitalised_cost AS carrying_delta
            FROM {schema}.asset_acquisitions ac
            JOIN {schema}.assets a ON a.id = ac.asset_id
            CROSS JOIN LATERAL (
                SELECT ROUND((
                    COALESCE(
                        ac.net_amount,
                        CASE
                            WHEN COALESCE(ac.vat_treatment, 'no_vat') = 'inclusive'
                            AND COALESCE(ac.vat_amount, 0) <> 0
                            THEN COALESCE(ac.gross_amount, ac.amount, 0)
                                - COALESCE(ac.vat_amount, 0)
                            WHEN COALESCE(ac.vat_treatment, 'no_vat') = 'exclusive'
                            THEN COALESCE(ac.amount, ac.gross_amount, 0)
                            ELSE COALESCE(ac.amount, ac.gross_amount, 0)
                        END,
                        0
                    )
                    + CASE
                        WHEN COALESCE(ac.nonrecoverable_vat_capitalized, FALSE)
                        THEN COALESCE(ac.non_recoverable_vat_amount, 0)
                        ELSE 0
                    END
                )::numeric, 2)::numeric(18,2) AS capitalised_cost
            ) amount
            WHERE COALESCE(ac.status, 'draft') = 'posted'
            AND COALESCE(a.is_component_group, FALSE) = FALSE
        ),

        fallback_acquisition_rows AS (
            SELECT
                a.company_id,
                a.id AS asset_id,
                a.asset_code,
                a.asset_name,
                a.asset_class,
                a.category,
                NULL::date AS period_start,
                NULL::date AS period_end,
                a.acquisition_date AS event_date,

                'addition'::text AS movement_type,
                'assets_fallback'::text AS source_table,
                a.id::bigint AS source_id,

                a.measurement_basis,
                'Fallback asset-register acquisition'::text AS narrative,

                COALESCE(NULLIF(a.opening_cost, 0), a.cost, 0)::numeric(18,2) AS cost_delta,
                0::numeric(18,2) AS accum_dep_delta,
                0::numeric(18,2) AS impairment_delta,
                0::numeric(18,2) AS revaluation_reserve_delta,
                COALESCE(a.cost, 0)::numeric(18,2) AS carrying_delta

            FROM {schema}.assets a
            WHERE FALSE
        ),

        subseq_rows AS (
            SELECT
                a.company_id,
                a.id AS asset_id,
                a.asset_code,
                a.asset_name,
                a.asset_class,
                a.category,
                NULL::date AS period_start,
                NULL::date AS period_end,
                sm.event_date AS event_date,

                CASE
                    WHEN sm.event_type = 'add_cost'                  THEN 'subsequent_addition'
                    WHEN sm.event_type = 'impairment_loss'          THEN 'impairment_loss'
                    WHEN sm.event_type = 'impairment_reversal'      THEN 'impairment_reversal'
                    WHEN sm.event_type = 'revaluation'              THEN 'revaluation'
                    WHEN sm.event_type = 'held_for_sale_classify'   THEN 'held_for_sale_transfer_out'
                    WHEN sm.event_type = 'held_for_sale_unclassify' THEN 'held_for_sale_transfer_in'
                    WHEN sm.event_type = 'transfer_ppe_to_ip'       THEN 'transfer_out'
                    WHEN sm.event_type = 'transfer_ip_to_ppe'       THEN 'transfer_in'
                    WHEN sm.event_type = 'change_estimate'          THEN 'estimate_change'
                    ELSE sm.event_type
                END::text AS movement_type,

                'asset_subsequent_measurements'::text AS source_table,
                sm.id::bigint AS source_id,

                a.measurement_basis,
                sm.notes::text AS narrative,

                CASE
                    WHEN sm.event_type = 'add_cost'
                        THEN COALESCE(sm.amount,0)
                    WHEN sm.event_type = 'held_for_sale_unclassify'
                        THEN COALESCE((sm.meta_json->>'cost_delta')::numeric, 0)
                    WHEN sm.event_type = 'transfer_ip_to_ppe'
                        THEN COALESCE((sm.meta_json->>'cost_delta')::numeric, 0)
                    WHEN sm.event_type = 'transfer_ppe_to_ip'
                        THEN -COALESCE((sm.meta_json->>'cost_delta')::numeric, 0)
                    WHEN sm.event_type = 'held_for_sale_classify'
                        THEN -COALESCE((sm.meta_json->>'cost_delta')::numeric, 0)
                    ELSE 0
                END::numeric(18,2) AS cost_delta,

                CASE
                    WHEN sm.event_type = 'held_for_sale_unclassify'
                        THEN COALESCE((sm.meta_json->>'accum_dep_delta')::numeric, 0)
                    WHEN sm.event_type = 'transfer_ip_to_ppe'
                        THEN COALESCE((sm.meta_json->>'accum_dep_delta')::numeric, 0)
                    WHEN sm.event_type = 'transfer_ppe_to_ip'
                        THEN -COALESCE((sm.meta_json->>'accum_dep_delta')::numeric, 0)
                    WHEN sm.event_type = 'held_for_sale_classify'
                        THEN -COALESCE((sm.meta_json->>'accum_dep_delta')::numeric, 0)
                    WHEN sm.event_type = 'revaluation'
                        THEN COALESCE((sm.meta_json->>'accum_dep_delta')::numeric, 0)
                    ELSE 0
                END::numeric(18,2) AS accum_dep_delta,

                CASE
                    WHEN sm.event_type = 'impairment_loss'
                        THEN COALESCE(sm.amount, COALESCE((sm.meta_json->>'impairment_amount')::numeric,0))
                    WHEN sm.event_type = 'impairment_reversal'
                        THEN -COALESCE(sm.amount, COALESCE((sm.meta_json->>'reversal_amount')::numeric,0))
                    WHEN sm.event_type = 'held_for_sale_unclassify'
                        THEN COALESCE((sm.meta_json->>'impairment_delta')::numeric, 0)
                    WHEN sm.event_type = 'transfer_ip_to_ppe'
                        THEN COALESCE((sm.meta_json->>'impairment_delta')::numeric, 0)
                    WHEN sm.event_type = 'transfer_ppe_to_ip'
                        THEN -COALESCE((sm.meta_json->>'impairment_delta')::numeric, 0)
                    WHEN sm.event_type = 'held_for_sale_classify'
                        THEN -COALESCE((sm.meta_json->>'impairment_delta')::numeric, 0)
                    ELSE 0
                END::numeric(18,2) AS impairment_delta,

                CASE
                    WHEN sm.event_type = 'revaluation'
                        THEN COALESCE((sm.meta_json->>'oci_amount')::numeric, 0)
                    ELSE 0
                END::numeric(18,2) AS revaluation_reserve_delta,

                CASE
                    WHEN sm.event_type = 'add_cost'
                        THEN COALESCE(sm.amount,0)
                    WHEN sm.event_type = 'impairment_loss'
                        THEN -COALESCE(sm.amount, COALESCE((sm.meta_json->>'impairment_amount')::numeric,0))
                    WHEN sm.event_type = 'impairment_reversal'
                        THEN COALESCE(sm.amount, COALESCE((sm.meta_json->>'reversal_amount')::numeric,0))
                    WHEN sm.event_type = 'revaluation'
                        THEN COALESCE((sm.meta_json->>'carrying_delta')::numeric, COALESCE(sm.amount,0))
                    WHEN sm.event_type = 'transfer_ppe_to_ip'
                        THEN -COALESCE((sm.meta_json->>'carrying_amount')::numeric, COALESCE(sm.amount,0))
                    WHEN sm.event_type = 'transfer_ip_to_ppe'
                        THEN COALESCE((sm.meta_json->>'carrying_amount')::numeric, COALESCE(sm.amount,0))
                    WHEN sm.event_type = 'held_for_sale_classify'
                        THEN -COALESCE((sm.meta_json->>'carrying_amount')::numeric, COALESCE(sm.amount,0))
                    WHEN sm.event_type = 'held_for_sale_unclassify'
                        THEN COALESCE((sm.meta_json->>'carrying_amount')::numeric, COALESCE(sm.amount,0))
                    ELSE 0
                END::numeric(18,2) AS carrying_delta
            FROM {schema}.asset_subsequent_measurements sm
            JOIN {schema}.assets a
            ON a.id = sm.asset_id
            WHERE COALESCE(sm.status, 'draft') = 'posted'
            AND sm.event_type NOT IN (
                'revaluation',
                'impairment_loss',
                'impairment_reversal'
            )
        ),

        depreciation_rows AS (
            SELECT
                a.company_id,
                a.id AS asset_id,
                a.asset_code,
                a.asset_name,
                a.asset_class,
                a.category,
                d.period_start,
                d.period_end,
                d.period_end AS event_date,

                'depreciation'::text AS movement_type,
                'asset_depreciation'::text AS source_table,
                d.id::bigint AS source_id,

                COALESCE(d.measurement_basis, a.measurement_basis) AS measurement_basis,
                CONCAT('Depreciation ', d.period_start, ' to ', d.period_end)::text AS narrative,

                0::numeric(18,2) AS cost_delta,
                COALESCE(d.depreciation_amount,0)::numeric(18,2) AS accum_dep_delta,
                0::numeric(18,2) AS impairment_delta,
                0::numeric(18,2) AS revaluation_reserve_delta,
                (-COALESCE(d.depreciation_amount,0))::numeric(18,2) AS carrying_delta
                FROM {schema}.asset_depreciation d
                JOIN {schema}.assets a
                ON a.id = d.asset_id
                WHERE d.status = 'posted'
                AND d.posted_journal_id IS NOT NULL
                AND d.period_start IS NOT NULL
                AND d.period_end IS NOT NULL
                ),

        revaluation_rows AS (
            SELECT
                a.company_id,
                a.id AS asset_id,
                a.asset_code,
                a.asset_name,
                a.asset_class,
                a.category,
                NULL::date AS period_start,
                NULL::date AS period_end,
                r.revaluation_date AS event_date,

                CASE
                    WHEN COALESCE(r.revaluation_change,0) >= 0 THEN 'revaluation_up'
                    ELSE 'revaluation_down'
                END::text AS movement_type,

                'asset_revaluations'::text AS source_table,
                r.id::bigint AS source_id,

                a.measurement_basis,
                COALESCE(r.reason, r.notes)::text AS narrative,

                (COALESCE(r.cost_after,0) - COALESCE(r.cost_before,0))::numeric(18,2) AS cost_delta,
                (COALESCE(r.accum_dep_after,0) - COALESCE(r.accum_dep_before,0))::numeric(18,2) AS accum_dep_delta,
                0::numeric(18,2) AS impairment_delta,
                COALESCE(r.oci_revaluation_surplus,0)::numeric(18,2) AS revaluation_reserve_delta,
                COALESCE(r.revaluation_change,0)::numeric(18,2) AS carrying_delta
            FROM {schema}.asset_revaluations r
            JOIN {schema}.assets a
            ON a.id = r.asset_id
            WHERE COALESCE(r.status,'draft') = 'posted'
        ),

        impairment_rows AS (
            SELECT
                a.company_id,
                a.id AS asset_id,
                a.asset_code,
                a.asset_name,
                a.asset_class,
                a.category,
                NULL::date AS period_start,
                NULL::date AS period_end,
                i.impairment_date AS event_date,

                CASE
                    WHEN COALESCE(i.impairment_amount,0) > 0 THEN 'impairment_loss'
                    ELSE 'impairment_reversal'
                END::text AS movement_type,

                'asset_impairments'::text AS source_table,
                i.id::bigint AS source_id,

                a.measurement_basis,
                COALESCE(i.reason, i.notes)::text AS narrative,

                0::numeric(18,2) AS cost_delta,
                0::numeric(18,2) AS accum_dep_delta,
                (
                    COALESCE(i.impairment_amount,0)
                    - COALESCE(i.reversal_amount,0)
                )::numeric(18,2) AS impairment_delta,
                0::numeric(18,2) AS revaluation_reserve_delta,
                (
                    -COALESCE(i.impairment_amount,0)
                    + COALESCE(i.reversal_amount,0)
                )::numeric(18,2) AS carrying_delta
            FROM {schema}.asset_impairments i
            JOIN {schema}.assets a
            ON a.id = i.asset_id
            WHERE COALESCE(i.status,'draft') = 'posted'
        ),

        disposal_rows AS (
            SELECT
                a.company_id,
                a.id AS asset_id,
                a.asset_code,
                a.asset_name,
                a.asset_class,
                a.category,
                NULL::date AS period_start,
                NULL::date AS period_end,
                d.disposal_date AS event_date,

                'disposal'::text AS movement_type,
                'asset_disposals'::text AS source_table,
                d.id::bigint AS source_id,

                a.measurement_basis,
                COALESCE(d.reference, d.notes)::text AS narrative,

                (-COALESCE(d.cost_removed,0))::numeric(18,2) AS cost_delta,
                (-COALESCE(d.accum_dep_removed,0))::numeric(18,2) AS accum_dep_delta,
                (-COALESCE(d.impairment_removed,0))::numeric(18,2) AS impairment_delta,
                0::numeric(18,2) AS revaluation_reserve_delta,
                (-COALESCE(d.carrying_amount,0))::numeric(18,2) AS carrying_delta
            FROM {schema}.asset_disposals d
            JOIN {schema}.assets a
            ON a.id = d.asset_id
            WHERE COALESCE(d.status,'draft') = 'posted'
        ),

        hfs_rows AS (
            SELECT
                a.company_id,
                a.id AS asset_id,
                a.asset_code,
                a.asset_name,
                a.asset_class,
                a.category,
                NULL::date AS period_start,
                NULL::date AS period_end,
                h.classification_date AS event_date,

                'held_for_sale_transfer_out'::text AS movement_type,
                'asset_held_for_sale'::text AS source_table,
                h.id::bigint AS source_id,

                a.measurement_basis,
                NULL::text AS narrative,

                (-COALESCE(h.cost_transferred,0))::numeric(18,2) AS cost_delta,
                (-COALESCE(h.accum_dep_transferred,0))::numeric(18,2) AS accum_dep_delta,
                (
                    COALESCE(h.impairment_on_classification,0)
                    - COALESCE(h.impairment_transferred,0)
                )::numeric(18,2) AS impairment_delta,
                0::numeric(18,2) AS revaluation_reserve_delta,
                (-COALESCE(h.carrying_amount,0))::numeric(18,2) AS carrying_delta
            FROM {schema}.asset_held_for_sale h
            JOIN {schema}.assets a
            ON a.id = h.asset_id
            WHERE COALESCE(h.status,'active') IN ('active','sold')
        ),

        transfer_rows AS (
            SELECT
                a.company_id,
                a.id AS asset_id,
                a.asset_code,
                a.asset_name,
                a.asset_class,
                a.category,
                NULL::date AS period_start,
                NULL::date AS period_end,
                t.transfer_date AS event_date,

                'transfer'::text AS movement_type,
                'asset_transfers'::text AS source_table,
                t.id::bigint AS source_id,

                a.measurement_basis,
                COALESCE(t.reason, t.notes)::text AS narrative,

                0::numeric(18,2) AS cost_delta,
                0::numeric(18,2) AS accum_dep_delta,
                0::numeric(18,2) AS impairment_delta,
                0::numeric(18,2) AS revaluation_reserve_delta,
                0::numeric(18,2) AS carrying_delta
            FROM {schema}.asset_transfers t
            JOIN {schema}.assets a
            ON a.id = t.asset_id
            WHERE COALESCE(t.status,'posted') = 'posted'
        ),

        standard_transfer_rows AS (
            SELECT
                a.company_id,
                a.id AS asset_id,
                a.asset_code,
                a.asset_name,
                a.asset_class,
                a.category,
                NULL::date AS period_start,
                NULL::date AS period_end,
                st.transfer_date AS event_date,

                CASE
                    WHEN UPPER(COALESCE(st.from_standard,'')) = 'IAS16'
                    AND UPPER(COALESCE(st.to_standard,'')) <> 'IAS16'
                        THEN 'transfer_out'
                    WHEN UPPER(COALESCE(st.from_standard,'')) <> 'IAS16'
                    AND UPPER(COALESCE(st.to_standard,'')) = 'IAS16'
                        THEN 'transfer_in'
                    ELSE 'standard_transfer'
                END::text AS movement_type,

                'asset_standard_transfers'::text AS source_table,
                st.id::bigint AS source_id,

                a.measurement_basis,
                COALESCE(st.reason, st.notes)::text AS narrative,

                0::numeric(18,2) AS cost_delta,
                0::numeric(18,2) AS accum_dep_delta,
                0::numeric(18,2) AS impairment_delta,
                COALESCE(st.oci_amount,0)::numeric(18,2) AS revaluation_reserve_delta,

                CASE
                    WHEN UPPER(COALESCE(st.from_standard,'')) = 'IAS16'
                    AND UPPER(COALESCE(st.to_standard,'')) <> 'IAS16'
                        THEN -COALESCE(st.carrying_amount_before,0)
                    WHEN UPPER(COALESCE(st.from_standard,'')) <> 'IAS16'
                    AND UPPER(COALESCE(st.to_standard,'')) = 'IAS16'
                        THEN COALESCE(st.carrying_amount_before,0)
                    ELSE 0
                END::numeric(18,2) AS carrying_delta
            FROM {schema}.asset_standard_transfers st
            JOIN {schema}.assets a
            ON a.id = st.asset_id
            WHERE COALESCE(st.status,'draft') = 'posted'
        ),

        lessor_derecognition_rows AS (
            SELECT
                a.company_id,
                a.id AS asset_id,
                a.asset_code,
                a.asset_name,
                a.asset_class,
                a.category,
                NULL::date AS period_start,
                NULL::date AS period_end,
                j.date AS event_date,

                'disposal'::text AS movement_type,
                'lessor_leases'::text AS source_table,
                ll.id::bigint AS source_id,

                a.measurement_basis,
                CONCAT('Finance lease commencement: ', ll.contract_name)::text AS narrative,

                (-COALESCE(a.cost, 0))::numeric(18,2) AS cost_delta,
                (-COALESCE(a.opening_accum_dep, 0))::numeric(18,2) AS accum_dep_delta,
                (-COALESCE(a.accumulated_impairment, 0))::numeric(18,2) AS impairment_delta,
                0::numeric(18,2) AS revaluation_reserve_delta,

                (-ABS(COALESCE(jl.credit, 0) - COALESCE(jl.debit, 0)))::numeric(18,2)
                    AS carrying_delta

            FROM {schema}.lessor_leases ll
            JOIN {schema}.assets a
              ON a.id = ll.asset_id
             AND a.company_id = ll.company_id
            JOIN {schema}.journal j
              ON j.id = ll.commencement_journal_id
             AND j.company_id = ll.company_id
             AND j.source = 'lessor_lease_commencement'
            LEFT JOIN {schema}.journal_lines jl
              ON jl.journal_id = j.id
             AND jl.account_code = ll.underlying_asset_account_code
            WHERE ll.lease_classification = 'finance'
              AND ll.commencement_journal_id IS NOT NULL
        ),

        reserve_rows AS (
            SELECT
                a.company_id,
                a.id AS asset_id,
                a.asset_code,
                a.asset_name,
                a.asset_class,
                a.category,
                NULL::date AS period_start,
                NULL::date AS period_end,
                rr.event_date AS event_date,

                CONCAT('reserve_', rr.event_type)::text AS movement_type,
                'asset_revaluation_reserve'::text AS source_table,
                rr.id::bigint AS source_id,

                a.measurement_basis,
                rr.notes::text AS narrative,

                0::numeric(18,2) AS cost_delta,
                0::numeric(18,2) AS accum_dep_delta,
                0::numeric(18,2) AS impairment_delta,
                COALESCE(rr.reserve_movement,0)::numeric(18,2) AS revaluation_reserve_delta,
                0::numeric(18,2) AS carrying_delta
            FROM {schema}.asset_revaluation_reserve rr
            JOIN {schema}.assets a
            ON a.id = rr.asset_id
            WHERE COALESCE(rr.status,'draft') = 'posted'
        )

        SELECT m.*
        FROM (
            SELECT * FROM opening_rows
            UNION ALL SELECT * FROM acquisition_rows
            UNION ALL SELECT * FROM fallback_acquisition_rows
            UNION ALL SELECT * FROM subseq_rows
            UNION ALL SELECT * FROM depreciation_rows
            UNION ALL SELECT * FROM revaluation_rows
            UNION ALL SELECT * FROM impairment_rows
            UNION ALL SELECT * FROM disposal_rows
            UNION ALL SELECT * FROM hfs_rows
            UNION ALL SELECT * FROM transfer_rows
            UNION ALL SELECT * FROM standard_transfer_rows
            UNION ALL SELECT * FROM lessor_derecognition_rows
            UNION ALL SELECT * FROM reserve_rows
        ) m
        WHERE EXISTS (
            SELECT 1
            FROM {schema}.assets a
            WHERE a.id = m.asset_id
              AND a.company_id = m.company_id
              AND LOWER(
                    REPLACE(
                        REPLACE(
                            COALESCE(a.accounting_standard, ''),
                            ' ',
                            ''
                        ),
                        '.',
                        ''
                    )
                  ) IN ('ias16', 'ias16ppe')
              AND COALESCE(a.is_component_group, FALSE) = FALSE
        );

        -- =========================================================
        -- PPE DISCLOSURE BY CLASS
        -- =========================================================
        CREATE VIEW {schema}.vw_ppe_disclosure_by_class AS
        SELECT
            m.company_id,
            m.asset_class,
            m.movement_type,

            SUM(COALESCE(m.cost_delta,0))::numeric(18,2)                AS cost_amount,
            SUM(COALESCE(m.accum_dep_delta,0))::numeric(18,2)           AS accum_dep_amount,
            SUM(COALESCE(m.impairment_delta,0))::numeric(18,2)          AS impairment_amount,
            SUM(COALESCE(m.revaluation_reserve_delta,0))::numeric(18,2) AS reserve_amount,
            SUM(COALESCE(m.carrying_delta,0))::numeric(18,2)            AS carrying_amount
        FROM {schema}.vw_ppe_movements m
        GROUP BY
            m.company_id,
            m.asset_class,
            m.movement_type;
        """
        cur.execute(sql)

    def get_ppe_disclosure_by_class(
        self,
        cur,
        company_id: int,
        start_date,
        end_date,
        *,
        asset_classes: list[str] | None = None,
    ):
        """
        Returns IAS 16 PPE rollforward by asset_class for the requested period.
        Opening = all movements before start_date
        Period   = all movements between start_date and end_date
        Closing  = opening + period
        """
        schema = self.company_schema(company_id)
        self.ensure_ppe_reporting_views(cur, company_id)

        ppe_roles = (
            "ppe_cost",
            "ppe_land",
            "ppe_buildings",
            "ppe_plant_machinery",
            "ppe_motor_vehicles",
            "ppe_computer_equipment",
            "ppe_furniture_fittings",
            "ppe_office_equipment",
            "ppe_tools",
            "ppe_construction_equipment",
            "ppe_accumulated_depreciation",
            "accumulated_depreciation_buildings",
            "accumulated_depreciation_motor_vehicles",
            "accumulated_depreciation_computer_equipment",
            "accumulated_depreciation_office_equipment",
            "accumulated_depreciation_office_furniture",
            "accumulated_depreciation_tools",
            "accumulated_depreciation_ppe",
        )

        params = [start_date, end_date]
        class_filter_sql = ""
        if asset_classes:
            class_filter_sql = "WHERE c.asset_class = ANY(%s)"
            params.append(asset_classes)

        sql = f"""
        WITH p AS (
            SELECT %s::date AS start_date, %s::date AS end_date
        ),
        opening AS (
            SELECT
                m.asset_class,
                SUM(m.cost_delta)::numeric(18,2)                AS opening_cost,
                SUM(m.accum_dep_delta)::numeric(18,2)           AS opening_accum_dep,
                SUM(m.impairment_delta)::numeric(18,2)          AS opening_impairment,
                SUM(m.revaluation_reserve_delta)::numeric(18,2) AS opening_reserve,
                SUM(m.carrying_delta)::numeric(18,2)            AS opening_carrying
            FROM {schema}.vw_ppe_movements m
            CROSS JOIN p
            WHERE m.event_date < p.start_date
            GROUP BY m.asset_class
        ),
        period_mov AS (
            SELECT
                m.asset_class,

                SUM(CASE WHEN m.movement_type = 'addition' THEN m.cost_delta ELSE 0 END)::numeric(18,2)                 AS additions_cost,
                SUM(CASE WHEN m.movement_type = 'subsequent_addition' THEN m.cost_delta ELSE 0 END)::numeric(18,2)      AS subsequent_additions_cost,

                SUM(CASE WHEN m.movement_type IN ('transfer_in','held_for_sale_transfer_in') THEN m.cost_delta ELSE 0 END)::numeric(18,2)  AS transfers_in_cost,
                SUM(CASE WHEN m.movement_type IN ('transfer_out','held_for_sale_transfer_out') THEN m.cost_delta ELSE 0 END)::numeric(18,2) AS transfers_out_cost,
                SUM(CASE WHEN m.movement_type = 'disposal' THEN m.cost_delta ELSE 0 END)::numeric(18,2) AS disposals_cost,
                SUM(CASE WHEN m.movement_type IN ('revaluation_up','revaluation_down') THEN m.cost_delta ELSE 0 END)::numeric(18,2) AS revaluation_cost_delta,

                SUM(CASE WHEN m.movement_type = 'depreciation' THEN m.accum_dep_delta ELSE 0 END)::numeric(18,2) AS depreciation_charge,
                SUM(CASE WHEN m.movement_type IN ('transfer_in','held_for_sale_transfer_in') THEN m.accum_dep_delta ELSE 0 END)::numeric(18,2)  AS transfers_in_accum_dep,
                SUM(CASE WHEN m.movement_type IN ('transfer_out','held_for_sale_transfer_out') THEN m.accum_dep_delta ELSE 0 END)::numeric(18,2) AS transfers_out_accum_dep,
                SUM(CASE WHEN m.movement_type = 'disposal' THEN m.accum_dep_delta ELSE 0 END)::numeric(18,2) AS disposals_accum_dep,
                SUM(CASE WHEN m.movement_type IN ('revaluation_up','revaluation_down') THEN m.accum_dep_delta ELSE 0 END)::numeric(18,2) AS revaluation_accum_dep_delta,

                SUM(CASE WHEN m.movement_type = 'impairment_loss' THEN m.impairment_delta ELSE 0 END)::numeric(18,2) AS impairment_losses,
                SUM(CASE WHEN m.movement_type = 'impairment_reversal' THEN -m.impairment_delta ELSE 0 END)::numeric(18,2) AS impairment_reversals,
                SUM(CASE WHEN m.movement_type IN ('transfer_in','held_for_sale_transfer_in') THEN m.impairment_delta ELSE 0 END)::numeric(18,2)  AS transfers_in_impairment,
                SUM(CASE WHEN m.movement_type IN ('transfer_out','held_for_sale_transfer_out') THEN m.impairment_delta ELSE 0 END)::numeric(18,2) AS transfers_out_impairment,
                SUM(CASE WHEN m.movement_type = 'disposal' THEN m.impairment_delta ELSE 0 END)::numeric(18,2) AS disposals_impairment,

                SUM(CASE WHEN m.movement_type = 'revaluation_up' THEN m.carrying_delta ELSE 0 END)::numeric(18,2) AS revaluation_upward,
                SUM(CASE WHEN m.movement_type = 'revaluation_down' THEN m.carrying_delta ELSE 0 END)::numeric(18,2) AS revaluation_downward,

                SUM(CASE WHEN m.movement_type IN ('transfer_in','held_for_sale_transfer_in') THEN m.carrying_delta ELSE 0 END)::numeric(18,2)  AS transfers_in_carrying,
                SUM(CASE WHEN m.movement_type IN ('transfer_out','held_for_sale_transfer_out') THEN m.carrying_delta ELSE 0 END)::numeric(18,2) AS transfers_out_carrying,
                SUM(CASE WHEN m.movement_type = 'disposal' THEN m.carrying_delta ELSE 0 END)::numeric(18,2) AS disposals_carrying,

                SUM(m.cost_delta)::numeric(18,2)                AS period_cost_delta,
                SUM(m.accum_dep_delta)::numeric(18,2)           AS period_accum_dep_delta,
                SUM(m.impairment_delta)::numeric(18,2)          AS period_impairment_delta,
                SUM(m.revaluation_reserve_delta)::numeric(18,2) AS period_reserve_delta,
                SUM(m.carrying_delta)::numeric(18,2)            AS period_carrying_delta

            FROM {schema}.vw_ppe_movements m
            CROSS JOIN p
            WHERE
            (
                m.movement_type <> 'depreciation'
                AND m.event_date BETWEEN p.start_date AND p.end_date
            )
            OR
            (
                m.movement_type = 'depreciation'
                AND m.period_end >= p.start_date
                AND m.period_start <= p.end_date
            )
            GROUP BY m.asset_class
        ),
        classes AS (
            SELECT DISTINCT asset_class
            FROM (
                SELECT asset_class FROM opening
                UNION
                SELECT asset_class FROM period_mov
            ) x
            WHERE NULLIF(TRIM(asset_class), '') IS NOT NULL
        )
        SELECT
            c.asset_class,

            COALESCE(o.opening_cost,0)::numeric(18,2)         AS opening_cost,
            COALESCE(o.opening_accum_dep,0)::numeric(18,2)    AS opening_accum_dep,
            COALESCE(o.opening_impairment,0)::numeric(18,2)   AS opening_impairment,
            COALESCE(o.opening_reserve,0)::numeric(18,2)      AS opening_reserve,
            COALESCE(o.opening_carrying,0)::numeric(18,2)     AS opening_carrying,

            COALESCE(pm.additions_cost,0)::numeric(18,2)              AS additions_cost,
            COALESCE(pm.subsequent_additions_cost,0)::numeric(18,2)   AS subsequent_additions_cost,
            COALESCE(pm.revaluation_cost_delta,0)::numeric(18,2)      AS revaluation_cost_delta,
            COALESCE(pm.transfers_in_cost,0)::numeric(18,2)           AS transfers_in_cost,
            COALESCE(pm.transfers_out_cost,0)::numeric(18,2)          AS transfers_out_cost,
            COALESCE(pm.disposals_cost,0)::numeric(18,2)              AS disposals_cost,

            COALESCE(pm.depreciation_charge,0)::numeric(18,2)         AS depreciation_charge,
            COALESCE(pm.revaluation_accum_dep_delta,0)::numeric(18,2) AS revaluation_accum_dep_delta,
            COALESCE(pm.transfers_in_accum_dep,0)::numeric(18,2)      AS transfers_in_accum_dep,
            COALESCE(pm.transfers_out_accum_dep,0)::numeric(18,2)     AS transfers_out_accum_dep,
            COALESCE(pm.disposals_accum_dep,0)::numeric(18,2)         AS disposals_accum_dep,

            COALESCE(pm.impairment_losses,0)::numeric(18,2)           AS impairment_losses,
            COALESCE(pm.impairment_reversals,0)::numeric(18,2)        AS impairment_reversals,
            COALESCE(pm.transfers_in_impairment,0)::numeric(18,2)     AS transfers_in_impairment,
            COALESCE(pm.transfers_out_impairment,0)::numeric(18,2)    AS transfers_out_impairment,
            COALESCE(pm.disposals_impairment,0)::numeric(18,2)        AS disposals_impairment,

            COALESCE(pm.revaluation_upward,0)::numeric(18,2)          AS revaluation_upward,
            COALESCE(pm.revaluation_downward,0)::numeric(18,2)        AS revaluation_downward,
            COALESCE(pm.transfers_in_carrying,0)::numeric(18,2)       AS transfers_in_carrying,
            COALESCE(pm.transfers_out_carrying,0)::numeric(18,2)      AS transfers_out_carrying,
            COALESCE(pm.disposals_carrying,0)::numeric(18,2)          AS disposals_carrying,

            (COALESCE(o.opening_cost,0) + COALESCE(pm.period_cost_delta,0))::numeric(18,2)            AS closing_cost,
            (COALESCE(o.opening_accum_dep,0) + COALESCE(pm.period_accum_dep_delta,0))::numeric(18,2)  AS closing_accum_dep,
            (COALESCE(o.opening_impairment,0) + COALESCE(pm.period_impairment_delta,0))::numeric(18,2)AS closing_impairment,
            (COALESCE(o.opening_reserve,0) + COALESCE(pm.period_reserve_delta,0))::numeric(18,2)      AS closing_reserve,
            (COALESCE(o.opening_carrying,0) + COALESCE(pm.period_carrying_delta,0))::numeric(18,2)    AS closing_carrying

        FROM classes c
        LEFT JOIN opening o
        ON o.asset_class = c.asset_class
        LEFT JOIN period_mov pm
        ON pm.asset_class = c.asset_class
        {class_filter_sql}
        ORDER BY c.asset_class;
        """

        cur.execute(sql, params)
        rows = cur.fetchall()

        out = []
        for row in rows:
            if isinstance(row, dict):
                out.append(dict(row))  # already a dict → keep as-is
            else:
                cols = [d[0] for d in cur.description]
                out.append(dict(zip(cols, row)))  # tuple → map properly

        return out

    # ─── IAS 40 Investment Property ────────────────────────────────

    def get_ip_disclosure_by_class(
        self, cur, company_id: int, start_date, end_date, *, asset_classes: list[str] | None = None,
    ):
        schema = self.company_schema(company_id)
        self.ensure_ppe_reporting_views(cur, company_id)

        params = [start_date, end_date, company_id]
        class_filter_sql = ""
        if asset_classes:
            class_filter_sql = "WHERE c.asset_class = ANY(%s)"
            params.append(asset_classes)

        sql = f"""
        WITH p AS (SELECT %s::date AS start_date, %s::date AS end_date),
        ip_assets AS (
            SELECT id, asset_class, category
            FROM {schema}.assets
            WHERE company_id = %s AND UPPER(COALESCE(accounting_standard, '')) = 'IAS40'
        ),
        opening AS (
            SELECT a.asset_class,
                SUM(m.cost_delta)::numeric(18,2) AS opening_cost,
                SUM(m.accum_dep_delta)::numeric(18,2) AS opening_accum_dep,
                SUM(m.impairment_delta)::numeric(18,2) AS opening_impairment,
                SUM(m.revaluation_reserve_delta)::numeric(18,2) AS opening_reserve,
                SUM(m.carrying_delta)::numeric(18,2) AS opening_carrying
            FROM {schema}.vw_ppe_movements m
            JOIN ip_assets a ON a.id = m.asset_id CROSS JOIN p
            WHERE m.event_date < p.start_date
            GROUP BY a.asset_class
        ),
        period_mov AS (
            SELECT a.asset_class,
                SUM(CASE WHEN m.movement_type = 'addition' THEN m.cost_delta ELSE 0 END)::numeric(18,2) AS additions_cost,
                SUM(CASE WHEN m.movement_type = 'subsequent_addition' THEN m.cost_delta ELSE 0 END)::numeric(18,2) AS subsequent_additions_cost,
                SUM(CASE WHEN m.movement_type IN ('transfer_in','held_for_sale_transfer_in') THEN m.cost_delta ELSE 0 END)::numeric(18,2) AS transfers_in_cost,
                SUM(CASE WHEN m.movement_type IN ('transfer_out','held_for_sale_transfer_out') THEN m.cost_delta ELSE 0 END)::numeric(18,2) AS transfers_out_cost,
                SUM(CASE WHEN m.movement_type = 'disposal' THEN m.cost_delta ELSE 0 END)::numeric(18,2) AS disposals_cost,
                SUM(CASE WHEN m.movement_type IN ('revaluation_up','revaluation_down') THEN m.cost_delta ELSE 0 END)::numeric(18,2) AS revaluation_cost_delta,
                SUM(CASE WHEN m.movement_type = 'depreciation' THEN m.accum_dep_delta ELSE 0 END)::numeric(18,2) AS depreciation_charge,
                SUM(CASE WHEN m.movement_type IN ('transfer_in','held_for_sale_transfer_in') THEN m.accum_dep_delta ELSE 0 END)::numeric(18,2) AS transfers_in_accum_dep,
                SUM(CASE WHEN m.movement_type IN ('transfer_out','held_for_sale_transfer_out') THEN m.accum_dep_delta ELSE 0 END)::numeric(18,2) AS transfers_out_accum_dep,
                SUM(CASE WHEN m.movement_type = 'disposal' THEN m.accum_dep_delta ELSE 0 END)::numeric(18,2) AS disposals_accum_dep,
                SUM(CASE WHEN m.movement_type IN ('revaluation_up','revaluation_down') THEN m.accum_dep_delta ELSE 0 END)::numeric(18,2) AS revaluation_accum_dep_delta,
                SUM(CASE WHEN m.movement_type = 'impairment_loss' THEN m.impairment_delta ELSE 0 END)::numeric(18,2) AS impairment_losses,
                SUM(CASE WHEN m.movement_type = 'impairment_reversal' THEN -m.impairment_delta ELSE 0 END)::numeric(18,2) AS impairment_reversals,
                SUM(CASE WHEN m.movement_type IN ('transfer_in','held_for_sale_transfer_in') THEN m.impairment_delta ELSE 0 END)::numeric(18,2) AS transfers_in_impairment,
                SUM(CASE WHEN m.movement_type IN ('transfer_out','held_for_sale_transfer_out') THEN m.impairment_delta ELSE 0 END)::numeric(18,2) AS transfers_out_impairment,
                SUM(CASE WHEN m.movement_type = 'disposal' THEN m.impairment_delta ELSE 0 END)::numeric(18,2) AS disposals_impairment,
                SUM(CASE WHEN m.movement_type = 'revaluation_up' THEN m.carrying_delta ELSE 0 END)::numeric(18,2) AS revaluation_upward,
                SUM(CASE WHEN m.movement_type = 'revaluation_down' THEN m.carrying_delta ELSE 0 END)::numeric(18,2) AS revaluation_downward,
                SUM(CASE WHEN m.movement_type IN ('transfer_in','held_for_sale_transfer_in') THEN m.carrying_delta ELSE 0 END)::numeric(18,2) AS transfers_in_carrying,
                SUM(CASE WHEN m.movement_type IN ('transfer_out','held_for_sale_transfer_out') THEN m.carrying_delta ELSE 0 END)::numeric(18,2) AS transfers_out_carrying,
                SUM(CASE WHEN m.movement_type = 'disposal' THEN m.carrying_delta ELSE 0 END)::numeric(18,2) AS disposals_carrying,
                SUM(m.cost_delta)::numeric(18,2) AS period_cost_delta,
                SUM(m.accum_dep_delta)::numeric(18,2) AS period_accum_dep_delta,
                SUM(m.impairment_delta)::numeric(18,2) AS period_impairment_delta,
                SUM(m.revaluation_reserve_delta)::numeric(18,2) AS period_reserve_delta,
                SUM(m.carrying_delta)::numeric(18,2) AS period_carrying_delta
            FROM {schema}.vw_ppe_movements m
            JOIN ip_assets a ON a.id = m.asset_id CROSS JOIN p
            WHERE (m.movement_type <> 'depreciation' AND m.event_date BETWEEN p.start_date AND p.end_date)
               OR (m.movement_type = 'depreciation' AND m.period_end >= p.start_date AND m.period_start <= p.end_date)
            GROUP BY a.asset_class
        ),
        classes AS (
            SELECT asset_class FROM opening UNION
            SELECT asset_class FROM period_mov UNION
            SELECT DISTINCT asset_class FROM ip_assets
        )
        SELECT c.asset_class,
            COALESCE(o.opening_cost,0)::numeric(18,2) AS opening_cost,
            COALESCE(o.opening_accum_dep,0)::numeric(18,2) AS opening_accum_dep,
            COALESCE(o.opening_impairment,0)::numeric(18,2) AS opening_impairment,
            COALESCE(o.opening_reserve,0)::numeric(18,2) AS opening_reserve,
            COALESCE(o.opening_carrying,0)::numeric(18,2) AS opening_carrying,
            COALESCE(pm.additions_cost,0)::numeric(18,2) AS additions_cost,
            COALESCE(pm.subsequent_additions_cost,0)::numeric(18,2) AS subsequent_additions_cost,
            COALESCE(pm.revaluation_cost_delta,0)::numeric(18,2) AS revaluation_cost_delta,
            COALESCE(pm.transfers_in_cost,0)::numeric(18,2) AS transfers_in_cost,
            COALESCE(pm.transfers_out_cost,0)::numeric(18,2) AS transfers_out_cost,
            COALESCE(pm.disposals_cost,0)::numeric(18,2) AS disposals_cost,
            COALESCE(pm.depreciation_charge,0)::numeric(18,2) AS depreciation_charge,
            COALESCE(pm.revaluation_accum_dep_delta,0)::numeric(18,2) AS revaluation_accum_dep_delta,
            COALESCE(pm.transfers_in_accum_dep,0)::numeric(18,2) AS transfers_in_accum_dep,
            COALESCE(pm.transfers_out_accum_dep,0)::numeric(18,2) AS transfers_out_accum_dep,
            COALESCE(pm.disposals_accum_dep,0)::numeric(18,2) AS disposals_accum_dep,
            COALESCE(pm.impairment_losses,0)::numeric(18,2) AS impairment_losses,
            COALESCE(pm.impairment_reversals,0)::numeric(18,2) AS impairment_reversals,
            COALESCE(pm.transfers_in_impairment,0)::numeric(18,2) AS transfers_in_impairment,
            COALESCE(pm.transfers_out_impairment,0)::numeric(18,2) AS transfers_out_impairment,
            COALESCE(pm.disposals_impairment,0)::numeric(18,2) AS disposals_impairment,
            COALESCE(pm.revaluation_upward,0)::numeric(18,2) AS revaluation_upward,
            COALESCE(pm.revaluation_downward,0)::numeric(18,2) AS revaluation_downward,
            COALESCE(pm.transfers_in_carrying,0)::numeric(18,2) AS transfers_in_carrying,
            COALESCE(pm.transfers_out_carrying,0)::numeric(18,2) AS transfers_out_carrying,
            COALESCE(pm.disposals_carrying,0)::numeric(18,2) AS disposals_carrying,
            (COALESCE(o.opening_cost,0)+COALESCE(pm.period_cost_delta,0))::numeric(18,2) AS closing_cost,
            (COALESCE(o.opening_accum_dep,0)+COALESCE(pm.period_accum_dep_delta,0))::numeric(18,2) AS closing_accum_dep,
            (COALESCE(o.opening_impairment,0)+COALESCE(pm.period_impairment_delta,0))::numeric(18,2) AS closing_impairment,
            (COALESCE(o.opening_reserve,0)+COALESCE(pm.period_reserve_delta,0))::numeric(18,2) AS closing_reserve,
            (COALESCE(o.opening_carrying,0)+COALESCE(pm.period_carrying_delta,0))::numeric(18,2) AS closing_carrying
        FROM classes c
        LEFT JOIN opening o ON o.asset_class = c.asset_class
        LEFT JOIN period_mov pm ON pm.asset_class = c.asset_class
        {class_filter_sql}
        ORDER BY c.asset_class"""
        cur.execute(sql, params)
        rows = cur.fetchall()
        out = []
        for row in rows:
            if isinstance(row, dict):
                out.append(dict(row))
            else:
                cols = [d[0] for d in cur.description]
                out.append(dict(zip(cols, row)))
        return out
    
