    def list_engagement_deliverables(
        self,
        cur,
        company_id: int,
        *,
        engagement_id: int,
        status: str = "",
        priority: str = "",
        assigned_user_id: int = None,
        reviewer_user_id: int = None,
        deliverable_type: str = "",
        q: str = "",
        active_only: bool = True,
        limit: int = 200,
        offset: int = 0,
    ):
        schema = self.company_schema(company_id)

        where = ["d.company_id = %s", "d.engagement_id = %s"]
        params = [company_id, engagement_id]

        if status:
            where.append("LOWER(d.status) = LOWER(%s)")
            params.append(status)

        if priority:
            where.append("LOWER(d.priority) = LOWER(%s)")
            params.append(priority)

        if assigned_user_id:
            where.append("d.assigned_user_id = %s")
            params.append(assigned_user_id)

        if reviewer_user_id:
            where.append("d.reviewer_user_id = %s")
            params.append(reviewer_user_id)

        if deliverable_type:
            where.append("LOWER(COALESCE(d.deliverable_type, '')) = LOWER(%s)")
            params.append(deliverable_type)

        if active_only:
            where.append("d.is_active = TRUE")

        if q:
            where.append("""
                (
                    d.deliverable_name ILIKE %s
                    OR COALESCE(d.deliverable_code, '') ILIKE %s
                    OR COALESCE(d.requested_from, '') ILIKE %s
                    OR COALESCE(d.notes, '') ILIKE %s
                )
            """)
            like = f"%{q.strip()}%"
            params.extend([like, like, like, like])

        sql = f"""
            SELECT
                d.*,
                e.engagement_name,
                e.engagement_code,
                e.engagement_type,
                e.target_company_id,

                assigned_u.first_name AS assigned_first_name,
                assigned_u.last_name AS assigned_last_name,
                assigned_u.email AS assigned_email,
                COALESCE(assigned_cu.assignment_role, assigned_cu.role, assigned_u.user_role) AS assigned_role,

                reviewer_u.first_name AS reviewer_first_name,
                reviewer_u.last_name AS reviewer_last_name,
                reviewer_u.email AS reviewer_email,
                COALESCE(reviewer_cu.assignment_role, reviewer_cu.role, reviewer_u.user_role) AS reviewer_role

            FROM {schema}.engagement_deliverables d
            JOIN {schema}.engagements e
            ON e.id = d.engagement_id
            AND e.company_id = d.company_id

            LEFT JOIN public.users assigned_u
            ON assigned_u.id = d.assigned_user_id
            LEFT JOIN public.company_users assigned_cu
            ON assigned_cu.company_id = d.company_id
            AND assigned_cu.user_id = d.assigned_user_id

            LEFT JOIN public.users reviewer_u
            ON reviewer_u.id = d.reviewer_user_id
            LEFT JOIN public.company_users reviewer_cu
            ON reviewer_cu.company_id = d.company_id
            AND reviewer_cu.user_id = d.reviewer_user_id

            WHERE {" AND ".join(where)}
            ORDER BY
                d.due_date NULLS LAST,
                d.priority DESC,
                d.id DESC
            LIMIT %s OFFSET %s
        """
        params.extend([limit, offset])
        cur.execute(sql, tuple(params))
        return cur.fetchall()

