    def list_practitioner_posting_module_filter_options(
        self,
        cur,
        company_id: int,
        *,
        engagement_id: int,
        module_name: str,
    ):
        schema = self.company_schema(company_id)

        sql = f"""
            WITH scoped_activity AS (
                SELECT *
                FROM {schema}.engagement_posting_activity
                WHERE company_id = %s
                AND engagement_id = %s
                AND is_active = TRUE
                AND module_name = %s
            )
            SELECT
                ARRAY(
                    SELECT DISTINCT LOWER(status)
                    FROM scoped_activity
                    WHERE status IS NOT NULL AND BTRIM(status) <> ''
                    ORDER BY LOWER(status)
                ) AS statuses,

                ARRAY(
                    SELECT DISTINCT LOWER(event_type)
                    FROM scoped_activity
                    WHERE event_type IS NOT NULL AND BTRIM(event_type) <> ''
                    ORDER BY LOWER(event_type)
                ) AS event_types
        """

        cur.execute(sql, (company_id, engagement_id, module_name))
        base = cur.fetchone() or {}

        users_sql = f"""
            WITH scoped_activity AS (
                SELECT *
                FROM {schema}.engagement_posting_activity
                WHERE company_id = %s
                AND engagement_id = %s
                AND is_active = TRUE
                AND module_name = %s
            )
            SELECT
                'prepared'::text AS role_type,
                u.id AS user_id,
                CONCAT(
                    COALESCE(u.first_name, ''),
                    CASE
                        WHEN u.last_name IS NOT NULL AND u.last_name <> '' THEN ' ' || u.last_name
                        ELSE ''
                    END
                ) AS user_name
            FROM scoped_activity pa
            JOIN public.users u
            ON u.id = pa.prepared_by_user_id

            UNION

            SELECT
                'reviewer'::text AS role_type,
                u.id AS user_id,
                CONCAT(
                    COALESCE(u.first_name, ''),
                    CASE
                        WHEN u.last_name IS NOT NULL AND u.last_name <> '' THEN ' ' || u.last_name
                        ELSE ''
                    END
                ) AS user_name
            FROM scoped_activity pa
            JOIN public.users u
            ON u.id = pa.reviewer_user_id

            ORDER BY role_type, user_name
        """
        cur.execute(users_sql, (company_id, engagement_id, module_name))
        user_rows = cur.fetchall() or []

        prepared_by = []
        reviewers = []

        for row in user_rows:
            item = {
                "user_id": row.get("user_id"),
                "user_name": row.get("user_name") or "",
            }
            if row.get("role_type") == "prepared":
                if item not in prepared_by:
                    prepared_by.append(item)
            elif row.get("role_type") == "reviewer":
                if item not in reviewers:
                    reviewers.append(item)

        return {
            "statuses": base.get("statuses") or [],
            "event_types": base.get("event_types") or [],
            "prepared_by_users": prepared_by,
            "reviewer_users": reviewers,
        }

    def get_review_queue_summary(
        self,
        cur,
        company_id: int,
        *,
        customer_id: int = None,
        engagement_id: int = None,
        current_user_id: int = None,
    ):
        schema = self.company_schema(company_id)

        sql = f"""
            WITH engagement_scope AS (
                SELECT e.id
                FROM {schema}.engagements e
                WHERE e.company_id = %s
                AND e.is_active = TRUE
                AND (%s IS NULL OR e.customer_id = %s)
                AND (%s IS NULL OR e.id = %s)
            ),
            queue_union AS (
                SELECT
                    'reporting_item'::text AS queue_type,
                    i.id AS source_id,
                    i.engagement_id,
                    i.status,
                    i.priority,
                    i.due_date,
                    i.owner_user_id AS assigned_user_id,
                    i.reviewer_user_id,
                    (
                        i.due_date IS NOT NULL
                        AND i.due_date < CURRENT_DATE
                        AND i.status NOT IN ('approved', 'completed', 'waived')
                    ) AS is_overdue,
                    (i.status = 'blocked') AS is_blocked,
                    (
                        %s IS NOT NULL
                        AND (
                            i.owner_user_id = %s
                            OR i.reviewer_user_id = %s
                        )
                    ) AS is_mine
                FROM {schema}.engagement_reporting_items i
                JOIN engagement_scope es ON es.id = i.engagement_id
                WHERE i.company_id = %s
                AND i.is_active = TRUE

                UNION ALL

                SELECT
                    'deliverable'::text,
                    d.id,
                    d.engagement_id,
                    d.status,
                    d.priority,
                    d.due_date,
                    d.assigned_user_id,
                    d.reviewer_user_id,
                    (
                        d.due_date IS NOT NULL
                        AND d.due_date < CURRENT_DATE
                        AND d.status NOT IN ('completed', 'waived', 'received')
                    ) AS is_overdue,
                    FALSE AS is_blocked,
                    (
                        %s IS NOT NULL
                        AND (
                            d.assigned_user_id = %s
                            OR d.reviewer_user_id = %s
                        )
                    ) AS is_mine
                FROM {schema}.engagement_deliverables d
                JOIN engagement_scope es ON es.id = d.engagement_id
                WHERE d.company_id = %s
                AND d.is_active = TRUE

                UNION ALL

                SELECT
                    'posting_activity'::text,
                    p.id,
                    p.engagement_id,
                    p.status,
                    'normal'::text AS priority,
                    p.posting_date AS due_date,
                    p.prepared_by_user_id AS assigned_user_id,
                    p.reviewer_user_id,
                    (
                        p.posting_date IS NOT NULL
                        AND p.posting_date < CURRENT_DATE
                        AND p.status NOT IN ('approved', 'posted', 'reversed')
                    ) AS is_overdue,
                    FALSE AS is_blocked,
                    (
                        %s IS NOT NULL
                        AND (
                            p.prepared_by_user_id = %s
                            OR p.reviewer_user_id = %s
                        )
                    ) AS is_mine
                FROM {schema}.engagement_posting_activity p
                JOIN engagement_scope es ON es.id = p.engagement_id
                WHERE p.company_id = %s
                AND p.is_active = TRUE

                UNION ALL

                SELECT
                    'monthly_close'::text,
                    m.id,
                    m.engagement_id,
                    m.status,
                    m.priority,
                    m.due_date,
                    m.owner_user_id AS assigned_user_id,
                    m.reviewer_user_id,
                    (
                        m.due_date IS NOT NULL
                        AND m.due_date < CURRENT_DATE
                        AND m.status NOT IN ('completed', 'skipped')
                    ) AS is_overdue,
                    (m.status = 'blocked') AS is_blocked,
                    (
                        %s IS NOT NULL
                        AND (
                            m.owner_user_id = %s
                            OR m.reviewer_user_id = %s
                        )
                    ) AS is_mine
                FROM {schema}.engagement_monthly_close_tasks m
                JOIN engagement_scope es ON es.id = m.engagement_id
                WHERE m.company_id = %s
                AND m.is_active = TRUE

                UNION ALL

                SELECT
                    'year_end'::text,
                    y.id,
                    y.engagement_id,
                    y.status,
                    y.priority,
                    y.due_date,
                    y.owner_user_id AS assigned_user_id,
                    y.reviewer_user_id,
                    (
                        y.due_date IS NOT NULL
                        AND y.due_date < CURRENT_DATE
                        AND y.status NOT IN ('completed', 'waived')
                    ) AS is_overdue,
                    (y.status = 'blocked') AS is_blocked,
                    (
                        %s IS NOT NULL
                        AND (
                            y.owner_user_id = %s
                            OR y.reviewer_user_id = %s
                        )
                    ) AS is_mine
                FROM {schema}.engagement_year_end_tasks y
                JOIN engagement_scope es ON es.id = y.engagement_id
                WHERE y.company_id = %s
                AND y.is_active = TRUE

                UNION ALL

                SELECT
                    'signoff'::text,
                    s.id,
                    s.engagement_id,
                    s.status,
                    'high'::text AS priority,
                    s.due_date,
                    s.assigned_user_id,
                    NULL::int AS reviewer_user_id,
                    (
                        s.due_date IS NOT NULL
                        AND s.due_date < CURRENT_DATE
                        AND s.status NOT IN ('completed', 'waived')
                    ) AS is_overdue,
                    (s.status = 'blocked') AS is_blocked,
                    (
                        %s IS NOT NULL
                        AND s.assigned_user_id = %s
                    ) AS is_mine
                FROM {schema}.engagement_signoff_steps s
                JOIN engagement_scope es ON es.id = s.engagement_id
                WHERE s.company_id = %s
                AND s.is_active = TRUE
            )
            SELECT
                COUNT(*) AS total_items,
                COUNT(*) FILTER (
                    WHERE status IN ('ready', 'in_review', 'pending_review', 'in_progress', 'not_started')
                ) AS awaiting_review,
                COUNT(*) FILTER (WHERE is_overdue = TRUE) AS overdue_items,
                COUNT(*) FILTER (WHERE is_blocked = TRUE) AS blocked_items,
                COUNT(*) FILTER (
                    WHERE queue_type = 'signoff'
                    AND status NOT IN ('completed', 'waived')
                ) AS pending_signoffs,
                COUNT(*) FILTER (WHERE is_mine = TRUE) AS my_queue
            FROM queue_union
        """

        params = (
            company_id, customer_id, customer_id, engagement_id, engagement_id,

            current_user_id, current_user_id, current_user_id, company_id,
            current_user_id, current_user_id, current_user_id, company_id,
            current_user_id, current_user_id, current_user_id, company_id,
            current_user_id, current_user_id, current_user_id, company_id,
            current_user_id, current_user_id, current_user_id, company_id,
            current_user_id, current_user_id, company_id,
        )

        cur.execute(sql, params)
        return cur.fetchone()

