    def get_engagement_escalation(
        self,
        cur,
        company_id: int,
        *,
        escalation_id: int,
    ):
        schema = self.company_schema(company_id)

        sql = f"""
            SELECT
                e.*,
                eng.engagement_name,
                eng.engagement_code,
                eng.customer_id,
                c.name AS customer_name,

                CONCAT(
                    COALESCE(ru.first_name, ''),
                    CASE
                        WHEN COALESCE(ru.last_name, '') <> '' THEN ' ' || ru.last_name
                        ELSE ''
                    END
                ) AS raised_by_user_name,

                CONCAT(
                    COALESCE(au.first_name, ''),
                    CASE
                        WHEN COALESCE(au.last_name, '') <> '' THEN ' ' || au.last_name
                        ELSE ''
                    END
                ) AS assigned_to_user_name
            FROM {schema}.engagement_escalations e
            JOIN {schema}.engagements eng
            ON eng.id = e.engagement_id
            AND eng.company_id = e.company_id
            LEFT JOIN {schema}.customers c
            ON c.id = eng.customer_id
            AND c.company_id = eng.company_id
            LEFT JOIN public.users ru
            ON ru.id = e.raised_by_user_id
            LEFT JOIN public.users au
            ON au.id = e.assigned_to_user_id
            WHERE e.company_id = %s
            AND e.id = %s
            LIMIT 1
        """
        cur.execute(sql, (company_id, escalation_id))
        return cur.fetchone()

    def create_engagement_escalation(
        self,
        cur,
        company_id: int,
        *,
        engagement_id: int,
        source_type: str,
        source_id: int = None,
        escalation_type: str,
        severity: str = "medium",
        title: str = "",
        description: str = "",
        status: str = "open",
        raised_by_user_id: int = None,
        assigned_to_user_id: int = None,
        due_date=None,
        created_by_user_id: int = None,
    ):
        schema = self.company_schema(company_id)

        cur.execute(
            f"""
            INSERT INTO {schema}.engagement_escalations (
                company_id,
                engagement_id,
                source_type,
                source_id,
                escalation_type,
                severity,
                title,
                description,
                status,
                raised_by_user_id,
                assigned_to_user_id,
                due_date,
                created_by_user_id,
                updated_by_user_id,
                is_active
            )
            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, TRUE)
            RETURNING id
            """,
            (
                company_id,
                engagement_id,
                source_type,
                source_id,
                escalation_type,
                severity,
                title or None,
                description or None,
                status,
                raised_by_user_id,
                assigned_to_user_id,
                due_date,
                created_by_user_id,
                created_by_user_id,
            ),
        )
        row = cur.fetchone()
        return row["id"] if isinstance(row, dict) else row[0]

    def deactivate_engagement_escalation(
        self,
        cur,
        company_id: int,
        *,
        escalation_id: int,
        updated_by_user_id: int = None,
    ):
        schema = self.company_schema(company_id)

        cur.execute(
            f"""
            UPDATE {schema}.engagement_escalations
            SET
                is_active = FALSE,
                updated_by_user_id = COALESCE(%s, updated_by_user_id)
            WHERE company_id = %s
            AND id = %s
            AND is_active = TRUE
            """,
            (updated_by_user_id, company_id, escalation_id),
        )
        return cur.rowcount

    def backfill_overdue_working_paper_escalations(self, cur, company_id: int):
        schema = self.company_schema(company_id)

        cur.execute(
            f"""
            INSERT INTO {schema}.engagement_escalations (
                company_id,
                engagement_id,
                source_type,
                source_id,
                escalation_type,
                severity,
                title,
                description,
                status,
                raised_by_user_id,
                assigned_to_user_id,
                due_date,
                is_active,
                created_at,
                updated_at
            )
            SELECT
                wp.company_id,
                wp.engagement_id,
                'working_paper' AS source_type,
                wp.id AS source_id,
                'deadline_risk' AS escalation_type,
                CASE
                    WHEN wp.due_date < CURRENT_DATE - INTERVAL '7 days' THEN 'high'
                    ELSE 'medium'
                END AS severity,
                CONCAT('Overdue working paper: ', wp.paper_name) AS title,
                CONCAT(
                    'Working paper ',
                    COALESCE(wp.paper_code, '#' || wp.id::text),
                    ' is overdue and still not completed.'
                ) AS description,
                'open' AS status,
                wp.preparer_user_id AS raised_by_user_id,
                wp.reviewer_user_id AS assigned_to_user_id,
                wp.due_date,
                TRUE,
                NOW(),
                NOW()
            FROM {schema}.engagement_working_papers wp
            WHERE wp.company_id = %s
            AND wp.is_active = TRUE
            AND wp.due_date IS NOT NULL
            AND wp.due_date < CURRENT_DATE
            AND wp.status NOT IN ('reviewed', 'cleared', 'archived')
            AND NOT EXISTS (
                SELECT 1
                FROM {schema}.engagement_escalations e
                WHERE e.company_id = wp.company_id
                    AND e.engagement_id = wp.engagement_id
                    AND e.source_type = 'working_paper'
                    AND e.source_id = wp.id
                    AND e.escalation_type = 'deadline_risk'
                    AND e.is_active = TRUE
                    AND e.status IN ('open', 'in_progress')
            )
            """,
            (company_id,),
        )
        
    def _resource_planning_base_cte_sql(self, schema: str):
        return f"""
            WITH engagement_scope AS (
                SELECT
                    e.id AS engagement_id,
                    e.company_id,
                    e.customer_id,
                    e.engagement_name,
                    e.engagement_code,
                    e.engagement_type,
                    e.status,
                    e.priority,
                    e.workflow_stage,
                    e.start_date,
                    e.end_date,
                    e.due_date,
                    c.name AS customer_name
                FROM {schema}.engagements e
                LEFT JOIN {schema}.customers c
                ON c.id = e.customer_id
                AND c.company_id = e.company_id
                WHERE e.company_id = %s
                AND (%s = FALSE OR e.is_active = TRUE)
                AND (
                        %s = ''
                        OR COALESCE(e.engagement_name, '') ILIKE %s
                        OR COALESCE(e.engagement_code, '') ILIKE %s
                        OR COALESCE(e.engagement_type, '') ILIKE %s
                        OR COALESCE(c.name, '') ILIKE %s
                    )
                AND (
                        e.start_date IS NULL
                        OR e.start_date <= (CURRENT_DATE + (%s * INTERVAL '1 day'))
                    )
                AND (
                        e.due_date IS NULL
                        OR e.due_date >= CURRENT_DATE - INTERVAL '30 day'
                    )
            ),
            team_alloc AS (
                SELECT
                    et.id,
                    et.engagement_id,
                    et.user_id,
                    LOWER(COALESCE(et.role_on_engagement, '')) AS role_on_engagement,
                    COALESCE(et.allocation_percent, 0) AS allocation_percent,
                    et.start_date,
                    et.end_date,
                    et.is_active
                FROM {schema}.engagement_team et
                WHERE et.company_id = %s
                AND (%s = FALSE OR et.is_active = TRUE)
                AND (
                        %s = ''
                        OR LOWER(COALESCE(et.role_on_engagement, '')) = %s
                    )
            ),
            users_scope AS (
                SELECT
                    u.id AS user_id,
                    CONCAT(
                        COALESCE(u.first_name, ''),
                        CASE
                            WHEN COALESCE(u.last_name, '') <> '' THEN ' ' || u.last_name
                            ELSE ''
                        END
                    ) AS user_name,
                    COALESCE(u.email, '') AS email
                FROM public.users u
            ),
            alloc_joined AS (
                SELECT
                    es.engagement_id,
                    es.customer_id,
                    es.customer_name,
                    es.engagement_name,
                    es.engagement_code,
                    es.engagement_type,
                    es.status,
                    es.priority,
                    es.workflow_stage,
                    es.start_date AS engagement_start_date,
                    es.end_date AS engagement_end_date,
                    es.due_date,
                    ta.user_id,
                    us.user_name,
                    us.email,
                    ta.role_on_engagement,
                    ta.allocation_percent,
                    ta.start_date AS allocation_start_date,
                    ta.end_date AS allocation_end_date
                FROM engagement_scope es
                LEFT JOIN team_alloc ta
                ON ta.engagement_id = es.engagement_id
                LEFT JOIN users_scope us
                ON us.user_id = ta.user_id
            ),
            engagement_staffing AS (
                SELECT
                    aj.engagement_id,
                    MAX(aj.customer_id) AS customer_id,
                    MAX(aj.customer_name) AS customer_name,
                    MAX(aj.engagement_name) AS engagement_name,
                    MAX(aj.engagement_code) AS engagement_code,
                    MAX(aj.engagement_type) AS engagement_type,
                    MAX(aj.status) AS status,
                    MAX(aj.priority) AS priority,
                    MAX(aj.workflow_stage) AS workflow_stage,
                    MAX(aj.engagement_start_date) AS start_date,
                    MAX(aj.engagement_end_date) AS end_date,
                    MAX(aj.due_date) AS due_date,

                    COUNT(*) FILTER (WHERE aj.user_id IS NOT NULL) AS team_rows,
                    COUNT(*) FILTER (WHERE aj.role_on_engagement = 'manager') AS manager_count,
                    COUNT(*) FILTER (WHERE aj.role_on_engagement = 'reviewer') AS reviewer_count,
                    COUNT(*) FILTER (WHERE aj.role_on_engagement = 'partner') AS partner_count,
                    COUNT(*) FILTER (WHERE aj.role_on_engagement = 'qc') AS qc_count,

                    COALESCE(SUM(aj.allocation_percent), 0) AS total_allocation_percent
                FROM alloc_joined aj
                GROUP BY aj.engagement_id
            ),
            user_load AS (
                SELECT
                    aj.user_id,
                    MAX(aj.user_name) AS user_name,
                    MAX(aj.email) AS email,
                    COUNT(DISTINCT aj.engagement_id) AS active_engagements,
                    ROUND(COALESCE(SUM(aj.allocation_percent), 0), 2) AS total_allocation_percent,
                    COUNT(*) FILTER (
                        WHERE aj.due_date IS NOT NULL
                        AND aj.due_date <= (CURRENT_DATE + INTERVAL '14 day')
                        AND aj.status NOT IN ('completed', 'cancelled', 'archived')
                    ) AS engagements_due_soon
                FROM alloc_joined aj
                WHERE aj.user_id IS NOT NULL
                GROUP BY aj.user_id
            )
        """
    def get_resource_planning_summary(
        self,
        cur,
        company_id: int,
        *,
        q: str = "",
        role_on_engagement: str = "",
        active_only: bool = True,
        horizon_days: int = 60,
    ):
        schema = self.company_schema(company_id)
        base_sql = self._resource_planning_base_cte_sql(schema)

        sql = base_sql + """
            SELECT
                COUNT(*) AS total_engagements,
                COUNT(*) FILTER (
                    WHERE due_date IS NOT NULL
                    AND due_date <= (CURRENT_DATE + INTERVAL '30 day')
                    AND status NOT IN ('completed', 'cancelled', 'archived')
                ) AS upcoming_peaks,
                COUNT(*) FILTER (
                    WHERE manager_count = 0
                    OR reviewer_count = 0
                ) AS coverage_gaps,
                COUNT(*) FILTER (
                    WHERE total_allocation_percent > 100
                ) AS overloaded_engagements,
                COUNT(*) FILTER (
                    WHERE total_allocation_percent < 100
                    AND status NOT IN ('completed', 'cancelled', 'archived')
                ) AS under_allocated_engagements,
                (
                    SELECT COUNT(*)
                    FROM user_load ul
                    WHERE ul.total_allocation_percent > 100
                ) AS overloaded_users,
                (
                    SELECT COUNT(*)
                    FROM user_load ul
                    WHERE ul.total_allocation_percent < 70
                ) AS available_users
            FROM engagement_staffing
        """

        like = f"%{q.strip()}%"
        cur.execute(
            sql,
            (
                company_id,
                active_only,
                q.strip(), like, like, like, like,
                horizon_days,
                company_id,
                active_only,
                role_on_engagement, role_on_engagement,
            ),
        )
        return cur.fetchone()

    def list_resource_planning_peaks(
        self,
        cur,
        company_id: int,
        *,
        q: str = "",
        role_on_engagement: str = "",
        active_only: bool = True,
        horizon_days: int = 60,
        limit: int = 100,
        offset: int = 0,
    ):
        schema = self.company_schema(company_id)
        base_sql = self._resource_planning_base_cte_sql(schema)

        sql = base_sql + """
            SELECT
                engagement_id,
                customer_id,
                customer_name,
                engagement_name,
                engagement_code,
                engagement_type,
                status,
                priority,
                workflow_stage,
                start_date,
                end_date,
                due_date,
                manager_count,
                reviewer_count,
                partner_count,
                qc_count,
                total_allocation_percent,
                CASE
                    WHEN due_date IS NOT NULL AND due_date < CURRENT_DATE THEN 'overdue'
                    WHEN due_date IS NOT NULL AND due_date <= (CURRENT_DATE + INTERVAL '7 day') THEN 'this_week'
                    WHEN due_date IS NOT NULL AND due_date <= (CURRENT_DATE + INTERVAL '30 day') THEN 'this_month'
                    ELSE 'upcoming'
                END AS pressure_window
            FROM engagement_staffing
            WHERE due_date IS NOT NULL
            AND due_date <= (CURRENT_DATE + (%s * INTERVAL '1 day'))
            AND status NOT IN ('completed', 'cancelled', 'archived')
            ORDER BY
                due_date ASC,
                CASE priority
                    WHEN 'urgent' THEN 1
                    WHEN 'high' THEN 2
                    WHEN 'normal' THEN 3
                    ELSE 4
                END,
                engagement_name ASC
            LIMIT %s OFFSET %s
        """

        like = f"%{q.strip()}%"
        cur.execute(
            sql,
            (
                company_id,
                active_only,
                q.strip(), like, like, like, like,
                horizon_days,
                company_id,
                active_only,
                role_on_engagement, role_on_engagement,
                horizon_days,
                limit,
                offset,
            ),
        )
        return cur.fetchall()

    def list_resource_planning_coverage_gaps(
        self,
        cur,
        company_id: int,
        *,
        q: str = "",
        active_only: bool = True,
        horizon_days: int = 60,
        limit: int = 100,
        offset: int = 0,
    ):
        schema = self.company_schema(company_id)
        base_sql = self._resource_planning_base_cte_sql(schema)

        sql = base_sql + """
            SELECT
                engagement_id,
                customer_id,
                customer_name,
                engagement_name,
                engagement_code,
                engagement_type,
                status,
                priority,
                workflow_stage,
                start_date,
                end_date,
                due_date,
                manager_count,
                reviewer_count,
                partner_count,
                qc_count,
                total_allocation_percent,
                ARRAY_REMOVE(ARRAY[
                    CASE WHEN manager_count = 0 THEN 'manager' END,
                    CASE WHEN reviewer_count = 0 THEN 'reviewer' END,
                    CASE WHEN partner_count = 0 THEN 'partner' END
                ], NULL) AS missing_roles
            FROM engagement_staffing
            WHERE (
                    manager_count = 0
                OR reviewer_count = 0
                OR partner_count = 0
            )
            AND (
                    due_date IS NULL
                    OR due_date <= (CURRENT_DATE + (%s * INTERVAL '1 day'))
                )
            AND status NOT IN ('completed', 'cancelled', 'archived')
            ORDER BY
                due_date NULLS LAST,
                priority DESC,
                engagement_name ASC
            LIMIT %s OFFSET %s
        """

        like = f"%{q.strip()}%"
        cur.execute(
            sql,
            (
                company_id,
                active_only,
                q.strip(), like, like, like, like,
                horizon_days,
                company_id,
                active_only,
                "", "",
                horizon_days,
                limit,
                offset,
            ),
        )
        return cur.fetchall()
    
    def list_resource_planning_reallocation_opportunities(
        self,
        cur,
        company_id: int,
        *,
        q: str = "",
        role_on_engagement: str = "",
        active_only: bool = True,
        horizon_days: int = 60,
        limit: int = 100,
        offset: int = 0,
    ):
        schema = self.company_schema(company_id)
        base_sql = self._resource_planning_base_cte_sql(schema)

        sql = base_sql + """
            SELECT
                user_id,
                user_name,
                email,
                active_engagements,
                total_allocation_percent,
                engagements_due_soon,
                CASE
                    WHEN total_allocation_percent > 100 THEN 'overloaded'
                    WHEN total_allocation_percent < 70 THEN 'available'
                    ELSE 'balanced'
                END AS capacity_band,
                CASE
                    WHEN total_allocation_percent > 100 THEN ROUND(total_allocation_percent - 100, 2)
                    WHEN total_allocation_percent < 70 THEN ROUND(70 - total_allocation_percent, 2)
                    ELSE 0
                END AS adjustment_percent
            FROM user_load
            WHERE (
                    total_allocation_percent > 100
                OR total_allocation_percent < 70
            )
            AND (
                    %s = ''
                    OR COALESCE(user_name, '') ILIKE %s
                    OR COALESCE(email, '') ILIKE %s
            )
            ORDER BY
                CASE
                    WHEN total_allocation_percent > 100 THEN 1
                    WHEN total_allocation_percent < 70 THEN 2
                    ELSE 3
                END,
                ABS(total_allocation_percent - 100) DESC,
                user_name ASC
            LIMIT %s OFFSET %s
        """

        like = f"%{q.strip()}%"
        cur.execute(
            sql,
            (
                company_id,
                active_only,
                q.strip(), like, like, like, like,
                horizon_days,
                company_id,
                active_only,
                role_on_engagement, role_on_engagement,
                q.strip(), like, like,
                limit,
                offset,
            ),
        )
        return cur.fetchall()

    def list_resource_planning_schedule(
        self,
        cur,
        company_id: int,
        *,
        q: str = "",
        role_on_engagement: str = "",
        active_only: bool = True,
        horizon_days: int = 60,
        only_overloaded: bool = False,
        only_available: bool = False,
        limit: int = 100,
        offset: int = 0,
    ):
        schema = self.company_schema(company_id)
        base_sql = self._resource_planning_base_cte_sql(schema)

        sql = base_sql + """
            SELECT
                user_id,
                user_name,
                email,
                active_engagements,
                total_allocation_percent,
                engagements_due_soon,
                CASE
                    WHEN total_allocation_percent > 100 THEN TRUE
                    ELSE FALSE
                END AS is_overloaded,
                CASE
                    WHEN total_allocation_percent < 70 THEN TRUE
                    ELSE FALSE
                END AS is_available
            FROM user_load
            WHERE user_id IS NOT NULL
            AND (%s = FALSE OR total_allocation_percent > 100)
            AND (%s = FALSE OR total_allocation_percent < 70)
            AND (
                    %s = ''
                    OR COALESCE(user_name, '') ILIKE %s
                    OR COALESCE(email, '') ILIKE %s
            )
            ORDER BY
                total_allocation_percent DESC,
                engagements_due_soon DESC,
                user_name ASC
            LIMIT %s OFFSET %s
        """

        like = f"%{q.strip()}%"
        cur.execute(
            sql,
            (
                company_id,
                active_only,
                q.strip(), like, like, like, like,
                horizon_days,
                company_id,
                active_only,
                role_on_engagement, role_on_engagement,
                only_overloaded,
                only_available,
                q.strip(), like, like,
                limit,
                offset,
            ),
        )
        return cur.fetchall()

    def _final_deliverables_review_base_sql(self, schema: str):
        return f"""
            WITH scoped_engagements AS (
                SELECT
                    e.id,
                    e.company_id,
                    e.customer_id,
                    c.name AS customer_name,
                    e.engagement_name,
                    e.engagement_code,
                    e.engagement_type,
                    e.status,
                    e.priority,
                    e.workflow_stage,
                    e.start_date,
                    e.due_date
                FROM {schema}.engagements e
                LEFT JOIN {schema}.customers c
                ON c.id = e.customer_id
                AND c.company_id = e.company_id
                WHERE e.company_id = %s
                AND (%s = FALSE OR e.is_active = TRUE)
                AND (
                        %s = ''
                        OR COALESCE(e.engagement_name, '') ILIKE %s
                        OR COALESCE(e.engagement_code, '') ILIKE %s
                        OR COALESCE(e.engagement_type, '') ILIKE %s
                        OR COALESCE(c.name, '') ILIKE %s
                    )
                AND (
                        %s = ''
                        OR LOWER(COALESCE(e.status, '')) = %s
                    )
            ),
            wp_stats AS (
                SELECT
                    wp.engagement_id,
                    COUNT(*) AS total_working_papers,
                    COUNT(*) FILTER (
                        WHERE wp.status IN ('reviewed', 'cleared', 'archived')
                    ) AS completed_working_papers,
                    COUNT(*) FILTER (
                        WHERE wp.due_date IS NOT NULL
                        AND wp.due_date < CURRENT_DATE
                        AND wp.status NOT IN ('reviewed', 'cleared', 'archived')
                    ) AS overdue_working_papers,
                    COUNT(*) FILTER (
                        WHERE wp.status = 'blocked'
                    ) AS blocked_working_papers,
                    COUNT(*) FILTER (
                        WHERE wp.status IN ('prepared', 'in_review')
                    ) AS in_review_working_papers
                FROM {schema}.engagement_working_papers wp
                WHERE wp.company_id = %s
                AND wp.is_active = TRUE
                GROUP BY wp.engagement_id
            ),
            deliverable_stats AS (
                SELECT
                    d.engagement_id,
                    COUNT(*) AS total_deliverables,
                    COUNT(*) FILTER (
                        WHERE d.status IN ('completed', 'approved', 'signed_off')
                    ) AS completed_deliverables,
                    COUNT(*) FILTER (
                        WHERE d.due_date IS NOT NULL
                        AND d.due_date < CURRENT_DATE
                        AND d.status NOT IN ('completed', 'approved', 'signed_off')
                    ) AS overdue_deliverables,
                    COUNT(*) FILTER (
                        WHERE d.status IN ('outstanding', 'requested')
                    ) AS outstanding_deliverables,
                    COUNT(*) FILTER (
                        WHERE d.status = 'in_review'
                    ) AS in_review_deliverables
                FROM {schema}.engagement_deliverables d
                WHERE d.company_id = %s
                AND d.is_active = TRUE
                GROUP BY d.engagement_id
            ),
            signoff_stats AS (
                SELECT
                    s.engagement_id,
                    COUNT(*) AS total_signoff_steps,
                    COUNT(*) FILTER (
                        WHERE s.status IN ('completed', 'approved', 'signed_off')
                    ) AS completed_signoff_steps,
                    COUNT(*) FILTER (
                        WHERE s.status NOT IN ('completed', 'approved', 'signed_off')
                    ) AS pending_signoff_steps
                FROM {schema}.engagement_signoff_steps s
                WHERE s.company_id = %s
                AND s.is_active = TRUE
                GROUP BY s.engagement_id
            ),
            reporting_stats AS (
                SELECT
                    r.engagement_id,
                    COUNT(*) AS total_reporting_items
                FROM {schema}.engagement_reporting_items r
                WHERE r.company_id = %s
                AND r.is_active = TRUE
                GROUP BY r.engagement_id
            ),
            escalations AS (
                SELECT
                    x.engagement_id,
                    COUNT(*) FILTER (
                        WHERE x.status NOT IN ('resolved', 'closed')
                    ) AS open_escalations
                FROM {schema}.engagement_escalations x
                WHERE x.company_id = %s
                AND x.is_active = TRUE
                GROUP BY x.engagement_id
            ),
            combined AS (
                SELECT
                    e.id AS engagement_id,
                    e.customer_id,
                    e.customer_name,
                    e.engagement_name,
                    e.engagement_code,
                    e.engagement_type,
                    e.status,
                    e.priority,
                    e.workflow_stage,
                    e.start_date,
                    e.due_date,

                    COALESCE(w.total_working_papers, 0) AS total_working_papers,
                    COALESCE(w.completed_working_papers, 0) AS completed_working_papers,
                    COALESCE(w.overdue_working_papers, 0) AS overdue_working_papers,
                    COALESCE(w.blocked_working_papers, 0) AS blocked_working_papers,
                    COALESCE(w.in_review_working_papers, 0) AS in_review_working_papers,

                    COALESCE(d.total_deliverables, 0) AS total_deliverables,
                    COALESCE(d.completed_deliverables, 0) AS completed_deliverables,
                    COALESCE(d.overdue_deliverables, 0) AS overdue_deliverables,
                    COALESCE(d.outstanding_deliverables, 0) AS outstanding_deliverables,
                    COALESCE(d.in_review_deliverables, 0) AS in_review_deliverables,

                    COALESCE(s.total_signoff_steps, 0) AS total_signoff_steps,
                    COALESCE(s.completed_signoff_steps, 0) AS completed_signoff_steps,
                    COALESCE(s.pending_signoff_steps, 0) AS pending_signoff_steps,

                    COALESCE(r.total_reporting_items, 0) AS total_reporting_items,
                    COALESCE(x.open_escalations, 0) AS open_escalations
                FROM scoped_engagements e
                LEFT JOIN wp_stats w ON w.engagement_id = e.id
                LEFT JOIN deliverable_stats d ON d.engagement_id = e.id
                LEFT JOIN signoff_stats s ON s.engagement_id = e.id
                LEFT JOIN reporting_stats r ON r.engagement_id = e.id
                LEFT JOIN escalations x ON x.engagement_id = e.id
            ),
            final AS (
                SELECT
                    *,
                    CASE
                        WHEN (
                            overdue_working_papers > 0
                            OR overdue_deliverables > 0
                            OR open_escalations > 0
                            OR (due_date IS NOT NULL AND due_date < CURRENT_DATE AND status NOT IN ('completed', 'cancelled', 'archived'))
                        ) THEN 'high'
                        WHEN (
                            pending_signoff_steps > 0
                            OR outstanding_deliverables > 0
                            OR in_review_working_papers > 0
                            OR in_review_deliverables > 0
                        ) THEN 'medium'
                        ELSE 'low'
                    END AS risk_band,
                    CASE
                        WHEN (total_working_papers + total_deliverables + total_signoff_steps) = 0 THEN 0
                        ELSE ROUND(
                            (
                                (completed_working_papers + completed_deliverables + completed_signoff_steps)::numeric
                                / NULLIF((total_working_papers + total_deliverables + total_signoff_steps), 0)
                            ) * 100,
                            2
                        )
                    END AS readiness_percent,
                    CASE
                        WHEN
                            overdue_working_papers = 0
                            AND overdue_deliverables = 0
                            AND pending_signoff_steps = 0
                            AND outstanding_deliverables = 0
                            AND open_escalations = 0
                        THEN TRUE
                        ELSE FALSE
                    END AS ready_for_signoff
                FROM combined
            )
        """

    def get_final_deliverables_review_summary(
        self,
        cur,
        company_id: int,
        *,
        q: str = "",
        status: str = "",
        risk_band: str = "",
        active_only: bool = True,
    ):
        schema = self.company_schema(company_id)
        base_sql = self._final_deliverables_review_base_sql(schema)

        sql = base_sql + """
            SELECT
                COUNT(*) AS total_engagements,
                COUNT(*) FILTER (WHERE ready_for_signoff = TRUE) AS ready_for_signoff,
                COUNT(*) FILTER (WHERE risk_band = 'high') AS high_risk,
                COUNT(*) FILTER (WHERE overdue_deliverables > 0 OR overdue_working_papers > 0) AS overdue_items,
                COUNT(*) FILTER (WHERE pending_signoff_steps > 0) AS pending_signoffs,
                ROUND(AVG(readiness_percent), 2) AS avg_readiness_percent
            FROM final
            WHERE (%s = '' OR risk_band = %s)
        """

        like = f"%{q.strip()}%"
        cur.execute(
            sql,
            (
                company_id,
                active_only,
                q.strip(), like, like, like, like,
                status, status,
                company_id,
                company_id,
                company_id,
                company_id,
                company_id,
                risk_band, risk_band,
            ),
        )
        return cur.fetchone()

    def list_final_deliverables_review(
        self,
        cur,
        company_id: int,
        *,
        q: str = "",
        status: str = "",
        risk_band: str = "",
        ready_only: bool = False,
        blockers_only: bool = False,
        active_only: bool = True,
        limit: int = 100,
        offset: int = 0,
    ):
        schema = self.company_schema(company_id)
        base_sql = self._final_deliverables_review_base_sql(schema)

        sql = base_sql + """
            SELECT *
            FROM final
            WHERE (%s = '' OR risk_band = %s)
            AND (%s = FALSE OR ready_for_signoff = TRUE)
            AND (
                    %s = FALSE OR (
                        overdue_working_papers > 0
                        OR overdue_deliverables > 0
                        OR pending_signoff_steps > 0
                        OR open_escalations > 0
                    )
                )
            ORDER BY
                CASE risk_band
                    WHEN 'high' THEN 1
                    WHEN 'medium' THEN 2
                    ELSE 3
                END,
                ready_for_signoff DESC,
                due_date NULLS LAST,
                engagement_name ASC
            LIMIT %s OFFSET %s
        """

        like = f"%{q.strip()}%"
        cur.execute(
            sql,
            (
                company_id,
                active_only,
                q.strip(), like, like, like, like,
                status, status,
                company_id,
                company_id,
                company_id,
                company_id,
                company_id,
                risk_band, risk_band,
                ready_only,
                blockers_only,
                limit,
                offset,
            ),
        )
        return cur.fetchall()

    def get_final_deliverables_review_detail(
        self,
        cur,
        company_id: int,
        *,
        engagement_id: int,
    ):
        schema = self.company_schema(company_id)

        summary_sql = self._final_deliverables_review_base_sql(schema) + """
            SELECT *
            FROM final
            WHERE engagement_id = %s
            LIMIT 1
        """

        cur.execute(
            summary_sql,
            (
                company_id,
                True,
                "", "%%", "%%", "%%", "%%",
                "", "",
                company_id,
                company_id,
                company_id,
                company_id,
                company_id,
                engagement_id,
            ),
        )
        summary_row = cur.fetchone()
        if not summary_row:
            return None

        cur.execute(
            f"""
            SELECT
                id,
                deliverable_code,
                deliverable_name,
                deliverable_type,
                requested_from,
                assigned_user_id,
                reviewer_user_id,
                due_date,
                received_date,
                status,
                priority,
                notes,
                document_count
            FROM {schema}.engagement_deliverables
            WHERE company_id = %s
            AND engagement_id = %s
            AND is_active = TRUE
            ORDER BY
                CASE priority
                    WHEN 'urgent' THEN 1
                    WHEN 'high' THEN 2
                    WHEN 'normal' THEN 3
                    ELSE 4
                END,
                due_date NULLS LAST,
                deliverable_name ASC
            """,
            (company_id, engagement_id),
        )
        deliverables = cur.fetchall()

        cur.execute(
            f"""
            SELECT
                id,
                paper_code,
                paper_name,
                paper_section,
                paper_type,
                status,
                priority,
                due_date,
                preparer_user_id,
                reviewer_user_id,
                document_count,
                notes,
                review_notes,
                linked_reporting_item_id,
                linked_deliverable_id,
                prepared_at,
                reviewed_at,
                cleared_at
            FROM {schema}.engagement_working_papers
            WHERE company_id = %s
            AND engagement_id = %s
            AND is_active = TRUE
            ORDER BY due_date NULLS LAST, paper_name ASC
            """,
            (company_id, engagement_id),
        )
        working_papers = cur.fetchall()

        cur.execute(
            f"""
            SELECT
                id,
                step_code,
                step_name,
                status,
                assigned_user_id,
                due_date,
                completed_at,
                notes
            FROM {schema}.engagement_signoff_steps
            WHERE company_id = %s
            AND engagement_id = %s
            AND is_active = TRUE
            ORDER BY due_date NULLS LAST, step_name ASC
            """,
            (company_id, engagement_id),
        )
        signoff_steps = cur.fetchall()

        cur.execute(
            f"""
            SELECT
                id,
                item_type,
                item_name,
                status,
                due_date,
                owner_user_id,
                reviewer_user_id,
                notes
            FROM {schema}.engagement_reporting_items
            WHERE company_id = %s
            AND engagement_id = %s
            AND is_active = TRUE
            ORDER BY due_date NULLS LAST, item_name ASC
            """,
            (company_id, engagement_id),
        )
        reporting_items = cur.fetchall()

        return {
            "summary": summary_row,
            "deliverables": deliverables,
            "working_papers": working_papers,
            "signoff_steps": signoff_steps,
            "reporting_items": reporting_items,
        }
        
    def _approval_center_base_sql(self, schema: str):
        return f"""
            WITH scoped_engagements AS (
                SELECT
                    e.id AS engagement_id,
                    e.company_id,
                    e.customer_id,
                    e.engagement_name,
                    e.engagement_code,
                    e.engagement_type,
                    e.status AS engagement_status,
                    e.priority AS engagement_priority,
                    e.workflow_stage,
                    e.due_date AS engagement_due_date,
                    c.name AS customer_name
                FROM {schema}.engagements e
                LEFT JOIN {schema}.customers c
                ON c.id = e.customer_id
                AND c.company_id = e.company_id
                WHERE e.company_id = %s
                AND (%s = FALSE OR e.is_active = TRUE)
                AND (
                        %s = ''
                        OR COALESCE(e.engagement_name, '') ILIKE %s
                        OR COALESCE(e.engagement_code, '') ILIKE %s
                        OR COALESCE(c.name, '') ILIKE %s
                    )
            ),
            deliverable_stats AS (
                SELECT
                    d.engagement_id,
                    COUNT(*) FILTER (
                        WHERE d.status NOT IN ('completed', 'approved', 'signed_off')
                    ) AS pending_deliverables,
                    COUNT(*) FILTER (
                        WHERE d.due_date IS NOT NULL
                        AND d.due_date < CURRENT_DATE
                        AND d.status NOT IN ('completed', 'approved', 'signed_off')
                    ) AS overdue_deliverables
                FROM {schema}.engagement_deliverables d
                WHERE d.company_id = %s
                AND d.is_active = TRUE
                GROUP BY d.engagement_id
            ),
            signoff_stats AS (
                SELECT
                    s.engagement_id,
                    COUNT(*) FILTER (
                        WHERE s.status NOT IN ('completed', 'approved', 'signed_off')
                    ) AS pending_signoff_steps
                FROM {schema}.engagement_signoff_steps s
                WHERE s.company_id = %s
                AND s.is_active = TRUE
                GROUP BY s.engagement_id
            ),
            escalation_stats AS (
                SELECT
                    x.engagement_id,
                    COUNT(*) FILTER (
                        WHERE x.status NOT IN ('resolved', 'closed')
                    ) AS open_escalations
                FROM {schema}.engagement_escalations x
                WHERE x.company_id = %s
                AND x.is_active = TRUE
                GROUP BY x.engagement_id
            ),
            last_decision AS (
                SELECT DISTINCT ON (d.approval_request_id)
                    d.approval_request_id,
                    LOWER(COALESCE(d.decision, '')) AS last_action,
                    d.note AS decision_note,
                    d.decided_by_user_id,
                    d.decided_at
                FROM {schema}.approval_decisions d
                WHERE d.company_id = %s
                ORDER BY d.approval_request_id, d.decided_at DESC, d.id DESC
            ),
            request_items AS (
                SELECT
                    ar.id AS source_id,
                    LOWER(COALESCE(ar.module, '')) AS queue_type,
                    ar.company_id,
                    NULLIF(COALESCE(ar.payload_json ->> 'engagement_id', ''), '')::INT AS engagement_id,
                    ar.entity_type,
                    ar.entity_id,
                    ar.entity_ref,
                    ar.module,
                    ar.action,
                    COALESCE(
                        NULLIF(ar.payload_json ->> 'title', ''),
                        NULLIF(ar.entity_ref, ''),
                        CONCAT(ar.entity_type, ' ', ar.entity_id)
                    ) AS title,
                    COALESCE(
                        NULLIF(ar.payload_json ->> 'description', ''),
                        NULLIF(ar.decision_note, ''),
                        ''
                    ) AS description,
                    LOWER(COALESCE(ar.status, 'pending')) AS status,
                    LOWER(COALESCE(ar.risk_level, 'low')) AS risk_band,
                    ar.requested_by_user_id,
                    NULL::INT AS assigned_reviewer_user_id,
                    ar.decided_by_user_id AS assigned_manager_user_id,
                    ar.amount,
                    ar.currency,
                    NULL::DATE AS due_date,
                    ar.payload_json,
                    ar.requested_at,
                    ar.created_at,
                    ar.updated_at,
                    ld.last_action,
                    COALESCE(ld.decision_note, ar.decision_note) AS manager_comment
                FROM {schema}.approval_requests ar
                LEFT JOIN last_decision ld
                ON ld.approval_request_id = ar.id
                WHERE ar.company_id = %s
                AND (%s = '' OR LOWER(COALESCE(ar.module, '')) = %s)
                AND (%s = '' OR LOWER(COALESCE(ar.status, 'pending')) = %s)
                AND (
                        %s = ''
                        OR COALESCE(ar.entity_ref, '') ILIKE %s
                        OR COALESCE(ar.entity_type, '') ILIKE %s
                        OR COALESCE(ar.action, '') ILIKE %s
                        OR COALESCE(ar.module, '') ILIKE %s
                    )
            ),
            combined AS (
                SELECT
                    r.source_id,
                    r.queue_type,
                    r.company_id,
                    r.engagement_id,
                    e.customer_id,
                    e.customer_name,
                    e.engagement_name,
                    e.engagement_code,
                    e.engagement_type,
                    e.engagement_status,
                    e.engagement_priority,
                    e.workflow_stage,
                    e.engagement_due_date,

                    r.entity_type,
                    r.entity_id,
                    r.entity_ref,
                    r.module,
                    r.action,
                    r.title,
                    r.description,
                    r.status,
                    r.risk_band,
                    r.requested_by_user_id,
                    r.assigned_reviewer_user_id,
                    r.assigned_manager_user_id,
                    r.amount,
                    r.currency,
                    r.due_date,
                    r.payload_json,
                    r.requested_at,
                    r.created_at,
                    r.updated_at,
                    r.last_action,
                    r.manager_comment,

                    COALESCE(d.pending_deliverables, 0) AS pending_deliverables,
                    COALESCE(d.overdue_deliverables, 0) AS overdue_deliverables,
                    COALESCE(s.pending_signoff_steps, 0) AS pending_signoff_steps,
                    COALESCE(x.open_escalations, 0) AS open_escalations
                FROM request_items r
                LEFT JOIN scoped_engagements e
                ON e.engagement_id = r.engagement_id
                LEFT JOIN deliverable_stats d
                ON d.engagement_id = r.engagement_id
                LEFT JOIN signoff_stats s
                ON s.engagement_id = r.engagement_id
                LEFT JOIN escalation_stats x
                ON x.engagement_id = r.engagement_id
            ),
            final AS (
                SELECT
                    *,
                    CASE
                        WHEN status IN ('approved') THEN TRUE
                        WHEN overdue_deliverables = 0
                        AND open_escalations = 0
                        AND pending_signoff_steps = 0
                        THEN TRUE
                        ELSE FALSE
                    END AS ready_for_release
                FROM combined
            )
        """


    def get_approval_center_summary(
        self,
        cur,
        company_id: int,
        *,
        q: str = "",
        module: str = "",
        status: str = "",
        ready_only: bool = False,
        blockers_only: bool = False,
        active_only: bool = True,  # kept for compatibility
    ):
        schema = self.company_schema(company_id)

        where = ["ar.company_id = %s"]
        params = [company_id]

        if module:
            where.append("LOWER(COALESCE(ar.module, '')) = LOWER(%s)")
            params.append(module)

        if status:
            where.append("LOWER(COALESCE(ar.status, '')) = LOWER(%s)")
            params.append(status)

        if q:
            like = f"%{q}%"
            where.append("""
                (
                    COALESCE(ar.entity_ref, '') ILIKE %s
                    OR COALESCE(ar.entity_type, '') ILIKE %s
                    OR COALESCE(ar.action, '') ILIKE %s
                    OR COALESCE(ar.module, '') ILIKE %s
                )
            """)
            params.extend([like, like, like, like])

        if ready_only:
            where.append("""
                LOWER(COALESCE(ar.status, '')) IN ('approved')
            """)

        if blockers_only:
            where.append("""
                (
                    LOWER(COALESCE(ar.status, '')) IN ('rejected')
                    OR LOWER(COALESCE(ar.risk_level, '')) IN ('high', 'critical')
                )
            """)

        where_sql = " AND ".join(where)

        cur.execute(
            f"""
            SELECT
                COUNT(*) AS total_items,
                COUNT(*) FILTER (
                    WHERE LOWER(COALESCE(ar.status, '')) = 'pending'
                ) AS pending_approvals,
                COUNT(*) FILTER (
                    WHERE LOWER(COALESCE(ar.status, '')) = 'approved'
                ) AS ready_for_release,
                COUNT(*) FILTER (
                    WHERE LOWER(COALESCE(ar.risk_level, '')) IN ('high', 'critical')
                ) AS high_risk,
                COUNT(*) FILTER (
                    WHERE LOWER(COALESCE(ar.status, '')) = 'rejected'
                ) AS returned_for_rework,
                COUNT(*) FILTER (
                    WHERE LOWER(COALESCE(ar.action, '')) = 'escalate'
                    OR LOWER(COALESCE(ar.risk_level, '')) IN ('high', 'critical')
                ) AS escalated_items
            FROM {schema}.approval_requests ar
            WHERE {where_sql}
            """,
            params,
        )

        return cur.fetchone()

    def list_approval_center_items(
        self,
        cur,
        company_id: int,
        *,
        q: str = "",
        module: str = "",
        status: str = "",
        ready_only: bool = False,
        blockers_only: bool = False,
        active_only: bool = True,  # kept for compatibility
        limit: int = 100,
        offset: int = 0,
    ):
        schema = self.company_schema(company_id)

        where = ["ar.company_id = %s"]
        params = [company_id]

        if module:
            where.append("LOWER(COALESCE(ar.module, '')) = LOWER(%s)")
            params.append(module)

        if status:
            where.append("LOWER(COALESCE(ar.status, '')) = LOWER(%s)")
            params.append(status)

        if q:
            like = f"%{q}%"
            where.append("""
                (
                    COALESCE(ar.entity_ref, '') ILIKE %s
                    OR COALESCE(ar.entity_type, '') ILIKE %s
                    OR COALESCE(ar.action, '') ILIKE %s
                    OR COALESCE(ar.module, '') ILIKE %s
                )
            """)
            params.extend([like, like, like, like])

        if ready_only:
            where.append("LOWER(COALESCE(ar.status, '')) = 'approved'")

        if blockers_only:
            where.append("""
                (
                    LOWER(COALESCE(ar.status, '')) = 'rejected'
                    OR LOWER(COALESCE(ar.risk_level, '')) IN ('high', 'critical')
                )
            """)

        where_sql = " AND ".join(where)

        cur.execute(
            f"""
            SELECT
                ar.id AS source_id,
                LOWER(COALESCE(ar.module, '')) AS queue_type,
                NULLIF(COALESCE(ar.payload_json ->> 'engagement_id', ''), '')::INT AS engagement_id,
                ar.entity_type,
                ar.entity_id,
                ar.entity_ref,
                ar.module,
                ar.action,
                COALESCE(
                    NULLIF(ar.payload_json ->> 'title', ''),
                    NULLIF(ar.entity_ref, ''),
                    CONCAT(COALESCE(ar.entity_type, 'item'), ' ', COALESCE(ar.entity_id, ''))
                ) AS title,
                COALESCE(
                    NULLIF(ar.payload_json ->> 'description', ''),
                    COALESCE(ar.decision_note, '')
                ) AS description,
                LOWER(COALESCE(ar.status, 'pending')) AS status,
                LOWER(COALESCE(ar.risk_level, 'low')) AS risk_band,
                ar.requested_by_user_id,
                ar.decided_by_user_id AS assigned_manager_user_id,
                ar.amount,
                ar.currency,
                ar.payload_json,
                ar.requested_at,
                ar.created_at,
                ar.updated_at
            FROM {schema}.approval_requests ar
            WHERE {where_sql}
            ORDER BY
                CASE LOWER(COALESCE(ar.risk_level, 'low'))
                    WHEN 'critical' THEN 1
                    WHEN 'high' THEN 2
                    WHEN 'medium' THEN 3
                    ELSE 4
                END,
                ar.requested_at DESC NULLS LAST,
                ar.created_at DESC
            LIMIT %s OFFSET %s
            """,
            [*params, limit, offset],
        )

        return cur.fetchall()

    def get_approval_center_item_detail(
        self,
        cur,
        company_id: int,
        *,
        queue_type: str,
        source_id: int,
    ):
        schema = self.company_schema(company_id)

        cur.execute(
            f"""
            SELECT
                ar.id AS source_id,
                LOWER(COALESCE(ar.module, '')) AS queue_type,
                NULLIF(COALESCE(ar.payload_json ->> 'engagement_id', ''), '')::INT AS engagement_id,
                ar.entity_type,
                ar.entity_id,
                ar.entity_ref,
                ar.module,
                ar.action,
                COALESCE(
                    NULLIF(ar.payload_json ->> 'title', ''),
                    NULLIF(ar.entity_ref, ''),
                    CONCAT(COALESCE(ar.entity_type, 'item'), ' ', COALESCE(ar.entity_id, ''))
                ) AS title,
                COALESCE(
                    NULLIF(ar.payload_json ->> 'description', ''),
                    COALESCE(ar.decision_note, '')
                ) AS description,
                LOWER(COALESCE(ar.status, 'pending')) AS status,
                LOWER(COALESCE(ar.risk_level, 'low')) AS risk_band,
                ar.requested_by_user_id,
                ar.decided_by_user_id AS assigned_manager_user_id,
                ar.amount,
                ar.currency,
                ar.payload_json,
                ar.requested_at,
                ar.created_at,
                ar.updated_at
            FROM {schema}.approval_requests ar
            WHERE ar.company_id = %s
            AND ar.id = %s
            AND LOWER(COALESCE(ar.module, '')) = %s
            LIMIT 1
            """,
            (company_id, source_id, queue_type),
        )
        row = cur.fetchone()
        if not row:
            return None

        cur.execute(
            f"""
            SELECT
                id,
                approval_request_id,
                decision,
                decided_by_user_id,
                decided_at,
                note,
                meta_json
            FROM {schema}.approval_decisions
            WHERE company_id = %s
            AND approval_request_id = %s
            ORDER BY decided_at DESC, id DESC
            """,
            (company_id, source_id),
        )
        decisions = cur.fetchall()

        deliverables = []
        signoff_steps = []
        escalations = []

        engagement_id = row.get("engagement_id")
        if engagement_id:
            cur.execute(
                f"""
                SELECT
                    id,
                    deliverable_code,
                    deliverable_name,
                    deliverable_type,
                    status,
                    priority,
                    due_date,
                    notes
                FROM {schema}.engagement_deliverables
                WHERE company_id = %s
                AND engagement_id = %s
                AND is_active = TRUE
                ORDER BY due_date NULLS LAST, deliverable_name ASC
                """,
                (company_id, engagement_id),
            )
            deliverables = cur.fetchall()

            cur.execute(
                f"""
                SELECT
                    id,
                    step_code,
                    step_name,
                    status,
                    due_date,
                    completed_at,
                    notes
                FROM {schema}.engagement_signoff_steps
                WHERE company_id = %s
                AND engagement_id = %s
                AND is_active = TRUE
                ORDER BY due_date NULLS LAST, step_name ASC
                """,
                (company_id, engagement_id),
            )
            signoff_steps = cur.fetchall()

            cur.execute(
                f"""
                SELECT
                    id,
                    title,
                    status,
                    priority,
                    due_date,
                    owner_user_id,
                    resolution_summary
                FROM {schema}.engagement_escalations
                WHERE company_id = %s
                AND engagement_id = %s
                AND is_active = TRUE
                ORDER BY due_date NULLS LAST, id DESC
                """,
                (company_id, engagement_id),
            )
            escalations = cur.fetchall()

        return {
            "summary": row,
            "decisions": decisions,
            "deliverables": deliverables,
            "signoff_steps": signoff_steps,
            "escalations": escalations,
        }

    def apply_approval_center_action(
        self,
        cur,
        company_id: int,
        *,
        queue_type: str,
        source_id: int,
        action: str,
        actor_user_id: int,
        comment: str = "",
        due_date=None,  # ignored
    ):
        schema = self.company_schema(company_id)

        status_map = {
            "approve": "approved",
            "return": "rejected",
            "reject": "rejected",
            "cancel": "cancelled",
            "release": "approved",
            "escalate": "pending",
            "comment": "pending",
        }
        decision_map = {
            "approve": "approve",
            "return": "reassign",
            "reject": "reject",
            "cancel": "cancel",
            "release": "approve",
            "escalate": "comment",
            "comment": "comment",
        }

        new_status = status_map.get(action)
        decision = decision_map.get(action)
        if not new_status or not decision:
            return False

        cur.execute(
            f"""
            UPDATE {schema}.approval_requests
            SET
                status = %s,
                decision_note = CASE
                    WHEN %s <> '' THEN %s
                    ELSE decision_note
                END,
                decided_by_user_id = %s,
                decided_at = NOW(),
                updated_at = NOW()
            WHERE company_id = %s
            AND id = %s
            AND LOWER(COALESCE(module, '')) = %s
            RETURNING id
            """,
            (
                new_status,
                comment,
                comment,
                actor_user_id,
                company_id,
                source_id,
                queue_type,
            ),
        )
        updated = cur.fetchone()
        if not updated:
            return False

        cur.execute(
            f"""
            INSERT INTO {schema}.approval_decisions (
                company_id,
                approval_request_id,
                decision,
                decided_by_user_id,
                decided_at,
                note,
                meta_json
            )
            VALUES (%s, %s, %s, %s, NOW(), %s, '{{}}'::jsonb)
            RETURNING id
            """,
            (
                company_id,
                source_id,
                decision,
                actor_user_id,
                comment or None,
            ),
        )

        return updated

    def update_engagement_escalation(
        self,
        cur,
        company_id: int,
        *,
        escalation_id: int,
        source_type: str = None,
        source_id: int = None,
        escalation_type: str = None,
        severity: str = None,
        title: str = None,
        description: str = None,
        status: str = None,
        assigned_to_user_id: int = None,
        due_date=None,
        updated_by_user_id: int = None,
    ):
        schema = self.company_schema(company_id)

        cur.execute(
            f"""
            UPDATE {schema}.engagement_escalations
            SET
                source_type = COALESCE(%s, source_type),
                source_id = COALESCE(%s, source_id),
                escalation_type = COALESCE(%s, escalation_type),
                severity = COALESCE(%s, severity),
                title = COALESCE(%s, title),
                description = COALESCE(%s, description),
                status = COALESCE(%s, status),
                assigned_to_user_id = COALESCE(%s, assigned_to_user_id),
                due_date = COALESCE(%s, due_date),
                updated_by_user_id = COALESCE(%s, updated_by_user_id),
                resolved_at = CASE
                    WHEN %s IN ('resolved', 'closed') AND resolved_at IS NULL THEN NOW()
                    ELSE resolved_at
                END,
                closed_at = CASE
                    WHEN %s = 'closed' AND closed_at IS NULL THEN NOW()
                    ELSE closed_at
                END
            WHERE company_id = %s
            AND id = %s
            """,
            (
                source_type,
                source_id,
                escalation_type,
                severity,
                title,
                description,
                status,
                assigned_to_user_id,
                due_date,
                updated_by_user_id,
                status,
                status,
                company_id,
                escalation_id,
            ),
        )
        return cur.rowcount
    
    # ============================================================
    # Engagement Acceptance
    # ============================================================

    def list_engagement_acceptance_items(
        self,
        cur,
        company_id: int,
        *,
        engagement_id: int = None,
        customer_id: int = None,
        acceptance_type: str = "",
        status: str = "",
        risk_level: str = "",  # kept for old callers; now resolved from latest R&I
        assigned_partner_user_id: int = None,
        q: str = "",
        active_only: bool = True,
        limit: int = 100,
        offset: int = 0,
    ):
        schema = self.company_schema(company_id)

        sql = f"""
            SELECT
                ea.id,
                ea.company_id,
                ea.engagement_id,
                ea.acceptance_type,
                ea.status,
                ea.decision,
                ea.decision_date,
                ea.decision_notes,
                ea.valid_from,
                ea.valid_to,
                ea.requested_by_user_id,
                ea.assigned_partner_user_id,
                ea.decided_by_user_id,
                ea.is_active,
                ea.created_at,
                ea.updated_at,

                ria.id AS risk_assessment_id,
                ria.status AS risk_assessment_status,
                ria.risk_level,
                ria.independence_cleared,
                ria.conflicts_checked,
                ria.competence_confirmed,
                ria.capacity_confirmed,
                ria.preconditions_notes AS risk_preconditions_notes,
                ria.decision_notes AS risk_decision_notes,

                e.engagement_code,
                e.engagement_name,
                e.engagement_type,
                e.customer_id,
                e.status AS engagement_status,
                c.name AS customer_name,

                TRIM(CONCAT(COALESCE(req.first_name, ''),
                    CASE WHEN COALESCE(req.last_name, '') <> '' THEN ' ' || req.last_name ELSE '' END
                )) AS requested_by_user_name,

                TRIM(CONCAT(COALESCE(partner.first_name, ''),
                    CASE WHEN COALESCE(partner.last_name, '') <> '' THEN ' ' || partner.last_name ELSE '' END
                )) AS assigned_partner_user_name,

                TRIM(CONCAT(COALESCE(decider.first_name, ''),
                    CASE WHEN COALESCE(decider.last_name, '') <> '' THEN ' ' || decider.last_name ELSE '' END
                )) AS decided_by_user_name

            FROM {schema}.engagement_acceptance ea

            JOIN {schema}.engagements e
              ON e.id = ea.engagement_id
             AND e.company_id = ea.company_id

            JOIN {schema}.customers c
              ON c.id = e.customer_id

            LEFT JOIN LATERAL (
                SELECT r.*
                FROM {schema}.risk_independence_assessments r
                WHERE r.company_id = ea.company_id
                  AND r.engagement_id = ea.engagement_id
                  AND r.is_active = TRUE
                ORDER BY
                    CASE r.status
                        WHEN 'approved' THEN 1
                        WHEN 'under_review' THEN 2
                        WHEN 'submitted' THEN 3
                        WHEN 'returned' THEN 4
                        WHEN 'draft' THEN 5
                        WHEN 'declined' THEN 6
                        ELSE 99
                    END,
                    r.updated_at DESC,
                    r.id DESC
                LIMIT 1
            ) ria ON TRUE

            LEFT JOIN public.users req
              ON req.id = ea.requested_by_user_id

            LEFT JOIN public.users partner
              ON partner.id = ea.assigned_partner_user_id

            LEFT JOIN public.users decider
              ON decider.id = ea.decided_by_user_id

            WHERE ea.company_id = %s
              AND (%s = FALSE OR ea.is_active = TRUE)
              AND (%s IS NULL OR ea.engagement_id = %s)
              AND (%s IS NULL OR e.customer_id = %s)
              AND (%s = '' OR LOWER(ea.acceptance_type) = LOWER(%s))
              AND (%s = '' OR LOWER(ea.status) = LOWER(%s))
              AND (%s = '' OR LOWER(COALESCE(ria.risk_level, 'normal')) = LOWER(%s))
              AND (%s IS NULL OR ea.assigned_partner_user_id = %s)
              AND (
                    %s = ''
                    OR COALESCE(e.engagement_name, '') ILIKE %s
                    OR COALESCE(e.engagement_code, '') ILIKE %s
                    OR COALESCE(c.name, '') ILIKE %s
                    OR COALESCE(ea.decision_notes, '') ILIKE %s
                    OR COALESCE(ria.client_risk_notes, '') ILIKE %s
                    OR COALESCE(ria.service_complexity_notes, '') ILIKE %s
                    OR COALESCE(ria.decision_notes, '') ILIKE %s
              )
            ORDER BY
                CASE ea.status
                    WHEN 'under_review' THEN 1
                    WHEN 'submitted' THEN 2
                    WHEN 'returned' THEN 3
                    WHEN 'draft' THEN 4
                    WHEN 'approved' THEN 5
                    WHEN 'declined' THEN 6
                    ELSE 99
                END,
                ea.updated_at DESC,
                ea.id DESC
            LIMIT %s OFFSET %s
        """

        like = f"%{(q or '').strip()}%"
        cur.execute(
            sql,
            (
                company_id,
                active_only,
                engagement_id, engagement_id,
                customer_id, customer_id,
                acceptance_type.strip(), acceptance_type.strip(),
                status.strip(), status.strip(),
                risk_level.strip(), risk_level.strip(),
                assigned_partner_user_id, assigned_partner_user_id,
                (q or "").strip(),
                like, like, like, like, like, like, like,
                limit, offset,
            ),
        )
        return cur.fetchall()


