    def apply_engagement_acceptance_decision(
        self,
        cur,
        company_id: int,
        *,
        acceptance_id: int,
        action: str,
        actor_user_id: int,
        decision_notes: str = "",
    ):
        schema = self.company_schema(company_id)
        action = (action or "").strip().lower()

        if action == "submit":
            sql = f"""
                UPDATE {schema}.engagement_acceptance
                SET
                    status = 'submitted',
                    decision = NULL,
                    decision_date = NULL,
                    decided_by_user_id = NULL,
                    updated_by_user_id = %s,
                    updated_at = NOW()
                WHERE company_id = %s AND id = %s AND is_active = TRUE
                RETURNING id
            """
            cur.execute(sql, (actor_user_id, company_id, acceptance_id))
            return cur.fetchone()

        if action == "approve":
            sql = f"""
                UPDATE {schema}.engagement_acceptance
                SET
                    status = 'approved',
                    decision = 'approve',
                    decision_date = NOW(),
                    decided_by_user_id = %s,
                    decision_notes = %s,
                    updated_by_user_id = %s,
                    updated_at = NOW()
                WHERE company_id = %s AND id = %s AND is_active = TRUE
                RETURNING id
            """
            cur.execute(sql, (actor_user_id, (decision_notes or "").strip(), actor_user_id, company_id, acceptance_id))
            return cur.fetchone()

        if action == "decline":
            sql = f"""
                UPDATE {schema}.engagement_acceptance
                SET
                    status = 'declined',
                    decision = 'decline',
                    decision_date = NOW(),
                    decided_by_user_id = %s,
                    decision_notes = %s,
                    updated_by_user_id = %s,
                    updated_at = NOW()
                WHERE company_id = %s AND id = %s AND is_active = TRUE
                RETURNING id
            """
            cur.execute(sql, (actor_user_id, (decision_notes or "").strip(), actor_user_id, company_id, acceptance_id))
            return cur.fetchone()

        if action == "return":
            sql = f"""
                UPDATE {schema}.engagement_acceptance
                SET
                    status = 'returned',
                    decision = 'return',
                    decision_date = NOW(),
                    decided_by_user_id = %s,
                    decision_notes = %s,
                    updated_by_user_id = %s,
                    updated_at = NOW()
                WHERE company_id = %s AND id = %s AND is_active = TRUE
                RETURNING id
            """
            cur.execute(sql, (actor_user_id, (decision_notes or "").strip(), actor_user_id, company_id, acceptance_id))
            return cur.fetchone()

        raise ValueError("Unsupported action.")

    def create_engagement_acceptance_item(
        self,
        cur,
        company_id: int,
        *,
        engagement_id: int,
        acceptance_type: str = "acceptance",
        status: str = "draft",
        requested_by_user_id: int = None,
        assigned_partner_user_id: int = None,
        decision_notes: str = None,
        valid_from=None,
        valid_to=None,
        created_by_user_id: int = None,
        updated_by_user_id: int = None,
        **_legacy_ignored,
    ):
        schema = self.company_schema(company_id)

        cur.execute(
            f"""
            INSERT INTO {schema}.engagement_acceptance (
                company_id,
                engagement_id,
                acceptance_type,
                status,
                requested_by_user_id,
                assigned_partner_user_id,
                decision_notes,
                valid_from,
                valid_to,
                created_by_user_id,
                updated_by_user_id
            )
            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
            RETURNING id
            """,
            (
                company_id,
                engagement_id,
                (acceptance_type or "acceptance").strip().lower(),
                (status or "draft").strip().lower(),
                requested_by_user_id,
                assigned_partner_user_id,
                decision_notes,
                valid_from,
                valid_to,
                created_by_user_id,
                updated_by_user_id,
            ),
        )
        row = cur.fetchone()
        return row["id"] if row else None

    def create_engagement_acceptance(self, *args, user_id: int | None = None, **kwargs) -> dict | int:
        """
        Supports both:

        1) Managed transaction:
        create_engagement_acceptance(company_id, data, user_id=...)

        2) Existing transaction/cursor:
        create_engagement_acceptance(cur, company_id, engagement_id=..., ...)
        """

        def build_acceptance_payload(data: dict) -> dict:
            data = data or {}

            return {
                "engagement_id": int(data.get("engagement_id") or 0),
                "acceptance_type": data.get("acceptance_type") or "acceptance",
                "status": data.get("status") or "draft",

                "requested_by_user_id": (
                    data.get("requested_by_user_id")
                    or data.get("actor_user_id")
                    or user_id
                ),
                "assigned_partner_user_id": data.get("assigned_partner_user_id"),

                # Acceptance assessment fields
                "risk_level": data.get("risk_level") or "normal",
                "independence_cleared": bool(data.get("independence_cleared")),
                "conflicts_checked": bool(data.get("conflicts_checked")),
                "competence_confirmed": bool(data.get("competence_confirmed")),
                "capacity_confirmed": bool(data.get("capacity_confirmed")),
                "client_risk_notes": data.get("client_risk_notes") or "",
                "service_complexity_notes": data.get("service_complexity_notes") or "",
                "preconditions_notes": data.get("preconditions_notes") or "",
                "decision_notes": data.get("decision_notes") or "",

                "valid_from": data.get("valid_from"),
                "valid_to": data.get("valid_to"),

                "created_by_user_id": (
                    data.get("created_by_user_id")
                    or data.get("actor_user_id")
                    or user_id
                ),
                "updated_by_user_id": (
                    data.get("updated_by_user_id")
                    or data.get("actor_user_id")
                    or user_id
                ),
            }

        # STYLE 2: create_engagement_acceptance(cur, company_id, ...)
        if len(args) >= 2 and hasattr(args[0], "execute"):
            cur = args[0]
            company_id = int(args[1])
            data = build_acceptance_payload(kwargs)

            if data["engagement_id"] <= 0:
                raise ValueError("engagement_id is required")

            return self.create_engagement_acceptance_item(
                cur,
                company_id,
                **data,
            )

        # STYLE 1: create_engagement_acceptance(company_id, data, user_id=...)
        if len(args) < 2:
            raise TypeError("create_engagement_acceptance requires company_id and data")

        company_id = int(args[0])
        data = build_acceptance_payload(args[1])
        schema = self.company_schema(company_id)

        if data["engagement_id"] <= 0:
            raise ValueError("engagement_id is required")

        with self._conn_cursor() as (conn, cur):
            item_id = self.create_engagement_acceptance_item(
                cur,
                company_id,
                **data,
            )

            row = self.fetch_one(
                f"""
                SELECT *
                FROM {schema}.engagement_acceptance
                WHERE company_id = %s AND id = %s
                LIMIT 1
                """,
                (company_id, int(item_id)),
                cur=cur,
            )

            conn.commit()
            return row

    def update_engagement_acceptance(
        self,
        company_id: int,
        acceptance_id: int,
        data: dict,
        *,
        user_id: int | None = None,
    ) -> dict:
        schema = self.company_schema(company_id)
        data = data or {}

        allowed = {
            "acceptance_type",
            "status",
            "requested_by_user_id",
            "assigned_partner_user_id",
            "decision_notes",
            "valid_from",
            "valid_to",
        }

        sets = []
        params = []

        for key in allowed:
            if key in data:
                sets.append(f"{key}=%s")
                value = data.get(key)

                if key in {"acceptance_type", "status"} and value is not None:
                    value = str(value).strip().lower()

                params.append(value)

        sets.append("updated_by_user_id=%s")
        params.append(data.get("updated_by_user_id") or user_id)

        sets.append("updated_at=NOW()")

        if not sets:
            return self.fetch_one(
                f"""
                SELECT *
                FROM {schema}.engagement_acceptance
                WHERE company_id=%s AND id=%s
                LIMIT 1
                """,
                (int(company_id), int(acceptance_id)),
            )

        params.extend([int(company_id), int(acceptance_id)])

        with self._conn_cursor() as (conn, cur):
            row = self.fetch_one(
                f"""
                UPDATE {schema}.engagement_acceptance
                SET {", ".join(sets)}
                WHERE company_id=%s AND id=%s
                RETURNING *
                """,
                tuple(params),
                cur=cur,
            )

            if not row:
                raise ValueError("engagement_acceptance not found")

            conn.commit()
            return row
    
    def update_engagement_acceptance_item(
        self,
        cur,
        company_id: int,
        *,
        acceptance_id: int,
        acceptance_type: str = None,
        status: str = None,
        assigned_partner_user_id: int = None,
        decision_notes: str = None,
        valid_from=None,
        valid_to=None,
        updated_by_user_id: int = None,
        **_legacy_ignored,
    ):
        schema = self.company_schema(company_id)

        cur.execute(
            f"""
            UPDATE {schema}.engagement_acceptance
            SET
                acceptance_type = COALESCE(%s, acceptance_type),
                status = COALESCE(%s, status),
                assigned_partner_user_id = COALESCE(%s, assigned_partner_user_id),
                decision_notes = COALESCE(%s, decision_notes),
                valid_from = COALESCE(%s, valid_from),
                valid_to = COALESCE(%s, valid_to),
                updated_by_user_id = COALESCE(%s, updated_by_user_id),
                updated_at = NOW()
            WHERE company_id = %s
              AND id = %s
              AND is_active = TRUE
            RETURNING id
            """,
            (
                acceptance_type.strip().lower() if isinstance(acceptance_type, str) else acceptance_type,
                status.strip().lower() if isinstance(status, str) else status,
                assigned_partner_user_id,
                decision_notes,
                valid_from,
                valid_to,
                updated_by_user_id,
                company_id,
                acceptance_id,
            ),
        )
        return cur.rowcount


    def decide_engagement_acceptance_item(
        self,
        cur,
        company_id: int,
        *,
        acceptance_id: int,
        decision: str,
        decision_notes: str = None,
        decided_by_user_id: int = None,
    ):
        schema = self.company_schema(company_id)

        normalized = (decision or "").strip().lower()
        if normalized not in ("approve", "decline", "return"):
            raise ValueError("Invalid decision. Use approve, decline, or return.")

        mapped_status = {
            "approve": "approved",
            "decline": "declined",
            "return": "returned",
        }[normalized]

        cur.execute(
            f"""
            UPDATE {schema}.engagement_acceptance
            SET
                decision = %s,
                status = %s,
                decision_date = NOW(),
                decision_notes = COALESCE(%s, decision_notes),
                decided_by_user_id = %s,
                updated_by_user_id = %s,
                updated_at = NOW()
            WHERE company_id = %s
              AND id = %s
              AND is_active = TRUE
            RETURNING id
            """,
            (
                normalized,
                mapped_status,
                decision_notes,
                decided_by_user_id,
                decided_by_user_id,
                company_id,
                acceptance_id,
            ),
        )
        return cur.rowcount


    # ============================================================
    # Risk & Independence Assessments
    # ============================================================

    def get_risk_independence_summary(
        self,
        cur,
        company_id: int,
        *,
        engagement_id: int = None,
        customer_id: int = None,
        active_only: bool = True,
    ):
        schema = self.company_schema(company_id)

        cur.execute(
            f"""
            SELECT
                COUNT(*) FILTER (WHERE (%s = FALSE OR ria.is_active = TRUE)) AS total_items,
                COUNT(*) FILTER (
                    WHERE (%s = FALSE OR ria.is_active = TRUE)
                    AND ria.status IN ('submitted', 'under_review')
                ) AS open_reviews,
                COUNT(*) FILTER (
                    WHERE (%s = FALSE OR ria.is_active = TRUE)
                    AND ria.risk_level IN ('high', 'critical')
                ) AS high_risk_items,
                COUNT(*) FILTER (
                    WHERE (%s = FALSE OR ria.is_active = TRUE)
                    AND (
                        COALESCE(ria.independence_cleared, FALSE) = FALSE
                        OR COALESCE(ria.conflicts_checked, FALSE) = FALSE
                    )
                ) AS independence_gaps,
                COUNT(*) FILTER (
                    WHERE (%s = FALSE OR ria.is_active = TRUE)
                    AND COALESCE(BTRIM(ria.preconditions_notes), '') <> ''
                ) AS items_with_conditions
            FROM {schema}.risk_independence_assessments ria
            JOIN {schema}.engagements e
              ON e.id = ria.engagement_id
             AND e.company_id = ria.company_id
            WHERE ria.company_id = %s
              AND (%s IS NULL OR ria.engagement_id = %s)
              AND (%s IS NULL OR e.customer_id = %s)
            """,
            (
                active_only,
                active_only,
                active_only,
                active_only,
                active_only,
                company_id,
                engagement_id, engagement_id,
                customer_id, customer_id,
            ),
        )
        return cur.fetchone()


    def list_risk_independence_items(
        self,
        cur,
        company_id: int,
        *,
        engagement_id: int = None,
        customer_id: int = None,
        status: str = "",
        risk_level: str = "",
        q: str = "",
        active_only: bool = True,
        limit: int = 100,
        offset: int = 0,
    ):
        schema = self.company_schema(company_id)

        sql = f"""
            SELECT
                ria.*,
                e.engagement_code,
                e.engagement_name,
                e.engagement_type,
                e.customer_id,
                e.status AS engagement_status,
                c.name AS customer_name,

                TRIM(CONCAT(COALESCE(partner.first_name, ''),
                    CASE WHEN COALESCE(partner.last_name, '') <> '' THEN ' ' || partner.last_name ELSE '' END
                )) AS assigned_partner_user_name,

                TRIM(CONCAT(COALESCE(reviewer.first_name, ''),
                    CASE WHEN COALESCE(reviewer.last_name, '') <> '' THEN ' ' || reviewer.last_name ELSE '' END
                )) AS reviewed_by_user_name

            FROM {schema}.risk_independence_assessments ria

            JOIN {schema}.engagements e
              ON e.id = ria.engagement_id
             AND e.company_id = ria.company_id

            JOIN {schema}.customers c
              ON c.id = e.customer_id

            LEFT JOIN public.users partner
              ON partner.id = ria.assigned_partner_user_id

            LEFT JOIN public.users reviewer
              ON reviewer.id = ria.reviewed_by_user_id

            WHERE ria.company_id = %s
              AND (%s = FALSE OR ria.is_active = TRUE)
              AND (%s IS NULL OR ria.engagement_id = %s)
              AND (%s IS NULL OR e.customer_id = %s)
              AND (%s = '' OR LOWER(ria.status) = LOWER(%s))
              AND (%s = '' OR LOWER(ria.risk_level) = LOWER(%s))
              AND (
                    %s = ''
                    OR COALESCE(e.engagement_name, '') ILIKE %s
                    OR COALESCE(e.engagement_code, '') ILIKE %s
                    OR COALESCE(c.name, '') ILIKE %s
                    OR COALESCE(ria.client_risk_notes, '') ILIKE %s
                    OR COALESCE(ria.service_complexity_notes, '') ILIKE %s
                    OR COALESCE(ria.decision_notes, '') ILIKE %s
              )
            ORDER BY
                CASE ria.status
                    WHEN 'under_review' THEN 1
                    WHEN 'submitted' THEN 2
                    WHEN 'returned' THEN 3
                    WHEN 'draft' THEN 4
                    WHEN 'approved' THEN 5
                    WHEN 'declined' THEN 6
                    ELSE 99
                END,
                ria.updated_at DESC,
                ria.id DESC
            LIMIT %s OFFSET %s
        """

        like = f"%{(q or '').strip()}%"
        cur.execute(
            sql,
            (
                company_id,
                active_only,
                engagement_id, engagement_id,
                customer_id, customer_id,
                status.strip(), status.strip(),
                risk_level.strip(), risk_level.strip(),
                (q or "").strip(),
                like, like, like, like, like, like,
                limit, offset,
            ),
        )
        return cur.fetchall()


    def get_risk_independence_assessment_detail(
        self,
        cur,
        company_id: int,
        *,
        assessment_id: int,
    ):
        schema = self.company_schema(company_id)

        cur.execute(
            f"""
            SELECT
                ria.*,
                e.engagement_code,
                e.engagement_name,
                e.engagement_type,
                e.customer_id,
                e.status AS engagement_status,
                c.name AS customer_name,

                TRIM(CONCAT(COALESCE(partner.first_name, ''),
                    CASE WHEN COALESCE(partner.last_name, '') <> '' THEN ' ' || partner.last_name ELSE '' END
                )) AS assigned_partner_user_name,

                TRIM(CONCAT(COALESCE(reviewer.first_name, ''),
                    CASE WHEN COALESCE(reviewer.last_name, '') <> '' THEN ' ' || reviewer.last_name ELSE '' END
                )) AS reviewed_by_user_name

            FROM {schema}.risk_independence_assessments ria

            JOIN {schema}.engagements e
              ON e.id = ria.engagement_id
             AND e.company_id = ria.company_id

            JOIN {schema}.customers c
              ON c.id = e.customer_id

            LEFT JOIN public.users partner
              ON partner.id = ria.assigned_partner_user_id

            LEFT JOIN public.users reviewer
              ON reviewer.id = ria.reviewed_by_user_id

            WHERE ria.company_id = %s
              AND ria.id = %s
            LIMIT 1
            """,
            (company_id, assessment_id),
        )
        return cur.fetchone()


