    def decide_risk_independence_assessment(
        self,
        cur,
        company_id: int,
        *,
        assessment_id: int,
        decision: str,
        decision_notes: str = None,
        reviewed_by_user_id: int = None,
    ):
        schema = self.company_schema(company_id)

        normalized = (decision or "").strip().lower()
        if normalized not in ("approve", "decline", "return"):
            raise ValueError("Invalid decision. Use approve, decline, or return.")

        mapped_status = {
            "approve": "approved",
            "decline": "declined",
            "return": "returned",
        }[normalized]

        cur.execute(
            f"""
            UPDATE {schema}.risk_independence_assessments
            SET
                decision = %s,
                status = %s,
                decision_date = NOW(),
                decision_notes = COALESCE(%s, decision_notes),
                reviewed_by_user_id = %s,
                updated_by_user_id = %s,
                updated_at = NOW()
            WHERE company_id = %s
              AND id = %s
              AND is_active = TRUE
            RETURNING id
            """,
            (
                normalized,
                mapped_status,
                decision_notes,
                reviewed_by_user_id,
                reviewed_by_user_id,
                company_id,
                assessment_id,
            ),
        )
        return cur.rowcount
    
