    def find_project_wip_account_code(self, company_id: int, *, cur) -> str | None:
        schema = self.company_schema(company_id)

        cur.execute(
            f"""
            SELECT code
            FROM {schema}.coa
            WHERE company_id=%s
            AND posting=true
            AND role='project_wip'
            ORDER BY id ASC
            LIMIT 1
            """,
            (int(company_id),),
        )

        row = cur.fetchone()
        if row:
            return (row.get("code") if isinstance(row, dict) else row[0]) or None

        return self.find_default_inventory_account_code(
            company_id,
            cur=cur,
            prefer_project_wip=True,
        )

    def issue_inventory_to_project(
        self,
        company_id: int,
        *,
        project_id: int,
        tx_date,
        lines: list[dict],
        task_id: int | None = None,
        cost_code_id: int | None = None,
        usage_type: str = "consumed",
        ref: str | None = None,
        notes: str | None = None,
        created_by: int | None = None,
        post_now: bool = True,
    ) -> dict:
        schema = self.company_schema(company_id)

        if not lines or not isinstance(lines, list):
            raise ValueError("lines required")

        if hasattr(tx_date, "isoformat"):
            tx_date = tx_date.isoformat()[:10]
        else:
            tx_date = str(tx_date or "")[:10]

        if not tx_date:
            raise ValueError("tx_date is required")

        ref = (ref or f"PMI-{int(project_id)}-{tx_date}").strip()
        usage_type = (usage_type or "consumed").strip().lower()

        def money(x) -> float:
            from decimal import Decimal, ROUND_HALF_UP
            return float(Decimal(str(x or 0)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))

        def _to_int(v, default=None):
            try:
                if v in (None, ""):
                    return default
                return int(v)
            except Exception:
                return default

        def _to_float(v, default=0.0):
            try:
                if v in (None, ""):
                    return default
                return float(str(v).replace(",", "").strip())
            except Exception:
                return default

        with self._conn_cursor() as (conn, cur):
            # 1) Validate project
            project = self.fetch_one(
                f"""
                SELECT *
                FROM {schema}.projects
                WHERE company_id=%s AND id=%s
                FOR UPDATE
                """,
                (int(company_id), int(project_id)),
                cur=cur,
            )

            if not project:
                raise ValueError("PROJECT_NOT_FOUND")

            if str(project.get("status") or "").lower() in ("cancelled", "closed"):
                raise ValueError("PROJECT_CLOSED_OR_CANCELLED")

            # Validate header task/cost code links
            header_task_id = _to_int(task_id)
            header_cost_code_id = _to_int(cost_code_id)

            self.validate_project_task(
                company_id,
                project_id=int(project_id),
                task_id=header_task_id,
                cur=cur,
            )

            self.validate_project_cost_code(
                company_id,
                header_cost_code_id,
                cur=cur,
            )

            # 2) Resolve project debit account according to accounting mode
            accounting_mode = str(project.get("accounting_mode") or "contract").strip().lower()

            if not bool(project.get("inventory_enabled", True)):
                raise ValueError("PROJECT_INVENTORY_DISABLED")

            if accounting_mode in {"contract", "wip", "capital"}:
                project_debit_raw = (
                    project.get("wip_account_code")
                    or self.find_project_wip_account_code(company_id, cur=cur)
                    or ""
                ).strip()
                missing_error = "PROJECT_WIP_ACCOUNT_NOT_CONFIGURED"
            elif accounting_mode in {"expense", "none"}:
                project_debit_raw = (project.get("cost_account_code") or "").strip()
                missing_error = "PROJECT_COST_ACCOUNT_NOT_CONFIGURED"
            else:
                raise ValueError(f"INVALID_PROJECT_ACCOUNTING_MODE|{accounting_mode}")

            if not project_debit_raw:
                raise ValueError(missing_error)

            debit_row = self.get_account_row_for_posting(company_id, project_debit_raw)
            if not debit_row:
                raise ValueError(f"PROJECT_DEBIT_ACCOUNT_NOT_FOUND|{project_debit_raw}")

            project_debit_account = (debit_row[1] or project_debit_raw).strip()
            # 3) Create inventory_tx header
            cur.execute(
                f"""
                INSERT INTO {schema}.inventory_tx (
                    company_id, tx_date, tx_type, status, ref, notes,
                    source, source_id, created_by,
                    project_id, task_id, cost_code_id, usage_type,
                    created_at, updated_at
                )
                VALUES (
                    %s,%s,'issue_to_project','draft',%s,%s,
                    'project',%s,%s,
                    %s,%s,%s,%s,
                    NOW(),NOW()
                )
                RETURNING id
                """,
                (
                    int(company_id),
                    tx_date,
                    ref,
                    notes,
                    int(project_id),
                    created_by,
                    int(project_id),
                    header_task_id,
                    header_cost_code_id,
                    usage_type,
                ),
            )

            row = cur.fetchone() or {}
            tx_id = int(row.get("id") or 0)
            if tx_id <= 0:
                raise ValueError("FAILED_TO_CREATE_PROJECT_ISSUE_TX")

            inv_credit_totals: dict[str, float] = {}
            total_issue_cost = 0.0

            # 4) Lines + costing
            for idx, ln in enumerate(lines, start=1):
                item_id = _to_int(ln.get("item_id") or ln.get("itemId"), 0)
                qty = _to_float(ln.get("qty") or ln.get("quantity"), 0.0)

                if item_id <= 0:
                    raise ValueError(f"line {idx}: item_id required")

                if qty <= 0:
                    raise ValueError(f"line {idx}: qty must be > 0")

                line_task_id = _to_int(ln.get("task_id") or ln.get("taskId"), task_id)
                line_cost_code_id = _to_int(ln.get("cost_code_id") or ln.get("costCodeId"), cost_code_id)
                line_usage_type = (ln.get("usage_type") or ln.get("usageType") or usage_type or "consumed").strip().lower()

                self.validate_project_task(
                    company_id,
                    project_id=int(project_id),
                    task_id=line_task_id,
                    cur=cur,
                )

                self.validate_project_cost_code(
                    company_id,
                    line_cost_code_id,
                    cur=cur,
                )

                # Load item
                item = self.fetch_one(
                    f"""
                    SELECT *
                    FROM {schema}.inventory_items
                    WHERE company_id=%s AND id=%s
                    LIMIT 1
                    """,
                    (int(company_id), int(item_id)),
                    cur=cur,
                )

                if not item:
                    raise ValueError(f"INVENTORY_ITEM_NOT_FOUND|item_id={item_id}")

                if item.get("is_active") is False:
                    raise ValueError(f"INVENTORY_ITEM_INACTIVE|item_id={item_id}")

                track_stock = bool(item.get("track_stock", True))

                inv_raw = (item.get("inventory_account") or "").strip()

                if not inv_raw:
                    inv_raw = (self.find_default_inventory_account_code(company_id, cur=cur) or "").strip()

                if not inv_raw:
                    raise ValueError(f"ITEM_INVENTORY_ACCOUNT_MISSING|item_id={item_id}")

                inv_row = self.get_account_row_for_posting(company_id, inv_raw)
                if not inv_row:
                    raise ValueError(f"INVENTORY_ACCOUNT_NOT_FOUND|item_id={item_id}|{inv_raw}")

                inventory_account = (inv_row[1] or inv_raw).strip()

                valuation_method = (item.get("valuation_method") or "AVG").strip().upper()
                if valuation_method not in ("AVG", "FIFO"):
                    valuation_method = "AVG"

                if track_stock:
                    onhand = self._inventory_onhand_cur(company_id, item_id, cur)
                    if qty > onhand:
                        raise ValueError(
                            f"INSUFFICIENT_STOCK|item_id={item_id}|onhand={onhand}|requested={qty}"
                        )

                # Cost + consume stock
                if valuation_method == "FIFO":
                    line_cost = money(
                        self.fifo_consume(
                            company_id,
                            item_id=item_id,
                            qty_out=qty,
                            tx_date=tx_date,
                            source="project_material_issue",
                            source_id=int(tx_id),
                            posted_journal_id=None,
                            cur=cur,
                        )
                    )
                else:
                    unit_cost = money(self._inventory_avg_cost_cur(company_id, item_id, cur))
                    if unit_cost <= 0:
                        unit_cost = money(item.get("purchase_cost") or 0)

                    if unit_cost <= 0:
                        raise ValueError(f"MISSING_COST|item_id={item_id}")

                    line_cost = money(qty * unit_cost)

                    if track_stock:
                        cur.execute(
                            f"""
                            INSERT INTO {schema}.inventory_layers (
                                company_id, item_id, tx_date,
                                qty_in, qty_out, unit_cost,
                                ref, source, source_id, tx_id,
                                created_at
                            )
                            VALUES (
                                %s,%s,%s,
                                0,%s,%s,
                                %s,'project_material_issue',%s,%s,
                                NOW()
                            )
                            """,
                            (
                                int(company_id),
                                int(item_id),
                                tx_date,
                                float(qty),
                                float(unit_cost),
                                ref,
                                int(tx_id),
                                int(tx_id),
                            ),
                        )

                if line_cost <= 0:
                    raise ValueError(f"ZERO_ISSUE_COST|item_id={item_id}")

                unit_cost_for_line = money(line_cost / qty)

                # Insert tx line
                cur.execute(
                    f"""
                    INSERT INTO {schema}.inventory_tx_lines (
                        company_id, tx_id, line_no, item_id,
                        qty, unit_cost, unit_price,
                        vat_code, memo,
                        project_id, task_id, cost_code_id, usage_type,
                        created_at
                    )
                    VALUES (
                        %s,%s,%s,%s,
                        %s,%s,0,
                        %s,%s,
                        %s,%s,%s,%s,
                        NOW()
                    )
                    """,
                    (
                        int(company_id),
                        int(tx_id),
                        int(idx),
                        int(item_id),
                        float(qty),
                        float(unit_cost_for_line),
                        ln.get("vat_code") or ln.get("vatCode"),
                        ln.get("memo"),
                        int(project_id),
                        line_task_id,
                        line_cost_code_id,
                        line_usage_type,
                    ),
                )

                inv_credit_totals[inventory_account] = money(
                    inv_credit_totals.get(inventory_account, 0.0) + line_cost
                )
                total_issue_cost = money(total_issue_cost + line_cost)

            if total_issue_cost <= 0:
                raise ValueError("PROJECT_ISSUE_TOTAL_IS_ZERO")

            journal_id = None

            # 5) Post journal using your post_journal()
            if post_now:
                journal_lines = [
                    {
                        "account_code": project_debit_account,
                        "debit": total_issue_cost,
                        "credit": 0.0,
                        "memo": f"Materials issued to project {project.get('project_code') or project_id}",
                    }
                ]

                for acct, amt in inv_credit_totals.items():
                    if amt <= 0:
                        continue
                    journal_lines.append({
                        "account_code": acct,
                        "debit": 0.0,
                        "credit": amt,
                        "memo": "Inventory issued to project",
                    })

                journal_id = self.post_journal(
                    company_id,
                    {
                        "date": tx_date,
                        "ref": ref,
                        "description": f"Project material issue #{tx_id}",
                        "source": "project_material_issue",
                        "source_id": int(tx_id),
                        "source_table": "inventory_tx",
                        "module_name": "inventory",
                        "event_type": "posted",
                        "engagement_company_id": project.get("engagement_company_id") or project.get("source_company_id"),
                        "engagement_id": project.get("engagement_id"),
                        "created_by_user_id": created_by,
                        "updated_by_user_id": created_by,
                        "prepared_by_user_id": created_by,
                        "lines": journal_lines,
                    },
                    cur=cur,
                    conn=conn,
                )

                cur.execute(
                    f"""
                    UPDATE {schema}.inventory_tx
                    SET status='posted',
                        posted_journal_id=%s,
                        posted_at=NOW(),
                        posted_by=%s,
                        updated_at=NOW()
                    WHERE company_id=%s AND id=%s
                    """,
                    (
                        int(journal_id),
                        created_by,
                        int(company_id),
                        int(tx_id),
                    ),
                )

                cur.execute(
                    f"""
                    UPDATE {schema}.inventory_layers
                    SET posted_journal_id=%s
                    WHERE company_id=%s
                    AND source='project_material_issue'
                    AND source_id=%s
                    """,
                    (
                        int(journal_id),
                        int(company_id),
                        int(tx_id),
                    ),
                )

                cur.execute(
                    f"""
                    UPDATE {schema}.inventory_fifo_allocations
                    SET posted_journal_id=%s
                    WHERE company_id=%s
                    AND source='project_material_issue'
                    AND source_id=%s
                    """,
                    (
                        int(journal_id),
                        int(company_id),
                        int(tx_id),
                    ),
                )

            return {
                "ok": True,
                "project_id": int(project_id),
                "inventory_tx_id": int(tx_id),
                "journal_id": int(journal_id) if journal_id else None,
                "total_cost": total_issue_cost,
            }
        
    def list_project_budget_lines_all(
        self,
        company_id: int,
        *,
        project_id: int | None = None,
        q: str = "",
        limit: int = 100,
        offset: int = 0,
    ) -> list[dict]:
        schema = self.company_schema(company_id)

        where = [
            "b.company_id = %s",
            "COALESCE(b.is_archived, FALSE) = FALSE",
        ]
        params: list[Any] = [int(company_id)]

        if project_id:
            where.append("b.project_id = %s")
            params.append(int(project_id))

        if q:
            like = f"%{q.strip()}%"
            where.append("""
                (
                    p.project_code ILIKE %s
                    OR p.project_name ILIKE %s
                    OR b.description ILIKE %s
                    OR b.cost_code ILIKE %s
                    OR cc.code ILIKE %s
                    OR cc.name ILIKE %s
                )
            """)
            params.extend([like, like, like, like, like, like])

        params.extend([int(limit), int(offset)])

        return self.fetch_all(
            f"""
            SELECT
                b.*,
                COALESCE(NULLIF(b.cost_code, ''), cc.code) AS cost_code,
                b.cost_code AS budget_cost_code,
                cc.code AS linked_cost_code,
                cc.name AS cost_code_name,
                cc.cost_type,
                p.project_code,
                p.project_name,
                c.name AS customer_name,
                t.task_code,
                t.task_name
            FROM {schema}.project_budget_lines b
            JOIN {schema}.projects p
                ON p.company_id = b.company_id
            AND p.id = b.project_id
            LEFT JOIN {schema}.customers c
                ON c.company_id = p.company_id
            AND c.id = p.customer_id
            LEFT JOIN {schema}.project_tasks t
                ON t.company_id = b.company_id
            AND t.id = b.task_id
            LEFT JOIN {schema}.project_cost_codes cc
                ON cc.company_id = b.company_id
            AND cc.id = b.cost_code_id
            WHERE {" AND ".join(where)}
            ORDER BY p.project_code ASC, b.line_no ASC, b.id ASC
            LIMIT %s OFFSET %s
            """,
            tuple(params),
        ) or []

    def list_project_material_issues(
        self,
        company_id: int,
        *,
        project_id: int | None = None,
        q: str = "",
        date_from=None,
        date_to=None,
        limit: int = 100,
        offset: int = 0,
    ) -> list[dict]:
        schema = self.company_schema(company_id)

        where = [
            "tx.company_id = %s",
            "tx.tx_type = 'issue_to_project'",
        ]
        params: list[Any] = [int(company_id)]

        if project_id:
            where.append("tx.project_id = %s")
            params.append(int(project_id))

        if date_from:
            where.append("tx.tx_date >= %s")
            params.append(date_from)

        if date_to:
            where.append("tx.tx_date <= %s")
            params.append(date_to)

        if q:
            like = f"%{q.strip()}%"
            where.append("""
                (
                    tx.ref ILIKE %s
                    OR tx.notes ILIKE %s
                    OR p.project_code ILIKE %s
                    OR p.project_name ILIKE %s
                    OR i.name ILIKE %s
                    OR i.sku ILIKE %s
                )
            """)
            params.extend([like, like, like, like, like, like])

        params.extend([int(limit), int(offset)])

        return self.fetch_all(
            f"""
            SELECT
                tx.id AS tx_id,
                tx.tx_date,
                tx.ref,
                tx.status,
                tx.notes,
                tx.project_id,
                tx.task_id,
                tx.cost_code_id,
                tx.usage_type,
                tx.posted_journal_id,

                p.project_code,
                p.project_name,
                c.name AS customer_name,

                ln.id AS line_id,
                ln.item_id,
                i.sku,
                i.name AS item_name,
                ln.qty,
                ln.unit_cost,
                (COALESCE(ln.qty, 0) * COALESCE(ln.unit_cost, 0)) AS extended_cost,
                ln.memo,

                t.task_code,
                t.task_name,
                cc.code AS cost_code,
                cc.name AS cost_code_name

            FROM {schema}.inventory_tx tx
            LEFT JOIN {schema}.inventory_tx_lines ln
                ON ln.company_id = tx.company_id
            AND ln.tx_id = tx.id
            LEFT JOIN {schema}.inventory_items i
                ON i.company_id = ln.company_id
            AND i.id = ln.item_id
            LEFT JOIN {schema}.projects p
                ON p.company_id = tx.company_id
            AND p.id = tx.project_id
            LEFT JOIN {schema}.customers c
                ON c.company_id = p.company_id
            AND c.id = p.customer_id
            LEFT JOIN {schema}.project_tasks t
                ON t.company_id = tx.company_id
            AND t.id = COALESCE(ln.task_id, tx.task_id)
            LEFT JOIN {schema}.project_cost_codes cc
                ON cc.company_id = tx.company_id
            AND cc.id = COALESCE(ln.cost_code_id, tx.cost_code_id)
            WHERE {" AND ".join(where)}
            ORDER BY tx.tx_date DESC, tx.id DESC, ln.id ASC
            LIMIT %s OFFSET %s
            """,
            tuple(params),
        ) or []

    def get_project_profitability(
        self,
        company_id: int,
        *,
        project_id: int | None = None,
        limit: int = 100,
    ) -> list[dict]:
        schema = self.company_schema(company_id)

        where = ["p.company_id = %s"]
        params: list[Any] = [int(company_id)]

        if project_id:
            where.append("p.id = %s")
            params.append(int(project_id))

        params.append(int(limit))

        material_cost_sql = """
            SELECT SUM(
                COALESCE(ln.qty, 0) * COALESCE(ln.unit_cost, 0)
            )
            FROM {schema}.inventory_tx tx
            JOIN {schema}.inventory_tx_lines ln
                ON ln.company_id = tx.company_id
            AND ln.tx_id = tx.id
            WHERE tx.company_id = p.company_id
            AND tx.project_id = p.id
            AND tx.tx_type = 'issue_to_project'
        """.format(schema=schema)

        return self.fetch_all(
            f"""
            SELECT
                p.id AS project_id,
                p.project_code,
                p.project_name,
                p.project_type,
                p.accounting_mode,
                p.status,
                p.progress_percent,
                p.billing_enabled,
                p.revenue_enabled,
                c.name AS customer_name,

                COALESCE(p.contract_value, 0) AS contract_value,

                COALESCE((
                    SELECT SUM(b.budget_amount)
                    FROM {schema}.project_budget_lines b
                    WHERE b.company_id = p.company_id
                    AND b.project_id = p.id
                ), 0) AS budget_total,

                COALESCE((
                    {material_cost_sql}
                ), 0) AS material_cost_total,

                COALESCE((
                    SELECT SUM(rc.recognized_revenue_to_date)
                    FROM {schema}.revenue_contracts rc
                    WHERE rc.company_id = p.company_id
                    AND rc.project_id = p.id
                ), 0) AS recognized_revenue,

                COALESCE((
                    SELECT SUM(rc.billed_to_date)
                    FROM {schema}.revenue_contracts rc
                    WHERE rc.company_id = p.company_id
                    AND rc.project_id = p.id
                ), 0) AS billed_to_date,

                (
                    COALESCE((
                        SELECT SUM(rc.recognized_revenue_to_date)
                        FROM {schema}.revenue_contracts rc
                        WHERE rc.company_id = p.company_id
                        AND rc.project_id = p.id
                    ), 0)
                    -
                    COALESCE((
                        {material_cost_sql}
                    ), 0)
                ) AS gross_margin

            FROM {schema}.projects p
            LEFT JOIN {schema}.customers c
                ON c.company_id = p.company_id
            AND c.id = p.customer_id
            WHERE {" AND ".join(where)}
            ORDER BY p.created_at DESC, p.id DESC
            LIMIT %s
            """,
            tuple(params),
        ) or []    

    def sync_ifrs15_contract_to_accrual_item(
        self,
        company_id: int,
        contract_id: int,
        *,
        source_invoice_id=None,
        user_id=None,
        cur=None,
    ):
        """
        Mirrors an IFRS 15 contract liability into accrual_deferral_items.

        Important:
        - This method does not create journals.
        - This method does not generate schedule lines.
        - Revenue recognition remains controlled by the IFRS 15 module.
        """

        from decimal import Decimal, ROUND_HALF_UP
        from datetime import date as _date
        from psycopg2.extras import Json

        schema = self.company_schema(company_id)

        def money(value) -> Decimal:
            return Decimal(str(value or 0)).quantize(
                Decimal("0.01"),
                rounding=ROUND_HALF_UP,
            )

        def account_code(value) -> str:
            if value is None:
                return ""

            if isinstance(value, str):
                return value.strip()

            if isinstance(value, dict):

                for key in (
                    "posting_code",
                    "account_code",
                    "code",
                    "account",
                    "coa_code",
                    "gl_code",
                    "value",
                ):
                    v = value.get(key)
                    if isinstance(v, str) and v.strip():
                        return v.strip()

                return ""

            if isinstance(value, (tuple, list)):

                for candidate in value:

                    code = account_code(candidate)

                    if code:
                        return code

                return ""

            return str(value).strip()

        def _run(_cur):
            contract = self.fetch_one(
                f"""
                SELECT
                    rc.id,
                    rc.company_id,
                    rc.customer_id,
                    rc.contract_number,
                    rc.contract_title,
                    rc.contract_currency,
                    rc.contract_date,
                    rc.start_date,
                    rc.end_date,
                    rc.transaction_price,
                    rc.billed_to_date,
                    rc.recognized_revenue_to_date,
                    rc.contract_liability_balance,
                    rc.status,
                    rc.payload_json,
                    c.name AS customer_name
                FROM {schema}.revenue_contracts rc
                LEFT JOIN {schema}.customers c
                ON c.id = rc.customer_id
                WHERE rc.company_id = %s
                AND rc.id = %s
                LIMIT 1
                """,
                (
                    int(company_id),
                    int(contract_id),
                ),
                cur=_cur,
            )

            if not contract:
                raise ValueError(
                    f"Revenue contract {contract_id} was not found"
                )

            billed_to_date = money(
                contract.get("billed_to_date")
            )

            recognized_to_date = money(
                contract.get("recognized_revenue_to_date")
            )

            calculated_liability = money(
                max(
                    billed_to_date - recognized_to_date,
                    Decimal("0.00"),
                )
            )

            stored_liability = money(
                contract.get("contract_liability_balance")
            )

            # Prefer the calculated current position.
            contract_liability = calculated_liability

            # Fallback for older contracts where totals were not populated.
            if (
                contract_liability <= Decimal("0.00")
                and stored_liability > Decimal("0.00")
            ):
                contract_liability = stored_liability

            ifrs15_accounts = self.resolve_ifrs15_accounts(
                company_id,
                cur=_cur,
            ) or {}

            contract_liability_account = account_code(
                ifrs15_accounts.get("contract_liability_account")
                or ifrs15_accounts.get("contract_liability_code")
                or ifrs15_accounts.get("contract_liability")
                or ifrs15_accounts.get("CONTRACT_LIABILITY")
            )

            revenue_account = account_code(
                ifrs15_accounts.get("contract_revenue_account")
                or ifrs15_accounts.get("revenue_code")
                or ifrs15_accounts.get("contract_revenue")
                or ifrs15_accounts.get("CONTRACT_REVENUE")
                or ifrs15_accounts.get("revenue")
                or ifrs15_accounts.get("REVENUE")
            )

            print(
                "Resolved accounts:",
                contract_liability_account,
                revenue_account,
            )

            if not contract_liability_account:
                raise ValueError(
                    f"Contract liability account could not be resolved. "
                    f"Resolver returned: {ifrs15_accounts}"
                )

            if not revenue_account:
                raise ValueError(
                    f"Revenue account could not be resolved. "
                    f"Resolver returned: {ifrs15_accounts}"
                )

            contract_number = contract.get("contract_number") or f"REV-CON-{contract_id}"
            contract_title = contract.get("contract_title") or contract_number
            customer_name = contract.get("customer_name") or "Customer"

            existing = self.fetch_one(
                f"""
                SELECT *
                FROM {schema}.accrual_deferral_items
                WHERE company_id = %s
                AND item_type = 'deferred_income'
                AND (
                        (source_module = 'ifrs15' AND source_id = %s)
                        OR source_revenue_contract_id = %s
                        OR (source_module = 'ifrs15' AND source_reference = %s)
                    )
                ORDER BY id
                LIMIT 1
                FOR UPDATE
                """,
                (
                    int(company_id),
                    int(contract_id),
                    int(contract_id),
                    contract_number,
                ),
                cur=_cur,
            )

            start_date = (
                contract.get("start_date")
                or contract.get("contract_date")
                or _date.today()
            )

            end_date = (
                contract.get("end_date")
                or start_date
            )

            currency = (
                contract.get("contract_currency")
                or self.company_currency(company_id)
                or "USD"
            )

            item_title = (
                f"IFRS 15 Deferred Revenue - "
                f"{contract_number}"
            )

            status = (
                "active"
                if contract_liability > Decimal("0.00")
                else "completed"
            )

            payload_json = {
                "mirror_only": True,
                "accounting_owner": "ifrs15",
                "contract_id": int(contract_id),
                "contract_number": contract_number,
                "contract_title": contract_title,
                "customer_id": contract.get("customer_id"),
                "customer_name": customer_name,
                "billed_to_date": float(billed_to_date),
                "recognized_revenue_to_date": float(
                    recognized_to_date
                ),
                "contract_liability": float(
                    contract_liability
                ),
                "source_invoice_id": (
                    int(source_invoice_id)
                    if source_invoice_id
                    else None
                ),
                "warning": (
                    "Mirror item only. Do not post recognition "
                    "from the accrual and deferral module."
                ),
            }

            if existing:
                item_id = int(existing["id"])

                _cur.execute(
                    f"""
                    UPDATE {schema}.accrual_deferral_items
                    SET
                        item_title = %s,
                        status = %s,
                        counterparty_type = 'customer',
                        customer_id = %s,
                        currency = %s,
                        transaction_date = %s,
                        start_date = %s,
                        end_date = %s,

                        original_amount = %s,
                        recognized_to_date = %s,
                        remaining_balance = %s,

                        recognition_method = 'manual',
                        frequency = 'manual',

                        balance_account = %s,
                        balance_account_role = 'contract_liability',
                        recognition_account = %s,
                        recognition_account_role = 'contract_revenue',

                        source_invoice_id = COALESCE(%s, source_invoice_id),
                        source_module = 'ifrs15',
                        source_table = 'revenue_contracts',
                        source_id = %s,
                        source_reference = %s,
                        source_revenue_contract_id = %s,

                        is_system_generated = TRUE,
                        is_mirror_item = TRUE,
                        approval_status = 'approved',

                        notes = %s,
                        payload_json = %s,
                        updated_by_user_id = %s,
                        updated_at = NOW(),
                        last_synced_at = NOW()
                    WHERE company_id = %s
                    AND id = %s
                    RETURNING *
                    """,
                    (
                        item_title,
                        status,
                        contract.get("customer_id"),
                        currency,
                        contract.get("contract_date") or start_date,
                        start_date,
                        end_date,
                        billed_to_date,
                        recognized_to_date,
                        contract_liability,
                        contract_liability_account or None,
                        revenue_account or None,
                        (
                            int(source_invoice_id)
                            if source_invoice_id
                            else None
                        ),
                        int(contract_id),
                        contract_number,
                        int(contract_id),
                        (
                            "System-generated IFRS 15 deferred "
                            f"revenue mirror for {contract_number}. "
                            "Do not post this item separately."
                        ),
                        Json(payload_json),
                        int(user_id) if user_id else None,
                        int(company_id),
                        item_id,
                    ),
                )

                item = dict(_cur.fetchone())

            else:
                item_number = f"IFRS15-{int(contract_id):05d}"

                _cur.execute(
                    f"""
                    INSERT INTO {schema}.accrual_deferral_items (
                        company_id,
                        item_number,
                        item_title,
                        item_type,
                        status,

                        counterparty_type,
                        customer_id,
                        currency,

                        transaction_date,
                        start_date,
                        end_date,

                        original_amount,
                        recognized_to_date,
                        remaining_balance,

                        recognition_method,
                        frequency,

                        balance_account,
                        balance_account_role,
                        recognition_account,
                        recognition_account_role,

                        vat_amount,
                        tax_mode,

                        source_invoice_id,
                        source_module,
                        source_table,
                        source_id,
                        source_reference,
                        source_revenue_contract_id,

                        is_system_generated,
                        is_mirror_item,

                        approval_status,
                        approved_by_user_id,
                        approved_at,

                        notes,
                        payload_json,

                        created_by_user_id,
                        updated_by_user_id,
                        last_synced_at
                    )
                    VALUES (
                        %s,%s,%s,'deferred_income',%s,
                        'customer',%s,%s,
                        %s,%s,%s,
                        %s,%s,%s,
                        'manual','manual',
                        %s,'contract_liability',
                        %s,'contract_revenue',
                        0,'no_vat',
                        %s,
                        'ifrs15',
                        'revenue_contracts',
                        %s,%s,%s,
                        TRUE,TRUE,
                        'approved',%s,NOW(),
                        %s,%s,
                        %s,%s,NOW()
                    )
                    RETURNING *
                    """,
                    (
                        int(company_id),
                        item_number,
                        item_title,
                        status,
                        contract.get("customer_id"),
                        currency,
                        contract.get("contract_date") or start_date,
                        start_date,
                        end_date,
                        billed_to_date,
                        recognized_to_date,
                        contract_liability,
                        contract_liability_account or None,
                        revenue_account or None,
                        (
                            int(source_invoice_id)
                            if source_invoice_id
                            else None
                        ),
                        int(contract_id),
                        contract_number,
                        int(contract_id),
                        int(user_id) if user_id else None,
                        (
                            "System-generated IFRS 15 deferred "
                            f"revenue mirror for {contract_number}. "
                            "Do not post this item separately."
                        ),
                        Json(payload_json),
                        int(user_id) if user_id else None,
                        int(user_id) if user_id else None,
                    ),
                )

                item = dict(_cur.fetchone())

            # Mirror items must not contain accrual recognition schedules.
            _cur.execute(
                f"""
                DELETE FROM {schema}.accrual_deferral_schedule_lines
                WHERE company_id = %s
                AND item_id = %s
                AND status = 'pending'
                """,
                (
                    int(company_id),
                    int(item["id"]),
                ),
            )

            return {
                "item": item,
                "contract_id": int(contract_id),
                "contract_number": contract_number,
                "contract_liability": float(contract_liability),
                "status": status,
            }

        if cur is not None:
            return _run(cur)

        with self._conn_cursor() as (conn, _cur):
            try:
                result = _run(_cur)
                conn.commit()
                return result
            except Exception:
                conn.rollback()
                raise

    def accrual_deferral_list_items(
        self,
        company_id: int,
        item_type=None,
        status=None,
        source_module=None,
    ):
        schema = self.company_schema(company_id)

        where = ["adi.company_id = %s"]
        params = [int(company_id)]

        if item_type:
            where.append("adi.item_type = %s")
            params.append(str(item_type).strip())

        if status:
            where.append("adi.status = %s")
            params.append(str(status).strip())

        if source_module:
            where.append("adi.source_module = %s")
            params.append(str(source_module).strip())

        return self.fetch_all(
            f"""
            SELECT
                adi.*,

                c.name AS customer_name,
                v.name AS supplier_name,

                rc.contract_number,
                rc.contract_title,
                rc.billed_to_date AS ifrs15_billed_to_date,
                rc.recognized_revenue_to_date
                    AS ifrs15_recognized_to_date,
                rc.contract_liability_balance
                    AS ifrs15_contract_liability_balance,
                rc.contract_asset_balance
                    AS ifrs15_contract_asset_balance,

                i.number AS source_invoice_number,
                i.invoice_date AS source_invoice_date,

                COALESCE(schedule_summary.schedule_line_count, 0)
                    AS schedule_line_count,

                COALESCE(schedule_summary.pending_line_count, 0)
                    AS pending_line_count,

                COALESCE(schedule_summary.posted_line_count, 0)
                    AS posted_line_count,

                CASE
                    WHEN adi.is_mirror_item = TRUE
                        THEN 'ifrs15_mirror'
                    WHEN adi.source_module IS NOT NULL
                        THEN adi.source_module
                    ELSE 'manual'
                END AS display_source_type

            FROM {schema}.accrual_deferral_items adi

            LEFT JOIN {schema}.customers c
            ON c.id = adi.customer_id

            LEFT JOIN {schema}.vendors v
            ON v.id = adi.supplier_id
            AND v.company_id = adi.company_id

            LEFT JOIN {schema}.revenue_contracts rc
            ON rc.id = adi.source_revenue_contract_id
            AND adi.source_module = 'ifrs15'

            LEFT JOIN {schema}.invoices i
            ON i.id = adi.source_invoice_id

            LEFT JOIN LATERAL (
                SELECT
                    COUNT(*) AS schedule_line_count,

                    COUNT(*) FILTER (
                        WHERE adsl.status = 'pending'
                    ) AS pending_line_count,

                    COUNT(*) FILTER (
                        WHERE adsl.status = 'posted'
                    ) AS posted_line_count

                FROM {schema}.accrual_deferral_schedule_lines adsl
                WHERE adsl.company_id = adi.company_id
                AND adsl.item_id = adi.id
            ) schedule_summary ON TRUE

            WHERE {" AND ".join(where)}

            ORDER BY
                adi.is_mirror_item DESC,
                adi.created_at DESC,
                adi.id DESC
            """,
            tuple(params),
        )

    def accrual_deferral_get_item(
        self,
        company_id: int,
        item_id: int,
    ):
        from decimal import Decimal, ROUND_HALF_UP

        schema = self.company_schema(company_id)

        def money(value):
            return Decimal(str(value or 0)).quantize(
                Decimal("0.01"),
                rounding=ROUND_HALF_UP,
            )

        item = self.fetch_one(
            f"""
            SELECT
                adi.*,

                c.name AS customer_name,
                v.name AS supplier_name,

                rc.contract_number,
                rc.contract_title,
                rc.contract_currency,
                rc.transaction_price,
                rc.billed_to_date AS ifrs15_billed_to_date,
                rc.recognized_revenue_to_date
                    AS ifrs15_recognized_to_date,
                rc.contract_asset_balance
                    AS ifrs15_contract_asset_balance,
                rc.contract_liability_balance
                    AS ifrs15_contract_liability_balance,

                i.number AS source_invoice_number,
                i.invoice_date AS source_invoice_date,
                i.status AS source_invoice_status,
                i.posted_journal_id
                    AS source_invoice_journal_id

            FROM {schema}.accrual_deferral_items adi

            LEFT JOIN {schema}.customers c
            ON c.id = adi.customer_id

            LEFT JOIN {schema}.vendors v
            ON v.id = adi.supplier_id

            LEFT JOIN {schema}.revenue_contracts rc
            ON rc.id = adi.source_revenue_contract_id
            AND adi.source_module = 'ifrs15'

            LEFT JOIN {schema}.invoices i
            ON i.id = adi.source_invoice_id

            WHERE adi.company_id = %s
            AND adi.id = %s
            LIMIT 1
            """,
            (
                int(company_id),
                int(item_id),
            ),
        )

        if not item:
            return None

        schedule = self.fetch_all(
            f"""
            SELECT *
            FROM {schema}.accrual_deferral_schedule_lines
            WHERE company_id = %s
            AND item_id = %s
            ORDER BY line_no
            """,
            (
                int(company_id),
                int(item_id),
            ),
        )

        events = self.fetch_all(
            f"""
            SELECT *
            FROM {schema}.accrual_deferral_events
            WHERE company_id = %s
            AND item_id = %s
            ORDER BY event_date DESC, id DESC
            """,
            (
                int(company_id),
                int(item_id),
            ),
        )

        original_amount = money(
            item.get("original_amount")
        )

        recognized_to_date = money(
            item.get("recognized_to_date")
        )

        remaining_balance = money(
            item.get("remaining_balance")
        )

        if original_amount > 0:
            recognized_percent = (
                recognized_to_date
                / original_amount
                * Decimal("100")
            ).quantize(Decimal("0.01"))
        else:
            recognized_percent = Decimal("0.00")

        source = {
            "module": item.get("source_module"),
            "table": item.get("source_table"),
            "id": item.get("source_id"),
            "reference": item.get("source_reference"),
            "invoice_id": item.get("source_invoice_id"),
            "invoice_number": item.get(
                "source_invoice_number"
            ),
            "revenue_contract_id": item.get(
                "source_revenue_contract_id"
            ),
            "contract_number": item.get(
                "contract_number"
            ),
            "contract_title": item.get(
                "contract_title"
            ),
            "customer_id": item.get("customer_id"),
            "customer_name": item.get(
                "customer_name"
            ),
            "is_system_generated": bool(
                item.get("is_system_generated")
            ),
            "is_mirror_item": bool(
                item.get("is_mirror_item")
            ),
        }

        balances = {
            "original_amount": float(original_amount),
            "recognized_to_date": float(
                recognized_to_date
            ),
            "remaining_balance": float(
                remaining_balance
            ),
            "recognized_percent": float(
                recognized_percent
            ),
            "balance_account": item.get(
                "balance_account"
            ),
            "balance_account_role": item.get(
                "balance_account_role"
            ),
            "recognition_account": item.get(
                "recognition_account"
            ),
            "recognition_account_role": item.get(
                "recognition_account_role"
            ),
        }

        ifrs15 = None

        if item.get("source_module") == "ifrs15":
            billed = money(
                item.get("ifrs15_billed_to_date")
            )

            recognized = money(
                item.get("ifrs15_recognized_to_date")
            )

            calculated_liability = money(
                max(
                    billed - recognized,
                    Decimal("0.00"),
                )
            )

            calculated_asset = money(
                max(
                    recognized - billed,
                    Decimal("0.00"),
                )
            )

            ifrs15 = {
                "contract_number": item.get(
                    "contract_number"
                ),
                "contract_title": item.get(
                    "contract_title"
                ),
                "transaction_price": float(
                    money(item.get("transaction_price"))
                ),
                "billed_to_date": float(billed),
                "recognized_revenue_to_date": float(
                    recognized
                ),
                "contract_liability": float(
                    calculated_liability
                ),
                "contract_asset": float(
                    calculated_asset
                ),
                "accounting_owner": "ifrs15",
                "mirror_only": True,
                "posting_allowed": False,
            }

        return {
            "item": item,
            "schedule": schedule,
            "events": events,
            "source": source,
            "balances": balances,
            "ifrs15": ifrs15,
        }

    def backfill_ifrs15_deferred_revenue_items(
        self,
        company_id: int,
        user_id=None,
    ):
        schema = self.company_schema(company_id)

        with self._conn_cursor() as (conn, cur):
            try:
                contracts = self.fetch_all(
                    f"""
                    SELECT
                        id,
                        billed_to_date,
                        recognized_revenue_to_date,
                        contract_liability_balance
                    FROM {schema}.revenue_contracts
                    WHERE company_id = %s
                    AND (
                            COALESCE(billed_to_date, 0)
                            >
                            COALESCE(
                                recognized_revenue_to_date,
                                0
                            )
                            OR
                            COALESCE(
                                contract_liability_balance,
                                0
                            ) > 0
                    )
                    ORDER BY id
                    """,
                    (int(company_id),),
                    cur=cur,
                )

                created_or_updated = []

                for contract in contracts:
                    result = (
                        self.sync_ifrs15_contract_to_accrual_item(
                            company_id=int(company_id),
                            contract_id=int(contract["id"]),
                            user_id=user_id,
                            cur=cur,
                        )
                    )

                    created_or_updated.append(result)

                conn.commit()

                return {
                    "company_id": int(company_id),
                    "contracts_found": len(contracts),
                    "items_synced": len(created_or_updated),
                    "items": created_or_updated,
                }

            except Exception:
                conn.rollback()
                raise

    def accrual_deferral_next_number(
        self,
        company_id: int,
        prefix: str = "AD",
        cur=None,
    ):
        schema = self.company_schema(company_id)

        row = self.fetch_one(
            f"""
            SELECT COALESCE(MAX(SUBSTRING(item_number FROM '([0-9]+)$')::INT),0)+1 next_number
            FROM {schema}.accrual_deferral_items
            WHERE company_id=%s
            AND item_number LIKE %s
            """,
            (company_id, f"{prefix}-%"),
            cur=cur,
        )

        return f"{prefix}-{row['next_number']:05d}"
        
    def company_currency(self, company_id: int) -> str:
        row = self.fetch_one("""
            SELECT currency
            FROM public.companies
            WHERE id = %s
        """, (int(company_id),))

        currency = (row or {}).get("currency")
        if currency:
            return str(currency).strip().upper()

        # Global fallback
        return "USD"

    def accrual_deferral_create_item(
        self,
        company_id: int,
        payload: dict,
        user_id=None,
    ):
        schema = self.company_schema(company_id)

        item_type = str(
            payload.get("item_type") or "prepaid_expense"
        ).strip()

        requested_status = str(
            payload.get("status") or "draft"
        ).strip().lower()

        item_number = (
            payload.get("item_number")
            or self.accrual_deferral_next_number(company_id)
        )

        # --------------------------------------------------
        # Resolve balance-sheet account
        # --------------------------------------------------
        balance_account = str(
            payload.get("balance_account") or ""
        ).strip()

        balance_account_role = str(
            payload.get("balance_account_role")
            or item_type
        ).strip()

        if not balance_account:
            balance_row = self.accrual_deferral_account_by_role(
                company_id,
                balance_account_role,
            )

            balance_account = str(
                balance_row.get("code") or ""
            ).strip()

        if not balance_account:
            raise ValueError(
                f"Balance account could not be resolved for {item_type}"
            )

        # --------------------------------------------------
        # Resolve recognition expense/income account
        # --------------------------------------------------
        recognition_account = str(
            payload.get("recognition_account") or ""
        ).strip()

        recognition_account_role = str(
            payload.get("recognition_account_role") or ""
        ).strip()

        if not recognition_account and recognition_account_role:
            recognition_row = self.accrual_deferral_account_by_role(
                company_id,
                recognition_account_role,
            )

            recognition_account = str(
                recognition_row.get("code") or ""
            ).strip()

        if requested_status == "active" and not recognition_account:
            raise ValueError(
                "Select a recognition expense or income account "
                "before activating this accrual/deferral item"
            )

        # --------------------------------------------------
        # Other accounts
        # --------------------------------------------------
        settlement_account = str(
            payload.get("settlement_account") or ""
        ).strip() or None

        settlement_role = str(
            payload.get("settlement_role") or ""
        ).strip() or None

        tax_account = str(
            payload.get("tax_account") or ""
        ).strip() or None

        # --------------------------------------------------
        # Validate dates and amount
        # --------------------------------------------------
        start_date = _date(payload.get("start_date"))
        end_date = _date(payload.get("end_date"))

        transaction_date = (
            _date(payload.get("transaction_date"))
            or start_date
        )

        if not start_date or not end_date:
            raise ValueError(
                "start_date and end_date are required"
            )

        if end_date < start_date:
            raise ValueError(
                "end_date cannot be before start_date"
            )

        original_amount = _d(
            payload.get("original_amount")
        )

        if original_amount <= 0:
            raise ValueError(
                "original_amount must be greater than zero"
            )

        with self.transaction() as (conn, cur):
            cur.execute(f"""
                INSERT INTO {schema}.accrual_deferral_items (
                    company_id,
                    item_number,
                    item_title,
                    item_type,
                    status,
                    counterparty_type,
                    customer_id,
                    supplier_id,
                    employee_id,
                    currency,
                    transaction_date,
                    start_date,
                    end_date,
                    original_amount,
                    recognized_to_date,
                    remaining_balance,
                    recognition_method,
                    frequency,
                    balance_account,
                    balance_account_role,
                    recognition_account,
                    recognition_account_role,
                    settlement_account,
                    settlement_role,
                    tax_account,
                    vat_amount,
                    tax_mode,
                    source_invoice_id,
                    source_bill_id,
                    source_receipt_id,
                    source_payment_id,
                    source_journal_id,
                    approval_status,
                    notes,
                    payload_json,
                    created_by_user_id,
                    updated_by_user_id
                )
                VALUES (
                    %s,%s,%s,%s,%s,
                    %s,%s,%s,%s,%s,
                    %s,%s,%s,%s,0,
                    %s,%s,%s,%s,%s,
                    %s,%s,%s,%s,%s,
                    %s,%s,%s,%s,%s,
                    %s,%s,%s,%s,%s,
                    %s,%s
                )
                RETURNING *
            """, (
                int(company_id),
                item_number,
                (
                    payload.get("item_title")
                    or payload.get("title")
                    or item_number
                ),
                item_type,
                requested_status,

                payload.get("counterparty_type"),
                payload.get("customer_id"),
                payload.get("supplier_id"),
                payload.get("employee_id"),
                (
                    payload.get("currency")
                    or self.company_currency(company_id)
                ),

                transaction_date,
                start_date,
                end_date,
                original_amount,

                original_amount,
                payload.get("recognition_method") or "straight_line",
                payload.get("frequency") or "monthly",

                balance_account,
                balance_account_role,
                recognition_account or None,
                recognition_account_role or None,

                settlement_account,
                settlement_role,
                tax_account,
                _d(payload.get("vat_amount")),
                payload.get("tax_mode") or "exclusive",

                payload.get("source_invoice_id"),
                payload.get("source_bill_id"),
                payload.get("source_receipt_id"),
                payload.get("source_payment_id"),
                payload.get("source_journal_id"),

                payload.get("approval_status") or "draft",
                payload.get("notes"),
                Json(payload.get("payload_json") or {}),
                user_id,
                user_id,
            ))

            item = cur.fetchone()

            cur.execute(f"""
                INSERT INTO {schema}.accrual_deferral_events (
                    company_id,
                    item_id,
                    event_date,
                    event_type,
                    amount,
                    currency,
                    source_invoice_id,
                    source_bill_id,
                    source_receipt_id,
                    source_payment_id,
                    source_journal_id,
                    notes,
                    payload_json,
                    created_by_user_id
                )
                VALUES (
                    %s,%s,%s,'initial',
                    %s,%s,%s,%s,%s,
                    %s,%s,%s,%s,%s
                )
            """, (
                int(company_id),
                item["id"],
                transaction_date,
                original_amount,
                item["currency"],
                payload.get("source_invoice_id"),
                payload.get("source_bill_id"),
                payload.get("source_receipt_id"),
                payload.get("source_payment_id"),
                payload.get("source_journal_id"),
                payload.get("notes"),
                Json(payload.get("payload_json") or {}),
                user_id,
            ))

            self.accrual_deferral_generate_schedule(
                company_id,
                item["id"],
                cur=cur,
            )

        return self.accrual_deferral_get_item(
            company_id,
            item["id"],
        )

    def accrual_deferral_generate_schedule(self, company_id: int, item_id: int, cur=None):
        schema = self.company_schema(company_id)

        own_cursor = cur is None

        if own_cursor:
            ctx = self.transaction()
            conn, cur = ctx.__enter__()

        try:
            cur.execute(f"""
                SELECT *
                FROM {schema}.accrual_deferral_items
                WHERE company_id = %s AND id = %s
            """, (int(company_id), int(item_id)))

            item = cur.fetchone()

            if not item:
                raise ValueError("Accrual/deferral item not found")

            cur.execute(f"""
                DELETE FROM {schema}.accrual_deferral_schedule_lines
                WHERE company_id = %s
                AND item_id = %s
                AND status = 'pending'
            """, (int(company_id), int(item_id)))

            start = _date(item["start_date"])
            end = _date(item["end_date"])
            amount = _d(item["original_amount"])

            months = []
            d = date(start.year, start.month, 1)

            while d <= end:
                period_start = max(d, start)
                period_end = min(_month_end(d), end)
                months.append((period_start, period_end))
                d = _add_month(d)

            if not months:
                return {"created": 0}

            monthly_amount = (amount / Decimal(len(months))).quantize(Decimal("0.01"))

            opening = amount
            created = 0

            for idx, (ps, pe) in enumerate(months, start=1):
                if idx == len(months):
                    recognition_amount = opening
                else:
                    recognition_amount = monthly_amount

                closing = opening - recognition_amount

                cur.execute(f"""
                    INSERT INTO {schema}.accrual_deferral_schedule_lines (
                        company_id,
                        item_id,
                        line_no,
                        period_start,
                        period_end,
                        recognition_date,
                        opening_balance,
                        recognition_amount,
                        closing_balance,
                        status,
                        payload_json
                    )
                    VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,'pending',%s)
                    ON CONFLICT (item_id, line_no)
                    DO UPDATE SET
                        period_start = EXCLUDED.period_start,
                        period_end = EXCLUDED.period_end,
                        recognition_date = EXCLUDED.recognition_date,
                        opening_balance = EXCLUDED.opening_balance,
                        recognition_amount = EXCLUDED.recognition_amount,
                        closing_balance = EXCLUDED.closing_balance
                """, (
                    int(company_id),
                    int(item_id),
                    idx,
                    ps,
                    pe,
                    pe,
                    opening,
                    recognition_amount,
                    closing,
                    Json({}),
                ))

                opening = closing
                created += 1

            if own_cursor:
                ctx.__exit__(None, None, None)

            return {"created": created}

        except Exception:
            if own_cursor:
                ctx.__exit__(*sys.exc_info())
            raise


    def accrual_deferral_update_item(
        self,
        company_id: int,
        item_id: int,
        payload: dict,
        user_id=None,
    ):
        schema = self.company_schema(company_id)

        existing = self.accrual_deferral_get_item(
            company_id,
            item_id,
        )

        if not existing:
            return None

        allowed = {
            "item_title",
            "status",
            "counterparty_type",
            "customer_id",
            "supplier_id",
            "employee_id",
            "currency",
            "transaction_date",
            "start_date",
            "end_date",
            "original_amount",
            "recognition_method",
            "frequency",
            "balance_account",
            "balance_account_role",
            "recognition_account",
            "recognition_account_role",
            "settlement_account",
            "settlement_role",
            "tax_account",
            "vat_amount",
            "tax_mode",
            "approval_status",
            "notes",
            "payload_json",
        }

        # --------------------------------------------------
        # Resolve final status
        # --------------------------------------------------
        new_status = str(
            payload.get("status")
            if "status" in payload
            else existing.get("status")
            or "draft"
        ).strip().lower()

        if "status" in payload:
            payload["status"] = new_status

        # --------------------------------------------------
        # Resolve balance account
        # --------------------------------------------------
        balance_account = str(
            payload.get("balance_account")
            if "balance_account" in payload
            else existing.get("balance_account")
            or ""
        ).strip()

        balance_account_role = str(
            payload.get("balance_account_role")
            if "balance_account_role" in payload
            else existing.get("balance_account_role")
            or existing.get("item_type")
            or ""
        ).strip()

        if not balance_account and balance_account_role:
            balance_row = self.accrual_deferral_account_by_role(
                company_id,
                balance_account_role,
            )

            balance_account = str(
                balance_row.get("code") or ""
            ).strip()

            payload["balance_account"] = (
                balance_account or None
            )

        if not balance_account:
            raise ValueError(
                "A balance-sheet account is required "
                "for this accrual/deferral item"
            )

        if "balance_account_role" in payload:
            payload["balance_account_role"] = (
                balance_account_role or None
            )

        # --------------------------------------------------
        # Resolve recognition account
        # --------------------------------------------------
        recognition_account = str(
            payload.get("recognition_account")
            if "recognition_account" in payload
            else existing.get("recognition_account")
            or ""
        ).strip()

        recognition_account_role = str(
            payload.get("recognition_account_role")
            if "recognition_account_role" in payload
            else existing.get("recognition_account_role")
            or ""
        ).strip()

        if not recognition_account and recognition_account_role:
            recognition_row = self.accrual_deferral_account_by_role(
                company_id,
                recognition_account_role,
            )

            recognition_account = str(
                recognition_row.get("code") or ""
            ).strip()

            payload["recognition_account"] = (
                recognition_account or None
            )

        if "recognition_account_role" in payload:
            payload["recognition_account_role"] = (
                recognition_account_role or None
            )

        if new_status == "active" and not recognition_account:
            raise ValueError(
                "Select a recognition expense or income account "
                "before activating this item"
            )

        # --------------------------------------------------
        # Validate dates
        # --------------------------------------------------
        start_date = (
            _date(payload.get("start_date"))
            if "start_date" in payload
            else _date(existing.get("start_date"))
        )

        end_date = (
            _date(payload.get("end_date"))
            if "end_date" in payload
            else _date(existing.get("end_date"))
        )

        transaction_date = (
            _date(payload.get("transaction_date"))
            if "transaction_date" in payload
            else _date(existing.get("transaction_date"))
        )

        if not start_date or not end_date:
            raise ValueError(
                "start_date and end_date are required"
            )

        if end_date < start_date:
            raise ValueError(
                "end_date cannot be before start_date"
            )

        if "start_date" in payload:
            payload["start_date"] = start_date

        if "end_date" in payload:
            payload["end_date"] = end_date

        if "transaction_date" in payload:
            payload["transaction_date"] = transaction_date

        # --------------------------------------------------
        # Validate amount
        # --------------------------------------------------
        original_amount = (
            _d(payload.get("original_amount"))
            if "original_amount" in payload
            else _d(existing.get("original_amount"))
        )

        recognized_to_date = _d(
            existing.get("recognized_to_date")
        )

        if original_amount <= 0:
            raise ValueError(
                "original_amount must be greater than zero"
            )

        if original_amount < recognized_to_date:
            raise ValueError(
                "original_amount cannot be less than the amount "
                "already recognised"
            )

        if "original_amount" in payload:
            payload["original_amount"] = original_amount

        # --------------------------------------------------
        # Normalise other values
        # --------------------------------------------------
        if "vat_amount" in payload:
            payload["vat_amount"] = _d(
                payload.get("vat_amount")
            )

        if "payload_json" in payload:
            payload["payload_json"] = Json(
                payload.get("payload_json") or {}
            )

        for field in (
            "balance_account",
            "balance_account_role",
            "recognition_account",
            "recognition_account_role",
            "settlement_account",
            "settlement_role",
            "tax_account",
        ):
            if field in payload and isinstance(payload[field], str):
                payload[field] = (
                    payload[field].strip() or None
                )

        sets = []
        params = []

        for key in allowed:
            if key in payload:
                sets.append(f"{key} = %s")
                params.append(payload.get(key))

        # Recalculate remaining balance when amount changes.
        if "original_amount" in payload:
            sets.append("""
                remaining_balance =
                    GREATEST(%s - recognized_to_date, 0)
            """)
            params.append(original_amount)

        if not sets:
            return existing

        sets.append("updated_by_user_id = %s")
        params.append(user_id)

        sets.append("updated_at = NOW()")

        params.extend([
            int(company_id),
            int(item_id),
        ])

        schedule_fields = {
            "start_date",
            "end_date",
            "original_amount",
            "frequency",
            "recognition_method",
        }

        regenerate_schedule = any(
            key in payload
            for key in schedule_fields
        )

        with self.transaction() as (conn, cur):
            cur.execute(f"""
                UPDATE {schema}.accrual_deferral_items
                SET {", ".join(sets)}
                WHERE company_id = %s
                AND id = %s
                RETURNING *
            """, tuple(params))

            item = cur.fetchone()

            if not item:
                return None

            if regenerate_schedule:
                self.accrual_deferral_generate_schedule(
                    company_id,
                    item_id,
                    cur=cur,
                )

        return self.accrual_deferral_get_item(
            company_id,
            item_id,
        )

    def accrual_deferral_delete_item(self, company_id: int, item_id: int):
        schema = self.company_schema(company_id)

        row = self.fetch_one(f"""
            DELETE FROM {schema}.accrual_deferral_items
            WHERE company_id = %s
            AND id = %s
            AND status IN ('draft', 'cancelled')
            RETURNING id
        """, (int(company_id), int(item_id)))

        return bool(row)


    def accrual_deferral_list_runs(self, company_id: int):
        schema = self.company_schema(company_id)

        return self.fetch_all(f"""
            SELECT *
            FROM {schema}.accrual_deferral_runs
            WHERE company_id = %s
            ORDER BY period_end DESC, id DESC
        """, (int(company_id),))

    def accrual_deferral_post_run_by_date(
        self,
        company_id: int,
        payload: dict,
        user_id=None,
    ):
        payload = payload or {}
        schema = self.company_schema(company_id)
        run = self.fetch_one(f"""
            SELECT *
            FROM {schema}.accrual_deferral_runs
            WHERE company_id = %s
            AND id = %s
            FOR UPDATE
        """, (
            int(company_id),
            int(run_id),
        ))

        if not run:
            raise ValueError(
                "Accrual/deferral run not found"
            )

        if run.get("status") == "posted":
            raise ValueError(
                "This recognition run has already been posted"
            )

        if run.get("status") != "draft":
            raise ValueError(
                f"Cannot post a run with status '{run.get('status')}'"
            )
            
        run_id = payload.get("run_id")

        if run_id:
            run_id = int(run_id)

            run = self.accrual_deferral_get_run(
                company_id,
                run_id,
            )

            if not run:
                raise ValueError(
                    "Accrual/deferral run not found"
                )

            run_row = run.get("run") or {}

            if run_row.get("status") != "draft":
                raise ValueError(
                    "Only a draft recognition run can be posted"
                )

        else:
            normalised = self.accrual_deferral_normalise_run_payload(
                company_id,
                payload,
            )

            created = self.accrual_deferral_create_run(
                company_id,
                normalised,
                user_id=user_id,
            )

            run_row = created.get("run") or {}

            if not run_row.get("id"):
                raise ValueError(
                    "Recognition run was created but no run ID was returned"
                )

            run_id = int(run_row["id"])

        posted = self.accrual_deferral_post_run(
            company_id,
            run_id,
            user_id=user_id,
        )

        return {
            "run_id": run_id,
            **posted,
        }

    def accrual_deferral_preview_run_by_date(
        self,
        company_id: int,
        payload: dict,
        user_id=None,
    ):
        normalised = self.accrual_deferral_normalise_run_payload(
            company_id,
            payload,
        )

        created = self.accrual_deferral_create_run(
            company_id,
            normalised,
            user_id=user_id,
        )

        run = created.get("run") if isinstance(created, dict) else None

        if not run or not run.get("id"):
            raise ValueError(
                "Recognition run was created but no run ID was returned"
            )

        run_id = int(run["id"])

        preview = self.accrual_deferral_build_recognition_preview(
            company_id,
            run_id,
        )

        return {
            "run_id": run_id,
            "run": run,
            "preview": preview,
        }

    def accrual_deferral_normalise_run_payload(
        self,
        company_id: int,
        payload: dict,
    ):
        payload = payload or {}

        recognition_date = _date(
            payload.get("recognition_date")
            or payload.get("run_date")
            or payload.get("period_end")
        )

        if not recognition_date:
            raise ValueError("recognition_date is required")

        period_start = _date(
            payload.get("period_start")
        )

        if not period_start:
            period_start = date(
                recognition_date.year,
                recognition_date.month,
                1,
            )

        if period_start > recognition_date:
            raise ValueError(
                "period_start cannot be after recognition_date"
            )

        item_id = payload.get("item_id")

        if item_id in ("", None):
            item_id = None
        else:
            item_id = int(item_id)

        item_type = str(
            payload.get("item_type") or ""
        ).strip() or None

        return {
            "period_start": period_start,
            "period_end": recognition_date,
            "recognition_date": recognition_date,
            "run_date": recognition_date,
            "item_id": item_id,
            "item_type": item_type,
            "run_scope": (
                "item"
                if item_id
                else "type"
                if item_type
                else "company"
            ),
            "run_reason": (
                payload.get("run_reason")
                or "manual"
            ),
            "payload_json": payload,
        }

    def accrual_deferral_create_run(
        self,
        company_id: int,
        payload: dict,
        user_id=None,
    ):
        schema = self.company_schema(company_id)

        period_start = _date(payload.get("period_start"))
        period_end = _date(
            payload.get("period_end")
            or payload.get("recognition_date")
            or payload.get("run_date")
        )

        if not period_end:
            raise ValueError("period_end is required")

        if not period_start:
            period_start = date(
                period_end.year,
                period_end.month,
                1,
            )

        if period_start > period_end:
            raise ValueError(
                "period_start cannot be after period_end"
            )

        item_id = payload.get("item_id")
        item_type = payload.get("item_type")

        with self.transaction() as (conn, cur):
            cur.execute(f"""
                INSERT INTO {schema}.accrual_deferral_runs (
                    company_id,
                    item_id,
                    run_scope,
                    item_type,
                    period_start,
                    period_end,
                    status,
                    run_reason,
                    requested_by_user_id,
                    payload_json
                )
                VALUES (
                    %s,%s,%s,%s,%s,%s,
                    'draft',%s,%s,%s
                )
                RETURNING *
            """, (
                int(company_id),
                int(item_id) if item_id else None,
                payload.get("run_scope") or (
                    "item"
                    if item_id
                    else "type"
                    if item_type
                    else "company"
                ),
                item_type or None,
                period_start,
                period_end,
                payload.get("run_reason") or "period_end",
                user_id,
                Json(payload.get("payload_json") or {}),
            ))

            run = cur.fetchone()

        return self.accrual_deferral_get_run(
            company_id,
            run["id"],
        )

    def accrual_deferral_get_run(self, company_id: int, run_id: int):
        schema = self.company_schema(company_id)

        run = self.fetch_one(f"""
            SELECT *
            FROM {schema}.accrual_deferral_runs
            WHERE company_id = %s AND id = %s
        """, (int(company_id), int(run_id)))

        if not run:
            return None

        entries = self.fetch_all(f"""
            SELECT *
            FROM {schema}.accrual_deferral_entries
            WHERE company_id = %s AND run_id = %s
            ORDER BY id
        """, (int(company_id), int(run_id)))

        return {
            "run": run,
            "entries": entries,
        }

    def accrual_deferral_account_by_role(
        self,
        company_id: int,
        role: str,
        *,
        account_purpose: str = "primary",
    ):
        schema = self.company_schema(company_id)

        role = str(role or "").strip().lower()

        row = self.fetch_one(
            f"""
            SELECT
                code,
                name,
                role,
                section,
                category,
                subcategory
            FROM {schema}.coa
            WHERE company_id = %s
            AND posting = TRUE
            AND lower(coalesce(role, '')) = %s
            ORDER BY
                CASE
                    /*
                    * For the Accruals & Deferrals module, prefer
                    * the general prepaid-expense control account.
                    */
                    WHEN %s = 'prepaid_expense'
                    AND (
                        lower(coalesce(name, '')) IN (
                            'prepaid expense',
                            'prepaid expenses'
                        )
                        OR lower(coalesce(subcategory, '')) = 'prepayments'
                    )
                    THEN 0

                    /*
                    * Supplier advances are valid accounts, but they
                    * should not be the default prepaid-expense control.
                    */
                    WHEN %s = 'prepaid_expense'
                    AND (
                        lower(coalesce(name, '')) LIKE '%%supplier advance%%'
                        OR lower(coalesce(name, '')) LIKE '%%vendor prepayment%%'
                    )
                    THEN 20

                    ELSE 10
                END,
                id
            LIMIT 1
            """,
            (
                int(company_id),
                role,
                role,
                role,
            ),
        )

        if not row:
            raise ValueError(f"Missing COA role mapping: {role}")

        return row

    def accrual_deferral_build_initial_preview(self, company_id: int, item_id: int, payload=None):
        payload = payload or {}
        schema = self.company_schema(company_id)

        item = self.fetch_one(f"""
            SELECT *
            FROM {schema}.accrual_deferral_items
            WHERE company_id=%s AND id=%s
        """, (int(company_id), int(item_id)))

        if not item:
            raise ValueError("Accrual/deferral item not found")

        item_type = item["item_type"]
        amount = float(item.get("original_amount") or 0)

        settlement_account = (
            payload.get("settlement_account")
            or payload.get("contra_account")
            or item.get("source_account")
        )

        if not settlement_account:
            settlement_role = payload.get("settlement_role") or "cash_bank"
            settlement_account = self.accrual_deferral_account_by_role(
                company_id, settlement_role
            )["code"]

        balance_account = item.get("balance_account")
        recognition_account = item.get("recognition_account")

        if not balance_account:
            role_map = {
                "prepaid_expense": "prepaid_expense",
                "deferred_expense": "deferred_expense",
                "deferred_income": "deferred_income",
                "accrued_expense": "accrued_expense",
                "accrued_income": "accrued_income",
            }
            balance_account = self.accrual_deferral_account_by_role(
                company_id, role_map[item_type]
            )["code"]

        if item_type in ("prepaid_expense", "deferred_expense", "accrued_income"):
            lines = [
                {"account_code": balance_account, "debit": amount, "credit": 0},
                {"account_code": settlement_account, "debit": 0, "credit": amount},
            ]

        elif item_type in ("deferred_income", "accrued_expense"):
            lines = [
                {"account_code": settlement_account, "debit": amount, "credit": 0},
                {"account_code": balance_account, "debit": 0, "credit": amount},
            ]

        else:
            raise ValueError(f"Unsupported item_type: {item_type}")

        return {
            "date": str(item.get("transaction_date")),
            "ref": f"AD-INIT-{item['id']}",
            "description": f"Initial recognition - {item.get('item_title')}",
            "source": "accrual_deferral_initial",
            "source_id": int(item["id"]),
            "module_name": "accrual_deferrals",
            "currency": item.get("currency") or "USD",
            "lines": lines,
            "item": item,
        }


    def accrual_deferral_post_initial(self, company_id: int, item_id: int, payload=None, user_id=None):
        payload = payload or {}
        schema = self.company_schema(company_id)

        entry = self.accrual_deferral_build_initial_preview(company_id, item_id, payload)
        entry["created_by_user_id"] = user_id
        entry["prepared_by_user_id"] = user_id

        with self._conn_cursor() as (conn, cur):
            try:
                journal_id = self.post_journal(company_id, entry, cur=cur, conn=conn)

                cur.execute(f"""
                    UPDATE {schema}.accrual_deferral_items
                    SET source_journal_id = %s,
                        status = CASE WHEN status='draft' THEN 'active' ELSE status END,
                        updated_by_user_id = %s,
                        updated_at = NOW()
                    WHERE company_id=%s AND id=%s
                """, (journal_id, user_id, int(company_id), int(item_id)))

                cur.execute(f"""
                    INSERT INTO {schema}.accrual_deferral_events (
                        company_id, item_id, event_date, event_type, amount,
                        currency, source_journal_id, notes, payload_json, created_by_user_id
                    )
                    VALUES (%s,%s,%s,'initial_posted',%s,%s,%s,%s,%s,%s)
                """, (
                    int(company_id),
                    int(item_id),
                    entry["date"],
                    entry["lines"][0]["debit"] or entry["lines"][1]["credit"],
                    entry.get("currency") or "USD",
                    journal_id,
                    "Initial recognition posted",
                    Json(payload or {}),
                    user_id,
                ))

                conn.commit()
                return {
                    "journal_id": journal_id,
                    "preview": entry,
                    "item": self.accrual_deferral_get_item(company_id, item_id),
                }

            except Exception:
                conn.rollback()
                raise


    def accrual_deferral_build_recognition_preview(self, company_id: int, run_id: int):
        schema = self.company_schema(company_id)

        run = self.fetch_one(f"""
            SELECT *
            FROM {schema}.accrual_deferral_runs
            WHERE company_id=%s AND id=%s
        """, (int(company_id), int(run_id)))

        if not run:
            raise ValueError("Accrual/deferral run not found")

        where = [
            "l.company_id = %s",
            "l.status = 'pending'",
            "l.recognition_date <= %s",
            "i.status = 'active'",
            "COALESCE(i.is_mirror_item, FALSE) = FALSE",
        ]

        params = [
            int(company_id),
            run["period_end"],
        ]
        if run.get("item_id"):
            where.append("i.id = %s")
            params.append(int(run["item_id"]))

        if run.get("item_type"):
            where.append("i.item_type = %s")
            params.append(run["item_type"])

        lines_src = self.fetch_all(
            f"""
            WITH eligible_lines AS (
                SELECT
                    l.*,
                    i.item_number,
                    i.item_title,
                    i.item_type,
                    i.balance_account,
                    i.recognition_account,
                    i.currency
                FROM {schema}.accrual_deferral_schedule_lines l
                JOIN {schema}.accrual_deferral_items i
                ON i.id = l.item_id
                AND i.company_id = l.company_id
                WHERE {" AND ".join(where)}
            ),
            latest_period AS (
                SELECT MAX(recognition_date) AS recognition_date
                FROM eligible_lines
            )
            SELECT e.*
            FROM eligible_lines e
            JOIN latest_period p
            ON p.recognition_date = e.recognition_date
            ORDER BY e.item_id, e.line_no
            """,
            tuple(params),
        )

        posting_date = (
            lines_src[0]["recognition_date"]
            if lines_src
            else run["period_end"]
        )

        def gl_name(account_code):
            row = self.fetch_one(
                f"""
                SELECT name
                FROM {schema}.coa
                WHERE company_id = %s
                AND code = %s
                LIMIT 1
                """,
                (
                    int(company_id),
                    account_code,
                ),
            ) or {}

            return row.get("name") or account_code

        journal_lines = []
        entries = []

        for row in lines_src:
            amount = float(row.get("recognition_amount") or 0)
            if amount <= 0:
                continue

            item_type = row["item_type"]

            balance_account = row.get("balance_account")
            recognition_account = row.get("recognition_account")

            if not balance_account:
                balance_role = {
                    "prepaid_expense": "prepaid_expense",
                    "deferred_expense": "deferred_expense",
                    "deferred_income": "deferred_income",
                    "accrued_expense": "accrued_expense",
                    "accrued_income": "accrued_income",
                }[item_type]
                balance_account = self.accrual_deferral_account_by_role(company_id, balance_role)["code"]

            if not recognition_account:
                raise ValueError(
                    f"Missing recognition_account for item {row.get('item_id')} - {row.get('item_title')}"
                )

            if item_type in ("prepaid_expense", "deferred_expense"):
                debit_account = recognition_account
                credit_account = balance_account

            elif item_type == "deferred_income":
                debit_account = balance_account
                credit_account = recognition_account

            elif item_type == "accrued_expense":
                debit_account = recognition_account
                credit_account = balance_account

            elif item_type == "accrued_income":
                debit_account = balance_account
                credit_account = recognition_account

            else:
                raise ValueError(f"Unsupported item_type: {item_type}")

            journal_lines.append({
                "account_code": debit_account,
                "account_name": gl_name(debit_account),
                "debit": amount,
                "credit": 0,
                "description": row.get("item_title"),
            })

            journal_lines.append({
                "account_code": credit_account,
                "account_name": gl_name(credit_account),
                "debit": 0,
                "credit": amount,
                "description": row.get("item_title"),
            })

            entries.append({
                "schedule_line_id": row["id"],
                "item_id": row["item_id"],
                "item_type": item_type,
                "period_start": row["period_start"],
                "period_end": row["period_end"],
                "opening_balance": row["opening_balance"],
                "recognition_amount": row["recognition_amount"],
                "closing_balance": row["closing_balance"],
                "debit_account": debit_account,
                "credit_account": credit_account,
            })

        total_debit = round(sum(float(x.get("debit") or 0) for x in journal_lines), 2)
        total_credit = round(sum(float(x.get("credit") or 0) for x in journal_lines), 2)

        return {
            "journal": {
                "date": str(posting_date),
                "ref": f"AD-RUN-{run_id}",
                "description": (
                    f"Accruals/Deferrals recognition for "
                    f"{posting_date}"
                ),
                "source": "accrual_deferral_run",
                "source_id": int(run_id),
                "module_name": "accrual_deferrals",
                "currency": self.company_currency(company_id),
                "lines": journal_lines,
                "total_debit": total_debit,
                "total_credit": total_credit,
                "balanced": round(total_debit, 2) == round(total_credit, 2),
            },
            "entries": entries,
            "schedule": entries,
            "total": total_debit,
            "posting_date": str(posting_date),
            "run": run,
        }

    def accrual_deferral_post_run(
        self,
        company_id: int,
        run_id: int,
        user_id=None,
    ):
        schema = self.company_schema(company_id)

        # Build the recognition preview first.
        preview = self.accrual_deferral_build_recognition_preview(
            company_id,
            run_id,
        )

        journal = preview.get("journal") or {}

        if not journal.get("lines"):
            raise ValueError(
                "No pending schedule lines found for this run"
            )

        journal["created_by_user_id"] = user_id
        journal["prepared_by_user_id"] = user_id

        with self._conn_cursor() as (conn, cur):
            try:
                # Prevent posting the same run twice.
                cur.execute(f"""
                    SELECT id, status, journal_id
                    FROM {schema}.accrual_deferral_runs
                    WHERE company_id = %s
                    AND id = %s
                    FOR UPDATE
                """, (
                    int(company_id),
                    int(run_id),
                ))

                run_row = cur.fetchone()

                if not run_row:
                    raise ValueError(
                        "Accrual/deferral run not found"
                    )

                if run_row.get("status") == "posted":
                    raise ValueError(
                        "This recognition run has already been posted"
                    )

                if run_row.get("status") != "draft":
                    raise ValueError(
                        f"Cannot post a run with status "
                        f"'{run_row.get('status')}'"
                    )

                journal_id = self.post_journal(
                    company_id,
                    journal,
                    cur=cur,
                    conn=conn,
                )

                for e in preview.get("entries") or []:
                    cur.execute(f"""
                        INSERT INTO {schema}.accrual_deferral_entries (
                            company_id,
                            run_id,
                            item_id,
                            schedule_line_id,
                            period_start,
                            period_end,
                            item_type,
                            opening_balance,
                            recognition_amount,
                            closing_balance,
                            debit_account,
                            credit_account,
                            source_basis,
                            payload_json
                        )
                        VALUES (
                            %s,%s,%s,%s,%s,%s,%s,
                            %s,%s,%s,%s,%s,
                            'system',%s
                        )
                    """, (
                        int(company_id),
                        int(run_id),
                        int(e["item_id"]),
                        int(e["schedule_line_id"]),
                        e["period_start"],
                        e["period_end"],
                        e["item_type"],
                        e["opening_balance"],
                        e["recognition_amount"],
                        e["closing_balance"],
                        e["debit_account"],
                        e["credit_account"],
                        Json({}),
                    ))

                    cur.execute(f"""
                        UPDATE {schema}.accrual_deferral_schedule_lines
                        SET status = 'posted',
                            journal_id = %s,
                            posted_at = NOW(),
                            posted_by_user_id = %s
                        WHERE company_id = %s
                        AND id = %s
                        AND status = 'pending'
                    """, (
                        journal_id,
                        user_id,
                        int(company_id),
                        int(e["schedule_line_id"]),
                    ))

                    cur.execute(f"""
                        UPDATE {schema}.accrual_deferral_items
                        SET recognized_to_date =
                                recognized_to_date + %s,
                            remaining_balance =
                                GREATEST(
                                    remaining_balance - %s,
                                    0
                                ),
                            status = CASE
                                WHEN GREATEST(
                                    remaining_balance - %s,
                                    0
                                ) = 0
                                THEN 'completed'
                                ELSE status
                            END,
                            updated_by_user_id = %s,
                            updated_at = NOW()
                        WHERE company_id = %s
                        AND id = %s
                    """, (
                        e["recognition_amount"],
                        e["recognition_amount"],
                        e["recognition_amount"],
                        user_id,
                        int(company_id),
                        int(e["item_id"]),
                    ))

                cur.execute(f"""
                    UPDATE {schema}.accrual_deferral_runs
                    SET status = 'posted',
                        journal_id = %s,
                        total_recognition_amount = %s,
                        posted_by_user_id = %s,
                        posted_at = NOW()
                    WHERE company_id = %s
                    AND id = %s
                    RETURNING *
                """, (
                    journal_id,
                    preview.get("total") or 0,
                    user_id,
                    int(company_id),
                    int(run_id),
                ))

                posted_run = cur.fetchone()

                conn.commit()

                return {
                    "journal_id": journal_id,
                    "preview": preview,
                    "run": posted_run,
                }

            except Exception:
                conn.rollback()
                raise

    def accrual_deferral_build_item_preview_from_payload(
        self,
        company_id: int,
        payload: dict,
    ):
        schema = self.company_schema(company_id)

        # ---------------------------------------------------------
        # Local helpers
        # ---------------------------------------------------------
        def account_code(value) -> str:
            if value is None:
                return ""

            if isinstance(value, str):
                return value.strip()

            if isinstance(value, dict):
                return str(
                    value.get("posting_code")
                    or value.get("account_code")
                    or value.get("code")
                    or ""
                ).strip()

            if isinstance(value, (tuple, list)):
                for candidate in value:
                    if isinstance(candidate, str) and candidate.strip():
                        return candidate.strip()

            return str(value or "").strip()

        def account_name(code: str, fallback: str = "") -> str:
            code = account_code(code)

            if not code:
                return fallback or ""

            row = self.fetch_one(
                f"""
                SELECT code, name
                FROM {schema}.coa
                WHERE code = %s
                LIMIT 1
                """,
                (code,),
            ) or {}

            return str(
                row.get("name")
                or fallback
                or code
            ).strip()

        def resolve_role(role: str, fallback_name: str = "") -> dict:
            role = str(role or "").strip()

            if not role:
                raise ValueError("Account role is required")

            resolved = self.accrual_deferral_account_by_role(
                company_id,
                role,
            )

            code = account_code(resolved)

            if not code:
                raise ValueError(f"Missing COA role mapping: {role}")

            name = ""

            if isinstance(resolved, dict):
                name = str(
                    resolved.get("name")
                    or resolved.get("account_name")
                    or ""
                ).strip()

            return {
                "code": code,
                "name": (
                    name
                    or account_name(code, fallback_name)
                    or fallback_name
                    or code
                ),
                "role": role,
            }

        def resolve_ap_control() -> dict:
            settings = self.get_company_account_settings(company_id) or {}

            raw = str(
                settings.get("ap_control_code")
                or ""
            ).strip()

            if not raw:
                raise ValueError(
                    "AP control account is not configured in "
                    "company_account_settings.ap_control_code"
                )

            posting_row = self.get_account_row_for_posting(
                company_id,
                raw,
            )

            if not posting_row:
                raise ValueError(
                    f"AP control account '{raw}' was not found in the company COA"
                )

            if isinstance(posting_row, dict):
                code = account_code(posting_row) or raw

                name = str(
                    posting_row.get("name")
                    or posting_row.get("account_name")
                    or ""
                ).strip()
            else:
                code = str(
                    posting_row[1]
                    if len(posting_row) > 1 and posting_row[1]
                    else raw
                ).strip()

                name = str(
                    posting_row[2]
                    if len(posting_row) > 2 and posting_row[2]
                    else ""
                ).strip()

            if not code:
                raise ValueError(
                    f"Resolved AP posting code is blank for '{raw}'"
                )

            return {
                "code": code,
                "name": (
                    name
                    or account_name(code, "Accounts Payable")
                    or "Accounts Payable"
                ),
                "role": "accounts_payable",
            }

        # ---------------------------------------------------------
        # Main payload
        # ---------------------------------------------------------
        item_type = str(
            payload.get("item_type")
            or "prepaid_expense"
        ).strip().lower()

        item_title = str(
            payload.get("item_title")
            or "Accrual/Deferral"
        ).strip()

        amount = round(
            float(payload.get("original_amount") or 0),
            2,
        )

        currency = str(
            payload.get("currency")
            or self.company_currency(company_id)
            or "USD"
        ).strip().upper()

        settlement_method = str(
            payload.get("settlement_method")
            or ""
        ).strip().lower()

        if amount <= 0:
            raise ValueError("original_amount must be greater than zero")

        if settlement_method not in {
            "cash_bank",
            "accounts_payable",
        }:
            raise ValueError(
                "settlement_method must be cash_bank or accounts_payable"
            )

        # ---------------------------------------------------------
        # Validate dates before generating schedule
        # ---------------------------------------------------------
        start_date = _date(payload.get("start_date"))
        end_date = _date(payload.get("end_date"))

        if not start_date or not end_date:
            raise ValueError("start_date and end_date are required")

        if end_date < start_date:
            raise ValueError("end_date cannot be before start_date")

        # ---------------------------------------------------------
        # Balance account
        # ---------------------------------------------------------
        balance_role = str(
            payload.get("balance_account_role")
            or item_type
        ).strip()

        supplied_balance = account_code(
            payload.get("balance_account")
        )

        if supplied_balance:
            balance_account = {
                "code": supplied_balance,
                "name": account_name(
                    supplied_balance,
                    balance_role.replace("_", " ").title(),
                ),
                "role": balance_role,
            }
        else:
            balance_account = resolve_role(
                balance_role,
                balance_role.replace("_", " ").title(),
            )

        # ---------------------------------------------------------
        # Recognition account
        # ---------------------------------------------------------
        recognition_role = str(
            payload.get("recognition_account_role")
            or ""
        ).strip()

        supplied_recognition = account_code(
            payload.get("recognition_account")
        )

        recognition_account = None

        if supplied_recognition:
            recognition_account = {
                "code": supplied_recognition,
                "name": account_name(
                    supplied_recognition,
                    (
                        recognition_role.replace("_", " ").title()
                        if recognition_role
                        else "Recognition Account"
                    ),
                ),
                "role": recognition_role or None,
            }

        elif recognition_role:
            recognition_account = resolve_role(
                recognition_role,
                recognition_role.replace("_", " ").title(),
            )

        # ---------------------------------------------------------
        # Settlement account
        # ---------------------------------------------------------
        if settlement_method == "accounts_payable":
            settlement_account = resolve_ap_control()

        else:
            supplied_settlement = account_code(
                payload.get("settlement_account")
            )

            if not supplied_settlement:
                raise ValueError("Select the company bank account")

            bank_account_display_name = str(
                payload.get("settlement_account_name")
                or ""
            ).strip()

            gl_account_name = account_name(
                supplied_settlement,
                "Cash & Bank",
            )

            settlement_account = {
                "code": supplied_settlement,

                # Journal preview must show the linked GL account name.
                "name": gl_account_name,

                "role": "cash_bank",

                # Keep the actual bank-account name only as supporting metadata.
                "bank_account_name": bank_account_display_name,
            }

        # ---------------------------------------------------------
        # Initial journal
        # ---------------------------------------------------------
        if item_type in {
            "prepaid_expense",
            "deferred_expense",
            "accrued_income",
        }:
            lines = [
                {
                    "account_code": balance_account["code"],
                    "account_name": balance_account["name"],
                    "debit": amount,
                    "credit": 0.0,
                    "description": item_title,
                },
                {
                    "account_code": settlement_account["code"],
                    "account_name": settlement_account["name"],
                    "debit": 0.0,
                    "credit": amount,
                    "description": item_title,
                },
            ]

        elif item_type in {
            "deferred_income",
            "accrued_expense",
        }:
            lines = [
                {
                    "account_code": settlement_account["code"],
                    "account_name": settlement_account["name"],
                    "debit": amount,
                    "credit": 0.0,
                    "description": item_title,
                },
                {
                    "account_code": balance_account["code"],
                    "account_name": balance_account["name"],
                    "debit": 0.0,
                    "credit": amount,
                    "description": item_title,
                },
            ]

        else:
            raise ValueError(f"Unsupported item_type: {item_type}")

        total_debit = round(
            sum(float(line.get("debit") or 0) for line in lines),
            2,
        )

        total_credit = round(
            sum(float(line.get("credit") or 0) for line in lines),
            2,
        )

        schedule = self.accrual_deferral_schedule_preview_from_payload(
            company_id,
            payload,
        )

        journal_ref = str(
            payload.get("journal_ref")
            or payload.get("reference")
            or "AD-INIT-DRAFT"
        ).strip()

        warnings = []

        if settlement_method == "accounts_payable":
            warnings.append(
                "Initial recognition will be posted through the Accounts Payable bill workflow."
            )

        return {
            "journal": {
                "date": payload.get("transaction_date"),
                "ref": journal_ref,
                "description": f"Initial recognition - {item_title}",
                "source": "accrual_deferral_initial",
                "source_id": None,
                "module_name": "accrual_deferrals",
                "currency": currency,
                "lines": lines,
                "total_debit": total_debit,
                "total_credit": total_credit,
                "balanced": round(total_debit, 2) == round(total_credit, 2),
                "posting_route": (
                    "accounts_payable"
                    if settlement_method == "accounts_payable"
                    else "accrual_deferrals"
                ),
            },
            "accounts": {
                "settlement": settlement_account,
                "balance": balance_account,
                "recognition": recognition_account,

                "bank_account": (
                    {
                        "name": settlement_account.get("bank_account_name"),
                        "gl_account_code": settlement_account.get("code"),
                        "gl_account_name": settlement_account.get("name"),
                    }
                    if settlement_method == "cash_bank"
                    else None
                ),
            },
            "schedule_preview": schedule,
            "warnings": warnings,
        }

    def accrual_deferral_schedule_preview_from_payload(self, company_id: int, payload: dict):
        start = _date(payload.get("start_date"))
        end = _date(payload.get("end_date"))
        amount = _d(payload.get("original_amount"))

        if not start or not end or amount <= 0:
            return []

        months = []
        d = date(start.year, start.month, 1)

        while d <= end:
            ps = max(d, start)
            pe = min(_month_end(d), end)
            months.append((ps, pe))
            d = _add_month(d)

        if not months:
            return []

        monthly_amount = (amount / Decimal(len(months))).quantize(Decimal("0.01"))
        opening = amount
        rows = []

        for idx, (ps, pe) in enumerate(months, start=1):
            recognition_amount = opening if idx == len(months) else monthly_amount
            closing = opening - recognition_amount

            rows.append({
                "line_no": idx,
                "period_start": ps.isoformat(),
                "period_end": pe.isoformat(),
                "recognition_date": pe.isoformat(),
                "opening_balance": float(opening),
                "recognition_amount": float(recognition_amount),
                "closing_balance": float(closing),
                "status": "pending",
            })

            opening = closing

        return rows


    def accrual_deferral_create_and_post_initial(self, company_id: int, payload: dict, user_id=None):
        item = self.accrual_deferral_create_item(company_id, payload, user_id=user_id)
        item_id = item["item"]["id"]

        posted = self.accrual_deferral_post_initial(
            company_id,
            item_id,
            {
                "settlement_account": payload.get("settlement_account"),
                "settlement_role": payload.get("settlement_role") or "cash_bank",
            },
            user_id=user_id,
        )

        return posted

    def _num(self, v, default=0):
        if v is None or v == "":
            return Decimal(str(default))
        return Decimal(str(v))


    def ifrs9_list_instruments(self, company_id: int, instrument_type=None, status=None):
        schema = self.company_schema(company_id)

        where = ["company_id = %s"]
        params = [int(company_id)]

        if instrument_type:
            where.append("instrument_type = %s")
            params.append(instrument_type)

        if status:
            where.append("status = %s")
            params.append(status)

        sql = f"""
            SELECT *
            FROM {schema}.ifrs9_financial_instruments
            WHERE {" AND ".join(where)}
            ORDER BY recognition_date DESC, id DESC
        """

        return self.fetch_all(sql, tuple(params))


    def ifrs9_get_instrument(self, company_id: int, instrument_id: int):
        schema = self.company_schema(company_id)

        instrument = self.fetch_one(f"""
            SELECT *
            FROM {schema}.ifrs9_financial_instruments
            WHERE company_id = %s
            AND id = %s
        """, (int(company_id), int(instrument_id)))

        if not instrument:
            return None

        classifications = self.fetch_all(f"""
            SELECT *
            FROM {schema}.ifrs9_classifications
            WHERE company_id = %s
            AND instrument_id = %s
            ORDER BY classification_date DESC, id DESC
        """, (int(company_id), int(instrument_id)))

        eir_terms = self.fetch_all(f"""
            SELECT *
            FROM {schema}.ifrs9_effective_interest_terms
            WHERE company_id = %s
            AND instrument_id = %s
            ORDER BY effective_date DESC, id DESC
        """, (int(company_id), int(instrument_id)))

        return {
            "item": instrument,
            "classifications": classifications,
            "effective_interest_terms": eir_terms,
        }


    def ifrs9_create_instrument(self, company_id: int, payload: dict, cur=None):
        schema = self.company_schema(company_id)

        instrument_name = (payload.get("instrument_name") or "").strip()
        instrument_type = (payload.get("instrument_type") or "").strip()
        recognition_date = payload.get("recognition_date")

        if not instrument_name:
            raise ValueError("instrument_name is required")

        if not instrument_type:
            raise ValueError("instrument_type is required")

        if not recognition_date:
            raise ValueError("recognition_date is required")

        sql = f"""
            INSERT INTO {schema}.ifrs9_financial_instruments (
                company_id,
                instrument_name,
                instrument_reference,
                instrument_type,
                source_table,
                source_id,
                loan_id,
                customer_id,
                vendor_id,
                invoice_id,
                bill_id,
                counterparty_name,
                counterparty_type,
                recognition_date,
                derecognition_date,
                currency,
                original_amount,
                carrying_amount,
                classification_status,
                measurement_category,
                business_model,
                sppi_result,
                effective_interest_rate,
                contractual_interest_rate,
                status,
                created_by,
                meta_json
            )
            VALUES (
                %s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,
                %s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,
                %s,%s,%s,%s,COALESCE(%s::jsonb, '{{}}'::jsonb)
            )
            RETURNING *
        """

        params = (
            int(company_id),
            instrument_name,
            payload.get("instrument_reference"),
            instrument_type,
            payload.get("source_table"),
            payload.get("source_id"),
            payload.get("loan_id"),
            payload.get("customer_id"),
            payload.get("vendor_id"),
            payload.get("invoice_id"),
            payload.get("bill_id"),
            payload.get("counterparty_name"),
            payload.get("counterparty_type"),
            recognition_date,
            payload.get("derecognition_date"),
            (
                payload.get("currency")
                or self.company_currency(company_id)
            ),
            self._num(payload.get("original_amount")),
            self._num(payload.get("carrying_amount", payload.get("original_amount") or 0)),
            payload.get("classification_status") or "unclassified",
            payload.get("measurement_category"),
            payload.get("business_model"),
            payload.get("sppi_result"),
            payload.get("effective_interest_rate"),
            payload.get("contractual_interest_rate"),
            payload.get("status") or "active",
            payload.get("created_by"),
            payload.get("meta_json"),
        )

        if cur:
            cur.execute(sql, params)
            return cur.fetchone()

        return self.execute_sql(sql, params, fetchone=True)


    def ifrs9_update_instrument(self, company_id: int, instrument_id: int, payload: dict):
        schema = self.company_schema(company_id)

        allowed = {
            "instrument_name",
            "instrument_reference",
            "counterparty_name",
            "counterparty_type",
            "derecognition_date",
            "currency",
            "original_amount",
            "carrying_amount",
            "classification_status",
            "measurement_category",
            "business_model",
            "sppi_result",
            "effective_interest_rate",
            "contractual_interest_rate",
            "status",
            "meta_json",
        }

        updates = []
        params = []

        for key in allowed:
            if key in payload:
                if key in {"original_amount", "carrying_amount"}:
                    updates.append(f"{key} = %s")
                    params.append(self._num(payload.get(key)))
                elif key == "meta_json":
                    updates.append("meta_json = COALESCE(%s::jsonb, '{}'::jsonb)")
                    params.append(payload.get(key))
                else:
                    updates.append(f"{key} = %s")
                    params.append(payload.get(key))

        if not updates:
            return self.ifrs9_get_instrument(company_id, instrument_id)["item"]

        updates.append("updated_at = NOW()")

        params.extend([int(company_id), int(instrument_id)])

        sql = f"""
            UPDATE {schema}.ifrs9_financial_instruments
            SET {", ".join(updates)}
            WHERE company_id = %s
            AND id = %s
            RETURNING *
        """

        return self.execute_sql(sql, tuple(params), fetchone=True)


    def ifrs9_classify_instrument(self, company_id: int, instrument_id: int, payload: dict):
        schema = self.company_schema(company_id)

        classification_date = payload.get("classification_date") or date.today().isoformat()
        business_model = payload.get("business_model")
        sppi_result = payload.get("sppi_result")
        measurement_category = payload.get("measurement_category")

        if not business_model:
            raise ValueError("business_model is required")

        if not sppi_result:
            raise ValueError("sppi_result is required")

        if not measurement_category:
            raise ValueError("measurement_category is required")

        with self.transaction() as (conn, cur):
            cur.execute(f"""
                INSERT INTO {schema}.ifrs9_classifications (
                    company_id,
                    instrument_id,
                    classification_date,
                    business_model,
                    sppi_result,
                    measurement_category,
                    reason,
                    approved_by,
                    approved_at,
                    meta_json
                )
                VALUES (%s,%s,%s,%s,%s,%s,%s,%s,NOW(),COALESCE(%s::jsonb, '{{}}'::jsonb))
                RETURNING *
            """, (
                int(company_id),
                int(instrument_id),
                classification_date,
                business_model,
                sppi_result,
                measurement_category,
                payload.get("reason"),
                payload.get("approved_by"),
                payload.get("meta_json"),
            ))

            classification = cur.fetchone()

            cur.execute(f"""
                UPDATE {schema}.ifrs9_financial_instruments
                SET classification_status = 'classified',
                    business_model = %s,
                    sppi_result = %s,
                    measurement_category = %s,
                    updated_at = NOW()
                WHERE company_id = %s
                AND id = %s
                RETURNING *
            """, (
                business_model,
                sppi_result,
                measurement_category,
                int(company_id),
                int(instrument_id),
            ))

            instrument = cur.fetchone()

        return {
            "classification": classification,
            "instrument": instrument,
        }


    def ifrs9_create_eir_terms(
        self,
        company_id: int,
        instrument_id: int,
        payload: dict,
        *,
        user_id=None,
    ):
        schema = self.company_schema(company_id)
        method = str(
            payload.get("calculation_method") or "system"
        ).strip()

        if method not in {"system", "manual"}:
            raise ValueError(
                "calculation_method must be system or manual"
            )

        if method == "system":
            calculation = self.ifrs9_calculate_eir(
                company_id,
                instrument_id,
                payload,
            )
            effective_rate = calculation["annual_eir"]
            initial_carrying = calculation[
                "initial_carrying_amount"
            ]
            periods_per_year = calculation[
                "periods_per_year"
            ]
            total_periods = calculation["total_periods"]
        else:
            calculation = None
            effective_rate = float(
                payload.get("effective_interest_rate") or 0
            )
            initial_carrying = self._money2(
                payload.get("initial_carrying_amount")
            )
            periods_per_year = int(
                payload.get("periods_per_year") or 1
            )
            total_periods = int(
                payload.get("total_periods") or 1
            )

            if effective_rate <= -1:
                raise ValueError(
                    "Manual effective interest rate is invalid"
                )

            if initial_carrying <= 0:
                raise ValueError(
                    "Manual initial carrying amount is required"
                )

        effective_date = (
            payload.get("effective_date")
            or date.today().isoformat()
        )

        with self.transaction() as (conn, cur):
            cur.execute(f"""
                INSERT INTO {schema}.ifrs9_effective_interest_terms (
                    company_id,
                    instrument_id,
                    effective_date,
                    contractual_rate,
                    effective_interest_rate,
                    transaction_costs,
                    fees_received,
                    fees_paid,
                    premium_amount,
                    discount_amount,
                    calculation_method,
                    notes,
                    initial_principal,
                    initial_carrying_amount,
                    maturity_date,
                    payment_frequency,
                    periods_per_year,
                    total_periods,
                    cashflows_json,
                    calculated_at,
                    calculated_by,
                    created_at,
                    updated_at,
                    meta_json
                )
                VALUES (
                    %s,%s,%s,%s,%s,%s,%s,%s,%s,%s,
                    %s,%s,%s,%s,%s,%s,%s,%s,
                    %s::jsonb,NOW(),%s,NOW(),NOW(),%s::jsonb
                )
                ON CONFLICT (
                    company_id,
                    instrument_id,
                    effective_date
                )
                DO UPDATE SET
                    contractual_rate=EXCLUDED.contractual_rate,
                    effective_interest_rate=
                        EXCLUDED.effective_interest_rate,
                    transaction_costs=EXCLUDED.transaction_costs,
                    fees_received=EXCLUDED.fees_received,
                    fees_paid=EXCLUDED.fees_paid,
                    premium_amount=EXCLUDED.premium_amount,
                    discount_amount=EXCLUDED.discount_amount,
                    calculation_method=
                        EXCLUDED.calculation_method,
                    notes=EXCLUDED.notes,
                    initial_principal=
                        EXCLUDED.initial_principal,
                    initial_carrying_amount=
                        EXCLUDED.initial_carrying_amount,
                    maturity_date=EXCLUDED.maturity_date,
                    payment_frequency=
                        EXCLUDED.payment_frequency,
                    periods_per_year=
                        EXCLUDED.periods_per_year,
                    total_periods=EXCLUDED.total_periods,
                    cashflows_json=EXCLUDED.cashflows_json,
                    calculated_at=NOW(),
                    calculated_by=EXCLUDED.calculated_by,
                    updated_at=NOW(),
                    meta_json=EXCLUDED.meta_json
                RETURNING *
            """, (
                int(company_id),
                int(instrument_id),
                effective_date,
                payload.get("contractual_rate") or 0,
                effective_rate,
                self._money2(payload.get("transaction_costs")),
                self._money2(payload.get("fees_received")),
                self._money2(payload.get("fees_paid")),
                self._money2(payload.get("premium_amount")),
                self._money2(payload.get("discount_amount")),
                method,
                payload.get("notes"),
                self._money2(
                    payload.get(
                        "initial_principal",
                        calculation["initial_principal"]
                        if calculation else 0,
                    )
                ),
                initial_carrying,
                payload.get("maturity_date"),
                payload.get("payment_frequency") or "annual",
                periods_per_year,
                total_periods,
                json.dumps(
                    payload.get("cashflows") or [],
                    default=str,
                ),
                user_id,
                json.dumps({
                    "calculation": calculation,
                }, default=str),
            ))

            item = cur.fetchone()

            cur.execute(f"""
                UPDATE {schema}.ifrs9_financial_instruments
                SET effective_interest_rate=%s,
                    contractual_interest_rate=%s,
                    carrying_amount=%s,
                    updated_at=NOW()
                WHERE company_id=%s
                AND id=%s
                RETURNING *
            """, (
                effective_rate,
                payload.get("contractual_rate") or 0,
                initial_carrying,
                int(company_id),
                int(instrument_id),
            ))

            instrument = cur.fetchone()

        return {
            "item": item,
            "instrument": instrument,
            "calculation": calculation,
        }

    def _ifrs9_npv(self, rate, initial_amount, cashflows):
        return -float(initial_amount) + sum(
            float(row["amount"]) / ((1.0 + rate) ** int(row["period_no"]))
            for row in cashflows
        )


    def _ifrs9_solve_eir(self, initial_amount, cashflows):
        initial_amount = float(initial_amount or 0)

        if initial_amount <= 0:
            raise ValueError(
                "Initial carrying amount must be greater than zero"
            )

        rows = sorted(
            [
                {
                    "period_no": int(row.get("period_no") or 0),
                    "amount": float(row.get("amount") or 0),
                    "payment_date": row.get("payment_date"),
                }
                for row in cashflows or []
            ],
            key=lambda row: row["period_no"],
        )

        if not rows:
            raise ValueError(
                "At least one contractual cash flow is required"
            )

        if any(row["period_no"] <= 0 for row in rows):
            raise ValueError(
                "Every cash flow period must be greater than zero"
            )

        if any(row["amount"] < 0 for row in rows):
            raise ValueError(
                "Contractual cash-flow amounts cannot be negative"
            )

        if sum(row["amount"] for row in rows) <= 0:
            raise ValueError(
                "Total contractual cash flows must be greater than zero"
            )

        low, high = -0.999999, 1.0
        low_npv = self._ifrs9_npv(
            low,
            initial_amount,
            rows,
        )
        high_npv = self._ifrs9_npv(
            high,
            initial_amount,
            rows,
        )

        while low_npv * high_npv > 0 and high < 1000:
            high *= 2
            high_npv = self._ifrs9_npv(
                high,
                initial_amount,
                rows,
            )

        if low_npv * high_npv > 0:
            raise ValueError(
                "An effective interest rate could not be calculated "
                "from the supplied cash flows"
            )

        for _ in range(200):
            mid = (low + high) / 2
            mid_npv = self._ifrs9_npv(
                mid,
                initial_amount,
                rows,
            )

            if abs(mid_npv) < 0.0000001:
                return mid

            if low_npv * mid_npv <= 0:
                high = mid
            else:
                low = mid
                low_npv = mid_npv

        return (low + high) / 2

    def ifrs9_calculate_eir(
        self,
        company_id: int,
        instrument_id: int,
        payload: dict,
    ):
        schema = self.company_schema(company_id)

        instrument = self.fetch_one(f"""
            SELECT *
            FROM {schema}.ifrs9_financial_instruments
            WHERE company_id=%s
            AND id=%s
        """, (
            int(company_id),
            int(instrument_id),
        ))

        if not instrument:
            raise ValueError("IFRS 9 instrument not found")

        if instrument.get("measurement_category") != "amortised_cost":
            raise ValueError(
                "Effective interest applies only to instruments "
                "measured at amortised cost"
            )

        if instrument.get("status") != "active":
            raise ValueError(
                "Effective interest can only be calculated "
                "for active instruments"
            )

        frequency = str(
            payload.get("payment_frequency") or "monthly"
        ).strip()

        frequency_periods = {
            "monthly": 12,
            "quarterly": 4,
            "semi_annual": 2,
            "annual": 1,
            "irregular": 1,
        }

        if frequency not in frequency_periods:
            raise ValueError("Invalid payment frequency")

        periods_per_year = int(
            payload.get("periods_per_year")
            or frequency_periods[frequency]
        )

        principal = self._money2(
            payload.get(
                "initial_principal",
                instrument.get("original_amount"),
            )
        )

        transaction_costs = self._money2(
            payload.get("transaction_costs")
        )
        fees_received = self._money2(
            payload.get("fees_received")
        )
        fees_paid = self._money2(
            payload.get("fees_paid")
        )
        premium = self._money2(
            payload.get("premium_amount")
        )
        discount = self._money2(
            payload.get("discount_amount")
        )

        asset_types = {
            "loan_receivable",
            "staff_loan",
            "director_loan",
            "deposit_asset",
            "bond",
            "note_receivable",
            "other_financial_asset",
        }

        is_asset = instrument.get("instrument_type") in asset_types

        if is_asset:
            initial_carrying = self._money2(
                principal
                + transaction_costs
                + fees_paid
                + premium
                - fees_received
                - discount
            )
        else:
            initial_carrying = self._money2(
                principal
                - transaction_costs
                - fees_paid
                - premium
                + fees_received
                + discount
            )

        if initial_carrying <= 0:
            raise ValueError(
                "Calculated initial carrying amount must be greater than zero"
            )

        cashflows = payload.get("cashflows") or []
        periodic_rate = self._ifrs9_solve_eir(
            initial_carrying,
            cashflows,
        )

        annual_rate = (
            (1.0 + periodic_rate) ** periods_per_year
        ) - 1.0

        return {
            "instrument_id": int(instrument_id),
            "instrument_type": instrument.get("instrument_type"),
            "initial_principal": float(principal),
            "initial_carrying_amount": float(initial_carrying),
            "periodic_eir": periodic_rate,
            "annual_eir": annual_rate,
            "annual_eir_percent": annual_rate * 100,
            "periods_per_year": periods_per_year,
            "payment_frequency": frequency,
            "total_periods": len(cashflows),
            "cashflows": cashflows,
        }

    def ifrs9_list_ecl_models(self, company_id: int):
        schema = self.company_schema(company_id)

        return self.fetch_all(f"""
            SELECT *
            FROM {schema}.ifrs9_ecl_models
            WHERE company_id = %s
            ORDER BY is_active DESC, model_name
        """, (int(company_id),))


    def ifrs9_create_ecl_model(
        self,
        company_id: int,
        payload: dict,
    ):
        schema = self.company_schema(company_id)

        model_name = str(
            payload.get("model_name") or ""
        ).strip()

        model_type = str(
            payload.get("model_type") or "simplified"
        ).strip()

        applies_to = str(
            payload.get("applies_to") or "trade_receivable"
        ).strip()

        basis = str(
            payload.get("basis") or "provision_matrix"
        ).strip()

        if not model_name:
            raise ValueError("model_name is required")

        # Only this workflow is implemented in Phase 1.
        if model_type != "simplified":
            raise ValueError(
                "Only simplified ECL models are currently supported"
            )

        if applies_to != "trade_receivable":
            raise ValueError(
                "Phase 1 ECL models must apply to trade receivables"
            )

        if basis != "provision_matrix":
            raise ValueError(
                "Only provision matrix ECL models are currently supported"
            )

        duplicate = self.fetch_one(f"""
            SELECT id
            FROM {schema}.ifrs9_ecl_models
            WHERE company_id=%s
            AND LOWER(TRIM(model_name))=LOWER(TRIM(%s))
            AND is_active=TRUE
            LIMIT 1
        """, (
            int(company_id),
            model_name,
        ))

        if duplicate:
            raise ValueError(
                "An active ECL model with this name already exists"
            )

        return self.execute_sql(f"""
            INSERT INTO {schema}.ifrs9_ecl_models (
                company_id,
                model_name,
                model_type,
                applies_to,
                basis,
                is_active,
                effective_from,
                effective_to,
                version_no,
                approval_status,
                review_date,
                model_owner,
                created_by,
                created_at,
                updated_at,
                meta_json
            )
            VALUES (
                %s,%s,%s,%s,%s,TRUE,%s,%s,1,'draft',
                %s,%s,%s,NOW(),NOW(),
                COALESCE(%s::jsonb, '{{}}'::jsonb)
            )
            RETURNING *
        """, (
            int(company_id),
            model_name,
            model_type,
            applies_to,
            basis,
            payload.get("effective_from"),
            payload.get("effective_to"),
            payload.get("review_date"),
            payload.get("model_owner"),
            payload.get("created_by"),
            payload.get("meta_json"),
        ), fetchone=True)

    def ifrs9_update_ecl_model(
        self,
        company_id: int,
        model_id: int,
        payload: dict,
    ):
        schema = self.company_schema(company_id)

        existing = self.fetch_one(f"""
            SELECT *
            FROM {schema}.ifrs9_ecl_models
            WHERE company_id=%s
            AND id=%s
        """, (
            int(company_id),
            int(model_id),
        ))

        if not existing:
            raise ValueError("IFRS 9 ECL model not found")

        posted_runs = self.fetch_one(f"""
            SELECT COUNT(*) AS count
            FROM {schema}.ifrs9_ecl_runs
            WHERE company_id=%s
            AND model_id=%s
            AND status='posted'
        """, (
            int(company_id),
            int(model_id),
        ))

        has_posted_runs = int(
            (posted_runs or {}).get("count") or 0
        ) > 0

        immutable_fields = {
            "model_type",
            "applies_to",
            "basis",
        }

        if has_posted_runs and any(
            key in payload
            and payload.get(key) != existing.get(key)
            for key in immutable_fields
        ):
            raise ValueError(
                "Model type, application and basis cannot be changed "
                "after ECL runs have been posted"
            )

        model_name = str(
            payload.get(
                "model_name",
                existing.get("model_name"),
            ) or ""
        ).strip()

        if not model_name:
            raise ValueError("model_name is required")

        effective_from = payload.get(
            "effective_from",
            existing.get("effective_from"),
        )

        effective_to = payload.get(
            "effective_to",
            existing.get("effective_to"),
        )

        if (
            effective_from
            and effective_to
            and str(effective_to) < str(effective_from)
        ):
            raise ValueError(
                "effective_to cannot be earlier than effective_from"
            )

        return self.execute_sql(f"""
            UPDATE {schema}.ifrs9_ecl_models
            SET model_name=%s,
                effective_from=%s,
                effective_to=%s,
                review_date=%s,
                model_owner=%s,
                updated_at=NOW(),
                meta_json=COALESCE(
                    %s::jsonb,
                    meta_json,
                    '{{}}'::jsonb
                )
            WHERE company_id=%s
            AND id=%s
            RETURNING *
        """, (
            model_name,
            effective_from,
            effective_to,
            payload.get(
                "review_date",
                existing.get("review_date"),
            ),
            payload.get(
                "model_owner",
                existing.get("model_owner"),
            ),
            payload.get("meta_json"),
            int(company_id),
            int(model_id),
        ), fetchone=True)

    def ifrs9_activate_ecl_model(
        self,
        company_id: int,
        model_id: int,
        *,
        user_id=None,
    ):
        schema = self.company_schema(company_id)

        model = self.ifrs9_get_ecl_model(
            company_id,
            model_id,
        )

        if not model:
            raise ValueError("IFRS 9 ECL model not found")

        item = model["model"]
        bands = model.get("bands") or []

        if item.get("model_type") != "simplified":
            raise ValueError(
                "Only simplified ECL models may currently be activated"
            )

        if item.get("applies_to") != "trade_receivable":
            raise ValueError(
                "The model must apply to trade receivables"
            )

        if item.get("basis") != "provision_matrix":
            raise ValueError(
                "The model must use a provision matrix"
            )

        if not bands:
            raise ValueError(
                "Configure the provision matrix before activating the model"
            )

        ordered = sorted(
            bands,
            key=lambda row: int(row.get("days_from") or 0),
        )

        if int(ordered[0].get("days_from") or 0) != 0:
            raise ValueError(
                "The provision matrix must start at day 0"
            )

        if ordered[-1].get("days_to") is not None:
            raise ValueError(
                "The final provision matrix band must be open-ended"
            )

        for index, current in enumerate(ordered[:-1]):
            following = ordered[index + 1]

            current_to = current.get("days_to")
            following_from = int(
                following.get("days_from") or 0
            )

            if current_to is None:
                raise ValueError(
                    "Only the final matrix band may be open-ended"
                )

            if following_from != int(current_to) + 1:
                raise ValueError(
                    "The provision matrix contains a gap or overlap"
                )

        return self.execute_sql(f"""
            UPDATE {schema}.ifrs9_ecl_models
            SET is_active=TRUE,
                approval_status='approved',
                approved_by=%s,
                approved_at=NOW(),
                effective_from=COALESCE(
                    effective_from,
                    CURRENT_DATE
                ),
                updated_at=NOW()
            WHERE company_id=%s
            AND id=%s
            RETURNING *
        """, (
            user_id,
            int(company_id),
            int(model_id),
        ), fetchone=True)

    def ifrs9_deactivate_ecl_model(
        self,
        company_id: int,
        model_id: int,
        *,
        user_id=None,
    ):
        schema = self.company_schema(company_id)

        draft_run = self.fetch_one(f"""
            SELECT id
            FROM {schema}.ifrs9_ecl_runs
            WHERE company_id=%s
            AND model_id=%s
            AND status='draft'
            ORDER BY id DESC
            LIMIT 1
        """, (
            int(company_id),
            int(model_id),
        ))

        if draft_run:
            raise ValueError(
                f"Model cannot be deactivated while draft ECL run "
                f"{draft_run['id']} exists"
            )

        return self.execute_sql(f"""
            UPDATE {schema}.ifrs9_ecl_models
            SET is_active=FALSE,
                approval_status='retired',
                effective_to=COALESCE(
                    effective_to,
                    CURRENT_DATE
                ),
                updated_at=NOW(),
                meta_json=COALESCE(
                    meta_json,
                    '{{}}'::jsonb
                ) || jsonb_build_object(
                    'deactivated_by', %s,
                    'deactivated_at', NOW()
                )
            WHERE company_id=%s
            AND id=%s
            RETURNING *
        """, (
            user_id,
            int(company_id),
            int(model_id),
        ))

    def ifrs9_set_ecl_matrix_bands(self, company_id: int, model_id: int, bands: list):
        schema = self.company_schema(company_id)
        model = self.fetch_one(f"""
            SELECT id, model_type, basis, is_active
            FROM {schema}.ifrs9_ecl_models
            WHERE company_id=%s AND id=%s
        """, (int(company_id), int(model_id)))

        if not model:
            raise ValueError("IFRS 9 ECL model not found")
        if model.get("basis") != "provision_matrix":
            raise ValueError("Provision matrix bands can only be saved for provision matrix models")
        if not bands:
            raise ValueError("At least one provision matrix band is required")

        cleaned = []
        labels = set()

        for raw in bands:
            label = str(raw.get("band_label") or "").strip()
            days_from = int(raw.get("days_from") or 0)
            days_to = raw.get("days_to")
            days_to = None if days_to in (None, "") else int(days_to)
            loss_rate = Decimal(str(raw.get("loss_rate") or 0))

            if not label:
                raise ValueError("Every provision matrix band requires a name")
            if label.lower() in labels:
                raise ValueError(f"Duplicate provision matrix band name: {label}")
            if days_from < 0:
                raise ValueError(f"{label}: days_from cannot be negative")
            if days_to is not None and days_to < days_from:
                raise ValueError(f"{label}: days_to cannot be less than days_from")
            if loss_rate < 0 or loss_rate > 1:
                raise ValueError(f"{label}: loss_rate must be between 0 and 1")

            labels.add(label.lower())
            cleaned.append({
                "band_label": label,
                "days_from": days_from,
                "days_to": days_to,
                "loss_rate": loss_rate,
            })

        cleaned.sort(key=lambda row: row["days_from"])

        if cleaned[0]["days_from"] != 0:
            raise ValueError("The first provision matrix band must begin at day 0")

        open_ended = [row for row in cleaned if row["days_to"] is None]
        if len(open_ended) != 1:
            raise ValueError("Exactly one open-ended provision matrix band is required")
        if cleaned[-1]["days_to"] is not None:
            raise ValueError("The final provision matrix band must be open-ended")

        for index, row in enumerate(cleaned[:-1]):
            next_row = cleaned[index + 1]

            if row["days_to"] is None:
                raise ValueError("Only the final provision matrix band may be open-ended")
            if next_row["days_from"] <= row["days_to"]:
                raise ValueError(
                    f"Provision matrix bands overlap between "
                    f"'{row['band_label']}' and '{next_row['band_label']}'"
                )
            if next_row["days_from"] != row["days_to"] + 1:
                raise ValueError(
                    f"Provision matrix gap exists between "
                    f"'{row['band_label']}' and '{next_row['band_label']}'"
                )

        with self.transaction() as (conn, cur):
            cur.execute(f"""
                DELETE FROM {schema}.ifrs9_ecl_matrix_bands
                WHERE company_id=%s AND model_id=%s
            """, (int(company_id), int(model_id)))

            inserted = []
            for row in cleaned:
                cur.execute(f"""
                    INSERT INTO {schema}.ifrs9_ecl_matrix_bands (
                        company_id, model_id, band_label,
                        days_from, days_to, loss_rate
                    )
                    VALUES (%s,%s,%s,%s,%s,%s)
                    RETURNING *
                """, (
                    int(company_id),
                    int(model_id),
                    row["band_label"],
                    row["days_from"],
                    row["days_to"],
                    row["loss_rate"],
                ))
                inserted.append(cur.fetchone())

        return inserted

    def ifrs9_get_ecl_model(self, company_id: int, model_id: int):
        schema = self.company_schema(company_id)

        model = self.fetch_one(f"""
            SELECT *
            FROM {schema}.ifrs9_ecl_models
            WHERE company_id = %s
            AND id = %s
        """, (int(company_id), int(model_id)))

        if not model:
            return None

        bands = self.fetch_all(f"""
            SELECT *
            FROM {schema}.ifrs9_ecl_matrix_bands
            WHERE company_id = %s
            AND model_id = %s
            ORDER BY days_from
        """, (int(company_id), int(model_id)))

        return {
            "model": model,
            "bands": bands,
        }


    def ifrs9_sync_loan_payables(self, company_id: int):
        schema = self.company_schema(company_id)

        sql = f"""
            INSERT INTO {schema}.ifrs9_financial_instruments (
                company_id,
                instrument_name,
                instrument_reference,
                instrument_type,
                source_table,
                source_id,
                loan_id,
                counterparty_name,
                counterparty_type,
                recognition_date,
                currency,
                original_amount,
                carrying_amount,
                classification_status,
                measurement_category,
                business_model,
                sppi_result,
                effective_interest_rate,
                contractual_interest_rate,
                status,
                meta_json
            )
            SELECT
                l.company_id,
                l.loan_name,
                l.loan_reference,
                'loan_payable',
                'loans',
                l.id,
                l.id,
                l.lender_name,
                'bank',
                l.start_date,
                COALESCE(l.currency, 'USD'),
                COALESCE(l.principal_amount, 0),
                COALESCE(l.outstanding_principal, l.principal_amount, 0),
                'classified',
                'amortised_cost',
                'hold_to_collect',
                'not_applicable',
                NULL,
                COALESCE(l.annual_interest_rate, 0),
                CASE
                    WHEN l.status = 'closed' THEN 'closed'
                    WHEN l.status = 'void' THEN 'void'
                    ELSE 'active'
                END,
                jsonb_build_object('synced_from', 'loans')
            FROM {schema}.loans l
            WHERE l.company_id = %s
            AND NOT EXISTS (
                SELECT 1
                FROM {schema}.ifrs9_financial_instruments fi
                WHERE fi.company_id = l.company_id
                    AND fi.source_table = 'loans'
                    AND fi.source_id = l.id
            )
            RETURNING *
        """

        return self.fetch_all(sql, (int(company_id),))


    def ifrs9_create_modification(
        self,
        company_id: int,
        instrument_id: int,
        payload: dict,
        *,
        user_id=None,
    ):
        schema = self.company_schema(company_id)

        reason = str(
            payload.get("reason") or ""
        ).strip()

        if not reason:
            raise ValueError("Modification reason is required")

        result = self.ifrs9_calculate_modification(
            company_id,
            instrument_id,
            payload,
        )

        duplicate = self.fetch_one(f"""
            SELECT id, journal_status
            FROM {schema}.ifrs9_modifications
            WHERE company_id=%s
            AND instrument_id=%s
            AND modification_date=%s::date
            AND journal_status IN ('draft','posted')
            ORDER BY id DESC
            LIMIT 1
        """, (
            int(company_id),
            int(instrument_id),
            result["modification_date"],
        ))

        if duplicate:
            raise ValueError(
                f"An active modification already exists on this date "
                f"(modification {duplicate['id']}, "
                f"status {duplicate['journal_status']})"
            )

        return self.execute_sql(f"""
            INSERT INTO {schema}.ifrs9_modifications (
                company_id,
                instrument_id,
                modification_date,
                modification_type,
                old_carrying_amount,
                revised_cashflow_pv,
                modification_gain_loss,
                substantial_modification,
                derecognition_required,
                original_effective_interest_rate,
                revised_contractual_rate,
                revised_maturity_date,
                revised_cashflows_json,
                percentage_change,
                journal_status,
                journal_id,
                reason,
                created_by,
                created_at,
                updated_at,
                meta_json
            )
            VALUES (
                %s,%s,%s,%s,%s,%s,%s,%s,%s,%s,
                %s,%s,%s::jsonb,%s,'draft',NULL,%s,%s,
                NOW(),NOW(),%s::jsonb
            )
            RETURNING *
        """, (
            int(company_id),
            int(instrument_id),
            result["modification_date"],
            payload.get("modification_type")
            or "cashflow_change",
            result["old_carrying_amount"],
            result["revised_cashflow_pv"],
            result["modification_gain_loss"],
            result["substantial_modification"],
            result["derecognition_required"],
            result["original_effective_interest_rate"],
            payload.get("revised_contractual_rate"),
            payload.get("revised_maturity_date"),
            json.dumps(
                payload.get("revised_cashflows") or [],
                default=str,
            ),
            result["percentage_change"],
            reason,
            user_id,
            json.dumps({
                "calculation": result,
                "substantial_threshold":
                    payload.get(
                        "substantial_threshold",
                        0.10,
                    ),
            }, default=str),
        ), fetchone=True)

    def ifrs9_list_modifications(
        self,
        company_id: int,
        instrument_id: int,
    ):
        schema = self.company_schema(company_id)

        return self.fetch_all(f"""
            SELECT
                m.*,
                fi.instrument_name,
                fi.instrument_type,
                fi.currency
            FROM {schema}.ifrs9_modifications m
            JOIN {schema}.ifrs9_financial_instruments fi
            ON fi.company_id=m.company_id
            AND fi.id=m.instrument_id
            WHERE m.company_id=%s
            AND m.instrument_id=%s
            ORDER BY m.modification_date DESC, m.id DESC
        """, (
            int(company_id),
            int(instrument_id),
        ))

    def ifrs9_get_modification(
        self,
        company_id: int,
        modification_id: int,
    ):
        schema = self.company_schema(company_id)

        return self.fetch_one(f"""
            SELECT
                m.*,
                fi.instrument_name,
                fi.instrument_type,
                fi.currency,
                fi.carrying_amount AS current_carrying_amount
            FROM {schema}.ifrs9_modifications m
            JOIN {schema}.ifrs9_financial_instruments fi
            ON fi.company_id=m.company_id
            AND fi.id=m.instrument_id
            WHERE m.company_id=%s
            AND m.id=%s
        """, (
            int(company_id),
            int(modification_id),
        ))

    def ifrs9_preview_modification_journal(
        self,
        company_id: int,
        modification_id: int,
    ):
        item = self.ifrs9_get_modification(
            company_id,
            modification_id,
        )

        if not item:
            raise ValueError(
                "IFRS 9 modification not found"
            )

        if item.get("journal_status") != "draft":
            raise ValueError(
                f"Only draft modifications may be previewed. "
                f"Current status: {item.get('journal_status')}"
            )

        if item.get("derecognition_required"):
            raise ValueError(
                "This is a substantial modification and must "
                "be processed through derecognition"
            )

        asset_types = {
            "trade_receivable",
            "loan_receivable",
            "staff_loan",
            "director_loan",
            "deposit_asset",
            "investment",
            "bond",
            "note_receivable",
            "other_financial_asset",
        }

        is_asset = (
            item.get("instrument_type")
            in asset_types
        )

        old_amount = self._money2(
            item.get("old_carrying_amount")
        )

        revised_pv = self._money2(
            item.get("revised_cashflow_pv")
        )

        change = self._money2(
            revised_pv - old_amount
        )

        if is_asset:
            instrument_code = self.ifrs9_resolve_account(
                company_id,
                "financial_asset_amortised_cost",
            )
        else:
            instrument_code = self.ifrs9_resolve_account(
                company_id,
                "financial_liability_amortised_cost",
            )

        lines = []

        if is_asset:
            if change > 0:
                # Increase asset = debit asset, credit gain.
                gain_code = self.ifrs9_resolve_account(
                    company_id,
                    "modification_gain",
                )

                lines = [
                    {
                        "account_code": instrument_code,
                        "description": (
                            f"Increase modified carrying amount: "
                            f"{item.get('instrument_name')}"
                        ),
                        "debit": change,
                        "credit": 0,
                    },
                    {
                        "account_code": gain_code,
                        "description": (
                            "Financial-asset modification gain"
                        ),
                        "debit": 0,
                        "credit": change,
                    },
                ]
            elif change < 0:
                amount = abs(change)

                loss_code = self.ifrs9_resolve_account(
                    company_id,
                    "modification_loss",
                )

                lines = [
                    {
                        "account_code": loss_code,
                        "description": (
                            "Financial-asset modification loss"
                        ),
                        "debit": amount,
                        "credit": 0,
                    },
                    {
                        "account_code": instrument_code,
                        "description": (
                            f"Reduce modified carrying amount: "
                            f"{item.get('instrument_name')}"
                        ),
                        "debit": 0,
                        "credit": amount,
                    },
                ]
        else:
            if change > 0:
                # Increase liability = debit loss, credit liability.
                loss_code = self.ifrs9_resolve_account(
                    company_id,
                    "modification_loss",
                )

                lines = [
                    {
                        "account_code": loss_code,
                        "description": (
                            "Financial-liability modification loss"
                        ),
                        "debit": change,
                        "credit": 0,
                    },
                    {
                        "account_code": instrument_code,
                        "description": (
                            f"Increase modified liability: "
                            f"{item.get('instrument_name')}"
                        ),
                        "debit": 0,
                        "credit": change,
                    },
                ]
            elif change < 0:
                amount = abs(change)

                gain_code = self.ifrs9_resolve_account(
                    company_id,
                    "modification_gain",
                )

                lines = [
                    {
                        "account_code": instrument_code,
                        "description": (
                            f"Reduce modified liability: "
                            f"{item.get('instrument_name')}"
                        ),
                        "debit": amount,
                        "credit": 0,
                    },
                    {
                        "account_code": gain_code,
                        "description": (
                            "Financial-liability modification gain"
                        ),
                        "debit": 0,
                        "credit": amount,
                    },
                ]

        if not lines:
            raise ValueError(
                "The modification does not produce a carrying-value change"
            )

        amount = abs(change)

        return {
            "modification": item,
            "date": item["modification_date"],
            "ref": f"IFRS9-MOD-{modification_id}",
            "description": (
                f"IFRS 9 modification – "
                f"{item.get('instrument_name')}"
            ),
            "currency": (
                item.get("currency")
                or self.company_currency(company_id)
            ),
            "gross_amount": float(amount),
            "net_amount": float(amount),
            "dr_total": float(amount),
            "cr_total": float(amount),
            "lines": lines,
        }

    def ifrs9_post_modification(
        self,
        company_id: int,
        modification_id: int,
        *,
        user_id=None,
    ):
        schema = self.company_schema(company_id)

        with self.transaction() as (conn, cur):
            item = self.fetch_one(f"""
                SELECT *
                FROM {schema}.ifrs9_modifications
                WHERE company_id=%s
                AND id=%s
                FOR UPDATE
            """, (
                int(company_id),
                int(modification_id),
            ), cur=cur)

            if not item:
                raise ValueError(
                    "IFRS 9 modification not found"
                )

            if item.get("journal_status") != "draft":
                raise ValueError(
                    f"Only draft modifications may be posted. "
                    f"Current status: {item.get('journal_status')}"
                )

            if item.get("journal_id"):
                raise ValueError(
                    f"Modification already has journal "
                    f"{item['journal_id']}"
                )

            if item.get("derecognition_required"):
                raise ValueError(
                    "Substantial modification requires derecognition"
                )

            preview = self.ifrs9_preview_modification_journal(
                company_id,
                modification_id,
            )

            entry = {
                "date": preview["date"],
                "ref": preview["ref"],
                "description": preview["description"],
                "gross_amount": preview["gross_amount"],
                "net_amount": preview["net_amount"],
                "vat_amount": 0,
                "currency": preview["currency"],
                "source": "ifrs9_modification",
                "source_id": int(modification_id),
                "module_name": "ifrs9",
                "created_by_user_id": user_id,
                "prepared_by_user_id": user_id,
                "lines": [
                    {
                        **line,
                        "line_no": index,
                        "source": "ifrs9_modification",
                        "source_id": int(modification_id),
                    }
                    for index, line in enumerate(
                        preview["lines"],
                        start=1,
                    )
                ],
            }

            journal_id = self.post_journal(
                company_id,
                entry,
                cur=cur,
                conn=conn,
            )

            cur.execute(f"""
                UPDATE {schema}.ifrs9_modifications
                SET journal_status='posted',
                    journal_id=%s,
                    posted_by=%s,
                    posted_at=NOW(),
                    updated_at=NOW(),
                    meta_json=COALESCE(
                        meta_json,
                        '{{}}'::jsonb
                    ) || jsonb_build_object(
                        'posted_at', NOW(),
                        'posted_by', %s,
                        'journal_preview', %s::jsonb
                    )
                WHERE company_id=%s
                AND id=%s
                AND journal_status='draft'
                AND journal_id IS NULL
                RETURNING *
            """, (
                int(journal_id),
                user_id,
                user_id,
                json.dumps(preview, default=str),
                int(company_id),
                int(modification_id),
            ))

            posted = cur.fetchone()

            if not posted:
                raise ValueError(
                    "Modification changed before posting completed"
                )

            cur.execute(f"""
                UPDATE {schema}.ifrs9_financial_instruments
                SET carrying_amount=%s,
                    contractual_interest_rate=COALESCE(
                        %s,
                        contractual_interest_rate
                    ),
                    updated_at=NOW()
                WHERE company_id=%s
                AND id=%s
                RETURNING *
            """, (
                item["revised_cashflow_pv"],
                item.get("revised_contractual_rate"),
                int(company_id),
                int(item["instrument_id"]),
            ))

            instrument = cur.fetchone()

        return {
            "modification": posted,
            "instrument": instrument,
            "journal_id": journal_id,
            "preview": preview,
        }
        
