    # Forecast / Budget helpers
    # ============================================================

    def _forecast_audit(
        self,
        company_id: int,
        *,
        entity_type: str,
        entity_id: Optional[int],
        action: str,
        actor_user_id: Optional[int] = None,
        before_json: Optional[dict] = None,
        after_json: Optional[dict] = None,
        message: Optional[str] = None,
    ):
        schema = self.company_schema(company_id)

        self.execute_sql(f"""
            INSERT INTO {schema}.forecast_audit_events (
                company_id, entity_type, entity_id, action,
                actor_user_id, before_json, after_json, message
            )
            VALUES (%s,%s,%s,%s,%s,%s::jsonb,%s::jsonb,%s);
        """, (
            int(company_id),
            entity_type,
            entity_id,
            action,
            actor_user_id,
            json.dumps(before_json or {}),
            json.dumps(after_json or {}),
            message,
        ))


    def forecast_validate_account(self, company_id: int, account_code: str) -> Dict[str, Any]:
        schema = self.company_schema(company_id)

        row = self.fetch_one(f"""
            SELECT code, name, section, category, posting
            FROM {schema}.coa
            WHERE company_id=%s
            AND code=%s
            AND posting=TRUE
            LIMIT 1;
        """, (int(company_id), account_code))

        if not row:
            raise ValueError(f"Invalid posting account code: {account_code}")

        return row

    def forecast_projected_full_year(
        self,
        company_id: int,
        version_id: int,
    ) -> Dict[str, Any]:
        schema = self.company_schema(company_id)
        version = self.forecast_get_version_required(company_id, version_id)

        start_date = str(version["period_start"])[:10]
        end_date = str(version["period_end"])[:10]
        actuals_to_date = str(version.get("actuals_to_date") or start_date)[:10]

        rows = self.fetch_all(f"""
            WITH actual AS (
                SELECT
                    jl.account_code,
                    DATE_TRUNC('month', j.date)::date AS period_month,
                    SUM(
                        CASE
                            WHEN LOWER(COALESCE(c.section, '')) IN ('income', 'revenue')
                                THEN COALESCE(jl.credit, 0) - COALESCE(jl.debit, 0)
                            ELSE COALESCE(jl.debit, 0) - COALESCE(jl.credit, 0)
                        END
                    )::numeric(18,2) AS amount
                FROM {schema}.journals j
                JOIN {schema}.journal_lines jl
                ON jl.journal_id = j.id
                AND jl.company_id = j.company_id
                LEFT JOIN {schema}.coa c
                ON c.company_id = jl.company_id
                AND c.code = jl.account_code
                WHERE j.company_id = %s
                AND j.date >= %s::date
                AND j.date <= %s::date
                AND COALESCE(j.status, 'posted') = 'posted'
                GROUP BY jl.account_code, DATE_TRUNC('month', j.date)::date
            ),
            forecast AS (
                SELECT
                    account_code,
                    DATE_TRUNC('month', period_month)::date AS period_month,
                    SUM(amount)::numeric(18,2) AS amount
                FROM {schema}.forecast_lines
                WHERE company_id = %s
                AND version_id = %s
                AND period_month > DATE_TRUNC('month', %s::date)::date
                AND period_month <= %s::date
                GROUP BY account_code, DATE_TRUNC('month', period_month)::date
            ),
            combined AS (
                SELECT account_code, period_month, amount, 'actual' AS source
                FROM actual

                UNION ALL

                SELECT account_code, period_month, amount, 'forecast' AS source
                FROM forecast
            )
            SELECT
                x.account_code,
                c.name AS account_name,
                c.section,
                c.category,
                SUM(x.amount) FILTER (WHERE x.source = 'actual')::numeric(18,2)
                    AS actual_ytd,
                SUM(x.amount) FILTER (WHERE x.source = 'forecast')::numeric(18,2)
                    AS forecast_remaining,
                SUM(x.amount)::numeric(18,2) AS projected_full_year
            FROM combined x
            LEFT JOIN {schema}.coa c
            ON c.company_id = %s
            AND c.code = x.account_code
            GROUP BY x.account_code, c.name, c.section, c.category
            ORDER BY c.section, c.category, x.account_code;
        """, (
            int(company_id),
            start_date,
            actuals_to_date,
            int(company_id),
            int(version_id),
            actuals_to_date,
            end_date,
            int(company_id),
        ))

        return {
            "version": version,
            "period_start": start_date,
            "period_end": end_date,
            "actuals_to_date": actuals_to_date,
            "rows": rows,
        }
            
    def forecast_assert_editable(self, row: Dict[str, Any], label: str = "Record"):
        status = (row.get("status") or "").lower()
        if status in ("approved", "locked"):
            raise ValueError(f"Cannot edit {label.lower()} in status '{status}'.")


    def forecast_validate_capex_parent(
        self,
        company_id: int,
        *,
        version_id: Optional[int] = None,
        budget_id: Optional[int] = None,
    ):
        if not version_id and not budget_id:
            raise ValueError(
                "version_id or budget_id is required."
            )

        if version_id:
            self.forecast_get_version_required(
                company_id,
                int(version_id),
            )

        if budget_id:
            self.forecast_get_budget_required(
                company_id,
                int(budget_id),
            )

    def forecast_list_capex_items(
        self,
        company_id: int,
        *,
        version_id: Optional[int] = None,
        budget_id: Optional[int] = None,
    ) -> List[Dict[str, Any]]:
        schema = self.company_schema(company_id)

        params = [int(company_id)]
        where = [
            "c.company_id = %s"
        ]

        if version_id:
            where.append(
                "c.version_id = %s"
            )
            params.append(int(version_id))

        if budget_id:
            where.append(
                "c.budget_id = %s"
            )
            params.append(int(budget_id))

        return self.fetch_all(f"""
            SELECT
                c.*,

                CASE
                    WHEN c.funding_source = 'loan'
                        THEN c.total_cost

                    WHEN c.funding_source = 'mixed'
                        THEN ROUND(
                            c.total_cost *
                            (c.loan_percentage / 100.0),
                            2
                        )

                    ELSE 0
                END AS estimated_loan_funding,

                CASE
                    WHEN c.funding_source = 'loan'
                        THEN 0

                    WHEN c.funding_source = 'mixed'
                        THEN ROUND(
                            c.total_cost *
                            (
                                1 -
                                c.loan_percentage / 100.0
                            ),
                            2
                        )

                    ELSE c.total_cost
                END AS estimated_cash_outflow

            FROM {schema}.forecast_capex_items c

            WHERE {' AND '.join(where)}

            ORDER BY
                c.purchase_month,
                c.asset_name,
                c.id;
        """, tuple(params))

    def forecast_create_capex_item(
        self,
        company_id: int,
        payload: Dict[str, Any],
        user_id: Optional[int] = None,
    ) -> Dict[str, Any]:
        schema = self.company_schema(company_id)

        version_id = payload.get(
            "version_id"
        )
        budget_id = payload.get(
            "budget_id"
        )

        self.forecast_validate_capex_parent(
            company_id,
            version_id=version_id,
            budget_id=budget_id,
        )

        asset_name = str(
            payload.get("asset_name") or ""
        ).strip()

        if not asset_name:
            raise ValueError(
                "asset_name is required."
            )

        purchase_month = payload.get(
            "purchase_month"
        )

        if not purchase_month:
            raise ValueError(
                "purchase_month is required."
            )

        quantity = Decimal(
            str(payload.get("quantity") or 1)
        )

        unit_cost = Decimal(
            str(payload.get("unit_cost") or 0)
        )

        total_cost = payload.get(
            "total_cost"
        )

        if total_cost is None:
            total_cost = (
                quantity * unit_cost
            )
        else:
            total_cost = Decimal(
                str(total_cost)
            )

        useful_life_months = payload.get(
            "useful_life_months"
        )

        if useful_life_months is not None:
            useful_life_months = int(
                useful_life_months
            )

        residual_value = Decimal(
            str(
                payload.get(
                    "residual_value"
                ) or 0
            )
        )

        funding_source = str(
            payload.get(
                "funding_source"
            ) or "cash"
        ).strip().lower()

        loan_percentage = Decimal(
            str(
                payload.get(
                    "loan_percentage"
                ) or 0
            )
        )

        row = self.fetch_one(f"""
            INSERT INTO
                {schema}.forecast_capex_items
            (
                company_id,
                version_id,
                budget_id,

                asset_name,
                asset_class,
                account_code,

                purchase_month,
                quantity,
                unit_cost,
                total_cost,

                useful_life_months,
                residual_value,
                depreciation_method,

                funding_source,
                loan_percentage,

                notes,
                meta_json
            )
            VALUES (
                %s,%s,%s,
                %s,%s,%s,
                %s,%s,%s,%s,
                %s,%s,%s,
                %s,%s,
                %s,%s::jsonb
            )
            RETURNING *;
        """, (
            int(company_id),
            version_id,
            budget_id,

            asset_name,
            payload.get("asset_class"),
            payload.get("account_code"),

            purchase_month,
            quantity,
            unit_cost,
            total_cost,

            useful_life_months,
            residual_value,
            payload.get(
                "depreciation_method"
            ) or "straight_line",

            funding_source,
            loan_percentage,

            payload.get("notes"),
            json.dumps(
                payload.get("meta_json") or {}
            ),
        ))

        self._forecast_audit(
            company_id,
            entity_type="forecast_capex_item",
            entity_id=row["id"],
            action="create_capex_item",
            actor_user_id=user_id,
            after_json=row,
            message=(
                f"Created forecast capex item "
                f"{row['id']}"
            ),
        )

        return row

    def forecast_update_capex_item(
        self,
        company_id: int,
        capex_id: int,
        payload: Dict[str, Any],
        user_id: Optional[int] = None,
    ) -> Dict[str, Any]:
        schema = self.company_schema(company_id)

        before = self.fetch_one(f"""
            SELECT *
            FROM {schema}.forecast_capex_items
            WHERE company_id = %s
            AND id = %s
            LIMIT 1;
        """, (
            int(company_id),
            int(capex_id),
        ))

        if not before:
            raise ValueError(
                "Capital expenditure item not found."
            )

        quantity = Decimal(
            str(
                payload.get(
                    "quantity",
                    before["quantity"],
                )
            )
        )

        unit_cost = Decimal(
            str(
                payload.get(
                    "unit_cost",
                    before["unit_cost"],
                )
            )
        )

        total_cost = payload.get(
            "total_cost"
        )

        if total_cost is None:
            total_cost = quantity * unit_cost

        row = self.fetch_one(f"""
            UPDATE
                {schema}.forecast_capex_items

            SET
                asset_name = COALESCE(
                    %s,
                    asset_name
                ),

                asset_class = COALESCE(
                    %s,
                    asset_class
                ),

                account_code = COALESCE(
                    %s,
                    account_code
                ),

                purchase_month = COALESCE(
                    %s,
                    purchase_month
                ),

                quantity = %s,
                unit_cost = %s,
                total_cost = %s,

                useful_life_months =
                    COALESCE(
                        %s,
                        useful_life_months
                    ),

                residual_value =
                    COALESCE(
                        %s,
                        residual_value
                    ),

                depreciation_method =
                    COALESCE(
                        %s,
                        depreciation_method
                    ),

                funding_source =
                    COALESCE(
                        %s,
                        funding_source
                    ),

                loan_percentage =
                    COALESCE(
                        %s,
                        loan_percentage
                    ),

                notes = COALESCE(
                    %s,
                    notes
                ),

                meta_json = COALESCE(
                    %s::jsonb,
                    meta_json
                ),

                updated_at = now()

            WHERE company_id = %s
            AND id = %s

            RETURNING *;
        """, (
            payload.get("asset_name"),
            payload.get("asset_class"),
            payload.get("account_code"),
            payload.get("purchase_month"),

            quantity,
            unit_cost,
            total_cost,

            payload.get(
                "useful_life_months"
            ),

            payload.get(
                "residual_value"
            ),

            payload.get(
                "depreciation_method"
            ),

            payload.get(
                "funding_source"
            ),

            payload.get(
                "loan_percentage"
            ),

            payload.get("notes"),

            (
                json.dumps(
                    payload.get("meta_json")
                )
                if payload.get(
                    "meta_json"
                ) is not None
                else None
            ),

            int(company_id),
            int(capex_id),
        ))

        self._forecast_audit(
            company_id,
            entity_type="forecast_capex_item",
            entity_id=capex_id,
            action="update_capex_item",
            actor_user_id=user_id,
            before_json=before,
            after_json=row,
            message=(
                f"Updated forecast capex item "
                f"{capex_id}"
            ),
        )

        return row

