    def payroll_employees_list(self, company_id: int, status=None):
        schema = self.company_schema(company_id)

        params = [int(company_id)]
        where = "WHERE e.company_id=%s"

        if status:
            where += " AND e.employment_status=%s"
            params.append(status)

        return self.fetch_all(f"""
            SELECT
                e.*,
                d.name AS department_name,
                p.title AS position_title,
                contract.employment_start_date
            FROM {schema}.payroll_employees e
            LEFT JOIN {schema}.payroll_departments d
            ON d.id=e.department_id
            LEFT JOIN {schema}.payroll_positions p
            ON p.id=e.position_id
            LEFT JOIN LATERAL(
                SELECT MIN(c.effective_from)::date
                    AS employment_start_date
                FROM {schema}.payroll_employee_contracts c
                WHERE c.company_id=e.company_id
                AND c.employee_id=e.id
            ) contract ON TRUE
            {where}
            ORDER BY e.last_name,e.first_name,e.id;
        """,tuple(params))


    def payroll_employee_get(self, company_id: int, employee_id: int):
        schema = self.company_schema(company_id)

        emp = self.fetch_one(f"""
            SELECT *
            FROM {schema}.payroll_employees
            WHERE company_id=%s AND id=%s
            LIMIT 1;
        """, (int(company_id), int(employee_id)))

        if not emp:
            return None

        emp["contracts"] = self.fetch_all(f"""
            SELECT *
            FROM {schema}.payroll_employee_contracts
            WHERE company_id=%s AND employee_id=%s
            ORDER BY effective_from DESC, id DESC;
        """, (int(company_id), int(employee_id)))

        emp["tax_profiles"] = self.fetch_all(f"""
            SELECT *
            FROM {schema}.payroll_employee_tax_profiles
            WHERE company_id=%s AND employee_id=%s
            ORDER BY effective_from DESC, id DESC;
        """, (int(company_id), int(employee_id)))

        emp["bank_accounts"] = self.fetch_all(f"""
            SELECT *
            FROM {schema}.payroll_employee_bank_accounts
            WHERE company_id=%s AND employee_id=%s
            ORDER BY is_primary DESC, id DESC;
        """, (int(company_id), int(employee_id)))

        emp["benefits"] = self.payroll_employee_benefits_list(company_id, employee_id)
        emp["leave_requests"] = self.payroll_employee_leave_list(company_id, employee_id)
        emp["loans"] = self.payroll_employee_loans_list(company_id, employee_id)

        return emp


