    def payroll_run_create(
        self,
        company_id: int,
        pay_calendar_id: int,
    ) -> dict:
        company_id = int(company_id)
        pay_calendar_id = int(pay_calendar_id)

        schema = self.company_schema(company_id)

        existing = self.fetch_one(f"""
            SELECT *
            FROM {schema}.payroll_runs
            WHERE company_id=%s
            AND pay_calendar_id=%s
            LIMIT 1;
        """, (
            company_id,
            pay_calendar_id,
        ))

        if existing:
            existing["already_existed"] = True
            return existing

        cal = self.fetch_one(f"""
            SELECT *
            FROM {schema}.payroll_pay_calendars
            WHERE company_id=%s
            AND id=%s
            LIMIT 1;
        """, (
            company_id,
            pay_calendar_id,
        ))

        if not cal:
            raise ValueError("Pay calendar not found")

        return self.fetch_one(f"""
            INSERT INTO {schema}.payroll_runs (
                company_id,
                pay_calendar_id,
                run_no,
                period_start,
                period_end,
                payment_date,
                status
            )
            VALUES (
                %s,%s,
                'PAY-' || %s || '-'
                    || to_char(%s::date, 'YYYYMM'),
                %s,%s,%s,'draft'
            )
            RETURNING *;
        """, (
            company_id,
            pay_calendar_id,
            company_id,
            cal["period_end"],
            cal["period_start"],
            cal["period_end"],
            cal["payment_date"],
        ))

    def payroll_defined_contribution_lines(
        self,company_id:int,employee_id:int,period_start,period_end,
        pensionable_pay
    )->tuple[list,list]:
        from decimal import Decimal

        schema=self.company_schema(company_id)
        base=_payroll_money(pensionable_pay)

        rows=self.fetch_all(f"""
            SELECT m.id AS member_id,m.plan_id,
                   p.code,p.name,
                   COALESCE(m.employee_percentage,
                            p.employee_contribution_percentage,0)
                       AS employee_percentage,
                   COALESCE(m.employer_percentage,
                            p.employer_contribution_percentage,0)
                       AS employer_percentage,
                   COALESCE(m.pensionable_percentage,100)
                       AS pensionable_percentage,
                   p.expense_account_code,
                   p.payable_account_code
            FROM {schema}.payroll_benefit_plan_members m
            JOIN {schema}.payroll_benefit_plans p
              ON p.id=m.plan_id AND p.company_id=m.company_id
            WHERE m.company_id=%s
              AND m.employee_id=%s
              AND m.is_active=TRUE
              AND p.is_active=TRUE
              AND p.plan_type='defined_contribution'
              AND m.effective_from<=%s
              AND(m.effective_to IS NULL OR m.effective_to>=%s)
              AND(p.effective_from IS NULL OR p.effective_from<=%s)
              AND(p.effective_to IS NULL OR p.effective_to>=%s)
            ORDER BY p.code;
        """,(
            int(company_id),int(employee_id),
            period_end,period_start,period_end,period_start,
        ))

        deductions,contributions=[],[]

        for x in rows:
            if not x.get("payable_account_code"):
                raise ValueError(
                    f"Defined-contribution plan {x['code']} "
                    "has no payable account"
                )

            pensionable=_payroll_money(
                base*
                _payroll_decimal(x.get("pensionable_percentage"))/
                Decimal("100")
            )

            employee_amount=_payroll_money(
                pensionable*
                _payroll_decimal(x.get("employee_percentage"))/
                Decimal("100")
            )

            employer_amount=_payroll_money(
                pensionable*
                _payroll_decimal(x.get("employer_percentage"))/
                Decimal("100")
            )

            metadata={
                "plan_id":int(x["plan_id"]),
                "member_id":int(x["member_id"]),
                "plan_code":x["code"],
                "pensionable_pay":str(pensionable),
                "employee_percentage":str(x["employee_percentage"]),
                "employer_percentage":str(x["employer_percentage"]),
            }

            if employee_amount>0:
                deductions.append({
                    "item_type":"benefit_plan",
                    "item_id":int(x["plan_id"]),
                    "code":f"DC-EMP-{x['code']}",
                    "name":f"{x['name']} employee contribution",
                    "amount":employee_amount,
                    "percentage":x["employee_percentage"],
                    "taxable":False,
                    "pensionable":False,
                    "source_type":"defined_contribution_plan",
                    "source_id":int(x["member_id"]),
                    "gl_account_code":x["payable_account_code"],
                    "offset_account_code":None,
                    "metadata":metadata,
                })

            if employer_amount>0:
                if not x.get("expense_account_code"):
                    raise ValueError(
                        f"Defined-contribution plan {x['code']} "
                        "has no expense account"
                    )

                contributions.append({
                    "item_type":"benefit_plan",
                    "item_id":int(x["plan_id"]),
                    "code":f"DC-ER-{x['code']}",
                    "name":f"{x['name']} employer contribution",
                    "amount":employer_amount,
                    "percentage":x["employer_percentage"],
                    "taxable":False,
                    "pensionable":False,
                    "source_type":"defined_contribution_plan",
                    "source_id":int(x["member_id"]),
                    "gl_account_code":x["payable_account_code"],
                    "offset_account_code":x["expense_account_code"],
                    "metadata":metadata,
                })

        return deductions,contributions
    
    def payroll_employee_period_facts(
        self,
        company_id:int,
        payroll_run_id:int,
        employee:dict,
        setup:dict,
        run:dict|None=None,
    )->dict:
        company_id=int(company_id)
        payroll_run_id=int(payroll_run_id)
        schema=self.company_schema(company_id)

        if not run:
            run=self.fetch_one(f"""
                SELECT period_start,period_end
                FROM {schema}.payroll_runs
                WHERE company_id=%s AND id=%s
                LIMIT 1;
            """,(company_id,payroll_run_id))

        if not run:
            raise ValueError("Payroll run not found")

        start=max(run["period_start"],employee["start_date"])
        end=min(
            run["period_end"],
            employee.get("termination_date") or run["period_end"],
        )

        zero=Decimal("0")

        if end<start:
            return{
                "eligible":False,
                "eligible_from":start,
                "eligible_to":end,
                "scheduled_days":zero,
                "eligible_days":zero,
                "worked_days":zero,
                "paid_leave_days":zero,
                "unpaid_days":zero,
                "scheduled_hours":zero,
                "worked_hours":zero,
                "unpaid_hours":zero,
                "proration_method":
                    setup.get("proration_method") or "working_days",
                "proration_factor":zero,
            }

        hours_per_day=_payroll_decimal(
            setup.get("hours_per_day") or 8
        )

        days=self.fetch_one(f"""
            WITH dates AS(
                SELECT d::date AS work_date
                FROM generate_series(
                    %s::date,
                    %s::date,
                    INTERVAL '1 day'
                ) d
            )
            SELECT
                COUNT(*)::NUMERIC AS calendar_days,

                COUNT(*) FILTER(
                    WHERE work_date BETWEEN %s AND %s
                )::NUMERIC AS eligible_calendar_days,

                COUNT(*) FILTER(
                    WHERE EXTRACT(ISODOW FROM work_date)<6
                    AND h.id IS NULL
                )::NUMERIC AS working_days,

                COUNT(*) FILTER(
                    WHERE work_date BETWEEN %s AND %s
                    AND EXTRACT(ISODOW FROM work_date)<6
                    AND h.id IS NULL
                )::NUMERIC AS eligible_working_days
            FROM dates
            LEFT JOIN {schema}.company_holidays h
            ON h.company_id=%s
            AND h.holiday_date=dates.work_date;
        """,(
            run["period_start"],
            run["period_end"],
            start,
            end,
            start,
            end,
            company_id,
        )) or {}

        attendance=self.fetch_one(f"""
            SELECT
                COUNT(*) FILTER(
                    WHERE approved=TRUE
                    AND attendance_type='present'
                )::NUMERIC AS worked_days,

                COUNT(*) FILTER(
                    WHERE approved=TRUE
                    AND attendance_type IN(
                        'paid_leave',
                        'sick_leave',
                        'public_holiday'
                    )
                )::NUMERIC AS paid_leave_days,

                COUNT(*) FILTER(
                    WHERE approved=TRUE
                    AND attendance_type IN(
                        'unpaid_leave',
                        'absent'
                    )
                )::NUMERIC AS unpaid_days,

                COALESCE(SUM(worked_hours)
                    FILTER(WHERE approved=TRUE),0
                ) AS worked_hours,

                COALESCE(SUM(unpaid_hours)
                    FILTER(WHERE approved=TRUE),0
                ) AS unpaid_hours
            FROM {schema}.payroll_attendance_inputs
            WHERE company_id=%s
            AND payroll_run_id=%s
            AND employee_id=%s
            AND attendance_date BETWEEN %s AND %s;
        """,(
            company_id,
            payroll_run_id,
            int(employee["id"]),
            start,
            end,
        )) or {}

        calendar_days=_payroll_decimal(
            days.get("calendar_days")
        )
        eligible_calendar=_payroll_decimal(
            days.get("eligible_calendar_days")
        )
        working_days=_payroll_decimal(
            days.get("working_days")
        )
        eligible_days=_payroll_decimal(
            days.get("eligible_working_days")
        )
        unpaid_days=_payroll_decimal(
            attendance.get("unpaid_days")
        )
        worked_days=_payroll_decimal(
            attendance.get("worked_days")
        )
        paid_leave_days=_payroll_decimal(
            attendance.get("paid_leave_days")
        )
        worked_hours=_payroll_decimal(
            attendance.get("worked_hours")
        )
        unpaid_hours=_payroll_decimal(
            attendance.get("unpaid_hours")
        )

        scheduled_hours=eligible_days*hours_per_day
        method=setup.get("proration_method") or "working_days"

        if method=="calendar_days":
            factor=(
                eligible_calendar/calendar_days
                if calendar_days else zero
            )

        elif method=="fixed_30_days":
            payable=max(eligible_calendar-unpaid_days,zero)
            factor=payable/Decimal("30")

        elif method=="scheduled_hours":
            full_hours=working_days*hours_per_day
            payable=max(scheduled_hours-unpaid_hours,zero)
            factor=payable/full_hours if full_hours else zero

        elif method=="actual_hours":
            full_hours=working_days*hours_per_day
            factor=worked_hours/full_hours if full_hours else zero

        elif method=="no_proration":
            factor=Decimal("1")

        else:
            payable=max(eligible_days-unpaid_days,zero)
            factor=payable/working_days if working_days else zero

        factor=max(zero,min(factor,Decimal("1")))

        return{
            "eligible":True,
            "eligible_from":start,
            "eligible_to":end,
            "calendar_days":calendar_days,
            "eligible_calendar_days":eligible_calendar,
            "scheduled_days":working_days,
            "eligible_days":eligible_days,
            "worked_days":worked_days,
            "paid_leave_days":paid_leave_days,
            "unpaid_days":unpaid_days,
            "scheduled_hours":scheduled_hours,
            "worked_hours":worked_hours,
            "unpaid_hours":unpaid_hours,
            "hours_per_day":hours_per_day,
            "proration_method":method,
            "proration_factor":factor,
        }


    def payroll_calculate_basic_pay(
        self,
        setup:dict,
        facts:dict,
    )->dict:
        basis=setup.get("pay_basis") or "monthly"
        factor=_payroll_decimal(
            facts.get("proration_factor")
        )
        full=_payroll_money(
            setup.get("fixed_basic_amount")
        )
        quantity=Decimal("0")
        rate=_payroll_decimal(setup.get("rate"))

        if basis=="monthly":
            amount=_payroll_money(full*factor)

        elif basis=="daily":
            quantity=max(
                _payroll_decimal(facts.get("eligible_days"))
                -_payroll_decimal(facts.get("unpaid_days")),
                Decimal("0"),
            )
            amount=_payroll_money(quantity*rate)

        elif basis=="hourly":
            worked=_payroll_decimal(
                facts.get("worked_hours")
            )
            scheduled=max(
                _payroll_decimal(facts.get("scheduled_hours"))
                -_payroll_decimal(facts.get("unpaid_hours")),
                Decimal("0"),
            )
            quantity=worked if worked>0 else scheduled
            amount=_payroll_money(quantity*rate)

        elif basis=="quantity":
            quantity=_payroll_decimal(
                setup.get("standard_quantity")
            )
            amount=_payroll_money(quantity*rate)

        else:
            amount=Decimal("0.00")

        return{
            "pay_basis":basis,
            "full_basic_amount":full,
            "quantity":quantity,
            "rate":rate,
            "proration_factor":factor,
            "prorated_basic_amount":amount,
        }

    def payroll_run_eligibility(
        self,
        company_id:int,
        payroll_run_id:int,
    )->dict:
        company_id=int(company_id)
        payroll_run_id=int(payroll_run_id)
        schema=self.company_schema(company_id)

        run=self.fetch_one(f"""
            SELECT r.*,c.frequency
            FROM {schema}.payroll_runs r
            JOIN {schema}.payroll_pay_calendars c
            ON c.id=r.pay_calendar_id
            AND c.company_id=r.company_id
            WHERE r.company_id=%s
            AND r.id=%s
            LIMIT 1;
        """,(company_id,payroll_run_id))

        if not run:
            raise ValueError("Payroll run not found")

        employees=self.fetch_all(f"""
            SELECT e.*
            FROM {schema}.payroll_employees e
            WHERE e.company_id=%s
            AND e.start_date<=%s
            AND(
                e.termination_date IS NULL
                OR e.termination_date>=%s
            )
            AND e.employment_status IN(
                'active',
                'terminated',
                'suspended'
            )
            ORDER BY e.employee_no;
        """,(
            company_id,
            run["period_end"],
            run["period_start"],
        ))

        items=[]
        errors=[]
        warnings=[]

        for employee in employees:
            employee_id=int(employee["id"])
            name=" ".join(filter(None,[
                employee.get("first_name"),
                employee.get("last_name"),
            ]))

            setup=self.payroll_employee_pay_setup_for_period(
                company_id,
                employee_id,
                run["period_end"],
            )

            if not setup:
                message=(
                    f"{employee['employee_no']} {name}: "
                    "no effective remuneration setup."
                )
                errors.append(message)
                items.append({
                    "employee_id":employee_id,
                    "employee_no":employee["employee_no"],
                    "employee_name":name,
                    "eligible":False,
                    "error":"No effective remuneration setup",
                })
                continue

            facts=self.payroll_employee_period_facts(
                company_id,
                payroll_run_id,
                employee,
                setup,
                run,
            )
            basic=self.payroll_calculate_basic_pay(
                setup,
                facts,
            )

            employee_warnings=[]

            if employee["start_date"]>run["period_start"]:
                employee_warnings.append(
                    "Employee starts during this payroll period."
                )

            termination=employee.get("termination_date")

            if termination and termination<run["period_end"]:
                employee_warnings.append(
                    "Employee terminates during this payroll period."
                )

            if (
                setup.get("attendance_required")
                and facts["eligible_days"]>0
                and(
                    facts["worked_days"]
                    +facts["paid_leave_days"]
                    +facts["unpaid_days"]
                )<=0
            ):
                employee_warnings.append(
                    "Attendance is required but has not been captured."
                )

            warnings.extend(
                f"{employee['employee_no']} {name}: {message}"
                for message in employee_warnings
            )

            items.append({
                "employee_id":employee_id,
                "employee_no":employee["employee_no"],
                "employee_name":name,
                "employment_status":
                    employee.get("employment_status"),
                "start_date":employee.get("start_date"),
                "termination_date":
                    employee.get("termination_date"),
                "pay_setup_id":setup["id"],
                "pay_basis":setup.get("pay_basis"),
                "attendance_required":bool(
                    setup.get("attendance_required")
                ),
                **facts,
                **basic,
                "warnings":employee_warnings,
            })

        return{
            "run":{
                "id":run["id"],
                "run_no":run.get("run_no"),
                "period_start":run["period_start"],
                "period_end":run["period_end"],
                "payment_date":run["payment_date"],
                "status":run["status"],
                "frequency":run["frequency"],
            },
            "items":items,
            "summary":{
                "candidate_count":len(employees),
                "eligible_count":sum(
                    1 for item in items
                    if item.get("eligible")
                ),
                "error_count":len(errors),
                "warning_count":len(warnings),
                "ready":not errors,
            },
            "errors":errors,
            "warnings":warnings,
        }

    def payroll_assert_run_editable(
        self,
        company_id:int,
        payroll_run_id:int,
    )->dict:
        schema=self.company_schema(company_id)

        run=self.fetch_one(f"""
            SELECT *
            FROM {schema}.payroll_runs
            WHERE company_id=%s AND id=%s
            LIMIT 1;
        """,(int(company_id),int(payroll_run_id)))

        if not run:
            raise ValueError("Payroll run not found")

        if(
            run.get("status") in(
                "approved",
                "posted",
                "reversed",
                "cancelled",
            )
            or run.get("submitted_at")
        ):
            state=(
                "submitted"
                if run.get("submitted_at")
                and run.get("status")=="calculated"
                else run.get("status")
            )

            raise ValueError(
                f"Payroll inputs cannot be changed while "
                f"the payroll run is {state}."
            )

        return run


