    def payroll_company_tax_context(
        self,
        company_id: int,
        payment_date=None,
    ):
        company_id = int(company_id)

        company = self.fetch_one("""
            SELECT
                c.id,
                c.country,
                c.currency,
                ps.payroll_start_date,
                ps.tax_authority_id
            FROM public.companies c
            LEFT JOIN company_{company_id}.payroll_settings ps
            ON ps.company_id = c.id
            WHERE c.id = %s
            LIMIT 1;
        """.format(
            company_id=company_id
        ), (
            company_id,
        )) or {}

        resolved_date = (
            payment_date
            or company.get("payroll_start_date")
            or date.today()
        )

        if isinstance(resolved_date, datetime):
            resolved_date = resolved_date.date()

        elif not isinstance(resolved_date, date):
            resolved_date = date.fromisoformat(
                str(resolved_date)[:10]
            )

        country = str(
            company.get("country") or ""
        ).strip().lower()

        country_code_map = {
            "south africa": "ZA",
            "rsa": "ZA",
            "za": "ZA",

            "lesotho": "LS",
            "ls": "LS",

            "botswana": "BW",
            "bw": "BW",
        }

        country_code = country_code_map.get(country)

        if not country_code:
            raise ValueError(
                f"Unsupported payroll country: "
                f"{company.get('country') or 'not configured'}"
            )

        if payment_date in (None, "", "None"):
            payment_date = date.today()

        elif isinstance(payment_date, datetime):
            payment_date = payment_date.date()

        elif not isinstance(payment_date, date):
            payment_date = date.fromisoformat(
                str(payment_date)[:10]
            )

        row = self.fetch_one("""
            SELECT
                r.authority_code,
                r.country_code,
                r.currency,
                y.id AS tax_year_id,
                y.tax_year_label,
                y.calculation_basis,
                y.effective_from,
                y.effective_to
            FROM public.payroll_tax_regimes r
            JOIN public.payroll_tax_years y
            ON y.regime_id = r.id
            AND y.is_active = TRUE
            LEFT JOIN public.tax_authorities ta
            ON UPPER(ta.code) = UPPER(r.authority_code)
            WHERE r.is_active = TRUE
            AND (
                ta.id = %s
                OR %s IS NULL
            )
            AND %s BETWEEN y.effective_from
                        AND y.effective_to
            ORDER BY y.effective_from DESC
            LIMIT 1;
        """, (
            company.get("tax_authority_id"),
            company.get("tax_authority_id"),
            resolved_date,
        ))

        if not row:
            raise ValueError(
                f"No active payroll tax table exists for "
                f"{country_code} on {payment_date}"
            )

        return row

    def payroll_tax_brackets(
        self,
        tax_year_id: int,
        residency_status: str = "resident",
    ):
        return self.fetch_all("""
            SELECT *
            FROM public.payroll_tax_brackets
            WHERE tax_year_id=%s
            AND residency_status=%s
            ORDER BY sort_order;
        """, (
            int(tax_year_id),
            residency_status,
        ))


    def payroll_tax_parameters(
        self,
        tax_year_id: int,
    ):
        rows = self.fetch_all("""
            SELECT
                parameter_key,
                numeric_value,
                text_value,
                json_value
            FROM public.payroll_tax_parameters
            WHERE tax_year_id=%s;
        """, (int(tax_year_id),))

        return {
            row["parameter_key"]:
                row.get("numeric_value")
                if row.get("numeric_value") is not None
                else row.get("text_value")
                if row.get("text_value") is not None
                else row.get("json_value")
            for row in rows
        }


    def payroll_progressive_tax(
        self,
        taxable_amount,
        brackets,
    ):
        taxable_amount = _payroll_decimal(taxable_amount)

        selected = None

        for bracket in brackets:
            lower = _payroll_decimal(
                bracket.get("lower_bound")
            )

            upper = bracket.get("upper_bound")

            if taxable_amount >= lower and (
                upper is None
                or taxable_amount
                <= _payroll_decimal(upper)
            ):
                selected = bracket
                break

        if not selected:
            return Decimal("0.00")

        base_tax = _payroll_decimal(
            selected.get("base_tax")
        )

        excess_over = _payroll_decimal(
            selected.get("excess_over")
        )

        rate = _payroll_decimal(
            selected.get("marginal_rate")
        )

        return _payroll_money(
            base_tax
            + max(
                Decimal("0"),
                taxable_amount - excess_over,
            ) * rate
        )

    def payroll_calculate_paye(
        self,
        *,
        tax_context: dict,
        taxable_income,
        frequency: str,
        tax_profile: dict,
    ):
        authority = tax_context["authority_code"]

        if tax_profile.get("paye_exempt"):
            return {
                "paye": Decimal("0.00"),
                "annualised_taxable_income": Decimal("0.00"),
                "authority_code": authority,
                "tax_year_label":
                    tax_context["tax_year_label"],
                "method": "exempt",
            }

        if authority == "SARS":
            return self.payroll_calculate_sars_paye(
                tax_context=tax_context,
                taxable_income=taxable_income,
                frequency=frequency,
                tax_profile=tax_profile,
            )

        if authority == "RSL":
            return self.payroll_calculate_rsl_paye(
                tax_context=tax_context,
                taxable_income=taxable_income,
                frequency=frequency,
                tax_profile=tax_profile,
            )

        if authority == "BURS":
            return self.payroll_calculate_burs_paye(
                tax_context=tax_context,
                taxable_income=taxable_income,
                frequency=frequency,
                tax_profile=tax_profile,
            )

        raise ValueError(
            f"No PAYE calculator exists for {authority}"
        )

    def payroll_calculate_sars_paye(
        self,
        *,
        tax_context,
        taxable_income,
        frequency,
        tax_profile,
    ):
        factors = {
            "monthly": Decimal("12"),
            "fortnightly": Decimal("26"),
            "weekly": Decimal("52"),
        }

        factor = factors.get(frequency)

        if not factor:
            raise ValueError(
                f"Unsupported SARS payroll frequency: {frequency}"
            )

        taxable_period = _payroll_decimal(taxable_income)
        annual_taxable = taxable_period * factor

        brackets = self.payroll_tax_brackets(
            tax_context["tax_year_id"],
            tax_profile.get("residency_status")
            or "resident",
        )

        parameters = self.payroll_tax_parameters(
            tax_context["tax_year_id"]
        )

        annual_tax = self.payroll_progressive_tax(
            annual_taxable,
            brackets,
        )

        dob = tax_profile.get("date_of_birth")
        age = 0

        if dob:
            dob = (
                date.fromisoformat(str(dob)[:10])
                if not isinstance(dob, date)
                else dob
            )

            year_end = tax_context["effective_to"]

            if not isinstance(year_end, date):
                year_end = date.fromisoformat(
                    str(year_end)[:10]
                )

            age = (
                year_end.year
                - dob.year
                - (
                    (year_end.month, year_end.day)
                    < (dob.month, dob.day)
                )
            )

        rebate = _payroll_decimal(
            parameters.get("primary_rebate")
        )

        if age >= 65:
            rebate += _payroll_decimal(
                parameters.get("secondary_rebate")
            )

        if age >= 75:
            rebate += _payroll_decimal(
                parameters.get("tertiary_rebate")
            )

        annual_tax = max(
            Decimal("0"),
            annual_tax - rebate,
        )

        members = int(
            tax_profile.get("medical_scheme_members")
            or 0
        )

        monthly_medical_credit = Decimal("0")

        if members >= 1:
            monthly_medical_credit += _payroll_decimal(
                parameters.get(
                    "medical_credit_taxpayer"
                )
            )

        if members >= 2:
            monthly_medical_credit += _payroll_decimal(
                parameters.get(
                    "medical_credit_first_dependant"
                )
            )

        if members > 2:
            monthly_medical_credit += (
                _payroll_decimal(
                    parameters.get(
                        "medical_credit_additional_dependant"
                    )
                )
                * Decimal(members - 2)
            )

        annual_tax = max(
            Decimal("0"),
            annual_tax
            - monthly_medical_credit * Decimal("12"),
        )

        paye = _payroll_money(
            annual_tax / factor
        )

        paye += _payroll_money(
            tax_profile.get("additional_tax_amount")
            or 0
        )

        return {
            "paye": paye,
            "annualised_taxable_income":
                _payroll_money(annual_taxable),
            "authority_code": "SARS",
            "tax_year_label":
                tax_context["tax_year_label"],
            "method": "annualised",
        }

    def payroll_calculate_rsl_paye(
        self,
        *,
        tax_context,
        taxable_income,
        frequency,
        tax_profile,
    ):
        if frequency != "monthly":
            raise ValueError(
                "RSL automatic PAYE currently supports "
                "monthly payroll only"
            )

        taxable = _payroll_decimal(taxable_income)

        brackets = self.payroll_tax_brackets(
            tax_context["tax_year_id"],
            tax_profile.get("residency_status")
            or "resident",
        )

        parameters = self.payroll_tax_parameters(
            tax_context["tax_year_id"]
        )

        tax_before_credit = self.payroll_progressive_tax(
            taxable,
            brackets,
        )

        credit = Decimal("0")

        if (
            tax_profile.get("residency_status")
            or "resident"
        ) == "resident":
            credit = _payroll_decimal(
                parameters.get("monthly_tax_credit")
            )

        paye = max(
            Decimal("0"),
            tax_before_credit - credit,
        )

        paye += _payroll_decimal(
            tax_profile.get("additional_tax_amount")
            or 0
        )

        return {
            "paye": _payroll_money(paye),
            "annualised_taxable_income":
                _payroll_money(taxable * 12),
            "authority_code": "RSL",
            "tax_year_label":
                tax_context["tax_year_label"],
            "method": "monthly_table",
        }

    def payroll_calculate_burs_paye(
        self,
        *,
        tax_context,
        taxable_income,
        frequency,
        tax_profile,
    ):
        brackets = self.payroll_tax_brackets(
            tax_context["tax_year_id"],
            tax_profile.get("residency_status")
            or "resident",
        )

        if not brackets:
            raise ValueError(
                "The applicable Botswana BURS PAYE table "
                "has not yet been verified and activated."
            )

        raise NotImplementedError(
            "BURS PAYE calculation is not yet activated."
        )

    def payroll_employee_pay_setup_for_period(
        self,
        company_id: int,
        employee_id: int,
        period_end,
    ):
        company_id = int(company_id)
        employee_id = int(employee_id)

        schema = self.company_schema(company_id)

        setup = self.fetch_one(f"""
            SELECT *
            FROM {schema}.payroll_employee_pay_setups
            WHERE company_id=%s
            AND employee_id=%s
            AND is_active=TRUE
            AND effective_from <= %s
            AND (
                effective_to IS NULL
                OR effective_to >= %s
            )
            ORDER BY effective_from DESC, id DESC
            LIMIT 1;
        """, (
            company_id,
            employee_id,
            period_end,
            period_end,
        ))

        if not setup:
            return None

        setup["items"] = self.fetch_all(f"""
            SELECT
                i.*,

                COALESCE(
                    et.code,
                    dt.code,
                    bt.code,
                    ct.code
                ) AS code,

                COALESCE(
                    et.name,
                    dt.name,
                    bt.name,
                    ct.name
                ) AS name,

                COALESCE(et.taxable, bt.taxable, FALSE)
                    AS taxable,

                COALESCE(et.pensionable, FALSE)
                    AS pensionable

            FROM {schema}.payroll_employee_pay_setup_items i

            LEFT JOIN {schema}.payroll_earning_types et
            ON i.item_type='earning'
            AND et.id=i.item_id

            LEFT JOIN {schema}.payroll_deduction_types dt
            ON i.item_type='deduction'
            AND dt.id=i.item_id

            LEFT JOIN {schema}.payroll_benefit_types bt
            ON i.item_type='benefit'
            AND bt.id=i.item_id

            LEFT JOIN
                {schema}.payroll_employer_contribution_types ct
            ON i.item_type='contribution'
            AND ct.id=i.item_id

            WHERE i.company_id=%s
            AND i.pay_setup_id=%s
            AND i.is_active=TRUE

            ORDER BY i.item_type, i.id;
        """, (
            company_id,
            int(setup["id"]),
        ))

        return setup

    def payroll_setup_item_amount(
        self,
        item: dict,
        gross_base,
    ):
        method = (
            item.get("calculation_method")
            or "fixed_amount"
        )

        if method == "fixed_amount":
            return _payroll_money(
                item.get("amount")
            )

        if method == "percentage":
            return _payroll_money(
                _payroll_decimal(gross_base)
                * _payroll_decimal(
                    item.get("percentage")
                )
                / Decimal("100")
            )

        if method == "quantity_rate":
            return _payroll_money(
                _payroll_decimal(item.get("quantity"))
                * _payroll_decimal(item.get("rate"))
            )

        if method == "manual":
            return Decimal("0.00")

        raise ValueError(
            f"Unsupported calculation method: {method}"
        ) 

    def _payroll_adjust_to_workday(
        self,
        d,
        direction="forward",
    ):
        """
        If *d* falls on a Saturday or Sunday, return the
        nearest weekday.  direction controls which way:
          "forward"  → next Monday   (default)
          "backward" → previous Friday
          "nearest"  → closest weekday
        Does NOT check holidays (use _payroll_next_workday
        for that).
        """
        if d.weekday() < 5:          # Mon-Fri
            return d

        if direction == "backward":
            # Sat → Fri, Sun → Fri
            return d - timedelta(days=(d.weekday() - 4))

        if direction == "nearest":
            # Sat → Fri (1 day back), Sun → Mon (1 day fwd)
            if d.weekday() == 5:     # Saturday
                return d - timedelta(days=1)
            return d + timedelta(days=1)   # Sunday

        # "forward" (default)
        return d + timedelta(days=(7 - d.weekday()))


    # ─── HELPER 2: Adjust for holidays too ───
    # Add this inside your PayrollMethods class.

    def _payroll_next_workday(
        self,
        d,
        schema,
        company_id,
        direction="forward",
    ):
        """
        Like _payroll_adjust_to_workday but also skips
        dates in the company_holidays table.
        """
        candidate = self._payroll_adjust_to_workday(d, direction)
        max_loops = 15  # safety limit
        for _ in range(max_loops):
            if candidate.weekday() >= 5:
                candidate = self._payroll_adjust_to_workday(
                    candidate, direction
                )
                continue
            row = self.fetch_one(f"""
                SELECT 1 FROM {schema}.company_holidays
                WHERE company_id = %s
                  AND holiday_date = %s
                LIMIT 1;
            """, (int(company_id), candidate))
            if not row:
                return candidate
            # It's a holiday — move to next/prev day
            if direction == "backward":
                candidate -= timedelta(days=1)
            else:
                candidate += timedelta(days=1)
        return candidate


    # ─── MAIN FIX: Replace payroll_calendars_generate() ───
    # REPLACE the existing method entirely.

    def payroll_calendars_generate(
        self,
        company_id: int,
        periods: int = None,
        from_month=None,
    ):
        import calendar as cal_mod
        from datetime import date, timedelta

        company_id = int(company_id)
        schema = self.company_schema(company_id)

        settings = self.payroll_settings_get(company_id) or {}

        frequency = (
            settings.get("default_frequency") or "monthly"
        )

        if frequency != "monthly":
            raise ValueError(
                "Automatic calendar generation currently "
                "supports monthly payroll only"
            )

        start_day = settings.get("period_start_day")
        end_day = settings.get("period_end_day")
        end_offset = int(
            settings.get("period_end_month_offset") or 0
        )

        payment_rule = settings.get("payment_day_rule")
        payment_offset = int(
            settings.get("payment_month_offset") or 0
        )

        adjustment = (
            settings.get("payment_adjustment") or "none"
        )

        if not start_day or not end_day or not payment_rule:
            raise ValueError(
                "Complete the payroll schedule in Settings "
                "first"
            )

        # ── FIX 1: Auto-correct impossible offset ──
        if int(end_day) < int(start_day) and end_offset == 0:
            end_offset = 1

        periods = int(
            periods
            or settings.get("calendar_generation_months")
            or 12
        )

        if periods < 1 or periods > 60:
            raise ValueError(
                "periods must be between 1 and 60"
            )

        # Determine the anchor month
        if from_month:
            if isinstance(from_month, str):
                raw = from_month[:10]
                anchor = date.fromisoformat(raw)
            else:
                anchor = from_month
        elif settings.get("payroll_start_date"):
            value = settings["payroll_start_date"]
            if isinstance(value, str):
                anchor = date.fromisoformat(value[:10])
            else:
                anchor = value
        else:
            today = date.today()
            anchor = date(today.year, today.month, 1)

        anchor = date(anchor.year, anchor.month, 1)

        # Check if holiday-aware adjustment is requested
        holiday_aware = (
            adjustment == "next_workday"
            or adjustment == "previous_workday"
            or adjustment == "nearest_workday"
        )

        # Determine adjustment direction for holidays
        h_direction = "forward"
        if adjustment == "previous_workday":
            h_direction = "backward"
        elif adjustment == "nearest_workday":
            h_direction = "nearest"

        generated = []

        for index in range(periods):
            start_month = self._payroll_add_months(
                anchor, index,
            )

            raw_start = self._payroll_safe_month_day(
                start_month.year,
                start_month.month,
                int(start_day),
            )

            end_month = self._payroll_add_months(
                start_month, end_offset,
            )

            raw_end = self._payroll_safe_month_day(
                end_month.year,
                end_month.month,
                int(end_day),
            )

            if raw_end < raw_start:
                raise ValueError(
                    "Generated period end cannot be before "
                    "period start"
                )

            # ── FIX 2 & 3: Weekend + holiday adjustment ──
            # Adjust period start
            if holiday_aware:
                period_start = self._payroll_next_workday(
                    raw_start, schema, company_id, h_direction
                )
            else:
                period_start = raw_start

            # Adjust period end
            if holiday_aware:
                period_end = self._payroll_next_workday(
                    raw_end, schema, company_id, "backward"
                )
            else:
                period_end = raw_end

            # Payment date
            payment_month = self._payroll_add_months(
                date(period_end.year, period_end.month, 1),
                payment_offset,
            )

            payment_date = self._payroll_payment_date(
                payment_month, payment_rule,
            )

            # Adjust payment date for weekends
            if adjustment in (
                "next_workday", "nearest_workday"
            ) or adjustment == "none":
                # Default: move weekend pay dates forward
                # to Monday
                if payment_date.weekday() >= 5:
                    payment_date = (
                        self._payroll_adjust_to_workday(
                            payment_date, "forward"
                        )
                    )

            if holiday_aware:
                payment_date = self._payroll_next_workday(
                    payment_date, schema, company_id,
                    h_direction
                )

            # Build adjustment notes for the frontend
            notes = []
            if period_start != raw_start:
                notes.append(
                    f"start adjusted from "
                    f"{raw_start.strftime('%d %b')} to "
                    f"{period_start.strftime('%d %b')}"
                )
            if period_end != raw_end:
                notes.append(
                    f"end adjusted from "
                    f"{raw_end.strftime('%d %b')} to "
                    f"{period_end.strftime('%d %b')}"
                )

            row = self.fetch_one(f"""
                INSERT INTO {schema}.payroll_pay_calendars (
                    company_id,
                    frequency,
                    period_start,
                    period_end,
                    payment_date,
                    status
                )
                VALUES (%s,%s,%s,%s,%s,'open')
                ON CONFLICT (
                    company_id,
                    period_start,
                    period_end
                )
                DO UPDATE SET
                    frequency = EXCLUDED.frequency,
                    payment_date = EXCLUDED.payment_date
                RETURNING *;
            """, (
                company_id,
                frequency,
                period_start,
                period_end,
                payment_date,
            ))

            if row and notes:
                row = dict(row)
                row["_adjustment_notes"] = "; ".join(notes)

            generated.append(row)

        return generated

    def payroll_statutory_mappings_list(
        self,
        company_id:int,
        authority_code=None,
        return_type=None,
    )->list[dict]:
        schema=self.company_schema(company_id)
        params=[int(company_id)]
        where=["company_id=%s"]

        if authority_code:
            where.append("authority_code=%s")
            params.append(str(authority_code).strip())

        if return_type:
            where.append("return_type=%s")
            params.append(str(return_type).strip())

        return self.fetch_all(f"""
            SELECT *
            FROM {schema}.payroll_statutory_item_mappings
            WHERE {" AND ".join(where)}
            ORDER BY
                authority_code,
                return_type,
                display_order,
                id;
        """,tuple(params))


    def payroll_statutory_mapping_save(
        self,
        company_id:int,
        body:dict,
        mapping_id=None,
    )->dict:
        company_id=int(company_id)
        schema=self.company_schema(company_id)

        authority_code=str(
            body.get("authority_code") or ""
        ).strip().upper()
        return_type=str(
            body.get("return_type") or ""
        ).strip().lower()
        source_line_type=str(
            body.get("source_line_type") or ""
        ).strip().lower()
        schedule_section=str(
            body.get("schedule_section") or ""
        ).strip()

        if not authority_code:
            raise ValueError("authority_code is required")
        if not return_type:
            raise ValueError("return_type is required")
        if not source_line_type:
            raise ValueError("source_line_type is required")
        if not schedule_section:
            raise ValueError("schedule_section is required")

        values=(
            authority_code,
            return_type,
            source_line_type,
            str(body.get("source_code") or "").strip() or None,
            schedule_section,
            str(
                body.get("amount_basis") or "amount"
            ).strip().lower(),
            bool(body.get("include_employee_detail",True)),
            int(body.get("display_order") or 1),
            bool(body.get("is_active",True)),
        )

        if mapping_id:
            row=self.fetch_one(f"""
                UPDATE {schema}.payroll_statutory_item_mappings
                SET
                    authority_code=%s,
                    return_type=%s,
                    source_line_type=%s,
                    source_code=%s,
                    schedule_section=%s,
                    amount_basis=%s,
                    include_employee_detail=%s,
                    display_order=%s,
                    is_active=%s,
                    updated_at=NOW()
                WHERE company_id=%s AND id=%s
                RETURNING *;
            """,values+(
                company_id,
                int(mapping_id),
            ))
        else:
            row=self.fetch_one(f"""
                INSERT INTO {schema}.payroll_statutory_item_mappings(
                    company_id,
                    authority_code,
                    return_type,
                    source_line_type,
                    source_code,
                    schedule_section,
                    amount_basis,
                    include_employee_detail,
                    display_order,
                    is_active
                )
                VALUES(
                    %s,%s,%s,%s,%s,
                    %s,%s,%s,%s,%s
                )
                RETURNING *;
            """,(company_id,)+values)

        if not row:
            raise ValueError("Statutory mapping not found")

        return row


    def payroll_statutory_mapping_delete(
        self,
        company_id:int,
        mapping_id:int,
    )->bool:
        schema=self.company_schema(company_id)

        row=self.fetch_one(f"""
            DELETE FROM {schema}.payroll_statutory_item_mappings
            WHERE company_id=%s AND id=%s
            RETURNING id;
        """,(
            int(company_id),
            int(mapping_id),
        ))

        return bool(row)

    def payroll_statutory_returns_list(
        self,
        company_id:int,
        *,
        authority_code=None,
        return_type=None,
        status=None,
        date_from=None,
        date_to=None,
    )->list[dict]:
        schema=self.company_schema(company_id)
