    def payroll_statutory_return_get(
        self,
        company_id:int,
        return_id:int,
    )->dict|None:
        schema=self.company_schema(company_id)

        row=self.fetch_one(f"""
            SELECT *
            FROM {schema}.payroll_statutory_return_runs
            WHERE company_id=%s AND id=%s
            LIMIT 1;
        """,(
            int(company_id),
            int(return_id),
        ))

        if not row:
            return None

        row["lines"]=self.fetch_all(f"""
            SELECT *
            FROM {schema}.payroll_statutory_return_lines
            WHERE company_id=%s
            AND statutory_return_run_id=%s
            ORDER BY
                schedule_section,
                employee_no,
                source_code,
                id;
        """,(
            int(company_id),
            int(return_id),
        ))

        return row 

    def payroll_statutory_return_save(
        self,
        company_id:int,
        body:dict,
        user_id=None,
        return_id=None,
    )->dict:
        company_id=int(company_id)
        schema=self.company_schema(company_id)

        authority_code=str(
            body.get("authority_code") or ""
        ).strip().upper()
        return_type=str(
            body.get("return_type") or ""
        ).strip().lower()
        period_start=body.get("period_start")
        period_end=body.get("period_end")
        reporting_date=(
            body.get("reporting_date")
            or period_end
        )

        if not authority_code:
            raise ValueError("authority_code is required")
        if not return_type:
            raise ValueError("return_type is required")
        if not period_start or not period_end:
            raise ValueError(
                "period_start and period_end are required"
            )

        if str(period_end)<str(period_start):
            raise ValueError(
                "period_end cannot be before period_start"
            )

        values=(
            authority_code,
            return_type,
            period_start,
            period_end,
            reporting_date,
            body.get("due_date") or None,
            str(body.get("currency") or "LSL").upper(),
            str(body.get("notes") or "").strip() or None,
            user_id,
        )

        if return_id:
            existing=self.payroll_statutory_return_get(
                company_id,
                return_id,
            )

            if not existing:
                raise ValueError(
                    "Statutory return not found"
                )

            if existing["status"] not in(
                "draft",
                "calculated",
                "rejected",
            ):
                raise ValueError(
                    f"{existing['status'].title()} return "
                    "cannot be edited"
                )

            row=self.fetch_one(f"""
                UPDATE {schema}.payroll_statutory_return_runs
                SET
                    authority_code=%s,
                    return_type=%s,
                    period_start=%s,
                    period_end=%s,
                    reporting_date=%s,
                    due_date=%s,
                    currency=%s,
                    notes=%s,
                    updated_by_user_id=%s,
                    updated_at=NOW()
                WHERE company_id=%s AND id=%s
                RETURNING *;
            """,values+(
                company_id,
                int(return_id),
            ))
        else:
            sequence=self.fetch_one(f"""
                SELECT COALESCE(
                    MAX(
                        NULLIF(
                            REGEXP_REPLACE(
                                return_no,
                                '[^0-9]',
                                '',
                                'g'
                            ),
                            ''
                        )::INT
                    ),
                    0
                )+1 AS next_no
                FROM {schema}.payroll_statutory_return_runs
                WHERE company_id=%s;
            """,(company_id,)) or {}

            return_no=(
                f"STAT-{int(sequence.get('next_no') or 1):06d}"
            )

            row=self.fetch_one(f"""
                INSERT INTO {schema}.payroll_statutory_return_runs(
                    company_id,
                    return_no,
                    authority_code,
                    return_type,
                    period_start,
                    period_end,
                    reporting_date,
                    due_date,
                    currency,
                    notes,
                    created_by_user_id,
                    updated_by_user_id
                )
                VALUES(
                    %s,%s,%s,%s,%s,%s,
                    %s,%s,%s,%s,%s,%s
                )
                RETURNING *;
            """,(
                company_id,
                return_no,
                *values,
            ))

        return self.payroll_statutory_return_get(
            company_id,
            row["id"],
        )

    def payroll_statutory_return_calculate(
        self,
        company_id:int,
        return_id:int,
        user_id=None,
    )->dict:
        company_id=int(company_id)
        return_id=int(return_id)
        schema=self.company_schema(company_id)

        statutory=self.payroll_statutory_return_get(
            company_id,
            return_id,
        )

        if not statutory:
            raise ValueError("Statutory return not found")

        if statutory["status"] in(
            "approved",
            "submitted",
            "accepted",
            "cancelled",
        ):
            raise ValueError(
                f"{statutory['status'].title()} return "
                "cannot be recalculated"
            )

        mappings=self.fetch_all(f"""
            SELECT *
            FROM {schema}.payroll_statutory_item_mappings
            WHERE company_id=%s
            AND is_active=TRUE
            AND return_type=%s
            AND authority_code IN(%s,'DEFAULT')
            ORDER BY
                CASE
                    WHEN authority_code=%s THEN 1
                    ELSE 2
                END,
                display_order,
                id;
        """,(
            company_id,
            statutory["return_type"],
            statutory["authority_code"],
            statutory["authority_code"],
        ))

        if not mappings:
            raise ValueError(
                "No statutory mappings are configured "
                "for this return type"
            )

        self.execute_sql(f"""
            DELETE FROM {schema}.payroll_statutory_return_lines
            WHERE company_id=%s
            AND statutory_return_run_id=%s;
        """,(
            company_id,
            return_id,
        ))

        inserted=0

        for mapping in mappings:
            source_code=mapping.get("source_code")
            code_filter="AND l.code=%s" if source_code else ""
            params=[
                company_id,
                statutory["period_start"],
                statutory["period_end"],
                mapping["source_line_type"],
            ]

            if source_code:
                params.append(source_code)

            rows=self.fetch_all(f"""
                SELECT
                    r.id AS payroll_run_id,
                    re.employee_id,
                    e.employee_no,
                    CONCAT_WS(
                        ' ',
                        e.first_name,
                        e.last_name
                    ) AS employee_name,
                    e.tax_number,
                    COALESCE(d.name,'Unassigned')
                        AS department_name,
                    re.gross_pay,
                    re.taxable_income,
                    l.code AS source_code,
                    l.description AS source_description,
                    l.amount,
                    l.metadata
                FROM {schema}.payroll_run_lines l
                JOIN {schema}.payroll_runs r
                ON r.company_id=l.company_id
                AND r.id=l.payroll_run_id
                JOIN {schema}.payroll_run_employees re
                ON re.company_id=l.company_id
                AND re.id=l.run_employee_id
                JOIN {schema}.payroll_employees e
                ON e.company_id=l.company_id
                AND e.id=l.employee_id
                LEFT JOIN {schema}.payroll_departments d
                ON d.company_id=e.company_id
                AND d.id=e.department_id
                WHERE l.company_id=%s
                AND r.payment_date BETWEEN %s AND %s
                AND r.status='posted'
                AND l.line_type=%s
                {code_filter}
                ORDER BY
                    e.employee_no,
                    l.id;
            """,tuple(params))

            for row in rows:
                amount=_payroll_money(row.get("amount"))
                employee_amount=(
                    amount
                    if mapping["source_line_type"]
                    in("tax","deduction")
                    else Decimal("0")
                )
                employer_amount=(
                    amount
                    if mapping["source_line_type"]
                    =="employer_contribution"
                    else Decimal("0")
                )

                self.fetch_one(f"""
                    INSERT INTO {schema}.payroll_statutory_return_lines(
                        company_id,
                        statutory_return_run_id,
                        payroll_run_id,
                        employee_id,
                        employee_no,
                        employee_name,
                        tax_number,
                        department_name,
                        schedule_section,
                        source_line_type,
                        source_code,
                        source_description,
                        gross_remuneration,
                        taxable_remuneration,
                        employee_amount,
                        employer_amount,
                        total_amount,
                        metadata
                    )
                    VALUES(
                        %s,%s,%s,%s,%s,%s,%s,%s,%s,
                        %s,%s,%s,%s,%s,%s,%s,%s,%s
                    )
                    RETURNING id;
                """,(
                    company_id,
                    return_id,
                    row.get("payroll_run_id"),
                    row.get("employee_id"),
                    row.get("employee_no"),
                    row.get("employee_name"),
                    row.get("tax_number"),
                    row.get("department_name"),
                    mapping["schedule_section"],
                    row.get("source_line_type")
                    or mapping["source_line_type"],
                    row.get("source_code"),
                    row.get("source_description"),
                    _payroll_money(row.get("gross_pay")),
                    _payroll_money(
                        row.get("taxable_income")
                    ),
                    employee_amount,
                    employer_amount,
                    _payroll_money(
                        employee_amount+employer_amount
                    ),
                    row.get("metadata") or {},
                ))
                inserted+=1

        totals=self.fetch_one(f"""
            SELECT
                COUNT(DISTINCT employee_id)::INT
                    AS employee_count,
                COALESCE(SUM(gross_remuneration),0)
                    AS gross_remuneration,
                COALESCE(SUM(taxable_remuneration),0)
                    AS taxable_remuneration,
                COALESCE(SUM(employee_amount),0)
                    AS employee_amount,
                COALESCE(SUM(employer_amount),0)
                    AS employer_amount,
                COALESCE(SUM(total_amount),0)
                    AS total_payable
            FROM {schema}.payroll_statutory_return_lines
            WHERE company_id=%s
            AND statutory_return_run_id=%s;
        """,(
            company_id,
            return_id,
        )) or {}

        self.fetch_one(f"""
            UPDATE {schema}.payroll_statutory_return_runs
            SET
                status='calculated',
                employee_count=%s,
                gross_remuneration=%s,
                taxable_remuneration=%s,
                employee_amount=%s,
                employer_amount=%s,
                total_payable=%s,
                calculated_by_user_id=%s,
                calculated_at=NOW(),
                updated_by_user_id=%s,
                updated_at=NOW()
            WHERE company_id=%s AND id=%s
            RETURNING id;
        """,(
            int(totals.get("employee_count") or 0),
            _payroll_money(
                totals.get("gross_remuneration")
            ),
            _payroll_money(
                totals.get("taxable_remuneration")
            ),
            _payroll_money(
                totals.get("employee_amount")
            ),
            _payroll_money(
                totals.get("employer_amount")
            ),
            _payroll_money(
                totals.get("total_payable")
            ),
            user_id,
            user_id,
            company_id,
            return_id,
        ))

        if not inserted:
            raise ValueError(
                "No posted payroll amounts matched the "
                "configured statutory mappings"
            )

        return self.payroll_statutory_return_get(
            company_id,
            return_id,
        )

    def payroll_statutory_return_action(
        self,
        company_id:int,
        return_id:int,
        action:str,
        body:dict|None=None,
        user_id=None,
    )->dict:
        company_id=int(company_id)
        return_id=int(return_id)
        body=body or {}
        schema=self.company_schema(company_id)

        statutory=self.payroll_statutory_return_get(
            company_id,
            return_id,
        )

        if not statutory:
            raise ValueError("Statutory return not found")

        action=str(action or "").strip().lower()
        status=statutory["status"]

        if action=="approve":
            if status!="calculated":
                raise ValueError(
                    "Only calculated returns can be approved"
                )

            if not statutory.get("lines"):
                raise ValueError(
                    "The statutory return has no lines"
                )

            self.fetch_one(f"""
                UPDATE {schema}.payroll_statutory_return_runs
                SET
                    status='approved',
                    approved_by_user_id=%s,
                    approved_at=NOW(),
                    updated_by_user_id=%s,
                    updated_at=NOW()
                WHERE company_id=%s AND id=%s
                RETURNING id;
            """,(
                user_id,
                user_id,
                company_id,
                return_id,
            ))

        elif action=="submit":
            if status!="approved":
                raise ValueError(
                    "Only approved returns can be submitted"
                )

            reference=str(
                body.get("submission_reference") or ""
            ).strip()

            if not reference:
                raise ValueError(
                    "submission_reference is required"
                )

            self.fetch_one(f"""
                UPDATE {schema}.payroll_statutory_return_runs
                SET
                    status='submitted',
                    submission_reference=%s,
                    submission_date=%s,
                    submitted_by_user_id=%s,
                    rejection_reason=NULL,
                    updated_by_user_id=%s,
                    updated_at=NOW()
                WHERE company_id=%s AND id=%s
                RETURNING id;
            """,(
                reference,
                body.get("submission_date")
                or statutory["reporting_date"],
                user_id,
                user_id,
                company_id,
                return_id,
            ))

        elif action=="accept":
            if status!="submitted":
                raise ValueError(
                    "Only submitted returns can be accepted"
                )

            self.fetch_one(f"""
                UPDATE {schema}.payroll_statutory_return_runs
                SET
                    status='accepted',
                    accepted_date=%s,
                    rejection_reason=NULL,
                    updated_by_user_id=%s,
                    updated_at=NOW()
                WHERE company_id=%s AND id=%s
                RETURNING id;
            """,(
                body.get("accepted_date")
                or statutory["reporting_date"],
                user_id,
                company_id,
                return_id,
            ))

        elif action=="reject":
            if status!="submitted":
                raise ValueError(
                    "Only submitted returns can be rejected"
                )

            reason=str(
                body.get("rejection_reason") or ""
            ).strip()

            if not reason:
                raise ValueError(
                    "rejection_reason is required"
                )

            self.fetch_one(f"""
                UPDATE {schema}.payroll_statutory_return_runs
                SET
                    status='rejected',
                    rejection_reason=%s,
                    updated_by_user_id=%s,
                    updated_at=NOW()
                WHERE company_id=%s AND id=%s
                RETURNING id;
            """,(
                reason,
                user_id,
                company_id,
                return_id,
            ))

        elif action=="return-to-draft":
            if status not in(
                "calculated",
                "approved",
                "rejected",
            ):
                raise ValueError(
                    "This return cannot be returned to draft"
                )

            self.fetch_one(f"""
                UPDATE {schema}.payroll_statutory_return_runs
                SET
                    status='draft',
                    approved_by_user_id=NULL,
                    approved_at=NULL,
                    submission_reference=NULL,
                    submission_date=NULL,
                    submitted_by_user_id=NULL,
                    rejection_reason=NULL,
                    updated_by_user_id=%s,
                    updated_at=NOW()
                WHERE company_id=%s AND id=%s
                RETURNING id;
            """,(
                user_id,
                company_id,
                return_id,
            ))

        elif action=="cancel":
            if status=="accepted":
                raise ValueError(
                    "Accepted returns cannot be cancelled"
                )

            self.fetch_one(f"""
                UPDATE {schema}.payroll_statutory_return_runs
                SET
                    status='cancelled',
                    updated_by_user_id=%s,
                    updated_at=NOW()
                WHERE company_id=%s AND id=%s
                RETURNING id;
            """,(
                user_id,
                company_id,
                return_id,
            ))

        else:
            raise ValueError(
                "Unsupported statutory return action"
            )

        return self.payroll_statutory_return_get(
            company_id,
            return_id,
        )

    def payroll_statutory_return_export_payload(
        self,
        company_id:int,
        return_id:int,
    )->dict:
        statutory=self.payroll_statutory_return_get(
            company_id,
            return_id,
        )

        if not statutory:
            raise ValueError("Statutory return not found")

        grouped={}

        for line in statutory.get("lines") or []:
            grouped.setdefault(
                line["schedule_section"],
                [],
            ).append(line)

        sections=[]

        for title,rows in grouped.items():
            sections.append({
                "title":title,
                "rows":[{
                    "employee_no":row.get("employee_no"),
                    "employee_name":row.get("employee_name"),
                    "tax_number":row.get("tax_number"),
                    "department":
                        row.get("department_name"),
                    "source_code":row.get("source_code"),
                    "description":
                        row.get("source_description"),
                    "gross_remuneration":float(
                        _payroll_money(
                            row.get("gross_remuneration")
                        )
                    ),
                    "taxable_remuneration":float(
                        _payroll_money(
                            row.get("taxable_remuneration")
                        )
                    ),
                    "employee_amount":float(
                        _payroll_money(
                            row.get("employee_amount")
                        )
                    ),
                    "employer_amount":float(
                        _payroll_money(
                            row.get("employer_amount")
                        )
                    ),
                    "total_amount":float(
                        _payroll_money(
                            row.get("total_amount")
                        )
                    ),
                } for row in rows],
                "amount_keys":[
                    "gross_remuneration",
                    "taxable_remuneration",
                    "employee_amount",
                    "employer_amount",
                    "total_amount",
                ],
                "amount_labels":{
                    "gross_remuneration":
                        "Gross remuneration",
                    "taxable_remuneration":
                        "Taxable remuneration",
                    "employee_amount":
                        "Employee amount",
                    "employer_amount":
                        "Employer amount",
                    "total_amount":"Total",
                },
            })

        return{
            "meta":{
                "report_key":
                    "payroll_statutory_return",
                "company_id":int(company_id),
                "return_id":int(return_id),
                "return_no":statutory["return_no"],
                "authority_code":
                    statutory["authority_code"],
                "return_type":
                    statutory["return_type"],
                "period_start":
                    statutory["period_start"],
                "period_end":statutory["period_end"],
                "status":statutory["status"],
            },
            "title":(
                f"{statutory['authority_code']} "
                f"{statutory['return_type'].replace('_',' ').title()}"
            ),
            "sections":sections,
            "totals":{
                "employee_count":
                    statutory["employee_count"],
                "gross_remuneration":float(
                    statutory["gross_remuneration"]
                ),
                "taxable_remuneration":float(
                    statutory["taxable_remuneration"]
                ),
                "employee_amount":float(
                    statutory["employee_amount"]
                ),
                "employer_amount":float(
                    statutory["employer_amount"]
                ),
                "total_payable":float(
                    statutory["total_payable"]
                ),
            },
            "return":statutory,
        }

    def deferred_tax_get_settings(self, company_id: int) -> Dict[str, Any]:
        row = self.fetch_one("""
            SELECT
                c.id AS company_id,
                c.country,
                c.tax_authority_id,
                c.income_tax_rate,
                c.deferred_tax_enabled,
                c.deferred_tax_settings,
                ta.code AS tax_authority_code,
                ta.name AS tax_authority_name
            FROM public.companies c
            LEFT JOIN public.tax_authorities ta
            ON ta.id = c.tax_authority_id
            WHERE c.id = %s
            LIMIT 1;
        """, (company_id,))

        if not row:
            raise ValueError("Company not found.")

        return row

    def deferred_tax_update_settings(
        self,
        company_id: int,
        payload: Dict[str, Any],
    ) -> Dict[str, Any]:
        authority_id = payload.get("tax_authority_id")
        tax_rate = Decimal(str(payload.get("income_tax_rate") or 0))
        enabled = bool(payload.get("deferred_tax_enabled", True))
        settings = payload.get("deferred_tax_settings") or {}

        if tax_rate < 0 or tax_rate > 100:
            raise ValueError("Income tax rate must be between 0 and 100.")

        if authority_id:
            authority = self.fetch_one("""
                SELECT id
                FROM public.tax_authorities
                WHERE id = %s
                AND is_active = TRUE
                LIMIT 1;
            """, (authority_id,))

            if not authority:
                raise ValueError("Invalid tax authority.")

        return self.fetch_one("""
            UPDATE public.companies
            SET
                tax_authority_id = %s,
                income_tax_rate = %s,
                deferred_tax_enabled = %s,
                deferred_tax_settings = %s::jsonb
            WHERE id = %s
            RETURNING
                id AS company_id,
                tax_authority_id,
                income_tax_rate,
                deferred_tax_enabled,
                deferred_tax_settings;
        """, (
            authority_id,
            tax_rate,
            enabled,
            json.dumps(settings),
            company_id,
        ))

    def deferred_tax_list_authorities(self):
        return self.fetch_all("""
            SELECT id, code, name, country_code
            FROM public.tax_authorities
            WHERE is_active = TRUE
            ORDER BY name;
        """)

    def deferred_tax_list_allowance_rules(
        self,
        tax_authority_id: int,
    ):
        return self.fetch_all("""
            SELECT
                id,
                tax_authority_id,
                asset_category,
                method,
                rate_percent,
                useful_life_years,
                initial_allowance_percent,
                effective_from,
                effective_to,
                notes
            FROM public.tax_allowance_rules
            WHERE tax_authority_id = %s
            AND is_active = TRUE
            ORDER BY asset_category, effective_from DESC;
        """, (tax_authority_id,))


    def deferred_tax_list_runs(
        self,
        company_id: int,
        status: Optional[str] = None,
        reporting_date: Optional[str] = None,
    ) -> List[Dict[str, Any]]:
        schema = self.company_schema(company_id)

        where = ["r.company_id = %s"]
        params: List[Any] = [int(company_id)]

        if status:
            where.append("r.status = %s")
            params.append(status)

        if reporting_date:
            where.append("r.reporting_date = %s")
            params.append(reporting_date)

        return self.fetch_all(f"""
            SELECT
                r.*,
                ta.code AS tax_authority_code,
                ta.name AS tax_authority_name,
                COUNT(l.id)::int AS line_count
            FROM {schema}.deferred_tax_runs r
            LEFT JOIN public.tax_authorities ta
                ON ta.id = r.tax_authority_id
            LEFT JOIN {schema}.deferred_tax_run_lines l
                ON l.run_id = r.id
            WHERE {' AND '.join(where)}
            GROUP BY
                r.id,
                ta.code,
                ta.name
            ORDER BY
                r.reporting_date DESC,
                r.id DESC;
        """, tuple(params))

    def deferred_tax_get_run(
        self,
        company_id: int,
        run_id: int,
    ) -> Dict[str, Any]:
        schema = self.company_schema(company_id)

        run = self.fetch_one(f"""
            SELECT
                r.*,
                ta.code AS tax_authority_code,
                ta.name AS tax_authority_name
            FROM {schema}.deferred_tax_runs r
            LEFT JOIN public.tax_authorities ta
                ON ta.id = r.tax_authority_id
            WHERE r.company_id = %s
            AND r.id = %s
            LIMIT 1;
        """, (
            int(company_id),
            int(run_id),
        ))

        if not run:
            raise ValueError("Deferred-tax run not found.")

        run["lines"] = self.fetch_all(f"""
            SELECT *
            FROM {schema}.deferred_tax_run_lines
            WHERE company_id = %s
            AND run_id = %s
            ORDER BY
                source_module,
                source_type,
                id;
        """, (
            int(company_id),
            int(run_id),
        ))

        run["recognition_assessments"] = self.fetch_all(f"""
            SELECT *
            FROM {schema}.deferred_tax_recognition_assessments
            WHERE company_id = %s
            AND run_id = %s
            ORDER BY assessment_type, id;
        """, (
            int(company_id),
            int(run_id),
        ))

        return run

    def deferred_tax_create_run(
        self,
        company_id: int,
        payload: Dict[str, Any],
        user_id: Optional[int] = None,
    ) -> Dict[str, Any]:
        schema = self.company_schema(company_id)

        reporting_date = payload.get("reporting_date")
        tax_authority_id = payload.get("tax_authority_id")
        tax_rate = _decimal(payload.get("tax_rate"))

        if not reporting_date:
            raise ValueError("reporting_date is required.")

        if tax_authority_id is None:
            raise ValueError("tax_authority_id is required.")

        if tax_rate < 0 or tax_rate > 100:
            raise ValueError("tax_rate must be between 0 and 100.")

        authority = self.fetch_one("""
            SELECT id
            FROM public.tax_authorities
            WHERE id = %s
            AND is_active = TRUE
            LIMIT 1;
        """, (int(tax_authority_id),))

        if not authority:
            raise ValueError("Invalid tax authority.")

        existing = self.fetch_one(f"""
            SELECT id
            FROM {schema}.deferred_tax_runs
            WHERE company_id = %s
            AND reporting_date = %s
            AND tax_authority_id = %s
            AND status <> 'void'
            LIMIT 1;
        """, (
            int(company_id),
            reporting_date,
            int(tax_authority_id),
        ))

        if existing:
            raise ValueError(
                "An active deferred-tax run already exists "
                "for this reporting date and tax authority."
            )

        run = self.fetch_one(f"""
            INSERT INTO {schema}.deferred_tax_runs (
                company_id,
                reporting_date,
                tax_authority_id,
                tax_rate,
                created_by_user_id,
                calculation_json
            )
            VALUES (%s, %s, %s, %s, %s, %s::jsonb)
            RETURNING *;
        """, (
            int(company_id),
            reporting_date,
            int(tax_authority_id),
            tax_rate,
            int(user_id) if user_id else None,
            json_dumps(_json_dict(payload.get("calculation_json"))),
        ))

        return run

    def deferred_tax_add_line(
        self,
        company_id: int,
        run_id: int,
        payload: Dict[str, Any],
    ) -> Dict[str, Any]:
        schema = self.company_schema(company_id)

        run = self.fetch_one(f"""
            SELECT id, status, tax_rate
            FROM {schema}.deferred_tax_runs
            WHERE company_id = %s
            AND id = %s
            LIMIT 1;
        """, (
            int(company_id),
            int(run_id),
        ))

        if not run:
            raise ValueError("Deferred-tax run not found.")

        if run["status"] != "draft":
            raise ValueError("Only draft runs can be edited.")

        carrying_amount = _decimal(payload.get("carrying_amount"))
        tax_base = _decimal(payload.get("tax_base"))

        balance_type = payload.get("balance_type")
        if balance_type not in {
            "asset",
            "liability",
            "tax_loss",
            "tax_credit",
        }:
            raise ValueError("Invalid balance_type.")

        temporary_difference, difference_type = (
            self.deferred_tax_classify_difference(
                balance_type=balance_type,
                carrying_amount=carrying_amount,
                tax_base=tax_base,
            )
        )

        tax_rate = _decimal(
            payload.get("tax_rate"),
            str(run["tax_rate"]),
        )

        recognition_percent = _decimal(
            payload.get("recognition_percent"),
            "100",
        )

        if recognition_percent < 0 or recognition_percent > 100:
            raise ValueError(
                "recognition_percent must be between 0 and 100."
            )

        gross_deferred_tax = (
            abs(temporary_difference)
            * tax_rate
            / Decimal("100")
        ).quantize(Decimal("0.01"))

        recognized_amount = (
            gross_deferred_tax
            * recognition_percent
            / Decimal("100")
        ).quantize(Decimal("0.01"))

        unrecognized_amount = (
            gross_deferred_tax - recognized_amount
        ).quantize(Decimal("0.01"))

        line = self.fetch_one(f"""
            INSERT INTO {schema}.deferred_tax_run_lines (
                company_id,
                run_id,
                source_module,
                source_table,
                source_type,
                source_id,
                source_line_id,
                description,
                balance_type,
                carrying_amount,
                tax_base,
                temporary_difference,
                difference_type,
                tax_rate,
                gross_deferred_tax,
                recognition_percent,
                recognized_amount,
                unrecognized_amount,
                recognition_destination,
                tax_treatment_code,
                reversal_pattern,
                expected_reversal_date,
                is_manual,
                scan_status,
                calculation_json
            )
            VALUES (
                %s, %s, %s, %s, %s,
                %s, %s, %s, %s, %s,
                %s, %s, %s, %s, %s,
                %s, %s, %s, %s, %s,
                %s, %s, %s, %s, %s::jsonb
            )
            RETURNING *;
        """, (
            int(company_id),
            int(run_id),
            payload.get("source_module", "manual"),
            payload.get("source_table"),
            payload.get("source_type", "manual"),
            payload.get("source_id"),
            payload.get("source_line_id"),
            payload.get("description") or "Manual temporary difference",
            balance_type,
            carrying_amount,
            tax_base,
            temporary_difference,
            difference_type,
            tax_rate,
            gross_deferred_tax,
            recognition_percent,
            recognized_amount,
            unrecognized_amount,
            payload.get(
                "recognition_destination",
                "profit_or_loss",
            ),
            payload.get("tax_treatment_code"),
            payload.get("reversal_pattern"),
            payload.get("expected_reversal_date"),
            bool(payload.get("is_manual", True)),
            "resolved",
            json_dumps(
                _json_dict(payload.get("calculation_json"))
            ),
        ))

        self.deferred_tax_refresh_totals(
            company_id,
            run_id,
        )

        return line

    def deferred_tax_classify_difference(
        self,
        balance_type: str,
        carrying_amount: Decimal,
        tax_base: Decimal,
    ) -> tuple[Decimal, str]:
        difference = carrying_amount - tax_base

        if difference == 0:
            return Decimal("0"), "none"

        if balance_type == "asset":
            difference_type = (
                "taxable"
                if difference > 0
                else "deductible"
            )

        elif balance_type == "liability":
            difference_type = (
                "deductible"
                if difference > 0
                else "taxable"
            )

        elif balance_type == "tax_loss":
            return abs(difference), "tax_loss"

        elif balance_type == "tax_credit":
            return abs(difference), "tax_credit"

        else:
            raise ValueError("Invalid balance type.")

        return difference, difference_type

    def deferred_tax_refresh_totals(
        self,
        company_id: int,
        run_id: int,
    ) -> Dict[str, Any]:
        schema = self.company_schema(company_id)

        totals = self.fetch_one(f"""
            SELECT
                COALESCE(SUM(
                    CASE
                        WHEN scan_status = 'resolved'
                        AND difference_type = 'taxable'
                        THEN ABS(temporary_difference)
                        ELSE 0
                    END
                ), 0)::numeric(18,2)
                    AS total_taxable_difference,

                COALESCE(SUM(
                    CASE
                        WHEN scan_status = 'resolved'
                        AND difference_type IN (
                            'deductible',
                            'tax_loss',
                            'tax_credit'
                        )
                        THEN ABS(temporary_difference)
                        ELSE 0
                    END
                ), 0)::numeric(18,2)
                    AS total_deductible_difference,

                COALESCE(SUM(
                    CASE
                        WHEN scan_status = 'resolved'
                        AND difference_type = 'taxable'
                        THEN gross_deferred_tax
                        ELSE 0
                    END
                ), 0)::numeric(18,2)
                    AS gross_dtl,

                COALESCE(SUM(
                    CASE
                        WHEN scan_status = 'resolved'
                        AND difference_type IN (
                            'deductible',
                            'tax_loss',
                            'tax_credit'
                        )
                        THEN gross_deferred_tax
                        ELSE 0
                    END
                ), 0)::numeric(18,2)
                    AS gross_dta,

                COALESCE(SUM(
                    CASE
                        WHEN scan_status = 'resolved'
                        AND difference_type = 'taxable'
                        THEN recognized_amount
                        ELSE 0
                    END
                ), 0)::numeric(18,2)
                    AS recognized_dtl,

                COALESCE(SUM(
                    CASE
                        WHEN scan_status = 'resolved'
                        AND difference_type IN (
                            'deductible',
                            'tax_loss',
                            'tax_credit'
                        )
                        THEN recognized_amount
                        ELSE 0
                    END
                ), 0)::numeric(18,2)
                    AS recognized_dta,

                COALESCE(SUM(
                    CASE
                        WHEN difference_type IN (
                            'deductible',
                            'tax_loss',
                            'tax_credit'
                        )
                        THEN unrecognized_amount
                        ELSE 0
                    END
                ), 0)::numeric(18,2)
                    AS unrecognized_dta,

                COALESCE(SUM(
                    CASE
                        WHEN scan_status <> 'resolved'
                        AND difference_type = 'taxable'
                        THEN gross_deferred_tax
                        ELSE 0
                    END
                ), 0)::numeric(18,2)
                    AS unresolved_dtl,

                COUNT(*) FILTER (
                    WHERE scan_status = 'requires_review'
                )::int AS requires_review_count,

                COUNT(*) FILTER (
                    WHERE scan_status = 'reconciliation_error'
                )::int AS reconciliation_error_count

            FROM {schema}.deferred_tax_run_lines
            WHERE company_id = %s
            AND run_id = %s;
        """, (
            int(company_id),
            int(run_id),
        )) or {}

        total_taxable_difference = Decimal(str(
            totals.get("total_taxable_difference") or 0
        ))

        total_deductible_difference = Decimal(str(
            totals.get("total_deductible_difference") or 0
        ))

        gross_dta = Decimal(str(
            totals.get("gross_dta") or 0
        ))

        gross_dtl = Decimal(str(
            totals.get("gross_dtl") or 0
        ))

        recognized_dta = Decimal(str(
            totals.get("recognized_dta") or 0
        ))

        recognized_dtl = Decimal(str(
            totals.get("recognized_dtl") or 0
        ))

        unrecognized_dta = Decimal(str(
            totals.get("unrecognized_dta") or 0
        ))

        net_deferred_tax = (
            recognized_dtl - recognized_dta
        ).quantize(Decimal("0.01"))

        calculation_summary = {
            "recognized_dta": str(recognized_dta.quantize(Decimal("0.01"))),
            "recognized_dtl": str(recognized_dtl.quantize(Decimal("0.01"))),
            "unrecognized_dta": str(unrecognized_dta.quantize(Decimal("0.01"))),
            "unresolved_dtl": str(
                Decimal(str(totals.get("unresolved_dtl") or 0))
                .quantize(Decimal("0.01"))
            ),
            "requires_review_count": int(
                totals.get("requires_review_count") or 0
            ),
            "reconciliation_error_count": int(
                totals.get("reconciliation_error_count") or 0
            ),
        }

        self.execute_sql(f"""
            UPDATE {schema}.deferred_tax_runs
            SET total_taxable_difference=%s,
                total_deductible_difference=%s,
                gross_dta=%s,
                gross_dtl=%s,
                recognized_dta=%s,
                recognized_dtl=%s,
                unrecognized_dta=%s,
                net_deferred_tax=%s,
                calculation_json=COALESCE(
                    calculation_json,
                    '{{}}'::jsonb
                ) || %s::jsonb
            WHERE company_id=%s AND id=%s
        """, (
            total_taxable_difference,
            total_deductible_difference,
            gross_dta,
            gross_dtl,
            recognized_dta,
            recognized_dtl,
            unrecognized_dta,
            net_deferred_tax,
            json.dumps(calculation_summary, default=str),
            int(company_id),
            int(run_id),
        ))

        return self.fetch_one(f"""
            SELECT *
            FROM {schema}.deferred_tax_runs
            WHERE company_id = %s
            AND id = %s
            LIMIT 1;
        """, (
            int(company_id),
            int(run_id),
        ))

    def deferred_tax_delete_line(
        self,
        company_id: int,
        run_id: int,
        line_id: int,
    ) -> None:
        schema = self.company_schema(company_id)

        run = self.fetch_one(f"""
            SELECT status
            FROM {schema}.deferred_tax_runs
            WHERE company_id = %s
            AND id = %s
            LIMIT 1;
        """, (
            int(company_id),
            int(run_id),
        ))

        if not run:
            raise ValueError("Deferred-tax run not found.")

        if run["status"] != "draft":
            raise ValueError("Only draft runs can be edited.")

        deleted = self.fetch_one(f"""
            DELETE FROM {schema}.deferred_tax_run_lines
            WHERE company_id = %s
            AND run_id = %s
            AND id = %s
            RETURNING id;
        """, (
            int(company_id),
            int(run_id),
            int(line_id),
        ))

        if not deleted:
            raise ValueError("Deferred-tax line not found.")

        self.deferred_tax_refresh_totals(
            company_id,
            run_id,
        )

    def deferred_tax_review_run(
        self,
        company_id: int,
        run_id: int,
        user_id: int,
    ) -> Dict[str, Any]:
        schema = self.company_schema(company_id)

        self.deferred_tax_refresh_totals(company_id, run_id)

        run = self.fetch_one(f"""
            SELECT id, status
            FROM {schema}.deferred_tax_runs
            WHERE company_id=%s AND id=%s
            LIMIT 1;
        """, (int(company_id), int(run_id)))

        if not run:
            raise ValueError("Deferred-tax run not found.")

        if run["status"] != "draft":
            raise ValueError(
                "Only a draft deferred-tax run can be reviewed."
            )

        checks = self.fetch_one(f"""
            SELECT
                COUNT(*)::int AS line_count,
                COUNT(*) FILTER (
                    WHERE scan_status='requires_review'
                )::int AS review_count,
                COUNT(*) FILTER (
                    WHERE scan_status='reconciliation_error'
                )::int AS reconciliation_error_count
            FROM {schema}.deferred_tax_run_lines
            WHERE company_id=%s AND run_id=%s;
        """, (int(company_id), int(run_id))) or {}

        line_count = int(checks.get("line_count") or 0)
        review_count = int(checks.get("review_count") or 0)
        error_count = int(
            checks.get("reconciliation_error_count") or 0
        )

        if line_count == 0:
            raise ValueError(
                "The deferred-tax run has no temporary-difference lines. "
                "Scan the balance sheet or add a manual line first."
            )

        if review_count:
            raise ValueError(
                f"{review_count} deferred-tax line(s) still require review."
            )

        if error_count:
            raise ValueError(
                f"{error_count} deferred-tax line(s) have reconciliation errors."
            )

        return self.fetch_one(f"""
            UPDATE {schema}.deferred_tax_runs
            SET status='reviewed',
                reviewed_by_user_id=%s,
                reviewed_at=NOW()
            WHERE company_id=%s
            AND id=%s
            AND status='draft'
            RETURNING *;
        """, (
            int(user_id) if user_id else None,
            int(company_id),
            int(run_id),
        ))

    def deferred_tax_approve_run(
        self,
        company_id: int,
        run_id: int,
        user_id: int,
    ) -> Dict[str, Any]:
        schema = self.company_schema(company_id)

        self.deferred_tax_refresh_totals(company_id, run_id)

        run = self.fetch_one(f"""
            SELECT id, status
            FROM {schema}.deferred_tax_runs
            WHERE company_id=%s AND id=%s
            LIMIT 1;
        """, (int(company_id), int(run_id)))

        if not run:
            raise ValueError("Deferred-tax run not found.")

        if run["status"] != "reviewed":
            raise ValueError(
                "Only a reviewed deferred-tax run can be approved."
            )

        checks = self.fetch_one(f"""
            SELECT
                COUNT(*) FILTER (
                    WHERE scan_status='requires_review'
                )::int AS review_count,
                COUNT(*) FILTER (
                    WHERE scan_status='reconciliation_error'
                )::int AS reconciliation_error_count
            FROM {schema}.deferred_tax_run_lines
            WHERE company_id=%s AND run_id=%s;
        """, (int(company_id), int(run_id))) or {}

        review_count = int(checks.get("review_count") or 0)
        error_count = int(
            checks.get("reconciliation_error_count") or 0
        )

        if review_count or error_count:
            raise ValueError(
                "The deferred-tax run contains unresolved lines. "
                "Return it to draft and resolve them before approval."
            )

        approved = self.fetch_one(f"""
            UPDATE {schema}.deferred_tax_runs
            SET status='approved',
                approved_by_user_id=%s,
                approved_at=NOW()
            WHERE company_id=%s
            AND id=%s
            AND status='reviewed'
            RETURNING *;
        """, (
            int(user_id) if user_id else None,
            int(company_id),
            int(run_id),
        ))

        if not approved:
            raise ValueError(
                "The deferred-tax run could not be approved."
            )

        return approved

    def deferred_tax_void_run(
        self,
        company_id: int,
        run_id: int,
    ) -> Dict[str, Any]:
        schema = self.company_schema(company_id)

        run = self.fetch_one(f"""
            UPDATE {schema}.deferred_tax_runs
            SET status = 'void'
            WHERE company_id = %s
            AND id = %s
            AND status IN (
                'draft',
                'reviewed',
                'approved'
            )
            RETURNING *;
        """, (
            int(company_id),
            int(run_id),
        ))

        if not run:
            raise ValueError(
                "Posted or reversed runs cannot be voided."
            )

        return run

    def deferred_tax_list_overrides(
        self,
        company_id: int,
        source_module: Optional[str] = None,
        source_type: Optional[str] = None,
        source_id: Optional[int] = None,
    ) -> List[Dict[str, Any]]:
        schema = self.company_schema(company_id)

        where = ["company_id = %s"]
        params: List[Any] = [int(company_id)]

        if source_module:
            where.append("source_module = %s")
            params.append(source_module)

        if source_type:
            where.append("source_type = %s")
            params.append(source_type)

        if source_id is not None:
            where.append("source_id = %s")
            params.append(int(source_id))

        return self.fetch_all(f"""
            SELECT *
            FROM {schema}.deferred_tax_tax_base_overrides
            WHERE {' AND '.join(where)}
            ORDER BY effective_date DESC, id DESC;
        """, tuple(params))

    def deferred_tax_save_override(
        self,
        company_id: int,
        payload: Dict[str, Any],
        user_id: Optional[int] = None,
    ) -> Dict[str, Any]:
        schema = self.company_schema(company_id)

        existing = self.fetch_one(f"""
            SELECT id
            FROM {schema}.deferred_tax_tax_base_overrides
            WHERE company_id = %s
            AND source_module = %s
            AND source_type = %s
            AND source_id IS NOT DISTINCT FROM %s
            AND effective_date = %s
            LIMIT 1;
        """, (
            int(company_id),
            payload["source_module"],
            payload["source_type"],
            payload.get("source_id"),
            payload["effective_date"],
        ))

        values = (
            _decimal(payload["tax_base"]),
            payload["reason"],
            payload.get("supporting_reference"),
            int(user_id) if user_id else None,
        )

        if existing:
            return self.fetch_one(f"""
                UPDATE {schema}.deferred_tax_tax_base_overrides
                SET
                    tax_base = %s,
                    reason = %s,
                    supporting_reference = %s,
                    created_by_user_id = %s
                WHERE company_id = %s
                AND id = %s
                RETURNING *;
            """, values + (
                int(company_id),
                int(existing["id"]),
            ))

        return self.fetch_one(f"""
            INSERT INTO {schema}.deferred_tax_tax_base_overrides (
                company_id,
                source_module,
                source_type,
                source_id,
                effective_date,
                tax_base,
                reason,
                supporting_reference,
                created_by_user_id
            )
            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s)
            RETURNING *;
        """, (
            int(company_id),
            payload["source_module"],
            payload["source_type"],
            payload.get("source_id"),
            payload["effective_date"],
            *values,
        ))

    def deferred_tax_save_recognition_assessment(
        self,
        company_id: int,
        run_id: int,
        payload: Dict[str, Any],
        user_id: Optional[int] = None,
    ) -> Dict[str, Any]:
        schema = self.company_schema(company_id)

        assessment_type = payload.get("assessment_type")

        valid_types = {
            "deductible_temporary_differences",
            "tax_losses",
            "tax_credits",
            "investment_exemption",
        }

        if assessment_type not in valid_types:
            raise ValueError("Invalid assessment_type.")

        run = self.fetch_one(f"""
            SELECT id, status
            FROM {schema}.deferred_tax_runs
            WHERE company_id = %s
            AND id = %s
            LIMIT 1;
        """, (
            int(company_id),
            int(run_id),
        ))

        if not run:
            raise ValueError("Deferred-tax run not found.")

        if run["status"] not in {"draft", "reviewed"}:
            raise ValueError(
                "Recognition assessments cannot be changed "
                "after approval."
            )

        available = _decimal(
            payload.get("available_deductible_amount")
        )

        forecast_profit = _decimal(
            payload.get("forecast_taxable_profit")
        )

        recognized = _decimal(
            payload.get("recognized_amount")
        )

        unrecognized = _decimal(
            payload.get(
                "unrecognized_amount",
                available - recognized,
            )
        )

        existing = self.fetch_one(f"""
            SELECT id
            FROM {schema}.deferred_tax_recognition_assessments
            WHERE company_id = %s
            AND run_id = %s
            AND assessment_type = %s
            LIMIT 1;
        """, (
            int(company_id),
            int(run_id),
            assessment_type,
        ))

        values = (
            available,
            forecast_profit,
            recognized,
            unrecognized,
            payload.get("conclusion"),
            json_dumps(
                _json_dict(payload.get("evidence_json"))
            ),
            int(user_id) if user_id else None,
        )

        if existing:
            assessment = self.fetch_one(f"""
                UPDATE {schema}.deferred_tax_recognition_assessments
                SET
                    available_deductible_amount = %s,
                    forecast_taxable_profit = %s,
                    recognized_amount = %s,
                    unrecognized_amount = %s,
                    conclusion = %s,
                    evidence_json = %s::jsonb,
                    assessed_by_user_id = %s,
                    assessed_at = NOW()
                WHERE company_id = %s
                AND id = %s
                RETURNING *;
            """, values + (
                int(company_id),
                int(existing["id"]),
            ))

            self.deferred_tax_refresh_totals(
                company_id,
                run_id,
            )

            return assessment

        assessment = self.fetch_one(f"""
            INSERT INTO {schema}.deferred_tax_recognition_assessments (
                company_id,
                run_id,
                assessment_type,
                available_deductible_amount,
                forecast_taxable_profit,
                recognized_amount,
                unrecognized_amount,
                conclusion,
                evidence_json,
                assessed_by_user_id,
                assessed_at
            )
            VALUES (
                %s, %s, %s, %s, %s,
                %s, %s, %s, %s::jsonb, %s,
                NOW()
            )
            RETURNING *;
        """, (
            int(company_id),
            int(run_id),
            assessment_type,
            available,
            forecast_profit,
            recognized,
            unrecognized,
            payload.get("conclusion"),
            json_dumps(
                _json_dict(
                    payload.get("evidence_json")
                )
            ),
            int(user_id) if user_id else None,
        ))

        self.deferred_tax_refresh_totals(
            company_id,
            run_id,
        )

        return assessment

    def deferred_tax_return_to_draft(
        self,
        company_id: int,
        run_id: int,
    ) -> dict:
        schema = self.company_schema(company_id)

        row = self.fetch_one(f"""
            UPDATE {schema}.deferred_tax_runs
            SET
                status = 'draft',
                reviewed_by_user_id = NULL,
                reviewed_at = NULL
            WHERE company_id = %s
            AND id = %s
            AND status = 'reviewed'
            RETURNING *;
        """, (
            int(company_id),
            int(run_id),
        ))

        if not row:
            raise ValueError(
                "Only a reviewed run can be returned to draft."
            )

        return row

    def deferred_tax_post_run(
        self,
        company_id: int,
        run_id: int,
        user_id: int | None = None,
    ) -> Dict[str, Any]:
        schema = self.company_schema(company_id)

        run = self.fetch_one(
            f"""
            SELECT *
            FROM {schema}.deferred_tax_runs
            WHERE company_id = %s
            AND id = %s
            LIMIT 1;
            """,
            (
                company_id,
                run_id,
            ),
        )

        if not run:
            raise ValueError("Deferred-tax run not found.")

        if run.get("status") != "approved":
            raise ValueError(
                "Only an approved run can be posted."
            )

        if run.get("journal_id"):
            raise ValueError(
                "Deferred-tax run is already posted."
            )

        reporting_date = str(
            run.get("reporting_date") or ""
        )[:10]

        preview = self.preview_deferred_tax_posting(
            company_id=company_id,
            run_id=run_id,
            posting_date=reporting_date,
            reference=f"DT-{run_id}",
            description=(
                f"Deferred tax adjustment at "
                f"{reporting_date}"
            ),
            user_id=user_id,
        )

        lines = (
            preview.get("preview_journal_lines")
            or []
        )

        if not lines:
            return self.fetch_one(
                f"""
                UPDATE {schema}.deferred_tax_runs
                SET status = 'posted',
                    posted_at = NOW()
                WHERE company_id = %s
                AND id = %s
                RETURNING *;
                """,
                (
                    company_id,
                    run_id,
                ),
            )

        totals = preview.get("totals") or {}

        total_debit = Decimal(
            str(totals.get("debit") or 0)
        )

        total_credit = Decimal(
            str(totals.get("credit") or 0)
        )

        if total_debit != total_credit:
            raise ValueError(
                "Deferred-tax journal does not balance: "
                f"debits {total_debit}, "
                f"credits {total_credit}"
            )

        preview_header = (
            preview.get("preview_journal")
            or {}
        )

        journal_id = self.post_journal(
            company_id,
            {
                "date": (
                    preview_header.get("date")
                    or reporting_date
                ),
                "ref": (
                    preview_header.get("ref")
                    or f"DT-{run_id}"
                ),
                "description": (
                    preview_header.get("description")
                    or (
                        f"Deferred tax adjustment at "
                        f"{reporting_date}"
                    )
                ),
                "source": "deferred_tax",
                "source_id": run_id,
                "prepared_by_user_id": user_id,
                "created_by_user_id": user_id,
                "module_name": "deferred_tax",
                "lines": lines,
            },
        )

        return self.fetch_one(
            f"""
            UPDATE {schema}.deferred_tax_runs
            SET status = 'posted',
                journal_id = %s,
                posted_at = NOW()
            WHERE company_id = %s
            AND id = %s
            RETURNING *;
            """,
            (
                journal_id,
                company_id,
                run_id,
            ),
        )
        
    def deferred_tax_build_balance_sheet(
        self,
        company_id: int,
        as_at: date,
    ) -> Dict[str, Any]:

        def _get_company_context(cid: int) -> Dict[str, Any]:
            return get_company_context(self, cid) or {}

        def _get_trial_balance(
            cid: int,
            _date_from: Optional[date],
            date_to: date,
        ) -> List[Dict[str, Any]]:
            rows = self.get_trial_balance_as_of(cid, date_to) or []
            coa_rows = self.get_company_coa(cid) or []

            coa_map = {
                str(row.get("code") or "").strip(): row
                for row in coa_rows
                if row.get("code")
            }

            result = []

            for row in rows:
                code = str(
                    row.get("code")
                    or row.get("account")
                    or row.get("account_code")
                    or ""
                ).strip()

                if not code:
                    continue

                coa = coa_map.get(code, {})

                result.append({
                    **row,
                    "code": code,
                    "name": row.get("name") or coa.get("name") or code,
                    "section": row.get("section") or coa.get("section") or "",
                    "category": row.get("category") or coa.get("category") or "",
                    "subcategory": row.get("subcategory") or coa.get("subcategory") or "",
                    "standard": row.get("standard") or coa.get("standard") or "",
                    "role": row.get("role") or coa.get("role") or "",
                    "code_family": row.get("code_family") or coa.get("code_family") or "",
                    "is_contra": bool(
                        row.get("is_contra")
                        or coa.get("is_contra")
                        or False
                    ),
                    "debit_total": float(
                        row.get("debit_total")
                        or row.get("debit")
                        or 0
                    ),
                    "credit_total": float(
                        row.get("credit_total")
                        or row.get("credit")
                        or 0
                    ),
                })

            return result

        return build_balance_sheet_v3(
            company_id=int(company_id),
            as_of=as_at,
            get_company_context_fn=_get_company_context,
            get_trial_balance_fn=_get_trial_balance,
            get_pnl_full_fn=self.get_pnl_full,
            include_net_profit_line=True,
            view="external",
            basis="external",
        )

    def _dt_classify(
        self,
        balance_type: str,
        carrying_amount: Decimal,
        tax_base: Decimal,
    ):
        difference = carrying_amount - tax_base

        if difference == 0:
            return difference, "none"

        if balance_type == "asset":
            return difference, "taxable" if difference > 0 else "deductible"

        if balance_type == "liability":
            return difference, "deductible" if difference > 0 else "taxable"

        raise ValueError(f"Unsupported balance type: {balance_type}")

    def _dt_insert_scanned_line(
        self,
        cur,
        *,
        schema: str,
        company_id: int,
        run: Dict[str, Any],
        source_module: str,
        source_table: str,
        source_type: str,
        source_id,
        source_line_id,
        description: str,
        balance_type: str,
        carrying_amount,
        tax_base,
        bs_account_code: str,
        bs_carrying_amount,
        scan_status: str = "resolved",
        resolution_message: str = None,
        tax_treatment_code: str = None,
        destination: str = "profit_or_loss",
        calculation_json: Dict[str, Any] = None,
    ):
        carrying = Decimal(str(carrying_amount or 0))
        tax_base_value = Decimal(str(tax_base or 0))

        difference, difference_type = self._dt_classify(
            balance_type,
            carrying,
            tax_base_value,
        )

        rate = Decimal(str(run.get("tax_rate") or 0))
        gross_tax = (
            abs(difference) * rate / Decimal("100")
        ).quantize(Decimal("0.01"))

        resolved = scan_status == "resolved"

        params = {
            "company_id": company_id,
            "run_id": run["id"],
            "source_module": source_module,
            "source_table": source_table,
            "source_type": source_type,
            "source_id": source_id,
            "source_line_id": source_line_id,
            "description": description,
            "balance_type": balance_type,
            "carrying_amount": carrying,
            "tax_base": tax_base_value,
            "temporary_difference": difference,
            "difference_type": difference_type,
            "tax_rate": rate,
            "gross_deferred_tax": gross_tax,
            "recognition_percent": Decimal("100") if resolved else Decimal("0"),
            "recognized_amount": gross_tax if resolved else Decimal("0"),
            "unrecognized_amount": Decimal("0") if resolved else gross_tax,
            "recognition_destination": destination,
            "tax_treatment_code": tax_treatment_code,
            "scan_status": scan_status,
            "resolution_message": resolution_message,
            "bs_account_code": bs_account_code,
            "bs_carrying_amount": Decimal(str(bs_carrying_amount or 0)),
            "calculation_json": json.dumps(
                calculation_json or {},
                default=str,
            ),
        }

        cur.execute(f"""
            INSERT INTO {schema}.deferred_tax_run_lines (
                company_id,
                run_id,
                source_module,
                source_table,
                source_type,
                source_id,
                source_line_id,
                description,
                balance_type,
                carrying_amount,
                tax_base,
                temporary_difference,
                difference_type,
                tax_rate,
                gross_deferred_tax,
                recognition_percent,
                recognized_amount,
                unrecognized_amount,
                recognition_destination,
                tax_treatment_code,
                is_manual,
                scan_status,
                resolution_message,
                bs_account_code,
                bs_carrying_amount,
                calculation_json
            )
            VALUES (
                %(company_id)s,
                %(run_id)s,
                %(source_module)s,
                %(source_table)s,
                %(source_type)s,
                %(source_id)s,
                %(source_line_id)s,
                %(description)s,
                %(balance_type)s,
                %(carrying_amount)s,
                %(tax_base)s,
                %(temporary_difference)s,
                %(difference_type)s,
                %(tax_rate)s,
                %(gross_deferred_tax)s,
                %(recognition_percent)s,
                %(recognized_amount)s,
                %(unrecognized_amount)s,
                %(recognition_destination)s,
                %(tax_treatment_code)s,
                FALSE,
                %(scan_status)s,
                %(resolution_message)s,
                %(bs_account_code)s,
                %(bs_carrying_amount)s,
                %(calculation_json)s::jsonb
            )
            RETURNING id;
        """, params)

        row = cur.fetchone()
        return row["id"] if isinstance(row, dict) else row[0]

    def deferred_tax_update_lease_tax_treatment(
        self,
        company_id: int,
        lease_id: int,
        payload: Dict[str, Any],
        user_id: Optional[int] = None,
    ) -> Dict[str, Any]:
        schema = self.company_schema(company_id)

        deduction_basis = str(
            payload.get("tax_deduction_basis") or ""
        ).strip().lower()

        valid_basis = {
            "lease_payments",
            "rou_asset",
            "none",
            "manual",
        }

        if deduction_basis not in valid_basis:
            raise ValueError(
                "tax_deduction_basis must be one of: "
                "lease_payments, rou_asset, none or manual."
            )

        deduction_percent = Decimal(str(
            payload.get("tax_deduction_percent", 100)
        ))

        if deduction_percent < 0 or deduction_percent > 100:
            raise ValueError(
                "tax_deduction_percent must be between 0 and 100."
            )

        rou_override = payload.get(
            "rou_tax_base_override"
        )

        liability_override = payload.get(
            "liability_tax_base_override"
        )

        if deduction_basis == "manual":
            if rou_override in (None, ""):
                raise ValueError(
                    "rou_tax_base_override is required "
                    "for manual lease tax treatment."
                )

            if liability_override in (None, ""):
                raise ValueError(
                    "liability_tax_base_override is required "
                    "for manual lease tax treatment."
                )

        lease = self.fetch_one(f"""
            UPDATE {schema}.leases
            SET
                tax_deduction_basis = %s,
                tax_deduction_percent = %s,
                rou_tax_base_override = %s,
                liability_tax_base_override = %s,
                lease_tax_treatment_notes = %s,
                lease_tax_treatment_updated_at = NOW(),
                lease_tax_treatment_updated_by = %s,
                updated_at = NOW()
            WHERE company_id = %s
            AND id = %s
            RETURNING *;
        """, (
            deduction_basis,
            deduction_percent,
            (
                Decimal(str(rou_override))
                if rou_override not in (None, "")
                else None
            ),
            (
                Decimal(str(liability_override))
                if liability_override not in (None, "")
                else None
            ),
            payload.get("lease_tax_treatment_notes"),
            int(user_id) if user_id else None,
            int(company_id),
            int(lease_id),
        ))

        if not lease:
            raise ValueError("Lease not found.")

        return lease

    def _dt_get_lessee_lease_balances(
        self,
        cur,
        *,
        schema: str,
        company_id: int,
        reporting_date,
    ) -> List[Dict[str, Any]]:
        """
        Returns lessee ROU asset and lease liability balances
        as at the IAS 12 reporting date.

        The active lease schedule is used for both depreciation
        and closing liability.
        """
        return self.fetch_all(f"""
            WITH active_versions AS (
                SELECT
                    ls.lease_id,
                    MAX(ls.version_no) AS version_no
                FROM {schema}.lease_schedule ls
                WHERE ls.company_id = %s
                AND COALESCE(ls.is_active, TRUE) = TRUE
                GROUP BY ls.lease_id
            ),

            schedule_totals AS (
                SELECT
                    ls.lease_id,

                    COALESCE(SUM(
                        CASE
                            WHEN ls.period_end <= %s
                            THEN ls.depreciation
                            ELSE 0
                        END
                    ), 0)::numeric(18,2)
                        AS accumulated_depreciation,

                    COALESCE(SUM(
                        CASE
                            WHEN ls.period_end <= %s
                            THEN ls.interest
                            ELSE 0
                        END
                    ), 0)::numeric(18,2)
                        AS accumulated_interest,

                    COALESCE(SUM(
                        CASE
                            WHEN ls.period_end <= %s
                            THEN ls.principal
                            ELSE 0
                        END
                    ), 0)::numeric(18,2)
                        AS accumulated_principal,

                    COALESCE(SUM(
                        CASE
                            WHEN ls.period_end > %s
                            THEN ls.net_payment
                            ELSE 0
                        END
                    ), 0)::numeric(18,2)
                        AS future_net_lease_payments,

                    COALESCE((
                        SELECT ls2.closing_liability
                        FROM {schema}.lease_schedule ls2
                        WHERE ls2.lease_id = ls.lease_id
                        AND ls2.version_no = ls.version_no
                        AND COALESCE(ls2.is_active, TRUE) = TRUE
                        AND ls2.period_end <= %s
                        ORDER BY
                            ls2.period_end DESC,
                            ls2.period_no DESC,
                            ls2.id DESC
                        LIMIT 1
                    ), 0)::numeric(18,2)
                        AS schedule_closing_liability,

                    MIN(ls.period_start)
                        AS first_schedule_date,

                    MAX(ls.period_end)
                        AS final_schedule_date

                FROM {schema}.lease_schedule ls

                JOIN active_versions av
                    ON av.lease_id = ls.lease_id
                    AND av.version_no = ls.version_no

                WHERE ls.company_id = %s
                AND COALESCE(ls.is_active, TRUE) = TRUE

                GROUP BY
                    ls.lease_id,
                    ls.version_no
            ),

            posted_modifications AS (
                SELECT
                    lm.lease_id,

                    COALESCE(SUM(
                        CASE
                            WHEN lm.modification_date <= %s
                            AND lm.status = 'posted'
                            THEN lm.rou_adjustment
                            ELSE 0
                        END
                    ), 0)::numeric(18,2)
                        AS rou_adjustments,

                    COALESCE(SUM(
                        CASE
                            WHEN lm.modification_date <= %s
                            AND lm.status = 'posted'
                            THEN lm.liability_adjustment
                            ELSE 0
                        END
                    ), 0)::numeric(18,2)
                        AS liability_adjustments

                FROM {schema}.lease_modifications lm
                WHERE lm.company_id = %s
                GROUP BY lm.lease_id
            ),

            posted_terminations AS (
                SELECT
                    lt.lease_id,
                    MAX(lt.termination_date) AS termination_date,
                    COALESCE(MAX(lt.rou_nbv), 0)::numeric(18,2)
                        AS terminated_rou_nbv,
                    COALESCE(MAX(
                        lt.liability_carrying_amount
                    ), 0)::numeric(18,2)
                        AS terminated_liability
                FROM {schema}.lease_terminations lt
                WHERE lt.company_id = %s
                AND lt.status = 'posted'
                AND lt.termination_date <= %s
                GROUP BY lt.lease_id
            )

            SELECT
                l.id AS lease_id,
                l.lease_name,
                l.role,
                l.start_date,
                l.end_date,
                l.status,
                l.termination_date,

                l.opening_rou_asset,
                l.opening_lease_liability,
                l.initial_direct_costs,

                l.tax_treatment_rule_id,
                l.tax_deduction_basis,
                l.tax_deduction_percent,
                l.rou_tax_base_override,
                l.liability_tax_base_override,
                l.lease_tax_treatment_notes,

                COALESCE(
                    st.accumulated_depreciation,
                    0
                )::numeric(18,2)
                    AS accumulated_depreciation,

                COALESCE(
                    st.accumulated_interest,
                    0
                )::numeric(18,2)
                    AS accumulated_interest,

                COALESCE(
                    st.accumulated_principal,
                    0
                )::numeric(18,2)
                    AS accumulated_principal,

                COALESCE(
                    st.future_net_lease_payments,
                    0
                )::numeric(18,2)
                    AS future_net_lease_payments,

                COALESCE(
                    st.schedule_closing_liability,
                    l.opening_lease_liability
                )::numeric(18,2)
                    AS schedule_closing_liability,

                COALESCE(
                    pm.rou_adjustments,
                    0
                )::numeric(18,2)
                    AS rou_adjustments,

                COALESCE(
                    pm.liability_adjustments,
                    0
                )::numeric(18,2)
                    AS liability_adjustments,

                CASE
                    WHEN pt.lease_id IS NOT NULL
                    THEN 0
                    ELSE GREATEST(
                        0,
                        l.opening_rou_asset
                        + COALESCE(pm.rou_adjustments, 0)
                        - COALESCE(
                            st.accumulated_depreciation,
                            0
                        )
                    )
                END::numeric(18,2)
                    AS rou_carrying_amount,

                CASE
                    WHEN pt.lease_id IS NOT NULL
                    THEN 0
                    ELSE GREATEST(
                        0,
                        COALESCE(
                            st.schedule_closing_liability,
                            l.opening_lease_liability
                        )
                    )
                END::numeric(18,2)
                    AS liability_carrying_amount,

                st.first_schedule_date,
                st.final_schedule_date

            FROM {schema}.leases l

            LEFT JOIN schedule_totals st
                ON st.lease_id = l.id

            LEFT JOIN posted_modifications pm
                ON pm.lease_id = l.id

            LEFT JOIN posted_terminations pt
                ON pt.lease_id = l.id

            WHERE l.company_id = %s
            AND LOWER(COALESCE(l.role, '')) = 'lessee'
            AND l.start_date <= %s
            AND (
                l.end_date >= %s
                OR pt.lease_id IS NULL
            )

            ORDER BY
                l.lease_name,
                l.id;
        """, (
            int(company_id),
            reporting_date,
            reporting_date,
            reporting_date,
            reporting_date,
            reporting_date,
            int(company_id),
            reporting_date,
            reporting_date,
            int(company_id),
            int(company_id),
            reporting_date,
            int(company_id),
            reporting_date,
            reporting_date,
        ), cur=cur) or []

    def _dt_get_lease_tax_rule(
        self,
        cur,
        *,
        tax_authority_id: int,
        lease_role: str,
        as_at,
        rule_id: int = None,
    ):
        """
        Returns the applicable public lease tax-treatment rule.

        Priority:
        1. Explicit rule_id, when supplied.
        2. Active default for the authority and lease role.
        """
        normalized_role = str(
            lease_role or "lessee"
        ).strip().lower()

        valid_roles = {
            "lessee",
            "lessor_operating",
            "lessor_finance",
        }

        if normalized_role not in valid_roles:
            normalized_role = "lessee"

        if rule_id:
            rule = self.fetch_one("""
                SELECT
                    r.*,
                    ta.code AS tax_authority_code,
                    ta.name AS tax_authority_name
                FROM public.lease_tax_treatment_rules r
                JOIN public.tax_authorities ta
                    ON ta.id = r.tax_authority_id
                WHERE r.id = %s
                AND r.tax_authority_id = %s
                AND r.lease_role = %s
                AND r.is_active = TRUE
                AND r.effective_from <= %s
                AND (
                    r.effective_to IS NULL
                    OR r.effective_to >= %s
                )
                LIMIT 1;
            """, (
                int(rule_id),
                int(tax_authority_id),
                normalized_role,
                as_at,
                as_at,
            ), cur=cur)

            if rule:
                return rule

        return self.fetch_one("""
            SELECT
                r.*,
                ta.code AS tax_authority_code,
                ta.name AS tax_authority_name
            FROM public.lease_tax_treatment_rules r
            JOIN public.tax_authorities ta
                ON ta.id = r.tax_authority_id
            WHERE r.tax_authority_id = %s
            AND r.lease_role = %s
            AND r.is_default = TRUE
            AND r.is_active = TRUE
            AND r.effective_from <= %s
            AND (
                r.effective_to IS NULL
                OR r.effective_to >= %s
            )
            ORDER BY
                r.effective_from DESC,
                r.id DESC
            LIMIT 1;
        """, (
            int(tax_authority_id),
            normalized_role,
            as_at,
            as_at,
        ), cur=cur)

    def _dt_scan_lessee_leases(
        self,
        cur,
        *,
        schema: str,
        company_id: int,
        run: Dict[str, Any],
    ):
        """
        Scans lessee IFRS 16 leases as paired IAS 12 items:

        1. ROU asset
        2. Lease liability

        The ordinary asset scanner must continue excluding ROU assets.
        """
        reporting_date = run["reporting_date"]
        tax_authority_id = int(run["tax_authority_id"])

        leases = self._dt_get_lessee_lease_balances(
            cur,
            schema=schema,
            company_id=company_id,
            reporting_date=reporting_date,
        )

        for lease in leases:
            lease_id = int(lease["lease_id"])

            rou_carrying = Decimal(str(
                lease.get("rou_carrying_amount") or 0
            )).quantize(Decimal("0.01"))

            liability_carrying = Decimal(str(
                lease.get("liability_carrying_amount") or 0
            )).quantize(Decimal("0.01"))

            future_payments = Decimal(str(
                lease.get("future_net_lease_payments") or 0
            )).quantize(Decimal("0.01"))

            rule = self._dt_get_lease_tax_rule(
                cur,
                tax_authority_id=tax_authority_id,
                lease_role="lessee",
                as_at=reporting_date,
                rule_id=lease.get("tax_treatment_rule_id"),
            )

            lease_basis_override = str(
                lease.get("tax_deduction_basis") or ""
            ).strip().lower()

            if lease_basis_override:
                tax_basis = lease_basis_override
            else:
                tax_basis = str(
                    rule.get("deduction_basis")
                    if rule
                    else "requires_review"
                ).strip().lower()

            lease_percent = lease.get(
                "tax_deduction_percent"
            )

            if (
                lease_basis_override
                and lease_percent is not None
            ):
                deduction_percent = Decimal(str(
                    lease_percent
                ))
            else:
                deduction_percent = Decimal(str(
                    (
                        rule.get("deduction_percent")
                        if rule
                        else 100
                    ) or 100
                ))

            deduction_percent = max(
                Decimal("0"),
                min(
                    Decimal("100"),
                    deduction_percent,
                ),
            )

            rou_tax_base_method = str(
                (
                    rule.get("rou_tax_base_method")
                    if rule
                    else "requires_review"
                ) or "requires_review"
            ).strip().lower()

            liability_tax_base_method = str(
                (
                    rule.get("liability_tax_base_method")
                    if rule
                    else "requires_review"
                ) or "requires_review"
            ).strip().lower()

            has_lease_override = bool(
                lease_basis_override
            )

            rule_requires_review = bool(
                tax_basis == "requires_review"
                or (
                    not has_lease_override
                    and (
                        not rule
                        or bool(rule.get("requires_review"))
                        or rou_tax_base_method
                            == "requires_review"
                        or liability_tax_base_method
                            == "requires_review"
                    )
                )
            )

            deduction_factor = (
                deduction_percent / Decimal("100")
            )

            future_deductions = (
                future_payments * deduction_factor
            ).quantize(Decimal("0.01"))

            scan_status = "resolved"
            resolution_message = None

            if rule_requires_review:
                scan_status = "requires_review"

                if not rule:
                    resolution_message = (
                        "No active lease tax-treatment rule was "
                        "found for the selected tax authority, "
                        "lease role and reporting date."
                    )
                else:
                    resolution_message = (
                        f"{rule.get('rule_name') or 'The applicable lease tax rule'} "
                        "requires review before deferred tax can "
                        "be recognised."
                    )

                rou_tax_base = rou_carrying
                liability_tax_base = liability_carrying
                future_deductions = Decimal("0.00")

            elif tax_basis == "lease_payments":
                rou_tax_base = Decimal("0.00")

                liability_tax_base = max(
                    Decimal("0.00"),
                    liability_carrying - future_deductions,
                ).quantize(Decimal("0.01"))

            elif tax_basis == "rou_asset":
                rou_override = lease.get(
                    "rou_tax_base_override"
                )

                if rou_override is None:
                    scan_status = "requires_review"
                    resolution_message = (
                        "The lease tax treatment says deductions "
                        "relate to the ROU asset, but no remaining "
                        "ROU tax base has been provided."
                    )

                    rou_tax_base = rou_carrying
                    liability_tax_base = liability_carrying

                else:
                    rou_tax_base = Decimal(str(
                        rou_override
                    )).quantize(Decimal("0.01"))

                    liability_tax_base = (
                        liability_carrying
                    )

            elif tax_basis == "none":
                rou_tax_base = Decimal("0.00")
                liability_tax_base = liability_carrying
                future_deductions = Decimal("0.00")

            elif tax_basis == "manual":
                rou_override = lease.get(
                    "rou_tax_base_override"
                )

                liability_override = lease.get(
                    "liability_tax_base_override"
                )

                if (
                    rou_override is None
                    or liability_override is None
                ):
                    scan_status = "requires_review"
                    resolution_message = (
                        "Manual lease tax treatment requires both "
                        "the ROU asset tax base and lease liability "
                        "tax base."
                    )

                    rou_tax_base = rou_carrying
                    liability_tax_base = liability_carrying

                else:
                    rou_tax_base = Decimal(str(
                        rou_override
                    )).quantize(Decimal("0.01"))

                    liability_tax_base = Decimal(str(
                        liability_override
                    )).quantize(Decimal("0.01"))

            else:
                scan_status = "requires_review"
                resolution_message = (
                    "Select the lease tax deduction basis: "
                    "lease payments, ROU asset, none or manual."
                )

                rou_tax_base = rou_carrying
                liability_tax_base = liability_carrying

            common_json = {
                "lease_id": lease_id,
                "lease_name": lease.get("lease_name"),
                "role": lease.get("role"),
                "lease_start_date": str(
                    lease.get("start_date") or ""
                ),
                "lease_end_date": str(
                    lease.get("end_date") or ""
                ),
                "reporting_date": str(reporting_date),
                "tax_deduction_basis": tax_basis,
                "tax_deduction_percent":
                    str(deduction_percent),
                "future_net_lease_payments":
                    str(future_payments),
                "future_deductible_amount":
                    str(future_deductions),
                "opening_rou_asset": str(
                    lease.get("opening_rou_asset") or 0
                ),
                "opening_lease_liability": str(
                    lease.get(
                        "opening_lease_liability"
                    ) or 0
                ),
                "accumulated_depreciation": str(
                    lease.get(
                        "accumulated_depreciation"
                    ) or 0
                ),
                "accumulated_interest": str(
                    lease.get(
                        "accumulated_interest"
                    ) or 0
                ),
                "accumulated_principal": str(
                    lease.get(
                        "accumulated_principal"
                    ) or 0
                ),
                "rou_adjustments": str(
                    lease.get("rou_adjustments") or 0
                ),
                "liability_adjustments": str(
                    lease.get(
                        "liability_adjustments"
                    ) or 0
                ),
                "tax_treatment_notes":
                    lease.get(
                        "lease_tax_treatment_notes"
                    ),
            }

            # ------------------------------------------
            # ROU asset line
            # ------------------------------------------
            self._dt_insert_scanned_line(
                cur,
                schema=schema,
                company_id=company_id,
                run=run,
                source_module="leases",
                source_table="leases",
                source_type="lessee_rou_asset",
                source_id=lease_id,
                source_line_id=None,
                description=(
                    f"{lease.get('lease_name') or 'Lease'} "
                    f"— ROU asset"
                ),
                balance_type="asset",
                carrying_amount=rou_carrying,
                tax_base=rou_tax_base,
                bs_account_code=None,
                bs_carrying_amount=rou_carrying,
                scan_status=scan_status,
                resolution_message=resolution_message,
                tax_treatment_code=(
                    f"ifrs16_lessee|{tax_basis or 'unknown'}"
                    "|rou_asset"
                ),
                destination="profit_or_loss",
                calculation_json={
                    **common_json,
                    "lease_component": "rou_asset",
                    "carrying_amount": str(
                        rou_carrying
                    ),
                    "tax_base": str(rou_tax_base),
                    "tax_base_formula": (
                        "manual override"
                        if tax_basis == "manual"
                        else (
                            "remaining ROU tax basis"
                            if tax_basis == "rou_asset"
                            else "zero"
                        )
                    ),
                },
            )

            # ------------------------------------------
            # Lease liability line
            # ------------------------------------------
            self._dt_insert_scanned_line(
                cur,
                schema=schema,
                company_id=company_id,
                run=run,
                source_module="leases",
                source_table="leases",
                source_type="lessee_lease_liability",
                source_id=lease_id,
                source_line_id=None,
                description=(
                    f"{lease.get('lease_name') or 'Lease'} "
                    f"— lease liability"
                ),
                balance_type="liability",
                carrying_amount=liability_carrying,
                tax_base=liability_tax_base,
                bs_account_code=None,
                bs_carrying_amount=liability_carrying,
                scan_status=scan_status,
                resolution_message=resolution_message,
                tax_treatment_code=(
                    f"ifrs16_lessee|{tax_basis or 'unknown'}"
                    "|lease_liability"
                ),
                destination="profit_or_loss",
                calculation_json={
                    **common_json,
                    "lease_component":
                        "lease_liability",
                    "carrying_amount": str(
                        liability_carrying
                    ),
                    "tax_base": str(
                        liability_tax_base
                    ),
                    "tax_base_formula": (
                        "carrying amount less future "
                        "deductible lease payments"
                        if tax_basis == "lease_payments"
                        else (
                            "manual override"
                            if tax_basis == "manual"
                            else "carrying amount"
                        )
                    ),
                },
            )

    def _dt_scan_assets(
        self,
        cur,
        *,
        schema,
        company_id,
        run,
        candidate,
        asset_tax_run_id,
    ):
        """
        Scans IAS 16 PPE, IAS 38 intangible assets and IAS 40 investment
        property for temporary differences.

        ROU assets are intentionally excluded because they must be scanned
        together with the related lease liability in a separate lease scanner.
        """
        self.ensure_ppe_reporting_views(cur, company_id)

        as_at = run["reporting_date"]
        authority_id = run["tax_authority_id"]
        face_amount = Decimal(
            str(candidate.get("carrying_amount") or 0)
        ).quantize(Decimal("0.01"))

        company_settings = self.deferred_tax_get_settings(company_id)
        dt_settings = (
            company_settings.get("deferred_tax_settings") or {}
        )

        tolerance = Decimal(str(
            dt_settings.get("reconciliation_tolerance", 0.05)
        ))

        standard_map = {
            "ppe": "ias16",
            "intangible_asset": "ias38",
            "investment_property": "ias40",
        }

        source_type = str(
            candidate.get("source_type") or ""
        ).strip().lower()

        accounting_standard = standard_map.get(source_type)

        if not accounting_standard:
            return

        # Only use the candidate account as a filter when it is a real
        # balance-sheet account code. Generic labels such as "PPE" must not
        # be compared with assets.asset_account_code.
        candidate_account_code = str(
            candidate.get("account_code") or ""
        ).strip()

        if not candidate_account_code.startswith("BS_"):
            candidate_account_code = ""

        tax_run_id = int(asset_tax_run_id)

        assets = self.fetch_all(f"""
            WITH movement_totals AS (
                SELECT
                    m.asset_id,

                    SUM(
                        CASE
                            WHEN m.event_date <= %s
                            THEN COALESCE(m.cost_delta, 0)
                            ELSE 0
                        END
                    )::numeric(18,2) AS closing_cost,

                    SUM(
                        CASE
                            WHEN m.event_date <= %s
                            THEN COALESCE(m.accum_dep_delta, 0)
                            ELSE 0
                        END
                    )::numeric(18,2) AS closing_accum_dep,

                    SUM(
                        CASE
                            WHEN m.event_date <= %s
                            THEN COALESCE(m.impairment_delta, 0)
                            ELSE 0
                        END
                    )::numeric(18,2) AS closing_impairment,

                    SUM(
                        CASE
                            WHEN m.event_date <= %s
                            THEN COALESCE(m.carrying_delta, 0)
                            ELSE 0
                        END
                    )::numeric(18,2) AS closing_carrying,

                    SUM(
                        CASE
                            WHEN m.event_date <= %s
                            AND m.source_table = 'asset_revaluation_reserve'
                            THEN COALESCE(
                                m.revaluation_reserve_delta,
                                0
                            )
                            ELSE 0
                        END
                    )::numeric(18,2)
                        AS closing_revaluation_reserve,

                    SUM(
                        CASE
                            WHEN m.event_date <= %s
                            AND m.source_table = 'asset_revaluations'
                            AND m.movement_type IN (
                                'revaluation_up',
                                'revaluation_down'
                            )
                            THEN COALESCE(m.carrying_delta, 0)
                            ELSE 0
                        END
                    )::numeric(18,2)
                        AS total_revaluation_movement,

                    SUM(
                        CASE
                            WHEN m.event_date <= %s
                            AND m.source_table = 'asset_impairments'
                            AND m.movement_type = 'impairment_loss'
                            THEN COALESCE(m.impairment_delta, 0)
                            ELSE 0
                        END
                    )::numeric(18,2) AS impairment_losses,

                    SUM(
                        CASE
                            WHEN m.event_date <= %s
                            AND m.source_table = 'asset_impairments'
                            AND m.movement_type = 'impairment_reversal'
                            THEN ABS(
                                COALESCE(m.impairment_delta, 0)
                            )
                            ELSE 0
                        END
                    )::numeric(18,2) AS impairment_reversals,

                    MAX(
                        CASE
                            WHEN m.event_date <= %s
                            THEN m.event_date
                        END
                    ) AS latest_movement_date

                FROM {schema}.vw_ppe_movements m
                WHERE m.company_id = %s
                GROUP BY m.asset_id
            )

            SELECT
                a.id AS asset_id,
                a.asset_code,
                a.asset_name,
                a.asset_class,
                a.category,
                a.asset_account_code,
                a.accounting_standard,
                a.measurement_basis,
                COALESCE(a.fair_value_model, FALSE)
                    AS fair_value_model,
                a.depreciation_method,
                a.useful_life_months,
                a.residual_value,
                a.acquisition_date,
                a.available_for_use_date,
                a.status AS asset_status,

                COALESCE(mt.closing_cost, 0)::numeric(18,2)
                    AS closing_cost,

                COALESCE(mt.closing_accum_dep, 0)::numeric(18,2)
                    AS closing_accum_dep,

                COALESCE(mt.closing_impairment, 0)::numeric(18,2)
                    AS closing_impairment,

                COALESCE(mt.closing_carrying, 0)::numeric(18,2)
                    AS accounting_carrying_amount,

                COALESCE(
                    mt.closing_revaluation_reserve,
                    0
                )::numeric(18,2) AS revaluation_reserve,

                COALESCE(
                    mt.total_revaluation_movement,
                    0
                )::numeric(18,2) AS revaluation_movement,

                COALESCE(
                    mt.impairment_losses,
                    0
                )::numeric(18,2) AS impairment_losses,

                COALESCE(
                    mt.impairment_reversals,
                    0
                )::numeric(18,2) AS impairment_reversals,

                mt.latest_movement_date,

                p.id AS tax_profile_id,
                p.tax_authority_id,

                trl.id AS tax_run_line_id,
                trl.allowance_rule_id,
                trl.opening_tax_wdv,
                trl.additions,
                trl.disposal_proceeds,
                trl.disposal_tax_value,
                trl.allowance_base,
                trl.initial_allowance,
                trl.annual_allowance,
                trl.total_capital_allowance,
                trl.closing_tax_wdv,
                trl.book_depreciation,
                trl.accounting_carrying_amount
                    AS tax_run_accounting_carrying_amount,
                trl.tax_adjustment,
                trl.temporary_difference
                    AS tax_run_temporary_difference,
                trl.calculation_method,
                trl.rate_percent,
                trl.override_reason,
                trl.notes

            FROM {schema}.assets a

            LEFT JOIN movement_totals mt
                ON mt.asset_id = a.id

            LEFT JOIN {schema}.asset_tax_profiles p
                ON p.company_id = a.company_id
                AND p.asset_id = a.id
                AND p.tax_authority_id = %s

            LEFT JOIN {schema}.asset_tax_run_lines trl
                ON trl.company_id = a.company_id
                AND trl.asset_id = a.id
                AND trl.run_id = %s

            WHERE a.company_id = %s

            AND LOWER(
                REPLACE(
                    COALESCE(a.accounting_standard, ''),
                    ' ',
                    ''
                )
            ) = %s

            AND (
                NULLIF(%s, '') IS NULL
                OR a.asset_account_code = %s
            )

            AND (
                COALESCE(
                    a.available_for_use_date,
                    a.acquisition_date
                ) IS NULL
                OR COALESCE(
                    a.available_for_use_date,
                    a.acquisition_date
                ) <= %s
            )

            AND COALESCE(a.status, 'active') NOT IN (
                'disposed',
                'void',
                'cancelled'
            )

            ORDER BY
                a.asset_class,
                a.asset_code,
                a.id;
        """, (
            as_at,
            as_at,
            as_at,
            as_at,
            as_at,
            as_at,
            as_at,
            as_at,
            as_at,
            int(company_id),
            int(authority_id),
            tax_run_id,
            int(company_id),
            accounting_standard,
            candidate_account_code,
            candidate_account_code,
            as_at,
        ), cur=cur) or []

        assets = [
            row
            for row in assets
            if (
                abs(Decimal(str(
                    row.get("closing_cost") or 0
                ))) > Decimal("0.005")
                or abs(Decimal(str(
                    row.get("closing_accum_dep") or 0
                ))) > Decimal("0.005")
                or abs(Decimal(str(
                    row.get("closing_impairment") or 0
                ))) > Decimal("0.005")
                or abs(Decimal(str(
                    row.get("accounting_carrying_amount") or 0
                ))) > Decimal("0.005")
            )
        ]

        detail_total = sum(
            (
                Decimal(str(
                    row.get("accounting_carrying_amount") or 0
                ))
                for row in assets
            ),
            Decimal("0"),
        ).quantize(Decimal("0.01"))

        reconciliation_difference = (
            detail_total - face_amount
        ).quantize(Decimal("0.01"))

        if not assets:
            self._dt_insert_scanned_line(
                cur,
                schema=schema,
                company_id=company_id,
                run=run,
                source_module="assets",
                source_table="assets",
                source_type=source_type,
                source_id=None,
                source_line_id=None,
                description=(
                    candidate.get("description")
                    or source_type.replace("_", " ").title()
                ),
                balance_type="asset",
                carrying_amount=face_amount,
                tax_base=face_amount,
                bs_account_code=candidate.get("account_code"),
                bs_carrying_amount=face_amount,
                scan_status="requires_review",
                resolution_message=(
                    "No matching assets were found in the asset "
                    "register for this balance-sheet item."
                ),
                tax_treatment_code="asset_register_missing",
                calculation_json={
                    "accounting_standard": accounting_standard,
                    "candidate_account_code":
                        candidate_account_code,
                    "balance_sheet_face_amount":
                        str(face_amount),
                    "asset_register_total": "0.00",
                    "reconciliation_difference":
                        str(-face_amount),
                },
            )
            return

        category_reconciled = (
            abs(reconciliation_difference)
            <= tolerance
        )
 
        for asset in assets:
            carrying_amount = Decimal(str(
                asset.get("accounting_carrying_amount") or 0
            )).quantize(Decimal("0.01"))

            tax_profile_id = asset.get("tax_profile_id")
            tax_run_line_id = asset.get("tax_run_line_id")
            closing_tax_wdv = asset.get("closing_tax_wdv")

            allowance_rule_id = asset.get(
                "allowance_rule_id"
            )

            tax_calculation_method = str(
                asset.get("calculation_method") or ""
            ).strip().upper()

            tax_notes = str(
                asset.get("notes") or ""
            ).strip()

            tax_override_reason = str(
                asset.get("override_reason") or ""
            ).strip()

            revaluation_movement = Decimal(str(
                asset.get("revaluation_movement") or 0
            ))

            revaluation_reserve = Decimal(str(
                asset.get("revaluation_reserve") or 0
            ))

            impairment_losses = Decimal(str(
                asset.get("impairment_losses") or 0
            ))

            impairment_reversals = Decimal(str(
                asset.get("impairment_reversals") or 0
            ))

            measurement_basis = str(
                asset.get("measurement_basis") or ""
            ).strip().lower()

            fair_value_model = bool(
                asset.get("fair_value_model")
            )

            tax_base_is_known = False

            if not tax_profile_id:
                scan_status = "requires_review"
                resolution_message = (
                    "No tax profile is assigned to this asset. "
                    "The tax base has not been determined."
                )
                tax_base = carrying_amount

            elif not tax_run_line_id or closing_tax_wdv is None:
                scan_status = "requires_review"
                resolution_message = (
                    "The selected asset-tax run does not contain "
                    "a closing tax WDV for this asset."
                )
                tax_base = carrying_amount

            elif (
                not allowance_rule_id
                and not tax_override_reason
            ):
                scan_status = "requires_review"
                resolution_message = (
                    "The asset-tax line has no allowance rule or "
                    "documented tax-base override. Review the tax "
                    "treatment before recognising deferred tax."
                )
                tax_base = Decimal(
                    str(closing_tax_wdv)
                ).quantize(Decimal("0.01"))

            elif (
                tax_calculation_method == "CUSTOM"
                and not tax_override_reason
                and "non depreciable" not in tax_notes.lower()
                and "non-depreciable" not in tax_notes.lower()
            ):
                scan_status = "requires_review"
                resolution_message = (
                    "The asset tax base was produced by a custom "
                    "tax method without a documented override."
                )
                tax_base = Decimal(
                    str(closing_tax_wdv)
                ).quantize(Decimal("0.01"))

            else:
                scan_status = "resolved"
                resolution_message = None
                tax_base = Decimal(
                    str(closing_tax_wdv)
                ).quantize(Decimal("0.01"))
                tax_base_is_known = True

            # IAS 40 fair-value movements are recognised in profit or
            # loss. IAS 16/IAS 38 revaluation differences may be OCI.
            recognition_destination = "profit_or_loss"

            if accounting_standard != "ias40":
                total_difference = abs(
                    carrying_amount - tax_base
                )

                revaluation_related_difference = Decimal("0")

                if (
                    tax_base_is_known
                    and revaluation_reserve != 0
                ):
                    revaluation_related_difference = min(
                        total_difference,
                        abs(revaluation_reserve),
                    )

                if (
                    total_difference > 0
                    and revaluation_related_difference
                    == total_difference
                ):
                    recognition_destination = "oci"

            treatment_parts = []

            if (
                revaluation_movement != 0
                or revaluation_reserve != 0
                or (
                    accounting_standard != "ias40"
                    and measurement_basis == "revaluation"
                )
            ):
                treatment_parts.append("revaluation")

            if impairment_losses != 0:
                treatment_parts.append("impairment_loss")

            if impairment_reversals != 0:
                treatment_parts.append("impairment_reversal")

            if accounting_standard == "ias40":
                treatment_parts.append("investment_property")

                if fair_value_model:
                    treatment_parts.append(
                        "investment_property_fair_value"
                    )
                else:
                    treatment_parts.append(
                        "investment_property_cost_model"
                    )

            if (
                tax_base_is_known
                and carrying_amount != tax_base
            ):
                treatment_parts.append(
                    "accounting_carrying_amount_vs_tax_wdv"
                )

            if not tax_base_is_known:
                treatment_parts.append(
                    "tax_base_undetermined"
                )

            if not treatment_parts:
                treatment_parts.append(
                    "no_identified_tax_difference"
                )

            self._dt_insert_scanned_line(
                cur,
                schema=schema,
                company_id=company_id,
                run=run,
                source_module="assets",
                source_table="assets",
                source_type=source_type,
                source_id=asset["asset_id"],
                source_line_id=tax_run_line_id,
                description=(
                    asset.get("asset_name")
                    or asset.get("asset_code")
                    or candidate.get("description")
                    or source_type.replace("_", " ").title()
                ),
                balance_type="asset",
                carrying_amount=carrying_amount,
                tax_base=tax_base,
                bs_account_code=candidate.get("account_code"),
                bs_carrying_amount=face_amount,
                scan_status=scan_status,
                resolution_message=resolution_message,
                tax_treatment_code="|".join(
                    treatment_parts
                ),
                destination=recognition_destination,
                calculation_json={
                    "asset_code": asset.get("asset_code"),
                    "asset_class": asset.get("asset_class"),
                    "asset_account_code": asset.get("asset_account_code"),
                    "accounting_standard": asset.get("accounting_standard"),
                    "measurement_basis": asset.get("measurement_basis"),
                    "fair_value_model": fair_value_model,
                    "depreciation_method": asset.get("depreciation_method"),
                    "accounting_useful_life_months": asset.get("useful_life_months"),
                    "residual_value": str(asset.get("residual_value") or 0),
                    "acquisition_date": str(asset.get("acquisition_date") or ""),
                    "available_for_use_date": str(asset.get("available_for_use_date") or ""),
                    "closing_cost": str(asset.get("closing_cost") or 0),
                    "closing_accum_dep": str(asset.get("closing_accum_dep") or 0),
                    "closing_impairment": str(asset.get("closing_impairment") or 0),
                    "accounting_carrying_amount": str(carrying_amount),
                    "revaluation_movement": str(revaluation_movement),
                    "revaluation_reserve": str(revaluation_reserve),
                    "impairment_losses": str(impairment_losses),
                    "impairment_reversals": str(impairment_reversals),
                    "latest_movement_date": str(asset.get("latest_movement_date") or ""),
                    "tax_base_is_known": tax_base_is_known,
                    "tax_profile_id": tax_profile_id,
                    "asset_tax_run_id": tax_run_id,
                    "asset_tax_run_line_id": tax_run_line_id,
                    "allowance_rule_id": asset.get("allowance_rule_id"),
                    "opening_tax_wdv": str(asset.get("opening_tax_wdv") or 0),
                    "additions": str(asset.get("additions") or 0),
                    "disposal_proceeds": str(asset.get("disposal_proceeds") or 0),
                    "disposal_tax_value": str(asset.get("disposal_tax_value") or 0),
                    "allowance_base": str(asset.get("allowance_base") or 0),
                    "initial_allowance": str(asset.get("initial_allowance") or 0),
                    "annual_allowance": str(asset.get("annual_allowance") or 0),
                    "total_capital_allowance": str(asset.get("total_capital_allowance") or 0),
                    "closing_tax_wdv": str(closing_tax_wdv) if closing_tax_wdv is not None else "",
                    "book_depreciation": str(asset.get("book_depreciation") or 0),
                    "tax_adjustment": str(asset.get("tax_adjustment") or 0),
                    "tax_run_temporary_difference": str(asset.get("tax_run_temporary_difference") or 0),
                    "tax_run_accounting_carrying_amount": str(asset.get("tax_run_accounting_carrying_amount") or 0),
                    "tax_calculation_method": asset.get("calculation_method"),
                    "tax_rate_percent": str(asset.get("rate_percent") or 0),
                    "tax_override_reason": asset.get("override_reason"),
                    "tax_notes": asset.get("notes"),
                    "category_reconciled": category_reconciled,
                    "candidate_account_code": candidate_account_code,
                    "balance_sheet_face_amount": str(face_amount),
                    "asset_register_total": str(detail_total),
                    "reconciliation_difference": str(reconciliation_difference),
                    "tax_base_source":
                        "asset_tax_run.closing_tax_wdv",
                    "asset_tax_run_status_basis":
                        "selected_asset_tax_run",
                    "allowance_rule_configured":
                        bool(allowance_rule_id),
                    "tax_calculation_method":
                        tax_calculation_method,
                    "tax_base_override_documented":
                        bool(tax_override_reason),
                    "ias12_scan_status":
                        scan_status,
                    "ias12_resolution_message":
                        resolution_message,
                },
            )

    def _dt_accrual_tax_base(
        self,
        item_type: str,
        treatment: str,
        carrying_amount: Decimal,
        manual_tax_base,
    ):
        if treatment == "manual":
            if manual_tax_base is None:
                return None
            return Decimal(str(manual_tax_base))

        if item_type in ("prepaid_expense", "deferred_expense"):
            if treatment == "already_deducted":
                return Decimal("0")
            if treatment == "deductible_as_recognized":
                return carrying_amount

        if item_type == "accrued_expense":
            if treatment == "deductible_on_payment":
                return Decimal("0")
            if treatment == "deductible_when_incurred":
                return carrying_amount

        if item_type == "deferred_income":
            if treatment == "taxed_on_receipt":
                return Decimal("0")
            if treatment == "taxed_when_earned":
                return carrying_amount

        if item_type == "accrued_income":
            if treatment == "taxed_on_receipt":
                return Decimal("0")
            if treatment == "taxed_when_earned":
                return carrying_amount

        if treatment == "non_deductible":
            return carrying_amount

        return None

    def _dt_scan_accrual_deferrals(
        self,
        cur,
        *,
        schema: str,
        company_id: int,
        run: Dict[str, Any],
        candidate: Dict[str, Any],
    ):
        items = self.fetch_all(f"""
            SELECT
                i.id,
                i.item_number,
                i.item_title,
                i.item_type,
                i.balance_account,
                i.tax_treatment_code,
                i.manual_tax_base,
                i.tax_treatment_notes,
                s.id AS schedule_line_id,
                s.closing_balance
            FROM {schema}.accrual_deferral_items i
            JOIN LATERAL (
                SELECT
                    sl.id,
                    sl.closing_balance
                FROM {schema}.accrual_deferral_schedule_lines sl
                WHERE sl.company_id = i.company_id
                AND sl.item_id = i.id
                AND sl.period_end <= %s
                AND sl.status NOT IN ('reversed','void')
                ORDER BY sl.period_end DESC, sl.id DESC
                LIMIT 1
            ) s ON TRUE
            WHERE i.company_id = %s
            AND i.status IN ('active','completed')
            AND i.item_type = %s
            AND i.balance_account = %s
            AND ABS(s.closing_balance) > 0.005
            ORDER BY i.id;
        """, (
            run["reporting_date"],
            company_id,
            candidate["source_type"],
            candidate["account_code"],
        ), cur=cur) or []

        detail_total = sum(
            Decimal(str(row.get("closing_balance") or 0))
            for row in items
        )

        face_amount = Decimal(str(candidate["carrying_amount"] or 0))
        reconciles = abs(detail_total - face_amount) <= Decimal("0.05")

        if not items:
            self._dt_insert_scanned_line(
                cur,
                schema=schema,
                company_id=company_id,
                run=run,
                source_module="accrual_deferral",
                source_table="accrual_deferral_items",
                source_type=candidate["source_type"],
                source_id=None,
                source_line_id=None,
                description=candidate["description"],
                balance_type=candidate["balance_type"],
                carrying_amount=face_amount,
                tax_base=face_amount,
                bs_account_code=candidate["account_code"],
                bs_carrying_amount=face_amount,
                scan_status="requires_review",
                resolution_message=(
                    "No accrual/deferral schedule detail was found "
                    "for this balance-sheet account."
                ),
                calculation_json={"candidate": candidate},
            )
            return

        for row in items:
            carrying = Decimal(str(row["closing_balance"] or 0))
            treatment = row.get("tax_treatment_code")

            tax_base = self._dt_accrual_tax_base(
                row["item_type"],
                treatment,
                carrying,
                row.get("manual_tax_base"),
            )

            if not reconciles:
                scan_status = "reconciliation_error"
                message = (
                    f"Schedule total {detail_total} does not reconcile "
                    f"to balance-sheet value {face_amount}."
                )
            elif tax_base is None:
                scan_status = "requires_review"
                message = "Select the tax treatment for this item."
                tax_base = carrying
            else:
                scan_status = "resolved"
                message = None

            self._dt_insert_scanned_line(
                cur,
                schema=schema,
                company_id=company_id,
                run=run,
                source_module="accrual_deferral",
                source_table="accrual_deferral_items",
                source_type=row["item_type"],
                source_id=row["id"],
                source_line_id=row["schedule_line_id"],
                description=(
                    row.get("item_title")
                    or row.get("item_number")
                    or candidate["description"]
                ),
                balance_type=candidate["balance_type"],
                carrying_amount=carrying,
                tax_base=tax_base,
                bs_account_code=candidate["account_code"],
                bs_carrying_amount=face_amount,
                scan_status=scan_status,
                resolution_message=message,
                tax_treatment_code=treatment,
                calculation_json={
                    "item_number": row.get("item_number"),
                    "schedule_total": str(detail_total),
                    "balance_sheet_face_amount": str(face_amount),
                    "tax_treatment_notes": row.get(
                        "tax_treatment_notes"
                    ),
                },
            )

    def deferred_tax_prepare_asset_tax_base(
        self,
        company_id,
        reporting_date,
        tax_authority_id,
        user_id=None,
    ):
        schema = self.company_schema(company_id)

        with self._conn_cursor() as (conn, cur):
            try:
                cur.execute(f"""
                    SELECT *
                    FROM {schema}.asset_tax_runs
                    WHERE company_id = %s
                    AND tax_authority_id = %s
                    AND tax_year_end = %s
                    ORDER BY id DESC
                    LIMIT 1;
                """, (
                    company_id,
                    tax_authority_id,
                    reporting_date,
                ))

                run = cur.fetchone()
                run = dict(run) if run else None

                if not run:
                    start_date = reporting_date.replace(
                        year=reporting_date.year - 1
                    ) + timedelta(days=1)

                    cur.execute(f"""
                        INSERT INTO {schema}.asset_tax_runs (
                            company_id,
                            tax_authority_id,
                            tax_year,
                            tax_year_start,
                            tax_year_end,
                            status,
                            created_by_user_id
                        )
                        VALUES (%s, %s, %s, %s, %s, 'draft', %s)
                        RETURNING *;
                    """, (
                        company_id,
                        tax_authority_id,
                        reporting_date.year,
                        start_date,
                        reporting_date,
                        user_id,
                    ))

                    run = cur.fetchone()
                    run = dict(run) if run else None

                conn.commit()

            except Exception:
                conn.rollback()
                raise

        if not run:
            raise ValueError("Asset-tax run could not be prepared.")

        if run["status"] in ("draft", "calculated"):
            return self.asset_tax_calculate_run(
                company_id,
                int(run["id"]),
            )

        return run

    def _dt_absorb_balance_difference(
        self,
        balance_sheet: Dict[str, Any],
        balance_difference: Decimal,
    ) -> Dict[str, Any]:
        if abs(balance_difference) <= Decimal("0.05"):
            return balance_sheet

        equity = (
            balance_sheet
            .setdefault("equity_and_liabilities", {})
            .setdefault("equity", {})
        )

        lines = equity.setdefault("lines", [])
        totals = equity.setdefault("totals", {})
        eql = (
            balance_sheet["equity_and_liabilities"]
            .setdefault("totals", {})
            .setdefault("values", {})
        )

        amount = float(balance_difference)

        if "total" in totals or "total" in eql:
            values = {
                "noncur": 0.0,
                "cur": 0.0,
                "total": amount,
            }

            totals["total"] = float(totals.get("total") or 0) + amount
            eql["total"] = float(eql.get("total") or 0) + amount
        else:
            values = {"cur": amount}

            totals["cur"] = float(totals.get("cur") or 0) + amount
            eql["cur"] = float(eql.get("cur") or 0) + amount

        lines.append({
            "code": "DT_UNCLOSED_RESULT",
            "name": (
                "Unclosed prior-period profit"
                if balance_difference > 0
                else "Unclosed prior-period loss"
            ),
            "values": values,
            "is_contra": False,
            "meta": {
                "row_type": "balancing_figure",
                "is_deferred_tax_balancing_figure": True,
                "requires_year_end_close": True,
                "source_module": "year_end_close",
                "source_type": "unclosed_profit_loss",
                "role": "equity_retained_earnings",
            },
        })

        balance_sheet["balance_check"] = {
            "label": "Assets - (Equity + Liabilities)",
            "values": (
                {"noncur": 0.0, "cur": 0.0, "total": 0.0}
                if "total" in values
                else {"cur": 0.0}
            ),
        }

        balance_sheet.setdefault("meta", {})[
            "deferred_tax_balancing_figure"
        ] = {
            "amount": str(balance_difference),
            "type": (
                "unclosed_profit"
                if balance_difference > 0
                else "unclosed_loss"
            ),
            "requires_year_end_close": True,
        }

        return balance_sheet

    def deferred_tax_scan_run(
        self,
        company_id: int,
        run_id: int,
        user_id: int | None = None,
    ) -> Dict[str, Any]:
        schema = self.company_schema(company_id)

        run = self.fetch_one(f"""
            SELECT *
            FROM {schema}.deferred_tax_runs
            WHERE company_id = %s
            AND id = %s
            LIMIT 1;
        """, (
            company_id,
            run_id,
        ))

        if not run:
            raise ValueError("Deferred-tax run not found.")

        if run["status"] != "draft":
            raise ValueError(
                "Only a draft deferred-tax run can be scanned."
            )

        prepared = self.deferred_tax_prepare_asset_tax_base(
            company_id=company_id,
            reporting_date=run["reporting_date"],
            tax_authority_id=int(run["tax_authority_id"]),
            user_id=user_id,
        )

        asset_tax_run = (
            prepared.get("run")
            if isinstance(prepared, dict) and prepared.get("run")
            else prepared
        )

        if not asset_tax_run or not asset_tax_run.get("id"):
            raise ValueError(
                "Asset-tax calculation could not be prepared."
            )

        asset_tax_run_id = int(asset_tax_run["id"])

        with self._conn_cursor() as (conn, cur):
            try:
                as_at = run["reporting_date"]

                balance_sheet = self.deferred_tax_build_balance_sheet(company_id, as_at)

                if "data" in balance_sheet and isinstance(balance_sheet.get("data"), dict):
                    balance_sheet = balance_sheet["data"]

                check = balance_sheet.get("balance_check") or {}
                values = check.get("values") or {}
                raw_difference = values.get("total") if values.get("total") is not None else values.get("cur", 0)
                balance_difference = Decimal(str(raw_difference or 0))

                absorbed_difference = Decimal("0.00")

                if abs(balance_difference) > Decimal("0.05"):
                    absorbed_difference = balance_difference

                    balance_sheet = self._dt_absorb_balance_difference(
                        balance_sheet,
                        balance_difference,
                    )

                candidates = extract_deferred_tax_candidates(
                    balance_sheet
                )

                cur.execute(f"""
                    DELETE FROM {schema}.deferred_tax_run_lines
                    WHERE company_id = %s
                    AND run_id = %s
                    AND is_manual = FALSE;
                """, (
                    company_id,
                    run_id,
                ))

                scanned = 0

                for candidate in candidates:
                    module = candidate.get("source_module")
                    source_type = candidate.get("source_type")

                    if (
                        module == "assets"
                        and source_type in (
                            "ppe",
                            "intangible_asset",
                            "investment_property",
                        )
                    ):
                        self._dt_scan_assets(
                            cur,
                            schema=schema,
                            company_id=company_id,
                            run=run,
                            candidate=candidate,
                            asset_tax_run_id=asset_tax_run_id,
                        )
                        scanned += 1
                        continue

                    if (
                        module == "accrual_deferral"
                        and source_type in (
                            "prepaid_expense",
                            "deferred_expense",
                            "deferred_income",
                            "accrued_income",
                            "accrued_expense",
                        )
                    ):
                        self._dt_scan_accrual_deferrals(
                            cur,
                            schema=schema,
                            company_id=company_id,
                            run=run,
                            candidate=candidate,
                        )
                        scanned += 1
                        continue


                # Run once after all balance-sheet candidates have been scanned.
                lease_lines_before = self.fetch_one(
                    f"""
                    SELECT COUNT(*)::int AS line_count
                    FROM {schema}.deferred_tax_run_lines
                    WHERE company_id = %s
                    AND run_id = %s
                    AND source_module = 'leases'
                    AND is_manual = FALSE;
                    """,
                    (
                        int(company_id),
                        int(run_id),
                    ),
                    cur=cur,
                ) or {}

                self._dt_scan_lessee_leases(
                    cur,
                    schema=schema,
                    company_id=company_id,
                    run=run,
                )

                lease_lines_after = self.fetch_one(
                    f"""
                    SELECT COUNT(*)::int AS line_count
                    FROM {schema}.deferred_tax_run_lines
                    WHERE company_id = %s
                    AND run_id = %s
                    AND source_module = 'leases'
                    AND is_manual = FALSE;
                    """,
                    (
                        int(company_id),
                        int(run_id),
                    ),
                    cur=cur,
                ) or {}

                scanned += max(
                    0,
                    int(lease_lines_after.get("line_count") or 0)
                    - int(lease_lines_before.get("line_count") or 0),
                )

                conn.commit()

            except Exception:
                conn.rollback()
                raise

        self.deferred_tax_refresh_totals(
            company_id,
            run_id,
        )

        result = self.deferred_tax_get_run(
            company_id,
            run_id,
        )

        result["scan_summary"] = {
            "balance_sheet_as_at": str(as_at),
            "candidate_count": len(candidates),
            "processed_candidate_count": scanned,
            "asset_tax_run_id": asset_tax_run_id,
            "absorbed_balance_difference": str(absorbed_difference),
            "year_end_close_required": abs(absorbed_difference) > Decimal("0.05"),
            "warning": (
                f"A balancing figure of {abs(absorbed_difference):,.2f} was temporarily "
                f"absorbed as unclosed prior-period "
                f"{'profit' if absorbed_difference > 0 else 'loss'}. "
                f"Complete the Year-End Close to transfer it to retained earnings."
                if abs(absorbed_difference) > Decimal("0.05")
                else None
            ),
        }

        return result

    def revenue_tax_rules_list(
        self,
        tax_authority_id: int = None,
        authority_code: str = None,
        revenue_item_type: str = None,
        active_only: bool = True,
        as_at=None,
    ):
        conditions = []
        params = []

        if tax_authority_id is not None:
            conditions.append("r.tax_authority_id = %s")
            params.append(int(tax_authority_id))

        if authority_code:
            conditions.append("UPPER(ta.code) = UPPER(%s)")
            params.append(str(authority_code).strip())

        if revenue_item_type:
            conditions.append("r.revenue_item_type = %s")
            params.append(str(revenue_item_type).strip())

        if active_only:
            conditions.append("r.is_active = TRUE")

        if as_at:
            conditions.append("r.effective_from <= %s")
            params.append(as_at)

            conditions.append(
                "(r.effective_to IS NULL OR r.effective_to >= %s)"
            )
            params.append(as_at)

        where_sql = ""

        if conditions:
            where_sql = "WHERE " + " AND ".join(conditions)

        return self.fetch_all(f"""
            SELECT
                r.id,
                r.tax_authority_id,
                ta.code AS tax_authority_code,
                ta.name AS tax_authority_name,

                r.rule_code,
                r.rule_name,
                r.revenue_item_type,
                r.tax_trigger_method,
                r.tax_base_method,

                r.effective_from,
                r.effective_to,

                r.configuration,
                r.is_default,
                r.requires_review,
                r.is_active,

                r.source_reference,
                r.notes,
                r.created_at,
                r.updated_at

            FROM public.revenue_tax_treatment_rules r

            JOIN public.tax_authorities ta
                ON ta.id = r.tax_authority_id

            {where_sql}

            ORDER BY
                ta.code,
                r.revenue_item_type,
                r.is_default DESC,
                r.effective_from DESC,
                r.id DESC;
        """, tuple(params)) or []

    def revenue_tax_rule_default(
        self,
        *,
        tax_authority_id: int,
        revenue_item_type: str = "contract_liability",
        as_at=None,
    ):
        as_at = as_at or date.today()

        return self.fetch_one("""
            SELECT
                r.id,
                r.tax_authority_id,
                ta.code AS tax_authority_code,
                ta.name AS tax_authority_name,

                r.rule_code,
                r.rule_name,
                r.revenue_item_type,
                r.tax_trigger_method,
                r.tax_base_method,

                r.effective_from,
                r.effective_to,

                r.configuration,
                r.is_default,
                r.requires_review,
                r.is_active,

                r.source_reference,
                r.notes

            FROM public.revenue_tax_treatment_rules r

            JOIN public.tax_authorities ta
                ON ta.id = r.tax_authority_id

            WHERE r.tax_authority_id = %s
            AND r.revenue_item_type = %s
            AND r.is_default = TRUE
            AND r.is_active = TRUE
            AND r.effective_from <= %s
            AND (
                r.effective_to IS NULL
                OR r.effective_to >= %s
            )

            ORDER BY
                r.effective_from DESC,
                r.id DESC

            LIMIT 1;
        """, (
            int(tax_authority_id),
            str(revenue_item_type),
            as_at,
            as_at,
        ))

    def revenue_contract_tax_profiles_list(
        self,
        company_id: int,
        *,
        contract_id: int = None,
        tax_authority_id: int = None,
        review_status: str = None,
        as_at=None,
    ):
        schema = self.company_schema(company_id)

        conditions = [
            "p.company_id = %s",
        ]

        params = [
            int(company_id),
        ]

        if contract_id is not None:
            conditions.append("p.contract_id = %s")
            params.append(int(contract_id))

        if tax_authority_id is not None:
            conditions.append("p.tax_authority_id = %s")
            params.append(int(tax_authority_id))

        if review_status:
            conditions.append("p.review_status = %s")
            params.append(str(review_status).strip())

        if as_at:
            conditions.append("p.effective_from <= %s")
            params.append(as_at)

            conditions.append(
                "(p.effective_to IS NULL OR p.effective_to >= %s)"
            )
            params.append(as_at)

        where_sql = " AND ".join(conditions)

        return self.fetch_all(f"""
            SELECT
                p.id,
                p.company_id,
                p.contract_id,

                rc.contract_number,
                rc.contract_title,
                rc.contract_date,
                rc.start_date,
                rc.end_date,
                rc.status AS contract_status,

                rc.recognized_revenue_to_date,
                rc.billed_to_date,
                rc.cash_received_to_date,

                GREATEST(
                    COALESCE(rc.billed_to_date, 0)
                    - COALESCE(rc.recognized_revenue_to_date, 0),
                    0
                )::numeric(18,2) AS contract_liability,

                GREATEST(
                    COALESCE(rc.recognized_revenue_to_date, 0)
                    - COALESCE(rc.billed_to_date, 0),
                    0
                )::numeric(18,2) AS contract_asset,

                p.tax_authority_id,
                ta.code AS tax_authority_code,
                ta.name AS tax_authority_name,

                p.treatment_rule_id,
                r.rule_code,
                r.rule_name,
                r.revenue_item_type,
                r.tax_base_method,
                r.requires_review AS rule_requires_review,

                p.tax_treatment_method,
                p.taxable_revenue_to_date,
                p.tax_base_override,
                p.override_reason,
                p.review_status,

                p.effective_from,
                p.effective_to,

                p.notes,
                p.payload_json,

                p.created_by_user_id,
                p.updated_by_user_id,
                p.created_at,
                p.updated_at

            FROM {schema}.revenue_contract_tax_profiles p

            JOIN {schema}.revenue_contracts rc
                ON rc.id = p.contract_id
                AND rc.company_id = p.company_id

            JOIN public.tax_authorities ta
                ON ta.id = p.tax_authority_id

            LEFT JOIN public.revenue_tax_treatment_rules r
                ON r.id = p.treatment_rule_id

            WHERE {where_sql}

            ORDER BY
                rc.contract_number,
                p.effective_from DESC,
                p.id DESC;
        """, tuple(params)) or []

    def revenue_contract_tax_profile_get(
        self,
        company_id: int,
        profile_id: int,
    ):
        rows = self.revenue_contract_tax_profiles_list(
            company_id,
        )

        for row in rows:
            if int(row.get("id") or 0) == int(profile_id):
                return row

        return None

    def revenue_contract_tax_profile_get(
        self,
        company_id: int,
        profile_id: int,
    ):
        schema = self.company_schema(company_id)

        return self.fetch_one(f"""
            SELECT
                p.*,

                rc.contract_number,
                rc.contract_title,
                rc.contract_date,
                rc.start_date,
                rc.end_date,

                rc.recognized_revenue_to_date,
                rc.billed_to_date,
                rc.cash_received_to_date,

                ta.code AS tax_authority_code,
                ta.name AS tax_authority_name,

                r.rule_code,
                r.rule_name,
                r.revenue_item_type,
                r.tax_base_method,
                r.requires_review AS rule_requires_review

            FROM {schema}.revenue_contract_tax_profiles p

            JOIN {schema}.revenue_contracts rc
                ON rc.id = p.contract_id
                AND rc.company_id = p.company_id

            JOIN public.tax_authorities ta
                ON ta.id = p.tax_authority_id

            LEFT JOIN public.revenue_tax_treatment_rules r
                ON r.id = p.treatment_rule_id

            WHERE p.company_id = %s
            AND p.id = %s

            LIMIT 1;
        """, (
            int(company_id),
            int(profile_id),
        ))

    def revenue_contract_tax_profile_ensure(
        self,
        company_id: int,
        contract_id: int,
        *,
        tax_authority_id: int = None,
        user_id: int = None,
        cur=None,
    ):
        import json
        from datetime import date

        schema = self.company_schema(company_id)

        def execute_with_cursor(active_cur):
            contract = self.fetch_one(f"""
                SELECT
                    id,
                    company_id,
                    contract_number,
                    contract_title,
                    contract_date,
                    status
                FROM {schema}.revenue_contracts
                WHERE company_id = %s
                AND id = %s
                LIMIT 1;
            """, (
                int(company_id),
                int(contract_id),
            ), cur=active_cur)

            if not contract:
                raise ValueError(
                    "Revenue contract not found."
                )

            company = self.fetch_one("""
                SELECT
                    id,
                    tax_authority_id
                FROM public.companies
                WHERE id = %s
                LIMIT 1;
            """, (
                int(company_id),
            ), cur=active_cur)

            if not company:
                raise ValueError("Company not found.")

            authority_id = (
                int(tax_authority_id)
                if tax_authority_id is not None
                else company.get("tax_authority_id")
            )

            if not authority_id:
                raise ValueError(
                    "The company has no tax authority assigned."
                )

            effective_from = (
                contract.get("contract_date")
                or date.today()
            )

            existing = self.fetch_one(f"""
                SELECT *
                FROM {schema}.revenue_contract_tax_profiles
                WHERE company_id = %s
                AND contract_id = %s
                AND tax_authority_id = %s
                AND review_status <> 'inactive'
                ORDER BY
                    effective_from DESC,
                    id DESC
                LIMIT 1;
            """, (
                int(company_id),
                int(contract_id),
                int(authority_id),
            ), cur=active_cur)

            if existing:
                return existing

            rule = self.fetch_one("""
                SELECT
                    r.id,
                    r.tax_authority_id,
                    r.rule_code,
                    r.rule_name,
                    r.revenue_item_type,
                    r.tax_trigger_method,
                    r.tax_base_method,
                    r.requires_review,
                    ta.code AS tax_authority_code
                FROM public.revenue_tax_treatment_rules r
                JOIN public.tax_authorities ta
                    ON ta.id = r.tax_authority_id
                WHERE r.tax_authority_id = %s
                AND r.revenue_item_type = 'contract_liability'
                AND r.is_default = TRUE
                AND r.is_active = TRUE
                AND r.effective_from <= %s
                AND (
                    r.effective_to IS NULL
                    OR r.effective_to >= %s
                )
                ORDER BY
                    r.effective_from DESC,
                    r.id DESC
                LIMIT 1;
            """, (
                int(authority_id),
                effective_from,
                effective_from,
            ), cur=active_cur)

            if not rule:
                raise ValueError(
                    "No default revenue tax rule exists for "
                    "the selected tax authority."
                )

            tax_method = (
                rule.get("tax_trigger_method")
                or "requires_review"
            )

            profile_payload = {
                "auto_seeded": True,
                "rule_code": rule.get("rule_code"),
                "authority_code": rule.get(
                    "tax_authority_code"
                ),
                "source": "revenue_contract",
            }

            active_cur.execute(f"""
                INSERT INTO {schema}.revenue_contract_tax_profiles (
                    company_id,
                    contract_id,
                    tax_authority_id,
                    treatment_rule_id,
                    tax_treatment_method,
                    taxable_revenue_to_date,
                    review_status,
                    effective_from,
                    notes,
                    payload_json,
                    created_by_user_id,
                    updated_by_user_id
                )
                VALUES (
                    %s,
                    %s,
                    %s,
                    %s,
                    %s,
                    0,
                    'requires_review',
                    %s,
                    %s,
                    %s::jsonb,
                    %s,
                    %s
                )
                RETURNING *;
            """, (
                int(company_id),
                int(contract_id),
                int(authority_id),
                int(rule["id"]),
                str(tax_method),
                effective_from,
                (
                    "Automatically created from the default "
                    "public revenue tax rule."
                ),
                json.dumps(
                    profile_payload,
                    default=str,
                ),
                int(user_id) if user_id else None,
                int(user_id) if user_id else None,
            ))

            return dict(active_cur.fetchone())

        if cur is not None:
            return execute_with_cursor(cur)

        with self._conn_cursor() as (conn, local_cur):
            result = execute_with_cursor(local_cur)
            conn.commit()
            return result
        
    def revenue_contract_tax_profile_update(
        self,
        company_id: int,
        profile_id: int,
        payload: dict,
        *,
        user_id: int = None,
    ):
        schema = self.company_schema(company_id)

        current = self.fetch_one(f"""
            SELECT *
            FROM {schema}.revenue_contract_tax_profiles
            WHERE company_id = %s
            AND id = %s
            LIMIT 1;
        """, (
            int(company_id),
            int(profile_id),
        ))

        if not current:
            raise ValueError(
                "Revenue contract tax profile not found."
            )

        allowed_methods = {
            "accounting_recognition",
            "billing",
            "cash_received",
            "receipt_or_accrual",
            "upfront_taxation",
            "completion",
            "manual",
            "requires_review",
        }

        allowed_statuses = {
            "requires_review",
            "configured",
            "approved",
            "inactive",
        }

        treatment_rule_id = payload.get(
            "treatment_rule_id",
            current.get("treatment_rule_id"),
        )

        tax_treatment_method = str(
            payload.get(
                "tax_treatment_method",
                current.get("tax_treatment_method")
                or "requires_review",
            )
        ).strip()

        if tax_treatment_method not in allowed_methods:
            raise ValueError(
                "Invalid revenue tax treatment method."
            )

        review_status = str(
            payload.get(
                "review_status",
                current.get("review_status")
                or "requires_review",
            )
        ).strip()

        if review_status not in allowed_statuses:
            raise ValueError(
                "Invalid revenue tax profile status."
            )

        taxable_revenue_to_date = Decimal(str(
            payload.get(
                "taxable_revenue_to_date",
                current.get("taxable_revenue_to_date")
                or 0,
            )
        ))

        if taxable_revenue_to_date < 0:
            raise ValueError(
                "Taxable revenue to date cannot be negative."
            )

        override_value = payload.get(
            "tax_base_override",
            current.get("tax_base_override"),
        )

        if override_value in ("", None):
            tax_base_override = None
        else:
            tax_base_override = Decimal(
                str(override_value)
            )

            if tax_base_override < 0:
                raise ValueError(
                    "Tax-base override cannot be negative."
                )

        override_reason = payload.get(
            "override_reason",
            current.get("override_reason"),
        )

        if (
            tax_base_override is not None
            and not str(override_reason or "").strip()
        ):
            raise ValueError(
                "An override reason is required when "
                "a tax-base override is entered."
            )

        effective_from = payload.get(
            "effective_from",
            current.get("effective_from"),
        )

        effective_to = payload.get(
            "effective_to",
            current.get("effective_to"),
        )

        notes = payload.get(
            "notes",
            current.get("notes"),
        )

        payload_json = payload.get(
            "payload_json",
            current.get("payload_json") or {},
        )

        return self.fetch_one(f"""
            UPDATE {schema}.revenue_contract_tax_profiles
            SET
                treatment_rule_id = %s,
                tax_treatment_method = %s,
                taxable_revenue_to_date = %s,
                tax_base_override = %s,
                override_reason = %s,
                review_status = %s,
                effective_from = %s,
                effective_to = %s,
                notes = %s,
                payload_json = %s::jsonb,
                updated_by_user_id = %s,
                updated_at = NOW()

            WHERE company_id = %s
            AND id = %s

            RETURNING *;
        """, (
            treatment_rule_id,
            tax_treatment_method,
            taxable_revenue_to_date,
            tax_base_override,
            override_reason,
            review_status,
            effective_from,
            effective_to,
            notes,
            json.dumps(
                payload_json,
                default=str,
            ),
            user_id,
            int(company_id),
            int(profile_id),
        ))

    def revenue_contract_tax_base_calculate(
        self,
        *,
        contract: dict,
        profile: dict,
    ):
        recognized = Decimal(str(
            contract.get(
                "recognized_revenue_to_date"
            ) or 0
        ))

        billed = Decimal(str(
            contract.get("billed_to_date") or 0
        ))

        cash_received = Decimal(str(
            contract.get(
                "cash_received_to_date"
            ) or 0
        ))

        taxable_to_date = Decimal(str(
            profile.get(
                "taxable_revenue_to_date"
            ) or 0
        ))

        contract_liability = max(
            billed - recognized,
            Decimal("0"),
        )

        method = str(
            profile.get(
                "tax_treatment_method"
            )
            or "requires_review"
        ).strip().lower()

        override_value = profile.get(
            "tax_base_override"
        )

        if override_value is not None:
            tax_base = Decimal(str(override_value))

            return {
                "carrying_amount": contract_liability,
                "tax_base": tax_base,
                "method": "manual_override",
                "scan_status": "resolved",
                "message": (
                    "Tax base was manually overridden."
                ),
                "recognized_revenue_to_date": recognized,
                "billed_to_date": billed,
                "cash_received_to_date": cash_received,
                "taxable_revenue_to_date": taxable_to_date,
            }

        if method == "accounting_recognition":
            return {
                "carrying_amount": contract_liability,
                "tax_base": contract_liability,
                "method": method,
                "scan_status": "resolved",
                "message": (
                    "Tax follows accounting revenue recognition."
                ),
                "recognized_revenue_to_date": recognized,
                "billed_to_date": billed,
                "cash_received_to_date": cash_received,
                "taxable_revenue_to_date": taxable_to_date,
            }

        if method in {
            "billing",
            "upfront_taxation",
        }:
            return {
                "carrying_amount": contract_liability,
                "tax_base": Decimal("0"),
                "method": method,
                "scan_status": "resolved",
                "message": (
                    "The contract liability has already "
                    "been included in taxable revenue."
                ),
                "recognized_revenue_to_date": recognized,
                "billed_to_date": billed,
                "cash_received_to_date": cash_received,
                "taxable_revenue_to_date": taxable_to_date,
            }

        if method == "cash_received":
            taxed_before_accounting = max(
                cash_received - recognized,
                Decimal("0"),
            )

            tax_base = max(
                contract_liability
                - taxed_before_accounting,
                Decimal("0"),
            )

            return {
                "carrying_amount": contract_liability,
                "tax_base": tax_base,
                "method": method,
                "scan_status": "resolved",
                "message": (
                    "Tax base calculated using cash "
                    "received before accounting recognition."
                ),
                "recognized_revenue_to_date": recognized,
                "billed_to_date": billed,
                "cash_received_to_date": cash_received,
                "taxable_revenue_to_date": taxable_to_date,
            }

        if method == "completion":
            return {
                "carrying_amount": contract_liability,
                "tax_base": contract_liability,
                "method": method,
                "scan_status": "resolved",
                "message": (
                    "Tax is deferred until contract completion."
                ),
                "recognized_revenue_to_date": recognized,
                "billed_to_date": billed,
                "cash_received_to_date": cash_received,
                "taxable_revenue_to_date": taxable_to_date,
            }

        if method == "manual":
            future_taxable_amount = max(
                billed - taxable_to_date,
                Decimal("0"),
            )

            tax_base = min(
                contract_liability,
                future_taxable_amount,
            )

            return {
                "carrying_amount": contract_liability,
                "tax_base": tax_base,
                "method": method,
                "scan_status": "resolved",
                "message": (
                    "Tax base calculated from manually "
                    "maintained taxable revenue to date."
                ),
                "recognized_revenue_to_date": recognized,
                "billed_to_date": billed,
                "cash_received_to_date": cash_received,
                "taxable_revenue_to_date": taxable_to_date,
            }

        return {
            "carrying_amount": contract_liability,
            "tax_base": contract_liability,
            "method": method,
            "scan_status": "requires_review",
            "message": (
                "The revenue tax treatment must be reviewed "
                "before deferred tax can be recognized."
            ),
            "recognized_revenue_to_date": recognized,
            "billed_to_date": billed,
            "cash_received_to_date": cash_received,
            "taxable_revenue_to_date": taxable_to_date,
        }

    def deferred_tax_get_lease_tax_treatment(
        self,
        company_id: int,
        lease_id: int,
    ) -> dict | None:
        schema = self.company_schema(company_id)

        with self._conn_cursor() as (_, cur):
            row = self.fetch_one(f"""
                SELECT
                    r.*,
                    l.lease_name,
                    l.start_date AS lease_start_date,
                    l.end_date AS lease_end_date
                FROM {schema}.lease_tax_treatment_rules r
                JOIN {schema}.leases l
                ON l.id = r.lease_id
                AND l.company_id = r.company_id
                WHERE r.company_id = %s
                AND r.lease_id = %s
                LIMIT 1
            """, (
                company_id,
                lease_id,
            ), cur=cur)

        return dict(row) if row else None
        
    def deferred_tax_update_lease_tax_treatment(
        self,
        company_id: int,
        lease_id: int,
        payload: dict,
        user_id=None,
    ) -> dict:
        schema = self.company_schema(company_id)

        basis = str(
            payload.get("tax_deduction_basis") or ""
        ).strip().lower()

        allowed = {
            "lease_payments",
            "rou_asset",
            "none",
            "manual",
        }

        if basis not in allowed:
            raise ValueError(
                "Select a valid lease tax-deduction basis."
            )

        deduction_percent = self._money2(
            payload.get("tax_deduction_percent", 100)
        )

        if deduction_percent < 0 or deduction_percent > 100:
            raise ValueError(
                "Tax deduction percentage must be between 0 and 100."
            )

        rou_override = payload.get(
            "rou_tax_base_override"
        )
        liability_override = payload.get(
            "liability_tax_base_override"
        )

        if basis == "manual":
            if rou_override in (None, ""):
                raise ValueError(
                    "ROU asset tax base is required "
                    "for manual treatment."
                )

            if liability_override in (None, ""):
                raise ValueError(
                    "Lease liability tax base is required "
                    "for manual treatment."
                )

        with self._conn_cursor() as (conn, cur):
            lease = self.fetch_one(f"""
                SELECT id
                FROM {schema}.leases
                WHERE company_id = %s
                AND id = %s
                LIMIT 1
            """, (
                company_id,
                lease_id,
            ), cur=cur)

            if not lease:
                raise ValueError("Lease not found.")

            cur.execute(f"""
                INSERT INTO {schema}.lease_tax_treatment_rules (
                    company_id,
                    lease_id,
                    tax_deduction_basis,
                    tax_deduction_percent,
                    rou_tax_base_override,
                    liability_tax_base_override,
                    tax_treatment_notes,
                    review_status,
                    reviewed_by_user_id,
                    reviewed_at,
                    created_by_user_id,
                    updated_at
                )
                VALUES (
                    %s,%s,%s,%s,%s,%s,%s,
                    'reviewed',%s,NOW(),%s,NOW()
                )
                ON CONFLICT (company_id, lease_id)
                DO UPDATE SET
                    tax_deduction_basis =
                        EXCLUDED.tax_deduction_basis,
                    tax_deduction_percent =
                        EXCLUDED.tax_deduction_percent,
                    rou_tax_base_override =
                        EXCLUDED.rou_tax_base_override,
                    liability_tax_base_override =
                        EXCLUDED.liability_tax_base_override,
                    tax_treatment_notes =
                        EXCLUDED.tax_treatment_notes,
                    review_status = 'reviewed',
                    reviewed_by_user_id =
                        EXCLUDED.reviewed_by_user_id,
                    reviewed_at = NOW(),
                    updated_at = NOW()
                RETURNING *
            """, (
                company_id,
                lease_id,
                basis,
                deduction_percent,
                (
                    self._money2(rou_override)
                    if rou_override not in (None, "")
                    else None
                ),
                (
                    self._money2(liability_override)
                    if liability_override not in (None, "")
                    else None
                ),
                (
                    payload.get("lease_tax_treatment_notes")
                    or None
                ),
                user_id,
                user_id,
            ))

            row = dict(cur.fetchone())
            conn.commit()

        return row

    def get_deferred_tax_posting_accounts(self, company_id: int) -> dict:
        settings = self.get_company_account_settings(company_id) or {}
        schema = self.company_schema(company_id)

        rules = {
            "deferred_tax_asset": (
                ["deferred_tax_asset"],
                ["deferred tax asset"],
                ["asset", "assets"],
            ),
            "deferred_tax_liability": (
                ["deferred_tax_liability"],
                ["deferred tax liability", "deferred tax"],
                ["liability", "liabilities"],
            ),
            "deferred_tax_expense": (
                ["income_tax_expense_deferred", "deferred_tax_expense"],
                ["income tax expense - deferred", "deferred tax expense"],
                ["expense", "expenses"],
            ),
            "deferred_tax_income": (
                ["deferred_tax_income", "income_tax_benefit_deferred"],
                ["deferred tax income", "deferred tax benefit"],
                [],
            ),
            "deferred_tax_oci": (
                [
                    "deferred_tax_oci",
                    "deferred_tax_oci_reserve",
                ],
                [
                    "deferred tax oci",
                    "deferred tax on revaluation",
                    "deferred tax reserve",
                ],
                ["equity"],
            ),
            "deferred_tax_equity": (
                ["deferred_tax_equity", "equity_retained_earnings"],
                ["deferred tax equity", "retained earnings"],
                ["equity"],
            ),
        }

        with self._conn_cursor() as (_, cur):
            cur.execute(f"""
                SELECT code, name, section, role
                FROM {schema}.coa
                WHERE COALESCE(posting, TRUE) = TRUE
            """)
            coa = cur.fetchall()

        def find(roles, names, sections):
            for row in coa:
                role = str(row.get("role") or "").strip().lower()
                name = str(row.get("name") or "").strip().lower()
                section = str(row.get("section") or "").strip().lower()

                if role in roles or (
                    any(value in name for value in names)
                    and (not sections or section in sections)
                ):
                    return str(row["code"]).strip()

            return None

        accounts = {
            key: settings.get(key) or find(
                [value.lower() for value in roles],
                [value.lower() for value in names],
                [value.lower() for value in sections],
            )
            for key, (roles, names, sections) in rules.items()
        }

        accounts["deferred_tax_income"] = (
            accounts["deferred_tax_income"]
            or accounts["deferred_tax_expense"]
        )

        accounts["deferred_tax_oci"] = (
            accounts["deferred_tax_oci"]
            or accounts["deferred_tax_equity"]
        )

        return accounts
    
    def deferred_tax_list_lines(
        self,
        company_id: int,
        run_id: int,
    ) -> list[dict]:
        schema = self.company_schema(company_id)

        with self._conn_cursor(
            company_id,
            dict_rows=True,
        ) as (_, cur):
            cur.execute(
                f"""
                SELECT *
                FROM {schema}.deferred_tax_run_lines
                WHERE company_id = %s
                AND run_id = %s
                ORDER BY id
                """,
                (
                    int(company_id),
                    int(run_id),
                ),
            )

            rows = cur.fetchall() or []

        result = []

        for row in rows:
            line = dict(row)

            line["recognition_destination"] = (
                str(
                    line.get("recognition_destination")
                    or "profit_or_loss"
                )
                .strip()
                .lower()
            )

            line["deferred_tax_type"] = (
                str(
                    line.get("deferred_tax_type")
                    or line.get("tax_type")
                    or line.get("balance_type")
                    or ""
                )
                .strip()
                .lower()
            )

            result.append(line)

        return result

    def preview_deferred_tax_posting(
        self,
        *,
        company_id: int,
        run_id: int,
        posting_date=None,
        reference: str | None = None,
        description: str | None = None,
        user_id: int | None = None,
    ) -> dict:
        from datetime import date
        from decimal import Decimal, ROUND_HALF_UP

        ZERO = Decimal("0.00")

        def money(value) -> Decimal:
            return Decimal(str(value or 0)).quantize(
                Decimal("0.01"),
                rounding=ROUND_HALF_UP,
            )

        def account_name(code: str) -> str:
            row = self.get_account_row_for_posting(
                company_id,
                code,
            )
            return str(row[0] if row else code)

        def add_line(
            code: str,
            amount: Decimal,
            *,
            debit: bool,
            memo: str,
        ) -> None:
            amount = money(abs(amount))

            if amount == ZERO:
                return

            journal_lines.append({
                "account_code": code,
                "account_name": account_name(code),
                "debit": float(amount) if debit else 0.0,
                "credit": 0.0 if debit else float(amount),
                "memo": memo,
            })

        run = self.deferred_tax_get_run(
            company_id,
            run_id,
        )

        if not run:
            raise ValueError("Deferred tax run not found")

        if run.get("status") not in (
            "reviewed",
            "approved",
        ):
            raise ValueError(
                "Deferred tax run must be reviewed or approved "
                "before preview"
            )

        post_date = (
            posting_date
            or run.get("reporting_date")
        )

        if isinstance(post_date, str):
            post_date = date.fromisoformat(
                post_date[:10]
            )

        accounts = self.get_deferred_tax_posting_accounts(
            company_id
        )

        def resolve(value, label: str) -> str:
            value = str(value or "").strip()

            if not value:
                raise ValueError(
                    f"Missing {label} account"
                )

            row = self.get_account_row_for_posting(
                company_id,
                value,
            )

            if not row:
                raise ValueError(
                    f"{label} account '{value}' not found in COA"
                )

            return str(row[1] or value).strip()

        dta_code = resolve(
            accounts.get("deferred_tax_asset"),
            "Deferred tax asset",
        )

        dtl_code = resolve(
            accounts.get("deferred_tax_liability"),
            "Deferred tax liability",
        )

        tax_expense_code = resolve(
            accounts.get("deferred_tax_expense"),
            "Deferred tax expense",
        )

        tax_income_code = resolve(
            accounts.get("deferred_tax_income")
            or accounts.get("deferred_tax_expense"),
            "Deferred tax income",
        )

        oci_code = None

        if accounts.get("deferred_tax_oci"):
            oci_code = resolve(
                accounts.get("deferred_tax_oci"),
                "Deferred tax OCI",
            )

        equity_code = None

        if accounts.get("deferred_tax_equity"):
            equity_code = resolve(
                accounts.get("deferred_tax_equity"),
                "Deferred tax equity",
            )

        lines_data = (
            run.get("lines")
            or self.deferred_tax_list_lines(
                company_id,
                run_id,
            )
            or []
        )

        recognized_dta = money(
            run.get("recognized_dta")
        )

        recognized_dtl = money(
            run.get("recognized_dtl")
        )

        net_movement = money(
            recognized_dtl - recognized_dta
        )

        destination_totals = {
            "profit_or_loss": ZERO,
            "oci": ZERO,
            "equity": ZERO,
            "business_combination": ZERO,
        }

        for line in lines_data:
            amount = money(
                line.get("recognized_amount")
                or line.get("deferred_tax_amount")
            )

            if amount == ZERO:
                continue

            destination = str(
                line.get("recognition_destination")
                or "profit_or_loss"
            ).strip().lower()

            if destination not in destination_totals:
                destination = "profit_or_loss"

            tax_type = str(
                line.get("deferred_tax_type")
                or line.get("tax_type")
                or line.get("balance_type")
                or ""
            ).strip().lower()

            dta_amount = money(
                line.get("recognized_dta")
                or line.get("dta_amount")
            )

            dtl_amount = money(
                line.get("recognized_dtl")
                or line.get("dtl_amount")
            )

            if dtl_amount != ZERO or dta_amount != ZERO:
                signed_amount = money(
                    dtl_amount - dta_amount
                )

            elif tax_type in (
                "asset",
                "dta",
                "deferred_tax_asset",
                "deductible",
            ):
                signed_amount = -abs(amount)

            elif tax_type in (
                "liability",
                "dtl",
                "deferred_tax_liability",
                "taxable",
            ):
                signed_amount = abs(amount)

            else:
                temporary_difference = money(
                    line.get("temporary_difference")
                    or line.get("difference")
                )

                if temporary_difference < ZERO:
                    signed_amount = -abs(amount)
                else:
                    signed_amount = abs(amount)

            destination_totals[destination] = money(
                destination_totals[destination]
                + signed_amount
            )

        allocated_total = money(
            sum(destination_totals.values(), ZERO)
        )

        difference = money(
            net_movement - allocated_total
        )

        if difference != ZERO:
            destination_totals["profit_or_loss"] = money(
                destination_totals["profit_or_loss"]
                + difference
            )

        journal_lines = []

        base_memo = (
            str(description or "").strip()
            or f"Deferred tax adjustment – Run {run_id}"
        )

        # Balance-sheet side
        if recognized_dta > ZERO:
            add_line(
                dta_code,
                recognized_dta,
                debit=True,
                memo="Deferred tax asset recognised",
            )

        if recognized_dtl > ZERO:
            add_line(
                dtl_code,
                recognized_dtl,
                debit=False,
                memo="Deferred tax liability recognised",
            )

        # Offset side:
        # Positive = net DTL increase -> debit expense/OCI/equity.
        # Negative = net DTA increase -> credit benefit/OCI/equity.
        pnl_amount = destination_totals[
            "profit_or_loss"
        ]

        if pnl_amount > ZERO:
            add_line(
                tax_expense_code,
                pnl_amount,
                debit=True,
                memo=f"{base_memo} [tax expense]",
            )

        elif pnl_amount < ZERO:
            add_line(
                tax_income_code,
                pnl_amount,
                debit=False,
                memo=f"{base_memo} [tax income]",
            )

        oci_amount = destination_totals["oci"]

        if oci_amount != ZERO:
            if not oci_code:
                raise ValueError(
                    "Deferred tax OCI account is not configured"
                )

            add_line(
                oci_code,
                oci_amount,
                debit=oci_amount > ZERO,
                memo=f"{base_memo} [OCI]",
            )

        equity_amount = destination_totals["equity"]

        if equity_amount != ZERO:
            if not equity_code:
                raise ValueError(
                    "Deferred tax equity account is not configured"
                )

            add_line(
                equity_code,
                equity_amount,
                debit=equity_amount > ZERO,
                memo=f"{base_memo} [equity]",
            )

        business_combination_amount = destination_totals[
            "business_combination"
        ]

        if business_combination_amount != ZERO:
            raise ValueError(
                "Deferred tax relating to a business combination "
                "requires a dedicated acquisition account"
            )

        debit_total = money(sum(
            (
                Decimal(str(line.get("debit") or 0))
                for line in journal_lines
            ),
            ZERO,
        ))

        credit_total = money(sum(
            (
                Decimal(str(line.get("credit") or 0))
                for line in journal_lines
            ),
            ZERO,
        ))

        if debit_total != credit_total:
            raise ValueError(
                "Deferred tax journal does not balance: "
                f"debits {debit_total}, "
                f"credits {credit_total}, "
                f"difference {money(debit_total - credit_total)}"
            )

        ref = (
            str(reference or "").strip()
            or f"DT-PREVIEW-{run_id}"
        )

        return {
            "company_id": int(company_id),
            "run_id": int(run_id),
            "reporting_date": str(
                run.get("reporting_date")
            )[:10],
            "posting_date": post_date.isoformat(),
            "status": run.get("status"),
            "tax_rate": str(
                run.get("tax_rate") or 0
            ),
            "requested_by_user_id": (
                int(user_id)
                if user_id is not None
                else None
            ),
            "summary": {
                "recognized_dta": str(recognized_dta),
                "recognized_dtl": str(recognized_dtl),
                "net_movement": str(net_movement),
                "profit_or_loss": str(pnl_amount),
                "oci": str(oci_amount),
                "equity": str(equity_amount),
                "business_combination": str(
                    business_combination_amount
                ),
            },
            "preview_journal": {
                "date": post_date.isoformat(),
                "ref": ref,
                "description": base_memo,
                "source": "deferred_tax_preview",
                "source_id": None,
            },
            "preview_journal_lines": journal_lines,
            "totals": {
                "debit": str(debit_total),
                "credit": str(credit_total),
            },
        }

    def _asset_tax_decimal(self, value, field_name="Value", allow_none=True):
        if value in (None, ""):
            return None if allow_none else Decimal("0")

        try:
            return Decimal(str(value))
        except (TypeError, ValueError):
            raise ValueError(f"{field_name} must be a valid number.")


    def _asset_tax_date(self, value, field_name="Date", allow_none=True):
        if value in (None, ""):
            if allow_none:
                return None
            raise ValueError(f"{field_name} is required.")

        if isinstance(value, date):
            return value

        try:
            return date.fromisoformat(str(value)[:10])
        except (TypeError, ValueError):
            raise ValueError(f"{field_name} must be a valid date.")


    def _normalize_asset_tax_method(self, value):
        method = str(value or "WDV").strip().upper()

        if method not in {"WDV", "SL", "IMMEDIATE", "CUSTOM"}:
            raise ValueError(
                "Capital allowance method must be WDV, SL, IMMEDIATE or CUSTOM."
            )

        return method


    def _asset_tax_text(self, value):
        value = str(value or "").strip()
        return value or None


    def _asset_tax_rule_payload(self, payload, current=None):
        current = current or {}

        def pick(key, default=None):
            return payload[key] if key in payload else current.get(key, default)

        effective_from = self._asset_tax_date(
            pick("effective_from", date.today()),
            "Effective from",
            False,
        )
        effective_to = self._asset_tax_date(
            pick("effective_to"),
            "Effective to",
        )

        if effective_to and effective_to < effective_from:
            raise ValueError(
                "Effective-to date cannot be before effective-from date."
            )

        rule_code = str(pick("rule_code") or "").strip().upper()
        rule_name = str(pick("rule_name") or "").strip()

        if not rule_code:
            raise ValueError("Rule code is required.")

        if not rule_name:
            raise ValueError("Rule name is required.")

        return {
            "rule_code": rule_code,
            "rule_name": rule_name,
            "asset_category_hint": self._asset_tax_text(
                pick("asset_category_hint")
            ),
            "method": self._normalize_asset_tax_method(pick("method")),
            "rate_percent": self._asset_tax_decimal(
                pick("rate_percent"),
                "Rate",
            ),
            "useful_life_years": self._asset_tax_decimal(
                pick("useful_life_years"),
                "Useful life",
            ),
            "initial_allowance_percent": self._asset_tax_decimal(
                pick("initial_allowance_percent"),
                "Initial allowance percentage",
            ),
            "annual_allowance_percent": self._asset_tax_decimal(
                pick("annual_allowance_percent"),
                "Annual allowance percentage",
            ),
            "effective_from": effective_from,
            "effective_to": effective_to,
            "notes": self._asset_tax_text(pick("notes")),
            "is_active": bool(pick("is_active", True)),
        }


    def _asset_tax_company_rule_save(
        self,
        company_id,
        values,
        *,
        rule_id=None,
        tax_authority_id=None,
        default_rule_id=None,
        override_type="custom",
        user_id=None,
    ):
        schema = self.company_schema(company_id)

        params = (
            tax_authority_id,
            default_rule_id,
            values["rule_code"],
            values["rule_name"],
            values["asset_category_hint"],
            values["method"],
            values["rate_percent"],
            values["useful_life_years"],
            values["initial_allowance_percent"],
            values["annual_allowance_percent"],
            values["effective_from"],
            values["effective_to"],
            override_type,
            values["notes"],
            values["is_active"],
            user_id,
        )

        if rule_id:
            return self.fetch_one(f"""
                UPDATE {schema}.asset_tax_rule_overrides
                SET tax_authority_id=%s,
                    default_rule_id=%s,
                    rule_code=%s,
                    rule_name=%s,
                    asset_category_hint=%s,
                    method=%s,
                    rate_percent=%s,
                    useful_life_years=%s,
                    initial_allowance_percent=%s,
                    annual_allowance_percent=%s,
                    effective_from=%s,
                    effective_to=%s,
                    override_type=%s,
                    notes=%s,
                    is_active=%s,
                    is_deleted=FALSE,
                    updated_by_user_id=%s,
                    updated_at=NOW()
                WHERE company_id=%s
                AND id=%s
                RETURNING *;
            """, params + (company_id, rule_id))

        return self.fetch_one(f"""
            INSERT INTO {schema}.asset_tax_rule_overrides (
                company_id,
                tax_authority_id,
                default_rule_id,
                rule_code,
                rule_name,
                asset_category_hint,
                method,
                rate_percent,
                useful_life_years,
                initial_allowance_percent,
                annual_allowance_percent,
                effective_from,
                effective_to,
                override_type,
                notes,
                is_active,
                is_deleted,
                created_by_user_id,
                updated_by_user_id
            )
            VALUES (
                %s,%s,%s,%s,%s,%s,%s,%s,%s,%s,
                %s,%s,%s,%s,%s,%s,FALSE,%s,%s
            )
            RETURNING *;
        """, (
            company_id,
            tax_authority_id,
            default_rule_id,
            values["rule_code"],
            values["rule_name"],
            values["asset_category_hint"],
            values["method"],
            values["rate_percent"],
            values["useful_life_years"],
            values["initial_allowance_percent"],
            values["annual_allowance_percent"],
            values["effective_from"],
            values["effective_to"],
            override_type,
            values["notes"],
            values["is_active"],
            user_id,
            user_id,
        ))

    def asset_tax_rules_list(
        self,
        company_id,
        *,
        tax_authority_id=None,
        active_only=False,
        as_at=None,
    ):
        schema = self.company_schema(company_id)
        settings = self.deferred_tax_get_settings(company_id) or {}
        authority_id = tax_authority_id or settings.get("tax_authority_id")

        if not authority_id:
            return []

        as_at = self._asset_tax_date(
            as_at or date.today(),
            "Rule date",
            False,
        )

        rows = self.fetch_all(f"""
            WITH defaults AS (
                SELECT
                    r.id::BIGINT AS rule_id,
                    r.id AS default_rule_id,
                    NULL::BIGINT AS override_rule_id,
                    r.tax_authority_id,
                    ta.code AS tax_authority_code,
                    ta.name AS tax_authority_name,
                    r.rule_code,
                    r.rule_name,
                    r.asset_category_hint,
                    r.method,
                    r.rate_percent,
                    r.useful_life_years,
                    r.initial_allowance_percent,
                    r.annual_allowance_percent,
                    r.effective_from,
                    r.effective_to,
                    r.notes,
                    r.is_active,
                    'default'::TEXT AS rule_source,
                    FALSE AS is_company_rule,
                    FALSE AS is_override,
                    FALSE AS is_disabled_for_company,
                    NULL::TEXT AS override_type,
                    NULL::TIMESTAMPTZ AS updated_at
                FROM public.tax_allowance_rules r
                JOIN public.tax_authorities ta
                ON ta.id=r.tax_authority_id
                WHERE r.tax_authority_id=%s
                AND r.effective_from<=%s
                AND (r.effective_to IS NULL OR r.effective_to>=%s)
            ),
            company_rules AS (
                SELECT
                    o.id AS rule_id,
                    o.default_rule_id,
                    o.id AS override_rule_id,
                    o.tax_authority_id,
                    ta.code AS tax_authority_code,
                    ta.name AS tax_authority_name,
                    o.rule_code,
                    o.rule_name,
                    o.asset_category_hint,
                    o.method,
                    o.rate_percent,
                    o.useful_life_years,
                    o.initial_allowance_percent,
                    o.annual_allowance_percent,
                    o.effective_from,
                    o.effective_to,
                    o.notes,
                    o.is_active,
                    CASE
                        WHEN o.override_type='custom' THEN 'custom'
                        WHEN o.override_type='override' THEN 'override'
                        ELSE 'disabled_default'
                    END AS rule_source,
                    TRUE AS is_company_rule,
                    o.override_type='override' AS is_override,
                    o.override_type='disabled_default' AS is_disabled_for_company,
                    o.override_type,
                    o.updated_at
                FROM {schema}.asset_tax_rule_overrides o
                JOIN public.tax_authorities ta
                ON ta.id=o.tax_authority_id
                WHERE o.company_id=%s
                AND o.tax_authority_id=%s
                AND o.is_deleted=FALSE
                AND o.effective_from<=%s
                AND (o.effective_to IS NULL OR o.effective_to>=%s)
            )
            SELECT *
            FROM defaults d
            WHERE NOT EXISTS (
                SELECT 1
                FROM company_rules c
                WHERE c.default_rule_id=d.default_rule_id
                AND c.override_type IN ('override','disabled_default')
            )

            UNION ALL

            SELECT * FROM company_rules

            ORDER BY is_disabled_for_company, rule_name, effective_from DESC;
        """, (
            authority_id,
            as_at,
            as_at,
            company_id,
            authority_id,
            as_at,
            as_at,
        )) or []

        if active_only:
            rows = [
                row for row in rows
                if row.get("is_active")
                and not row.get("is_disabled_for_company")
            ]

        for row in rows:
            source = row.get("rule_source")
            row["can_edit"] = source in {"override", "custom"}
            row["can_delete"] = bool(row.get("is_company_rule"))
            row["can_override"] = source == "default"

        return rows


    def asset_tax_company_rule_get(self, company_id, rule_id):
        schema = self.company_schema(company_id)

        return self.fetch_one(f"""
            SELECT
                o.*,
                ta.code AS tax_authority_code,
                ta.name AS tax_authority_name,
                d.rule_code AS default_rule_code,
                d.rule_name AS default_rule_name
            FROM {schema}.asset_tax_rule_overrides o
            JOIN public.tax_authorities ta
            ON ta.id=o.tax_authority_id
            LEFT JOIN public.tax_allowance_rules d
            ON d.id=o.default_rule_id
            WHERE o.company_id=%s
            AND o.id=%s
            AND o.is_deleted=FALSE
            LIMIT 1;
        """, (company_id, rule_id))


    def asset_tax_company_rule_create(
        self,
        company_id,
        payload,
        *,
        user_id=None,
    ):
        settings = self.deferred_tax_get_settings(company_id) or {}
        authority_id = payload.get("tax_authority_id") or settings.get(
            "tax_authority_id"
        )

        if not authority_id:
            raise ValueError("A tax authority is required.")

        values = self._asset_tax_rule_payload(payload)

        return self._asset_tax_company_rule_save(
            company_id,
            values,
            tax_authority_id=authority_id,
            override_type="custom",
            user_id=user_id,
        )


    def asset_tax_company_rule_update(
        self,
        company_id,
        rule_id,
        payload,
        *,
        user_id=None,
    ):
        current = self.asset_tax_company_rule_get(company_id, rule_id)

        if not current:
            raise ValueError("Company capital allowance rule not found.")

        if current.get("override_type") == "disabled_default":
            raise ValueError(
                "A disabled default cannot be edited. Restore or override it first."
            )

        values = self._asset_tax_rule_payload(payload, current)

        return self._asset_tax_company_rule_save(
            company_id,
            values,
            rule_id=rule_id,
            tax_authority_id=current["tax_authority_id"],
            default_rule_id=current.get("default_rule_id"),
            override_type=current["override_type"],
            user_id=user_id,
        )


    def asset_tax_company_rule_delete(
        self,
        company_id,
        rule_id,
        *,
        user_id=None,
    ):
        schema = self.company_schema(company_id)
        current = self.asset_tax_company_rule_get(company_id, rule_id)

        if not current:
            raise ValueError("Company capital allowance rule not found.")

        used = self.fetch_one(f"""
            SELECT EXISTS (
                SELECT 1
                FROM {schema}.asset_tax_profiles
                WHERE company_id=%s
                AND override_rule_id=%s
            ) AS used;
        """, (company_id, rule_id))

        if used and used.get("used"):
            raise ValueError(
                "This rule is assigned to asset tax profiles. Reassign them first."
            )

        return self.fetch_one(f"""
            UPDATE {schema}.asset_tax_rule_overrides
            SET is_active=FALSE,
                is_deleted=TRUE,
                updated_by_user_id=%s,
                updated_at=NOW()
            WHERE company_id=%s
            AND id=%s
            RETURNING *;
        """, (user_id, company_id, rule_id))

    def asset_tax_default_rule_override(
        self,
        company_id,
        default_rule_id,
        payload,
        *,
        user_id=None,
    ):
        schema = self.company_schema(company_id)

        default_rule = self.fetch_one("""
            SELECT *
            FROM public.tax_allowance_rules
            WHERE id=%s
            LIMIT 1;
        """, (default_rule_id,))

        if not default_rule:
            raise ValueError("Default capital allowance rule not found.")

        values = self._asset_tax_rule_payload(payload, default_rule)

        existing = self.fetch_one(f"""
            SELECT id
            FROM {schema}.asset_tax_rule_overrides
            WHERE company_id=%s
            AND default_rule_id=%s
            AND is_deleted=FALSE
            ORDER BY id DESC
            LIMIT 1;
        """, (company_id, default_rule_id))

        return self._asset_tax_company_rule_save(
            company_id,
            values,
            rule_id=existing["id"] if existing else None,
            tax_authority_id=default_rule["tax_authority_id"],
            default_rule_id=default_rule_id,
            override_type="override",
            user_id=user_id,
        )


    def asset_tax_default_rule_disable(
        self,
        company_id,
        default_rule_id,
        *,
        user_id=None,
    ):
        schema = self.company_schema(company_id)

        default_rule = self.fetch_one("""
            SELECT *
            FROM public.tax_allowance_rules
            WHERE id=%s
            LIMIT 1;
        """, (default_rule_id,))

        if not default_rule:
            raise ValueError("Default capital allowance rule not found.")

        existing = self.fetch_one(f"""
            SELECT id
            FROM {schema}.asset_tax_rule_overrides
            WHERE company_id=%s
            AND default_rule_id=%s
            AND is_deleted=FALSE
            ORDER BY id DESC
            LIMIT 1;
        """, (company_id, default_rule_id))

        values = self._asset_tax_rule_payload(
            {
                **default_rule,
                "effective_from": date.today(),
                "effective_to": None,
                "notes": "Disabled for this company.",
                "is_active": False,
            }
        )

        return self._asset_tax_company_rule_save(
            company_id,
            values,
            rule_id=existing["id"] if existing else None,
            tax_authority_id=default_rule["tax_authority_id"],
            default_rule_id=default_rule_id,
            override_type="disabled_default",
            user_id=user_id,
        )

    def asset_tax_profiles_list(
        self,
        company_id,
        *,
        tax_authority_id=None,
        active_only=False,
    ):
        schema = self.company_schema(company_id)
        where = ["p.company_id=%s"]
        params = [company_id]

        if tax_authority_id:
            where.append("p.tax_authority_id=%s")
            params.append(tax_authority_id)

        if active_only:
            where.append("p.is_active=TRUE")

        return self.fetch_all(f"""
            SELECT
                p.*,
                a.asset_code,
                a.name AS asset_name,
                a.category AS asset_category,
                a.asset_class,
                ta.code AS tax_authority_code,
                ta.name AS tax_authority_name,
                COALESCE(o.rule_code,d.rule_code) AS rule_code,
                COALESCE(o.rule_name,d.rule_name) AS rule_name,
                COALESCE(o.method,d.method) AS rule_method,
                COALESCE(o.rate_percent,d.rate_percent) AS rule_rate_percent,
                CASE
                    WHEN p.override_rule_id IS NOT NULL
                        THEN COALESCE(p.rule_source,o.override_type,'override')
                    WHEN p.default_rule_id IS NOT NULL
                        THEN 'default'
                    ELSE COALESCE(p.rule_source,'manual')
                END AS effective_rule_source
            FROM {schema}.asset_tax_profiles p
            JOIN {schema}.assets a
            ON a.id=p.asset_id
            AND a.company_id=p.company_id
            LEFT JOIN public.tax_authorities ta
            ON ta.id=p.tax_authority_id
            LEFT JOIN public.tax_allowance_rules d
            ON d.id=p.default_rule_id
            LEFT JOIN {schema}.asset_tax_rule_overrides o
            ON o.id=p.override_rule_id
            AND o.company_id=p.company_id
            AND o.is_deleted=FALSE
            WHERE {" AND ".join(where)}
            ORDER BY a.asset_code,a.name,p.id;
        """, tuple(params)) or []


    def asset_tax_profile_update_rule(
        self,
        company_id,
        profile_id,
        payload,
        *,
        user_id=None,
    ):
        schema = self.company_schema(company_id)

        current = self.fetch_one(f"""
            SELECT *
            FROM {schema}.asset_tax_profiles
            WHERE company_id=%s
            AND id=%s
            LIMIT 1;
        """, (company_id, profile_id))

        if not current:
            raise ValueError("Asset tax profile not found.")

        source = str(
            payload.get("rule_source", current.get("rule_source") or "default")
        ).strip().lower()

        if source not in {"default", "override", "custom", "manual"}:
            raise ValueError("Invalid capital allowance rule source.")

        default_rule_id = payload.get("default_rule_id")
        override_rule_id = payload.get("override_rule_id")
        authority_id = payload.get("tax_authority_id") or current.get(
            "tax_authority_id"
        )

        if source == "default":
            rule = self.fetch_one("""
                SELECT id,tax_authority_id
                FROM public.tax_allowance_rules
                WHERE id=%s
                AND is_active=TRUE
                LIMIT 1;
            """, (default_rule_id,))

            if not rule:
                raise ValueError("Selected default allowance rule was not found.")

            authority_id = rule["tax_authority_id"]
            override_rule_id = None

        elif source in {"override", "custom"}:
            rule = self.fetch_one(f"""
                SELECT id,tax_authority_id,default_rule_id,override_type
                FROM {schema}.asset_tax_rule_overrides
                WHERE company_id=%s
                AND id=%s
                AND is_active=TRUE
                AND is_deleted=FALSE
                LIMIT 1;
            """, (company_id, override_rule_id))

            if not rule:
                raise ValueError("Selected company allowance rule was not found.")

            authority_id = rule["tax_authority_id"]
            default_rule_id = rule.get("default_rule_id")

        else:
            default_rule_id = None
            override_rule_id = None

        tax_cost = self._asset_tax_decimal(
            payload.get("tax_cost", current.get("tax_cost")),
            "Tax cost",
        )
        qualifying = self._asset_tax_decimal(
            payload.get("qualifying_percent", current.get("qualifying_percent", 100)),
            "Qualifying percentage",
            False,
        )
        private_use = self._asset_tax_decimal(
            payload.get("private_use_percent", current.get("private_use_percent", 0)),
            "Private-use percentage",
            False,
        )

        if not Decimal("0") <= qualifying <= Decimal("100"):
            raise ValueError("Qualifying percentage must be between 0 and 100.")

        if not Decimal("0") <= private_use <= Decimal("100"):
            raise ValueError("Private-use percentage must be between 0 and 100.")

        return self.fetch_one(f"""
            UPDATE {schema}.asset_tax_profiles
            SET tax_authority_id=%s,
                default_rule_id=%s,
                override_rule_id=%s,
                rule_source=%s,
                tax_cost=%s,
                tax_start_date=%s,
                qualifying_percent=%s,
                private_use_percent=%s,
                is_tax_depreciable=%s,
                is_active=%s,
                notes=%s,
                updated_by_user_id=%s,
                updated_at=NOW()
            WHERE company_id=%s
            AND id=%s
            RETURNING *;
        """, (
            authority_id,
            default_rule_id,
            override_rule_id,
            source,
            tax_cost,
            self._asset_tax_date(
                payload.get("tax_start_date", current.get("tax_start_date")),
                "Tax start date",
            ),
            qualifying,
            private_use,
            bool(payload.get(
                "is_tax_depreciable",
                current.get("is_tax_depreciable"),
            )),
            bool(payload.get("is_active", current.get("is_active"))),
            self._asset_tax_text(payload.get("notes", current.get("notes"))),
            user_id,
            company_id,
            profile_id,
        ))

    def _asset_tax_rule_select(self, table_alias="r", source="'default'"):
        return f"""
            {table_alias}.id AS rule_id,
            {table_alias}.default_rule_id,
            {table_alias}.override_rule_id,
            {table_alias}.tax_authority_id,
            {table_alias}.rule_code,
            {table_alias}.rule_name,
            {table_alias}.asset_category_hint,
            {table_alias}.method,
            {table_alias}.rate_percent,
            {table_alias}.useful_life_years,
            {table_alias}.initial_allowance_percent,
            {table_alias}.annual_allowance_percent,
            {table_alias}.effective_from,
            {table_alias}.effective_to,
            {table_alias}.notes,
            {source}::TEXT AS rule_source
        """


    def resolve_asset_tax_rule(
        self,
        company_id,
        *,
        profile,
        asset,
        tax_authority_id,
        as_at,
        cur=None,
    ):
        schema = self.company_schema(company_id)
        as_at = self._asset_tax_date(as_at, "Calculation date", False)
        override_id = profile.get("override_rule_id")
        default_id = profile.get("default_rule_id") or profile.get(
            "allowance_rule_id"
        )

        def one(query, params):
            return self.fetch_one(query, params, cur=cur)

        if override_id:
            rule = one(f"""
                SELECT
                    o.id AS rule_id,
                    o.default_rule_id,
                    o.id AS override_rule_id,
                    o.tax_authority_id,
                    o.rule_code,
                    o.rule_name,
                    o.asset_category_hint,
                    o.method,
                    o.rate_percent,
                    o.useful_life_years,
                    o.initial_allowance_percent,
                    o.annual_allowance_percent,
                    o.effective_from,
                    o.effective_to,
                    o.notes,
                    o.override_type AS rule_source
                FROM {schema}.asset_tax_rule_overrides o
                WHERE o.company_id=%s
                AND o.id=%s
                AND o.tax_authority_id=%s
                AND o.override_type IN ('override','custom')
                AND o.is_active=TRUE
                AND o.is_deleted=FALSE
                AND o.effective_from<=%s
                AND (o.effective_to IS NULL OR o.effective_to>=%s)
                LIMIT 1;
            """, (company_id, override_id, tax_authority_id, as_at, as_at))

            if rule:
                return rule

        if default_id:
            company_rule = one(f"""
                SELECT
                    o.id AS rule_id,
                    o.default_rule_id,
                    o.id AS override_rule_id,
                    o.tax_authority_id,
                    o.rule_code,
                    o.rule_name,
                    o.asset_category_hint,
                    o.method,
                    o.rate_percent,
                    o.useful_life_years,
                    o.initial_allowance_percent,
                    o.annual_allowance_percent,
                    o.effective_from,
                    o.effective_to,
                    o.notes,
                    o.override_type AS rule_source
                FROM {schema}.asset_tax_rule_overrides o
                WHERE o.company_id=%s
                AND o.default_rule_id=%s
                AND o.tax_authority_id=%s
                AND o.is_deleted=FALSE
                ORDER BY o.effective_from DESC,o.id DESC
                LIMIT 1;
            """, (company_id, default_id, tax_authority_id))

            if company_rule:
                if company_rule["rule_source"] == "disabled_default":
                    return None
                if company_rule.get("is_active", True):
                    return company_rule

            rule = one("""
                SELECT
                    r.id AS rule_id,
                    r.id AS default_rule_id,
                    NULL::BIGINT AS override_rule_id,
                    r.tax_authority_id,
                    r.rule_code,
                    r.rule_name,
                    r.asset_category_hint,
                    r.method,
                    r.rate_percent,
                    r.useful_life_years,
                    r.initial_allowance_percent,
                    r.annual_allowance_percent,
                    r.effective_from,
                    r.effective_to,
                    r.notes,
                    'default'::TEXT AS rule_source
                FROM public.tax_allowance_rules r
                WHERE r.id=%s
                AND r.tax_authority_id=%s
                AND r.is_active=TRUE
                AND r.effective_from<=%s
                AND (r.effective_to IS NULL OR r.effective_to>=%s)
                LIMIT 1;
            """, (default_id, tax_authority_id, as_at, as_at))

            if rule:
                return rule

        category = " ".join(
            str(asset.get(key) or "").strip()
            for key in (
                "asset_class",
                "category",
                "asset_category",
                "asset_class_group",
                "component_type",
            )
        ).lower()

        if not category:
            return None

        rules = self.asset_tax_rules_list(
            company_id,
            tax_authority_id=tax_authority_id,
            active_only=True,
            as_at=as_at,
        )

        for rule in rules:
            hint = str(rule.get("asset_category_hint") or "").strip().lower()
            if hint and hint in category:
                return rule

        return None


    def asset_tax_rule_snapshot(self, rule):
        if not rule:
            return {}

        keys = (
            "rule_id",
            "default_rule_id",
            "override_rule_id",
            "rule_source",
            "tax_authority_id",
            "rule_code",
            "rule_name",
            "asset_category_hint",
            "method",
            "rate_percent",
            "useful_life_years",
            "initial_allowance_percent",
            "annual_allowance_percent",
            "effective_from",
            "effective_to",
        )

        return {key: rule.get(key) for key in keys}

    def _asset_tax_rule_values(self, rule):
        if not rule:
            return {
                "method": "CUSTOM",
                "rate_percent": Decimal("0"),
                "initial_percent": Decimal("0"),
                "annual_percent": Decimal("0"),
                "useful_life_years": None,
                "requires_review": True,
            }

        return {
            "method": str(rule.get("method") or "WDV").upper(),
            "rate_percent": Decimal(str(
                rule.get("rate_percent")
                or rule.get("annual_allowance_percent")
                or 0
            )),
            "initial_percent": Decimal(str(
                rule.get("initial_allowance_percent") or 0
            )),
            "annual_percent": Decimal(str(
                rule.get("annual_allowance_percent")
                or rule.get("rate_percent")
                or 0
            )),
            "useful_life_years": (
                Decimal(str(rule["useful_life_years"]))
                if rule.get("useful_life_years") not in (None, "")
                else None
            ),
            "requires_review": False,
        }


    def _asset_tax_calculate_allowance(
        self,
        *,
        opening_tax_wdv,
        additions,
        rule,
    ):
        zero = Decimal("0")
        hundred = Decimal("100")
        values = self._asset_tax_rule_values(rule)

        opening_tax_wdv = Decimal(str(opening_tax_wdv or 0))
        additions = Decimal(str(additions or 0))
        available = opening_tax_wdv + additions

        initial = zero
        annual = zero
        method = values["method"]

        if not rule:
            notes = "No active allowance rule was resolved. Review required."
        elif method == "IMMEDIATE":
            annual = available
            notes = f"Immediate write-off using {rule['rule_source']} rule."
        elif method == "SL":
            life = values["useful_life_years"]
            annual = (
                available / life
                if life and life > zero
                else available * values["annual_percent"] / hundred
            )
            notes = f"Straight-line allowance using {rule['rule_source']} rule."
        else:
            initial = additions * values["initial_percent"] / hundred
            annual = available * values["annual_percent"] / hundred
            notes = (
                f"Written-down-value allowance using {rule['rule_source']} rule."
                if method == "WDV"
                else "Custom allowance method. Review the calculated amount."
            )
            values["requires_review"] = method == "CUSTOM"

        total = min(initial + annual, available)
        closing = max(available - total, zero)

        return {
            **values,
            "opening_tax_wdv": opening_tax_wdv,
            "additions": additions,
            "available_base": available,
            "initial_allowance": initial,
            "annual_allowance": annual,
            "total_capital_allowance": total,
            "closing_tax_wdv": closing,
            "notes": notes,
        }

    def _migration_json(self, value, default=None):
        if value is None:
            value = default if default is not None else {}

        if isinstance(value, str):
            try:
                return json.loads(value)
            except Exception:
                return default if default is not None else {}

        return value


    def _migration_json_dump(self, value, default=None) -> str:
        if value is None:
            value = default if default is not None else {}

        return json.dumps(
            value,
            default=str,
            separators=(",", ":"),
        )


    def migration_next_reference(
        self,
        company_id: int,
        *,
        cur=None,
    ) -> str:
        company_id = int(company_id)
        schema = self.company_schema(company_id)
        year = date.today().year
        prefix = f"MIG-{year}-"

        sql = f"""
            SELECT COALESCE(
                MAX(
                    CASE
                        WHEN reference ~ %s
                        THEN NULLIF(
                            regexp_replace(reference, '^.*-', ''),
                            ''
                        )::INT
                        ELSE 0
                    END
                ),
                0
            ) + 1
            FROM {schema}.migration_projects
            WHERE company_id=%s
            AND reference LIKE %s
        """

        sequence = self.fetch_val(
            sql,
            (
                rf"^MIG-{year}-[0-9]+$",
                company_id,
                f"{prefix}%",
            ),
            cur=cur,
        )

        return f"{prefix}{int(sequence or 1):04d}"

    def _migration_project_validate(
        self,
        data: dict,
        *,
        existing: dict | None = None,
    ) -> dict:
        data = data or {}
        existing = existing or {}

        def pick(*keys, default=None):
            for key in keys:
                if key in data:
                    return data.get(key)

            for key in keys:
                if key in existing:
                    return existing.get(key)

            return default

        name = str(
            pick(
                "name",
                default="",
            )
            or ""
        ).strip()

        description = str(
            pick(
                "description",
                default="",
            )
            or ""
        ).strip()

        financial_year_start = pick(
            "financial_year_start",
            "financialYearStart",
        )

        cutover_date = pick(
            "cutover_date",
            "cutoverDate",
        )

        default_currency = str(
            pick(
                "default_currency",
                "defaultCurrency",
                default="",
            )
            or ""
        ).strip().upper()

        source_system_code = str(
            pick(
                "source_system_code",
                "sourceSystemCode",
                default="",
            )
            or ""
        ).strip()

        source_system_name = str(
            pick(
                "source_system_name",
                "sourceSystem",
                default="",
            )
            or ""
        ).strip()

        source_format = str(
            pick(
                "source_format",
                "sourceFormat",
                default="",
            )
            or ""
        ).strip().lower()

        date_format = str(
            pick(
                "date_format",
                "dateFormat",
                default="",
            )
            or ""
        ).strip()

        missing = []

        if not name:
            missing.append("name")

        if not description:
            missing.append("description")

        if not financial_year_start:
            missing.append("financial_year_start")

        if not cutover_date:
            missing.append("cutover_date")

        if not default_currency:
            missing.append("default_currency")

        if not source_system_code:
            missing.append("source_system_code")

        if not source_system_name:
            missing.append("source_system_name")

        if not source_format:
            missing.append("source_format")

        if not date_format:
            missing.append("date_format")

        if missing:
            raise ValueError(
                "Missing required migration project fields: "
                + ", ".join(missing)
            )

        try:
            financial_year_start_value = (
                financial_year_start
                if isinstance(financial_year_start, date)
                else date.fromisoformat(
                    str(financial_year_start)[:10]
                )
            )
        except Exception:
            raise ValueError(
                "financial_year_start must be a valid ISO date."
            )

        try:
            cutover_date_value = (
                cutover_date
                if isinstance(cutover_date, date)
                else date.fromisoformat(
                    str(cutover_date)[:10]
                )
            )
        except Exception:
            raise ValueError(
                "cutover_date must be a valid ISO date."
            )

        if cutover_date_value < financial_year_start_value:
            raise ValueError(
                "Cutover date cannot be before the "
                "financial year start."
            )

        if len(default_currency) != 3:
            raise ValueError(
                "Default currency must be a three-letter code."
            )

        return {
            "name": name,
            "description": description,
            "financial_year_start":
                financial_year_start_value,
            "cutover_date": cutover_date_value,
            "default_currency":
                default_currency,
            "source_system_code":
                source_system_code,
            "source_system_name":
                source_system_name,
            "source_format":
                source_format,
            "date_format":
                date_format,
        }

    def migration_projects_list(
        self,
        company_id: int,
        *,
        status: str | None = None,
        search: str | None = None,
        limit: int = 200,
        cur=None,
    ) -> list[dict]:
        company_id = int(company_id)
        schema = self.company_schema(company_id)
        limit = max(1, min(int(limit or 200), 500))

        where = ["p.company_id=%s"]
        params: list = [company_id]

        status = str(status or "").strip().lower()
        if status:
            where.append("LOWER(COALESCE(p.status,''))=%s")
            params.append(status)

        search = str(search or "").strip()
        if search:
            where.append(
                """
                (
                    p.reference ILIKE %s
                    OR p.name ILIKE %s
                    OR COALESCE(p.description,'') ILIKE %s
                    OR COALESCE(p.source_system_name,'') ILIKE %s
                )
                """
            )
            pattern = f"%{search}%"
            params.extend([
                pattern,
                pattern,
                pattern,
                pattern,
            ])

        params.append(limit)

        sql = f"""
            SELECT
                p.id,
                p.company_id,
                p.reference,
                p.name,
                p.description,
                p.status,
                p.migration_mode,
                p.import_mode,
                p.financial_year_start,
                p.cutover_date,
                p.default_currency,
                p.source_timezone,
                p.source_country_code,
                p.source_tax_regime,
                p.source_system_code,
                p.source_system_name,
                p.source_system_version,
                p.source_format,
                p.date_format,
                p.decimal_separator,
                p.thousands_separator,
                p.debit_credit_convention,
                p.project_owner_user_id,
                p.started_at,
                p.completed_at,
                p.cancelled_at,
                p.created_at,
                p.updated_at,

                COALESCE(src.source_count, 0)::INT AS source_count,

                src.primary_source_id,
                src.primary_source_name,
                src.primary_source_format

            FROM {schema}.migration_projects p

            LEFT JOIN LATERAL (
                SELECT
                    COUNT(*) AS source_count,

                    MAX(s.id) FILTER (
                        WHERE s.is_primary=TRUE
                        AND s.is_active=TRUE
                    ) AS primary_source_id,

                    MAX(s.source_system_name) FILTER (
                        WHERE s.is_primary=TRUE
                        AND s.is_active=TRUE
                    ) AS primary_source_name,

                    MAX(s.source_format) FILTER (
                        WHERE s.is_primary=TRUE
                        AND s.is_active=TRUE
                    ) AS primary_source_format

                FROM {schema}.migration_project_sources s
                WHERE s.company_id=p.company_id
                AND s.project_id=p.id
                AND s.is_active=TRUE
            ) src ON TRUE

            WHERE {" AND ".join(where)}

            ORDER BY
                CASE
                    WHEN p.status='draft' THEN 0
                    WHEN p.status='configured' THEN 1
                    WHEN p.status='committed' THEN 3
                    ELSE 2
                END,
                p.updated_at DESC,
                p.id DESC

            LIMIT %s
        """

        return self.fetch_all(
            sql,
            tuple(params),
            cur=cur,
        ) or []


    def migration_project_get(
        self,
        company_id: int,
        project_id: int,
        *,
        cur=None,
    ) -> dict | None:
        company_id = int(company_id)
        project_id = int(project_id)
        schema = self.company_schema(company_id)

        project = self.fetch_one(
            f"""
            SELECT *
            FROM {schema}.migration_projects
            WHERE company_id=%s
            AND id=%s
            """,
            (
                company_id,
                project_id,
            ),
            cur=cur,
        )

        if not project:
            return None

        source = self.migration_project_source_get(
            company_id,
            project_id,
            cur=cur,
        )

        history = self.fetch_all(
            f"""
            SELECT
                id,
                previous_status,
                new_status,
                reason,
                details_json,
                changed_by_user_id,
                changed_at
            FROM {schema}.migration_project_status_history
            WHERE company_id=%s
            AND project_id=%s
            ORDER BY changed_at DESC, id DESC
            LIMIT 50
            """,
            (
                company_id,
                project_id,
            ),
            cur=cur,
        ) or []

        project["configuration_json"] = self._migration_json(
            project.get("configuration_json"),
            {},
        )

        project["metadata_json"] = self._migration_json(
            project.get("metadata_json"),
            {},
        )

        project["source"] = source
        project["status_history"] = history

        return project


    def migration_project_create(
        self,
        company_id: int,
        data: dict,
        *,
        user_id: int | None = None,
        cur=None,
    ) -> dict:
        company_id = int(company_id)
        schema = self.company_schema(company_id)
        data = data or {}
        validated = self._migration_project_validate(
            data,
        )
        name = validated["name"]
        description = validated["description"]
        financial_year_start = (
            validated["financial_year_start"]
        )
        cutover_date = validated["cutover_date"]
        default_currency = (
            validated["default_currency"]
        )
        reference = str(
            data.get("reference")
            or ""
        ).strip()

        if not reference:
            reference = self.migration_next_reference(
                company_id,
                cur=cur,
            )

        cutover_date = (
            data.get("cutover_date")
            or data.get("cutoverDate")
            or date.today().isoformat()
        )

        migration_mode = str(
            data.get("migration_mode")
            or data.get("migrationMode")
            or data.get("depth")
            or "opening"
        ).strip().lower()

        mode_aliases = {
            "current": "current_year",
            "two-years": "two_years",
            "full": "full_history",
        }

        migration_mode = mode_aliases.get(
            migration_mode,
            migration_mode,
        )

        import_mode = str(
            data.get("import_mode")
            or data.get("importMode")
            or "create_only"
        ).strip().lower()

        source_system_code = (
            validated["source_system_code"]
        )

        source_system_name = (
            validated["source_system_name"]
        )

        source_format = validated["source_format"]

        row = self.fetch_one(
            f"""
            INSERT INTO {schema}.migration_projects (
                company_id,
                reference,
                name,
                description,
                status,
                migration_mode,
                import_mode,
                financial_year_start,
                cutover_date,
                default_currency,
                source_timezone,
                source_country_code,
                source_tax_regime,
                source_system_code,
                source_system_name,
                source_system_version,
                source_format,
                date_format,
                decimal_separator,
                thousands_separator,
                debit_credit_convention,
                project_owner_user_id,
                created_by_user_id,
                updated_by_user_id,
                configuration_json,
                metadata_json,
                started_at,
                created_at,
                updated_at
            )
            VALUES (
                %s,%s,%s,%s,
                'draft',
                %s,%s,%s,%s,%s,
                %s,%s,%s,%s,%s,
                %s,%s,%s,%s,%s,%s,
                %s,%s,%s,
                %s::jsonb,
                %s::jsonb,
                NOW(),
                NOW(),
                NOW()
            )
            RETURNING *
            """,
            (
                company_id,
                reference,
                name,
                description,
                migration_mode,
                import_mode,
                financial_year_start,
                cutover_date,
                default_currency,
                data.get("source_timezone")
                or data.get("sourceTimezone"),
                data.get("source_country_code")
                or data.get("sourceCountryCode"),
                data.get("source_tax_regime")
                or data.get("sourceTaxRegime"),
                source_system_code,
                source_system_name,
                data.get("source_system_version")
                or data.get("sourceSystemVersion"),
                source_format,
                data.get("date_format")
                or data.get("dateFormat")
                or "YYYY-MM-DD",
                data.get("decimal_separator")
                or data.get("decimalSeparator")
                or ".",
                data.get("thousands_separator")
                or data.get("thousandsSeparator")
                or ",",
                data.get("debit_credit_convention")
                or data.get("debitCreditConvention")
                or "separate_columns",
                user_id,
                user_id,
                user_id,
                self._migration_json_dump(
                    data.get("configuration_json")
                    or data.get("configuration"),
                    {},
                ),
                self._migration_json_dump(
                    data.get("metadata_json")
                    or data.get("metadata"),
                    {},
                ),
            ),
            cur=cur,
        )

        project_id = int(row["id"])

        self.migration_project_source_save(
            company_id,
            project_id,
            {
                **data,
                "source_system_code": source_system_code,
                "source_system_name": source_system_name,
                "source_format": source_format,
                "is_primary": True,
            },
            user_id=user_id,
            cur=cur,
        )

        self.execute_sql(
            f"""
            INSERT INTO {schema}.migration_project_status_history (
                company_id,
                project_id,
                previous_status,
                new_status,
                reason,
                details_json,
                changed_by_user_id,
                changed_at
            )
            VALUES (
                %s,%s,NULL,'draft',
                'Migration project created',
                '{{}}'::jsonb,
                %s,
                NOW()
            )
            """,
            (
                company_id,
                project_id,
                user_id,
            ),
            cur=cur,
        )

        return self.migration_project_get(
            company_id,
            project_id,
            cur=cur,
        )


    def migration_project_update(
        self,
        company_id: int,
        project_id: int,
        data: dict,
        *,
        user_id: int | None = None,
        cur=None,
    ) -> dict:
        company_id = int(company_id)
        project_id = int(project_id)
        schema = self.company_schema(company_id)
        data = data or {}

        existing = self.migration_project_get(
            company_id,
            project_id,
            cur=cur,
        )

        if not existing:
            raise ValueError("Migration project not found.")

        if existing.get("status") in {
            "committing",
            "committed",
            "rolled_back",
            "cancelled",
        }:
            raise ValueError(
                f"Migration project cannot be edited while "
                f"its status is {existing.get('status')}."
            )

        validated = self._migration_project_validate(
            data,
            existing=existing,
        )

        migration_mode = str(
            data.get("migration_mode")
            or data.get("migrationMode")
            or data.get("depth")
            or existing.get("migration_mode")
            or "opening"
        ).strip().lower()

        mode_aliases = {
            "current": "current_year",
            "two-years": "two_years",
            "full": "full_history",
        }

        migration_mode = mode_aliases.get(
            migration_mode,
            migration_mode,
        )

        allowed_modes = {
            "opening",
            "current_year",
            "two_years",
            "full_history",
        }

        if migration_mode not in allowed_modes:
            raise ValueError(
                f"Unsupported migration mode: {migration_mode}"
            )

        import_mode = str(
            data.get("import_mode")
            or data.get("importMode")
            or existing.get("import_mode")
            or "create_only"
        ).strip().lower()

        allowed_import_modes = {
            "create_only",
            "update_only",
            "create_or_update",
            "replace_batch",
        }

        if import_mode not in allowed_import_modes:
            raise ValueError(
                f"Unsupported import mode: {import_mode}"
            )

        reference = str(
            data.get("reference")
            or existing.get("reference")
            or ""
        ).strip()

        if not reference:
            raise ValueError(
                "Migration project reference is required."
            )

        source_timezone = str(
            data.get("source_timezone")
            or data.get("sourceTimezone")
            or existing.get("source_timezone")
            or ""
        ).strip() or None

        source_country_code = str(
            data.get("source_country_code")
            or data.get("sourceCountryCode")
            or existing.get("source_country_code")
            or ""
        ).strip().upper() or None

        source_tax_regime = str(
            data.get("source_tax_regime")
            or data.get("sourceTaxRegime")
            or existing.get("source_tax_regime")
            or ""
        ).strip() or None

        source_system_version = str(
            data.get("source_system_version")
            or data.get("sourceSystemVersion")
            or existing.get("source_system_version")
            or ""
        ).strip() or None

        decimal_separator = str(
            data.get("decimal_separator")
            or data.get("decimalSeparator")
            or existing.get("decimal_separator")
            or "."
        )

        thousands_separator = data.get(
            "thousands_separator",
            data.get(
                "thousandsSeparator",
                existing.get("thousands_separator"),
            ),
        )

        if thousands_separator is None:
            thousands_separator = ","

        thousands_separator = str(
            thousands_separator
        )

        debit_credit_convention = str(
            data.get("debit_credit_convention")
            or data.get("debitCreditConvention")
            or existing.get("debit_credit_convention")
            or "separate_columns"
        ).strip().lower()

        allowed_conventions = {
            "separate_columns",
            "signed_amount",
            "transaction_type_amount",
            "account_normal_balance",
        }

        if debit_credit_convention not in allowed_conventions:
            raise ValueError(
                "Unsupported debit and credit convention: "
                f"{debit_credit_convention}"
            )

        project_owner_user_id = (
            data.get("project_owner_user_id")
            or data.get("projectOwnerUserId")
            or existing.get("project_owner_user_id")
            or user_id
        )

        if project_owner_user_id is not None:
            project_owner_user_id = int(
                project_owner_user_id
            )

        configuration_json = self._migration_json_dump(
            data.get(
                "configuration_json",
                data.get(
                    "configuration",
                    existing.get("configuration_json") or {},
                ),
            ),
            {},
        )

        metadata_json = self._migration_json_dump(
            data.get(
                "metadata_json",
                data.get(
                    "metadata",
                    existing.get("metadata_json") or {},
                ),
            ),
            {},
        )

        row = self.fetch_one(
            f"""
            UPDATE {schema}.migration_projects
            SET
                reference=%s,
                name=%s,
                description=%s,
                migration_mode=%s,
                import_mode=%s,
                financial_year_start=%s,
                cutover_date=%s,
                default_currency=%s,
                source_timezone=%s,
                source_country_code=%s,
                source_tax_regime=%s,
                source_system_code=%s,
                source_system_name=%s,
                source_system_version=%s,
                source_format=%s,
                date_format=%s,
                decimal_separator=%s,
                thousands_separator=%s,
                debit_credit_convention=%s,
                project_owner_user_id=%s,
                configuration_json=%s::jsonb,
                metadata_json=%s::jsonb,
                updated_by_user_id=%s,
                updated_at=NOW()
            WHERE company_id=%s
            AND id=%s
            RETURNING *
            """,
            (
                reference,
                validated["name"],
                validated["description"],
                migration_mode,
                import_mode,
                validated["financial_year_start"],
                validated["cutover_date"],
                validated["default_currency"],
                source_timezone,
                source_country_code,
                source_tax_regime,
                validated["source_system_code"],
                validated["source_system_name"],
                source_system_version,
                validated["source_format"],
                validated["date_format"],
                decimal_separator,
                thousands_separator,
                debit_credit_convention,
                project_owner_user_id,
                configuration_json,
                metadata_json,
                user_id,
                company_id,
                project_id,
            ),
            cur=cur,
        )

        if not row:
            raise ValueError(
                "Migration project could not be updated."
            )

        source_payload = data.get("source")

        if isinstance(source_payload, dict):
            source_payload = {
                **source_payload,
                "source_system_code":
                    source_payload.get("source_system_code")
                    or source_payload.get("sourceSystemCode")
                    or validated["source_system_code"],

                "source_system_name":
                    source_payload.get("source_system_name")
                    or source_payload.get("sourceSystem")
                    or validated["source_system_name"],

                "source_system_version":
                    source_payload.get("source_system_version")
                    or source_payload.get("sourceSystemVersion")
                    or source_system_version,

                "source_format":
                    source_payload.get("source_format")
                    or source_payload.get("sourceFormat")
                    or validated["source_format"],

                "country_code":
                    source_payload.get("country_code")
                    or source_payload.get("sourceCountryCode")
                    or source_country_code,

                "tax_regime":
                    source_payload.get("tax_regime")
                    or source_payload.get("sourceTaxRegime")
                    or source_tax_regime,

                "default_currency":
                    source_payload.get("default_currency")
                    or source_payload.get("defaultCurrency")
                    or validated["default_currency"],

                "source_timezone":
                    source_payload.get("source_timezone")
                    or source_payload.get("sourceTimezone")
                    or source_timezone,

                "date_format":
                    source_payload.get("date_format")
                    or source_payload.get("dateFormat")
                    or validated["date_format"],

                "decimal_separator":
                    source_payload.get("decimal_separator")
                    or source_payload.get("decimalSeparator")
                    or decimal_separator,

                "thousands_separator":
                    source_payload.get(
                        "thousands_separator",
                        source_payload.get(
                            "thousandsSeparator",
                            thousands_separator,
                        ),
                    ),

                "debit_credit_convention":
                    source_payload.get(
                        "debit_credit_convention"
                    )
                    or source_payload.get(
                        "debitCreditConvention"
                    )
                    or debit_credit_convention,
            }

        else:
            source_payload = {
                **data,
                "source_system_code":
                    validated["source_system_code"],

                "source_system_name":
                    validated["source_system_name"],

                "source_system_version":
                    source_system_version,

                "source_format":
                    validated["source_format"],

                "country_code":
                    source_country_code,

                "tax_regime":
                    source_tax_regime,

                "default_currency":
                    validated["default_currency"],

                "source_timezone":
                    source_timezone,

                "date_format":
                    validated["date_format"],

                "decimal_separator":
                    decimal_separator,

                "thousands_separator":
                    thousands_separator,

                "debit_credit_convention":
                    debit_credit_convention,
            }

        self.migration_project_source_save(
            company_id,
            project_id,
            source_payload,
            user_id=user_id,
            cur=cur,
        )

        return self.migration_project_get(
            company_id,
            project_id,
            cur=cur,
        )


    def migration_project_status_set(
        self,
        company_id: int,
        project_id: int,
        new_status: str,
        *,
        reason: str | None = None,
        details: dict | None = None,
        user_id: int | None = None,
        cur=None,
    ) -> dict:
        company_id = int(company_id)
        project_id = int(project_id)
        schema = self.company_schema(company_id)
        new_status = str(new_status or "").strip().lower()

        allowed = {
            "draft",
            "configured",
            "files_uploaded",
            "detected",
            "mapped",
            "validated",
            "previewed",
            "staged",
            "reconciled",
            "approved",
            "committing",
            "committed",
            "failed",
            "rolled_back",
            "cancelled",
        }

        if new_status not in allowed:
            raise ValueError(
                f"Unsupported migration status: {new_status}"
            )

        project = self.fetch_one(
            f"""
            SELECT id, status
            FROM {schema}.migration_projects
            WHERE company_id=%s
            AND id=%s
            """,
            (
                company_id,
                project_id,
            ),
            cur=cur,
        )

        if not project:
            raise ValueError("Migration project not found.")

        previous_status = str(
            project.get("status")
            or "draft"
        ).lower()

        if previous_status == new_status:
            return self.migration_project_get(
                company_id,
                project_id,
                cur=cur,
            )

        self.execute_sql(
            f"""
            UPDATE {schema}.migration_projects
            SET
                status=%s,

                completed_at=CASE
                    WHEN %s='committed'
                    THEN COALESCE(completed_at, NOW())
                    ELSE completed_at
                END,

                cancelled_at=CASE
                    WHEN %s='cancelled'
                    THEN COALESCE(cancelled_at, NOW())
                    ELSE cancelled_at
                END,

                updated_by_user_id=%s,
                updated_at=NOW()

            WHERE company_id=%s
            AND id=%s
            """,
            (
                new_status,
                new_status,
                new_status,
                user_id,
                company_id,
                project_id,
            ),
            cur=cur,
        )

        self.execute_sql(
            f"""
            INSERT INTO {schema}.migration_project_status_history (
                company_id,
                project_id,
                previous_status,
                new_status,
                reason,
                details_json,
                changed_by_user_id,
                changed_at
            )
            VALUES (
                %s,%s,%s,%s,%s,%s::jsonb,%s,NOW()
            )
            """,
            (
                company_id,
                project_id,
                previous_status,
                new_status,
                reason,
                self._migration_json_dump(details, {}),
                user_id,
            ),
            cur=cur,
        )

        return self.migration_project_get(
            company_id,
            project_id,
            cur=cur,
        )


    def migration_project_source_get(
        self,
        company_id: int,
        project_id: int,
        *,
        cur=None,
    ) -> dict | None:
        company_id = int(company_id)
        project_id = int(project_id)
        schema = self.company_schema(company_id)

        row = self.fetch_one(
            f"""
            SELECT
                s.*,
                p.code AS source_profile_code,
                p.name AS source_profile_name
            FROM {schema}.migration_project_sources s
            LEFT JOIN {schema}.migration_source_profiles p
            ON p.company_id=s.company_id
            AND p.id=s.source_profile_id
            WHERE s.company_id=%s
            AND s.project_id=%s
            AND s.is_active=TRUE
            ORDER BY
                s.is_primary DESC,
                s.id ASC
            LIMIT 1
            """,
            (
                company_id,
                project_id,
            ),
            cur=cur,
        )

        if not row:
            return None

        row["settings_json"] = self._migration_json(
            row.get("settings_json"),
            {},
        )

        row["metadata_json"] = self._migration_json(
            row.get("metadata_json"),
            {},
        )

        return row


    def migration_project_source_save(
        self,
        company_id: int,
        project_id: int,
        data: dict,
        *,
        user_id: int | None = None,
        cur=None,
    ) -> dict:
        company_id = int(company_id)
        project_id = int(project_id)
        schema = self.company_schema(company_id)
        data = data or {}

        project = self.fetch_one(
            f"""
            SELECT *
            FROM {schema}.migration_projects
            WHERE company_id=%s
            AND id=%s
            """,
            (
                company_id,
                project_id,
            ),
            cur=cur,
        )

        if not project:
            raise ValueError("Migration project not found.")

        existing = self.migration_project_source_get(
            company_id,
            project_id,
            cur=cur,
        )

        source_system_name = str(
            data.get("source_system_name")
            or data.get("sourceSystem")
            or project.get("source_system_name")
            or "Excel / CSV"
        ).strip()

        source_system_code = str(
            data.get("source_system_code")
            or data.get("sourceSystemCode")
            or project.get("source_system_code")
            or self._migration_slug(source_system_name)
        ).strip()

        source_format = str(
            data.get("source_format")
            or data.get("sourceFormat")
            or project.get("source_format")
            or "excel_csv"
        ).strip().lower()

        profile_id = (
            data.get("source_profile_id")
            or data.get("sourceProfileId")
        )

        if existing:
            source_id = int(existing["id"])

            row = self.fetch_one(
                f"""
                UPDATE {schema}.migration_project_sources
                SET
                    source_profile_id=%s,
                    source_system_code=%s,
                    source_system_name=%s,
                    source_system_version=%s,
                    source_format=%s,
                    country_code=%s,
                    tax_regime=%s,
                    default_currency=%s,
                    source_timezone=%s,
                    date_format=%s,
                    decimal_separator=%s,
                    thousands_separator=%s,
                    debit_credit_convention=%s,
                    connection_type=%s,
                    connection_name=%s,
                    settings_json=%s::jsonb,
                    credentials_reference=%s,
                    metadata_json=%s::jsonb,
                    is_primary=TRUE,
                    is_active=TRUE,
                    updated_by_user_id=%s,
                    updated_at=NOW()
                WHERE company_id=%s
                AND project_id=%s
                AND id=%s
                RETURNING *
                """,
                (
                    profile_id
                    or existing.get("source_profile_id"),

                    source_system_code,
                    source_system_name,

                    data.get("source_system_version")
                    or data.get("sourceSystemVersion")
                    or existing.get("source_system_version"),

                    source_format,

                    data.get("country_code")
                    or data.get("sourceCountryCode")
                    or existing.get("country_code"),

                    data.get("tax_regime")
                    or data.get("sourceTaxRegime")
                    or existing.get("tax_regime"),

                    data.get("default_currency")
                    or data.get("defaultCurrency")
                    or existing.get("default_currency"),

                    data.get("source_timezone")
                    or data.get("sourceTimezone")
                    or existing.get("source_timezone"),

                    data.get("date_format")
                    or data.get("dateFormat")
                    or existing.get("date_format")
                    or "YYYY-MM-DD",

                    data.get("decimal_separator")
                    or data.get("decimalSeparator")
                    or existing.get("decimal_separator")
                    or ".",

                    data.get("thousands_separator")
                    or data.get("thousandsSeparator")
                    or existing.get("thousands_separator")
                    or ",",

                    data.get("debit_credit_convention")
                    or data.get("debitCreditConvention")
                    or existing.get("debit_credit_convention")
                    or "separate_columns",

                    data.get("connection_type")
                    or data.get("connectionType")
                    or existing.get("connection_type")
                    or "file_upload",

                    data.get("connection_name")
                    or data.get("connectionName")
                    or existing.get("connection_name")
                    or "Primary migration source",

                    self._migration_json_dump(
                        data.get(
                            "settings_json",
                            data.get(
                                "settings",
                                existing.get("settings_json") or {},
                            ),
                        ),
                        {},
                    ),

                    data.get("credentials_reference")
                    or data.get("credentialsReference")
                    or existing.get("credentials_reference"),

                    self._migration_json_dump(
                        data.get(
                            "metadata_json",
                            data.get(
                                "metadata",
                                existing.get("metadata_json") or {},
                            ),
                        ),
                        {},
                    ),

                    user_id,
                    company_id,
                    project_id,
                    source_id,
                ),
                cur=cur,
            )

        else:
            row = self.fetch_one(
                f"""
                INSERT INTO {schema}.migration_project_sources (
                    company_id,
                    project_id,
                    source_profile_id,
                    source_system_code,
                    source_system_name,
                    source_system_version,
                    source_format,
                    country_code,
                    tax_regime,
                    default_currency,
                    source_timezone,
                    date_format,
                    decimal_separator,
                    thousands_separator,
                    debit_credit_convention,
                    connection_type,
                    connection_name,
                    settings_json,
                    credentials_reference,
                    metadata_json,
                    is_primary,
                    is_active,
                    created_by_user_id,
                    updated_by_user_id,
                    created_at,
                    updated_at
                )
                VALUES (
                    %s,%s,%s,%s,%s,%s,%s,
                    %s,%s,%s,%s,%s,%s,%s,%s,
                    %s,%s,%s::jsonb,%s,%s::jsonb,
                    TRUE,TRUE,%s,%s,NOW(),NOW()
                )
                RETURNING *
                """,
                (
                    company_id,
                    project_id,
                    profile_id,
                    source_system_code,
                    source_system_name,
                    data.get("source_system_version")
                    or data.get("sourceSystemVersion"),
                    source_format,
                    data.get("country_code")
                    or data.get("sourceCountryCode"),
                    data.get("tax_regime")
                    or data.get("sourceTaxRegime"),
                    data.get("default_currency")
                    or data.get("defaultCurrency"),
                    data.get("source_timezone")
                    or data.get("sourceTimezone"),
                    data.get("date_format")
                    or data.get("dateFormat")
                    or "YYYY-MM-DD",
                    data.get("decimal_separator")
                    or data.get("decimalSeparator")
                    or ".",
                    data.get("thousands_separator")
                    or data.get("thousandsSeparator")
                    or ",",
                    data.get("debit_credit_convention")
                    or data.get("debitCreditConvention")
                    or "separate_columns",
                    data.get("connection_type")
                    or data.get("connectionType")
                    or "file_upload",
                    data.get("connection_name")
                    or data.get("connectionName")
                    or "Primary migration source",
                    self._migration_json_dump(
                        data.get("settings_json")
                        or data.get("settings"),
                        {},
                    ),
                    data.get("credentials_reference")
                    or data.get("credentialsReference"),
                    self._migration_json_dump(
                        data.get("metadata_json")
                        or data.get("metadata"),
                        {},
                    ),
                    user_id,
                    user_id,
                ),
                cur=cur,
            )

        self.execute_sql(
            f"""
            UPDATE {schema}.migration_projects
            SET
                source_system_code=%s,
                source_system_name=%s,
                source_system_version=%s,
                source_format=%s,
                source_country_code=%s,
                source_tax_regime=%s,
                default_currency=%s,
                source_timezone=%s,
                date_format=%s,
                decimal_separator=%s,
                thousands_separator=%s,
                debit_credit_convention=%s,
                updated_by_user_id=%s,
                updated_at=NOW()
            WHERE company_id=%s
            AND id=%s
            """,
            (
                source_system_code,
                source_system_name,
                data.get("source_system_version")
                or data.get("sourceSystemVersion")
                or project.get("source_system_version"),
                source_format,
                data.get("country_code")
                or data.get("sourceCountryCode")
                or project.get("source_country_code"),
                data.get("tax_regime")
                or data.get("sourceTaxRegime")
                or project.get("source_tax_regime"),
                data.get("default_currency")
                or data.get("defaultCurrency")
                or project.get("default_currency"),
                data.get("source_timezone")
                or data.get("sourceTimezone")
                or project.get("source_timezone"),
                data.get("date_format")
                or data.get("dateFormat")
                or project.get("date_format")
                or "YYYY-MM-DD",
                data.get("decimal_separator")
                or data.get("decimalSeparator")
                or project.get("decimal_separator")
                or ".",
                data.get("thousands_separator")
                or data.get("thousandsSeparator")
                or project.get("thousands_separator")
                or ",",
                data.get("debit_credit_convention")
                or data.get("debitCreditConvention")
                or project.get("debit_credit_convention")
                or "separate_columns",
                user_id,
                company_id,
                project_id,
            ),
            cur=cur,
        )

        return self.migration_project_source_get(
            company_id,
            project_id,
            cur=cur,
        )


    def migration_source_profiles_list(
        self,
        company_id: int,
        *,
        include_inactive: bool = False,
        cur=None,
    ) -> list[dict]:
        company_id = int(company_id)
        schema = self.company_schema(company_id)

        where = ["company_id=%s"]
        params: list = [company_id]

        if not include_inactive:
            where.append("is_active=TRUE")

        rows = self.fetch_all(
            f"""
            SELECT *
            FROM {schema}.migration_source_profiles
            WHERE {" AND ".join(where)}
            ORDER BY
                is_system DESC,
                name ASC,
                id ASC
            """,
            tuple(params),
            cur=cur,
        ) or []

        for row in rows:
            for field, default in (
                ("file_name_patterns_json", []),
                ("sheet_name_patterns_json", {}),
                ("column_aliases_json", {}),
                ("detection_rules_json", {}),
                ("transformation_defaults_json", {}),
                ("metadata_json", {}),
            ):
                row[field] = self._migration_json(
                    row.get(field),
                    default,
                )

        return rows


    def migration_project_cancel(
        self,
        company_id: int,
        project_id: int,
        *,
        reason: str | None = None,
        user_id: int | None = None,
        cur=None,
    ) -> dict:
        project = self.migration_project_get(
            company_id,
            project_id,
            cur=cur,
        )

        if not project:
            raise ValueError("Migration project not found.")

        if project.get("status") in {
            "committing",
            "committed",
            "rolled_back",
        }:
            raise ValueError(
                f"Migration project cannot be cancelled while "
                f"its status is {project.get('status')}."
            )

        return self.migration_project_status_set(
            company_id,
            project_id,
            "cancelled",
            reason=reason or "Migration project cancelled",
            user_id=user_id,
            cur=cur,
        )


    def _migration_slug(self, value: str) -> str:
        value = str(value or "").strip().lower()

        value = "".join(
            character
            if character.isalnum()
            else "_"
            for character in value
        )

        while "__" in value:
            value = value.replace("__", "_")

        return value.strip("_") or "generic"

    def migration_scope_get(
        self,
        company_id: int,
        project_id: int,
        *,
        cur=None,
    ) -> dict:
        company_id = int(company_id)
        project_id = int(project_id)
        schema = self.company_schema(company_id)

        project = self.fetch_one(
            f"""
            SELECT
                id,
                migration_mode,
                import_mode,
                status
            FROM {schema}.migration_projects
            WHERE company_id=%s
            AND id=%s
            """,
            (
                company_id,
                project_id,
            ),
            cur=cur,
        )

        if not project:
            raise ValueError("Migration project not found.")

        catalog = self.fetch_all(
            f"""
            SELECT
                c.code,
                c.group_code,
                c.group_name,
                c.label,
                c.description,
                c.default_history_mode,
                c.supports_opening,
                c.supports_current_year,
                c.supports_two_years,
                c.supports_full_history,
                c.default_import_mode,
                c.is_required,
                c.sort_order,

                COALESCE(pe.is_selected, FALSE) AS is_selected,
                COALESCE(
                    pe.selection_source,
                    CASE
                        WHEN c.is_required THEN 'system'
                        ELSE 'manual'
                    END
                ) AS selection_source,

                COALESCE(
                    pe.history_mode,
                    CASE
                        WHEN c.default_history_mode='opening'
                        THEN 'opening'
                        ELSE %s
                    END
                ) AS history_mode,

                COALESCE(
                    pe.import_mode,
                    c.default_import_mode
                ) AS import_mode,

                pe.source_dataset_name,
                COALESCE(pe.settings_json, '{{}}'::jsonb)
                    AS settings_json,
                COALESCE(pe.metadata_json, '{{}}'::jsonb)
                    AS metadata_json

            FROM {schema}.migration_entity_catalog c

            LEFT JOIN {schema}.migration_project_entities pe
            ON pe.company_id=%s
            AND pe.project_id=%s
            AND pe.entity_code=c.code

            WHERE c.is_active=TRUE

            ORDER BY
                c.sort_order,
                c.group_name,
                c.label
            """,
            (
                project.get("migration_mode") or "opening",
                company_id,
                project_id,
            ),
            cur=cur,
        ) or []

        dependencies = self.fetch_all(
            f"""
            SELECT
                d.entity_code,
                d.depends_on_code,
                d.dependency_type,
                d.reason,
                d.sort_order
            FROM {schema}.migration_entity_dependencies d
            JOIN {schema}.migration_entity_catalog entity
            ON entity.code=d.entity_code
            AND entity.is_active=TRUE
            JOIN {schema}.migration_entity_catalog parent
            ON parent.code=d.depends_on_code
            AND parent.is_active=TRUE
            ORDER BY
                d.entity_code,
                d.sort_order,
                d.depends_on_code
            """,
            cur=cur,
        ) or []

        dependency_map: dict[str, list[dict]] = {}

        for dependency in dependencies:
            entity_code = dependency["entity_code"]

            dependency_map.setdefault(
                entity_code,
                [],
            ).append({
                "code": dependency["depends_on_code"],
                "type": dependency["dependency_type"],
                "reason": dependency.get("reason"),
            })

        for entity in catalog:
            entity["dependencies"] = dependency_map.get(
                entity["code"],
                [],
            )

            entity["settings_json"] = self._migration_json(
                entity.get("settings_json"),
                {},
            )

            entity["metadata_json"] = self._migration_json(
                entity.get("metadata_json"),
                {},
            )

        selected_count = sum(
            1
            for entity in catalog
            if entity.get("is_selected")
        )

        return {
            "project_id": project_id,
            "project_status": project.get("status"),
            "migration_mode": (
                project.get("migration_mode")
                or "opening"
            ),
            "default_import_mode": (
                project.get("import_mode")
                or "create_only"
            ),
            "selected_count": selected_count,
            "entities": catalog,
        }


    def migration_scope_dependency_codes(
        self,
        company_id: int,
        selected_codes: set[str],
        *,
        cur=None,
    ) -> set[str]:
        company_id = int(company_id)
        schema = self.company_schema(company_id)

        selected = {
            str(code or "").strip()
            for code in selected_codes
            if str(code or "").strip()
        }

        if not selected:
            return set()

        all_selected = set(selected)

        while True:
            rows = self.fetch_all(
                f"""
                SELECT
                    entity_code,
                    depends_on_code
                FROM {schema}.migration_entity_dependencies
                WHERE dependency_type='required'
                AND entity_code = ANY(%s)
                """,
                (
                    list(all_selected),
                ),
                cur=cur,
            ) or []

            before = len(all_selected)

            for row in rows:
                all_selected.add(
                    row["depends_on_code"]
                )

            if len(all_selected) == before:
                break

        return all_selected


    def migration_scope_validate_history_mode(
        self,
        entity: dict,
        history_mode: str,
    ) -> None:
        history_mode = str(
            history_mode or ""
        ).strip().lower()

        supported_field = {
            "opening": "supports_opening",
            "current_year": "supports_current_year",
            "two_years": "supports_two_years",
            "full_history": "supports_full_history",
        }.get(history_mode)

        if not supported_field:
            raise ValueError(
                f"Unsupported history mode: {history_mode}"
            )

        if not entity.get(supported_field):
            raise ValueError(
                f"{entity.get('label') or entity.get('code')} "
                f"does not support {history_mode} migration."
            )


    def migration_scope_save(
        self,
        company_id: int,
        project_id: int,
        entities: list[dict],
        *,
        user_id: int | None = None,
        cur=None,
    ) -> dict:
        company_id = int(company_id)
        project_id = int(project_id)
        schema = self.company_schema(company_id)

        project = self.fetch_one(
            f"""
            SELECT
                id,
                status,
                migration_mode,
                import_mode
            FROM {schema}.migration_projects
            WHERE company_id=%s
            AND id=%s
            """,
            (
                company_id,
                project_id,
            ),
            cur=cur,
        )

        if not project:
            raise ValueError("Migration project not found.")

        if project.get("status") in {
            "committing",
            "committed",
            "rolled_back",
            "cancelled",
        }:
            raise ValueError(
                f"Migration scope cannot be changed while "
                f"the project status is {project.get('status')}."
            )

        if not isinstance(entities, list):
            raise ValueError(
                "entities must be a list."
            )

        catalog_rows = self.fetch_all(
            f"""
            SELECT *
            FROM {schema}.migration_entity_catalog
            WHERE is_active=TRUE
            """,
            cur=cur,
        ) or []

        catalog = {
            row["code"]: row
            for row in catalog_rows
        }

        supplied: dict[str, dict] = {}

        for item in entities:
            if not isinstance(item, dict):
                raise ValueError(
                    "Each migration entity must be an object."
                )

            code = str(
                item.get("code")
                or item.get("entity_code")
                or ""
            ).strip()

            if not code:
                raise ValueError(
                    "Migration entity code is required."
                )

            if code not in catalog:
                raise ValueError(
                    f"Unknown migration entity: {code}"
                )

            supplied[code] = item

        selected_codes = {
            code
            for code, item in supplied.items()
            if bool(item.get("is_selected"))
        }

        selected_codes.update({
            code
            for code, row in catalog.items()
            if row.get("is_required")
        })

        selected_with_dependencies = (
            self.migration_scope_dependency_codes(
                company_id,
                selected_codes,
                cur=cur,
            )
        )

        for code, entity in catalog.items():
            supplied_item = supplied.get(code) or {}

            is_selected = (
                code in selected_with_dependencies
            )

            manually_selected = bool(
                supplied_item.get("is_selected")
            )

            if entity.get("is_required"):
                selection_source = "system"
            elif (
                is_selected
                and not manually_selected
            ):
                selection_source = "dependency"
            else:
                selection_source = "manual"

            history_mode = str(
                supplied_item.get("history_mode")
                or (
                    "opening"
                    if entity.get(
                        "default_history_mode"
                    ) == "opening"
                    else project.get(
                        "migration_mode"
                    )
                )
                or "opening"
            ).strip().lower()

            import_mode = str(
                supplied_item.get("import_mode")
                or entity.get(
                    "default_import_mode"
                )
                or project.get("import_mode")
                or "create_only"
            ).strip().lower()

            if is_selected:
                self.migration_scope_validate_history_mode(
                    entity,
                    history_mode,
                )

            if import_mode not in {
                "create_only",
                "update_only",
                "create_or_update",
                "replace_batch",
            }:
                raise ValueError(
                    f"Unsupported import mode for "
                    f"{code}: {import_mode}"
                )

            self.execute_sql(
                f"""
                INSERT INTO {schema}.migration_project_entities (
                    company_id,
                    project_id,
                    entity_code,
                    is_selected,
                    selection_source,
                    history_mode,
                    import_mode,
                    source_dataset_name,
                    settings_json,
                    metadata_json,
                    created_by_user_id,
                    updated_by_user_id,
                    created_at,
                    updated_at
                )
                VALUES (
                    %s,%s,%s,%s,%s,%s,%s,%s,
                    %s::jsonb,
                    %s::jsonb,
                    %s,%s,
                    NOW(),
                    NOW()
                )
                ON CONFLICT (
                    company_id,
                    project_id,
                    entity_code
                )
                DO UPDATE SET
                    is_selected=EXCLUDED.is_selected,
                    selection_source=EXCLUDED.selection_source,
                    history_mode=EXCLUDED.history_mode,
                    import_mode=EXCLUDED.import_mode,
                    source_dataset_name=EXCLUDED.source_dataset_name,
                    settings_json=EXCLUDED.settings_json,
                    metadata_json=EXCLUDED.metadata_json,
                    updated_by_user_id=EXCLUDED.updated_by_user_id,
                    updated_at=NOW()
                """,
                (
                    company_id,
                    project_id,
                    code,
                    is_selected,
                    selection_source,
                    history_mode,
                    import_mode,
                    supplied_item.get(
                        "source_dataset_name"
                    ),
                    self._migration_json_dump(
                        supplied_item.get(
                            "settings_json"
                        )
                        or supplied_item.get(
                            "settings"
                        ),
                        {},
                    ),
                    self._migration_json_dump(
                        supplied_item.get(
                            "metadata_json"
                        )
                        or supplied_item.get(
                            "metadata"
                        ),
                        {},
                    ),
                    user_id,
                    user_id,
                ),
                cur=cur,
            )

        selected_count = len(
            selected_with_dependencies
        )

        new_status = (
            "configured"
            if selected_count > 0
            else "draft"
        )

        self.execute_sql(
            f"""
            UPDATE {schema}.migration_projects
            SET
                status=CASE
                    WHEN status='draft'
                    THEN %s
                    ELSE status
                END,
                updated_by_user_id=%s,
                updated_at=NOW()
            WHERE company_id=%s
            AND id=%s
            """,
            (
                new_status,
                user_id,
                company_id,
                project_id,
            ),
            cur=cur,
        )

        return self.migration_scope_get(
            company_id,
            project_id,
            cur=cur,
        )

    def migration_upload_root(self) -> Path:
        root = (
            os.environ.get("FINSAGE_MIGRATION_UPLOAD_ROOT")
            or os.path.join(
                os.getcwd(),
                "uploads",
                "migrations",
            )
        )

        path = Path(root).resolve()
        path.mkdir(
            parents=True,
            exist_ok=True,
        )

        return path


    def migration_project_upload_dir(
        self,
        company_id: int,
        project_id: int,
    ) -> Path:
        company_id = int(company_id)
        project_id = int(project_id)

        path = (
            self.migration_upload_root()
            / f"company_{company_id}"
            / f"project_{project_id}"
        )

        path.mkdir(
            parents=True,
            exist_ok=True,
        )

        return path


    def migration_safe_filename(
        self,
        filename: str,
    ) -> str:
        filename = os.path.basename(
            str(filename or "")
        ).strip()

        if not filename:
            filename = "migration-file"

        stem, extension = os.path.splitext(
            filename
        )

        stem = re.sub(
            r"[^A-Za-z0-9._-]+",
            "_",
            stem,
        ).strip("._-")

        if not stem:
            stem = "migration-file"

        extension = re.sub(
            r"[^A-Za-z0-9.]",
            "",
            extension.lower(),
        )

        return f"{stem[:180]}{extension[:20]}"


    def migration_file_sha256(
        self,
        path: str | Path,
    ) -> str:
        digest = hashlib.sha256()

        with open(path, "rb") as source:
            while True:
                chunk = source.read(
                    1024 * 1024
                )

                if not chunk:
                    break

                digest.update(chunk)

        return digest.hexdigest()

    def migration_file_extension(
        self,
        filename: str,
    ) -> str:
        return Path(
            str(filename or "")
        ).suffix.lower().lstrip(".")


    def migration_file_format(
        self,
        filename: str,
    ) -> str:
        extension = self.migration_file_extension(
            filename
        )

        return {
            "xlsx": "excel_csv",
            "xls": "excel_csv",
            "csv": "excel_csv",
            "json": "json",
            "xml": "xml",
            "sql": "sql_extract",
            "txt": "other",
        }.get(
            extension,
            "other",
        )


    def migration_dataset_type(
        self,
        filename: str,
    ) -> str:
        extension = self.migration_file_extension(
            filename
        )

        return {
            "xlsx": "worksheet",
            "xls": "worksheet",
            "csv": "file",
            "json": "json_array",
            "xml": "xml_collection",
            "sql": "sql_table",
            "txt": "text_section",
        }.get(
            extension,
            "file",
        )

    def migration_files_list(
        self,
        company_id: int,
        project_id: int,
        *,
        include_removed: bool = False,
        cur=None,
    ) -> list[dict]:
        company_id = int(company_id)
        project_id = int(project_id)
        schema = self.company_schema(company_id)

        where = [
            "f.company_id=%s",
            "f.project_id=%s",
        ]

        params: list = [
            company_id,
            project_id,
        ]

        if not include_removed:
            where.append(
                "f.file_status <> 'removed'"
            )

        rows = self.fetch_all(
            f"""
            SELECT
                f.*,

                COALESCE(
                    (
                        SELECT COUNT(*)
                        FROM {schema}.migration_source_datasets d
                        WHERE d.company_id=f.company_id
                        AND d.project_id=f.project_id
                        AND d.source_file_id=f.id
                    ),
                    0
                )::INT AS actual_dataset_count

            FROM {schema}.migration_source_files f

            WHERE {" AND ".join(where)}

            ORDER BY
                f.upload_order,
                f.id
            """,
            tuple(params),
            cur=cur,
        ) or []

        for row in rows:
            row["settings_json"] = (
                self._migration_json(
                    row.get("settings_json"),
                    {},
                )
            )

            row["metadata_json"] = (
                self._migration_json(
                    row.get("metadata_json"),
                    {},
                )
            )

            row["datasets"] = (
                self.migration_datasets_list(
                    company_id,
                    project_id,
                    source_file_id=row["id"],
                    cur=cur,
                )
            )

        return rows


    def migration_datasets_list(
        self,
        company_id: int,
        project_id: int,
        *,
        source_file_id: int | None = None,
        cur=None,
    ) -> list[dict]:
        company_id = int(company_id)
        project_id = int(project_id)
        schema = self.company_schema(company_id)

        where = [
            "d.company_id=%s",
            "d.project_id=%s",
        ]

        params: list = [
            company_id,
            project_id,
        ]

        if source_file_id is not None:
            where.append(
                "d.source_file_id=%s"
            )

            params.append(
                int(source_file_id)
            )

        rows = self.fetch_all(
            f"""
            SELECT
                d.*,
                f.original_name AS source_file_name,
                c.label AS entity_label,
                c.group_name AS entity_group_name

            FROM {schema}.migration_source_datasets d

            JOIN {schema}.migration_source_files f
            ON f.company_id=d.company_id
            AND f.project_id=d.project_id
            AND f.id=d.source_file_id

            LEFT JOIN {schema}.migration_entity_catalog c
            ON c.code=d.entity_code

            WHERE {" AND ".join(where)}

            ORDER BY
                f.upload_order,
                d.id
            """,
            tuple(params),
            cur=cur,
        ) or []

        for row in rows:
            row["settings_json"] = (
                self._migration_json(
                    row.get("settings_json"),
                    {},
                )
            )

            row["metadata_json"] = (
                self._migration_json(
                    row.get("metadata_json"),
                    {},
                )
            )

        return rows

    def migration_source_file_create(
        self,
        company_id: int,
        project_id: int,
        *,
        original_name: str,
        stored_name: str,
        storage_path: str,
        mime_type: str | None,
        size_bytes: int,
        sha256_hash: str,
        user_id: int | None = None,
        cur=None,
    ) -> dict:
        company_id = int(company_id)
        project_id = int(project_id)
        schema = self.company_schema(company_id)

        project = self.fetch_one(
            f"""
            SELECT
                id,
                status,
                source_system_code,
                source_format
            FROM {schema}.migration_projects
            WHERE company_id=%s
            AND id=%s
            """,
            (
                company_id,
                project_id,
            ),
            cur=cur,
        )

        if not project:
            raise ValueError(
                "Migration project not found."
            )

        if project.get("status") in {
            "committing",
            "committed",
            "rolled_back",
            "cancelled",
        }:
            raise ValueError(
                "Files cannot be uploaded while "
                f"the project status is {project.get('status')}."
            )

        duplicate = self.fetch_one(
            f"""
            SELECT
                id,
                original_name
            FROM {schema}.migration_source_files
            WHERE company_id=%s
            AND project_id=%s
            AND sha256_hash=%s
            AND file_status <> 'removed'
            """,
            (
                company_id,
                project_id,
                sha256_hash,
            ),
            cur=cur,
        )

        if duplicate:
            raise ValueError(
                f"This file has already been uploaded as "
                f"{duplicate.get('original_name')}."
            )

        upload_order = int(
            self.fetch_val(
                f"""
                SELECT COALESCE(
                    MAX(upload_order),
                    0
                ) + 1
                FROM {schema}.migration_source_files
                WHERE company_id=%s
                AND project_id=%s
                """,
                (
                    company_id,
                    project_id,
                ),
                cur=cur,
            ) or 1
        )

        extension = (
            self.migration_file_extension(
                original_name
            )
        )

        source_format = (
            self.migration_file_format(
                original_name
            )
        )

        row = self.fetch_one(
            f"""
            INSERT INTO {schema}.migration_source_files (
                company_id,
                project_id,
                original_name,
                stored_name,
                storage_path,
                extension,
                mime_type,
                size_bytes,
                sha256_hash,
                file_status,
                upload_order,
                source_system_code,
                source_format,
                uploaded_by_user_id,
                settings_json,
                metadata_json,
                uploaded_at,
                created_at,
                updated_at
            )
            VALUES (
                %s,%s,%s,%s,%s,%s,%s,%s,%s,
                'uploaded',
                %s,%s,%s,%s,
                '{{}}'::jsonb,
                '{{}}'::jsonb,
                NOW(),
                NOW(),
                NOW()
            )
            RETURNING *
            """,
            (
                company_id,
                project_id,
                original_name,
                stored_name,
                storage_path,
                extension,
                mime_type,
                int(size_bytes or 0),
                sha256_hash,
                upload_order,
                project.get(
                    "source_system_code"
                ),
                source_format,
                user_id,
            ),
            cur=cur,
        )

        file_id = int(row["id"])

        dataset_name = (
            Path(original_name).stem
            or original_name
        )

        dataset_key = (
            self._migration_slug(
                dataset_name
            )
            or f"dataset_{file_id}"
        )

        self.execute_sql(
            f"""
            INSERT INTO {schema}.migration_source_datasets (
                company_id,
                project_id,
                source_file_id,
                dataset_key,
                dataset_name,
                sheet_name,
                dataset_type,
                header_row,
                data_start_row,
                delimiter,
                encoding,
                date_format,
                decimal_separator,
                thousands_separator,
                dataset_status,
                is_selected,
                created_by_user_id,
                updated_by_user_id,
                created_at,
                updated_at
            )
            VALUES (
                %s,%s,%s,%s,%s,NULL,%s,
                1,2,%s,%s,%s,%s,%s,
                'pending',
                TRUE,
                %s,%s,
                NOW(),
                NOW()
            )
            """,
            (
                company_id,
                project_id,
                file_id,
                dataset_key,
                dataset_name,
                self.migration_dataset_type(
                    original_name
                ),
                (
                    ","
                    if extension == "csv"
                    else None
                ),
                (
                    "utf-8"
                    if extension in {
                        "csv",
                        "json",
                        "xml",
                        "sql",
                        "txt",
                    }
                    else None
                ),
                project.get("date_format"),
                project.get(
                    "decimal_separator"
                ),
                project.get(
                    "thousands_separator"
                ),
                user_id,
                user_id,
            ),
            cur=cur,
        )

        self.execute_sql(
            f"""
            UPDATE {schema}.migration_source_files
            SET
                dataset_count=1,
                updated_at=NOW()
            WHERE company_id=%s
            AND project_id=%s
            AND id=%s
            """,
            (
                company_id,
                project_id,
                file_id,
            ),
            cur=cur,
        )

        self.execute_sql(
            f"""
            INSERT INTO {schema}.migration_file_events (
                company_id,
                project_id,
                source_file_id,
                event_type,
                message,
                details_json,
                actor_user_id,
                created_at
            )
            VALUES (
                %s,%s,%s,
                'uploaded',
                %s,
                %s::jsonb,
                %s,
                NOW()
            )
            """,
            (
                company_id,
                project_id,
                file_id,
                f"Uploaded {original_name}",
                self._migration_json_dump(
                    {
                        "original_name":
                            original_name,
                        "size_bytes":
                            int(size_bytes or 0),
                        "sha256_hash":
                            sha256_hash,
                    },
                    {},
                ),
                user_id,
            ),
            cur=cur,
        )

        self.execute_sql(
            f"""
            UPDATE {schema}.migration_projects
            SET
                status=CASE
                    WHEN status IN (
                        'draft',
                        'configured'
                    )
                    THEN 'files_uploaded'
                    ELSE status
                END,
                updated_by_user_id=%s,
                updated_at=NOW()
            WHERE company_id=%s
            AND id=%s
            """,
            (
                user_id,
                company_id,
                project_id,
            ),
            cur=cur,
        )

        return self.migration_source_file_get(
            company_id,
            project_id,
            file_id,
            cur=cur,
        )

    def migration_source_file_get(
        self,
        company_id: int,
        project_id: int,
        file_id: int,
        *,
        cur=None,
    ) -> dict | None:
        company_id = int(company_id)
        project_id = int(project_id)
        file_id = int(file_id)
        schema = self.company_schema(company_id)

        row = self.fetch_one(
            f"""
            SELECT *
            FROM {schema}.migration_source_files
            WHERE company_id=%s
            AND project_id=%s
            AND id=%s
            """,
            (
                company_id,
                project_id,
                file_id,
            ),
            cur=cur,
        )

        if not row:
            return None

        row["settings_json"] = (
            self._migration_json(
                row.get("settings_json"),
                {},
            )
        )

        row["metadata_json"] = (
            self._migration_json(
                row.get("metadata_json"),
                {},
            )
        )

        row["datasets"] = (
            self.migration_datasets_list(
                company_id,
                project_id,
                source_file_id=file_id,
                cur=cur,
            )
        )

        return row

    def migration_dataset_update(
        self,
        company_id: int,
        project_id: int,
        dataset_id: int,
        data: dict,
        *,
        user_id: int | None = None,
        cur=None,
    ) -> dict:
        company_id = int(company_id)
        project_id = int(project_id)
        dataset_id = int(dataset_id)
        schema = self.company_schema(company_id)
        data = data or {}

        existing = self.fetch_one(
            f"""
            SELECT *
            FROM {schema}.migration_source_datasets
            WHERE company_id=%s
            AND project_id=%s
            AND id=%s
            """,
            (
                company_id,
                project_id,
                dataset_id,
            ),
            cur=cur,
        )

        if not existing:
            raise ValueError(
                "Migration dataset not found."
            )

        entity_code = data.get(
            "entity_code",
            existing.get("entity_code"),
        )

        if entity_code:
            catalog = self.fetch_one(
                f"""
                SELECT code
                FROM {schema}.migration_entity_catalog
                WHERE code=%s
                AND is_active=TRUE
                """,
                (
                    str(entity_code).strip(),
                ),
                cur=cur,
            )

            if not catalog:
                raise ValueError(
                    f"Unknown migration entity: "
                    f"{entity_code}"
                )

            entity_code = str(
                entity_code
            ).strip()
        else:
            entity_code = None

        header_row = int(
            data.get(
                "header_row",
                existing.get("header_row")
                or 1,
            )
        )

        data_start_row = int(
            data.get(
                "data_start_row",
                existing.get("data_start_row")
                or max(
                    header_row + 1,
                    1,
                ),
            )
        )

        data_end_row = data.get(
            "data_end_row",
            existing.get("data_end_row"),
        )

        if data_end_row in {
            "",
            None,
        }:
            data_end_row = None
        else:
            data_end_row = int(
                data_end_row
            )

        if header_row < 0:
            raise ValueError(
                "Header row cannot be negative."
            )

        if data_start_row < 1:
            raise ValueError(
                "Data start row must be at least 1."
            )

        if (
            data_end_row is not None
            and data_end_row < data_start_row
        ):
            raise ValueError(
                "Data end row cannot be before "
                "the data start row."
            )

        dataset_status = (
            "configured"
            if entity_code
            else "pending"
        )

        row = self.fetch_one(
            f"""
            UPDATE {schema}.migration_source_datasets
            SET
                dataset_name=%s,
                entity_code=%s,
                header_row=%s,
                data_start_row=%s,
                data_end_row=%s,
                delimiter=%s,
                encoding=%s,
                date_format=%s,
                decimal_separator=%s,
                thousands_separator=%s,
                dataset_status=%s,
                is_selected=%s,
                settings_json=%s::jsonb,
                metadata_json=%s::jsonb,
                updated_by_user_id=%s,
                updated_at=NOW()
            WHERE company_id=%s
            AND project_id=%s
            AND id=%s
            RETURNING *
            """,
            (
                str(
                    data.get(
                        "dataset_name",
                        existing.get(
                            "dataset_name"
                        ),
                    )
                    or ""
                ).strip(),

                entity_code,
                header_row,
                data_start_row,
                data_end_row,

                data.get(
                    "delimiter",
                    existing.get("delimiter"),
                ),

                data.get(
                    "encoding",
                    existing.get("encoding"),
                ),

                data.get(
                    "date_format",
                    existing.get("date_format"),
                ),

                data.get(
                    "decimal_separator",
                    existing.get(
                        "decimal_separator"
                    ),
                ),

                data.get(
                    "thousands_separator",
                    existing.get(
                        "thousands_separator"
                    ),
                ),

                dataset_status,

                bool(
                    data.get(
                        "is_selected",
                        existing.get(
                            "is_selected",
                        ),
                    )
                ),

                self._migration_json_dump(
                    data.get(
                        "settings_json",
                        data.get(
                            "settings",
                            existing.get(
                                "settings_json"
                            ) or {},
                        ),
                    ),
                    {},
                ),

                self._migration_json_dump(
                    data.get(
                        "metadata_json",
                        data.get(
                            "metadata",
                            existing.get(
                                "metadata_json"
                            ) or {},
                        ),
                    ),
                    {},
                ),

                user_id,
                company_id,
                project_id,
                dataset_id,
            ),
            cur=cur,
        )

        self.execute_sql(
            f"""
            INSERT INTO {schema}.migration_file_events (
                company_id,
                project_id,
                source_file_id,
                event_type,
                message,
                details_json,
                actor_user_id,
                created_at
            )
            VALUES (
                %s,%s,%s,
                'configured',
                %s,
                %s::jsonb,
                %s,
                NOW()
            )
            """,
            (
                company_id,
                project_id,
                existing["source_file_id"],
                f"Configured dataset "
                f"{row.get('dataset_name')}",
                self._migration_json_dump(
                    {
                        "dataset_id":
                            dataset_id,
                        "entity_code":
                            entity_code,
                        "header_row":
                            header_row,
                        "data_start_row":
                            data_start_row,
                    },
                    {},
                ),
                user_id,
            ),
            cur=cur,
        )

        return self.fetch_one(
            f"""
            SELECT
                d.*,
                f.original_name
                    AS source_file_name,
                c.label AS entity_label
            FROM {schema}.migration_source_datasets d
            JOIN {schema}.migration_source_files f
            ON f.id=d.source_file_id
            LEFT JOIN {schema}.migration_entity_catalog c
            ON c.code=d.entity_code
            WHERE d.company_id=%s
            AND d.project_id=%s
            AND d.id=%s
            """,
            (
                company_id,
                project_id,
                dataset_id,
            ),
            cur=cur,
        )

    def migration_source_file_remove(
        self,
        company_id: int,
        project_id: int,
        file_id: int,
        *,
        user_id: int | None = None,
        cur=None,
    ) -> dict:
        company_id = int(company_id)
        project_id = int(project_id)
        file_id = int(file_id)
        schema = self.company_schema(company_id)

        file_row = self.fetch_one(
            f"""
            SELECT *
            FROM {schema}.migration_source_files
            WHERE company_id=%s
            AND project_id=%s
            AND id=%s
            """,
            (
                company_id,
                project_id,
                file_id,
            ),
            cur=cur,
        )

        if not file_row:
            raise ValueError(
                "Migration source file not found."
            )

        if file_row.get("file_status") == "removed":
            return file_row

        self.execute_sql(
            f"""
            UPDATE {schema}.migration_source_files
            SET
                file_status='removed',
                removed_at=NOW(),
                updated_at=NOW()
            WHERE company_id=%s
            AND project_id=%s
            AND id=%s
            """,
            (
                company_id,
                project_id,
                file_id,
            ),
            cur=cur,
        )

        self.execute_sql(
            f"""
            UPDATE {schema}.migration_source_datasets
            SET
                dataset_status='ignored',
                is_selected=FALSE,
                updated_by_user_id=%s,
                updated_at=NOW()
            WHERE company_id=%s
            AND project_id=%s
            AND source_file_id=%s
            """,
            (
                user_id,
                company_id,
                project_id,
                file_id,
            ),
            cur=cur,
        )

        self.execute_sql(
            f"""
            INSERT INTO {schema}.migration_file_events (
                company_id,
                project_id,
                source_file_id,
                event_type,
                message,
                details_json,
                actor_user_id,
                created_at
            )
            VALUES (
                %s,%s,%s,
                'removed',
                %s,
                '{{}}'::jsonb,
                %s,
                NOW()
            )
            """,
            (
                company_id,
                project_id,
                file_id,
                f"Removed "
                f"{file_row.get('original_name')}",
                user_id,
            ),
            cur=cur,
        )

        remaining = int(
            self.fetch_val(
                f"""
                SELECT COUNT(*)
                FROM {schema}.migration_source_files
                WHERE company_id=%s
                AND project_id=%s
                AND file_status <> 'removed'
                """,
                (
                    company_id,
                    project_id,
                ),
                cur=cur,
            ) or 0
        )

        if remaining == 0:
            self.execute_sql(
                f"""
                UPDATE {schema}.migration_projects
                SET
                    status=CASE
                        WHEN status='files_uploaded'
                        THEN 'configured'
                        ELSE status
                    END,
                    updated_by_user_id=%s,
                    updated_at=NOW()
                WHERE company_id=%s
                AND id=%s
                """,
                (
                    user_id,
                    company_id,
                    project_id,
                ),
                cur=cur,
            )

        return {
            "id": file_id,
            "removed": True,
            "remaining_files": remaining,
        }

