    def migration_reference_scan(
        self,
        company_id:int,
        project_id:int,
        *,
        user_id:int|None=None,
        cur=None,
    )->dict:
        company_id=int(company_id)
        project_id=int(project_id)
        schema=self.company_schema(company_id)

        mappings=self.migration_field_mappings_get(
            company_id,
            project_id,
            cur=cur,
        )

        definitions=self.migration_reference_fields()

        self.execute_sql(f"""
            DELETE FROM {schema}.migration_reference_values
            WHERE company_id=%s AND project_id=%s
        """,(company_id,project_id),cur=cur)

        found=0

        for dataset in mappings.get("datasets") or []:
            entity_code=dataset.get("entity_code")

            source_dataset=self.fetch_one(f"""
                SELECT metadata_json
                FROM {schema}.migration_source_datasets
                WHERE company_id=%s AND project_id=%s AND id=%s
            """,(company_id,project_id,dataset["dataset_id"]),cur=cur)

            metadata=self._migration_json(
                source_dataset.get("metadata_json") if source_dataset else {},
                {},
            )

            sample_rows=metadata.get("sample_rows") or []

            for reference_type,definition in definitions.items():
                if entity_code not in definition["entities"]:continue

                mapped_rows=[
                    row for row in dataset.get("rows") or []
                    if row.get("mapping_status")=="mapped"
                    and row.get("target_field_code") in definition["fields"]
                ]

                for mapping in mapped_rows:
                    source_name=mapping["source_name"]

                    counts={}

                    for row in sample_rows:
                        value=row.get(source_name)
                        if value in (None,""):continue

                        key=str(value).strip()
                        if not key:continue

                        counts[key]=counts.get(key,0)+1

                    for value,count in counts.items():
                        self.execute_sql(f"""
                            INSERT INTO {schema}.migration_reference_values(
                                company_id,project_id,dataset_id,
                                reference_type,source_value,source_label,
                                occurrence_count,sample_rows_json,
                                created_at,updated_at
                            )
                            VALUES(
                                %s,%s,%s,%s,%s,%s,%s,
                                '[]'::jsonb,
                                NOW(),NOW()
                            )
                            ON CONFLICT(
                                company_id,
                                project_id,
                                dataset_id,
                                reference_type,
                                source_value
                            )
                            DO UPDATE SET
                                occurrence_count=EXCLUDED.occurrence_count,
                                updated_at=NOW()
                        """,(
                            company_id,
                            project_id,
                            dataset["dataset_id"],
                            reference_type,
                            value,
                            value,
                            count,
                        ),cur=cur)

                        found+=1

        return {
            "project_id":project_id,
            "reference_count":found,
        }

    def migration_reference_auto(
        self,
        company_id:int,
        project_id:int,
        *,
        user_id:int|None=None,
        cur=None,
    )->dict:
        company_id=int(company_id)
        project_id=int(project_id)
        schema=self.company_schema(company_id)

        values=self.fetch_all(f"""
            SELECT reference_type,source_value,
                MAX(source_label) AS source_label
            FROM {schema}.migration_reference_values
            WHERE company_id=%s AND project_id=%s
            GROUP BY reference_type,source_value
            ORDER BY reference_type,source_value
        """,(company_id,project_id),cur=cur) or []

        target_cache={}

        for row in values:
            reference_type=row["reference_type"]

            if reference_type not in target_cache:
                try:
                    target_cache[reference_type]=self.migration_reference_targets(
                        company_id,
                        reference_type,
                        cur=cur,
                    )
                except Exception:
                    target_cache[reference_type]=[]

            best=None

            for target in target_cache[reference_type]:
                score=self.migration_reference_score(
                    row["source_value"],
                    row.get("source_label"),
                    target,
                )

                if best is None or score>best["confidence"]:
                    best={
                        "target":target,
                        "confidence":score,
                    }

            matched=bool(best and best["confidence"]>=75)

            self.execute_sql(f"""
                INSERT INTO {schema}.migration_reference_mappings(
                    company_id,project_id,
                    reference_type,source_value,source_label,
                    target_id,target_code,target_label,
                    mapping_action,mapping_method,confidence,
                    is_approved,
                    created_by_user_id,updated_by_user_id,
                    created_at,updated_at
                )
                VALUES(
                    %s,%s,%s,%s,%s,
                    %s,%s,%s,
                    %s,'auto',%s,FALSE,
                    %s,%s,
                    NOW(),NOW()
                )
                ON CONFLICT(
                    company_id,
                    project_id,
                    reference_type,
                    source_value
                )
                DO UPDATE SET
                    target_id=EXCLUDED.target_id,
                    target_code=EXCLUDED.target_code,
                    target_label=EXCLUDED.target_label,
                    mapping_action=EXCLUDED.mapping_action,
                    mapping_method='auto',
                    confidence=EXCLUDED.confidence,
                    is_approved=FALSE,
                    updated_by_user_id=EXCLUDED.updated_by_user_id,
                    updated_at=NOW()
            """,(
                company_id,
                project_id,
                reference_type,
                row["source_value"],
                row.get("source_label"),

                best["target"]["id"] if matched else None,
                best["target"]["code"] if matched else None,
                best["target"]["label"] if matched else None,

                "map" if matched else "create",
                best["confidence"] if best else 0,

                user_id,
                user_id,
            ),cur=cur)

        return self.migration_reference_mapping_get(
            company_id,
            project_id,
            cur=cur,
        )
        

    def migration_reference_mapping_get(
        self,
        company_id:int,
        project_id:int,
        *,
        cur=None,
    )->dict:
        company_id=int(company_id)
        project_id=int(project_id)
        schema=self.company_schema(company_id)

        values=self.fetch_all(f"""
            SELECT
                v.reference_type,
                v.source_value,
                MAX(v.source_label) AS source_label,
                SUM(v.occurrence_count)::BIGINT AS occurrence_count,

                m.target_id,
                m.target_code,
                m.target_label,
                m.mapping_action,
                m.mapping_method,
                m.confidence,
                m.is_approved,
                m.notes

            FROM {schema}.migration_reference_values v

            LEFT JOIN {schema}.migration_reference_mappings m
            ON m.company_id=v.company_id
            AND m.project_id=v.project_id
            AND m.reference_type=v.reference_type
            AND m.source_value=v.source_value

            WHERE v.company_id=%s
            AND v.project_id=%s

            GROUP BY
                v.reference_type,
                v.source_value,
                m.target_id,
                m.target_code,
                m.target_label,
                m.mapping_action,
                m.mapping_method,
                m.confidence,
                m.is_approved,
                m.notes

            ORDER BY
                v.reference_type,
                v.source_value
        """,(company_id,project_id),cur=cur) or []

        groups={}

        for row in values:
            reference_type=row["reference_type"]

            groups.setdefault(reference_type,{
                "reference_type":reference_type,
                "rows":[],
                "targets":[],
            })

            groups[reference_type]["rows"].append({
                **row,
                "confidence":float(row.get("confidence") or 0),
                "mapping_action":row.get("mapping_action") or "create",
                "mapping_method":row.get("mapping_method") or "manual",
                "is_approved":bool(row.get("is_approved")),
            })

        for reference_type,group in groups.items():
            try:
                group["targets"]=self.migration_reference_targets(
                    company_id,
                    reference_type,
                    cur=cur,
                )
            except Exception:
                group["targets"]=[]

            group["unresolved_count"]=sum(
                1 for row in group["rows"]
                if row["mapping_action"]=="map" and not row.get("target_id")
            )

            group["pending_count"]=sum(
                1 for row in group["rows"]
                if not row.get("is_approved")
            )

            group["is_complete"]=(
                group["unresolved_count"]==0
                and group["pending_count"]==0
            )

        groups_list=list(groups.values())

        return {
            "project_id":project_id,
            "groups":groups_list,
            "reference_count":sum(len(group["rows"]) for group in groups_list),
            "group_count":len(groups_list),
            "unresolved_count":sum(group["unresolved_count"] for group in groups_list),
            "pending_count":sum(group["pending_count"] for group in groups_list),
            "complete_count":sum(1 for group in groups_list if group["is_complete"]),
        }

    def migration_reference_mapping_save(
        self,
        company_id:int,
        project_id:int,
        mappings:list[dict],
        *,
        user_id:int|None=None,
        cur=None,
    )->dict:
        company_id=int(company_id)
        project_id=int(project_id)
        schema=self.company_schema(company_id)

        if not isinstance(mappings,list):
            raise ValueError("mappings must be a list.")

        allowed_types=set(self.migration_reference_fields())
        allowed_actions={"map","create","ignore"}

        for item in mappings:
            reference_type=str(item.get("reference_type") or "").strip().lower()
            source_value=str(item.get("source_value") or "").strip()
            action=str(item.get("mapping_action") or "map").strip().lower()

            if reference_type not in allowed_types:
                raise ValueError(f"Unsupported reference type: {reference_type}")

            if not source_value:
                raise ValueError("Source reference value is required.")

            if action not in allowed_actions:
                raise ValueError(f"Unsupported mapping action: {action}")

            target_id=item.get("target_id")
            target_code=item.get("target_code")
            target_label=item.get("target_label")

            if action=="map" and not target_id:
                raise ValueError(
                    f'Target is required for "{source_value}".'
                )

            if action!="map":
                target_id=None
                target_code=None
                target_label=None

            self.execute_sql(f"""
                INSERT INTO {schema}.migration_reference_mappings(
                    company_id,project_id,
                    reference_type,source_value,source_label,
                    target_id,target_code,target_label,
                    mapping_action,mapping_method,confidence,
                    is_approved,notes,
                    created_by_user_id,updated_by_user_id,
                    created_at,updated_at
                )
                VALUES(
                    %s,%s,%s,%s,%s,
                    %s,%s,%s,
                    %s,'manual',%s,
                    TRUE,%s,
                    %s,%s,
                    NOW(),NOW()
                )
                ON CONFLICT(
                    company_id,
                    project_id,
                    reference_type,
                    source_value
                )
                DO UPDATE SET
                    source_label=EXCLUDED.source_label,
                    target_id=EXCLUDED.target_id,
                    target_code=EXCLUDED.target_code,
                    target_label=EXCLUDED.target_label,
                    mapping_action=EXCLUDED.mapping_action,
                    mapping_method='manual',
                    confidence=EXCLUDED.confidence,
                    is_approved=TRUE,
                    notes=EXCLUDED.notes,
                    updated_by_user_id=EXCLUDED.updated_by_user_id,
                    updated_at=NOW()
            """,(
                company_id,
                project_id,
                reference_type,
                source_value,
                item.get("source_label"),

                target_id,
                target_code,
                target_label,

                action,
                float(item.get("confidence") or 0),
                item.get("notes"),

                user_id,
                user_id,
            ),cur=cur)

        return self.migration_reference_mapping_get(
            company_id,
            project_id,
            cur=cur,
        )

    def migration_reference_mapping_reset(
        self,
        company_id:int,
        project_id:int,
        *,
        cur=None,
    )->dict:
        company_id=int(company_id)
        project_id=int(project_id)
        schema=self.company_schema(company_id)

        self.execute_sql(f"""
            DELETE FROM {schema}.migration_reference_mappings
            WHERE company_id=%s AND project_id=%s
        """,(company_id,project_id),cur=cur)

        return self.migration_reference_mapping_get(
            company_id,
            project_id,
            cur=cur,
        )

    def migration_reference_mapping_validate(
        self,
        company_id:int,
        project_id:int,
        *,
        cur=None,
    )->dict:
        result=self.migration_reference_mapping_get(
            company_id,
            project_id,
            cur=cur,
        )

        issues=[]

        for group in result["groups"]:
            for row in group["rows"]:
                if row["mapping_action"]=="map" and not row.get("target_id"):
                    issues.append({
                        "reference_type":group["reference_type"],
                        "source_value":row["source_value"],
                        "code":"TARGET_REQUIRED",
                        "message":f'No target selected for "{row["source_value"]}".',
                    })

                if not row.get("is_approved"):
                    issues.append({
                        "reference_type":group["reference_type"],
                        "source_value":row["source_value"],
                        "code":"MAPPING_NOT_APPROVED",
                        "message":f'Mapping for "{row["source_value"]}" has not been approved.',
                    })

        return {
            "valid":not issues,
            "issues":issues,
            **result,
        }

    def migration_ppe_datasets(self,company_id:int,project_id:int,*,cur=None)->list[dict]:
        company_id,project_id=int(company_id),int(project_id)
        schema=self.company_schema(company_id)

        return self.fetch_all(f"""
            SELECT
                d.id AS dataset_id,
                d.dataset_name,
                d.source_file_id,
                f.original_name AS source_file_name,
                d.record_count,
                d.column_count,
                d.dataset_status
            FROM {schema}.migration_source_datasets d
            JOIN {schema}.migration_source_files f ON f.id=d.source_file_id
            WHERE d.company_id=%s
            AND d.project_id=%s
            AND d.entity_code='fixed_assets'
            AND d.is_selected=TRUE
            ORDER BY d.id
        """,(company_id,project_id),cur=cur) or []

    def migration_ppe_settings_get(self,company_id:int,project_id:int,dataset_id:int,*,cur=None)->dict:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)

        project=self.fetch_one(f"""
            SELECT cutover_date
            FROM {schema}.migration_projects
            WHERE company_id=%s AND id=%s
        """,(company_id,project_id),cur=cur)

        if not project:
            raise ValueError("Migration project not found.")

        row=self.fetch_one(f"""
            SELECT *
            FROM {schema}.migration_ppe_settings
            WHERE company_id=%s AND project_id=%s AND dataset_id=%s
        """,(company_id,project_id,dataset_id),cur=cur)

        if row:
            row["settings_json"]=self._migration_json(row.get("settings_json"),{})
            row["metadata_json"]=self._migration_json(row.get("metadata_json"),{})
            return row

        return {
            "company_id":company_id,
            "project_id":project_id,
            "dataset_id":dataset_id,
            "default_entry_mode":"opening_balance",
            "default_opening_as_at":project.get("cutover_date"),
            "default_posting_date":project.get("cutover_date"),
            "default_accounting_standard":"ias16",
            "default_measurement_basis":"cost",
            "default_depreciation_method":"SL",
            "use_project_cutover_as_opening_date":True,
            "create_missing_asset_classes":False,
            "require_asset_code":True,
            "require_gl_mapping":True,
            "settings_json":{},
            "metadata_json":{},
        }

    def migration_ppe_settings_save(
        self,company_id:int,project_id:int,dataset_id:int,data:dict,
        *,user_id:int|None=None,cur=None
    )->dict:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)
        data=data or {}

        current=self.migration_ppe_settings_get(
            company_id,project_id,dataset_id,cur=cur
        )

        entry_mode=str(data.get("default_entry_mode") or current["default_entry_mode"]).strip().lower()
        standard=str(data.get("default_accounting_standard") or current["default_accounting_standard"]).strip().lower()
        basis=str(data.get("default_measurement_basis") or current["default_measurement_basis"]).strip().lower()
        method=str(data.get("default_depreciation_method") or current["default_depreciation_method"]).strip().upper()

        if entry_mode not in {"opening_balance","acquisition"}:
            raise ValueError("Invalid PPE entry mode.")
        if standard not in {"ias16","ias38","ias40"}:
            raise ValueError("Invalid PPE accounting standard.")
        if basis not in {"cost","revaluation"}:
            raise ValueError("Invalid PPE measurement basis.")
        if method not in {"SL","RB","UOP","APP"}:
            raise ValueError("Invalid PPE depreciation method.")

        self.execute_sql(f"""
            INSERT INTO {schema}.migration_ppe_settings(
                company_id,project_id,dataset_id,
                default_entry_mode,default_opening_as_at,default_posting_date,
                default_accounting_standard,default_measurement_basis,
                default_depreciation_method,
                use_project_cutover_as_opening_date,
                create_missing_asset_classes,require_asset_code,require_gl_mapping,
                settings_json,metadata_json,
                created_by_user_id,updated_by_user_id,created_at,updated_at
            )
            VALUES(
                %s,%s,%s,%s,%s,%s,%s,%s,%s,
                %s,%s,%s,%s,%s::jsonb,%s::jsonb,%s,%s,NOW(),NOW()
            )
            ON CONFLICT(company_id,project_id,dataset_id)
            DO UPDATE SET
                default_entry_mode=EXCLUDED.default_entry_mode,
                default_opening_as_at=EXCLUDED.default_opening_as_at,
                default_posting_date=EXCLUDED.default_posting_date,
                default_accounting_standard=EXCLUDED.default_accounting_standard,
                default_measurement_basis=EXCLUDED.default_measurement_basis,
                default_depreciation_method=EXCLUDED.default_depreciation_method,
                use_project_cutover_as_opening_date=EXCLUDED.use_project_cutover_as_opening_date,
                create_missing_asset_classes=EXCLUDED.create_missing_asset_classes,
                require_asset_code=EXCLUDED.require_asset_code,
                require_gl_mapping=EXCLUDED.require_gl_mapping,
                settings_json=EXCLUDED.settings_json,
                metadata_json=EXCLUDED.metadata_json,
                updated_by_user_id=EXCLUDED.updated_by_user_id,
                updated_at=NOW()
        """,(
            company_id,project_id,dataset_id,
            entry_mode,
            data.get("default_opening_as_at") or current.get("default_opening_as_at"),
            data.get("default_posting_date") or current.get("default_posting_date"),
            standard,basis,method,
            bool(data.get("use_project_cutover_as_opening_date",current.get("use_project_cutover_as_opening_date",True))),
            bool(data.get("create_missing_asset_classes",current.get("create_missing_asset_classes",False))),
            bool(data.get("require_asset_code",current.get("require_asset_code",True))),
            bool(data.get("require_gl_mapping",current.get("require_gl_mapping",True))),
            self._migration_json_dump(data.get("settings_json") or current.get("settings_json"),{}),
            self._migration_json_dump(data.get("metadata_json") or current.get("metadata_json"),{}),
            user_id,user_id
        ),cur=cur)

        return self.migration_ppe_settings_get(
            company_id,project_id,dataset_id,cur=cur
        )

    def migration_ppe_source_classes(
        self,company_id:int,project_id:int,dataset_id:int,*,cur=None
    )->list[dict]:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)

        mapping=self.migration_field_mapping_dataset(
            company_id,project_id,dataset_id,cur=cur
        )

        class_map=next((
            row for row in mapping.get("rows") or []
            if row.get("mapping_status")=="mapped"
            and row.get("target_field_code")=="asset_class"
        ),None)

        if not class_map:
            return []

        dataset=self.fetch_one(f"""
            SELECT metadata_json
            FROM {schema}.migration_source_datasets
            WHERE company_id=%s AND project_id=%s AND id=%s
        """,(company_id,project_id,dataset_id),cur=cur)

        metadata=self._migration_json(dataset.get("metadata_json") if dataset else {},{})
        sample_rows=metadata.get("sample_rows") or {}

        if not isinstance(sample_rows,list):
            sample_rows=[]

        counts={}

        for row in sample_rows:
            value=str(row.get(class_map["source_name"]) or "").strip()
            if value:
                counts[value]=counts.get(value,0)+1

        return [
            {"source_class":key,"sample_count":value}
            for key,value in sorted(counts.items())
        ]

    def migration_ppe_target_classes(self,company_id:int,*,cur=None)->dict:
        company_id=int(company_id)
        schema=self.company_schema(company_id)

        rows=self.fetch_all(f"""
            SELECT DISTINCT
                asset_class,
                asset_class_group,
                accounting_standard,
                measurement_basis,
                depreciation_method,
                useful_life_months,
                asset_account_code,
                accum_dep_account_code,
                dep_expense_account_code,
                disposal_gain_account_code,
                disposal_loss_account_code
            FROM {schema}.assets
            WHERE company_id=%s
            AND NULLIF(BTRIM(asset_class),'') IS NOT NULL
            ORDER BY asset_class
        """,(company_id,),cur=cur) or []

        groups=[
            "Land","Buildings","Land and buildings","Plant and machinery",
            "Vehicles","Motorcycles / bikes","Bicycles","Scooters","Heavy vehicles",
            "Construction equipment","Mining equipment","Manufacturing equipment",
            "Computer equipment","Office equipment","Furniture and fittings",
            "Tools and small equipment","Leasehold improvements",
            "Assets under construction","Other PPE",
            "Investment property - Land","Investment property - Buildings",
            "Investment property - Under construction",
            "Goodwill","Patents","Copyrights","Trademarks","Software","Licences",
            "Franchises","Customer lists","Research and development",
            "Other intangible assets",
        ]

        return {"existing_classes":rows,"class_groups":groups}

    def migration_ppe_class_suggestion(
        self,source_class:str,targets:dict
    )->dict:
        source=str(source_class or "").strip()
        normalized=self.migration_normalise_heading(source)

        best=None

        for row in targets.get("existing_classes") or []:
            target=str(row.get("asset_class") or "").strip()
            target_norm=self.migration_normalise_heading(target)

            score=0.0
            if normalized and normalized==target_norm:
                score=100.0
            elif normalized and target_norm and (
                normalized in target_norm or target_norm in normalized
            ):
                score=90.0

            if best is None or score>best["confidence"]:
                best={"row":row,"confidence":score}

        if best and best["confidence"]>=80:
            row=best["row"]
            return {
                "target_asset_class":row.get("asset_class"),
                "target_asset_class_group":row.get("asset_class_group"),
                "accounting_standard":row.get("accounting_standard") or "ias16",
                "measurement_basis":row.get("measurement_basis") or "cost",
                "depreciation_method":row.get("depreciation_method"),
                "useful_life_months":row.get("useful_life_months"),
                "asset_account_code":row.get("asset_account_code"),
                "accum_dep_account_code":row.get("accum_dep_account_code"),
                "dep_expense_account_code":row.get("dep_expense_account_code"),
                "disposal_gain_account_code":row.get("disposal_gain_account_code"),
                "disposal_loss_account_code":row.get("disposal_loss_account_code"),
                "confidence":best["confidence"],
            }

        group=None

        keywords={
            "vehicle":"Vehicles","motor":"Vehicles","car":"Vehicles",
            "computer":"Computer equipment","laptop":"Computer equipment",
            "building":"Buildings","land":"Land",
            "furniture":"Furniture and fittings","office":"Office equipment",
            "plant":"Plant and machinery","machine":"Plant and machinery",
            "software":"Software","patent":"Patents","licence":"Licences",
            "license":"Licences",
        }

        low=source.lower()
        for keyword,target_group in keywords.items():
            if keyword in low:
                group=target_group
                break

        standard=(
            "ias40" if group and group.startswith("Investment property")
            else "ias38" if group in {
                "Goodwill","Patents","Copyrights","Trademarks","Software",
                "Licences","Franchises","Customer lists",
                "Research and development","Other intangible assets"
            }
            else "ias16"
        )

        return {
            "target_asset_class":source or None,
            "target_asset_class_group":group,
            "accounting_standard":standard,
            "measurement_basis":"cost",
            "depreciation_method":None,
            "useful_life_months":None,
            "asset_account_code":None,
            "accum_dep_account_code":None,
            "dep_expense_account_code":None,
            "disposal_gain_account_code":None,
            "disposal_loss_account_code":None,
            "confidence":60.0 if group else 0.0,
        }

    def migration_ppe_class_save(
        self,company_id:int,project_id:int,dataset_id:int,data:dict,
        *,user_id:int|None=None,cur=None
    )->dict:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)
        data=data or {}

        source_class=str(data.get("source_class") or "").strip()
        target_class=str(data.get("target_asset_class") or "").strip()
        target_group=str(data.get("target_asset_class_group") or "").strip() or None
        standard=str(data.get("accounting_standard") or "ias16").strip().lower()
        basis=str(data.get("measurement_basis") or "cost").strip().lower()
        method=str(data.get("depreciation_method") or "").strip().upper() or None

        if not source_class:
            raise ValueError("Source asset class is required.")
        if not target_class:
            raise ValueError("FinSage asset class is required.")
        if standard not in {"ias16","ias38","ias40"}:
            raise ValueError("Invalid accounting standard.")
        if basis not in {"cost","revaluation"}:
            raise ValueError("Invalid measurement basis.")
        if method and method not in {"SL","RB","UOP","APP"}:
            raise ValueError("Invalid depreciation method.")

        useful_life=data.get("useful_life_months")
        useful_life=int(useful_life) if useful_life not in (None,"") else None

        if method=="SL" and useful_life is not None and useful_life<=0:
            raise ValueError("Straight-line useful life must be greater than zero.")

        self.execute_sql(f"""
            INSERT INTO {schema}.migration_ppe_class_mappings(
                company_id,project_id,dataset_id,
                source_class,source_class_group,
                target_asset_class,target_asset_class_group,
                accounting_standard,measurement_basis,
                depreciation_method,useful_life_months,rb_rate_percent,
                asset_account_code,accum_dep_account_code,dep_expense_account_code,
                disposal_gain_account_code,disposal_loss_account_code,
                impairment_loss_account_code,impairment_reversal_account_code,
                accum_impairment_account_code,
                revaluation_reserve_account_code,
                revaluation_surplus_to_pnl_account_code,
                revaluation_deficit_pnl_account_code,
                rental_income_account_code,fv_gain_loss_account_code,
                mapping_method,confidence,is_approved,
                metadata_json,
                created_by_user_id,updated_by_user_id,
                created_at,updated_at
            )
            VALUES(
                %s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,
                %s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,
                %s,%s,%s,%s::jsonb,%s,%s,NOW(),NOW()
            )
            ON CONFLICT(company_id,project_id,dataset_id,source_class)
            DO UPDATE SET
                source_class_group=EXCLUDED.source_class_group,
                target_asset_class=EXCLUDED.target_asset_class,
                target_asset_class_group=EXCLUDED.target_asset_class_group,
                accounting_standard=EXCLUDED.accounting_standard,
                measurement_basis=EXCLUDED.measurement_basis,
                depreciation_method=EXCLUDED.depreciation_method,
                useful_life_months=EXCLUDED.useful_life_months,
                rb_rate_percent=EXCLUDED.rb_rate_percent,
                asset_account_code=EXCLUDED.asset_account_code,
                accum_dep_account_code=EXCLUDED.accum_dep_account_code,
                dep_expense_account_code=EXCLUDED.dep_expense_account_code,
                disposal_gain_account_code=EXCLUDED.disposal_gain_account_code,
                disposal_loss_account_code=EXCLUDED.disposal_loss_account_code,
                impairment_loss_account_code=EXCLUDED.impairment_loss_account_code,
                impairment_reversal_account_code=EXCLUDED.impairment_reversal_account_code,
                accum_impairment_account_code=EXCLUDED.accum_impairment_account_code,
                revaluation_reserve_account_code=EXCLUDED.revaluation_reserve_account_code,
                revaluation_surplus_to_pnl_account_code=EXCLUDED.revaluation_surplus_to_pnl_account_code,
                revaluation_deficit_pnl_account_code=EXCLUDED.revaluation_deficit_pnl_account_code,
                rental_income_account_code=EXCLUDED.rental_income_account_code,
                fv_gain_loss_account_code=EXCLUDED.fv_gain_loss_account_code,
                mapping_method=EXCLUDED.mapping_method,
                confidence=EXCLUDED.confidence,
                is_approved=EXCLUDED.is_approved,
                metadata_json=EXCLUDED.metadata_json,
                updated_by_user_id=EXCLUDED.updated_by_user_id,
                updated_at=NOW()
        """,(
            company_id,project_id,dataset_id,
            source_class,data.get("source_class_group"),
            target_class,target_group,standard,basis,method,useful_life,
            data.get("rb_rate_percent"),
            data.get("asset_account_code"),data.get("accum_dep_account_code"),
            data.get("dep_expense_account_code"),data.get("disposal_gain_account_code"),
            data.get("disposal_loss_account_code"),data.get("impairment_loss_account_code"),
            data.get("impairment_reversal_account_code"),data.get("accum_impairment_account_code"),
            data.get("revaluation_reserve_account_code"),
            data.get("revaluation_surplus_to_pnl_account_code"),
            data.get("revaluation_deficit_pnl_account_code"),
            data.get("rental_income_account_code"),data.get("fv_gain_loss_account_code"),
            "manual",float(data.get("confidence") or 100),True,
            self._migration_json_dump(data.get("metadata_json"),{}),
            user_id,user_id
        ),cur=cur)

        return self.fetch_one(f"""
            SELECT *
            FROM {schema}.migration_ppe_class_mappings
            WHERE company_id=%s AND project_id=%s
            AND dataset_id=%s AND source_class=%s
        """,(company_id,project_id,dataset_id,source_class),cur=cur)

    def migration_ppe_mapping_get(
        self,company_id:int,project_id:int,dataset_id:int,*,cur=None
    )->dict:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)

        settings=self.migration_ppe_settings_get(
            company_id,project_id,dataset_id,cur=cur
        )

        source_classes=self.migration_ppe_source_classes(
            company_id,project_id,dataset_id,cur=cur
        )

        saved=self.fetch_all(f"""
            SELECT *
            FROM {schema}.migration_ppe_class_mappings
            WHERE company_id=%s AND project_id=%s AND dataset_id=%s
            ORDER BY source_class
        """,(company_id,project_id,dataset_id),cur=cur) or []

        saved_by_class={row["source_class"]:row for row in saved}
        targets=self.migration_ppe_target_classes(company_id,cur=cur)

        mappings=[]

        for source in source_classes:
            row=saved_by_class.get(source["source_class"])

            if not row:
                suggestion=self.migration_ppe_class_suggestion(
                    source["source_class"],targets
                )

                row={
                    **source,
                    **suggestion,
                    "mapping_method":"auto",
                    "is_approved":False,
                }
            else:
                row={**source,**row}

            mappings.append(row)

        complete=bool(mappings) and all(
            row.get("is_approved")
            and row.get("target_asset_class")
            and row.get("target_asset_class_group")
            and (
                not settings.get("require_gl_mapping")
                or row.get("asset_account_code")
            )
            for row in mappings
        )

        return {
            "settings":settings,
            "mappings":mappings,
            "targets":targets,
            "class_count":len(mappings),
            "approved_count":sum(1 for row in mappings if row.get("is_approved")),
            "is_complete":complete,
        }

    def migration_ppe_payload_preview(
        self,company_id:int,project_id:int,dataset_id:int,*,cur=None
    )->dict:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)

        field_mapping=self.migration_field_mapping_dataset(
            company_id,project_id,dataset_id,cur=cur
        )

        ppe=self.migration_ppe_mapping_get(
            company_id,project_id,dataset_id,cur=cur
        )

        settings=ppe["settings"]

        dataset=self.fetch_one(f"""
            SELECT metadata_json
            FROM {schema}.migration_source_datasets
            WHERE company_id=%s AND project_id=%s AND id=%s
        """,(company_id,project_id,dataset_id),cur=cur)

        metadata=self._migration_json(dataset.get("metadata_json") if dataset else {},{})
        sample_rows=metadata.get("sample_rows") or []

        source_to_target={
            row["source_name"]:row["target_field_code"]
            for row in field_mapping.get("rows") or []
            if row.get("mapping_status")=="mapped"
            and row.get("target_field_code")
        }

        class_lookup={
            row["source_class"]:row
            for row in ppe["mappings"]
            if row.get("is_approved")
        }

        previews=[]

        for index,source_row in enumerate(sample_rows[:20],start=1):
            normalized={}

            for source_name,target_code in source_to_target.items():
                normalized[target_code]=source_row.get(source_name)

            source_class=str(normalized.get("asset_class") or "").strip()
            class_map=class_lookup.get(source_class) or {}

            useful_life_months=normalized.get("useful_life_months")

            if not useful_life_months and normalized.get("useful_life_years") not in (None,""):
                useful_life_months=int(
                    round(float(normalized["useful_life_years"])*12)
                )

            payload={
                "entry_mode":settings.get("default_entry_mode") or "opening_balance",
                "posting_date":settings.get("default_posting_date"),
                "asset_code":str(normalized.get("asset_code") or "").strip(),
                "asset_name":str(normalized.get("asset_name") or "").strip(),
                "asset_class":class_map.get("target_asset_class") or source_class,
                "asset_class_group":class_map.get("target_asset_class_group"),
                "category":normalized.get("category") or None,
                "location":normalized.get("location") or None,
                "serial_no":normalized.get("serial_no") or None,
                "notes":normalized.get("notes") or None,

                "acquisition_date":normalized.get("acquisition_date"),
                "available_for_use_date":normalized.get("available_for_use_date") or None,

                "cost":normalized.get("cost") or normalized.get("opening_cost") or 0,
                "residual_value":normalized.get("residual_value") or 0,

                "opening_as_at":normalized.get("opening_as_at")
                    or settings.get("default_opening_as_at"),

                "opening_cost":normalized.get("opening_cost")
                    or normalized.get("cost"),

                "opening_accum_dep":normalized.get("opening_accum_dep") or 0,
                "opening_impairment":normalized.get("opening_impairment") or 0,
                "opening_revaluation_surplus":
                    normalized.get("opening_revaluation_surplus") or 0,

                "depreciation_method":
                    str(normalized.get("depreciation_method")
                        or class_map.get("depreciation_method")
                        or settings.get("default_depreciation_method")
                        or "SL").upper(),

                "useful_life_months":
                    int(useful_life_months
                        or class_map.get("useful_life_months")
                        or 0),

                "rb_rate_percent":
                    normalized.get("rb_rate_percent")
                    or class_map.get("rb_rate_percent"),

                "uop_total_units":normalized.get("uop_total_units"),
                "uop_opening_reading":normalized.get("uop_opening_reading"),
                "uop_unit_name":normalized.get("uop_unit_name"),

                "accounting_standard":
                    class_map.get("accounting_standard")
                    or settings.get("default_accounting_standard")
                    or "ias16",

                "measurement_model":
                    class_map.get("measurement_basis")
                    or settings.get("default_measurement_basis")
                    or "cost",

                "asset_account_code":class_map.get("asset_account_code"),
                "accum_dep_account_code":class_map.get("accum_dep_account_code"),
                "dep_expense_account_code":class_map.get("dep_expense_account_code"),
                "disposal_gain_account_code":class_map.get("disposal_gain_account_code"),
                "disposal_loss_account_code":class_map.get("disposal_loss_account_code"),

                "vat_input_claimable":bool(normalized.get("vat_input_claimable") or False),
                "vat_recovery_percent":normalized.get("vat_recovery_percent") or 0,
            }

            cost=float(payload["cost"] or 0)
            accum=float(payload["opening_accum_dep"] or 0)
            impairment=float(payload["opening_impairment"] or 0)

            payload["calculated_carrying_amount"]=round(
                cost-accum-impairment,2
            )

            issues=[]

            if not payload["asset_code"]:
                issues.append("Asset code is required.")
            if not payload["asset_name"]:
                issues.append("Asset name is required.")
            if not payload["asset_class"]:
                issues.append("Asset class is required.")
            if not payload["acquisition_date"]:
                issues.append("Acquisition date is required.")
            if cost<=0:
                issues.append("Historical cost must be greater than zero.")
            if accum<0:
                issues.append("Accumulated depreciation cannot be negative.")
            if accum>cost:
                issues.append("Accumulated depreciation cannot exceed historical cost.")
            if impairment<0:
                issues.append("Opening impairment cannot be negative.")

            if payload["entry_mode"]=="opening_balance":
                if not payload["opening_as_at"]:
                    issues.append("Opening as at is required.")
                if not payload["posting_date"]:
                    issues.append("Posting date is required.")

            if settings.get("require_gl_mapping") and not payload["asset_account_code"]:
                issues.append("Asset cost account is not mapped.")

            if payload["depreciation_method"]!="APP":
                if not payload["accum_dep_account_code"]:
                    issues.append("Accumulated depreciation account is not mapped.")
                if not payload["dep_expense_account_code"]:
                    issues.append("Depreciation expense account is not mapped.")

            if payload["depreciation_method"]=="SL" and payload["useful_life_months"]<=0:
                issues.append("Useful life is required for straight-line depreciation.")

            if payload["depreciation_method"]=="RB" and float(payload["rb_rate_percent"] or 0)<=0:
                issues.append("Reducing balance rate is required.")

            previews.append({
                "row_number":index,
                "source":source_row,
                "payload":payload,
                "issues":issues,
                "valid":not issues,
            })

        return {
            "dataset_id":dataset_id,
            "rows":previews,
            "row_count":len(previews),
            "valid_count":sum(1 for row in previews if row["valid"]),
            "error_count":sum(1 for row in previews if not row["valid"]),
        }
        
    def migration_lease_datasets(
        self,
        company_id:int,
        project_id:int,
        *,
        cur=None,
    )->list[dict]:
        company_id,project_id=int(company_id),int(project_id)
        schema=self.company_schema(company_id)

        return self.fetch_all(f"""
            SELECT
                d.id AS dataset_id,
                d.dataset_name,
                d.record_count,
                d.column_count,
                d.dataset_status,
                f.original_name AS source_file_name
            FROM {schema}.migration_source_datasets d
            JOIN {schema}.migration_source_files f
            ON f.id=d.source_file_id
            WHERE d.company_id=%s
            AND d.project_id=%s
            AND d.entity_code='leases'
            AND d.is_selected=TRUE
            ORDER BY d.id
        """,(company_id,project_id),cur=cur) or []

    def migration_lease_settings_get(
        self,
        company_id:int,
        project_id:int,
        dataset_id:int,
        *,
        cur=None,
    )->dict:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)

        project=self.fetch_one(f"""
            SELECT cutover_date,default_currency
            FROM {schema}.migration_projects
            WHERE company_id=%s AND id=%s
        """,(company_id,project_id),cur=cur)

        if not project:
            raise ValueError("Migration project not found.")

        row=self.fetch_one(f"""
            SELECT *
            FROM {schema}.migration_lease_settings
            WHERE company_id=%s AND project_id=%s AND dataset_id=%s
        """,(company_id,project_id,dataset_id),cur=cur)

        if row:
            row["settings_json"]=self._migration_json(row.get("settings_json"),{})
            row["metadata_json"]=self._migration_json(row.get("metadata_json"),{})
            return row

        lease_accounts=self.get_lease_posting_accounts(company_id) or {}

        return {
            "company_id":company_id,
            "project_id":project_id,
            "dataset_id":dataset_id,

            "default_role":"lessee",
            "default_wizard_mode":"existing",
            "default_go_live_date":project.get("cutover_date"),
            "default_currency":project.get("default_currency"),

            "default_payment_frequency":"monthly",
            "default_payment_timing":"arrears",

            "default_billing_basis":"gross",
            "default_billing_frequency":"monthly",
            "default_billing_timing":"arrears",

            "lessee_rou_asset_account":lease_accounts.get("roa"),
            "lessee_liability_current_account":lease_accounts.get("liability_current"),
            "lessee_liability_noncurrent_account":lease_accounts.get("liability_noncurrent"),
            "lessee_interest_expense_account":lease_accounts.get("interest"),
            "lessee_depreciation_expense_account":lease_accounts.get("depreciation"),

            "lessor_receivable_current_account":None,
            "lessor_receivable_noncurrent_account":None,
            "lessor_revenue_account":None,
            "lessor_finance_income_account":None,
            "lessor_ar_account":None,
            "lessor_vat_output_account":None,
            "lessor_security_deposit_account":None,
            "lessor_accrued_rental_account":None,
            "lessor_deferred_rental_account":None,
            "lessor_initial_direct_cost_expense_account":None,
            "lessor_initial_direct_cost_asset_account":None,

            "require_counterparty_mapping":True,
            "require_account_mapping":True,
            "require_underlying_asset_for_lessor":True,

            "settings_json":{},
            "metadata_json":{},
        }

    def migration_lease_settings_save(
        self,
        company_id:int,
        project_id:int,
        dataset_id:int,
        data:dict,
        *,
        user_id:int|None=None,
        cur=None,
    )->dict:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)
        data=data or {}

        current=self.migration_lease_settings_get(
            company_id,project_id,dataset_id,cur=cur
        )

        role=str(data.get("default_role") or current["default_role"]).strip().lower()
        mode=str(data.get("default_wizard_mode") or current["default_wizard_mode"]).strip().lower()
        pay_freq=str(data.get("default_payment_frequency") or current["default_payment_frequency"]).strip().lower()
        pay_timing=str(data.get("default_payment_timing") or current["default_payment_timing"]).strip().lower()

        billing_basis=str(data.get("default_billing_basis") or current["default_billing_basis"]).strip().lower()
        billing_freq=str(data.get("default_billing_frequency") or current["default_billing_frequency"]).strip().lower()
        billing_timing=str(data.get("default_billing_timing") or current["default_billing_timing"]).strip().lower()

        if role not in {"lessee","lessor"}:
            raise ValueError("Lease role must be lessee or lessor.")
        if mode not in {"inception","existing"}:
            raise ValueError("Lease wizard mode must be inception or existing.")
        if pay_freq not in {"monthly","quarterly","annually"}:
            raise ValueError("Unsupported lessee payment frequency.")
        if pay_timing not in {"arrears","advance"}:
            raise ValueError("Unsupported lessee payment timing.")
        if billing_basis not in {"gross","net"}:
            raise ValueError("Lessor billing basis must be gross or net.")
        if billing_timing not in {"arrears","advance"}:
            raise ValueError("Lessor billing timing must be arrears or advance.")

        fields=[
            "lessee_rou_asset_account",
            "lessee_liability_current_account",
            "lessee_liability_noncurrent_account",
            "lessee_interest_expense_account",
            "lessee_depreciation_expense_account",

            "lessor_receivable_current_account",
            "lessor_receivable_noncurrent_account",
            "lessor_revenue_account",
            "lessor_finance_income_account",
            "lessor_ar_account",
            "lessor_vat_output_account",
            "lessor_security_deposit_account",
            "lessor_accrued_rental_account",
            "lessor_deferred_rental_account",
            "lessor_initial_direct_cost_expense_account",
            "lessor_initial_direct_cost_asset_account",
        ]

        values={
            field:data.get(field,current.get(field))
            for field in fields
        }

        self.execute_sql(f"""
            INSERT INTO {schema}.migration_lease_settings(
                company_id,project_id,dataset_id,
                default_role,default_wizard_mode,default_go_live_date,
                default_currency,
                default_payment_frequency,default_payment_timing,
                default_billing_basis,default_billing_frequency,default_billing_timing,

                lessee_rou_asset_account,
                lessee_liability_current_account,
                lessee_liability_noncurrent_account,
                lessee_interest_expense_account,
                lessee_depreciation_expense_account,

                lessor_receivable_current_account,
                lessor_receivable_noncurrent_account,
                lessor_revenue_account,
                lessor_finance_income_account,
                lessor_ar_account,
                lessor_vat_output_account,
                lessor_security_deposit_account,
                lessor_accrued_rental_account,
                lessor_deferred_rental_account,
                lessor_initial_direct_cost_expense_account,
                lessor_initial_direct_cost_asset_account,

                require_counterparty_mapping,
                require_account_mapping,
                require_underlying_asset_for_lessor,

                settings_json,metadata_json,
                created_by_user_id,updated_by_user_id,
                created_at,updated_at
            )
            VALUES(
                %s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,
                %s,%s,%s,%s,%s,
                %s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,
                %s,%s,%s,
                %s::jsonb,%s::jsonb,%s,%s,
                NOW(),NOW()
            )
            ON CONFLICT(company_id,project_id,dataset_id)
            DO UPDATE SET
                default_role=EXCLUDED.default_role,
                default_wizard_mode=EXCLUDED.default_wizard_mode,
                default_go_live_date=EXCLUDED.default_go_live_date,
                default_currency=EXCLUDED.default_currency,
                default_payment_frequency=EXCLUDED.default_payment_frequency,
                default_payment_timing=EXCLUDED.default_payment_timing,
                default_billing_basis=EXCLUDED.default_billing_basis,
                default_billing_frequency=EXCLUDED.default_billing_frequency,
                default_billing_timing=EXCLUDED.default_billing_timing,

                lessee_rou_asset_account=EXCLUDED.lessee_rou_asset_account,
                lessee_liability_current_account=EXCLUDED.lessee_liability_current_account,
                lessee_liability_noncurrent_account=EXCLUDED.lessee_liability_noncurrent_account,
                lessee_interest_expense_account=EXCLUDED.lessee_interest_expense_account,
                lessee_depreciation_expense_account=EXCLUDED.lessee_depreciation_expense_account,

                lessor_receivable_current_account=EXCLUDED.lessor_receivable_current_account,
                lessor_receivable_noncurrent_account=EXCLUDED.lessor_receivable_noncurrent_account,
                lessor_revenue_account=EXCLUDED.lessor_revenue_account,
                lessor_finance_income_account=EXCLUDED.lessor_finance_income_account,
                lessor_ar_account=EXCLUDED.lessor_ar_account,
                lessor_vat_output_account=EXCLUDED.lessor_vat_output_account,
                lessor_security_deposit_account=EXCLUDED.lessor_security_deposit_account,
                lessor_accrued_rental_account=EXCLUDED.lessor_accrued_rental_account,
                lessor_deferred_rental_account=EXCLUDED.lessor_deferred_rental_account,
                lessor_initial_direct_cost_expense_account=EXCLUDED.lessor_initial_direct_cost_expense_account,
                lessor_initial_direct_cost_asset_account=EXCLUDED.lessor_initial_direct_cost_asset_account,

                require_counterparty_mapping=EXCLUDED.require_counterparty_mapping,
                require_account_mapping=EXCLUDED.require_account_mapping,
                require_underlying_asset_for_lessor=EXCLUDED.require_underlying_asset_for_lessor,

                settings_json=EXCLUDED.settings_json,
                metadata_json=EXCLUDED.metadata_json,
                updated_by_user_id=EXCLUDED.updated_by_user_id,
                updated_at=NOW()
        """,(
            company_id,project_id,dataset_id,
            role,mode,
            data.get("default_go_live_date") or current.get("default_go_live_date"),
            data.get("default_currency") or current.get("default_currency"),
            pay_freq,pay_timing,
            billing_basis,billing_freq,billing_timing,

            values["lessee_rou_asset_account"],
            values["lessee_liability_current_account"],
            values["lessee_liability_noncurrent_account"],
            values["lessee_interest_expense_account"],
            values["lessee_depreciation_expense_account"],

            values["lessor_receivable_current_account"],
            values["lessor_receivable_noncurrent_account"],
            values["lessor_revenue_account"],
            values["lessor_finance_income_account"],
            values["lessor_ar_account"],
            values["lessor_vat_output_account"],
            values["lessor_security_deposit_account"],
            values["lessor_accrued_rental_account"],
            values["lessor_deferred_rental_account"],
            values["lessor_initial_direct_cost_expense_account"],
            values["lessor_initial_direct_cost_asset_account"],

            bool(data.get("require_counterparty_mapping",current.get("require_counterparty_mapping",True))),
            bool(data.get("require_account_mapping",current.get("require_account_mapping",True))),
            bool(data.get("require_underlying_asset_for_lessor",current.get("require_underlying_asset_for_lessor",True))),

            self._migration_json_dump(data.get("settings_json") or current.get("settings_json"),{}),
            self._migration_json_dump(data.get("metadata_json") or current.get("metadata_json"),{}),

            user_id,user_id,
        ),cur=cur)

        return self.migration_lease_settings_get(
            company_id,project_id,dataset_id,cur=cur
        )

    def migration_lease_reference_targets(
        self,
        company_id:int,
        reference_type:str,
        *,
        cur=None,
    )->list[dict]:
        company_id=int(company_id)
        schema=self.company_schema(company_id)
        reference_type=str(reference_type or "").strip().lower()

        if reference_type=="lessor":
            rows=self.fetch_all(f"""
                SELECT id,name
                FROM {schema}.lessors
                WHERE company_id=%s
                ORDER BY name,id
            """,(company_id,),cur=cur) or []

            return [
                {"id":row["id"],"label":row.get("name") or f"Lessor {row['id']}"}
                for row in rows
            ]

        if reference_type=="customer":
            rows=self.fetch_all(f"""
                SELECT id,name,external_code
                FROM {schema}.customers
                WHERE company_id=%s
                AND COALESCE(is_active,TRUE)=TRUE
                ORDER BY name,id
            """,(company_id,),cur=cur) or []

            return [
                {
                    "id":row["id"],
                    "code":row.get("external_code"),
                    "label":row.get("name") or f"Customer {row['id']}",
                }
                for row in rows
            ]

        if reference_type=="asset":
            rows=self.fetch_all(f"""
                SELECT
                    id,
                    asset_no,
                    asset_name,
                    asset_class,
                    carrying_amount,
                    cost_total
                FROM {schema}.assets
                WHERE company_id=%s
                AND COALESCE(disposed,FALSE)=FALSE
                ORDER BY asset_name,id
            """,(company_id,),cur=cur) or []

            return [
                {
                    "id":row["id"],
                    "code":row.get("asset_no"),
                    "label":row.get("asset_name") or f"Asset {row['id']}",
                    "asset_class":row.get("asset_class"),
                    "carrying_amount":row.get("carrying_amount"),
                    "cost_total":row.get("cost_total"),
                }
                for row in rows
            ]

        raise ValueError(f"Unsupported lease reference type: {reference_type}")

    def migration_lease_source_references(
        self,
        company_id:int,
        project_id:int,
        dataset_id:int,
        *,
        cur=None,
    )->dict:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)

        mapping=self.migration_field_mapping_dataset(
            company_id,project_id,dataset_id,cur=cur
        )

        dataset=self.fetch_one(f"""
            SELECT metadata_json
            FROM {schema}.migration_source_datasets
            WHERE company_id=%s AND project_id=%s AND id=%s
        """,(company_id,project_id,dataset_id),cur=cur)

        metadata=self._migration_json(dataset.get("metadata_json") if dataset else {},{})
        rows=metadata.get("sample_rows") or []

        target_to_source={
            row["target_field_code"]:row["source_name"]
            for row in mapping.get("rows") or []
            if row.get("mapping_status")=="mapped"
            and row.get("target_field_code")
        }

        config={
            "lessor":"lessor_reference",
            "customer":"customer_reference",
            "asset":"asset_reference",
        }

        result={}

        for reference_type,target_field in config.items():
            source_name=target_to_source.get(target_field)
            values={}

            if source_name:
                for source_row in rows:
                    value=str(source_row.get(source_name) or "").strip()
                    if value:
                        values[value]=values.get(value,0)+1

            saved=self.fetch_all(f"""
                SELECT *
                FROM {schema}.migration_lease_reference_mappings
                WHERE company_id=%s
                AND project_id=%s
                AND dataset_id=%s
                AND reference_type=%s
            """,(company_id,project_id,dataset_id,reference_type),cur=cur) or []

            saved_map={row["source_value"]:row for row in saved}

            result[reference_type]={
                "rows":[
                    {
                        "source_value":value,
                        "sample_count":count,
                        **(saved_map.get(value) or {}),
                    }
                    for value,count in sorted(values.items())
                ],
                "targets":self.migration_lease_reference_targets(
                    company_id,reference_type,cur=cur
                ),
            }

        return result

    def migration_lease_reference_save(
        self,
        company_id:int,
        project_id:int,
        dataset_id:int,
        mappings:list[dict],
        *,
        user_id:int|None=None,
        cur=None,
    )->dict:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)

        if not isinstance(mappings,list):
            raise ValueError("mappings must be a list.")

        for item in mappings:
            reference_type=str(item.get("reference_type") or "").strip().lower()
            source_value=str(item.get("source_value") or "").strip()
            target_id=int(item.get("target_id") or 0)

            if reference_type not in {"lessor","customer","asset"}:
                raise ValueError(f"Unsupported lease reference type: {reference_type}")

            if not source_value:
                raise ValueError("Source reference value is required.")

            if not target_id:
                raise ValueError(f'Target is required for "{source_value}".')

            targets=self.migration_lease_reference_targets(
                company_id,reference_type,cur=cur
            )

            target=next(
                (row for row in targets if int(row["id"])==target_id),
                None
            )

            if not target:
                raise ValueError(
                    f'Invalid {reference_type} target for "{source_value}".'
                )

            self.execute_sql(f"""
                INSERT INTO {schema}.migration_lease_reference_mappings(
                    company_id,project_id,dataset_id,
                    reference_type,source_value,source_label,
                    target_id,target_label,
                    mapping_method,confidence,is_approved,
                    metadata_json,
                    created_by_user_id,updated_by_user_id,
                    created_at,updated_at
                )
                VALUES(
                    %s,%s,%s,%s,%s,%s,%s,%s,
                    'manual',100,TRUE,
                    '{{}}'::jsonb,%s,%s,NOW(),NOW()
                )
                ON CONFLICT(
                    company_id,project_id,dataset_id,
                    reference_type,source_value
                )
                DO UPDATE SET
                    target_id=EXCLUDED.target_id,
                    target_label=EXCLUDED.target_label,
                    mapping_method='manual',
                    confidence=100,
                    is_approved=TRUE,
                    updated_by_user_id=EXCLUDED.updated_by_user_id,
                    updated_at=NOW()
            """,(
                company_id,project_id,dataset_id,
                reference_type,source_value,
                item.get("source_label") or source_value,
                target_id,target.get("label"),
                user_id,user_id,
            ),cur=cur)

        return self.migration_lease_source_references(
            company_id,project_id,dataset_id,cur=cur
        )

    def migration_lease_mapping_get(
        self,
        company_id:int,
        project_id:int,
        dataset_id:int,
        *,
        cur=None,
    )->dict:
        settings=self.migration_lease_settings_get(
            company_id,project_id,dataset_id,cur=cur
        )

        references=self.migration_lease_source_references(
            company_id,project_id,dataset_id,cur=cur
        )

        field_mapping=self.migration_field_mapping_dataset(
            company_id,project_id,dataset_id,cur=cur
        )

        role=settings.get("default_role") or "lessee"

        required_targets={
            "lessee":{
                "lease_name","start_date","end_date",
                "payment_amount","annual_rate",
            },
            "lessor":{
                "lease_name","start_date","end_date",
                "billing_amount",
            },
        }[role]

        mapped={
            row.get("target_field_code")
            for row in field_mapping.get("rows") or []
            if row.get("mapping_status")=="mapped"
        }

        missing_fields=sorted(required_targets-mapped)

        required_refs=["lessor"] if role=="lessee" else ["customer"]

        if role=="lessor" and settings.get("require_underlying_asset_for_lessor"):
            required_refs.append("asset")

        missing_references=[]

        for ref_type in required_refs:
            for row in references.get(ref_type,{}).get("rows") or []:
                if not row.get("target_id") or not row.get("is_approved"):
                    missing_references.append({
                        "reference_type":ref_type,
                        "source_value":row.get("source_value"),
                    })

        return {
            "settings":settings,
            "field_mapping":field_mapping,
            "references":references,
            "role":role,
            "missing_fields":missing_fields,
            "missing_references":missing_references,
            "is_complete":not missing_fields and not missing_references,
        }

    def _migration_lease_bool(self,value)->bool:
        if isinstance(value,bool):
            return value

        return str(value or "").strip().lower() in {
            "1","true","yes","y","on"
        }


    def _migration_lease_number(self,value,default=0.0)->float:
        if value in (None,""):
            return float(default or 0)

        try:
            return float(str(value).replace(",","").strip())
        except Exception:
            return float(default or 0)

    def migration_lease_normalized_rows(
        self,
        company_id:int,
        project_id:int,
        dataset_id:int,
        *,
        limit:int=20,
        cur=None,
    )->list[dict]:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)

        mapping=self.migration_field_mapping_dataset(
            company_id,project_id,dataset_id,cur=cur
        )

        dataset=self.fetch_one(f"""
            SELECT metadata_json
            FROM {schema}.migration_source_datasets
            WHERE company_id=%s AND project_id=%s AND id=%s
        """,(company_id,project_id,dataset_id),cur=cur)

        metadata=self._migration_json(dataset.get("metadata_json") if dataset else {},{})
        source_rows=metadata.get("sample_rows") or []

        source_to_target={
            row["source_name"]:row["target_field_code"]
            for row in mapping.get("rows") or []
            if row.get("mapping_status")=="mapped"
            and row.get("target_field_code")
        }

        result=[]

        for source_row in source_rows[:limit]:
            normalized={}

            for source_name,target_field in source_to_target.items():
                normalized[target_field]=source_row.get(source_name)

            result.append({
                "source":source_row,
                "normalized":normalized,
            })

        return result

    def migration_lease_reference_resolve(
        self,
        company_id:int,
        project_id:int,
        dataset_id:int,
        reference_type:str,
        source_value,
        *,
        cur=None,
    ):
        value=str(source_value or "").strip()

        if not value:
            return None

        schema=self.company_schema(int(company_id))

        row=self.fetch_one(f"""
            SELECT target_id
            FROM {schema}.migration_lease_reference_mappings
            WHERE company_id=%s
            AND project_id=%s
            AND dataset_id=%s
            AND reference_type=%s
            AND source_value=%s
            AND is_approved=TRUE
        """,(
            int(company_id),int(project_id),int(dataset_id),
            reference_type,value
        ),cur=cur)

        return int(row["target_id"]) if row and row.get("target_id") else None

    def migration_lessee_preview_row(
        self,
        company_id:int,
        project_id:int,
        dataset_id:int,
        normalized:dict,
        settings:dict,
        *,
        cur=None,
    )->dict:
        from BackEnd.Services.lease_engine import LeaseInput,build_lease_schedule,schedule_to_json
        from BackEnd.Services.lease_posting import build_lessee_opening_journal,liability_at_date

        lessor_id=self.migration_lease_reference_resolve(
            company_id,project_id,dataset_id,
            "lessor",
            normalized.get("lessor_reference"),
            cur=cur,
        )

        mode=str(
            normalized.get("wizard_mode")
            or settings.get("default_wizard_mode")
            or "existing"
        ).strip().lower()

        if mode not in {"inception","existing"}:
            mode="existing"

        start_date=self._migration_date(normalized.get("start_date"))
        end_date=self._migration_date(normalized.get("end_date"))

        go_live=self._migration_date(
            normalized.get("go_live_date")
            or settings.get("default_go_live_date"),
            required=False,
        )

        payment_frequency=str(
            normalized.get("payment_frequency")
            or settings.get("default_payment_frequency")
            or "monthly"
        ).strip().lower()

        payment_timing=str(
            normalized.get("payment_timing")
            or settings.get("default_payment_timing")
            or "arrears"
        ).strip().lower()

        lease=LeaseInput(
            company_id=int(company_id),
            role="lessee",
            lease_name=str(normalized.get("lease_name") or "").strip(),
            start_date=start_date,
            end_date=end_date,

            payment_amount=self._migration_lease_number(
                normalized.get("payment_amount")
            ),

            payment_frequency=payment_frequency,
            payment_timing=payment_timing,

            annual_rate=self._migration_lease_number(
                normalized.get("annual_rate")
            ),

            initial_direct_costs=self._migration_lease_number(
                normalized.get("initial_direct_costs")
            ),

            residual_value=self._migration_lease_number(
                normalized.get("residual_value")
            ),

            vat_rate=self._migration_lease_number(
                normalized.get("vat_rate")
            ),

            lease_liability_current_account=(
                normalized.get("lease_liability_current_account")
                or settings.get("lessee_liability_current_account")
            ),

            lease_liability_non_current_account=(
                normalized.get("lease_liability_non_current_account")
                or settings.get("lessee_liability_noncurrent_account")
            ),

            rou_asset_account=(
                normalized.get("rou_asset_account")
                or settings.get("lessee_rou_asset_account")
            ),

            interest_expense_account=(
                normalized.get("interest_expense_account")
                or settings.get("lessee_interest_expense_account")
            ),

            depreciation_expense_account=(
                normalized.get("depreciation_expense_account")
                or settings.get("lessee_depreciation_expense_account")
            ),
        )

        issues=[]

        if not lease.lease_name:
            issues.append("Lease name is required.")

        if not lessor_id:
            issues.append("Lessor is not mapped.")

        if lease.payment_amount<=0:
            issues.append("Lease payment must be greater than zero.")

        if mode=="existing" and not go_live:
            issues.append("Go-live date is required for an existing lease.")

        if issues:
            return {
                "role":"lessee",
                "valid":False,
                "issues":issues,
                "payload":{
                    **normalized,
                    "lessor_id":lessor_id,
                    "wizard_mode":mode,
                },
            }

        result=build_lease_schedule(lease)

        opening=build_lessee_opening_journal(
            company_id,
            result,
            mode=mode,
            as_of=go_live if mode=="existing" else start_date,
            strict=False,
        )

        preview=schedule_to_json(result)

        if mode=="existing" and go_live:
            preview["opening_lease_liability"]=liability_at_date(
                result,go_live
            )

        return {
            "role":"lessee",
            "valid":not opening.get("error"),
            "issues":[opening["error"]] if opening.get("error") else [],
            "payload":{
                **normalized,
                "role":"lessee",
                "lessor_id":lessor_id,
                "wizard_mode":mode,
                "go_live_date":str(go_live) if go_live else None,
            },
            "opening_lease_liability":preview.get("opening_lease_liability"),
            "opening_rou_asset":preview.get("opening_rou_asset"),
            "opening_journal":opening.get("journal_lines") or [],
            "dr_total":opening.get("dr_total"),
            "cr_total":opening.get("cr_total"),
            "schedule":preview.get("schedule") or [],
            "pv_table":preview.get("pv_table") or [],
        }

    def migration_lessor_preview_row(
        self,
        company_id:int,
        project_id:int,
        dataset_id:int,
        normalized:dict,
        settings:dict,
        *,
        cur=None,
    )->dict:
        from BackEnd.Services.lessor_lease_engine import lessor_lease_engine

        customer_id=self.migration_lease_reference_resolve(
            company_id,project_id,dataset_id,
            "customer",
            normalized.get("customer_reference"),
            cur=cur,
        )

        asset_id=self.migration_lease_reference_resolve(
            company_id,project_id,dataset_id,
            "asset",
            normalized.get("asset_reference"),
            cur=cur,
        )

        start_date=self._migration_date(normalized.get("start_date"))
        end_date=self._migration_date(normalized.get("end_date"))

        payload={
            **normalized,

            "customer_id":customer_id,
            "asset_id":asset_id,

            "contract_no":normalized.get("reference"),
            "contract_name":normalized.get("lease_name"),

            "start_date":start_date,
            "end_date":end_date,

            "billing_amount":self._migration_lease_number(
                normalized.get("billing_amount")
            ),

            "billing_basis":str(
                normalized.get("billing_basis")
                or settings.get("default_billing_basis")
                or "gross"
            ).strip().lower(),

            "billing_frequency":str(
                normalized.get("billing_frequency")
                or settings.get("default_billing_frequency")
                or "monthly"
            ).strip().lower(),

            "billing_timing":str(
                normalized.get("billing_timing")
                or settings.get("default_billing_timing")
                or "arrears"
            ).strip().lower(),

            "bill_day_of_month":int(
                self._migration_lease_number(
                    normalized.get("bill_day_of_month")
                )
            ) or None,

            "payment_terms_days":int(
                self._migration_lease_number(
                    normalized.get("payment_terms_days")
                )
            ),

            "vat_rate":self._migration_lease_number(
                normalized.get("vat_rate")
            ),

            "discount_rate":self._migration_lease_number(
                normalized.get("discount_rate")
            ),

            "fair_value":self._migration_lease_number(
                normalized.get("underlying_asset_fair_value")
            ),

            "underlying_asset_fair_value":self._migration_lease_number(
                normalized.get("underlying_asset_fair_value")
            ),

            "underlying_asset_carrying_amount":self._migration_lease_number(
                normalized.get("underlying_asset_carrying_amount")
            ),

            "economic_life_months":int(
                self._migration_lease_number(
                    normalized.get("economic_life_months")
                )
            ),

            "guaranteed_residual_value":self._migration_lease_number(
                normalized.get("guaranteed_residual_value")
            ),

            "unguaranteed_residual_value":self._migration_lease_number(
                normalized.get("unguaranteed_residual_value")
            ),

            "purchase_option_amount":self._migration_lease_number(
                normalized.get("purchase_option_amount")
            ),

            "purchase_option_expected":self._migration_lease_bool(
                normalized.get("purchase_option_expected")
            ),

            "transfer_of_ownership":self._migration_lease_bool(
                normalized.get("transfer_of_ownership")
            ),

            "specialised_asset":self._migration_lease_bool(
                normalized.get("specialised_asset")
            ),

            "manufacturer_dealer_lessor":self._migration_lease_bool(
                normalized.get("manufacturer_dealer_lessor")
            ),

            "initial_direct_costs":self._migration_lease_number(
                normalized.get("initial_direct_costs")
            ),

            "security_deposit_amount":self._migration_lease_number(
                normalized.get("security_deposit_amount")
            ),

            "currency":(
                normalized.get("currency")
                or settings.get("default_currency")
            ),

            "revenue_account_code":(
                normalized.get("revenue_account_code")
                or settings.get("lessor_revenue_account")
            ),

            "finance_income_account_code":(
                normalized.get("finance_income_account_code")
                or settings.get("lessor_finance_income_account")
            ),

            "net_investment_current_account_code":(
                normalized.get("net_investment_current_account_code")
                or settings.get("lessor_receivable_current_account")
            ),

            "net_investment_noncurrent_account_code":(
                normalized.get("net_investment_noncurrent_account_code")
                or settings.get("lessor_receivable_noncurrent_account")
            ),

            "ar_account_code":(
                normalized.get("ar_account_code")
                or settings.get("lessor_ar_account")
            ),

            "vat_output_account_code":(
                normalized.get("vat_output_account_code")
                or settings.get("lessor_vat_output_account")
            ),

            "security_deposit_account_code":(
                normalized.get("security_deposit_account_code")
                or settings.get("lessor_security_deposit_account")
            ),

            "accrued_rental_account_code":(
                normalized.get("accrued_rental_account_code")
                or settings.get("lessor_accrued_rental_account")
            ),

            "deferred_rental_account_code":(
                normalized.get("deferred_rental_account_code")
                or settings.get("lessor_deferred_rental_account")
            ),

            "initial_direct_cost_expense_account_code":(
                normalized.get("initial_direct_cost_expense_account_code")
                or settings.get("lessor_initial_direct_cost_expense_account")
            ),

            "initial_direct_cost_asset_account_code":(
                normalized.get("initial_direct_cost_asset_account_code")
                or settings.get("lessor_initial_direct_cost_asset_account")
            ),
        }

        issues=[]

        if not payload.get("contract_name"):
            issues.append("Lease name is required.")

        if not customer_id:
            issues.append("Customer is not mapped.")

        if (
            settings.get("require_underlying_asset_for_lessor")
            and not asset_id
        ):
            issues.append("Underlying asset is not mapped.")

        if payload["billing_amount"]<=0:
            issues.append("Billing amount must be greater than zero.")

        if payload["end_date"]<payload["start_date"]:
            issues.append("End date cannot be before start date.")

        if issues:
            return {
                "role":"lessor",
                "valid":False,
                "issues":issues,
                "payload":payload,
            }

        classification=lessor_lease_engine.classify_and_validate(
            payload
        )

        payload["lease_classification"]=(
            normalized.get("lease_classification")
            or classification.get("classification")
        )

        terms=lessor_lease_engine.preview_lessor_terms(
            payload
        )

        return {
            "role":"lessor",
            "valid":True,
            "issues":classification.get("warnings") or [],
            "payload":payload,
            "classification":classification,
            "terms":terms,
        }

    def migration_lease_preview(
        self,
        company_id:int,
        project_id:int,
        dataset_id:int,
        *,
        cur=None,
    )->dict:
        settings=self.migration_lease_settings_get(
            company_id,project_id,dataset_id,cur=cur
        )

        rows=self.migration_lease_normalized_rows(
            company_id,project_id,dataset_id,
            limit=20,
            cur=cur,
        )

        previews=[]

        for index,item in enumerate(rows,start=1):
            normalized=item["normalized"]

            role=str(
                normalized.get("lease_role")
                or settings.get("default_role")
                or "lessee"
            ).strip().lower()

            try:
                if role=="lessor":
                    preview=self.migration_lessor_preview_row(
                        company_id,project_id,dataset_id,
                        normalized,settings,cur=cur
                    )
                else:
                    preview=self.migration_lessee_preview_row(
                        company_id,project_id,dataset_id,
                        normalized,settings,cur=cur
                    )

            except Exception as error:
                preview={
                    "role":role,
                    "valid":False,
                    "issues":[str(error)],
                    "payload":normalized,
                }

            previews.append({
                "row_number":index,
                "source":item["source"],
                **preview,
            })

        return {
            "dataset_id":int(dataset_id),
            "rows":previews,
            "row_count":len(previews),
            "valid_count":sum(1 for row in previews if row.get("valid")),
            "error_count":sum(1 for row in previews if not row.get("valid")),
            "lessee_count":sum(1 for row in previews if row.get("role")=="lessee"),
            "lessor_count":sum(1 for row in previews if row.get("role")=="lessor"),
        }

    def _migration_loan_number(self,value,default=0.0)->float:
        if value in (None,""):return float(default or 0)
        try:return float(str(value).replace(",","").strip())
        except Exception:return float(default or 0)


    def _migration_loan_int(self,value,default=0)->int:
        if value in (None,""):return int(default or 0)
        try:return int(float(str(value).replace(",","").strip()))
        except Exception:return int(default or 0)


    def _migration_loan_bool(self,value)->bool:
        if isinstance(value,bool):return value
        return str(value or "").strip().lower() in {"1","true","yes","y","on"}


    def _migration_loan_date(self,value,required=False):
        if isinstance(value,date):return value
        text=str(value or "").strip()

        if not text:
            if required:raise ValueError("Date is required.")
            return None

        try:return datetime.strptime(text[:10],"%Y-%m-%d").date()
        except Exception:
            if required:raise ValueError(f"Invalid date: {text}")
            return None

    def migration_loan_datasets(
        self,company_id:int,project_id:int,*,cur=None
    )->list[dict]:
        company_id,project_id=int(company_id),int(project_id)
        schema=self.company_schema(company_id)

        return self.fetch_all(f"""
            SELECT
                d.id AS dataset_id,
                d.dataset_name,
                d.record_count,
                d.column_count,
                d.dataset_status,
                f.original_name AS source_file_name
            FROM {schema}.migration_source_datasets d
            JOIN {schema}.migration_source_files f
            ON f.id=d.source_file_id
            WHERE d.company_id=%s
            AND d.project_id=%s
            AND d.entity_code='loans'
            AND d.is_selected=TRUE
            ORDER BY d.id
        """,(company_id,project_id),cur=cur) or []

    def migration_loan_gl_defaults(
        self,company_id:int,*,cur=None
    )->dict:
        company_id=int(company_id)
        schema=self.company_schema(company_id)

        roles={
            "interest_expense_account_code":"loan_interest_expense",
            "accrued_interest_account_code":"loan_accrued_interest",
            "loan_payable_current_account_code":"loan_payable_current",
            "loan_payable_noncurrent_account_code":"loan_payable_noncurrent",
        }

        out={}

        for field,role in roles.items():
            row=self.fetch_one(f"""
                SELECT code
                FROM {schema}.coa
                WHERE company_id=%s
                AND posting=TRUE
                AND role=%s
                ORDER BY id
                LIMIT 1
            """,(company_id,role),cur=cur)

            out[field]=(row or {}).get("code")

        return out

    def migration_loan_settings_get(
        self,company_id:int,project_id:int,dataset_id:int,*,cur=None
    )->dict:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)

        project=self.fetch_one(f"""
            SELECT cutover_date,default_currency
            FROM {schema}.migration_projects
            WHERE company_id=%s AND id=%s
        """,(company_id,project_id),cur=cur)

        if not project:
            raise ValueError("Migration project not found.")

        row=self.fetch_one(f"""
            SELECT *
            FROM {schema}.migration_loan_settings
            WHERE company_id=%s AND project_id=%s AND dataset_id=%s
        """,(company_id,project_id,dataset_id),cur=cur)

        if row:
            row["settings_json"]=self._migration_json(row.get("settings_json"),{})
            row["metadata_json"]=self._migration_json(row.get("metadata_json"),{})
            return row

        gl=self.migration_loan_gl_defaults(company_id,cur=cur)

        return {
            "company_id":company_id,
            "project_id":project_id,
            "dataset_id":dataset_id,

            "source_mode":"contract_terms",
            "migration_date":project.get("cutover_date"),

            "default_currency":project.get("default_currency"),
            "default_loan_type":"term_loan",
            "default_interest_method":"amortised_fixed_payment",
            "default_payment_frequency":"monthly",

            **gl,

            "fees_asset_account_code":None,
            "fees_expense_account_code":None,

            "require_bank_mapping":False,
            "require_gl_mapping":True,
            "enable_ias23_mapping":True,

            "balance_tolerance":1.00,

            "settings_json":{},
            "metadata_json":{},
        }

    def migration_loan_settings_save(
        self,company_id:int,project_id:int,dataset_id:int,data:dict,
        *,user_id:int|None=None,cur=None
    )->dict:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)
        data=data or {}

        current=self.migration_loan_settings_get(
            company_id,project_id,dataset_id,cur=cur
        )

        source_mode=str(
            data.get("source_mode") or current["source_mode"]
        ).strip().lower()

        loan_type=str(
            data.get("default_loan_type") or current["default_loan_type"]
        ).strip().lower()

        method=str(
            data.get("default_interest_method") or current["default_interest_method"]
        ).strip().lower().replace("-","_").replace(" ","_")

        frequency=str(
            data.get("default_payment_frequency") or current["default_payment_frequency"]
        ).strip().lower()

        if source_mode not in {
            "contract_terms","existing_schedule","opening_balance_only"
        }:
            raise ValueError("Invalid loan migration source mode.")

        if loan_type not in {
            "term_loan","vehicle","mortgage","overdraft","director_loan","other"
        }:
            raise ValueError("Invalid loan type.")

        if method not in {
            "amortised_fixed_payment",
            "straight_line_interest",
            "interest_only",
            "manual",
        }:
            raise ValueError("Invalid interest method.")

        if frequency not in {
            "weekly","monthly","quarterly","annually"
        }:
            raise ValueError("Invalid payment frequency.")

        self.execute_sql(f"""
            INSERT INTO {schema}.migration_loan_settings(
                company_id,project_id,dataset_id,
                source_mode,migration_date,
                default_currency,default_loan_type,
                default_interest_method,default_payment_frequency,

                interest_expense_account_code,
                accrued_interest_account_code,
                loan_payable_current_account_code,
                loan_payable_noncurrent_account_code,
                fees_asset_account_code,
                fees_expense_account_code,

                require_bank_mapping,
                require_gl_mapping,
                enable_ias23_mapping,
                balance_tolerance,

                settings_json,metadata_json,
                created_by_user_id,updated_by_user_id,
                created_at,updated_at
            )
            VALUES(
                %s,%s,%s,%s,%s,%s,%s,%s,%s,
                %s,%s,%s,%s,%s,%s,
                %s,%s,%s,%s,
                %s::jsonb,%s::jsonb,%s,%s,
                NOW(),NOW()
            )
            ON CONFLICT(company_id,project_id,dataset_id)
            DO UPDATE SET
                source_mode=EXCLUDED.source_mode,
                migration_date=EXCLUDED.migration_date,
                default_currency=EXCLUDED.default_currency,
                default_loan_type=EXCLUDED.default_loan_type,
                default_interest_method=EXCLUDED.default_interest_method,
                default_payment_frequency=EXCLUDED.default_payment_frequency,

                interest_expense_account_code=EXCLUDED.interest_expense_account_code,
                accrued_interest_account_code=EXCLUDED.accrued_interest_account_code,
                loan_payable_current_account_code=EXCLUDED.loan_payable_current_account_code,
                loan_payable_noncurrent_account_code=EXCLUDED.loan_payable_noncurrent_account_code,
                fees_asset_account_code=EXCLUDED.fees_asset_account_code,
                fees_expense_account_code=EXCLUDED.fees_expense_account_code,

                require_bank_mapping=EXCLUDED.require_bank_mapping,
                require_gl_mapping=EXCLUDED.require_gl_mapping,
                enable_ias23_mapping=EXCLUDED.enable_ias23_mapping,
                balance_tolerance=EXCLUDED.balance_tolerance,

                settings_json=EXCLUDED.settings_json,
                metadata_json=EXCLUDED.metadata_json,
                updated_by_user_id=EXCLUDED.updated_by_user_id,
                updated_at=NOW()
        """,(
            company_id,project_id,dataset_id,
            source_mode,
            data.get("migration_date") or current.get("migration_date"),

            data.get("default_currency") or current.get("default_currency"),
            loan_type,method,frequency,

            data.get("interest_expense_account_code")
                or current.get("interest_expense_account_code"),

            data.get("accrued_interest_account_code")
                or current.get("accrued_interest_account_code"),

            data.get("loan_payable_current_account_code")
                or current.get("loan_payable_current_account_code"),

            data.get("loan_payable_noncurrent_account_code")
                or current.get("loan_payable_noncurrent_account_code"),

            data.get("fees_asset_account_code")
                or current.get("fees_asset_account_code"),

            data.get("fees_expense_account_code")
                or current.get("fees_expense_account_code"),

            bool(data.get("require_bank_mapping",current.get("require_bank_mapping",False))),
            bool(data.get("require_gl_mapping",current.get("require_gl_mapping",True))),
            bool(data.get("enable_ias23_mapping",current.get("enable_ias23_mapping",True))),

            float(
                data.get("balance_tolerance")
                if data.get("balance_tolerance") not in (None,"")
                else current.get("balance_tolerance") or 1
            ),

            self._migration_json_dump(
                data.get("settings_json") or current.get("settings_json"),{}
            ),

            self._migration_json_dump(
                data.get("metadata_json") or current.get("metadata_json"),{}
            ),

            user_id,user_id,
        ),cur=cur)

        return self.migration_loan_settings_get(
            company_id,project_id,dataset_id,cur=cur
        )

    def migration_loan_reference_targets(
        self,company_id:int,reference_type:str,*,cur=None
    )->list[dict]:
        company_id=int(company_id)
        schema=self.company_schema(company_id)
        reference_type=str(reference_type or "").strip().lower()

        if reference_type=="bank_account":
            rows=self.fetch_all(f"""
                SELECT id,ledger_account_code
                FROM {schema}.company_bank_accounts
                WHERE company_id=%s
                ORDER BY id
            """,(company_id,),cur=cur) or []

            return [
                {
                    "id":row["id"],
                    "code":row.get("ledger_account_code"),
                    "label":row.get("ledger_account_code") or f"Bank {row['id']}",
                }
                for row in rows
            ]

        if reference_type=="qualifying_asset":
            rows=self.fetch_all(f"""
                SELECT
                    id,
                    asset_code,
                    asset_name,
                    asset_class,
                    available_for_use_date,
                    ready_for_use_date,
                    asset_account_code
                FROM {schema}.assets
                WHERE company_id=%s
                AND COALESCE(is_qualifying_asset,FALSE)=TRUE
                AND COALESCE(disposed,FALSE)=FALSE
                ORDER BY asset_name,id
            """,(company_id,),cur=cur) or []

            return [
                {
                    "id":row["id"],
                    "code":row.get("asset_code"),
                    "label":row.get("asset_name") or f"Asset {row['id']}",
                    "asset_class":row.get("asset_class"),
                    "asset_account_code":row.get("asset_account_code"),
                }
                for row in rows
            ]

        raise ValueError(f"Unsupported loan reference type: {reference_type}")

    def migration_loan_source_references(
        self,company_id:int,project_id:int,dataset_id:int,*,cur=None
    )->dict:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)

        mapping=self.migration_field_mapping_dataset(
            company_id,project_id,dataset_id,cur=cur
        )

        dataset=self.fetch_one(f"""
            SELECT metadata_json
            FROM {schema}.migration_source_datasets
            WHERE company_id=%s AND project_id=%s AND id=%s
        """,(company_id,project_id,dataset_id),cur=cur)

        metadata=self._migration_json(
            dataset.get("metadata_json") if dataset else {},
            {},
        )

        sample_rows=metadata.get("sample_rows") or []

        target_to_source={
            row["target_field_code"]:row["source_name"]
            for row in mapping.get("rows") or []
            if row.get("mapping_status")=="mapped"
            and row.get("target_field_code")
        }

        refs={
            "bank_account":"bank_account_reference",
            "qualifying_asset":"qualifying_asset_reference",
        }

        result={}

        for reference_type,target_field in refs.items():
            source_name=target_to_source.get(target_field)
            values={}

            if source_name:
                for row in sample_rows:
                    value=str(row.get(source_name) or "").strip()
                    if value:values[value]=values.get(value,0)+1

            saved=self.fetch_all(f"""
                SELECT *
                FROM {schema}.migration_loan_reference_mappings
                WHERE company_id=%s
                AND project_id=%s
                AND dataset_id=%s
                AND reference_type=%s
            """,(company_id,project_id,dataset_id,reference_type),cur=cur) or []

            saved_map={row["source_value"]:row for row in saved}

            result[reference_type]={
                "rows":[
                    {
                        "source_value":value,
                        "sample_count":count,
                        **(saved_map.get(value) or {}),
                    }
                    for value,count in sorted(values.items())
                ],

                "targets":self.migration_loan_reference_targets(
                    company_id,reference_type,cur=cur
                ),
            }

        return result

    def migration_loan_reference_save(
        self,company_id:int,project_id:int,dataset_id:int,mappings:list[dict],
        *,user_id:int|None=None,cur=None
    )->dict:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)

        if not isinstance(mappings,list):
            raise ValueError("mappings must be a list.")

        for item in mappings:
            reference_type=str(item.get("reference_type") or "").strip().lower()
            source_value=str(item.get("source_value") or "").strip()
            target_id=int(item.get("target_id") or 0)

            if reference_type not in {"bank_account","qualifying_asset"}:
                raise ValueError(f"Unsupported loan reference type: {reference_type}")

            if not source_value:
                raise ValueError("Source reference value is required.")

            if not target_id:
                raise ValueError(f'Target required for "{source_value}".')

            targets=self.migration_loan_reference_targets(
                company_id,reference_type,cur=cur
            )

            target=next(
                (row for row in targets if int(row["id"])==target_id),
                None
            )

            if not target:
                raise ValueError(f'Invalid target for "{source_value}".')

            self.execute_sql(f"""
                INSERT INTO {schema}.migration_loan_reference_mappings(
                    company_id,project_id,dataset_id,
                    reference_type,source_value,source_label,
                    target_id,target_code,target_label,
                    mapping_method,confidence,is_approved,
                    metadata_json,
                    created_by_user_id,updated_by_user_id,
                    created_at,updated_at
                )
                VALUES(
                    %s,%s,%s,%s,%s,%s,
                    %s,%s,%s,
                    'manual',100,TRUE,
                    '{{}}'::jsonb,
                    %s,%s,NOW(),NOW()
                )
                ON CONFLICT(
                    company_id,project_id,dataset_id,
                    reference_type,source_value
                )
                DO UPDATE SET
                    target_id=EXCLUDED.target_id,
                    target_code=EXCLUDED.target_code,
                    target_label=EXCLUDED.target_label,
                    mapping_method='manual',
                    confidence=100,
                    is_approved=TRUE,
                    updated_by_user_id=EXCLUDED.updated_by_user_id,
                    updated_at=NOW()
            """,(
                company_id,project_id,dataset_id,
                reference_type,source_value,
                item.get("source_label") or source_value,

                target_id,
                target.get("code"),
                target.get("label"),

                user_id,user_id,
            ),cur=cur)

        return self.migration_loan_source_references(
            company_id,project_id,dataset_id,cur=cur
        )

    def migration_loan_reference_resolve(
        self,company_id:int,project_id:int,dataset_id:int,
        reference_type:str,source_value,*,cur=None
    ):
        value=str(source_value or "").strip()
        if not value:return None

        schema=self.company_schema(int(company_id))

        row=self.fetch_one(f"""
            SELECT target_id
            FROM {schema}.migration_loan_reference_mappings
            WHERE company_id=%s
            AND project_id=%s
            AND dataset_id=%s
            AND reference_type=%s
            AND source_value=%s
            AND is_approved=TRUE
        """,(
            int(company_id),int(project_id),int(dataset_id),
            reference_type,value
        ),cur=cur)

        return int(row["target_id"]) if row and row.get("target_id") else None

    def migration_loan_normalized_rows(
        self,company_id:int,project_id:int,dataset_id:int,
        *,limit:int=100,cur=None
    )->list[dict]:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)

        mapping=self.migration_field_mapping_dataset(
            company_id,project_id,dataset_id,cur=cur
        )

        dataset=self.fetch_one(f"""
            SELECT metadata_json
            FROM {schema}.migration_source_datasets
            WHERE company_id=%s AND project_id=%s AND id=%s
        """,(company_id,project_id,dataset_id),cur=cur)

        metadata=self._migration_json(
            dataset.get("metadata_json") if dataset else {},
            {},
        )

        source_rows=metadata.get("sample_rows") or []

        source_to_target={
            row["source_name"]:row["target_field_code"]
            for row in mapping.get("rows") or []
            if row.get("mapping_status")=="mapped"
            and row.get("target_field_code")
        }

        out=[]

        for source_row in source_rows[:limit]:
            normalized={}

            for source_name,target_field in source_to_target.items():
                normalized[target_field]=source_row.get(source_name)

            out.append({
                "source":source_row,
                "normalized":normalized,
            })

        return out   

    def migration_loan_cutover_split(
        self,schedule:list[dict],migration_date:date
    )->dict:
        horizon=migration_date+relativedelta(years=1)

        future=[
            row for row in schedule
            if self._migration_loan_date(row.get("due_date"))
            and self._migration_loan_date(row.get("due_date"))>migration_date
        ]

        current=sum(
            self._migration_loan_number(row.get("scheduled_principal"))
            for row in future
            if self._migration_loan_date(row.get("due_date"))<=horizon
        )

        noncurrent=sum(
            self._migration_loan_number(row.get("scheduled_principal"))
            for row in future
            if self._migration_loan_date(row.get("due_date"))>horizon
        )

        return {
            "current_portion":round(current,2),
            "noncurrent_portion":round(noncurrent,2),
        }

    def migration_loan_contract_preview(
        self,company_id:int,project_id:int,dataset_id:int,
        normalized:dict,settings:dict,*,cur=None
    )->dict:
        migration_date=self._migration_loan_date(
            normalized.get("migration_date")
            or settings.get("migration_date"),
            required=True,
        )

        start_date=self._migration_loan_date(
            normalized.get("start_date"),
            required=True,
        )

        first_payment_date=self._migration_loan_date(
            normalized.get("first_payment_date"),
            required=True,
        )

        principal=self._migration_loan_number(
            normalized.get("principal_amount")
        )

        term_count=self._migration_loan_int(
            normalized.get("term_count")
        )

        method=str(
            normalized.get("interest_method")
            or settings.get("default_interest_method")
            or "amortised_fixed_payment"
        ).strip().lower().replace("-","_").replace(" ","_")

        frequency=str(
            normalized.get("payment_frequency")
            or settings.get("default_payment_frequency")
            or "monthly"
        ).strip().lower()

        issues=[]

        if not str(normalized.get("loan_name") or "").strip():
            issues.append("Loan name is required.")

        if not str(normalized.get("lender_name") or "").strip():
            issues.append("Lender name is required.")

        if principal<=0:
            issues.append("Original principal must be greater than zero.")

        if term_count<=0:
            issues.append("Loan term count must be greater than zero.")

        if migration_date<start_date:
            issues.append("Migration date cannot be before the loan start date.")

        if issues:
            return {
                "valid":False,
                "issues":issues,
                "source_mode":"contract_terms",
                "payload":normalized,
            }

        loan_row={
            "principal_amount":principal,
            "annual_interest_rate":self._migration_loan_number(
                normalized.get("annual_interest_rate")
            ),
            "term_count":term_count,
            "interest_method":method,
            "first_payment_date":first_payment_date,
            "balloon_amount":self._migration_loan_number(
                normalized.get("balloon_amount")
            ),
            "repayment_holiday_count":self._migration_loan_int(
                normalized.get("repayment_holiday_count")
            ),
            "payment_frequency":frequency,
            "payment_amount":self._migration_loan_number(
                normalized.get("payment_amount")
            ),
        }

        schedule=self._build_loan_amortisation_rows(loan_row)

        schedule=[
            {
                key:(float(value) if isinstance(value,Decimal) else value)
                for key,value in row.items()
            }
            for row in schedule
        ]

        past=[
            row for row in schedule
            if self._migration_loan_date(row.get("due_date"))<=migration_date
        ]

        future=[
            row for row in schedule
            if self._migration_loan_date(row.get("due_date"))>migration_date
        ]

        calculated_outstanding=(
            self._migration_loan_number(past[-1].get("closing_balance"))
            if past else principal
        )

        imported_outstanding=self._migration_loan_number(
            normalized.get("outstanding_principal"),
            calculated_outstanding,
        )

        difference=round(
            imported_outstanding-calculated_outstanding,
            2,
        )

        tolerance=float(settings.get("balance_tolerance") or 1)

        if abs(difference)>tolerance:
            issues.append(
                f"Outstanding principal differs from reconstructed schedule by {difference:.2f}."
            )

        split=self.migration_loan_cutover_split(
            schedule,
            migration_date,
        )

        next_row=future[0] if future else None

        bank_id=self.migration_loan_reference_resolve(
            company_id,project_id,dataset_id,
            "bank_account",
            normalized.get("bank_account_reference"),
            cur=cur,
        )

        asset_id=self.migration_loan_reference_resolve(
            company_id,project_id,dataset_id,
            "qualifying_asset",
            normalized.get("qualifying_asset_reference"),
            cur=cur,
        )

        if settings.get("require_bank_mapping") and normalized.get("bank_account_reference") and not bank_id:
            issues.append("Bank account is not mapped.")

        if normalized.get("qualifying_asset_reference") and not asset_id:
            issues.append("IAS 23 qualifying asset is not mapped.")

        payload={
            "loan_name":str(normalized.get("loan_name") or "").strip(),
            "loan_reference":str(normalized.get("loan_reference") or "").strip() or None,
            "lender_name":str(normalized.get("lender_name") or "").strip(),

            "loan_type":str(
                normalized.get("loan_type")
                or settings.get("default_loan_type")
                or "term_loan"
            ).strip().lower(),

            "start_date":start_date,
            "first_payment_date":first_payment_date,
            "maturity_date":self._migration_loan_date(
                normalized.get("maturity_date")
            ),

            "principal_amount":principal,

            "annual_interest_rate":self._migration_loan_number(
                normalized.get("annual_interest_rate")
            ),

            "interest_method":method,
            "term_count":term_count,
            "payment_frequency":frequency,

            "payment_amount":self._migration_loan_number(
                normalized.get("payment_amount")
            ),

            "balloon_amount":self._migration_loan_number(
                normalized.get("balloon_amount")
            ),

            "fees_amount":self._migration_loan_number(
                normalized.get("fees_amount")
            ),

            "repayment_holiday_count":self._migration_loan_int(
                normalized.get("repayment_holiday_count")
            ),

            "variable_rate":self._migration_loan_bool(
                normalized.get("variable_rate")
            ),

            "rate_review_rule":normalized.get("rate_review_rule"),

            "currency":str(
                normalized.get("currency")
                or settings.get("default_currency")
                or "USD"
            ).strip().upper(),

            "bank_account_id":bank_id,

            "outstanding_principal":imported_outstanding,

            "outstanding_interest":self._migration_loan_number(
                normalized.get("outstanding_interest")
                or normalized.get("accrued_interest_opening")
            ),

            "interest_expense_account_code":
                normalized.get("interest_expense_account_code")
                or settings.get("interest_expense_account_code"),

            "accrued_interest_account_code":
                normalized.get("accrued_interest_account_code")
                or settings.get("accrued_interest_account_code"),

            "loan_payable_current_account_code":
                normalized.get("loan_payable_current_account_code")
                or settings.get("loan_payable_current_account_code"),

            "loan_payable_noncurrent_account_code":
                normalized.get("loan_payable_noncurrent_account_code")
                or settings.get("loan_payable_noncurrent_account_code"),

            "fees_asset_account_code":
                normalized.get("fees_asset_account_code")
                or settings.get("fees_asset_account_code"),

            "fees_expense_account_code":
                normalized.get("fees_expense_account_code")
                or settings.get("fees_expense_account_code"),

            "agreement_reference":normalized.get("agreement_reference"),
            "notes":normalized.get("notes"),

            "migration_date":migration_date,

            "ias23_link":{
                "asset_id":asset_id,
                "capitalization_start_date":
                    normalized.get("capitalization_start_date"),
                "capitalization_end_date":
                    normalized.get("capitalization_end_date"),
                "capitalization_ratio":
                    self._migration_loan_number(
                        normalized.get("capitalization_ratio"),
                        1,
                    ),
            } if asset_id else None,
        }

        if settings.get("require_gl_mapping"):
            required_accounts=[
                ("interest_expense_account_code","Interest expense account"),
                ("loan_payable_current_account_code","Current loan payable account"),
                ("loan_payable_noncurrent_account_code","Non-current loan payable account"),
            ]

            for field,label in required_accounts:
                if not payload.get(field):
                    issues.append(f"{label} is not mapped.")

            if payload["outstanding_interest"]>0 and not payload.get("accrued_interest_account_code"):
                issues.append("Accrued interest account is required for opening interest.")

        return {
            "valid":not issues,
            "issues":issues,
            "source_mode":"contract_terms",

            "payload":payload,

            "reconciliation":{
                "original_principal":round(principal,2),
                "calculated_outstanding":round(calculated_outstanding,2),
                "imported_outstanding":round(imported_outstanding,2),
                "difference":difference,
                "tolerance":tolerance,
            },

            "cutover":{
                "migration_date":migration_date,
                "outstanding_principal":round(imported_outstanding,2),
                "outstanding_interest":round(payload["outstanding_interest"],2),
                **split,
            },

            "next_payment":(
                {
                    "due_date":next_row.get("due_date"),
                    "payment":next_row.get("scheduled_payment"),
                    "interest":next_row.get("scheduled_interest"),
                    "principal":next_row.get("scheduled_principal"),
                    "closing_balance":next_row.get("closing_balance"),
                }
                if next_row else None
            ),

            "schedule":schedule,
        }

    def migration_loan_opening_preview(
        self,company_id:int,project_id:int,dataset_id:int,
        normalized:dict,settings:dict,*,cur=None
    )->dict:
        migration_date=self._migration_loan_date(
            normalized.get("migration_date")
            or settings.get("migration_date"),
            required=True,
        )

        outstanding=self._migration_loan_number(
            normalized.get("outstanding_principal")
        )

        remaining_term=self._migration_loan_int(
            normalized.get("remaining_term_count")
            or normalized.get("term_count")
        )

        next_payment_date=self._migration_loan_date(
            normalized.get("next_payment_date")
            or normalized.get("first_payment_date")
        )

        issues=[]

        if not str(normalized.get("loan_name") or "").strip():
            issues.append("Loan name is required.")

        if not str(normalized.get("lender_name") or "").strip():
            issues.append("Lender name is required.")

        if outstanding<=0:
            issues.append("Outstanding principal must be greater than zero.")

        if remaining_term<=0:
            issues.append("Remaining term count is required.")

        if not next_payment_date:
            issues.append("Next payment date is required.")

        if issues:
            return {
                "valid":False,
                "issues":issues,
                "source_mode":"opening_balance_only",
                "payload":normalized,
            }

        method=str(
            normalized.get("interest_method")
            or settings.get("default_interest_method")
            or "amortised_fixed_payment"
        ).strip().lower().replace("-","_").replace(" ","_")

        frequency=str(
            normalized.get("payment_frequency")
            or settings.get("default_payment_frequency")
            or "monthly"
        ).strip().lower()

        loan_row={
            "principal_amount":outstanding,
            "annual_interest_rate":self._migration_loan_number(
                normalized.get("annual_interest_rate")
            ),
            "term_count":remaining_term,
            "interest_method":method,
            "first_payment_date":next_payment_date,
            "balloon_amount":self._migration_loan_number(
                normalized.get("balloon_amount")
            ),
            "repayment_holiday_count":0,
            "payment_frequency":frequency,
            "payment_amount":self._migration_loan_number(
                normalized.get("payment_amount")
            ),
        }

        schedule=self._build_loan_amortisation_rows(loan_row)

        schedule=[
            {
                key:(float(value) if isinstance(value,Decimal) else value)
                for key,value in row.items()
            }
            for row in schedule
        ]

        split=self.migration_loan_cutover_split(
            schedule,
            migration_date,
        )

        bank_id=self.migration_loan_reference_resolve(
            company_id,project_id,dataset_id,
            "bank_account",
            normalized.get("bank_account_reference"),
            cur=cur,
        )

        asset_id=self.migration_loan_reference_resolve(
            company_id,project_id,dataset_id,
            "qualifying_asset",
            normalized.get("qualifying_asset_reference"),
            cur=cur,
        )

        payload={
            "loan_name":str(normalized.get("loan_name") or "").strip(),
            "loan_reference":str(normalized.get("loan_reference") or "").strip() or None,
            "lender_name":str(normalized.get("lender_name") or "").strip(),

            "loan_type":str(
                normalized.get("loan_type")
                or settings.get("default_loan_type")
                or "term_loan"
            ).strip().lower(),

            "start_date":self._migration_loan_date(
                normalized.get("start_date")
            ) or migration_date,

            "first_payment_date":next_payment_date,

            "maturity_date":self._migration_loan_date(
                normalized.get("maturity_date")
            ),

            "principal_amount":outstanding,
            "outstanding_principal":outstanding,

            "outstanding_interest":self._migration_loan_number(
                normalized.get("outstanding_interest")
                or normalized.get("accrued_interest_opening")
            ),

            "annual_interest_rate":self._migration_loan_number(
                normalized.get("annual_interest_rate")
            ),

            "interest_method":method,
            "term_count":remaining_term,
            "payment_frequency":frequency,

            "payment_amount":self._migration_loan_number(
                normalized.get("payment_amount")
            ),

            "balloon_amount":self._migration_loan_number(
                normalized.get("balloon_amount")
            ),

            "currency":str(
                normalized.get("currency")
                or settings.get("default_currency")
                or "USD"
            ).strip().upper(),

            "bank_account_id":bank_id,

            "interest_expense_account_code":
                normalized.get("interest_expense_account_code")
                or settings.get("interest_expense_account_code"),

            "accrued_interest_account_code":
                normalized.get("accrued_interest_account_code")
                or settings.get("accrued_interest_account_code"),

            "loan_payable_current_account_code":
                normalized.get("loan_payable_current_account_code")
                or settings.get("loan_payable_current_account_code"),

            "loan_payable_noncurrent_account_code":
                normalized.get("loan_payable_noncurrent_account_code")
                or settings.get("loan_payable_noncurrent_account_code"),

            "migration_date":migration_date,

            "ias23_link":{
                "asset_id":asset_id,
                "capitalization_start_date":
                    normalized.get("capitalization_start_date"),
                "capitalization_end_date":
                    normalized.get("capitalization_end_date"),
                "capitalization_ratio":
                    self._migration_loan_number(
                        normalized.get("capitalization_ratio"),
                        1,
                    ),
            } if asset_id else None,
        }

        if settings.get("require_gl_mapping"):
            for field,label in [
                ("interest_expense_account_code","Interest expense account"),
                ("loan_payable_current_account_code","Current loan payable account"),
                ("loan_payable_noncurrent_account_code","Non-current loan payable account"),
            ]:
                if not payload.get(field):
                    issues.append(f"{label} is not mapped.")

        next_row=schedule[0] if schedule else None

        return {
            "valid":not issues,
            "issues":issues,
            "source_mode":"opening_balance_only",

            "payload":payload,

            "cutover":{
                "migration_date":migration_date,
                "outstanding_principal":round(outstanding,2),
                "outstanding_interest":round(payload["outstanding_interest"],2),
                **split,
            },

            "next_payment":(
                {
                    "due_date":next_row.get("due_date"),
                    "payment":next_row.get("scheduled_payment"),
                    "interest":next_row.get("scheduled_interest"),
                    "principal":next_row.get("scheduled_principal"),
                    "closing_balance":next_row.get("closing_balance"),
                }
                if next_row else None
            ),

            "schedule":schedule,
        }

    def migration_loan_existing_schedule_preview(
        self,normalized_rows:list[dict],settings:dict
    )->dict:
        if not normalized_rows:
            return {
                "valid":False,
                "issues":["No loan schedule rows found."],
                "source_mode":"existing_schedule",
            }

        first=normalized_rows[0]

        migration_date=self._migration_loan_date(
            first.get("migration_date")
            or settings.get("migration_date"),
            required=True,
        )

        tolerance=float(settings.get("balance_tolerance") or 1)

        schedule=[]
        issues=[]

        sorted_rows=sorted(
            normalized_rows,
            key=lambda row:(
                self._migration_loan_int(row.get("schedule_period_no"),999999),
                self._migration_loan_date(row.get("schedule_due_date"))
                    or date.max,
            )
        )

        previous_closing=None

        for index,row in enumerate(sorted_rows,start=1):
            opening=self._migration_loan_number(
                row.get("schedule_opening_balance")
            )

            payment=self._migration_loan_number(
                row.get("schedule_payment")
            )

            interest=self._migration_loan_number(
                row.get("schedule_interest")
            )

            principal=self._migration_loan_number(
                row.get("schedule_principal")
            )

            closing=self._migration_loan_number(
                row.get("schedule_closing_balance")
            )

            due=self._migration_loan_date(
                row.get("schedule_due_date")
            )

            if not due:
                issues.append(f"Schedule row {index}: due date is required.")

            if abs(payment-(interest+principal))>tolerance:
                issues.append(
                    f"Schedule row {index}: payment does not equal principal + interest."
                )

            if abs((opening-principal)-closing)>tolerance:
                issues.append(
                    f"Schedule row {index}: opening less principal does not equal closing."
                )

            if previous_closing is not None and abs(opening-previous_closing)>tolerance:
                issues.append(
                    f"Schedule row {index}: opening balance does not agree to previous closing balance."
                )

            schedule.append({
                "period_no":self._migration_loan_int(
                    row.get("schedule_period_no"),index
                ),
                "due_date":due,
                "opening_balance":round(opening,2),
                "scheduled_payment":round(payment,2),
                "scheduled_interest":round(interest,2),
                "scheduled_principal":round(principal,2),
                "closing_balance":round(closing,2),
            })

            previous_closing=closing

        past=[
            row for row in schedule
            if row.get("due_date") and row["due_date"]<=migration_date
        ]

        future=[
            row for row in schedule
            if row.get("due_date") and row["due_date"]>migration_date
        ]

        calculated_outstanding=(
            past[-1]["closing_balance"]
            if past
            else schedule[0]["opening_balance"]
        )

        imported_outstanding=self._migration_loan_number(
            first.get("outstanding_principal"),
            calculated_outstanding,
        )

        difference=round(
            imported_outstanding-calculated_outstanding,
            2,
        )

        if abs(difference)>tolerance:
            issues.append(
                f"Imported outstanding principal differs from source schedule by {difference:.2f}."
            )

        split=self.migration_loan_cutover_split(
            schedule,
            migration_date,
        )

        return {
            "valid":not issues,
            "issues":issues,
            "source_mode":"existing_schedule",

            "payload":{
                **first,
                "outstanding_principal":imported_outstanding,
                "migration_date":migration_date,
            },

            "reconciliation":{
                "calculated_outstanding":round(calculated_outstanding,2),
                "imported_outstanding":round(imported_outstanding,2),
                "difference":difference,
                "tolerance":tolerance,
            },

            "cutover":{
                "migration_date":migration_date,
                "outstanding_principal":round(imported_outstanding,2),
                "outstanding_interest":self._migration_loan_number(
                    first.get("outstanding_interest")
                ),
                **split,
            },

            "next_payment":future[0] if future else None,
            "schedule":schedule,
        }

    def migration_loan_preview(
        self,company_id:int,project_id:int,dataset_id:int,*,cur=None
    )->dict:
        settings=self.migration_loan_settings_get(
            company_id,project_id,dataset_id,cur=cur
        )

        rows=self.migration_loan_normalized_rows(
            company_id,project_id,dataset_id,
            limit=100,
            cur=cur,
        )

        mode=settings.get("source_mode") or "contract_terms"
        previews=[]

        if mode=="existing_schedule":
            groups={}

            for item in rows:
                row=item["normalized"]

                key=str(
                    row.get("loan_reference")
                    or row.get("loan_name")
                    or "UNIDENTIFIED"
                ).strip()

                groups.setdefault(key,[]).append(row)

            for index,(key,group_rows) in enumerate(groups.items(),start=1):
                try:
                    preview=self.migration_loan_existing_schedule_preview(
                        group_rows,settings
                    )

                except Exception as error:
                    preview={
                        "valid":False,
                        "issues":[str(error)],
                        "source_mode":"existing_schedule",
                        "payload":group_rows[0] if group_rows else {},
                    }

                previews.append({
                    "row_number":index,
                    "loan_key":key,
                    **preview,
                })

        else:
            for index,item in enumerate(rows,start=1):
                normalized=item["normalized"]

                try:
                    if mode=="opening_balance_only":
                        preview=self.migration_loan_opening_preview(
                            company_id,project_id,dataset_id,
                            normalized,settings,cur=cur
                        )
                    else:
                        preview=self.migration_loan_contract_preview(
                            company_id,project_id,dataset_id,
                            normalized,settings,cur=cur
                        )

                except Exception as error:
                    preview={
                        "valid":False,
                        "issues":[str(error)],
                        "source_mode":mode,
                        "payload":normalized,
                    }

                previews.append({
                    "row_number":index,
                    "source":item["source"],
                    **preview,
                })

        return {
            "dataset_id":int(dataset_id),
            "source_mode":mode,
            "rows":previews,
            "row_count":len(previews),
            "valid_count":sum(1 for row in previews if row.get("valid")),
            "error_count":sum(1 for row in previews if not row.get("valid")),
        }

    def migration_loan_mapping_get(
        self,company_id:int,project_id:int,dataset_id:int,*,cur=None
    )->dict:
        settings=self.migration_loan_settings_get(
            company_id,project_id,dataset_id,cur=cur
        )

        field_mapping=self.migration_field_mapping_dataset(
            company_id,project_id,dataset_id,cur=cur
        )

        references=self.migration_loan_source_references(
            company_id,project_id,dataset_id,cur=cur
        )

        mode=settings.get("source_mode") or "contract_terms"

        required={
            "contract_terms":{
                "loan_name","lender_name",
                "start_date","first_payment_date",
                "principal_amount",
                "annual_interest_rate",
                "term_count",
            },

            "opening_balance_only":{
                "loan_name","lender_name",
                "outstanding_principal",
                "annual_interest_rate",
                "remaining_term_count",
                "next_payment_date",
            },

            "existing_schedule":{
                "loan_name",
                "schedule_due_date",
                "schedule_opening_balance",
                "schedule_payment",
                "schedule_interest",
                "schedule_principal",
                "schedule_closing_balance",
            },
        }[mode]

        mapped={
            row.get("target_field_code")
            for row in field_mapping.get("rows") or []
            if row.get("mapping_status")=="mapped"
        }

        missing_fields=sorted(required-mapped)
        missing_references=[]

        if settings.get("require_bank_mapping"):
            for row in references["bank_account"]["rows"]:
                if not row.get("target_id") or not row.get("is_approved"):
                    missing_references.append({
                        "reference_type":"bank_account",
                        "source_value":row.get("source_value"),
                    })

        if settings.get("enable_ias23_mapping"):
            for row in references["qualifying_asset"]["rows"]:
                if not row.get("target_id") or not row.get("is_approved"):
                    missing_references.append({
                        "reference_type":"qualifying_asset",
                        "source_value":row.get("source_value"),
                    })

        return {
            "settings":settings,
            "field_mapping":field_mapping,
            "references":references,
            "source_mode":mode,
            "missing_fields":missing_fields,
            "missing_references":missing_references,
            "is_complete":not missing_fields and not missing_references,
        }

    def _migration_revenue_number(self,value,default=0.0)->float:
        if value in (None,""):return float(default or 0)
        try:return float(str(value).replace(",","").strip())
        except Exception:return float(default or 0)


    def _migration_revenue_bool(self,value,default=False)->bool:
        if isinstance(value,bool):return value
        if value in (None,""):return bool(default)
        return str(value).strip().lower() in {"1","true","yes","y","on"}


    def _migration_revenue_date(self,value,required=False):
        if isinstance(value,date):return value
        text=str(value or "").strip()

        if not text:
            if required:raise ValueError("Date is required.")
            return None

        try:return datetime.strptime(text[:10],"%Y-%m-%d").date()
        except Exception:
            if required:raise ValueError(f"Invalid date: {text}")
            return None

    def migration_revenue_datasets(
        self,company_id:int,project_id:int,*,cur=None
    )->list[dict]:
        company_id,project_id=int(company_id),int(project_id)
        schema=self.company_schema(company_id)

        return self.fetch_all(f"""
            SELECT
                d.id AS dataset_id,
                d.dataset_name,
                d.record_count,
                d.column_count,
                d.dataset_status,
                f.original_name AS source_file_name
            FROM {schema}.migration_source_datasets d
            JOIN {schema}.migration_source_files f
            ON f.id=d.source_file_id
            WHERE d.company_id=%s
            AND d.project_id=%s
            AND d.entity_code='revenue_contracts'
            AND d.is_selected=TRUE
            ORDER BY d.id
        """,(company_id,project_id),cur=cur) or []

    def migration_revenue_gl_defaults(
        self,company_id:int,*,cur=None
    )->dict:
        accounts=self.resolve_ifrs15_accounts(
            int(company_id),
            cur=cur,
            strict=False,
        ) or {}

        return {
            "revenue_account_code":
                accounts.get("contract_revenue_account")
                or accounts.get("revenue_code")
                or None,

            "contract_asset_account_code":
                accounts.get("contract_asset_account")
                or accounts.get("contract_asset_code")
                or None,

            "contract_liability_account_code":
                accounts.get("contract_liability_account")
                or accounts.get("contract_liability_code")
                or None,

            "receivable_account_code":None,
        }

    def migration_revenue_settings_get(
        self,company_id:int,project_id:int,dataset_id:int,*,cur=None
    )->dict:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)

        project=self.fetch_one(f"""
            SELECT cutover_date,default_currency
            FROM {schema}.migration_projects
            WHERE company_id=%s AND id=%s
        """,(company_id,project_id),cur=cur)

        if not project:
            raise ValueError("Migration project not found.")

        row=self.fetch_one(f"""
            SELECT *
            FROM {schema}.migration_revenue_settings
            WHERE company_id=%s AND project_id=%s AND dataset_id=%s
        """,(company_id,project_id,dataset_id),cur=cur)

        if row:
            row["settings_json"]=self._migration_json(row.get("settings_json"),{})
            row["metadata_json"]=self._migration_json(row.get("metadata_json"),{})
            return row

        gl=self.migration_revenue_gl_defaults(company_id,cur=cur)

        return {
            "company_id":company_id,
            "project_id":project_id,
            "dataset_id":dataset_id,

            "source_mode":"contract_and_progress",
            "migration_date":project.get("cutover_date"),

            "default_currency":project.get("default_currency"),
            "default_billing_method":"milestone",
            "default_recognition_timing":"over_time",
            "default_progress_method":"cost_to_cost",

            **gl,

            "require_customer_mapping":True,
            "require_project_mapping":False,
            "require_gl_mapping":True,

            "reconciliation_tolerance":1.00,

            "settings_json":{},
            "metadata_json":{},
        }

    def migration_revenue_settings_save(
        self,company_id:int,project_id:int,dataset_id:int,data:dict,
        *,user_id:int|None=None,cur=None
    )->dict:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)
        data=data or {}

        current=self.migration_revenue_settings_get(
            company_id,project_id,dataset_id,cur=cur
        )

        source_mode=str(data.get("source_mode") or current["source_mode"]).strip().lower()
        billing=str(data.get("default_billing_method") or current["default_billing_method"]).strip().lower()
        timing=str(data.get("default_recognition_timing") or current["default_recognition_timing"]).strip().lower()
        progress=str(data.get("default_progress_method") or current["default_progress_method"]).strip().lower()

        if source_mode not in {"full_history","contract_and_progress","opening_position"}:
            raise ValueError("Invalid revenue migration source mode.")

        if billing not in {"milestone","progress","periodic","manual"}:
            raise ValueError("Invalid revenue billing method.")

        if timing not in {"over_time","point_in_time"}:
            raise ValueError("Invalid revenue recognition timing.")

        if progress not in {
            "cost_to_cost","milestone","units",
            "units_delivered","time_elapsed","manual"
        }:
            raise ValueError("Invalid revenue progress method.")

        self.execute_sql(f"""
            INSERT INTO {schema}.migration_revenue_settings(
                company_id,project_id,dataset_id,
                source_mode,migration_date,
                default_currency,
                default_billing_method,
                default_recognition_timing,
                default_progress_method,

                revenue_account_code,
                contract_asset_account_code,
                contract_liability_account_code,
                receivable_account_code,

                require_customer_mapping,
                require_project_mapping,
                require_gl_mapping,
                reconciliation_tolerance,

                settings_json,metadata_json,
                created_by_user_id,updated_by_user_id,
                created_at,updated_at
            )
            VALUES(
                %s,%s,%s,%s,%s,%s,%s,%s,%s,
                %s,%s,%s,%s,
                %s,%s,%s,%s,
                %s::jsonb,%s::jsonb,%s,%s,
                NOW(),NOW()
            )
            ON CONFLICT(company_id,project_id,dataset_id)
            DO UPDATE SET
                source_mode=EXCLUDED.source_mode,
                migration_date=EXCLUDED.migration_date,
                default_currency=EXCLUDED.default_currency,
                default_billing_method=EXCLUDED.default_billing_method,
                default_recognition_timing=EXCLUDED.default_recognition_timing,
                default_progress_method=EXCLUDED.default_progress_method,

                revenue_account_code=EXCLUDED.revenue_account_code,
                contract_asset_account_code=EXCLUDED.contract_asset_account_code,
                contract_liability_account_code=EXCLUDED.contract_liability_account_code,
                receivable_account_code=EXCLUDED.receivable_account_code,

                require_customer_mapping=EXCLUDED.require_customer_mapping,
                require_project_mapping=EXCLUDED.require_project_mapping,
                require_gl_mapping=EXCLUDED.require_gl_mapping,
                reconciliation_tolerance=EXCLUDED.reconciliation_tolerance,

                settings_json=EXCLUDED.settings_json,
                metadata_json=EXCLUDED.metadata_json,
                updated_by_user_id=EXCLUDED.updated_by_user_id,
                updated_at=NOW()
        """,(
            company_id,project_id,dataset_id,
            source_mode,
            data.get("migration_date") or current.get("migration_date"),

            data.get("default_currency") or current.get("default_currency"),
            billing,timing,progress,

            data.get("revenue_account_code") or current.get("revenue_account_code"),
            data.get("contract_asset_account_code") or current.get("contract_asset_account_code"),
            data.get("contract_liability_account_code") or current.get("contract_liability_account_code"),
            data.get("receivable_account_code") or current.get("receivable_account_code"),

            bool(data.get("require_customer_mapping",current.get("require_customer_mapping",True))),
            bool(data.get("require_project_mapping",current.get("require_project_mapping",False))),
            bool(data.get("require_gl_mapping",current.get("require_gl_mapping",True))),

            float(
                data.get("reconciliation_tolerance")
                if data.get("reconciliation_tolerance") not in (None,"")
                else current.get("reconciliation_tolerance") or 1
            ),

            self._migration_json_dump(data.get("settings_json") or current.get("settings_json"),{}),
            self._migration_json_dump(data.get("metadata_json") or current.get("metadata_json"),{}),

            user_id,user_id,
        ),cur=cur)

        return self.migration_revenue_settings_get(
            company_id,project_id,dataset_id,cur=cur
        )

    def migration_revenue_reference_targets(
        self,company_id:int,reference_type:str,*,cur=None
    )->list[dict]:
        company_id=int(company_id)
        schema=self.company_schema(company_id)
        reference_type=str(reference_type or "").strip().lower()

        if reference_type=="customer":
            rows=self.fetch_all(f"""
                SELECT id,external_code,name
                FROM {schema}.customers
                WHERE company_id=%s
                AND COALESCE(is_active,TRUE)=TRUE
                ORDER BY name,id
            """,(company_id,),cur=cur) or []

            return [{
                "id":row["id"],
                "code":row.get("external_code"),
                "label":row.get("name") or f"Customer {row['id']}",
            } for row in rows]

        if reference_type=="project":
            rows=self.fetch_all(f"""
                SELECT
                    id,
                    project_code,
                    project_name,
                    customer_id
                FROM {schema}.projects
                WHERE company_id=%s
                ORDER BY project_name,project_code,id
            """,(company_id,),cur=cur) or []

            return [{
                "id":row["id"],
                "code":row.get("project_code"),
                "label":row.get("project_name") or row.get("project_code") or f"Project {row['id']}",
                "customer_id":row.get("customer_id"),
            } for row in rows]

        raise ValueError(f"Unsupported revenue reference type: {reference_type}")

    def migration_revenue_source_references(
        self,company_id:int,project_id:int,dataset_id:int,*,cur=None
    )->dict:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)

        mapping=self.migration_field_mapping_dataset(
            company_id,project_id,dataset_id,cur=cur
        )

        dataset=self.fetch_one(f"""
            SELECT metadata_json
            FROM {schema}.migration_source_datasets
            WHERE company_id=%s AND project_id=%s AND id=%s
        """,(company_id,project_id,dataset_id),cur=cur)

        metadata=self._migration_json(
            dataset.get("metadata_json") if dataset else {},
            {},
        )

        sample_rows=metadata.get("sample_rows") or []

        target_to_source={
            row["target_field_code"]:row["source_name"]
            for row in mapping.get("rows") or []
            if row.get("mapping_status")=="mapped"
            and row.get("target_field_code")
        }

        refs={
            "customer":"customer_reference",
            "project":"project_reference",
        }

        result={}

        for reference_type,target_field in refs.items():
            source_name=target_to_source.get(target_field)
            values={}

            if source_name:
                for source_row in sample_rows:
                    value=str(source_row.get(source_name) or "").strip()
                    if value:values[value]=values.get(value,0)+1

            saved=self.fetch_all(f"""
                SELECT *
                FROM {schema}.migration_revenue_reference_mappings
                WHERE company_id=%s
                AND project_id=%s
                AND dataset_id=%s
                AND reference_type=%s
            """,(company_id,project_id,dataset_id,reference_type),cur=cur) or []

            saved_map={row["source_value"]:row for row in saved}

            result[reference_type]={
                "rows":[
                    {
                        "source_value":value,
                        "sample_count":count,
                        **(saved_map.get(value) or {}),
                    }
                    for value,count in sorted(values.items())
                ],

                "targets":self.migration_revenue_reference_targets(
                    company_id,reference_type,cur=cur
                ),
            }

        return result

    def migration_revenue_reference_save(
        self,company_id:int,project_id:int,dataset_id:int,mappings:list[dict],
        *,user_id:int|None=None,cur=None
    )->dict:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)

        if not isinstance(mappings,list):
            raise ValueError("mappings must be a list.")

        for item in mappings:
            reference_type=str(item.get("reference_type") or "").strip().lower()
            source_value=str(item.get("source_value") or "").strip()
            target_id=int(item.get("target_id") or 0)

            if reference_type not in {"customer","project"}:
                raise ValueError(f"Unsupported revenue reference type: {reference_type}")

            if not source_value:
                raise ValueError("Source reference value is required.")

            if not target_id:
                raise ValueError(f'Target required for "{source_value}".')

            targets=self.migration_revenue_reference_targets(
                company_id,reference_type,cur=cur
            )

            target=next(
                (row for row in targets if int(row["id"])==target_id),
                None
            )

            if not target:
                raise ValueError(f'Invalid target for "{source_value}".')

            self.execute_sql(f"""
                INSERT INTO {schema}.migration_revenue_reference_mappings(
                    company_id,project_id,dataset_id,
                    reference_type,source_value,source_label,
                    target_id,target_code,target_label,
                    mapping_method,confidence,is_approved,
                    metadata_json,
                    created_by_user_id,updated_by_user_id,
                    created_at,updated_at
                )
                VALUES(
                    %s,%s,%s,%s,%s,%s,
                    %s,%s,%s,
                    'manual',100,TRUE,
                    '{{}}'::jsonb,
                    %s,%s,NOW(),NOW()
                )
                ON CONFLICT(
                    company_id,project_id,dataset_id,
                    reference_type,source_value
                )
                DO UPDATE SET
                    target_id=EXCLUDED.target_id,
                    target_code=EXCLUDED.target_code,
                    target_label=EXCLUDED.target_label,
                    mapping_method='manual',
                    confidence=100,
                    is_approved=TRUE,
                    updated_by_user_id=EXCLUDED.updated_by_user_id,
                    updated_at=NOW()
            """,(
                company_id,project_id,dataset_id,
                reference_type,source_value,
                item.get("source_label") or source_value,

                target_id,
                target.get("code"),
                target.get("label"),

                user_id,user_id,
            ),cur=cur)

        return self.migration_revenue_source_references(
            company_id,project_id,dataset_id,cur=cur
        )

    def migration_revenue_reference_resolve(
        self,company_id:int,project_id:int,dataset_id:int,
        reference_type:str,source_value,*,cur=None
    ):
        value=str(source_value or "").strip()
        if not value:return None

        schema=self.company_schema(int(company_id))

        row=self.fetch_one(f"""
            SELECT target_id
            FROM {schema}.migration_revenue_reference_mappings
            WHERE company_id=%s
            AND project_id=%s
            AND dataset_id=%s
            AND reference_type=%s
            AND source_value=%s
            AND is_approved=TRUE
        """,(
            int(company_id),int(project_id),int(dataset_id),
            reference_type,value
        ),cur=cur)

        return int(row["target_id"]) if row and row.get("target_id") else None

    def migration_revenue_normalized_rows(
        self,company_id:int,project_id:int,dataset_id:int,
        *,limit:int=200,cur=None
    )->list[dict]:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)

        mapping=self.migration_field_mapping_dataset(
            company_id,project_id,dataset_id,cur=cur
        )

        dataset=self.fetch_one(f"""
            SELECT metadata_json
            FROM {schema}.migration_source_datasets
            WHERE company_id=%s AND project_id=%s AND id=%s
        """,(company_id,project_id,dataset_id),cur=cur)

        metadata=self._migration_json(
            dataset.get("metadata_json") if dataset else {},
            {},
        )

        source_rows=metadata.get("sample_rows") or []

        source_to_target={
            row["source_name"]:row["target_field_code"]
            for row in mapping.get("rows") or []
            if row.get("mapping_status")=="mapped"
            and row.get("target_field_code")
        }

        result=[]

        for source_row in source_rows[:limit]:
            normalized={}

            for source_name,target_field in source_to_target.items():
                normalized[target_field]=source_row.get(source_name)

            result.append({
                "source":source_row,
                "normalized":normalized,
            })

        return result

    def migration_revenue_progress_percent(
        self,row:dict,method:str,*,start_date=None,end_date=None,migration_date=None
    )->float:
        method=str(method or "").strip().lower()

        if method=="cost_to_cost":
            expected=self._migration_revenue_number(row.get("expected_total_cost"))
            actual=self._migration_revenue_number(row.get("actual_cost_to_date"))

            if expected<=0:
                raise ValueError("Expected total cost must be greater than zero for cost-to-cost.")

            return min(100.0,max(0.0,(actual/expected)*100))

        if method in {"units","units_delivered"}:
            total=self._migration_revenue_number(row.get("units_total"))
            done=self._migration_revenue_number(
                row.get("certified_units")
                if row.get("certified_units") not in (None,"")
                else row.get("units_done")
            )

            if total<=0:
                raise ValueError("Total units must be greater than zero.")

            if done<0 or done>total:
                raise ValueError("Completed/certified units must be between zero and total units.")

            return min(100.0,max(0.0,(done/total)*100))

        if method=="manual":
            pct=self._migration_revenue_number(row.get("progress_percent"))

            if pct<0 or pct>100:
                raise ValueError("Progress percentage must be between 0 and 100.")

            return pct

        if method=="milestone":
            status=str(row.get("milestone_status") or "").strip().lower()

            return 100.0 if status in {
                "achieved","certified","approved","completed"
            } else 0.0

        if method=="time_elapsed":
            start=self._migration_revenue_date(start_date)
            end=self._migration_revenue_date(end_date)
            as_of=self._migration_revenue_date(
                row.get("progress_date") or migration_date
            )

            if not start or not end or not as_of:
                raise ValueError("Time-elapsed recognition requires start, end and progress dates.")

            if end<=start:
                raise ValueError("Contract end date must be after start date.")

            if as_of<=start:return 0.0
            if as_of>=end:return 100.0

            elapsed=(as_of-start).days
            total=(end-start).days

            return min(100.0,max(0.0,(elapsed/total)*100))

        raise ValueError(f"Unsupported progress method: {method}")

    def migration_revenue_position(
        self,recognized:float,billed:float,cash_received:float
    )->dict:
        recognized=round(float(recognized or 0),2)
        billed=round(float(billed or 0),2)
        cash_received=round(float(cash_received or 0),2)

        contract_asset=max(recognized-billed,0)
        contract_liability=max(billed-recognized,0)
        receivable=max(billed-cash_received,0)

        return {
            "recognized_revenue_to_date":recognized,
            "billed_to_date":billed,
            "cash_received_to_date":cash_received,

            "contract_asset_balance":round(contract_asset,2),
            "contract_liability_balance":round(contract_liability,2),
            "accounts_receivable_balance":round(receivable,2),

            "position_type":
                "asset" if contract_asset>0
                else "liability" if contract_liability>0
                else "neutral",

            "position_amount":round(
                contract_asset if contract_asset>0 else contract_liability,
                2,
            ),
        }

    def migration_revenue_group_contracts(self,rows:list[dict])->dict:
        groups={}

        for item in rows:
            row=item.get("normalized") or {}

            key=str(
                row.get("contract_number")
                or row.get("contract_title")
                or "UNIDENTIFIED"
            ).strip()

            groups.setdefault(key,[]).append(row)

        return groups

    def migration_revenue_contract_preview(
        self,company_id:int,project_id:int,dataset_id:int,
        rows:list[dict],settings:dict,*,cur=None
    )->dict:
        if not rows:
            raise ValueError("Revenue contract has no source rows.")

        first=rows[0]

        contract_number=str(first.get("contract_number") or "").strip()
        contract_title=str(first.get("contract_title") or "").strip()

        transaction_price=self._migration_revenue_number(
            first.get("transaction_price")
        )

        migration_date=self._migration_revenue_date(
            first.get("migration_date")
            or settings.get("migration_date"),
            required=True,
        )

        start_date=self._migration_revenue_date(first.get("start_date"))
        end_date=self._migration_revenue_date(first.get("end_date"))

        customer_id=self.migration_revenue_reference_resolve(
            company_id,project_id,dataset_id,
            "customer",
            first.get("customer_reference"),
            cur=cur,
        )

        project_target_id=self.migration_revenue_reference_resolve(
            company_id,project_id,dataset_id,
            "project",
            first.get("project_reference"),
            cur=cur,
        )

        issues=[]

        if not contract_number:
            issues.append("Contract number is required.")

        if not contract_title:
            issues.append("Contract title is required.")

        if transaction_price<=0:
            issues.append("Transaction price must be greater than zero.")

        if settings.get("require_customer_mapping") and not customer_id:
            issues.append("Customer is not mapped.")

        if (
            settings.get("require_project_mapping")
            and first.get("project_reference")
            and not project_target_id
        ):
            issues.append("Project is not mapped.")

        if customer_id and project_target_id:
            project_row=self.fetch_one(f"""
                SELECT customer_id
                FROM {self.company_schema(int(company_id))}.projects
                WHERE company_id=%s AND id=%s
            """,(int(company_id),int(project_target_id)),cur=cur)

            project_customer=(project_row or {}).get("customer_id")

            if project_customer and int(project_customer)!=int(customer_id):
                issues.append("Mapped project belongs to a different customer.")

        billing_method=str(
            first.get("billing_method")
            or settings.get("default_billing_method")
            or "milestone"
        ).strip().lower()

        is_over_time=self._migration_revenue_bool(
            first.get("is_over_time"),
            settings.get("default_recognition_timing")=="over_time",
        )

        mode=settings.get("source_mode") or "contract_and_progress"

        obligations={}

        for row in rows:
            obligation_key=str(
                row.get("obligation_code")
                or row.get("obligation_name")
                or "MAIN"
            ).strip()

            obligations.setdefault(obligation_key,[]).append(row)

        obligation_previews=[]
        calculated_revenue=0.0

        for obligation_key,obligation_rows in obligations.items():
            base=obligation_rows[0]

            allocated=self._migration_revenue_number(
                base.get("allocated_transaction_price")
            )

            if allocated<=0:
                allocated=(
                    transaction_price
                    if len(obligations)==1
                    else self._migration_revenue_number(
                        base.get("standalone_selling_price")
                    )
                )

            timing=str(
                base.get("recognition_timing")
                or ("over_time" if is_over_time else "point_in_time")
            ).strip().lower()

            progress_method=str(
                base.get("progress_method")
                or settings.get("default_progress_method")
                or "cost_to_cost"
            ).strip().lower()

            progress_row=max(
                obligation_rows,
                key=lambda row:str(row.get("progress_date") or ""),
            )

            try:
                if timing=="point_in_time":
                    trigger=str(
                        base.get("recognition_trigger") or ""
                    ).strip()

                    if not trigger:
                        raise ValueError(
                            f'Point-in-time obligation "{obligation_key}" needs a recognition trigger.'
                        )

                    progress_pct=self._migration_revenue_number(
                        progress_row.get("progress_percent")
                    )

                    progress_pct=100.0 if progress_pct>=100 else 0.0

                else:
                    progress_pct=self.migration_revenue_progress_percent(
                        progress_row,
                        progress_method,
                        start_date=start_date,
                        end_date=end_date,
                        migration_date=migration_date,
                    )

            except Exception as error:
                issues.append(
                    f'{obligation_key}: {error}'
                )
                progress_pct=0.0

            revenue_required=round(
                allocated*(progress_pct/100),
                2,
            )

            calculated_revenue+=revenue_required

            obligation_previews.append({
                "obligation_code":
                    base.get("obligation_code") or obligation_key,

                "obligation_name":
                    base.get("obligation_name") or obligation_key,

                "recognition_timing":timing,
                "progress_method":
                    progress_method if timing=="over_time" else None,

                "recognition_trigger":
                    base.get("recognition_trigger")
                    if timing=="point_in_time" else None,

                "allocated_transaction_price":round(allocated,2),
                "expected_total_cost":
                    self._migration_revenue_number(
                        progress_row.get("expected_total_cost")
                    ),

                "actual_cost_to_date":
                    self._migration_revenue_number(
                        progress_row.get("actual_cost_to_date")
                    ),

                "units_done":
                    self._migration_revenue_number(
                        progress_row.get("units_done")
                    ),

                "units_total":
                    self._migration_revenue_number(
                        progress_row.get("units_total")
                    ),

                "certified_units":
                    self._migration_revenue_number(
                        progress_row.get("certified_units")
                    ),

                "progress_percent":round(progress_pct,4),
                "revenue_required_to_date":revenue_required,

                "progress_date":
                    progress_row.get("progress_date")
                    or migration_date,

                "milestone_code":
                    progress_row.get("milestone_code"),

                "certificate_reference":
                    progress_row.get("certificate_reference"),
            })

        calculated_revenue=round(calculated_revenue,2)

        imported_revenue=self._migration_revenue_number(
            first.get("recognized_revenue_to_date"),
            calculated_revenue,
        )

        # Full-history datasets can have several billing/cash rows.
        if mode=="full_history":
            billed=round(sum(
                self._migration_revenue_number(row.get("billing_amount"))
                for row in rows
            ),2)

            cash=round(sum(
                self._migration_revenue_number(row.get("receipt_amount"))
                for row in rows
            ),2)

            if billed==0:
                billed=self._migration_revenue_number(
                    first.get("billed_to_date")
                )

            if cash==0:
                cash=self._migration_revenue_number(
                    first.get("cash_received_to_date")
                )

        else:
            billed=self._migration_revenue_number(
                first.get("billed_to_date")
            )

            cash=self._migration_revenue_number(
                first.get("cash_received_to_date")
            )

        if mode=="opening_position":
            calculated_revenue=imported_revenue

        calculated_position=self.migration_revenue_position(
            calculated_revenue,
            billed,
            cash,
        )

        imported_position=self.migration_revenue_position(
            imported_revenue,
            billed,
            cash,
        )

        tolerance=float(
            settings.get("reconciliation_tolerance") or 1
        )

        revenue_difference=round(
            imported_revenue-calculated_revenue,
            2,
        )

        if (
            mode!="opening_position"
            and abs(revenue_difference)>tolerance
        ):
            issues.append(
                f"Imported revenue to date differs from reconstructed revenue by {revenue_difference:.2f}."
            )

        source_ca=first.get("contract_asset_balance")
        source_cl=first.get("contract_liability_balance")
        source_ar=first.get("accounts_receivable_balance")

        if source_ca not in (None,""):
            diff=round(
                self._migration_revenue_number(source_ca)
                -imported_position["contract_asset_balance"],
                2,
            )

            if abs(diff)>tolerance:
                issues.append(
                    f"Contract asset differs from reconstructed position by {diff:.2f}."
                )

        if source_cl not in (None,""):
            diff=round(
                self._migration_revenue_number(source_cl)
                -imported_position["contract_liability_balance"],
                2,
            )

            if abs(diff)>tolerance:
                issues.append(
                    f"Contract liability differs from reconstructed position by {diff:.2f}."
                )

        if source_ar not in (None,""):
            diff=round(
                self._migration_revenue_number(source_ar)
                -imported_position["accounts_receivable_balance"],
                2,
            )

            if abs(diff)>tolerance:
                issues.append(
                    f"Receivable differs from reconstructed position by {diff:.2f}."
                )

        if settings.get("require_gl_mapping"):
            for field,label in [
                ("revenue_account_code","Revenue account"),
                ("contract_asset_account_code","Contract asset account"),
                ("contract_liability_account_code","Contract liability account"),
            ]:
                if not settings.get(field):
                    issues.append(f"{label} is not configured.")

        variations=[]

        for row in rows:
            ref=str(row.get("variation_reference") or "").strip()

            if ref and not any(
                item["reference"]==ref
                for item in variations
            ):
                variations.append({
                    "reference":ref,
                    "amount":self._migration_revenue_number(
                        row.get("variation_amount")
                    ),
                })

        claims=[]

        for row in rows:
            ref=str(row.get("claim_reference") or "").strip()

            if ref and not any(
                item["reference"]==ref
                for item in claims
            ):
                claims.append({
                    "reference":ref,
                    "amount":self._migration_revenue_number(
                        row.get("claim_amount")
                    ),
                    "status":row.get("claim_status"),
                })

        payload={
            "customer_id":customer_id,
            "project_id":project_target_id,

            "contract_number":contract_number,
            "contract_title":contract_title,

            "contract_currency":str(
                first.get("contract_currency")
                or settings.get("default_currency")
                or "USD"
            ).strip().upper(),

            "contract_date":
                self._migration_revenue_date(
                    first.get("contract_date")
                ),

            "start_date":start_date,
            "end_date":end_date,

            "billing_method":billing_method,
            "transaction_price":round(transaction_price,2),

            "variable_consideration_est":
                self._migration_revenue_number(
                    first.get("variable_consideration_est")
                ),

            "variable_consideration_constrained":
                self._migration_revenue_number(
                    first.get("variable_consideration_constrained")
                ),

            "has_significant_financing_component":
                self._migration_revenue_bool(
                    first.get("has_significant_financing_component")
                ),

            "financing_component_amount":
                self._migration_revenue_number(
                    first.get("financing_component_amount")
                ),

            "is_over_time":is_over_time,

            "recognized_revenue_to_date":round(imported_revenue,2),
            "billed_to_date":round(billed,2),
            "cash_received_to_date":round(cash,2),

            "contract_asset_balance":
                imported_position["contract_asset_balance"],

            "contract_liability_balance":
                imported_position["contract_liability_balance"],

            "accounts_receivable_balance":
                imported_position["accounts_receivable_balance"],

            "migration_date":migration_date,
            "notes":first.get("notes"),

            "payload_json":{
                "migration":{
                    "source_mode":mode,
                    "migration_date":str(migration_date),
                    "variations":variations,
                    "claims":claims,
                }
            },
        }

        return {
            "valid":not issues,
            "issues":issues,

            "payload":payload,
            "obligations":obligation_previews,

            "reconciliation":{
                "transaction_price":round(transaction_price,2),

                "calculated_revenue_to_date":
                    round(calculated_revenue,2),

                "imported_revenue_to_date":
                    round(imported_revenue,2),

                "revenue_difference":
                    revenue_difference,

                "billed_to_date":
                    round(billed,2),

                "cash_received_to_date":
                    round(cash,2),

                "tolerance":tolerance,
            },

            "position":imported_position,

            "history":{
                "variation_count":len(variations),
                "claim_count":len(claims),

                "billing_event_count":sum(
                    1 for row in rows
                    if self._migration_revenue_number(
                        row.get("billing_amount")
                    )!=0
                ),

                "cash_event_count":sum(
                    1 for row in rows
                    if self._migration_revenue_number(
                        row.get("receipt_amount")
                    )!=0
                ),

                "progress_event_count":sum(
                    1 for row in rows
                    if row.get("progress_date")
                ),
            },
        }

    def migration_revenue_preview(
        self,company_id:int,project_id:int,dataset_id:int,*,cur=None
    )->dict:
        settings=self.migration_revenue_settings_get(
            company_id,project_id,dataset_id,cur=cur
        )

        rows=self.migration_revenue_normalized_rows(
            company_id,project_id,dataset_id,
            limit=200,
            cur=cur,
        )

        groups=self.migration_revenue_group_contracts(rows)

        previews=[]

        for index,(contract_key,group_rows) in enumerate(
            groups.items(),
            start=1,
        ):
            try:
                preview=self.migration_revenue_contract_preview(
                    company_id,
                    project_id,
                    dataset_id,
                    group_rows,
                    settings,
                    cur=cur,
                )

            except Exception as error:
                preview={
                    "valid":False,
                    "issues":[str(error)],
                    "payload":group_rows[0] if group_rows else {},
                    "obligations":[],
                    "reconciliation":{},
                    "position":{},
                    "history":{},
                }

            previews.append({
                "row_number":index,
                "contract_key":contract_key,
                **preview,
            })

        return {
            "dataset_id":int(dataset_id),
            "source_mode":settings.get("source_mode"),
            "contracts":previews,

            "contract_count":len(previews),

            "valid_count":sum(
                1 for row in previews
                if row.get("valid")
            ),

            "error_count":sum(
                1 for row in previews
                if not row.get("valid")
            ),

            "total_transaction_price":round(sum(
                self._migration_revenue_number(
                    row.get("payload",{}).get("transaction_price")
                )
                for row in previews
            ),2),

            "total_revenue_to_date":round(sum(
                self._migration_revenue_number(
                    row.get("position",{}).get(
                        "recognized_revenue_to_date"
                    )
                )
                for row in previews
            ),2),

            "total_contract_assets":round(sum(
                self._migration_revenue_number(
                    row.get("position",{}).get(
                        "contract_asset_balance"
                    )
                )
                for row in previews
            ),2),

            "total_contract_liabilities":round(sum(
                self._migration_revenue_number(
                    row.get("position",{}).get(
                        "contract_liability_balance"
                    )
                )
                for row in previews
            ),2),
        }

    def migration_revenue_mapping_get(
        self,company_id:int,project_id:int,dataset_id:int,*,cur=None
    )->dict:
        settings=self.migration_revenue_settings_get(
            company_id,project_id,dataset_id,cur=cur
        )

        field_mapping=self.migration_field_mapping_dataset(
            company_id,project_id,dataset_id,cur=cur
        )

        references=self.migration_revenue_source_references(
            company_id,project_id,dataset_id,cur=cur
        )

        mode=settings.get("source_mode") or "contract_and_progress"

        required={
            "full_history":{
                "contract_number",
                "contract_title",
                "customer_reference",
                "contract_date",
                "transaction_price",
            },

            "contract_and_progress":{
                "contract_number",
                "contract_title",
                "customer_reference",
                "contract_date",
                "transaction_price",
                "progress_method",
            },

            "opening_position":{
                "contract_number",
                "contract_title",
                "customer_reference",
                "contract_date",
                "transaction_price",
                "recognized_revenue_to_date",
                "billed_to_date",
            },
        }[mode]

        mapped={
            row.get("target_field_code")
            for row in field_mapping.get("rows") or []
            if row.get("mapping_status")=="mapped"
        }

        missing_fields=sorted(required-mapped)
        missing_references=[]

        if settings.get("require_customer_mapping"):
            for row in references["customer"]["rows"]:
                if not row.get("target_id") or not row.get("is_approved"):
                    missing_references.append({
                        "reference_type":"customer",
                        "source_value":row.get("source_value"),
                    })

        if settings.get("require_project_mapping"):
            for row in references["project"]["rows"]:
                if not row.get("target_id") or not row.get("is_approved"):
                    missing_references.append({
                        "reference_type":"project",
                        "source_value":row.get("source_value"),
                    })

        return {
            "settings":settings,
            "field_mapping":field_mapping,
            "references":references,

            "source_mode":mode,

            "missing_fields":missing_fields,
            "missing_references":missing_references,

            "is_complete":
                not missing_fields
                and not missing_references,
        }

    def _migration_ad_number(self,value,default=0.0)->float:
        if value in (None,""):return float(default or 0)
        try:return float(str(value).replace(",","").strip())
        except Exception:return float(default or 0)


    def _migration_ad_int(self,value,default=0)->int:
        if value in (None,""):return int(default or 0)
        try:return int(float(str(value).replace(",","").strip()))
        except Exception:return int(default or 0)


    def _migration_ad_date(self,value,required=False):
        if isinstance(value,date):return value

        text=str(value or "").strip()

        if not text:
            if required:raise ValueError("Date is required.")
            return None

        try:return datetime.strptime(text[:10],"%Y-%m-%d").date()
        except Exception:
            if required:raise ValueError(f"Invalid date: {text}")
            return None


    def _migration_ad_month_end(self,value:date)->date:
        if value.month==12:return date(value.year,12,31)
        return date(value.year,value.month+1,1)-timedelta(days=1)


    def _migration_ad_add_month(self,value:date)->date:
        if value.month==12:return date(value.year+1,1,1)
        return date(value.year,value.month+1,1)


    def migration_accrual_datasets(
        self,company_id:int,project_id:int,*,cur=None
    )->list[dict]:
        company_id,project_id=int(company_id),int(project_id)
        schema=self.company_schema(company_id)

        return self.fetch_all(f"""
            SELECT
                d.id AS dataset_id,
                d.dataset_name,
                d.record_count,
                d.column_count,
                d.dataset_status,
                f.original_name AS source_file_name
            FROM {schema}.migration_source_datasets d
            JOIN {schema}.migration_source_files f
            ON f.id=d.source_file_id
            WHERE d.company_id=%s
            AND d.project_id=%s
            AND d.entity_code='accrual_deferrals'
            AND d.is_selected=TRUE
            ORDER BY d.id
        """,(company_id,project_id),cur=cur) or []

    def migration_accrual_gl_defaults(
        self,company_id:int,*,cur=None
    )->dict:
        company_id=int(company_id)

        out={
            "prepaid_expense_account":None,
            "deferred_expense_account":None,
            "deferred_income_account":None,
            "accrued_income_account":None,
            "accrued_expense_account":None,
        }

        for field,role in {
            "prepaid_expense_account":"prepaid_expense",
            "deferred_expense_account":"deferred_expense",
            "deferred_income_account":"deferred_income",
            "accrued_income_account":"accrued_income",
            "accrued_expense_account":"accrued_expense",
        }.items():
            try:
                row=self.accrual_deferral_account_by_role(
                    company_id,
                    role,
                ) or {}

                out[field]=row.get("code")
            except Exception:
                out[field]=None

        return out

    def migration_accrual_settings_get(
        self,company_id:int,project_id:int,dataset_id:int,*,cur=None
    )->dict:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)

        project=self.fetch_one(f"""
            SELECT cutover_date,default_currency
            FROM {schema}.migration_projects
            WHERE company_id=%s AND id=%s
        """,(company_id,project_id),cur=cur)

        if not project:
            raise ValueError("Migration project not found.")

        row=self.fetch_one(f"""
            SELECT *
            FROM {schema}.migration_accrual_settings
            WHERE company_id=%s
            AND project_id=%s
            AND dataset_id=%s
        """,(company_id,project_id,dataset_id),cur=cur)

        if row:
            row["settings_json"]=self._migration_json(
                row.get("settings_json"),{}
            )
            row["metadata_json"]=self._migration_json(
                row.get("metadata_json"),{}
            )
            return row

        gl=self.migration_accrual_gl_defaults(
            company_id,
            cur=cur,
        )

        return {
            "company_id":company_id,
            "project_id":project_id,
            "dataset_id":dataset_id,

            "source_mode":"original_terms",
            "migration_date":project.get("cutover_date"),

            "default_currency":project.get("default_currency"),
            "default_item_type":"prepaid_expense",
            "default_recognition_method":"straight_line",
            "default_frequency":"monthly",
            "default_tax_mode":"no_vat",

            **gl,

            "default_recognition_account":None,
            "default_settlement_account":None,
            "default_tax_account":None,

            "require_counterparty_mapping":False,
            "require_gl_mapping":True,
            "reconciliation_tolerance":1.00,

            "settings_json":{},
            "metadata_json":{},
        }

    def migration_accrual_settings_save(
        self,company_id:int,project_id:int,dataset_id:int,data:dict,
        *,user_id:int|None=None,cur=None
    )->dict:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)
        data=data or {}

        current=self.migration_accrual_settings_get(
            company_id,project_id,dataset_id,cur=cur
        )

        source_mode=str(
            data.get("source_mode") or current["source_mode"]
        ).strip().lower()

        item_type=str(
            data.get("default_item_type") or current["default_item_type"]
        ).strip().lower()

        method=str(
            data.get("default_recognition_method")
            or current["default_recognition_method"]
        ).strip().lower()

        frequency=str(
            data.get("default_frequency") or current["default_frequency"]
        ).strip().lower()

        tax_mode=str(
            data.get("default_tax_mode") or current["default_tax_mode"]
        ).strip().lower()

        if source_mode not in {
            "original_terms","existing_schedule","opening_position"
        }:
            raise ValueError("Invalid accrual migration source mode.")

        if item_type not in {
            "prepaid_expense","deferred_expense","deferred_income",
            "accrued_income","accrued_expense"
        }:
            raise ValueError("Invalid accrual/deferral item type.")

        if method not in {
            "straight_line","manual","units","milestone"
        }:
            raise ValueError("Invalid recognition method.")

        if frequency not in {
            "monthly","quarterly","annually","once","manual"
        }:
            raise ValueError("Invalid recognition frequency.")

        if tax_mode not in {
            "exclusive","inclusive","no_vat"
        }:
            raise ValueError("Invalid tax mode.")

        self.execute_sql(f"""
            INSERT INTO {schema}.migration_accrual_settings(
                company_id,project_id,dataset_id,
                source_mode,migration_date,
                default_currency,
                default_item_type,
                default_recognition_method,
                default_frequency,
                default_tax_mode,

                prepaid_expense_account,
                deferred_expense_account,
                deferred_income_account,
                accrued_income_account,
                accrued_expense_account,

                default_recognition_account,
                default_settlement_account,
                default_tax_account,

                require_counterparty_mapping,
                require_gl_mapping,
                reconciliation_tolerance,

                settings_json,metadata_json,
                created_by_user_id,updated_by_user_id,
                created_at,updated_at
            )
            VALUES(
                %s,%s,%s,%s,%s,%s,%s,%s,%s,%s,
                %s,%s,%s,%s,%s,
                %s,%s,%s,
                %s,%s,%s,
                %s::jsonb,%s::jsonb,
                %s,%s,NOW(),NOW()
            )
            ON CONFLICT(company_id,project_id,dataset_id)
            DO UPDATE SET
                source_mode=EXCLUDED.source_mode,
                migration_date=EXCLUDED.migration_date,
                default_currency=EXCLUDED.default_currency,
                default_item_type=EXCLUDED.default_item_type,
                default_recognition_method=EXCLUDED.default_recognition_method,
                default_frequency=EXCLUDED.default_frequency,
                default_tax_mode=EXCLUDED.default_tax_mode,

                prepaid_expense_account=EXCLUDED.prepaid_expense_account,
                deferred_expense_account=EXCLUDED.deferred_expense_account,
                deferred_income_account=EXCLUDED.deferred_income_account,
                accrued_income_account=EXCLUDED.accrued_income_account,
                accrued_expense_account=EXCLUDED.accrued_expense_account,

                default_recognition_account=EXCLUDED.default_recognition_account,
                default_settlement_account=EXCLUDED.default_settlement_account,
                default_tax_account=EXCLUDED.default_tax_account,

                require_counterparty_mapping=EXCLUDED.require_counterparty_mapping,
                require_gl_mapping=EXCLUDED.require_gl_mapping,
                reconciliation_tolerance=EXCLUDED.reconciliation_tolerance,

                settings_json=EXCLUDED.settings_json,
                metadata_json=EXCLUDED.metadata_json,
                updated_by_user_id=EXCLUDED.updated_by_user_id,
                updated_at=NOW()
        """,(
            company_id,project_id,dataset_id,
            source_mode,
            data.get("migration_date") or current.get("migration_date"),

            data.get("default_currency") or current.get("default_currency"),
            item_type,method,frequency,tax_mode,

            data.get("prepaid_expense_account")
                or current.get("prepaid_expense_account"),

            data.get("deferred_expense_account")
                or current.get("deferred_expense_account"),

            data.get("deferred_income_account")
                or current.get("deferred_income_account"),

            data.get("accrued_income_account")
                or current.get("accrued_income_account"),

            data.get("accrued_expense_account")
                or current.get("accrued_expense_account"),

            data.get("default_recognition_account")
                or current.get("default_recognition_account"),

            data.get("default_settlement_account")
                or current.get("default_settlement_account"),

            data.get("default_tax_account")
                or current.get("default_tax_account"),

            bool(data.get(
                "require_counterparty_mapping",
                current.get("require_counterparty_mapping",False),
            )),

            bool(data.get(
                "require_gl_mapping",
                current.get("require_gl_mapping",True),
            )),

            float(
                data.get("reconciliation_tolerance")
                if data.get("reconciliation_tolerance") not in (None,"")
                else current.get("reconciliation_tolerance") or 1
            ),

            self._migration_json_dump(
                data.get("settings_json") or current.get("settings_json"),{}
            ),

            self._migration_json_dump(
                data.get("metadata_json") or current.get("metadata_json"),{}
            ),

            user_id,user_id,
        ),cur=cur)

        return self.migration_accrual_settings_get(
            company_id,project_id,dataset_id,cur=cur
        )

    def migration_accrual_reference_targets(
        self,company_id:int,reference_type:str,*,cur=None
    )->list[dict]:
        company_id=int(company_id)
        schema=self.company_schema(company_id)
        reference_type=str(reference_type or "").strip().lower()

        if reference_type=="customer":
            rows=self.fetch_all(f"""
                SELECT id,external_code,name
                FROM {schema}.customers
                WHERE company_id=%s
                AND COALESCE(is_active,TRUE)=TRUE
                ORDER BY name,id
            """,(company_id,),cur=cur) or []

            return [{
                "id":row["id"],
                "code":row.get("external_code"),
                "label":row.get("name") or f"Customer {row['id']}",
            } for row in rows]

        if reference_type=="vendor":
            rows=self.fetch_all(f"""
                SELECT id,vendor_code,name
                FROM {schema}.vendors
                WHERE company_id=%s
                ORDER BY name,id
            """,(company_id,),cur=cur) or []

            return [{
                "id":row["id"],
                "code":row.get("vendor_code"),
                "label":row.get("name") or f"Vendor {row['id']}",
            } for row in rows]

        if reference_type=="employee":
            rows=self.fetch_all(f"""
                SELECT id,employee_number,first_name,last_name
                FROM {schema}.payroll_employees
                WHERE company_id=%s
                ORDER BY last_name,first_name,id
            """,(company_id,),cur=cur) or []

            return [{
                "id":row["id"],
                "code":row.get("employee_number"),
                "label":" ".join(filter(None,[
                    row.get("first_name"),
                    row.get("last_name"),
                ])) or f"Employee {row['id']}",
            } for row in rows]

        raise ValueError(
            f"Unsupported accrual reference type: {reference_type}"
        )

    def migration_accrual_source_references(
        self,company_id:int,project_id:int,dataset_id:int,*,cur=None
    )->dict:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)

        mapping=self.migration_field_mapping_dataset(
            company_id,project_id,dataset_id,cur=cur
        )

        dataset=self.fetch_one(f"""
            SELECT metadata_json
            FROM {schema}.migration_source_datasets
            WHERE company_id=%s
            AND project_id=%s
            AND id=%s
        """,(company_id,project_id,dataset_id),cur=cur)

        metadata=self._migration_json(
            dataset.get("metadata_json") if dataset else {},
            {},
        )

        sample_rows=metadata.get("sample_rows") or []

        target_to_source={
            row["target_field_code"]:row["source_name"]
            for row in mapping.get("rows") or []
            if row.get("mapping_status")=="mapped"
            and row.get("target_field_code")
        }

        config={
            "customer":"customer_reference",
            "vendor":"vendor_reference",
            "employee":"employee_reference",
        }

        result={}

        for reference_type,target_field in config.items():
            source_name=target_to_source.get(target_field)
            values={}

            if source_name:
                for source_row in sample_rows:
                    value=str(source_row.get(source_name) or "").strip()
                    if value:values[value]=values.get(value,0)+1

            saved=self.fetch_all(f"""
                SELECT *
                FROM {schema}.migration_accrual_reference_mappings
                WHERE company_id=%s
                AND project_id=%s
                AND dataset_id=%s
                AND reference_type=%s
            """,(
                company_id,project_id,dataset_id,reference_type
            ),cur=cur) or []

            saved_map={
                row["source_value"]:row
                for row in saved
            }

            result[reference_type]={
                "rows":[
                    {
                        "source_value":value,
                        "sample_count":count,
                        **(saved_map.get(value) or {}),
                    }
                    for value,count in sorted(values.items())
                ],

                "targets":self.migration_accrual_reference_targets(
                    company_id,
                    reference_type,
                    cur=cur,
                ),
            }

        return result

    def migration_accrual_reference_save(
        self,company_id:int,project_id:int,dataset_id:int,mappings:list[dict],
        *,user_id:int|None=None,cur=None
    )->dict:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)

        if not isinstance(mappings,list):
            raise ValueError("mappings must be a list.")

        for item in mappings:
            reference_type=str(
                item.get("reference_type") or ""
            ).strip().lower()

            source_value=str(
                item.get("source_value") or ""
            ).strip()

            target_id=int(item.get("target_id") or 0)

            if reference_type not in {
                "customer","vendor","employee"
            }:
                raise ValueError(
                    f"Unsupported accrual reference type: {reference_type}"
                )

            if not source_value:
                raise ValueError("Source reference value is required.")

            if not target_id:
                raise ValueError(
                    f'Target required for "{source_value}".'
                )

            targets=self.migration_accrual_reference_targets(
                company_id,
                reference_type,
                cur=cur,
            )

            target=next(
                (row for row in targets if int(row["id"])==target_id),
                None,
            )

            if not target:
                raise ValueError(
                    f'Invalid target for "{source_value}".'
                )

            self.execute_sql(f"""
                INSERT INTO {schema}.migration_accrual_reference_mappings(
                    company_id,project_id,dataset_id,
                    reference_type,source_value,source_label,
                    target_id,target_code,target_label,
                    mapping_method,confidence,is_approved,
                    metadata_json,
                    created_by_user_id,updated_by_user_id,
                    created_at,updated_at
                )
                VALUES(
                    %s,%s,%s,%s,%s,%s,
                    %s,%s,%s,
                    'manual',100,TRUE,
                    '{{}}'::jsonb,
                    %s,%s,NOW(),NOW()
                )
                ON CONFLICT(
                    company_id,project_id,dataset_id,
                    reference_type,source_value
                )
                DO UPDATE SET
                    target_id=EXCLUDED.target_id,
                    target_code=EXCLUDED.target_code,
                    target_label=EXCLUDED.target_label,
                    mapping_method='manual',
                    confidence=100,
                    is_approved=TRUE,
                    updated_by_user_id=EXCLUDED.updated_by_user_id,
                    updated_at=NOW()
            """,(
                company_id,project_id,dataset_id,
                reference_type,source_value,
                item.get("source_label") or source_value,
                target_id,target.get("code"),target.get("label"),
                user_id,user_id,
            ),cur=cur)

        return self.migration_accrual_source_references(
            company_id,project_id,dataset_id,cur=cur
        )


    def migration_accrual_reference_resolve(
        self,company_id:int,project_id:int,dataset_id:int,
        reference_type:str,source_value,*,cur=None
    ):
        value=str(source_value or "").strip()
        if not value:return None

        schema=self.company_schema(int(company_id))

        row=self.fetch_one(f"""
            SELECT target_id
            FROM {schema}.migration_accrual_reference_mappings
            WHERE company_id=%s
            AND project_id=%s
            AND dataset_id=%s
            AND reference_type=%s
            AND source_value=%s
            AND is_approved=TRUE
        """,(
            int(company_id),
            int(project_id),
            int(dataset_id),
            reference_type,
            value,
        ),cur=cur)

        return (
            int(row["target_id"])
            if row and row.get("target_id")
            else None
        )


    def migration_accrual_normalized_rows(
        self,company_id:int,project_id:int,dataset_id:int,
        *,limit:int=200,cur=None
    )->list[dict]:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)

        mapping=self.migration_field_mapping_dataset(
            company_id,project_id,dataset_id,cur=cur
        )

        dataset=self.fetch_one(f"""
            SELECT metadata_json
            FROM {schema}.migration_source_datasets
            WHERE company_id=%s
            AND project_id=%s
            AND id=%s
        """,(company_id,project_id,dataset_id),cur=cur)

        metadata=self._migration_json(
            dataset.get("metadata_json") if dataset else {},
            {},
        )

        source_rows=metadata.get("sample_rows") or []

        source_to_target={
            row["source_name"]:row["target_field_code"]
            for row in mapping.get("rows") or []
            if row.get("mapping_status")=="mapped"
            and row.get("target_field_code")
        }

        result=[]

        for source_row in source_rows[:limit]:
            normalized={}

            for source_name,target_field in source_to_target.items():
                normalized[target_field]=source_row.get(source_name)

            result.append({
                "source":source_row,
                "normalized":normalized,
            })

        return result

    def migration_accrual_straight_line_schedule(
        self,start_date:date,end_date:date,amount:float
    )->list[dict]:
        start=self._migration_ad_date(start_date,required=True)
        end=self._migration_ad_date(end_date,required=True)
        amount=round(float(amount or 0),2)

        if end<start:
            raise ValueError("Recognition end date cannot be before start date.")

        if amount<=0:
            raise ValueError("Original amount must be greater than zero.")

        months=[]
        cursor=date(start.year,start.month,1)

        while cursor<=end:
            period_start=max(cursor,start)
            period_end=min(
                self._migration_ad_month_end(cursor),
                end,
            )

            months.append((period_start,period_end))
            cursor=self._migration_ad_add_month(cursor)

        if not months:return []

        normal_amount=round(amount/len(months),2)
        opening=amount
        schedule=[]

        for index,(period_start,period_end) in enumerate(months,start=1):
            recognition=(
                opening
                if index==len(months)
                else min(normal_amount,opening)
            )

            recognition=round(recognition,2)
            closing=round(max(opening-recognition,0),2)

            schedule.append({
                "line_no":index,
                "period_start":period_start,
                "period_end":period_end,
                "recognition_date":period_end,
                "opening_balance":round(opening,2),
                "recognition_amount":recognition,
                "closing_balance":closing,
            })

            opening=closing

        return schedule

    def migration_accrual_balance_account(
        self,item_type:str,row:dict,settings:dict
    ):
        direct=str(row.get("balance_account") or "").strip()
        if direct:return direct

        return {
            "prepaid_expense":
                settings.get("prepaid_expense_account"),

            "deferred_expense":
                settings.get("deferred_expense_account"),

            "deferred_income":
                settings.get("deferred_income_account"),

            "accrued_income":
                settings.get("accrued_income_account"),

            "accrued_expense":
                settings.get("accrued_expense_account"),
        }.get(item_type)

    def migration_accrual_recognition_journal(
        self,item_type:str,amount:float,
        balance_account:str|None,
        recognition_account:str|None,
    )->list[dict]:
        amount=round(float(amount or 0),2)

        if amount<=0:
            return []

        if not balance_account:
            raise ValueError("Balance account is required.")

        if not recognition_account:
            raise ValueError("Recognition account is required.")

        if item_type in {
            "prepaid_expense",
            "deferred_expense",
            "accrued_expense",
        }:
            debit_account=recognition_account
            credit_account=balance_account

        elif item_type=="deferred_income":
            debit_account=balance_account
            credit_account=recognition_account

        elif item_type=="accrued_income":
            debit_account=balance_account
            credit_account=recognition_account

        else:
            raise ValueError(
                f"Unsupported item type: {item_type}"
            )

        return [
            {
                "account_code":debit_account,
                "debit":amount,
                "credit":0.0,
            },
            {
                "account_code":credit_account,
                "debit":0.0,
                "credit":amount,
            },
        ]

    def migration_accrual_original_preview(
        self,company_id:int,project_id:int,dataset_id:int,
        row:dict,settings:dict,*,cur=None
    )->dict:
        item_type=str(
            row.get("item_type")
            or settings.get("default_item_type")
            or "prepaid_expense"
        ).strip().lower()

        method=str(
            row.get("recognition_method")
            or settings.get("default_recognition_method")
            or "straight_line"
        ).strip().lower()

        frequency=str(
            row.get("frequency")
            or settings.get("default_frequency")
            or "monthly"
        ).strip().lower()

        migration_date=self._migration_ad_date(
            row.get("migration_date")
            or settings.get("migration_date"),
            required=True,
        )

        start_date=self._migration_ad_date(
            row.get("start_date"),
            required=True,
        )

        end_date=self._migration_ad_date(
            row.get("end_date"),
            required=True,
        )

        transaction_date=self._migration_ad_date(
            row.get("transaction_date")
        ) or start_date

        original=self._migration_ad_number(
            row.get("original_amount")
        )

        issues=[]

        if item_type not in {
            "prepaid_expense","deferred_expense","deferred_income",
            "accrued_income","accrued_expense"
        }:
            issues.append(f"Unsupported item type: {item_type}.")

        if original<=0:
            issues.append("Original amount must be greater than zero.")

        if end_date<start_date:
            issues.append("End date cannot be before start date.")

        if migration_date<transaction_date:
            issues.append(
                "Migration date cannot be before transaction date."
            )

        if method!="straight_line":
            issues.append(
                f"{method} cannot be reconstructed from original terms alone; use Existing Schedule or Opening Position mode."
            )

        schedule=[]

        if not issues:
            schedule=self.migration_accrual_straight_line_schedule(
                start_date,
                end_date,
                original,
            )

        past=[
            line for line in schedule
            if line["recognition_date"]<=migration_date
        ]

        future=[
            line for line in schedule
            if line["recognition_date"]>migration_date
        ]

        calculated_recognized=round(sum(
            line["recognition_amount"]
            for line in past
        ),2)

        calculated_remaining=round(
            max(original-calculated_recognized,0),
            2,
        )

        imported_recognized=self._migration_ad_number(
            row.get("recognized_to_date"),
            calculated_recognized,
        )

        imported_remaining=self._migration_ad_number(
            row.get("remaining_balance"),
            max(original-imported_recognized,0),
        )

        tolerance=float(
            settings.get("reconciliation_tolerance") or 1
        )

        recognized_difference=round(
            imported_recognized-calculated_recognized,
            2,
        )

        remaining_difference=round(
            imported_remaining-calculated_remaining,
            2,
        )

        if abs(recognized_difference)>tolerance:
            issues.append(
                f"Recognised-to-date differs from reconstructed schedule by {recognized_difference:.2f}."
            )

        if abs(remaining_difference)>tolerance:
            issues.append(
                f"Remaining balance differs from reconstructed schedule by {remaining_difference:.2f}."
            )

        balance_account=self.migration_accrual_balance_account(
            item_type,row,settings
        )

        recognition_account=(
            row.get("recognition_account")
            or settings.get("default_recognition_account")
        )

        settlement_account=(
            row.get("settlement_account")
            or settings.get("default_settlement_account")
        )

        tax_account=(
            row.get("tax_account")
            or settings.get("default_tax_account")
        )

        if settings.get("require_gl_mapping"):
            if not balance_account:
                issues.append("Balance account is not mapped.")

            if not recognition_account:
                issues.append("Recognition account is not mapped.")

        customer_id=self.migration_accrual_reference_resolve(
            company_id,project_id,dataset_id,
            "customer",
            row.get("customer_reference"),
            cur=cur,
        )

        vendor_id=self.migration_accrual_reference_resolve(
            company_id,project_id,dataset_id,
            "vendor",
            row.get("vendor_reference"),
            cur=cur,
        )

        employee_id=self.migration_accrual_reference_resolve(
            company_id,project_id,dataset_id,
            "employee",
            row.get("employee_reference"),
            cur=cur,
        )

        counterparty_type=str(
            row.get("counterparty_type") or ""
        ).strip().lower() or None

        if not counterparty_type:
            if customer_id:counterparty_type="customer"
            elif vendor_id:counterparty_type="supplier"
            elif employee_id:counterparty_type="employee"

        if settings.get("require_counterparty_mapping"):
            source_counterparty=(
                row.get("customer_reference")
                or row.get("vendor_reference")
                or row.get("employee_reference")
            )

            if source_counterparty and not any([
                customer_id,
                vendor_id,
                employee_id,
            ]):
                issues.append("Counterparty is not mapped.")

        next_line=future[0] if future else None

        payload={
            "item_number":
                str(row.get("item_number") or "").strip() or None,

            "item_title":
                str(row.get("item_title") or "").strip(),

            "item_type":item_type,
            "status":"active",

            "counterparty_type":counterparty_type,
            "customer_id":customer_id,
            "supplier_id":vendor_id,
            "employee_id":employee_id,

            "currency":str(
                row.get("currency")
                or settings.get("default_currency")
                or "USD"
            ).strip().upper(),

            "transaction_date":transaction_date,
            "start_date":start_date,
            "end_date":end_date,

            "original_amount":round(original,2),
            "recognized_to_date":round(imported_recognized,2),
            "remaining_balance":round(imported_remaining,2),

            "recognition_method":method,
            "frequency":frequency,

            "balance_account":balance_account,
            "balance_account_role":
                row.get("balance_account_role") or item_type,

            "recognition_account":recognition_account,
            "recognition_account_role":
                row.get("recognition_account_role"),

            "settlement_account":settlement_account,
            "settlement_role":row.get("settlement_role"),

            "tax_account":tax_account,

            "vat_amount":self._migration_ad_number(
                row.get("vat_amount")
            ),

            "tax_mode":str(
                row.get("tax_mode")
                or settings.get("default_tax_mode")
                or "no_vat"
            ).strip().lower(),

            "tax_treatment_code":
                row.get("tax_treatment_code"),

            "tax_base_override":
                self._migration_ad_number(
                    row.get("tax_base_override")
                ) if row.get("tax_base_override") not in (None,"") else None,

            "manual_tax_base":
                self._migration_ad_number(
                    row.get("manual_tax_base")
                ) if row.get("manual_tax_base") not in (None,"") else None,

            "notes":row.get("notes"),

            "migration_date":migration_date,

            "payload_json":{
                "migration":{
                    "source_mode":"original_terms",
                    "migration_date":str(migration_date),
                }
            },
        }

        return {
            "valid":not issues,
            "issues":issues,
            "source_mode":"original_terms",
            "payload":payload,

            "reconciliation":{
                "original_amount":round(original,2),

                "calculated_recognized_to_date":
                    calculated_recognized,

                "imported_recognized_to_date":
                    round(imported_recognized,2),

                "recognized_difference":
                    recognized_difference,

                "calculated_remaining_balance":
                    calculated_remaining,

                "imported_remaining_balance":
                    round(imported_remaining,2),

                "remaining_difference":
                    remaining_difference,

                "tolerance":tolerance,
            },

            "cutover":{
                "migration_date":migration_date,
                "recognized_to_date":round(imported_recognized,2),
                "remaining_balance":round(imported_remaining,2),
                "recognized_percent":round(
                    imported_recognized/original*100,
                    2,
                ) if original else 0,
            },

            "next_recognition":(
                {
                    "date":next_line["recognition_date"],
                    "amount":next_line["recognition_amount"],
                    "opening_balance":next_line["opening_balance"],
                    "closing_balance":next_line["closing_balance"],

                    "journal_lines":
                        self.migration_accrual_recognition_journal(
                            item_type,
                            next_line["recognition_amount"],
                            balance_account,
                            recognition_account,
                        ) if balance_account and recognition_account else [],
                }
                if next_line else None
            ),

            "schedule":schedule,
        }

    def migration_accrual_opening_preview(
        self,company_id:int,project_id:int,dataset_id:int,
        row:dict,settings:dict,*,cur=None
    )->dict:
        item_type=str(
            row.get("item_type")
            or settings.get("default_item_type")
            or "prepaid_expense"
        ).strip().lower()

        migration_date=self._migration_ad_date(
            row.get("migration_date")
            or settings.get("migration_date"),
            required=True,
        )

        start_date=self._migration_ad_date(
            row.get("start_date")
        ) or migration_date

        end_date=self._migration_ad_date(
            row.get("end_date"),
            required=True,
        )

        original=self._migration_ad_number(
            row.get("original_amount")
        )

        recognized=self._migration_ad_number(
            row.get("recognized_to_date")
        )

        remaining=self._migration_ad_number(
            row.get("remaining_balance"),
            max(original-recognized,0),
        )

        issues=[]

        if original<=0:
            issues.append("Original amount must be greater than zero.")

        if recognized<0 or remaining<0:
            issues.append(
                "Recognised and remaining balances cannot be negative."
            )

        balance_check=round(
            original-recognized-remaining,
            2,
        )

        tolerance=float(
            settings.get("reconciliation_tolerance") or 1
        )

        if abs(balance_check)>tolerance:
            issues.append(
                f"Original amount does not reconcile to recognised + remaining by {balance_check:.2f}."
            )

        if end_date<migration_date and remaining>tolerance:
            issues.append(
                "Item has a remaining balance even though its recognition end date is before migration."
            )

        balance_account=self.migration_accrual_balance_account(
            item_type,row,settings
        )

        recognition_account=(
            row.get("recognition_account")
            or settings.get("default_recognition_account")
        )

        if settings.get("require_gl_mapping"):
            if not balance_account:
                issues.append("Balance account is not mapped.")
            if not recognition_account:
                issues.append("Recognition account is not mapped.")

        future_schedule=[]

        if (
            remaining>0
            and end_date>=migration_date
            and str(
                row.get("recognition_method")
                or settings.get("default_recognition_method")
                or "straight_line"
            ).strip().lower()=="straight_line"
        ):
            future_start=max(
                migration_date+timedelta(days=1),
                start_date,
            )

            if future_start<=end_date:
                future_schedule=self.migration_accrual_straight_line_schedule(
                    future_start,
                    end_date,
                    remaining,
                )

        payload={
            "item_number":
                str(row.get("item_number") or "").strip() or None,

            "item_title":
                str(row.get("item_title") or "").strip(),

            "item_type":item_type,

            "currency":str(
                row.get("currency")
                or settings.get("default_currency")
                or "USD"
            ).strip().upper(),

            "transaction_date":
                self._migration_ad_date(
                    row.get("transaction_date")
                ) or start_date,

            "start_date":start_date,
            "end_date":end_date,

            "original_amount":round(original,2),
            "recognized_to_date":round(recognized,2),
            "remaining_balance":round(remaining,2),

            "recognition_method":str(
                row.get("recognition_method")
                or settings.get("default_recognition_method")
                or "straight_line"
            ).strip().lower(),

            "frequency":str(
                row.get("frequency")
                or settings.get("default_frequency")
                or "monthly"
            ).strip().lower(),

            "balance_account":balance_account,
            "recognition_account":recognition_account,

            "settlement_account":
                row.get("settlement_account")
                or settings.get("default_settlement_account"),

            "tax_account":
                row.get("tax_account")
                or settings.get("default_tax_account"),

            "vat_amount":
                self._migration_ad_number(
                    row.get("vat_amount")
                ),

            "tax_mode":str(
                row.get("tax_mode")
                or settings.get("default_tax_mode")
                or "no_vat"
            ).strip().lower(),

            "migration_date":migration_date,
            "notes":row.get("notes"),

            "payload_json":{
                "migration":{
                    "source_mode":"opening_position",
                    "migration_date":str(migration_date),
                }
            },
        }

        return {
            "valid":not issues,
            "issues":issues,
            "source_mode":"opening_position",
            "payload":payload,

            "reconciliation":{
                "original_amount":round(original,2),
                "recognized_to_date":round(recognized,2),
                "remaining_balance":round(remaining,2),
                "balance_difference":balance_check,
                "tolerance":tolerance,
            },

            "cutover":{
                "migration_date":migration_date,
                "recognized_to_date":round(recognized,2),
                "remaining_balance":round(remaining,2),
            },

            "next_recognition":(
                future_schedule[0]
                if future_schedule
                else None
            ),

            "schedule":future_schedule,
        }

    def migration_accrual_existing_schedule_preview(
        self,rows:list[dict],settings:dict
    )->dict:
        if not rows:
            return {
                "valid":False,
                "issues":["No schedule rows found."],
                "source_mode":"existing_schedule",
            }

        first=rows[0]

        migration_date=self._migration_ad_date(
            first.get("migration_date")
            or settings.get("migration_date"),
            required=True,
        )

        tolerance=float(
            settings.get("reconciliation_tolerance") or 1
        )

        schedule=[]
        issues=[]

        sorted_rows=sorted(
            rows,
            key=lambda row:(
                self._migration_ad_int(
                    row.get("schedule_line_no"),
                    999999,
                ),
                self._migration_ad_date(
                    row.get("schedule_recognition_date")
                ) or date.max,
            ),
        )

        previous_closing=None

        for index,row in enumerate(sorted_rows,start=1):
            opening=self._migration_ad_number(
                row.get("schedule_opening_balance")
            )

            recognition=self._migration_ad_number(
                row.get("schedule_recognition_amount")
            )

            closing=self._migration_ad_number(
                row.get("schedule_closing_balance")
            )

            recognition_date=self._migration_ad_date(
                row.get("schedule_recognition_date")
            )

            if not recognition_date:
                issues.append(
                    f"Schedule row {index}: recognition date is required."
                )

            if recognition<0:
                issues.append(
                    f"Schedule row {index}: recognition amount cannot be negative."
                )

            if abs(
                (opening-recognition)-closing
            )>tolerance:
                issues.append(
                    f"Schedule row {index}: opening less recognition does not equal closing."
                )

            if (
                previous_closing is not None
                and abs(opening-previous_closing)>tolerance
            ):
                issues.append(
                    f"Schedule row {index}: opening balance does not agree to previous closing."
                )

            schedule.append({
                "line_no":self._migration_ad_int(
                    row.get("schedule_line_no"),
                    index,
                ),

                "period_start":
                    self._migration_ad_date(
                        row.get("schedule_period_start")
                    ),

                "period_end":
                    self._migration_ad_date(
                        row.get("schedule_period_end")
                    ),

                "recognition_date":recognition_date,

                "opening_balance":round(opening,2),
                "recognition_amount":round(recognition,2),
                "closing_balance":round(closing,2),
            })

            previous_closing=closing

        past=[
            row for row in schedule
            if row.get("recognition_date")
            and row["recognition_date"]<=migration_date
        ]

        future=[
            row for row in schedule
            if row.get("recognition_date")
            and row["recognition_date"]>migration_date
        ]

        original=(
            schedule[0]["opening_balance"]
            if schedule else 0
        )

        calculated_recognized=round(sum(
            row["recognition_amount"]
            for row in past
        ),2)

        calculated_remaining=(
            past[-1]["closing_balance"]
            if past
            else original
        )

        imported_recognized=self._migration_ad_number(
            first.get("recognized_to_date"),
            calculated_recognized,
        )

        imported_remaining=self._migration_ad_number(
            first.get("remaining_balance"),
            calculated_remaining,
        )

        recognized_diff=round(
            imported_recognized-calculated_recognized,
            2,
        )

        remaining_diff=round(
            imported_remaining-calculated_remaining,
            2,
        )

        if abs(recognized_diff)>tolerance:
            issues.append(
                f"Imported recognised-to-date differs from schedule by {recognized_diff:.2f}."
            )

        if abs(remaining_diff)>tolerance:
            issues.append(
                f"Imported remaining balance differs from schedule by {remaining_diff:.2f}."
            )

        return {
            "valid":not issues,
            "issues":issues,
            "source_mode":"existing_schedule",

            "payload":{
                **first,
                "original_amount":original,
                "recognized_to_date":imported_recognized,
                "remaining_balance":imported_remaining,
                "migration_date":migration_date,
            },

            "reconciliation":{
                "original_amount":round(original,2),
                "calculated_recognized_to_date":
                    calculated_recognized,
                "imported_recognized_to_date":
                    round(imported_recognized,2),
                "recognized_difference":recognized_diff,

                "calculated_remaining_balance":
                    round(calculated_remaining,2),
                "imported_remaining_balance":
                    round(imported_remaining,2),
                "remaining_difference":remaining_diff,

                "tolerance":tolerance,
            },

            "cutover":{
                "migration_date":migration_date,
                "recognized_to_date":
                    round(imported_recognized,2),
                "remaining_balance":
                    round(imported_remaining,2),
            },

            "next_recognition":
                future[0] if future else None,

            "schedule":schedule,
        }
    
    def migration_accrual_group_items(
        self,rows:list[dict]
    )->dict:
        groups={}

        for item in rows:
            row=item.get("normalized") or {}

            key=str(
                row.get("item_number")
                or row.get("item_title")
                or "UNIDENTIFIED"
            ).strip()

            groups.setdefault(key,[]).append(row)

        return groups

    def migration_accrual_preview(
        self,company_id:int,project_id:int,dataset_id:int,*,cur=None
    )->dict:
        settings=self.migration_accrual_settings_get(
            company_id,project_id,dataset_id,cur=cur
        )

        rows=self.migration_accrual_normalized_rows(
            company_id,project_id,dataset_id,
            limit=200,
            cur=cur,
        )

        mode=settings.get("source_mode") or "original_terms"
        previews=[]

        if mode=="existing_schedule":
            groups=self.migration_accrual_group_items(rows)

            for index,(key,group_rows) in enumerate(
                groups.items(),
                start=1,
            ):
                try:
                    preview=self.migration_accrual_existing_schedule_preview(
                        group_rows,
                        settings,
                    )

                except Exception as error:
                    preview={
                        "valid":False,
                        "issues":[str(error)],
                        "payload":group_rows[0] if group_rows else {},
                        "schedule":[],
                    }

                previews.append({
                    "row_number":index,
                    "item_key":key,
                    **preview,
                })

        else:
            for index,item in enumerate(rows,start=1):
                normalized=item["normalized"]

                try:
                    if mode=="opening_position":
                        preview=self.migration_accrual_opening_preview(
                            company_id,
                            project_id,
                            dataset_id,
                            normalized,
                            settings,
                            cur=cur,
                        )
                    else:
                        preview=self.migration_accrual_original_preview(
                            company_id,
                            project_id,
                            dataset_id,
                            normalized,
                            settings,
                            cur=cur,
                        )

                except Exception as error:
                    preview={
                        "valid":False,
                        "issues":[str(error)],
                        "payload":normalized,
                        "schedule":[],
                    }

                previews.append({
                    "row_number":index,
                    "source":item["source"],
                    **preview,
                })

        return {
            "dataset_id":int(dataset_id),
            "source_mode":mode,
            "items":previews,

            "item_count":len(previews),

            "valid_count":sum(
                1 for row in previews
                if row.get("valid")
            ),

            "error_count":sum(
                1 for row in previews
                if not row.get("valid")
            ),

            "total_original_amount":round(sum(
                self._migration_ad_number(
                    row.get("payload",{}).get("original_amount")
                )
                for row in previews
            ),2),

            "total_recognized_to_date":round(sum(
                self._migration_ad_number(
                    row.get("cutover",{}).get("recognized_to_date")
                )
                for row in previews
            ),2),

            "total_remaining_balance":round(sum(
                self._migration_ad_number(
                    row.get("cutover",{}).get("remaining_balance")
                )
                for row in previews
            ),2),

            "by_type":{
                item_type:sum(
                    1 for row in previews
                    if str(
                        row.get("payload",{}).get("item_type") or ""
                    )==item_type
                )
                for item_type in [
                    "prepaid_expense",
                    "deferred_expense",
                    "deferred_income",
                    "accrued_income",
                    "accrued_expense",
                ]
            },
        }

    def migration_accrual_mapping_get(
        self,company_id:int,project_id:int,dataset_id:int,*,cur=None
    )->dict:
        settings=self.migration_accrual_settings_get(
            company_id,project_id,dataset_id,cur=cur
        )

        field_mapping=self.migration_field_mapping_dataset(
            company_id,project_id,dataset_id,cur=cur
        )

        references=self.migration_accrual_source_references(
            company_id,project_id,dataset_id,cur=cur
        )

        mode=settings.get("source_mode") or "original_terms"

        required={
            "original_terms":{
                "item_title",
                "start_date",
                "end_date",
                "original_amount",
            },

            "opening_position":{
                "item_title",
                "end_date",
                "original_amount",
                "remaining_balance",
            },

            "existing_schedule":{
                "item_title",
                "schedule_recognition_date",
                "schedule_opening_balance",
                "schedule_recognition_amount",
                "schedule_closing_balance",
            },
        }[mode]

        mapped={
            row.get("target_field_code")
            for row in field_mapping.get("rows") or []
            if row.get("mapping_status")=="mapped"
        }

        missing_fields=sorted(required-mapped)
        missing_references=[]

        if settings.get("require_counterparty_mapping"):
            for reference_type in [
                "customer","vendor","employee"
            ]:
                for row in references[reference_type]["rows"]:
                    if not row.get("target_id") or not row.get("is_approved"):
                        missing_references.append({
                            "reference_type":reference_type,
                            "source_value":row.get("source_value"),
                        })

        return {
            "settings":settings,
            "field_mapping":field_mapping,
            "references":references,
            "source_mode":mode,

            "missing_fields":missing_fields,
            "missing_references":missing_references,

            "is_complete":
                not missing_fields
                and not missing_references,
        }

    def migration_payroll_datasets(
        self,company_id:int,project_id:int,*,cur=None
    )->list[dict]:
        company_id,project_id=int(company_id),int(project_id)
        schema=self.company_schema(company_id)

        return self.fetch_all(f"""
            SELECT
                d.id AS dataset_id,
                d.dataset_name,
                d.record_count,
                d.column_count,
                d.dataset_status,
                f.original_name AS source_file_name
            FROM {schema}.migration_source_datasets d
            JOIN {schema}.migration_source_files f
            ON f.id=d.source_file_id
            WHERE d.company_id=%s
            AND d.project_id=%s
            AND d.entity_code='payroll_employees'
            AND d.is_selected=TRUE
            ORDER BY d.id
        """,(company_id,project_id),cur=cur) or []

    def migration_payroll_tax_options(self,company_id:int,*,cur=None)->dict:
        company_id=int(company_id)

        authorities=self.fetch_all("""
            SELECT id,code,name,country_code
            FROM public.tax_authorities
            ORDER BY country_code,name,id
        """,cur=cur) or []

        regimes=self.fetch_all("""
            SELECT
                r.id,
                r.authority_code,
                r.country_code,
                r.name,
                r.currency,
                r.is_active
            FROM public.payroll_tax_regimes r
            WHERE r.is_active=TRUE
            ORDER BY r.country_code,r.name,r.id
        """,cur=cur) or []

        years=self.fetch_all("""
            SELECT
                y.id,
                y.regime_id,
                y.tax_year_label,
                y.effective_from,
                y.effective_to,
                y.calculation_basis,
                r.authority_code,
                r.country_code,
                r.currency
            FROM public.payroll_tax_years y
            JOIN public.payroll_tax_regimes r
            ON r.id=y.regime_id
            WHERE y.is_active=TRUE
            AND r.is_active=TRUE
            ORDER BY y.effective_from DESC,y.id DESC
        """,cur=cur) or []

        return {
            "authorities":authorities,
            "regimes":regimes,
            "years":years,
        }

    def migration_payroll_settings_get(
        self,company_id:int,project_id:int,dataset_id:int,*,cur=None
    )->dict:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)

        project=self.fetch_one(f"""
            SELECT cutover_date,default_currency
            FROM {schema}.migration_projects
            WHERE company_id=%s AND id=%s
        """,(company_id,project_id),cur=cur)

        if not project:
            raise ValueError("Migration project not found.")

        existing=self.fetch_one(f"""
            SELECT *
            FROM {schema}.migration_payroll_settings
            WHERE company_id=%s
            AND project_id=%s
            AND dataset_id=%s
        """,(company_id,project_id,dataset_id),cur=cur)

        if existing:
            existing["settings_json"]=self._migration_json(
                existing.get("settings_json"),{}
            )
            existing["metadata_json"]=self._migration_json(
                existing.get("metadata_json"),{}
            )
            return existing

        payroll_settings=self.fetch_one(f"""
            SELECT *
            FROM {schema}.payroll_settings
            WHERE company_id=%s
            LIMIT 1
        """,(company_id,),cur=cur) or {}

        tax_options=self.migration_payroll_tax_options(
            company_id,
            cur=cur,
        )

        default_authority_id=payroll_settings.get("tax_authority_id")
        default_regime_id=None

        if default_authority_id:
            authority=next(
                (
                    item for item in tax_options["authorities"]
                    if int(item["id"])==int(default_authority_id)
                ),
                None,
            )

            if authority:
                default_regime=next(
                    (
                        item for item in tax_options["regimes"]
                        if str(item.get("authority_code") or "").upper()
                        ==str(authority.get("code") or "").upper()
                    ),
                    None,
                )

                if default_regime:
                    default_regime_id=default_regime["id"]

        return {
            "company_id":company_id,
            "project_id":project_id,
            "dataset_id":dataset_id,

            "migration_date":project.get("cutover_date"),

            "default_currency":
                payroll_settings.get("default_currency")
                or project.get("default_currency"),

            "default_pay_frequency":
                payroll_settings.get("default_frequency")
                or "monthly",

            "default_pay_basis":"monthly",
            "default_contract_type":"permanent",
            "default_salary_type":"monthly",

            "default_tax_authority_id":default_authority_id,
            "default_tax_regime_id":default_regime_id,

            "default_residency_status":"resident",
            "default_tax_calculation_method":"standard",
            "default_tax_treatment":"standard",

            "default_proration_method":"working_days",
            "default_hours_per_day":8,
            "default_attendance_required":False,

            "department_strategy":"map_existing",
            "position_strategy":"map_existing",
            "payroll_item_strategy":"map_existing",

            "require_department_mapping":False,
            "require_position_mapping":False,
            "require_bank_details":False,
            "require_tax_profile":True,

            "settings_json":{},
            "metadata_json":{},
        }
  
    def migration_payroll_settings_save(
        self,company_id:int,project_id:int,dataset_id:int,data:dict,
        *,user_id:int|None=None,cur=None
    )->dict:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)
        data=data or {}

        current=self.migration_payroll_settings_get(
            company_id,project_id,dataset_id,cur=cur
        )

        frequency=str(
            data.get("default_pay_frequency")
            or current.get("default_pay_frequency")
            or "monthly"
        ).strip().lower()

        pay_basis=str(
            data.get("default_pay_basis")
            or current.get("default_pay_basis")
            or "monthly"
        ).strip().lower()

        residency=str(
            data.get("default_residency_status")
            or current.get("default_residency_status")
            or "resident"
        ).strip().lower()

        tax_method=str(
            data.get("default_tax_calculation_method")
            or current.get("default_tax_calculation_method")
            or "standard"
        ).strip().lower()

        tax_treatment=str(
            data.get("default_tax_treatment")
            or current.get("default_tax_treatment")
            or "standard"
        ).strip().lower()

        proration=str(
            data.get("default_proration_method")
            or current.get("default_proration_method")
            or "working_days"
        ).strip().lower()

        if frequency not in {"weekly","fortnightly","monthly"}:
            raise ValueError("Invalid payroll frequency.")

        if pay_basis not in {
            "monthly","hourly","daily","quantity","commission_only"
        }:
            raise ValueError("Invalid pay basis.")

        if residency not in {"resident","non_resident"}:
            raise ValueError("Invalid residency status.")

        if tax_method not in {
            "standard","directive","manual","exempt"
        }:
            raise ValueError("Invalid tax calculation method.")

        if tax_treatment not in {
            "standard","manual","exempt"
        }:
            raise ValueError("Invalid tax treatment.")

        if proration not in {
            "working_days","calendar_days","fixed_30_days",
            "scheduled_hours","actual_hours","no_proration"
        }:
            raise ValueError("Invalid proration method.")

        self.execute_sql(f"""
            INSERT INTO {schema}.migration_payroll_settings(
                company_id,project_id,dataset_id,
                migration_date,
                default_currency,
                default_pay_frequency,
                default_pay_basis,
                default_contract_type,
                default_salary_type,

                default_tax_authority_id,
                default_tax_regime_id,
                default_residency_status,
                default_tax_calculation_method,
                default_tax_treatment,

                default_proration_method,
                default_hours_per_day,
                default_attendance_required,

                department_strategy,
                position_strategy,
                payroll_item_strategy,

                require_department_mapping,
                require_position_mapping,
                require_bank_details,
                require_tax_profile,

                settings_json,
                metadata_json,
                created_by_user_id,
                updated_by_user_id,
                created_at,
                updated_at
            )
            VALUES(
                %s,%s,%s,%s,%s,%s,%s,%s,%s,
                %s,%s,%s,%s,%s,
                %s,%s,%s,
                %s,%s,%s,
                %s,%s,%s,%s,
                %s::jsonb,%s::jsonb,
                %s,%s,NOW(),NOW()
            )
            ON CONFLICT(company_id,project_id,dataset_id)
            DO UPDATE SET
                migration_date=EXCLUDED.migration_date,
                default_currency=EXCLUDED.default_currency,
                default_pay_frequency=EXCLUDED.default_pay_frequency,
                default_pay_basis=EXCLUDED.default_pay_basis,
                default_contract_type=EXCLUDED.default_contract_type,
                default_salary_type=EXCLUDED.default_salary_type,

                default_tax_authority_id=EXCLUDED.default_tax_authority_id,
                default_tax_regime_id=EXCLUDED.default_tax_regime_id,
                default_residency_status=EXCLUDED.default_residency_status,
                default_tax_calculation_method=EXCLUDED.default_tax_calculation_method,
                default_tax_treatment=EXCLUDED.default_tax_treatment,

                default_proration_method=EXCLUDED.default_proration_method,
                default_hours_per_day=EXCLUDED.default_hours_per_day,
                default_attendance_required=EXCLUDED.default_attendance_required,

                department_strategy=EXCLUDED.department_strategy,
                position_strategy=EXCLUDED.position_strategy,
                payroll_item_strategy=EXCLUDED.payroll_item_strategy,

                require_department_mapping=EXCLUDED.require_department_mapping,
                require_position_mapping=EXCLUDED.require_position_mapping,
                require_bank_details=EXCLUDED.require_bank_details,
                require_tax_profile=EXCLUDED.require_tax_profile,

                settings_json=EXCLUDED.settings_json,
                metadata_json=EXCLUDED.metadata_json,
                updated_by_user_id=EXCLUDED.updated_by_user_id,
                updated_at=NOW()
        """,(
            company_id,project_id,dataset_id,

            data.get("migration_date")
                or current.get("migration_date"),

            data.get("default_currency")
                or current.get("default_currency"),

            frequency,
            pay_basis,

            data.get("default_contract_type")
                or current.get("default_contract_type")
                or "permanent",

            data.get("default_salary_type")
                or current.get("default_salary_type")
                or "monthly",

            data.get(
                "default_tax_authority_id",
                current.get("default_tax_authority_id"),
            ),

            data.get(
                "default_tax_regime_id",
                current.get("default_tax_regime_id"),
            ),

            residency,
            tax_method,
            tax_treatment,
            proration,

            float(
                data.get("default_hours_per_day")
                if data.get("default_hours_per_day") not in (None,"")
                else current.get("default_hours_per_day") or 8
            ),

            bool(data.get(
                "default_attendance_required",
                current.get("default_attendance_required",False),
            )),

            data.get("department_strategy")
                or current.get("department_strategy")
                or "map_existing",

            data.get("position_strategy")
                or current.get("position_strategy")
                or "map_existing",

            data.get("payroll_item_strategy")
                or current.get("payroll_item_strategy")
                or "map_existing",

            bool(data.get(
                "require_department_mapping",
                current.get("require_department_mapping",False),
            )),

            bool(data.get(
                "require_position_mapping",
                current.get("require_position_mapping",False),
            )),

            bool(data.get(
                "require_bank_details",
                current.get("require_bank_details",False),
            )),

            bool(data.get(
                "require_tax_profile",
                current.get("require_tax_profile",True),
            )),

            self._migration_json_dump(
                data.get("settings_json")
                or current.get("settings_json"),
                {},
            ),

            self._migration_json_dump(
                data.get("metadata_json")
                or current.get("metadata_json"),
                {},
            ),

            user_id,user_id,
        ),cur=cur)

        return self.migration_payroll_settings_get(
            company_id,project_id,dataset_id,cur=cur
        )

    def migration_payroll_reference_targets(
        self,company_id:int,reference_type:str,*,cur=None
    )->list[dict]:
        company_id=int(company_id)
        schema=self.company_schema(company_id)
        reference_type=str(reference_type or "").strip().lower()

        queries={
            "department":f"""
                SELECT id,NULL::TEXT AS code,name AS label
                FROM {schema}.payroll_departments
                WHERE company_id=%s AND is_active=TRUE
                ORDER BY name,id
            """,

            "position":f"""
                SELECT id,NULL::TEXT AS code,title AS label
                FROM {schema}.payroll_positions
                WHERE company_id=%s AND is_active=TRUE
                ORDER BY title,id
            """,

            "earning_type":f"""
                SELECT id,code,name AS label
                FROM {schema}.payroll_earning_types
                WHERE company_id=%s AND is_active=TRUE
                ORDER BY code,id
            """,

            "deduction_type":f"""
                SELECT id,code,name AS label
                FROM {schema}.payroll_deduction_types
                WHERE company_id=%s AND is_active=TRUE
                ORDER BY code,id
            """,

            "contribution_type":f"""
                SELECT id,code,name AS label
                FROM {schema}.payroll_employer_contribution_types
                WHERE company_id=%s AND is_active=TRUE
                ORDER BY code,id
            """,

            "benefit_type":f"""
                SELECT id,code,name AS label
                FROM {schema}.payroll_benefit_types
                WHERE company_id=%s AND is_active=TRUE
                ORDER BY code,id
            """,
        }

        if reference_type in queries:
            return self.fetch_all(
                queries[reference_type],
                (company_id,),
                cur=cur,
            ) or []

        if reference_type=="tax_authority":
            return self.fetch_all("""
                SELECT
                    id,
                    code,
                    name AS label
                FROM public.tax_authorities
                ORDER BY name,id
            """,cur=cur) or []

        if reference_type=="tax_regime":
            return self.fetch_all("""
                SELECT
                    id,
                    authority_code AS code,
                    CONCAT(name,' — ',country_code) AS label
                FROM public.payroll_tax_regimes
                WHERE is_active=TRUE
                ORDER BY country_code,name,id
            """,cur=cur) or []

        raise ValueError(
            f"Unsupported payroll reference type: {reference_type}"
        )

    def migration_payroll_source_references(
        self,company_id:int,project_id:int,dataset_id:int,*,cur=None
    )->dict:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)

        mapping=self.migration_field_mapping_dataset(
            company_id,project_id,dataset_id,cur=cur
        )

        dataset=self.fetch_one(f"""
            SELECT metadata_json
            FROM {schema}.migration_source_datasets
            WHERE company_id=%s
            AND project_id=%s
            AND id=%s
        """,(company_id,project_id,dataset_id),cur=cur)

        metadata=self._migration_json(
            dataset.get("metadata_json") if dataset else {},
            {},
        )

        sample_rows=metadata.get("sample_rows") or []

        target_to_source={
            row["target_field_code"]:row["source_name"]
            for row in mapping.get("rows") or []
            if row.get("mapping_status")=="mapped"
            and row.get("target_field_code")
        }

        field_types={
            "department":"department_reference",
            "position":"position_reference",
            "tax_authority":"tax_authority_reference",
            "tax_regime":"tax_regime_reference",
        }

        result={}

        for reference_type,target_field in field_types.items():
            source_name=target_to_source.get(target_field)
            values={}

            if source_name:
                for source_row in sample_rows:
                    value=str(source_row.get(source_name) or "").strip()
                    if value:
                        values[value]=values.get(value,0)+1

            saved=self.fetch_all(f"""
                SELECT *
                FROM {schema}.migration_payroll_reference_mappings
                WHERE company_id=%s
                AND project_id=%s
                AND dataset_id=%s
                AND reference_type=%s
            """,(
                company_id,
                project_id,
                dataset_id,
                reference_type,
            ),cur=cur) or []

            saved_map={
                row["source_value"]:row
                for row in saved
            }

            result[reference_type]={
                "rows":[{
                    "source_value":value,
                    "sample_count":count,
                    **(saved_map.get(value) or {}),
                } for value,count in sorted(values.items())],

                "targets":self.migration_payroll_reference_targets(
                    company_id,
                    reference_type,
                    cur=cur,
                ),
            }

        return result

    def migration_payroll_reference_save(
        self,company_id:int,project_id:int,dataset_id:int,mappings:list[dict],
        *,user_id:int|None=None,cur=None
    )->dict:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)

        if not isinstance(mappings,list):
            raise ValueError("mappings must be a list.")

        allowed={
            "department",
            "position",
            "tax_authority",
            "tax_regime",
            "earning_type",
            "deduction_type",
            "contribution_type",
            "benefit_type",
        }

        for item in mappings:
            reference_type=str(
                item.get("reference_type") or ""
            ).strip().lower()

            source_value=str(
                item.get("source_value") or ""
            ).strip()

            target_id=int(item.get("target_id") or 0)

            if reference_type not in allowed:
                raise ValueError(
                    f"Unsupported payroll reference type: {reference_type}"
                )

            if not source_value:
                raise ValueError("Source value is required.")

            if not target_id:
                raise ValueError(
                    f'Select a target for "{source_value}".'
                )

            targets=self.migration_payroll_reference_targets(
                company_id,
                reference_type,
                cur=cur,
            )

            target=next(
                (
                    row for row in targets
                    if int(row["id"])==target_id
                ),
                None,
            )

            if not target:
                raise ValueError(
                    f'Invalid target for "{source_value}".'
                )

            self.execute_sql(f"""
                INSERT INTO {schema}.migration_payroll_reference_mappings(
                    company_id,project_id,dataset_id,
                    reference_type,
                    source_value,
                    source_label,
                    target_id,
                    target_code,
                    target_label,
                    mapping_method,
                    confidence,
                    is_approved,
                    create_target,
                    metadata_json,
                    created_by_user_id,
                    updated_by_user_id,
                    created_at,
                    updated_at
                )
                VALUES(
                    %s,%s,%s,%s,%s,%s,
                    %s,%s,%s,
                    'manual',100,TRUE,FALSE,
                    '{{}}'::jsonb,
                    %s,%s,NOW(),NOW()
                )
                ON CONFLICT(
                    company_id,
                    project_id,
                    dataset_id,
                    reference_type,
                    source_value
                )
                DO UPDATE SET
                    target_id=EXCLUDED.target_id,
                    target_code=EXCLUDED.target_code,
                    target_label=EXCLUDED.target_label,
                    mapping_method='manual',
                    confidence=100,
                    is_approved=TRUE,
                    create_target=FALSE,
                    updated_by_user_id=EXCLUDED.updated_by_user_id,
                    updated_at=NOW()
            """,(
                company_id,
                project_id,
                dataset_id,
                reference_type,
                source_value,
                item.get("source_label") or source_value,

                target_id,
                target.get("code"),
                target.get("label"),

                user_id,
                user_id,
            ),cur=cur)

        return self.migration_payroll_source_references(
            company_id,project_id,dataset_id,cur=cur
        )

    def migration_payroll_reference_resolve(
        self,company_id:int,project_id:int,dataset_id:int,
        reference_type:str,source_value,*,cur=None
    ):
        value=str(source_value or "").strip()
        if not value:return None

        schema=self.company_schema(int(company_id))

        row=self.fetch_one(f"""
            SELECT target_id
            FROM {schema}.migration_payroll_reference_mappings
            WHERE company_id=%s
            AND project_id=%s
            AND dataset_id=%s
            AND reference_type=%s
            AND source_value=%s
            AND is_approved=TRUE
        """,(
            int(company_id),
            int(project_id),
            int(dataset_id),
            reference_type,
            value,
        ),cur=cur)

        return (
            int(row["target_id"])
            if row and row.get("target_id")
            else None
        )

    def migration_payroll_normalized_rows(
        self,company_id:int,project_id:int,dataset_id:int,
        *,limit:int=500,cur=None
    )->list[dict]:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)

        mapping=self.migration_field_mapping_dataset(
            company_id,project_id,dataset_id,cur=cur
        )

        dataset=self.fetch_one(f"""
            SELECT metadata_json
            FROM {schema}.migration_source_datasets
            WHERE company_id=%s
            AND project_id=%s
            AND id=%s
        """,(company_id,project_id,dataset_id),cur=cur)

        metadata=self._migration_json(
            dataset.get("metadata_json") if dataset else {},
            {},
        )

        source_rows=metadata.get("sample_rows") or []

        source_to_target={
            row["source_name"]:row["target_field_code"]
            for row in mapping.get("rows") or []
            if row.get("mapping_status")=="mapped"
            and row.get("target_field_code")
        }

        result=[]

        for source_row in source_rows[:limit]:
            normalized={}

            for source_name,target_field in source_to_target.items():
                normalized[target_field]=source_row.get(source_name)

            result.append({
                "source":source_row,
                "normalized":normalized,
            })

        return result

    def _migration_payroll_number(self,value,default=0.0)->float:
        if value in (None,""):return float(default or 0)

        try:
            return float(
                str(value)
                .replace(",","")
                .replace(" ","")
                .strip()
            )
        except Exception:
            return float(default or 0)


    def _migration_payroll_bool(self,value,default=False)->bool:
        if isinstance(value,bool):return value
        if value in (None,""):return bool(default)

        return str(value).strip().lower() in {
            "1","true","yes","y","on"
        }


    def _migration_payroll_date(self,value,required=False):
        if isinstance(value,date):return value

        text=str(value or "").strip()

        if not text:
            if required:raise ValueError("Date is required.")
            return None

        try:
            return datetime.strptime(
                text[:10],
                "%Y-%m-%d",
            ).date()
        except Exception:
            if required:
                raise ValueError(
                    f"Invalid date: {text}"
                )
            return None

    def migration_payroll_employee_preview(
        self,company_id:int,project_id:int,dataset_id:int,
        row:dict,settings:dict,*,cur=None
    )->dict:
        company_id=int(company_id)
        schema=self.company_schema(company_id)

        first_name=str(
            row.get("first_name") or ""
        ).strip()

        last_name=str(
            row.get("last_name") or ""
        ).strip()

        employee_no=str(
            row.get("employee_no") or ""
        ).strip() or None

        start_date=self._migration_payroll_date(
            row.get("start_date"),
            required=True,
        )

        termination_date=self._migration_payroll_date(
            row.get("termination_date")
        )

        issues=[]
        warnings=[]

        if not first_name:
            issues.append("First name is required.")

        if not last_name:
            issues.append("Last name is required.")

        if termination_date and termination_date<start_date:
            issues.append(
                "Termination date cannot be before start date."
            )

        if not employee_no:
            warnings.append(
                "Employee number is missing; FinSage can generate one during commit."
            )

        existing=None

        if employee_no:
            existing=self.fetch_one(f"""
                SELECT id,employee_no,first_name,last_name
                FROM {schema}.payroll_employees
                WHERE company_id=%s
                AND LOWER(employee_no)=LOWER(%s)
                LIMIT 1
            """,(company_id,employee_no),cur=cur)

            if existing:
                issues.append(
                    f"Employee number {employee_no} already exists in FinSage."
                )

        department_id=self.migration_payroll_reference_resolve(
            company_id,
            project_id,
            dataset_id,
            "department",
            row.get("department_reference"),
            cur=cur,
        )

        position_id=self.migration_payroll_reference_resolve(
            company_id,
            project_id,
            dataset_id,
            "position",
            row.get("position_reference"),
            cur=cur,
        )

        if (
            settings.get("require_department_mapping")
            and row.get("department_reference")
            and not department_id
        ):
            issues.append("Department is not mapped.")

        if (
            settings.get("require_position_mapping")
            and row.get("position_reference")
            and not position_id
        ):
            issues.append("Position is not mapped.")

        # --------------------------------
        # Contract
        # --------------------------------
        contract_type=str(
            row.get("contract_type")
            or settings.get("default_contract_type")
            or "permanent"
        ).strip().lower()

        salary_type=str(
            row.get("salary_type")
            or settings.get("default_salary_type")
            or "monthly"
        ).strip().lower()

        basic_salary=self._migration_payroll_number(
            row.get("basic_salary")
        )

        hourly_rate=self._migration_payroll_number(
            row.get("hourly_rate")
        )

        contract_effective_from=self._migration_payroll_date(
            row.get("contract_effective_from")
        ) or start_date

        contract_effective_to=self._migration_payroll_date(
            row.get("contract_effective_to")
        )

        if contract_effective_to and contract_effective_to<contract_effective_from:
            issues.append(
                "Contract effective-to cannot be before effective-from."
            )

        if salary_type=="monthly" and basic_salary<=0:
            issues.append(
                "Monthly employee requires a basic salary."
            )

        if salary_type=="hourly" and hourly_rate<=0:
            issues.append(
                "Hourly employee requires an hourly rate."
            )

        # --------------------------------
        # Pay setup
        # --------------------------------
        pay_basis=str(
            row.get("pay_basis")
            or settings.get("default_pay_basis")
            or salary_type
            or "monthly"
        ).strip().lower()

        fixed_basic_amount=self._migration_payroll_number(
            row.get("fixed_basic_amount"),
            basic_salary,
        )

        rate=self._migration_payroll_number(
            row.get("rate"),
            hourly_rate,
        )

        pay_setup_effective_from=self._migration_payroll_date(
            row.get("pay_setup_effective_from")
        ) or contract_effective_from

        tax_treatment=str(
            row.get("tax_treatment")
            or settings.get("default_tax_treatment")
            or "standard"
        ).strip().lower()

        proration_method=str(
            row.get("proration_method")
            or settings.get("default_proration_method")
            or "working_days"
        ).strip().lower()

        if pay_basis not in {
            "monthly","hourly","daily",
            "quantity","commission_only"
        }:
            issues.append(
                f"Unsupported pay basis: {pay_basis}."
            )

        if tax_treatment not in {
            "standard","manual","exempt"
        }:
            issues.append(
                f"Unsupported tax treatment: {tax_treatment}."
            )

        # --------------------------------
        # Tax
        # --------------------------------
        source_authority=row.get(
            "tax_authority_reference"
        )

        source_regime=row.get(
            "tax_regime_reference"
        )

        tax_authority_id=(
            self.migration_payroll_reference_resolve(
                company_id,
                project_id,
                dataset_id,
                "tax_authority",
                source_authority,
                cur=cur,
            )
            if source_authority
            else settings.get("default_tax_authority_id")
        )

        tax_regime_id=(
            self.migration_payroll_reference_resolve(
                company_id,
                project_id,
                dataset_id,
                "tax_regime",
                source_regime,
                cur=cur,
            )
            if source_regime
            else settings.get("default_tax_regime_id")
        )

        residency_status=str(
            row.get("residency_status")
            or settings.get("default_residency_status")
            or "resident"
        ).strip().lower()

        tax_calculation_method=str(
            row.get("tax_calculation_method")
            or settings.get("default_tax_calculation_method")
            or "standard"
        ).strip().lower()

        paye_exempt=self._migration_payroll_bool(
            row.get("paye_exempt"),
            tax_calculation_method=="exempt",
        )

        if (
            settings.get("require_tax_profile")
            and not tax_authority_id
        ):
            issues.append(
                "Tax authority is not resolved."
            )

        if residency_status not in {
            "resident","non_resident"
        }:
            issues.append(
                "Invalid residency status."
            )

        # --------------------------------
        # Bank
        # --------------------------------
        bank_account_number=str(
            row.get("bank_account_number") or ""
        ).strip()

        if (
            settings.get("require_bank_details")
            and not bank_account_number
        ):
            issues.append(
                "Bank account number is required."
            )

        employee_payload={
            "employee_no":employee_no,
            "first_name":first_name,
            "last_name":last_name,
            "email":
                str(row.get("email") or "").strip()
                or None,
            "phone":
                str(row.get("phone") or "").strip()
                or None,
            "id_number":
                str(row.get("id_number") or "").strip()
                or None,
            "passport_number":
                str(row.get("passport_number") or "").strip()
                or None,
            "tax_number":
                str(row.get("tax_number") or "").strip()
                or None,

            "department_id":department_id,
            "position_id":position_id,

            "start_date":start_date,
            "termination_date":termination_date,

            "employment_status":str(
                row.get("employment_status")
                or (
                    "terminated"
                    if termination_date
                    else "active"
                )
            ).strip().lower(),
        }

        contract_payload={
            "contract_type":contract_type,
            "salary_type":salary_type,
            "basic_salary":round(basic_salary,2),
            "hourly_rate":round(hourly_rate,2),

            "normal_hours_per_month":
                self._migration_payroll_number(
                    row.get("normal_hours_per_month")
                ) or None,

            "effective_from":contract_effective_from,
            "effective_to":contract_effective_to,
        }

        tax_payload={
            "tax_authority_id":
                int(tax_authority_id)
                if tax_authority_id else None,

            "tax_regime_id":
                int(tax_regime_id)
                if tax_regime_id else None,

            "tax_number":
                str(row.get("tax_number") or "").strip()
                or None,

            "residency_status":residency_status,
            "date_of_birth":
                self._migration_payroll_date(
                    row.get("date_of_birth")
                ),

            "paye_exempt":paye_exempt,

            "tax_calculation_method":
                tax_calculation_method,

            "directive_number":
                str(row.get("directive_number") or "").strip()
                or None,

            "directive_rate":
                self._migration_payroll_number(
                    row.get("directive_rate")
                ) or None,

            "additional_tax_amount":
                self._migration_payroll_number(
                    row.get("additional_tax_amount")
                ),

            "medical_scheme_members":
                int(
                    self._migration_payroll_number(
                        row.get("medical_scheme_members")
                    )
                ),

            "effective_from":pay_setup_effective_from,
            "effective_to":None,
        }

        bank_payload=None

        if (
            row.get("bank_name")
            or bank_account_number
        ):
            bank_payload={
                "bank_name":
                    str(row.get("bank_name") or "").strip(),

                "account_name":
                    str(
                        row.get("bank_account_name")
                        or f"{first_name} {last_name}"
                    ).strip(),

                "account_number":
                    bank_account_number,

                "branch_code":
                    str(row.get("bank_branch_code") or "").strip()
                    or None,

                "account_type":
                    str(row.get("bank_account_type") or "").strip().lower()
                    or None,

                "is_primary":True,
            }

        setup_payload={
            "pay_basis":pay_basis,

            "fixed_basic_amount":
                round(fixed_basic_amount,2),

            "standard_quantity":
                self._migration_payroll_number(
                    row.get("standard_quantity")
                ) or None,

            "rate":round(rate,4),

            "tax_treatment":tax_treatment,

            "manual_paye_amount":
                self._migration_payroll_number(
                    row.get("manual_paye_amount")
                ) or None,

            "proration_method":proration_method,

            "hours_per_day":
                self._migration_payroll_number(
                    row.get("hours_per_day"),
                    settings.get("default_hours_per_day") or 8,
                ),

            "attendance_required":
                self._migration_payroll_bool(
                    row.get("attendance_required"),
                    settings.get(
                        "default_attendance_required",
                        False,
                    ),
                ),

            "effective_from":pay_setup_effective_from,
            "effective_to":None,
        }

        return {
            "valid":not issues,
            "issues":issues,
            "warnings":warnings,
            "employee":employee_payload,
            "contract":contract_payload,
            "tax_profile":tax_payload,
            "bank_account":bank_payload,
            "pay_setup":setup_payload,
        }

    def migration_payroll_preview(
        self,company_id:int,project_id:int,dataset_id:int,*,cur=None
    )->dict:
        settings=self.migration_payroll_settings_get(
            company_id,project_id,dataset_id,cur=cur
        )

        rows=self.migration_payroll_normalized_rows(
            company_id,
            project_id,
            dataset_id,
            limit=500,
            cur=cur,
        )

        items=[]

        for index,item in enumerate(rows,start=1):
            try:
                preview=self.migration_payroll_employee_preview(
                    company_id,
                    project_id,
                    dataset_id,
                    item["normalized"],
                    settings,
                    cur=cur,
                )
            except Exception as error:
                preview={
                    "valid":False,
                    "issues":[str(error)],
                    "warnings":[],
                    "employee":item["normalized"],
                    "contract":{},
                    "tax_profile":{},
                    "bank_account":None,
                    "pay_setup":{},
                }

            items.append({
                "row_number":index,
                "source":item["source"],
                **preview,
            })

        active_count=sum(
            1 for item in items
            if item.get("employee",{}).get("employment_status")=="active"
        )

        bank_count=sum(
            1 for item in items
            if item.get("bank_account")
        )

        tax_count=sum(
            1 for item in items
            if item.get("tax_profile",{}).get("tax_authority_id")
        )

        total_basic=round(sum(
            self._migration_payroll_number(
                item.get("contract",{}).get("basic_salary")
            )
            for item in items
        ),2)

        return {
            "dataset_id":int(dataset_id),
            "employees":items,

            "employee_count":len(items),
            "valid_count":sum(
                1 for item in items
                if item.get("valid")
            ),
            "error_count":sum(
                1 for item in items
                if not item.get("valid")
            ),

            "active_count":active_count,
            "bank_account_count":bank_count,
            "tax_profile_count":tax_count,
            "total_monthly_basic_salary":total_basic,
        }

    def migration_payroll_mapping_get(
        self,company_id:int,project_id:int,dataset_id:int,*,cur=None
    )->dict:
        settings=self.migration_payroll_settings_get(
            company_id,project_id,dataset_id,cur=cur
        )

        field_mapping=self.migration_field_mapping_dataset(
            company_id,project_id,dataset_id,cur=cur
        )

        references=self.migration_payroll_source_references(
            company_id,project_id,dataset_id,cur=cur
        )

        required={
            "first_name",
            "last_name",
            "start_date",
        }

        mapped={
            row.get("target_field_code")
            for row in field_mapping.get("rows") or []
            if row.get("mapping_status")=="mapped"
        }

        missing_fields=sorted(
            required-mapped
        )

        missing_references=[]

        checks={
            "department":
                settings.get("require_department_mapping"),

            "position":
                settings.get("require_position_mapping"),

            "tax_authority":
                settings.get("require_tax_profile"),
        }

        for reference_type,required_mapping in checks.items():
            if not required_mapping:
                continue

            group=references.get(reference_type) or {}

            for row in group.get("rows") or []:
                if (
                    not row.get("target_id")
                    or not row.get("is_approved")
                ):
                    missing_references.append({
                        "reference_type":reference_type,
                        "source_value":row.get("source_value"),
                    })

        if (
            settings.get("require_tax_profile")
            and not settings.get("default_tax_authority_id")
            and not references.get(
                "tax_authority",{}
            ).get("rows")
        ):
            missing_references.append({
                "reference_type":"tax_authority",
                "source_value":
                    "Default payroll tax authority",
            })

        return {
            "settings":settings,
            "field_mapping":field_mapping,
            "references":references,
            "tax_options":
                self.migration_payroll_tax_options(
                    company_id,
                    cur=cur,
                ),

            "missing_fields":missing_fields,
            "missing_references":missing_references,

            "is_complete":
                not missing_fields
                and not missing_references,
        }

    def migration_payroll_item_datasets(
        self,company_id:int,project_id:int,*,cur=None
    )->list[dict]:
        company_id,project_id=int(company_id),int(project_id)
        schema=self.company_schema(company_id)

        return self.fetch_all(f"""
            SELECT
                d.id AS dataset_id,
                d.dataset_name,
                d.entity_code,
                d.record_count,
                d.column_count,
                d.dataset_status,
                f.original_name AS source_file_name
            FROM {schema}.migration_source_datasets d
            JOIN {schema}.migration_source_files f
            ON f.id=d.source_file_id
            WHERE d.company_id=%s
            AND d.project_id=%s
            AND d.is_selected=TRUE
            AND d.entity_code IN(
                'payroll_items',
                'payroll_employees'
            )
            ORDER BY d.id
        """,(company_id,project_id),cur=cur) or []

    def migration_payroll_item_settings_get(
        self,company_id:int,project_id:int,dataset_id:int,*,cur=None
    )->dict:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)

        project=self.fetch_one(f"""
            SELECT cutover_date
            FROM {schema}.migration_projects
            WHERE company_id=%s
            AND id=%s
        """,(company_id,project_id),cur=cur)

        if not project:
            raise ValueError("Migration project not found.")

        row=self.fetch_one(f"""
            SELECT *
            FROM {schema}.migration_payroll_item_settings
            WHERE company_id=%s
            AND project_id=%s
            AND dataset_id=%s
        """,(company_id,project_id,dataset_id),cur=cur)

        if row:
            row["settings_json"]=self._migration_json(
                row.get("settings_json"),{}
            )
            row["metadata_json"]=self._migration_json(
                row.get("metadata_json"),{}
            )
            return row

        return {
            "company_id":company_id,
            "project_id":project_id,
            "dataset_id":dataset_id,

            "source_layout":"item_rows",
            "default_effective_from":
                project.get("cutover_date"),

            "earning_strategy":"map_existing",
            "deduction_strategy":"map_existing",
            "benefit_strategy":"map_existing",
            "contribution_strategy":"map_existing",

            "allow_create_missing":False,
            "require_all_items_mapped":True,

            "settings_json":{},
            "metadata_json":{},
        }

    def migration_payroll_item_settings_save(
        self,company_id:int,project_id:int,dataset_id:int,data:dict,
        *,user_id:int|None=None,cur=None
    )->dict:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)
        data=data or {}

        current=self.migration_payroll_item_settings_get(
            company_id,project_id,dataset_id,cur=cur
        )

        source_layout=str(
            data.get("source_layout")
            or current.get("source_layout")
            or "item_rows"
        ).strip().lower()

        if source_layout not in {
            "employee_rows",
            "item_rows",
        }:
            raise ValueError("Invalid payroll item source layout.")

        strategies={}

        for key in (
            "earning_strategy",
            "deduction_strategy",
            "benefit_strategy",
            "contribution_strategy",
        ):
            value=str(
                data.get(key)
                or current.get(key)
                or "map_existing"
            ).strip().lower()

            if value not in {
                "map_existing",
                "create_missing",
            }:
                raise ValueError(
                    f"Invalid {key.replace('_',' ')}."
                )

            strategies[key]=value

        self.execute_sql(f"""
            INSERT INTO {schema}.migration_payroll_item_settings(
                company_id,
                project_id,
                dataset_id,
                source_layout,
                default_effective_from,

                earning_strategy,
                deduction_strategy,
                benefit_strategy,
                contribution_strategy,

                allow_create_missing,
                require_all_items_mapped,

                settings_json,
                metadata_json,

                created_by_user_id,
                updated_by_user_id,
                created_at,
                updated_at
            )
            VALUES(
                %s,%s,%s,%s,%s,
                %s,%s,%s,%s,
                %s,%s,
                %s::jsonb,%s::jsonb,
                %s,%s,NOW(),NOW()
            )
            ON CONFLICT(company_id,project_id,dataset_id)
            DO UPDATE SET
                source_layout=EXCLUDED.source_layout,
                default_effective_from=EXCLUDED.default_effective_from,

                earning_strategy=EXCLUDED.earning_strategy,
                deduction_strategy=EXCLUDED.deduction_strategy,
                benefit_strategy=EXCLUDED.benefit_strategy,
                contribution_strategy=EXCLUDED.contribution_strategy,

                allow_create_missing=EXCLUDED.allow_create_missing,
                require_all_items_mapped=EXCLUDED.require_all_items_mapped,

                settings_json=EXCLUDED.settings_json,
                metadata_json=EXCLUDED.metadata_json,

                updated_by_user_id=EXCLUDED.updated_by_user_id,
                updated_at=NOW()
        """,(
            company_id,
            project_id,
            dataset_id,
            source_layout,

            data.get("default_effective_from")
                or current.get("default_effective_from"),

            strategies["earning_strategy"],
            strategies["deduction_strategy"],
            strategies["benefit_strategy"],
            strategies["contribution_strategy"],

            bool(data.get(
                "allow_create_missing",
                current.get("allow_create_missing",False),
            )),

            bool(data.get(
                "require_all_items_mapped",
                current.get("require_all_items_mapped",True),
            )),

            self._migration_json_dump(
                data.get("settings_json")
                or current.get("settings_json"),
                {},
            ),

            self._migration_json_dump(
                data.get("metadata_json")
                or current.get("metadata_json"),
                {},
            ),

            user_id,
            user_id,
        ),cur=cur)

        return self.migration_payroll_item_settings_get(
            company_id,
            project_id,
            dataset_id,
            cur=cur,
        )

    def migration_payroll_item_targets(
        self,company_id:int,item_type:str,*,cur=None
    )->list[dict]:
        company_id=int(company_id)
        schema=self.company_schema(company_id)
        item_type=str(item_type or "").strip().lower()

        if item_type=="earning":
            return self.fetch_all(f"""
                SELECT
                    id,
                    code,
                    name,
                    taxable,
                    pensionable
                FROM {schema}.payroll_earning_types
                WHERE company_id=%s
                AND is_active=TRUE
                ORDER BY code,name,id
            """,(company_id,),cur=cur) or []

        if item_type=="deduction":
            return self.fetch_all(f"""
                SELECT
                    id,
                    code,
                    name,
                    is_statutory
                FROM {schema}.payroll_deduction_types
                WHERE company_id=%s
                AND is_active=TRUE
                ORDER BY code,name,id
            """,(company_id,),cur=cur) or []

        if item_type=="benefit":
            return self.fetch_all(f"""
                SELECT
                    id,
                    code,
                    name,
                    benefit_category,
                    taxable
                FROM {schema}.payroll_benefit_types
                WHERE company_id=%s
                AND is_active=TRUE
                ORDER BY code,name,id
            """,(company_id,),cur=cur) or []

        if item_type=="contribution":
            return self.fetch_all(f"""
                SELECT
                    id,
                    code,
                    name
                FROM {schema}.payroll_employer_contribution_types
                WHERE company_id=%s
                AND is_active=TRUE
                ORDER BY code,name,id
            """,(company_id,),cur=cur) or []

        raise ValueError(
            f"Unsupported payroll item type: {item_type}"
        )

    def _migration_payroll_item_type(self,value)->str|None:
        value=str(value or "").strip().lower()

        aliases={
            "earning":"earning",
            "earnings":"earning",
            "income":"earning",
            "allowance":"earning",
            "salary":"earning",

            "deduction":"deduction",
            "deductions":"deduction",
            "employee deduction":"deduction",

            "benefit":"benefit",
            "benefits":"benefit",
            "fringe benefit":"benefit",

            "contribution":"contribution",
            "employer contribution":"contribution",
            "employer_contribution":"contribution",
        }

        return aliases.get(value)

    def migration_payroll_item_auto_match(
        self,company_id:int,item_type:str,source_code,source_name,*,cur=None
    ):
        targets=self.migration_payroll_item_targets(
            company_id,
            item_type,
            cur=cur,
        )

        source_code=str(source_code or "").strip().upper()
        source_name=str(source_name or "").strip().lower()

        if source_code:
            match=next(
                (
                    row for row in targets
                    if str(row.get("code") or "").strip().upper()
                    ==source_code
                ),
                None,
            )

            if match:
                return {
                    "target":match,
                    "confidence":100,
                    "method":"auto",
                }

        if source_name:
            match=next(
                (
                    row for row in targets
                    if str(row.get("name") or "").strip().lower()
                    ==source_name
                ),
                None,
            )

            if match:
                return {
                    "target":match,
                    "confidence":98,
                    "method":"auto",
                }

        return None

    def migration_payroll_items_detect(
        self,company_id:int,project_id:int,dataset_id:int,*,cur=None
    )->dict:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)

        normalized_rows=self.migration_payroll_normalized_rows(
            company_id,
            project_id,
            dataset_id,
            limit=500,
            cur=cur,
        )

        detected={}

        for item in normalized_rows:
            row=item.get("normalized") or {}

            item_name=str(
                row.get("payroll_item_name")
                or row.get("payroll_item_reference")
                or ""
            ).strip()

            item_code=str(
                row.get("payroll_item_code")
                or ""
            ).strip()

            item_type=self._migration_payroll_item_type(
                row.get("payroll_item_type")
            )

            if not item_name and not item_code:
                continue

            key=(
                item_type or "unknown",
                item_code.lower(),
                item_name.lower(),
            )

            if key not in detected:
                detected[key]={
                    "item_type":item_type,
                    "source_code":item_code or None,
                    "source_name":
                        item_name
                        or item_code,
                    "sample_count":0,
                    "sample_rows":[],
                }

            detected[key]["sample_count"]+=1

            if len(detected[key]["sample_rows"])<3:
                detected[key]["sample_rows"].append(row)

        saved=self.fetch_all(f"""
            SELECT *
            FROM {schema}.migration_payroll_item_mappings
            WHERE company_id=%s
            AND project_id=%s
            AND dataset_id=%s
            ORDER BY item_type,source_name
        """,(
            company_id,
            project_id,
            dataset_id,
        ),cur=cur) or []

        saved_map={
            (
                row.get("item_type"),
                str(row.get("source_code") or "").lower(),
                str(row.get("source_name") or "").lower(),
            ):row
            for row in saved
        }

        result=[]

        for key,item in detected.items():
            existing=saved_map.get(key)

            if existing:
                result.append({
                    **item,
                    **existing,
                })
                continue

            auto=None

            if item.get("item_type"):
                auto=self.migration_payroll_item_auto_match(
                    company_id,
                    item["item_type"],
                    item.get("source_code"),
                    item.get("source_name"),
                    cur=cur,
                )

            if auto:
                target=auto["target"]

                result.append({
                    **item,
                    "target_id":target["id"],
                    "target_code":target.get("code"),
                    "target_name":target.get("name"),
                    "mapping_method":"auto",
                    "confidence":auto["confidence"],
                    "is_approved":False,
                })
            else:
                result.append({
                    **item,
                    "target_id":None,
                    "target_code":None,
                    "target_name":None,
                    "mapping_method":"manual",
                    "confidence":0,
                    "is_approved":False,
                })

        return {
            "dataset_id":dataset_id,
            "items":result,

            "detected_count":len(result),

            "mapped_count":sum(
                1 for item in result
                if item.get("target_id")
            ),

            "approved_count":sum(
                1 for item in result
                if item.get("target_id")
                and item.get("is_approved")
            ),
        }

    def migration_payroll_item_mapping_save(
        self,company_id:int,project_id:int,dataset_id:int,mappings:list[dict],
        *,user_id:int|None=None,cur=None
    )->dict:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)

        if not isinstance(mappings,list):
            raise ValueError("mappings must be a list.")

        for item in mappings:
            item_type=self._migration_payroll_item_type(
                item.get("item_type")
            )

            if not item_type:
                raise ValueError(
                    f"Select an item type for {item.get('source_name') or 'payroll item'}."
                )

            source_name=str(
                item.get("source_name") or ""
            ).strip()

            source_code=str(
                item.get("source_code") or ""
            ).strip() or None

            target_id=int(
                item.get("target_id") or 0
            )

            if not source_name:
                raise ValueError(
                    "Payroll source item name is required."
                )

            if not target_id:
                raise ValueError(
                    f'Select a FinSage payroll item for "{source_name}".'
                )

            targets=self.migration_payroll_item_targets(
                company_id,
                item_type,
                cur=cur,
            )

            target=next(
                (
                    row for row in targets
                    if int(row["id"])==target_id
                ),
                None,
            )

            if not target:
                raise ValueError(
                    f'Invalid target for "{source_name}".'
                )

            calculation_method=str(
                item.get("default_calculation_method")
                or "fixed_amount"
            ).strip().lower()

            if calculation_method not in {
                "fixed_amount",
                "percentage",
                "quantity_rate",
                "manual",
            }:
                raise ValueError(
                    f'Invalid calculation method for "{source_name}".'
                )

            self.execute_sql(f"""
                INSERT INTO {schema}.migration_payroll_item_mappings(
                    company_id,
                    project_id,
                    dataset_id,

                    item_type,
                    source_code,
                    source_name,

                    target_id,
                    target_code,
                    target_name,

                    default_calculation_method,
                    default_amount,
                    default_percentage,
                    default_quantity,
                    default_rate,

                    taxable,
                    pensionable,

                    mapping_method,
                    confidence,
                    is_approved,

                    metadata_json,

                    created_by_user_id,
                    updated_by_user_id,
                    created_at,
                    updated_at
                )
                VALUES(
                    %s,%s,%s,
                    %s,%s,%s,
                    %s,%s,%s,
                    %s,%s,%s,%s,%s,
                    %s,%s,
                    'manual',100,TRUE,
                    '{{}}'::jsonb,
                    %s,%s,NOW(),NOW()
                )
                ON CONFLICT(
                    company_id,
                    project_id,
                    dataset_id,
                    item_type,
                    LOWER(source_name)
                )
                DO UPDATE SET
                    source_code=EXCLUDED.source_code,

                    target_id=EXCLUDED.target_id,
                    target_code=EXCLUDED.target_code,
                    target_name=EXCLUDED.target_name,

                    default_calculation_method=
                        EXCLUDED.default_calculation_method,

                    default_amount=EXCLUDED.default_amount,
                    default_percentage=EXCLUDED.default_percentage,
                    default_quantity=EXCLUDED.default_quantity,
                    default_rate=EXCLUDED.default_rate,

                    taxable=EXCLUDED.taxable,
                    pensionable=EXCLUDED.pensionable,

                    mapping_method='manual',
                    confidence=100,
                    is_approved=TRUE,

                    updated_by_user_id=
                        EXCLUDED.updated_by_user_id,

                    updated_at=NOW()
            """,(
                company_id,
                project_id,
                dataset_id,

                item_type,
                source_code,
                source_name,

                target["id"],
                target.get("code"),
                target.get("name"),

                calculation_method,

                self._migration_payroll_number(
                    item.get("default_amount")
                ) if item.get("default_amount") not in (None,"") else None,

                self._migration_payroll_number(
                    item.get("default_percentage")
                ) if item.get("default_percentage") not in (None,"") else None,

                self._migration_payroll_number(
                    item.get("default_quantity")
                ) if item.get("default_quantity") not in (None,"") else None,

                self._migration_payroll_number(
                    item.get("default_rate")
                ) if item.get("default_rate") not in (None,"") else None,

                item.get("taxable"),
                item.get("pensionable"),

                user_id,
                user_id,
            ),cur=cur)

        return self.migration_payroll_items_detect(
            company_id,
            project_id,
            dataset_id,
            cur=cur,
        )

    def migration_payroll_item_resolve(
        self,company_id:int,project_id:int,dataset_id:int|None,
        item_type:str,source_code,source_name,*,cur=None
    ):
        company_id,project_id=int(company_id),int(project_id)
        schema=self.company_schema(company_id)

        item_type=self._migration_payroll_item_type(
            item_type
        )

        if not item_type:return None

        source_code=str(source_code or "").strip()
        source_name=str(source_name or "").strip()

        dataset_sql=""
        params=[
            company_id,
            project_id,
            item_type,
        ]

        if dataset_id:
            dataset_sql="AND dataset_id=%s"
            params.append(int(dataset_id))

        if source_code:
            row=self.fetch_one(f"""
                SELECT *
                FROM {schema}.migration_payroll_item_mappings
                WHERE company_id=%s
                AND project_id=%s
                AND item_type=%s
                {dataset_sql}
                AND LOWER(COALESCE(source_code,''))=LOWER(%s)
                AND is_approved=TRUE
                ORDER BY id DESC
                LIMIT 1
            """,tuple(params+[source_code]),cur=cur)

            if row:return row

        if source_name:
            return self.fetch_one(f"""
                SELECT *
                FROM {schema}.migration_payroll_item_mappings
                WHERE company_id=%s
                AND project_id=%s
                AND item_type=%s
                {dataset_sql}
                AND LOWER(source_name)=LOWER(%s)
                AND is_approved=TRUE
                ORDER BY id DESC
                LIMIT 1
            """,tuple(params+[source_name]),cur=cur)

        return None

    def migration_payroll_item_preview_row(
        self,company_id:int,project_id:int,dataset_id:int,
        row:dict,settings:dict,*,cur=None
    )->dict:
        item_type=self._migration_payroll_item_type(
            row.get("payroll_item_type")
        )

        source_code=str(
            row.get("payroll_item_code") or ""
        ).strip()

        source_name=str(
            row.get("payroll_item_name")
            or row.get("payroll_item_reference")
            or ""
        ).strip()

        employee_no=str(
            row.get("employee_no") or ""
        ).strip()

        issues=[]

        if not employee_no:
            issues.append(
                "Employee number is required for payroll item migration."
            )

        if not source_name and not source_code:
            issues.append(
                "Payroll item name or code is required."
            )

        if not item_type:
            issues.append(
                "Payroll item type is required."
            )

        mapped=None

        if item_type:
            mapped=self.migration_payroll_item_resolve(
                company_id,
                project_id,
                dataset_id,
                item_type,
                source_code,
                source_name,
                cur=cur,
            )

        if not mapped:
            issues.append(
                f'Payroll item "{source_name or source_code}" is not mapped.'
            )

        employee=None

        if employee_no:
            schema=self.company_schema(
                int(company_id)
            )

            employee=self.fetch_one(f"""
                SELECT id,employee_no,first_name,last_name
                FROM {schema}.payroll_employees
                WHERE company_id=%s
                AND LOWER(employee_no)=LOWER(%s)
                LIMIT 1
            """,(
                int(company_id),
                employee_no,
            ),cur=cur)

        calculation_method=str(
            row.get("payroll_item_calculation_method")
            or (
                mapped.get("default_calculation_method")
                if mapped else None
            )
            or "fixed_amount"
        ).strip().lower()

        amount=self._migration_payroll_number(
            row.get("payroll_item_amount"),
            mapped.get("default_amount")
                if mapped else 0,
        )

        percentage=self._migration_payroll_number(
            row.get("payroll_item_percentage"),
            mapped.get("default_percentage")
                if mapped else 0,
        )

        quantity=self._migration_payroll_number(
            row.get("payroll_item_quantity"),
            mapped.get("default_quantity")
                if mapped else 0,
        )

        rate=self._migration_payroll_number(
            row.get("payroll_item_rate"),
            mapped.get("default_rate")
                if mapped else 0,
        )

        if calculation_method=="fixed_amount" and amount<0:
            issues.append(
                "Payroll item amount cannot be negative."
            )

        if (
            calculation_method=="percentage"
            and percentage<0
        ):
            issues.append(
                "Payroll item percentage cannot be negative."
            )

        if calculation_method=="quantity_rate":
            if quantity<0:
                issues.append(
                    "Payroll item quantity cannot be negative."
                )
            if rate<0:
                issues.append(
                    "Payroll item rate cannot be negative."
                )

        effective_from=self._migration_payroll_date(
            row.get("payroll_item_effective_from")
        ) or self._migration_payroll_date(
            settings.get("default_effective_from")
        )

        effective_to=self._migration_payroll_date(
            row.get("payroll_item_effective_to")
        )

        if (
            effective_from
            and effective_to
            and effective_to<effective_from
        ):
            issues.append(
                "Payroll item effective-to cannot be before effective-from."
            )

        return {
            "valid":not issues,
            "issues":issues,

            "employee":{
                "employee_id":
                    employee.get("id")
                    if employee else None,

                "employee_no":employee_no,

                "employee_name":
                    " ".join(filter(None,[
                        employee.get("first_name")
                            if employee else None,
                        employee.get("last_name")
                            if employee else None,
                    ])),
            },

            "item":{
                "item_type":item_type,

                "source_code":
                    source_code or None,

                "source_name":
                    source_name or source_code,

                "target_id":
                    mapped.get("target_id")
                    if mapped else None,

                "target_code":
                    mapped.get("target_code")
                    if mapped else None,

                "target_name":
                    mapped.get("target_name")
                    if mapped else None,

                "calculation_method":
                    calculation_method,

                "amount":
                    round(amount,2),

                "percentage":
                    round(percentage,4),

                "quantity":
                    round(quantity,4),

                "rate":
                    round(rate,4),

                "taxable":
                    row.get("payroll_item_taxable")
                    if row.get("payroll_item_taxable") not in (None,"")
                    else (
                        mapped.get("taxable")
                        if mapped else None
                    ),

                "pensionable":
                    row.get("payroll_item_pensionable")
                    if row.get("payroll_item_pensionable") not in (None,"")
                    else (
                        mapped.get("pensionable")
                        if mapped else None
                    ),

                "effective_from":effective_from,
                "effective_to":effective_to,
            },
        }


    def migration_payroll_items_preview(
        self,company_id:int,project_id:int,dataset_id:int,*,cur=None
    )->dict:
        settings=self.migration_payroll_item_settings_get(
            company_id,
            project_id,
            dataset_id,
            cur=cur,
        )

        rows=self.migration_payroll_normalized_rows(
            company_id,
            project_id,
            dataset_id,
            limit=500,
            cur=cur,
        )

        items=[]

        for index,row in enumerate(rows,start=1):
            normalized=row.get("normalized") or {}

            if not (
                normalized.get("payroll_item_name")
                or normalized.get("payroll_item_reference")
                or normalized.get("payroll_item_code")
            ):
                continue

            try:
                preview=self.migration_payroll_item_preview_row(
                    company_id,
                    project_id,
                    dataset_id,
                    normalized,
                    settings,
                    cur=cur,
                )
            except Exception as error:
                preview={
                    "valid":False,
                    "issues":[str(error)],
                    "employee":{
                        "employee_no":
                            normalized.get("employee_no"),
                    },
                    "item":normalized,
                }

            items.append({
                "row_number":index,
                "source":row.get("source"),
                **preview,
            })

        totals={
            "earning":0.0,
            "deduction":0.0,
            "benefit":0.0,
            "contribution":0.0,
        }

        for row in items:
            item=row.get("item") or {}
            item_type=item.get("item_type")

            if item_type in totals:
                totals[item_type]+=float(
                    item.get("amount") or 0
                )

        return {
            "dataset_id":int(dataset_id),
            "items":items,

            "item_count":len(items),

            "valid_count":sum(
                1 for item in items
                if item.get("valid")
            ),

            "error_count":sum(
                1 for item in items
                if not item.get("valid")
            ),

            "mapped_types":{
                item_type:sum(
                    1 for item in items
                    if item.get("item",{}).get("item_type")
                    ==item_type
                )
                for item_type in (
                    "earning",
                    "deduction",
                    "benefit",
                    "contribution",
                )
            },

            "totals":{
                key:round(value,2)
                for key,value in totals.items()
            },
        }

    def migration_payroll_items_mapping_get(
        self,company_id:int,project_id:int,dataset_id:int,*,cur=None
    )->dict:
        settings=self.migration_payroll_item_settings_get(
            company_id,
            project_id,
            dataset_id,
            cur=cur,
        )

        detection=self.migration_payroll_items_detect(
            company_id,
            project_id,
            dataset_id,
            cur=cur,
        )

        items=detection.get("items") or []

        unresolved=[
            item
            for item in items
            if (
                not item.get("item_type")
                or not item.get("target_id")
                or not item.get("is_approved")
            )
        ]

        return {
            "settings":settings,
            "detection":detection,

            "targets":{
                item_type:
                    self.migration_payroll_item_targets(
                        company_id,
                        item_type,
                        cur=cur,
                    )
                for item_type in (
                    "earning",
                    "deduction",
                    "benefit",
                    "contribution",
                )
            },

            "unresolved":unresolved,

            "is_complete":(
                not unresolved
                if settings.get(
                    "require_all_items_mapped",
                    True,
                )
                else True
            ),
        }

    def migration_payroll_leave_datasets(
        self,company_id:int,project_id:int,*,cur=None
    )->list[dict]:
        company_id,project_id=int(company_id),int(project_id)
        schema=self.company_schema(company_id)

        return self.fetch_all(f"""
            SELECT
                d.id AS dataset_id,
                d.dataset_name,
                d.record_count,
                d.column_count,
                d.dataset_status,
                f.original_name AS source_file_name
            FROM {schema}.migration_source_datasets d
            JOIN {schema}.migration_source_files f
            ON f.id=d.source_file_id
            WHERE d.company_id=%s
            AND d.project_id=%s
            AND d.entity_code='payroll_leave_balances'
            AND d.is_selected=TRUE
            ORDER BY d.id
        """,(company_id,project_id),cur=cur) or []


    def migration_payroll_loan_datasets(
        self,company_id:int,project_id:int,*,cur=None
    )->list[dict]:
        company_id,project_id=int(company_id),int(project_id)
        schema=self.company_schema(company_id)

        return self.fetch_all(f"""
            SELECT
                d.id AS dataset_id,
                d.dataset_name,
                d.record_count,
                d.column_count,
                d.dataset_status,
                f.original_name AS source_file_name
            FROM {schema}.migration_source_datasets d
            JOIN {schema}.migration_source_files f
            ON f.id=d.source_file_id
            WHERE d.company_id=%s
            AND d.project_id=%s
            AND d.entity_code='payroll_employee_loans'
            AND d.is_selected=TRUE
            ORDER BY d.id
        """,(company_id,project_id),cur=cur) or []

    def migration_payroll_leave_settings_get(
        self,company_id:int,project_id:int,dataset_id:int,*,cur=None
    )->dict:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)

        project=self.fetch_one(f"""
            SELECT cutover_date
            FROM {schema}.migration_projects
            WHERE company_id=%s AND id=%s
        """,(company_id,project_id),cur=cur)

        if not project:
            raise ValueError("Migration project not found.")

        row=self.fetch_one(f"""
            SELECT *
            FROM {schema}.migration_payroll_leave_settings
            WHERE company_id=%s
            AND project_id=%s
            AND dataset_id=%s
        """,(company_id,project_id,dataset_id),cur=cur)

        if row:
            row["settings_json"]=self._migration_json(row.get("settings_json"),{})
            row["metadata_json"]=self._migration_json(row.get("metadata_json"),{})
            return row

        return {
            "company_id":company_id,
            "project_id":project_id,
            "dataset_id":dataset_id,
            "migration_date":project.get("cutover_date"),
            "default_balance_unit":"days",
            "default_opening_source":"legacy_balance",
            "allow_negative_balance":False,
            "require_leave_type_mapping":True,
            "reconciliation_tolerance":0.01,
            "settings_json":{},
            "metadata_json":{},
        }

    def migration_payroll_leave_settings_save(
        self,company_id:int,project_id:int,dataset_id:int,data:dict,
        *,user_id:int|None=None,cur=None
    )->dict:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)
        data=data or {}

        current=self.migration_payroll_leave_settings_get(
            company_id,project_id,dataset_id,cur=cur
        )

        unit=str(
            data.get("default_balance_unit")
            or current.get("default_balance_unit")
            or "days"
        ).strip().lower()

        source=str(
            data.get("default_opening_source")
            or current.get("default_opening_source")
            or "legacy_balance"
        ).strip().lower()

        if unit not in {"days","hours"}:
            raise ValueError("Invalid leave balance unit.")

        if source not in {
            "legacy_balance",
            "entitlement_less_taken",
            "movement_history",
        }:
            raise ValueError("Invalid leave opening source.")

        self.execute_sql(f"""
            INSERT INTO {schema}.migration_payroll_leave_settings(
                company_id,project_id,dataset_id,
                migration_date,
                default_balance_unit,
                default_opening_source,
                allow_negative_balance,
                require_leave_type_mapping,
                reconciliation_tolerance,
                settings_json,
                metadata_json,
                created_by_user_id,
                updated_by_user_id,
                created_at,
                updated_at
            )
            VALUES(
                %s,%s,%s,%s,%s,%s,%s,%s,%s,
                %s::jsonb,%s::jsonb,%s,%s,NOW(),NOW()
            )
            ON CONFLICT(company_id,project_id,dataset_id)
            DO UPDATE SET
                migration_date=EXCLUDED.migration_date,
                default_balance_unit=EXCLUDED.default_balance_unit,
                default_opening_source=EXCLUDED.default_opening_source,
                allow_negative_balance=EXCLUDED.allow_negative_balance,
                require_leave_type_mapping=EXCLUDED.require_leave_type_mapping,
                reconciliation_tolerance=EXCLUDED.reconciliation_tolerance,
                settings_json=EXCLUDED.settings_json,
                metadata_json=EXCLUDED.metadata_json,
                updated_by_user_id=EXCLUDED.updated_by_user_id,
                updated_at=NOW()
        """,(
            company_id,project_id,dataset_id,
            data.get("migration_date") or current.get("migration_date"),
            unit,source,

            bool(data.get(
                "allow_negative_balance",
                current.get("allow_negative_balance",False),
            )),

            bool(data.get(
                "require_leave_type_mapping",
                current.get("require_leave_type_mapping",True),
            )),

            float(
                data.get("reconciliation_tolerance")
                if data.get("reconciliation_tolerance") not in (None,"")
                else current.get("reconciliation_tolerance") or 0.01
            ),

            self._migration_json_dump(
                data.get("settings_json") or current.get("settings_json"),{}
            ),

            self._migration_json_dump(
                data.get("metadata_json") or current.get("metadata_json"),{}
            ),

            user_id,user_id,
        ),cur=cur)

        return self.migration_payroll_leave_settings_get(
            company_id,project_id,dataset_id,cur=cur
        )

