    def migration_payroll_leave_type_targets(
        self,company_id:int,*,cur=None
    )->list[dict]:
        company_id=int(company_id)
        schema=self.company_schema(company_id)

        return self.fetch_all(f"""
            SELECT
                id,
                code,
                name
            FROM {schema}.payroll_leave_types
            WHERE company_id=%s
            AND is_active=TRUE
            ORDER BY code,name,id
        """,(company_id,),cur=cur) or []

    def migration_payroll_leave_types_detect(
        self,company_id:int,project_id:int,dataset_id:int,*,cur=None
    )->dict:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)

        rows=self.migration_payroll_normalized_rows(
            company_id,project_id,dataset_id,
            limit=500,
            cur=cur,
        )

        detected={}

        for item in rows:
            row=item.get("normalized") or {}

            source_code=str(
                row.get("leave_type_code") or ""
            ).strip()

            source_name=str(
                row.get("leave_type_name") or ""
            ).strip()

            if not source_name and not source_code:
                continue

            key=(source_code.lower(),source_name.lower())

            if key not in detected:
                detected[key]={
                    "source_code":source_code or None,
                    "source_name":source_name or source_code,
                    "sample_count":0,
                }

            detected[key]["sample_count"]+=1

        targets=self.migration_payroll_leave_type_targets(
            company_id,
            cur=cur,
        )

        saved=self.fetch_all(f"""
            SELECT *
            FROM {schema}.migration_payroll_leave_type_mappings
            WHERE company_id=%s
            AND project_id=%s
            AND dataset_id=%s
            ORDER BY source_name
        """,(company_id,project_id,dataset_id),cur=cur) or []

        saved_map={
            str(row.get("source_name") or "").lower():row
            for row in saved
        }

        result=[]

        for item in detected.values():
            existing=saved_map.get(
                item["source_name"].lower()
            )

            if existing:
                result.append({
                    **item,
                    **existing,
                })
                continue

            source_code=str(
                item.get("source_code") or ""
            ).upper()

            source_name=item["source_name"].lower()

            target=next(
                (
                    row for row in targets
                    if source_code
                    and str(row.get("code") or "").upper()==source_code
                ),
                None,
            )

            confidence=100 if target else 0

            if not target:
                target=next(
                    (
                        row for row in targets
                        if str(row.get("name") or "").strip().lower()
                        ==source_name
                    ),
                    None,
                )

                if target:
                    confidence=98

            result.append({
                **item,
                "target_leave_type_id":
                    target.get("id")
                    if target else None,

                "target_code":
                    target.get("code")
                    if target else None,

                "target_name":
                    target.get("name")
                    if target else None,

                "mapping_method":
                    "auto" if target else "manual",

                "confidence":confidence,
                "is_approved":False,
            })

        return {
            "items":result,
            "targets":targets,

            "detected_count":len(result),

            "mapped_count":sum(
                1 for item in result
                if item.get("target_leave_type_id")
            ),

            "approved_count":sum(
                1 for item in result
                if item.get("is_approved")
            ),
        }

    def migration_payroll_leave_type_mapping_save(
        self,company_id:int,project_id:int,dataset_id:int,mappings:list[dict],
        *,user_id:int|None=None,cur=None
    )->dict:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)

        targets=self.migration_payroll_leave_type_targets(
            company_id,
            cur=cur,
        )

        for item in mappings or []:
            source_name=str(
                item.get("source_name") or ""
            ).strip()

            source_code=str(
                item.get("source_code") or ""
            ).strip() or None

            target_id=int(
                item.get("target_leave_type_id")
                or item.get("target_id")
                or 0
            )

            if not source_name:
                raise ValueError(
                    "Source leave type name is required."
                )

            if not target_id:
                raise ValueError(
                    f'Select a leave type for "{source_name}".'
                )

            target=next(
                (
                    row for row in targets
                    if int(row["id"])==target_id
                ),
                None,
            )

            if not target:
                raise ValueError(
                    f'Invalid leave type for "{source_name}".'
                )

            self.execute_sql(f"""
                INSERT INTO {schema}.migration_payroll_leave_type_mappings(
                    company_id,
                    project_id,
                    dataset_id,
                    source_code,
                    source_name,
                    target_leave_type_id,
                    target_code,
                    target_name,
                    mapping_method,
                    confidence,
                    is_approved,
                    metadata_json,
                    created_by_user_id,
                    updated_by_user_id,
                    created_at,
                    updated_at
                )
                VALUES(
                    %s,%s,%s,%s,%s,
                    %s,%s,%s,
                    'manual',100,TRUE,
                    '{{}}'::jsonb,
                    %s,%s,NOW(),NOW()
                )
                ON CONFLICT(
                    company_id,
                    project_id,
                    dataset_id,
                    source_name
                )
                DO UPDATE SET
                    source_code=EXCLUDED.source_code,
                    target_leave_type_id=EXCLUDED.target_leave_type_id,
                    target_code=EXCLUDED.target_code,
                    target_name=EXCLUDED.target_name,
                    mapping_method='manual',
                    confidence=100,
                    is_approved=TRUE,
                    updated_by_user_id=EXCLUDED.updated_by_user_id,
                    updated_at=NOW()
            """,(
                company_id,project_id,dataset_id,
                source_code,source_name,
                target["id"],
                target.get("code"),
                target.get("name"),
                user_id,user_id,
            ),cur=cur)

        return self.migration_payroll_leave_types_detect(
            company_id,project_id,dataset_id,cur=cur
        )



    def migration_payroll_leave_type_resolve(
        self,company_id:int,project_id:int,dataset_id:int,
        source_code,source_name,*,cur=None
    ):
        schema=self.company_schema(int(company_id))

        source_code=str(source_code or "").strip()
        source_name=str(source_name or "").strip()

        if source_code:
            row=self.fetch_one(f"""
                SELECT *
                FROM {schema}.migration_payroll_leave_type_mappings
                WHERE company_id=%s
                AND project_id=%s
                AND dataset_id=%s
                AND LOWER(COALESCE(source_code,''))=LOWER(%s)
                AND is_approved=TRUE
                LIMIT 1
            """,(
                int(company_id),
                int(project_id),
                int(dataset_id),
                source_code,
            ),cur=cur)

            if row:return row

        if source_name:
            return self.fetch_one(f"""
                SELECT *
                FROM {schema}.migration_payroll_leave_type_mappings
                WHERE company_id=%s
                AND project_id=%s
                AND dataset_id=%s
                AND LOWER(source_name)=LOWER(%s)
                AND is_approved=TRUE
                LIMIT 1
            """,(
                int(company_id),
                int(project_id),
                int(dataset_id),
                source_name,
            ),cur=cur)

        return None


    def migration_payroll_employee_resolve(
        self,company_id:int,employee_no,*,cur=None
    ):
        employee_no=str(employee_no or "").strip()
        if not employee_no:return None

        schema=self.company_schema(int(company_id))

        return self.fetch_one(f"""
            SELECT
                id,
                employee_no,
                first_name,
                last_name
            FROM {schema}.payroll_employees
            WHERE company_id=%s
            AND LOWER(employee_no)=LOWER(%s)
            LIMIT 1
        """,(int(company_id),employee_no),cur=cur)


    def migration_payroll_leave_preview_row(
        self,company_id:int,project_id:int,dataset_id:int,
        row:dict,settings:dict,*,cur=None
    )->dict:
        employee_no=str(
            row.get("employee_no") or ""
        ).strip()

        source_name=str(
            row.get("leave_type_name") or ""
        ).strip()

        source_code=str(
            row.get("leave_type_code") or ""
        ).strip()

        issues=[]
        warnings=[]

        if not employee_no:
            issues.append("Employee number is required.")

        if not source_name and not source_code:
            issues.append("Leave type is required.")

        mapping=self.migration_payroll_leave_type_resolve(
            company_id,
            project_id,
            dataset_id,
            source_code,
            source_name,
            cur=cur,
        )

        if (
            settings.get("require_leave_type_mapping")
            and not mapping
        ):
            issues.append(
                f'Leave type "{source_name or source_code}" is not mapped.'
            )

        source_mode=str(
            settings.get("default_opening_source")
            or "legacy_balance"
        ).strip().lower()

        entitlement=self._migration_payroll_number(
            row.get("opening_entitlement")
        )

        taken=self._migration_payroll_number(
            row.get("leave_taken_to_date")
        )

        adjustments=self._migration_payroll_number(
            row.get("leave_adjustments")
        )

        imported_balance=self._migration_payroll_number(
            row.get("opening_balance")
            if row.get("opening_balance") not in (None,"")
            else row.get("accrued_balance")
        )

        carried_forward=self._migration_payroll_number(
            row.get("carried_forward")
        )

        if source_mode=="entitlement_less_taken":
            calculated_balance=round(
                entitlement-taken+adjustments+carried_forward,
                4,
            )

        else:
            calculated_balance=round(
                imported_balance,
                4,
            )

        tolerance=float(
            settings.get("reconciliation_tolerance") or 0.01
        )

        difference=round(
            imported_balance-calculated_balance,
            4,
        )

        if (
            source_mode=="entitlement_less_taken"
            and row.get("opening_balance") not in (None,"")
            and abs(difference)>tolerance
        ):
            issues.append(
                f"Opening leave balance differs from entitlement less taken by {difference:.4f}."
            )

        if (
            calculated_balance<0
            and not settings.get("allow_negative_balance")
        ):
            issues.append(
                "Negative leave balance is not allowed."
            )

        employee=self.migration_payroll_employee_resolve(
            company_id,
            employee_no,
            cur=cur,
        )

        if not employee:
            warnings.append(
                "Employee is not in the live payroll yet; migration will link by employee number during commit."
            )

        unit=str(
            row.get("balance_unit")
            or settings.get("default_balance_unit")
            or "days"
        ).strip().lower()

        if unit not in {"days","hours"}:
            issues.append("Leave balance unit must be days or hours.")

        migration_date=self._migration_payroll_date(
            row.get("migration_date")
            or settings.get("migration_date")
        )

        return {
            "valid":not issues,
            "issues":issues,
            "warnings":warnings,

            "employee":{
                "employee_id":
                    employee.get("id")
                    if employee else None,

                "employee_no":employee_no,

                "employee_name":
                    " ".join(filter(None,[
                        employee.get("first_name")
                            if employee else None,
                        employee.get("last_name")
                            if employee else None,
                    ])),
            },

            "leave":{
                "leave_type_id":
                    mapping.get("target_leave_type_id")
                    if mapping else None,

                "leave_type_code":
                    mapping.get("target_code")
                    if mapping else source_code or None,

                "leave_type_name":
                    mapping.get("target_name")
                    if mapping else source_name or source_code,

                "balance_unit":unit,

                "opening_entitlement":
                    round(entitlement,4),

                "leave_taken_to_date":
                    round(taken,4),

                "adjustments":
                    round(adjustments,4),

                "carried_forward":
                    round(carried_forward,4),

                "opening_balance":
                    round(calculated_balance,4),

                "expiry_date":
                    self._migration_payroll_date(
                        row.get("expiry_date")
                    ),

                "migration_date":migration_date,
                "notes":row.get("notes"),
            },

            "reconciliation":{
                "source_mode":source_mode,
                "imported_balance":
                    round(imported_balance,4),

                "calculated_balance":
                    round(calculated_balance,4),

                "difference":difference,
                "tolerance":tolerance,
            },
        }

    def migration_payroll_leave_preview(
        self,company_id:int,project_id:int,dataset_id:int,*,cur=None
    )->dict:
        settings=self.migration_payroll_leave_settings_get(
            company_id,project_id,dataset_id,cur=cur
        )

        rows=self.migration_payroll_normalized_rows(
            company_id,
            project_id,
            dataset_id,
            limit=1000,
            cur=cur,
        )

        items=[]

        for index,item in enumerate(rows,start=1):
            try:
                preview=self.migration_payroll_leave_preview_row(
                    company_id,
                    project_id,
                    dataset_id,
                    item.get("normalized") or {},
                    settings,
                    cur=cur,
                )
            except Exception as error:
                preview={
                    "valid":False,
                    "issues":[str(error)],
                    "warnings":[],
                    "employee":{
                        "employee_no":
                            item.get("normalized",{}).get("employee_no"),
                    },
                    "leave":{},
                    "reconciliation":{},
                }

            items.append({
                "row_number":index,
                "source":item.get("source"),
                **preview,
            })

        return {
            "dataset_id":int(dataset_id),
            "items":items,

            "balance_count":len(items),

            "valid_count":sum(
                1 for row in items
                if row.get("valid")
            ),

            "error_count":sum(
                1 for row in items
                if not row.get("valid")
            ),

            "total_opening_balance":round(sum(
                self._migration_payroll_number(
                    row.get("leave",{}).get("opening_balance")
                )
                for row in items
            ),4),
        }

    def migration_payroll_employee_loan_preview_row(
        self,company_id:int,project_id:int,dataset_id:int,
        row:dict,settings:dict,*,cur=None
    )->dict:
        employee_no=str(
            row.get("employee_no") or ""
        ).strip()

        loan_name=str(
            row.get("loan_name") or ""
        ).strip()

        loan_reference=str(
            row.get("loan_reference") or ""
        ).strip() or None

        issues=[]
        warnings=[]

        if not employee_no:
            issues.append("Employee number is required.")

        if not loan_name:
            issues.append("Loan name is required.")

        original_amount=self._migration_payroll_number(
            row.get("original_amount")
        )

        repaid=self._migration_payroll_number(
            row.get("amount_repaid_to_date")
        )

        outstanding=self._migration_payroll_number(
            row.get("outstanding_balance")
        )

        tolerance=float(
            settings.get("reconciliation_tolerance") or 1
        )

        calculated_outstanding=None
        difference=None

        if original_amount>0:
            calculated_outstanding=round(
                max(original_amount-repaid,0),
                2,
            )

            difference=round(
                outstanding-calculated_outstanding,
                2,
            )

            if abs(difference)>tolerance:
                issues.append(
                    f"Outstanding employee-loan balance differs from original less repayments by {difference:.2f}."
                )

        if outstanding<=0:
            issues.append(
                "Outstanding employee-loan balance must be greater than zero."
            )

        method=str(
            row.get("interest_method")
            or settings.get("default_interest_method")
            or "reducing_balance"
        ).strip().lower()

        frequency=str(
            row.get("repayment_frequency")
            or settings.get("default_frequency")
            or "monthly"
        ).strip().lower()

        if method not in {
            "reducing_balance",
            "flat",
            "interest_free",
            "manual",
        }:
            issues.append(
                f"Unsupported interest method: {method}."
            )

        if frequency not in {
            "weekly",
            "fortnightly",
            "monthly",
        }:
            issues.append(
                f"Unsupported repayment frequency: {frequency}."
            )

        repayment_amount=self._migration_payroll_number(
            row.get("repayment_amount")
        )

        if repayment_amount<=0:
            warnings.append(
                "Repayment amount is missing; payroll deduction cannot continue automatically until configured."
            )

        employee=self.migration_payroll_employee_resolve(
            company_id,
            employee_no,
            cur=cur,
        )

        if not employee:
            warnings.append(
                "Employee is not in the live payroll yet; migration will link by employee number during commit."
            )

        deduction_mapping=None
        deduction_reference=str(
            row.get("deduction_reference") or ""
        ).strip()

        if deduction_reference:
            deduction_mapping=self.migration_payroll_reference_resolve(
                company_id,
                project_id,
                dataset_id,
                "deduction_type",
                deduction_reference,
                cur=cur,
            )

        if (
            settings.get("require_deduction_mapping")
            and not deduction_mapping
        ):
            issues.append(
                "Employee loan payroll deduction is not mapped."
            )

        migration_date=self._migration_payroll_date(
            row.get("migration_date")
            or settings.get("migration_date")
        )

        return {
            "valid":not issues,
            "issues":issues,
            "warnings":warnings,

            "employee":{
                "employee_id":
                    employee.get("id")
                    if employee else None,

                "employee_no":employee_no,

                "employee_name":
                    " ".join(filter(None,[
                        employee.get("first_name")
                            if employee else None,
                        employee.get("last_name")
                            if employee else None,
                    ])),
            },

            "loan":{
                "loan_reference":loan_reference,
                "loan_name":loan_name,

                "currency":str(
                    row.get("currency")
                    or settings.get("default_currency")
                    or "USD"
                ).strip().upper(),

                "original_amount":
                    round(original_amount,2),

                "amount_repaid_to_date":
                    round(repaid,2),

                "outstanding_balance":
                    round(outstanding,2),

                "interest_rate":
                    round(
                        self._migration_payroll_number(
                            row.get("interest_rate")
                        ),
                        6,
                    ),

                "interest_method":method,

                "repayment_amount":
                    round(repayment_amount,2),

                "repayment_frequency":
                    frequency,

                "start_date":
                    self._migration_payroll_date(
                        row.get("start_date")
                    ),

                "next_repayment_date":
                    self._migration_payroll_date(
                        row.get("next_repayment_date")
                    ),

                "maturity_date":
                    self._migration_payroll_date(
                        row.get("maturity_date")
                    ),

                "deduction_type_id":
                    deduction_mapping,

                "deduction_reference":
                    deduction_reference or None,

                "migration_date":
                    migration_date,

                "notes":
                    row.get("notes"),
            },

            "reconciliation":{
                "original_amount":
                    round(original_amount,2),

                "amount_repaid_to_date":
                    round(repaid,2),

                "calculated_outstanding":
                    calculated_outstanding,

                "imported_outstanding":
                    round(outstanding,2),

                "difference":
                    difference,

                "tolerance":
                    tolerance,
            },
        }

    def migration_payroll_employee_loans_preview(
        self,company_id:int,project_id:int,dataset_id:int,*,cur=None
    )->dict:
        settings=self.migration_payroll_loan_settings_get(
            company_id,project_id,dataset_id,cur=cur
        )

        rows=self.migration_payroll_normalized_rows(
            company_id,
            project_id,
            dataset_id,
            limit=1000,
            cur=cur,
        )

        items=[]

        for index,item in enumerate(rows,start=1):
            try:
                preview=self.migration_payroll_employee_loan_preview_row(
                    company_id,
                    project_id,
                    dataset_id,
                    item.get("normalized") or {},
                    settings,
                    cur=cur,
                )
            except Exception as error:
                preview={
                    "valid":False,
                    "issues":[str(error)],
                    "warnings":[],
                    "employee":{
                        "employee_no":
                            item.get("normalized",{}).get("employee_no"),
                    },
                    "loan":{},
                    "reconciliation":{},
                }

            items.append({
                "row_number":index,
                "source":item.get("source"),
                **preview,
            })

        return {
            "dataset_id":int(dataset_id),
            "items":items,

            "loan_count":len(items),

            "valid_count":sum(
                1 for row in items
                if row.get("valid")
            ),

            "error_count":sum(
                1 for row in items
                if not row.get("valid")
            ),

            "total_outstanding":round(sum(
                self._migration_payroll_number(
                    row.get("loan",{}).get("outstanding_balance")
                )
                for row in items
            ),2),

            "total_repayment_amount":round(sum(
                self._migration_payroll_number(
                    row.get("loan",{}).get("repayment_amount")
                )
                for row in items
            ),2),
        }

    def migration_payroll_leave_mapping_get(
        self,company_id:int,project_id:int,dataset_id:int,*,cur=None
    )->dict:
        settings=self.migration_payroll_leave_settings_get(
            company_id,project_id,dataset_id,cur=cur
        )

        field_mapping=self.migration_field_mapping_dataset(
            company_id,project_id,dataset_id,cur=cur
        )

        leave_types=self.migration_payroll_leave_types_detect(
            company_id,project_id,dataset_id,cur=cur
        )

        required={
            "employee_no",
            "leave_type_name",
        }

        mapped={
            row.get("target_field_code")
            for row in field_mapping.get("rows") or []
            if row.get("mapping_status")=="mapped"
        }

        missing_fields=sorted(
            required-mapped
        )

        unresolved=[]

        if settings.get("require_leave_type_mapping"):
            unresolved=[
                item
                for item in leave_types.get("items") or []
                if (
                    not item.get("target_leave_type_id")
                    or not item.get("is_approved")
                )
            ]

        return {
            "settings":settings,
            "field_mapping":field_mapping,
            "leave_types":leave_types,
            "missing_fields":missing_fields,
            "unresolved_leave_types":unresolved,

            "is_complete":
                not missing_fields
                and not unresolved,
        }

    def migration_payroll_loan_mapping_get(
        self,company_id:int,project_id:int,dataset_id:int,*,cur=None
    )->dict:
        settings=self.migration_payroll_loan_settings_get(
            company_id,project_id,dataset_id,cur=cur
        )

        field_mapping=self.migration_field_mapping_dataset(
            company_id,project_id,dataset_id,cur=cur
        )

        required={
            "employee_no",
            "loan_name",
            "outstanding_balance",
        }

        mapped={
            row.get("target_field_code")
            for row in field_mapping.get("rows") or []
            if row.get("mapping_status")=="mapped"
        }

        missing_fields=sorted(
            required-mapped
        )

        return {
            "settings":settings,
            "field_mapping":field_mapping,
            "missing_fields":missing_fields,
            "is_complete":not missing_fields,
        }

    def migration_payroll_history_datasets(
        self,company_id:int,project_id:int,*,cur=None
    )->list[dict]:
        company_id,project_id=int(company_id),int(project_id)
        schema=self.company_schema(company_id)

        return self.fetch_all(f"""
            SELECT
                d.id AS dataset_id,
                d.dataset_name,
                d.record_count,
                d.column_count,
                d.dataset_status,
                f.original_name AS source_file_name
            FROM {schema}.migration_source_datasets d
            JOIN {schema}.migration_source_files f
            ON f.id=d.source_file_id
            WHERE d.company_id=%s
            AND d.project_id=%s
            AND d.entity_code='payroll_history'
            AND d.is_selected=TRUE
            ORDER BY d.id
        """,(company_id,project_id),cur=cur) or []

    def migration_payroll_history_settings_get(
        self,company_id:int,project_id:int,dataset_id:int,*,cur=None
    )->dict:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)

        project=self.fetch_one(f"""
            SELECT cutover_date,default_currency
            FROM {schema}.migration_projects
            WHERE company_id=%s AND id=%s
        """,(company_id,project_id),cur=cur)

        if not project:
            raise ValueError("Migration project not found.")

        row=self.fetch_one(f"""
            SELECT *
            FROM {schema}.migration_payroll_history_settings
            WHERE company_id=%s
            AND project_id=%s
            AND dataset_id=%s
        """,(company_id,project_id,dataset_id),cur=cur)

        if row:
            row["settings_json"]=self._migration_json(row.get("settings_json"),{})
            row["metadata_json"]=self._migration_json(row.get("metadata_json"),{})
            return row

        payroll_settings=self.fetch_one(f"""
            SELECT default_currency,default_frequency
            FROM {schema}.payroll_settings
            WHERE company_id=%s
            LIMIT 1
        """,(company_id,),cur=cur) or {}

        return {
            "company_id":company_id,
            "project_id":project_id,
            "dataset_id":dataset_id,

            "source_layout":"summary_rows",
            "migration_date":project.get("cutover_date"),

            "default_currency":
                payroll_settings.get("default_currency")
                or project.get("default_currency"),

            "default_pay_frequency":
                payroll_settings.get("default_frequency")
                or "monthly",

            "preserve_source_tax":True,
            "preserve_source_net_pay":True,
            "require_employee_mapping":True,
            "require_item_mapping":False,

            "reconciliation_tolerance":1.00,

            "settings_json":{},
            "metadata_json":{},
        }

    def migration_payroll_history_settings_save(
        self,company_id:int,project_id:int,dataset_id:int,data:dict,
        *,user_id:int|None=None,cur=None
    )->dict:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)
        data=data or {}

        current=self.migration_payroll_history_settings_get(
            company_id,project_id,dataset_id,cur=cur
        )

        layout=str(
            data.get("source_layout")
            or current.get("source_layout")
            or "summary_rows"
        ).strip().lower()

        frequency=str(
            data.get("default_pay_frequency")
            or current.get("default_pay_frequency")
            or "monthly"
        ).strip().lower()

        if layout not in {"summary_rows","item_rows"}:
            raise ValueError("Invalid historical payroll source layout.")

        if frequency not in {"weekly","fortnightly","monthly"}:
            raise ValueError("Invalid historical payroll frequency.")

        self.execute_sql(f"""
            INSERT INTO {schema}.migration_payroll_history_settings(
                company_id,project_id,dataset_id,
                source_layout,migration_date,
                default_currency,default_pay_frequency,

                preserve_source_tax,
                preserve_source_net_pay,
                require_employee_mapping,
                require_item_mapping,

                reconciliation_tolerance,
                settings_json,
                metadata_json,

                created_by_user_id,
                updated_by_user_id,
                created_at,
                updated_at
            )
            VALUES(
                %s,%s,%s,%s,%s,%s,%s,
                %s,%s,%s,%s,
                %s,%s::jsonb,%s::jsonb,
                %s,%s,NOW(),NOW()
            )
            ON CONFLICT(company_id,project_id,dataset_id)
            DO UPDATE SET
                source_layout=EXCLUDED.source_layout,
                migration_date=EXCLUDED.migration_date,
                default_currency=EXCLUDED.default_currency,
                default_pay_frequency=EXCLUDED.default_pay_frequency,

                preserve_source_tax=EXCLUDED.preserve_source_tax,
                preserve_source_net_pay=EXCLUDED.preserve_source_net_pay,
                require_employee_mapping=EXCLUDED.require_employee_mapping,
                require_item_mapping=EXCLUDED.require_item_mapping,

                reconciliation_tolerance=EXCLUDED.reconciliation_tolerance,
                settings_json=EXCLUDED.settings_json,
                metadata_json=EXCLUDED.metadata_json,

                updated_by_user_id=EXCLUDED.updated_by_user_id,
                updated_at=NOW()
        """,(
            company_id,project_id,dataset_id,
            layout,
            data.get("migration_date") or current.get("migration_date"),

            data.get("default_currency")
                or current.get("default_currency"),

            frequency,

            bool(data.get(
                "preserve_source_tax",
                current.get("preserve_source_tax",True),
            )),

            bool(data.get(
                "preserve_source_net_pay",
                current.get("preserve_source_net_pay",True),
            )),

            bool(data.get(
                "require_employee_mapping",
                current.get("require_employee_mapping",True),
            )),

            bool(data.get(
                "require_item_mapping",
                current.get("require_item_mapping",False),
            )),

            float(
                data.get("reconciliation_tolerance")
                if data.get("reconciliation_tolerance") not in (None,"")
                else current.get("reconciliation_tolerance") or 1
            ),

            self._migration_json_dump(
                data.get("settings_json") or current.get("settings_json"),{}
            ),

            self._migration_json_dump(
                data.get("metadata_json") or current.get("metadata_json"),{}
            ),

            user_id,user_id,
        ),cur=cur)

        return self.migration_payroll_history_settings_get(
            company_id,project_id,dataset_id,cur=cur
        )

    def migration_payroll_history_normalized_rows(
        self,company_id:int,project_id:int,dataset_id:int,
        *,limit:int=5000,cur=None
    )->list[dict]:
        company_id,project_id,dataset_id=int(company_id),int(project_id),int(dataset_id)
        schema=self.company_schema(company_id)

        mapping=self.migration_field_mapping_dataset(
            company_id,project_id,dataset_id,cur=cur
        )

        dataset=self.fetch_one(f"""
            SELECT metadata_json
            FROM {schema}.migration_source_datasets
            WHERE company_id=%s
            AND project_id=%s
            AND id=%s
        """,(company_id,project_id,dataset_id),cur=cur)

        metadata=self._migration_json(
            dataset.get("metadata_json") if dataset else {},
            {},
        )

        source_rows=metadata.get("sample_rows") or []

        source_to_target={
            row["source_name"]:row["target_field_code"]
            for row in mapping.get("rows") or []
            if row.get("mapping_status")=="mapped"
            and row.get("target_field_code")
        }

        result=[]

        for source_row in source_rows[:limit]:
            normalized={}

            for source_name,target_field in source_to_target.items():
                normalized[target_field]=source_row.get(source_name)

            result.append({
                "source":source_row,
                "normalized":normalized,
            })

        return result

    def migration_payroll_history_groups(
        self,rows:list[dict]
    )->dict:
        groups={}

        for item in rows:
            row=item.get("normalized") or {}

            run_reference=str(
                row.get("run_reference") or ""
            ).strip()

            employee_no=str(
                row.get("employee_no") or ""
            ).strip()

            key=(run_reference,employee_no)

            groups.setdefault(key,[]).append(row)

        return groups

    def _migration_payroll_history_status(self,value)->str:
        value=str(value or "").strip().lower()

        aliases={
            "completed":"completed",
            "complete":"completed",
            "final":"completed",
            "finalised":"completed",
            "finalized":"completed",
            "paid":"paid",
            "posted":"posted",
            "closed":"completed",
        }

        return aliases.get(value,"completed")


    def _migration_payroll_history_item_type(self,value)->str|None:
        value=str(value or "").strip().lower()

        aliases={
            "earning":"earning",
            "earnings":"earning",
            "income":"earning",
            "allowance":"earning",

            "deduction":"deduction",
            "deductions":"deduction",

            "tax":"tax",
            "paye":"tax",

            "benefit":"benefit",
            "fringe benefit":"benefit",

            "contribution":"contribution",
            "employer contribution":"contribution",
            "employer_contribution":"contribution",
        }

        return aliases.get(value)

    def migration_payroll_history_employee_preview(
        self,company_id:int,project_id:int,dataset_id:int,
        rows:list[dict],settings:dict,*,cur=None
    )->dict:
        if not rows:
            raise ValueError("Historical payroll employee has no source rows.")

        first=rows[0]

        run_reference=str(
            first.get("run_reference") or ""
        ).strip()

        employee_no=str(
            first.get("employee_no") or ""
        ).strip()

        issues=[]
        warnings=[]

        if not run_reference:
            issues.append("Payroll run reference is required.")

        if not employee_no:
            issues.append("Employee number is required.")

        period_start=self._migration_payroll_date(
            first.get("period_start"),
            required=True,
        )

        period_end=self._migration_payroll_date(
            first.get("period_end"),
            required=True,
        )

        payment_date=self._migration_payroll_date(
            first.get("payment_date")
        )

        if period_end<period_start:
            issues.append(
                "Payroll period end cannot be before period start."
            )

        migration_date=self._migration_payroll_date(
            settings.get("migration_date")
        )

        if migration_date and period_end>migration_date:
            issues.append(
                "Historical payroll period cannot end after migration date."
            )

        employee=self.migration_payroll_employee_resolve(
            company_id,
            employee_no,
            cur=cur,
        )

        if (
            settings.get("require_employee_mapping")
            and not employee
        ):
            warnings.append(
                "Employee is not yet in live payroll; historical import will link by employee number after employee migration."
            )

        layout=str(
            settings.get("source_layout")
            or "summary_rows"
        ).strip().lower()

        items=[]

        if layout=="item_rows":
            gross=0.0
            taxable=0.0
            paye=0.0
            deductions=0.0
            employer_contributions=0.0
            basic_pay=0.0

            for row in rows:
                item_type=self._migration_payroll_history_item_type(
                    row.get("payroll_item_type")
                )

                code=str(
                    row.get("payroll_item_code") or ""
                ).strip()

                name=str(
                    row.get("payroll_item_name") or ""
                ).strip()

                amount=round(
                    self._migration_payroll_number(
                        row.get("payroll_item_amount")
                    ),
                    2,
                )

                taxable_flag=self._migration_payroll_bool(
                    row.get("taxable")
                )

                if not item_type:
                    issues.append(
                        f'Payroll item "{name or code}" has no valid item type.'
                    )
                    continue

                mapped=None

                if item_type in {
                    "earning",
                    "deduction",
                    "benefit",
                    "contribution",
                }:
                    mapped=self.migration_payroll_item_resolve(
                        company_id,
                        project_id,
                        None,
                        item_type,
                        code,
                        name,
                        cur=cur,
                    )

                if (
                    settings.get("require_item_mapping")
                    and item_type!="tax"
                    and not mapped
                ):
                    issues.append(
                        f'Historical payroll item "{name or code}" is not mapped.'
                    )

                if item_type=="earning":
                    gross+=amount

                    if taxable_flag:
                        taxable+=amount

                    if code.upper()=="BASIC" or name.strip().lower() in {
                        "basic","basic pay","basic salary"
                    }:
                        basic_pay+=amount

                elif item_type=="tax":
                    paye+=amount

                elif item_type=="deduction":
                    deductions+=amount

                elif item_type=="contribution":
                    employer_contributions+=amount

                items.append({
                    "item_type":item_type,

                    "source_code":
                        code or None,

                    "source_name":
                        name or code,

                    "target_id":
                        mapped.get("target_id")
                        if mapped else None,

                    "target_code":
                        mapped.get("target_code")
                        if mapped else None,

                    "target_name":
                        mapped.get("target_name")
                        if mapped else None,

                    "amount":amount,

                    "quantity":
                        self._migration_payroll_number(
                            row.get("payroll_item_quantity")
                        ),

                    "rate":
                        self._migration_payroll_number(
                            row.get("payroll_item_rate")
                        ),

                    "taxable":
                        taxable_flag,

                    "pensionable":
                        self._migration_payroll_bool(
                            row.get("pensionable")
                        ),
                })

            source_net=self._migration_payroll_number(
                first.get("net_pay")
            )

            total_deductions=round(
                paye+deductions,
                2,
            )

        else:
            basic_pay=self._migration_payroll_number(
                first.get("basic_pay")
            )

            gross=self._migration_payroll_number(
                first.get("gross_pay")
            )

            taxable=self._migration_payroll_number(
                first.get("taxable_pay"),
                gross,
            )

            paye=self._migration_payroll_number(
                first.get("paye_amount")
            )

            deductions=self._migration_payroll_number(
                first.get("employee_deductions")
            )

            supplied_total_deductions=first.get(
                "total_deductions"
            )

            if supplied_total_deductions not in (None,""):
                total_deductions=self._migration_payroll_number(
                    supplied_total_deductions
                )

                if deductions==0:
                    deductions=max(
                        total_deductions-paye,
                        0,
                    )

            else:
                total_deductions=paye+deductions

            employer_contributions=self._migration_payroll_number(
                first.get("employer_contributions")
            )

            source_net=self._migration_payroll_number(
                first.get("net_pay")
            )

        gross=round(gross,2)
        taxable=round(taxable,2)
        paye=round(paye,2)
        deductions=round(deductions,2)
        employer_contributions=round(
            employer_contributions,
            2,
        )

        total_deductions=round(
            total_deductions,
            2,
        )

        calculated_net=round(
            gross-total_deductions,
            2,
        )

        tolerance=float(
            settings.get("reconciliation_tolerance")
            or 1
        )

        net_difference=round(
            source_net-calculated_net,
            2,
        )

        if abs(net_difference)>tolerance:
            issues.append(
                f"Source net pay differs from gross less deductions by {net_difference:.2f}."
            )

        if gross<0:
            issues.append("Gross pay cannot be negative.")

        if paye<0:
            issues.append("PAYE cannot be negative.")

        if total_deductions<0:
            issues.append("Total deductions cannot be negative.")

        if source_net<0:
            warnings.append(
                "Historical net pay is negative."
            )

        if taxable>gross+tolerance:
            warnings.append(
                "Taxable pay exceeds gross pay."
            )

        final_net=(
            source_net
            if settings.get("preserve_source_net_pay")
            else calculated_net
        )

        return {
            "valid":not issues,
            "issues":issues,
            "warnings":warnings,

            "run":{
                "run_reference":run_reference,

                "run_name":
                    str(first.get("run_name") or "").strip()
                    or run_reference,

                "period_start":period_start,
                "period_end":period_end,
                "payment_date":payment_date,

                "pay_frequency":str(
                    first.get("pay_frequency")
                    or settings.get("default_pay_frequency")
                    or "monthly"
                ).strip().lower(),

                "currency":str(
                    first.get("currency")
                    or settings.get("default_currency")
                    or "USD"
                ).strip().upper(),

                "status":
                    self._migration_payroll_history_status(
                        first.get("run_status")
                    ),
            },

            "employee":{
                "employee_id":
                    employee.get("id")
                    if employee else None,

                "employee_no":employee_no,

                "employee_name":
                    (
                        " ".join(filter(None,[
                            employee.get("first_name"),
                            employee.get("last_name"),
                        ]))
                        if employee
                        else str(
                            first.get("employee_name") or ""
                        ).strip()
                    ),
            },

            "result":{
                "basic_pay":round(basic_pay,2),
                "gross_pay":gross,
                "taxable_pay":taxable,

                "paye_amount":paye,

                "employee_deductions":
                    round(deductions,2),

                "total_deductions":
                    total_deductions,

                "employer_contributions":
                    employer_contributions,

                "source_net_pay":
                    round(source_net,2),

                "calculated_net_pay":
                    calculated_net,

                "net_pay":
                    round(final_net,2),
            },

            "payslip":{
                "payslip_reference":
                    first.get("payslip_reference"),

                "payment_reference":
                    first.get("payment_reference"),

                "payment_method":
                    first.get("payment_method"),

                "bank_account_last4":
                    first.get("bank_account_last4"),

                "notes":
                    first.get("notes"),
            },

            "items":items,

            "reconciliation":{
                "gross_pay":gross,
                "total_deductions":total_deductions,
                "calculated_net_pay":calculated_net,
                "source_net_pay":round(source_net,2),
                "net_difference":net_difference,
                "tolerance":tolerance,
            },
        }


    def migration_payroll_history_preview(
        self,company_id:int,project_id:int,dataset_id:int,*,cur=None
    )->dict:
        settings=self.migration_payroll_history_settings_get(
            company_id,project_id,dataset_id,cur=cur
        )

        rows=self.migration_payroll_history_normalized_rows(
            company_id,
            project_id,
            dataset_id,
            limit=5000,
            cur=cur,
        )

        groups=self.migration_payroll_history_groups(
            rows
        )

        employee_results=[]

        for index,((run_reference,employee_no),group_rows) in enumerate(
            groups.items(),
            start=1,
        ):
            try:
                preview=self.migration_payroll_history_employee_preview(
                    company_id,
                    project_id,
                    dataset_id,
                    group_rows,
                    settings,
                    cur=cur,
                )

            except Exception as error:
                preview={
                    "valid":False,
                    "issues":[str(error)],
                    "warnings":[],
                    "run":{
                        "run_reference":run_reference,
                    },
                    "employee":{
                        "employee_no":employee_no,
                    },
                    "result":{},
                    "payslip":{},
                    "items":[],
                    "reconciliation":{},
                }

            employee_results.append({
                "row_number":index,
                **preview,
            })

        runs={}

        for row in employee_results:
            run=row.get("run") or {}
            ref=str(
                run.get("run_reference") or ""
            ).strip()

            if ref not in runs:
                runs[ref]={
                    "run_reference":ref,
                    "run_name":run.get("run_name"),
                    "period_start":run.get("period_start"),
                    "period_end":run.get("period_end"),
                    "payment_date":run.get("payment_date"),
                    "currency":run.get("currency"),
                    "status":run.get("status"),

                    "employees":[],
                    "gross_pay":0.0,
                    "paye_amount":0.0,
                    "employee_deductions":0.0,
                    "employer_contributions":0.0,
                    "net_pay":0.0,
                }

            result=row.get("result") or {}

            runs[ref]["employees"].append(row)

            runs[ref]["gross_pay"]+=self._migration_payroll_number(
                result.get("gross_pay")
            )

            runs[ref]["paye_amount"]+=self._migration_payroll_number(
                result.get("paye_amount")
            )

            runs[ref]["employee_deductions"]+=self._migration_payroll_number(
                result.get("employee_deductions")
            )

            runs[ref]["employer_contributions"]+=self._migration_payroll_number(
                result.get("employer_contributions")
            )

            runs[ref]["net_pay"]+=self._migration_payroll_number(
                result.get("net_pay")
            )

        run_list=[]

        for run in runs.values():
            for field in (
                "gross_pay",
                "paye_amount",
                "employee_deductions",
                "employer_contributions",
                "net_pay",
            ):
                run[field]=round(
                    run[field],
                    2,
                )

            run["employee_count"]=len(
                run["employees"]
            )

            run["valid"]=all(
                employee.get("valid")
                for employee in run["employees"]
            )

            run["error_count"]=sum(
                len(employee.get("issues") or [])
                for employee in run["employees"]
            )

            run_list.append(run)

        run_list.sort(
            key=lambda row:(
                str(row.get("period_end") or ""),
                str(row.get("run_reference") or ""),
            )
        )

        return {
            "dataset_id":int(dataset_id),
            "runs":run_list,
            "employees":employee_results,

            "run_count":len(run_list),
            "employee_result_count":
                len(employee_results),

            "valid_run_count":sum(
                1 for run in run_list
                if run.get("valid")
            ),

            "error_run_count":sum(
                1 for run in run_list
                if not run.get("valid")
            ),

            "total_gross":round(sum(
                run["gross_pay"]
                for run in run_list
            ),2),

            "total_paye":round(sum(
                run["paye_amount"]
                for run in run_list
            ),2),

            "total_deductions":round(sum(
                run["employee_deductions"]
                for run in run_list
            ),2),

            "total_employer_contributions":round(sum(
                run["employer_contributions"]
                for run in run_list
            ),2),

            "total_net":round(sum(
                run["net_pay"]
                for run in run_list
            ),2),
        }

    def migration_payroll_history_mapping_get(
        self,company_id:int,project_id:int,dataset_id:int,*,cur=None
    )->dict:
        settings=self.migration_payroll_history_settings_get(
            company_id,project_id,dataset_id,cur=cur
        )

        field_mapping=self.migration_field_mapping_dataset(
            company_id,project_id,dataset_id,cur=cur
        )

        mapped={
            row.get("target_field_code")
            for row in field_mapping.get("rows") or []
            if row.get("mapping_status")=="mapped"
        }

        common_required={
            "run_reference",
            "period_start",
            "period_end",
            "employee_no",
        }

        if settings.get("source_layout")=="item_rows":
            required=common_required|{
                "payroll_item_name",
                "payroll_item_type",
                "payroll_item_amount",
            }
        else:
            required=common_required|{
                "gross_pay",
                "net_pay",
            }

        missing_fields=sorted(
            required-mapped
        )

        return {
            "settings":settings,
            "field_mapping":field_mapping,

            "missing_fields":missing_fields,

            "is_complete":
                not missing_fields,
        }

    def _migration_payroll_check(
        self,code:str,label:str,passed:bool,*,
        blocking:bool=True,message:str|None=None,
        value=None,expected=None
    )->dict:
        return {
            "code":code,
            "label":label,
            "passed":bool(passed),
            "blocking":bool(blocking),
            "severity":"ok" if passed else ("error" if blocking else "warning"),
            "message":message,
            "value":value,
            "expected":expected,
        }

    def migration_payroll_tax_readiness(
        self,company_id:int,project_id:int,*,cur=None
    )->dict:
        company_id,project_id=int(company_id),int(project_id)
        schema=self.company_schema(company_id)

        project=self.fetch_one(f"""
            SELECT cutover_date
            FROM {schema}.migration_projects
            WHERE company_id=%s AND id=%s
        """,(company_id,project_id),cur=cur)

        if not project:
            raise ValueError("Migration project not found.")

        cutover_date=project.get("cutover_date")

        payroll_settings=self.fetch_one(f"""
            SELECT *
            FROM {schema}.payroll_settings
            WHERE company_id=%s
            LIMIT 1
        """,(company_id,),cur=cur) or {}

        authority_id=payroll_settings.get("tax_authority_id")

        authority=None

        if authority_id:
            authority=self.fetch_one("""
                SELECT id,code,name,country_code
                FROM public.tax_authorities
                WHERE id=%s
            """,(authority_id,),cur=cur)

        regime=None

        if authority:
            regime=self.fetch_one("""
                SELECT *
                FROM public.payroll_tax_regimes
                WHERE UPPER(authority_code)=UPPER(%s)
                AND is_active=TRUE
                ORDER BY id
                LIMIT 1
            """,(authority.get("code"),),cur=cur)

        tax_year=None

        if regime and cutover_date:
            tax_year=self.fetch_one("""
                SELECT *
                FROM public.payroll_tax_years
                WHERE regime_id=%s
                AND effective_from<=%s
                AND effective_to>=%s
                AND is_active=TRUE
                ORDER BY effective_from DESC
                LIMIT 1
            """,(
                regime["id"],
                cutover_date,
                cutover_date,
            ),cur=cur)

        bracket_count=0

        if tax_year:
            bracket_count=int(self.fetch_val("""
                SELECT COUNT(*)
                FROM public.payroll_tax_brackets
                WHERE tax_year_id=%s
            """,(tax_year["id"],),cur=cur) or 0)

        return {
            "tax_authority":authority,
            "tax_regime":regime,
            "tax_year":tax_year,
            "bracket_count":bracket_count,

            "authority_ready":bool(authority),
            "regime_ready":bool(regime),
            "tax_year_ready":bool(tax_year),
            "brackets_ready":bracket_count>0,

            "is_ready":bool(
                authority
                and regime
                and tax_year
                and bracket_count>0
            ),
        }

    def migration_payroll_employee_reconciliation(
        self,company_id:int,project_id:int,*,cur=None
    )->dict:
        datasets=self.migration_payroll_datasets(
            company_id,project_id,cur=cur
        )

        results=[]
        employee_count=0
        ready_count=0
        total_basic=0.0

        for dataset in datasets:
            dataset_id=int(dataset["dataset_id"])

            try:
                mapping=self.migration_payroll_mapping_get(
                    company_id,project_id,dataset_id,cur=cur
                )

                preview=self.migration_payroll_preview(
                    company_id,project_id,dataset_id,cur=cur
                )

                employees=preview.get("employees") or []

                employee_count+=int(
                    preview.get("employee_count") or 0
                )

                ready_count+=int(
                    preview.get("valid_count") or 0
                )

                total_basic+=float(
                    preview.get("total_monthly_basic_salary") or 0
                )

                results.append({
                    "dataset_id":dataset_id,
                    "dataset_name":dataset.get("dataset_name"),

                    "mapping_complete":
                        bool(mapping.get("is_complete")),

                    "record_count":
                        preview.get("employee_count") or 0,

                    "ready_count":
                        preview.get("valid_count") or 0,

                    "error_count":
                        preview.get("error_count") or 0,

                    "total_basic_salary":
                        preview.get("total_monthly_basic_salary") or 0,

                    "employees":employees,
                })

            except Exception as error:
                results.append({
                    "dataset_id":dataset_id,
                    "dataset_name":dataset.get("dataset_name"),
                    "mapping_complete":False,
                    "record_count":0,
                    "ready_count":0,
                    "error_count":1,
                    "error":str(error),
                })

        return {
            "dataset_count":len(datasets),
            "employee_count":employee_count,
            "ready_count":ready_count,
            "error_count":max(employee_count-ready_count,0),
            "total_basic_salary":round(total_basic,2),
            "datasets":results,
        }

