    def ias41_mapping_validate(
        self,
        company_id: int,
        *,
        cur=None,
    ) -> dict:
        company_id = int(company_id)
        schema = self._ias41_company_guard(
            company_id,
            cur=cur,
        )

        mappings=self.fetch_all(
            f"""
            SELECT
                m.role_code,
                m.account_code,
                m.mapping_scope,
                c.id AS account_id,
                c.name AS account_name,
                COALESCE(c.posting,FALSE) AS posting
            FROM {schema}.ias41_account_mappings m
            LEFT JOIN {schema}.coa c
            ON c.company_id=m.company_id
            AND c.code=m.account_code
            WHERE m.company_id=%s
            AND m.mapping_scope='company'
            AND m.is_active=TRUE
            """,
            (company_id,),
            cur=cur,
        ) or []

        by_role = {
            str(row.get("role_code") or ""): row
            for row in mappings
        }

        required_roles = [
            "ias41_biological_asset_current",
            "ias41_agricultural_produce_inventory",
            "ias41_fair_value_gain",
            "ias41_fair_value_loss",
            "ias41_costs_to_sell",
            "ias41_mortality_loss",
        ]

        missing = []
        invalid = []

        for role_code in required_roles:
            row = by_role.get(role_code)

            if not row:
                missing.append(role_code)
                continue

            if not row.get("account_id") or row.get("posting") is not True:
                invalid.append({
                    "role_code": role_code,
                    "account_code": row.get("account_code"),
                    "reason": "Account is missing, inactive or non-posting.",
                })

        return {
            "ready": not missing and not invalid,
            "required_roles": required_roles,
            "missing_roles": missing,
            "invalid_accounts": invalid,
            "mapped_role_count": len(by_role),
        }

    def _ias41_get_row(
        self,
        company_id: int,
        table_name: str,
        record_id: int,
        *,
        joins_sql: str = "",
        select_sql: str = "t.*",
        cur=None,
    ) -> dict | None:
        company_id = int(company_id)
        schema = self._ias41_company_guard(
            company_id,
            cur=cur,
        )

        row = self.fetch_one(
            f"""
            SELECT {select_sql}
            FROM {schema}.{table_name} t
            {joins_sql}
            WHERE t.company_id = %s
            AND t.id = %s
            LIMIT 1
            """,
            (
                company_id,
                int(record_id),
            ),
            cur=cur,
        )

        return self._ias41_serialise(row)


    def _ias41_soft_delete(
        self,
        company_id: int,
        table_name: str,
        record_id: int,
        *,
        user_id: int | None = None,
        cur=None,
    ) -> bool:
        company_id = int(company_id)
        schema = self._ias41_company_guard(
            company_id,
            cur=cur,
        )

        row = self.fetch_one(
            f"""
            UPDATE {schema}.{table_name}
            SET
                is_active = FALSE,
                updated_at = NOW(),
                updated_by_user_id = %s
            WHERE company_id = %s
            AND id = %s
            RETURNING id
            """,
            (
                user_id,
                company_id,
                int(record_id),
            ),
            cur=cur,
        )

        return bool(row)

    def ias41_locations_list(
        self,
        company_id: int,
        *,
        active_only: bool = True,
        cur=None,
    ) -> list[dict]:
        company_id = int(company_id)
        schema = self._ias41_company_guard(
            company_id,
            cur=cur,
        )

        active_sql = (
            "AND l.is_active = TRUE"
            if active_only
            else ""
        )

        rows = self.fetch_all(
            f"""
            SELECT
                l.*,
                p.location_code AS parent_location_code,
                p.location_name AS parent_location_name
            FROM {schema}.ias41_locations l
            LEFT JOIN {schema}.ias41_locations p
            ON p.company_id = l.company_id
            AND p.id = l.parent_location_id
            WHERE l.company_id = %s
            {active_sql}
            ORDER BY
                l.location_name,
                l.location_code
            """,
            (company_id,),
            cur=cur,
        )

        return self._ias41_serialise_many(rows)


