    def ias41_location_save(
        self,
        company_id: int,
        payload: dict,
        *,
        location_id: int | None = None,
        user_id: int | None = None,
        cur=None,
    ) -> dict:
        company_id = int(company_id)
        schema = self._ias41_company_guard(
            company_id,
            cur=cur,
        )
        payload = payload or {}

        location_code = self._ias41_required_text(
            payload,
            "location_code",
            "Location code",
        )
        location_name = self._ias41_required_text(
            payload,
            "location_name",
            "Location name",
        )

        location_type = str(
            payload.get("location_type")
            or "farm"
        ).strip().lower()

        valid_types = {
            "farm",
            "field",
            "crop_block",
            "orchard",
            "plantation",
            "camp",
            "paddock",
            "barn",
            "stable",
            "poultry_house",
            "greenhouse",
            "nursery",
            "pond",
            "tank",
            "hatchery",
            "apiary",
            "warehouse",
            "other",
        }

        if location_type not in valid_types:
            raise ValueError("Invalid agricultural location type.")

        parent_location_id = self._ias41_optional_int(
            payload.get("parent_location_id")
        )

        if (
            location_id
            and parent_location_id == int(location_id)
        ):
            raise ValueError(
                "A location cannot be its own parent."
            )

        params = (
            location_code,
            location_name,
            location_type,
            parent_location_id,
            str(payload.get("description") or "").strip() or None,
            str(payload.get("address_line_1") or "").strip() or None,
            str(payload.get("address_line_2") or "").strip() or None,
            str(payload.get("city") or "").strip() or None,
            str(payload.get("district") or "").strip() or None,
            str(payload.get("province_state") or "").strip() or None,
            str(payload.get("country_code") or "").strip() or None,
            self._ias41_optional_float(payload.get("latitude")),
            self._ias41_optional_float(payload.get("longitude")),
            self._ias41_optional_float(payload.get("area_value")),
            str(payload.get("area_unit") or "").strip() or None,
            self._ias41_optional_int(
                payload.get("responsible_user_id")
            ),
            self._ias41_bool(payload.get("is_active"), True),
            self._ias41_json_value(payload.get("metadata")),
        )

        if location_id:
            row = self.fetch_one(
                f"""
                UPDATE {schema}.ias41_locations
                SET
                    location_code = %s,
                    location_name = %s,
                    location_type = %s,
                    parent_location_id = %s,
                    description = %s,
                    address_line_1 = %s,
                    address_line_2 = %s,
                    city = %s,
                    district = %s,
                    province_state = %s,
                    country_code = %s,
                    latitude = %s,
                    longitude = %s,
                    area_value = %s,
                    area_unit = %s,
                    responsible_user_id = %s,
                    is_active = %s,
                    metadata = %s::jsonb,
                    updated_at = NOW(),
                    updated_by_user_id = %s
                WHERE company_id = %s
                AND id = %s
                RETURNING *
                """,
                params + (
                    user_id,
                    company_id,
                    int(location_id),
                ),
                cur=cur,
            )
        else:
            row = self.fetch_one(
                f"""
                INSERT INTO {schema}.ias41_locations (
                    company_id,
                    location_code,
                    location_name,
                    location_type,
                    parent_location_id,
                    description,
                    address_line_1,
                    address_line_2,
                    city,
                    district,
                    province_state,
                    country_code,
                    latitude,
                    longitude,
                    area_value,
                    area_unit,
                    responsible_user_id,
                    is_active,
                    metadata,
                    created_at,
                    created_by_user_id,
                    updated_at,
                    updated_by_user_id
                )
                VALUES (
                    %s,
                    %s, %s, %s, %s, %s,
                    %s, %s, %s, %s, %s, %s,
                    %s, %s, %s, %s, %s, %s,
                    %s::jsonb,
                    NOW(), %s, NOW(), %s
                )
                RETURNING *
                """,
                (
                    company_id,
                ) + params + (
                    user_id,
                    user_id,
                ),
                cur=cur,
            )

        if not row:
            raise ValueError("Agricultural location was not saved.")

        return self._ias41_serialise(row) or {}


