    # Acquisitions, births, planting and opening balances
    # ============================================================

    IAS41_ACQUISITION_TYPES = {
        "purchase",
        "birth",
        "planting",
        "donation",
        "transfer_in",
        "opening_balance",
        "other",
    }

    IAS41_ACQUISITION_STATUSES = {
        "draft",
        "approved",
        "posted",
        "reversed",
        "cancelled",
    }

    IAS41_TRACKING_METHODS = {
        "batch",
        "individual",
        "both",
    }


    def _ias41_next_acquisition_number(
        self,
        company_id: int,
        *,
        transaction_date=None,
        cur=None,
    ) -> str:
        company_id = int(company_id)
        schema = self._ias41_company_guard(
            company_id,
            cur=cur,
        )

        date_text = str(
            transaction_date
            or date.today().isoformat()
        )

        year = date_text[:4]
        prefix = f"IAS41-ACQ-{year}-"

        row = self.fetch_one(
            f"""
            SELECT
                COALESCE(
                    MAX(
                        CASE
                            WHEN transaction_number
                                ~ %s
                            THEN SUBSTRING(
                                transaction_number
                                FROM '([0-9]+)$'
                            )::INTEGER
                            ELSE 0
                        END
                    ),
                    0
                ) + 1 AS next_number
            FROM {schema}.ias41_acquisitions
            WHERE company_id = %s
            AND transaction_number LIKE %s
            """,
            (
                f"^{prefix}[0-9]+$",
                company_id,
                f"{prefix}%",
            ),
            cur=cur,
        ) or {}

        next_number = int(
            row.get("next_number")
            or 1
        )

        return f"{prefix}{next_number:05d}"


    def _ias41_acquisition_line_calculate(
        self,
        payload: dict,
    ) -> dict:
        payload = payload or {}

        quantity = float(
            payload.get("quantity")
            or 0
        )

        if quantity <= 0:
            raise ValueError(
                "Acquisition line quantity must be greater than zero."
            )

        fair_value_per_unit = float(
            payload.get("fair_value_per_unit")
            or 0
        )

        gross_fair_value = payload.get(
            "gross_fair_value"
        )

        if gross_fair_value in (None, ""):
            gross_fair_value = (
                quantity
                * fair_value_per_unit
            )

        gross_fair_value = round(
            float(gross_fair_value),
            2,
        )

        costs_to_sell_per_unit = float(
            payload.get("costs_to_sell_per_unit")
            or 0
        )

        costs_to_sell_amount = payload.get(
            "costs_to_sell_amount"
        )

        if costs_to_sell_amount in (None, ""):
            costs_to_sell_amount = (
                quantity
                * costs_to_sell_per_unit
            )

        costs_to_sell_amount = round(
            float(costs_to_sell_amount),
            2,
        )

        carrying_amount = payload.get(
            "carrying_amount"
        )

        if carrying_amount in (None, ""):
            carrying_amount = (
                gross_fair_value
                - costs_to_sell_amount
            )

        carrying_amount = round(
            float(carrying_amount),
            2,
        )

        if carrying_amount < 0:
            raise ValueError(
                "Carrying amount cannot be negative."
            )

        return {
            "quantity": quantity,
            "fair_value_per_unit": fair_value_per_unit,
            "gross_fair_value": gross_fair_value,
            "costs_to_sell_per_unit": costs_to_sell_per_unit,
            "costs_to_sell_amount": costs_to_sell_amount,
            "carrying_amount": carrying_amount,
            "purchase_price": round(
                float(
                    payload.get("purchase_price")
                    or 0
                ),
                2,
            ),
            "direct_cost_amount": round(
                float(
                    payload.get("direct_cost_amount")
                    or 0
                ),
                2,
            ),
        }


    def _ias41_validate_acquisition_reference(
        self,
        company_id: int,
        table_name: str,
        record_id: int | None,
        *,
        label: str,
        cur=None,
    ) -> None:
        if not record_id:
            return

        company_id = int(company_id)
        schema = self.company_schema(company_id)

        row = self.fetch_one(
            f"""
            SELECT id
            FROM {schema}.{table_name}
            WHERE company_id = %s
            AND id = %s
            LIMIT 1
            """,
            (
                company_id,
                int(record_id),
            ),
            cur=cur,
        )

        if not row:
            raise ValueError(
                f"{label} was not found."
            )

    def ias41_acquisitions_list(
        self,
        company_id: int,
        *,
        status: str | None = None,
        transaction_type: str | None = None,
        date_from=None,
        date_to=None,
        cur=None,
    ) -> list[dict]:
        company_id = int(company_id)
        schema = self._ias41_company_guard(
            company_id,
            cur=cur,
        )

        conditions = [
            "a.company_id = %s",
        ]
        params = [
            company_id,
        ]

        if status:
            conditions.append(
                "a.status = %s"
            )
            params.append(
                str(status).strip().lower()
            )

        if transaction_type:
            conditions.append(
                "a.transaction_type = %s"
            )
            params.append(
                str(
                    transaction_type
                ).strip().lower()
            )

        if date_from:
            conditions.append(
                "a.transaction_date >= %s"
            )
            params.append(date_from)

        if date_to:
            conditions.append(
                "a.transaction_date <= %s"
            )
            params.append(date_to)

        rows = self.fetch_all(
            f"""
            SELECT
                a.*,

                (
                    SELECT COUNT(*)
                    FROM {schema}.ias41_acquisition_lines l
                    WHERE l.company_id = a.company_id
                    AND l.acquisition_id = a.id
                ) AS line_count,

                (
                    SELECT COALESCE(
                        SUM(l.quantity),
                        0
                    )
                    FROM {schema}.ias41_acquisition_lines l
                    WHERE l.company_id = a.company_id
                    AND l.acquisition_id = a.id
                ) AS total_quantity,

                (
                    SELECT COALESCE(
                        SUM(l.carrying_amount),
                        0
                    )
                    FROM {schema}.ias41_acquisition_lines l
                    WHERE l.company_id = a.company_id
                    AND l.acquisition_id = a.id
                ) AS line_carrying_amount

            FROM {schema}.ias41_acquisitions a
            WHERE {" AND ".join(conditions)}
            ORDER BY
                a.transaction_date DESC,
                a.id DESC
            """,
            tuple(params),
            cur=cur,
        )

        return self._ias41_serialise_many(rows)


    def ias41_acquisition_get(
        self,
        company_id: int,
        acquisition_id: int,
        *,
        cur=None,
    ) -> dict | None:
        company_id = int(company_id)
        schema = self._ias41_company_guard(
            company_id,
            cur=cur,
        )

        header = self.fetch_one(
            f"""
            SELECT *
            FROM {schema}.ias41_acquisitions
            WHERE company_id = %s
            AND id = %s
            LIMIT 1
            """,
            (
                company_id,
                int(acquisition_id),
            ),
            cur=cur,
        )

        if not header:
            return None

        lines = self.fetch_all(
            f"""
            SELECT
                l.*,
                ac.class_code,
                ac.class_name,
                ac.current_noncurrent,
                p.product_code,
                p.product_name,
                loc.location_code,
                loc.location_name,
                s.season_code,
                s.season_name,
                b.batch_code,
                b.batch_name,
                ba.asset_number,
                ba.asset_name
            FROM {schema}.ias41_acquisition_lines l
            JOIN {schema}.ias41_asset_classes ac
            ON ac.company_id = l.company_id
            AND ac.id = l.asset_class_id
            LEFT JOIN {schema}.ias41_products p
            ON p.company_id = l.company_id
            AND p.id = l.product_id
            LEFT JOIN {schema}.ias41_locations loc
            ON loc.company_id = l.company_id
            AND loc.id = l.location_id
            LEFT JOIN {schema}.ias41_seasons s
            ON s.company_id = l.company_id
            AND s.id = l.season_id
            LEFT JOIN {schema}.ias41_batches b
            ON b.company_id = l.company_id
            AND b.id = l.batch_id
            LEFT JOIN {schema}.ias41_biological_assets ba
            ON ba.company_id = l.company_id
            AND ba.id = l.biological_asset_id
            WHERE l.company_id = %s
            AND l.acquisition_id = %s
            ORDER BY
                l.line_number,
                l.id
            """,
            (
                company_id,
                int(acquisition_id),
            ),
            cur=cur,
        )

        out = self._ias41_serialise(
            header
        ) or {}

        out["lines"] = self._ias41_serialise_many(
            lines
        )

        return out

    def ias41_acquisition_save(
        self,
        company_id: int,
        payload: dict,
        *,
        acquisition_id: int | None = None,
        user_id: int | None = None,
        cur=None,
    ) -> dict:
        company_id = int(company_id)
        schema = self._ias41_company_guard(
            company_id,
            cur=cur,
        )

        payload = payload or {}

        existing = None

        if acquisition_id:
            existing = self.ias41_acquisition_get(
                company_id,
                acquisition_id,
                cur=cur,
            )

            if not existing:
                raise ValueError(
                    "IAS 41 acquisition was not found."
                )

            if existing.get("status") not in {
                "draft",
            }:
                raise ValueError(
                    "Only draft acquisitions can be changed."
                )

        transaction_type = str(
            payload.get("transaction_type")
            or (
                existing.get("transaction_type")
                if existing
                else "purchase"
            )
        ).strip().lower()

        if (
            transaction_type
            not in self.IAS41_ACQUISITION_TYPES
        ):
            raise ValueError(
                "Invalid IAS 41 acquisition transaction type."
            )

        transaction_date = (
            payload.get("transaction_date")
            or (
                existing.get("transaction_date")
                if existing
                else date.today().isoformat()
            )
        )

        recognition_date = (
            payload.get("recognition_date")
            or transaction_date
        )

        transaction_number = str(
            payload.get("transaction_number")
            or (
                existing.get("transaction_number")
                if existing
                else ""
            )
            or self._ias41_next_acquisition_number(
                company_id,
                transaction_date=transaction_date,
                cur=cur,
            )
        ).strip()

        vendor_id = self._ias41_optional_int(
            payload.get("vendor_id")
        )
        bill_id = self._ias41_optional_int(
            payload.get("bill_id")
        )

        source_location_id = self._ias41_optional_int(
            payload.get("source_location_id")
        )
        destination_location_id = (
            self._ias41_optional_int(
                payload.get(
                    "destination_location_id"
                )
            )
        )
        season_id = self._ias41_optional_int(
            payload.get("season_id")
        )

        self._ias41_validate_acquisition_reference(
            company_id,
            "ias41_locations",
            source_location_id,
            label="Source location",
            cur=cur,
        )
        self._ias41_validate_acquisition_reference(
            company_id,
            "ias41_locations",
            destination_location_id,
            label="Destination location",
            cur=cur,
        )
        self._ias41_validate_acquisition_reference(
            company_id,
            "ias41_seasons",
            season_id,
            label="Season",
            cur=cur,
        )

        lines = payload.get("lines") or []

        if not isinstance(lines, list):
            raise ValueError(
                "Acquisition lines must be a list."
            )

        if not lines:
            raise ValueError(
                "At least one acquisition line is required."
            )

        normalized_lines = []

        for index, source_line in enumerate(
            lines,
            start=1,
        ):
            source_line = source_line or {}

            asset_class_id = (
                self._ias41_optional_int(
                    source_line.get(
                        "asset_class_id"
                    )
                )
            )

            if not asset_class_id:
                raise ValueError(
                    f"Asset class is required on line {index}."
                )

            self._ias41_validate_acquisition_reference(
                company_id,
                "ias41_asset_classes",
                asset_class_id,
                label=f"Asset class on line {index}",
                cur=cur,
            )

            product_id = self._ias41_optional_int(
                source_line.get("product_id")
            )

            if product_id:
                self._ias41_validate_acquisition_reference(
                    company_id,
                    "ias41_products",
                    product_id,
                    label=f"Product on line {index}",
                    cur=cur,
                )

            line_location_id = (
                self._ias41_optional_int(
                    source_line.get(
                        "location_id"
                    )
                )
                or destination_location_id
            )

            line_season_id = (
                self._ias41_optional_int(
                    source_line.get(
                        "season_id"
                    )
                )
                or season_id
            )

            tracking_method = str(
                source_line.get(
                    "tracking_method"
                )
                or "batch"
            ).strip().lower()

            if (
                tracking_method
                not in self.IAS41_TRACKING_METHODS
            ):
                raise ValueError(
                    f"Invalid tracking method on line {index}."
                )

            calculated = (
                self._ias41_acquisition_line_calculate(
                    source_line
                )
            )

            biological_account = str(
                source_line.get(
                    "biological_asset_account_code"
                )
                or ""
            ).strip() or None

            fair_value_gain_account = str(
                source_line.get(
                    "fair_value_gain_account_code"
                )
                or ""
            ).strip() or None

            fair_value_loss_account = str(
                source_line.get(
                    "fair_value_loss_account_code"
                )
                or ""
            ).strip() or None

            payable_account = str(
                source_line.get(
                    "payable_account_code"
                )
                or ""
            ).strip() or None

            cash_account = str(
                source_line.get(
                    "cash_account_code"
                )
                or ""
            ).strip() or None

            for account_code in (
                biological_account,
                fair_value_gain_account,
                fair_value_loss_account,
                payable_account,
                cash_account,
            ):
                if account_code:
                    self._ias41_validate_account_code(
                        company_id,
                        account_code,
                        cur=cur,
                    )

            normalized_lines.append({
                **source_line,
                **calculated,
                "line_number": index,
                "asset_class_id": asset_class_id,
                "product_id": product_id,
                "location_id": line_location_id,
                "season_id": line_season_id,
                "tracking_method": tracking_method,
                "biological_asset_account_code":
                    biological_account,
                "fair_value_gain_account_code":
                    fair_value_gain_account,
                "fair_value_loss_account_code":
                    fair_value_loss_account,
                "payable_account_code":
                    payable_account,
                "cash_account_code":
                    cash_account,
            })

        gross_amount = round(
            sum(
                float(
                    line["gross_fair_value"]
                )
                for line in normalized_lines
            ),
            2,
        )

        costs_to_sell_amount = round(
            sum(
                float(
                    line["costs_to_sell_amount"]
                )
                for line in normalized_lines
            ),
            2,
        )

        carrying_amount = round(
            sum(
                float(
                    line["carrying_amount"]
                )
                for line in normalized_lines
            ),
            2,
        )

        header_values = (
            transaction_number,
            transaction_type,
            transaction_date,
            recognition_date,
            vendor_id,
            bill_id,
            self._ias41_optional_int(
                payload.get(
                    "source_company_id"
                )
            ),
            source_location_id,
            destination_location_id,
            season_id,
            str(
                payload.get("currency_code")
                or ""
            ).strip() or None,
            float(
                payload.get("exchange_rate")
                or 1
            ),
            gross_amount,
            costs_to_sell_amount,
            carrying_amount,
            str(
                payload.get("reference")
                or ""
            ).strip() or None,
            str(
                payload.get("description")
                or ""
            ).strip() or None,
            self._ias41_json_value(
                payload.get("metadata")
            ),
        )

        if acquisition_id:
            header = self.fetch_one(
                f"""
                UPDATE {schema}.ias41_acquisitions
                SET
                    transaction_number = %s,
                    transaction_type = %s,
                    transaction_date = %s,
                    recognition_date = %s,
                    vendor_id = %s,
                    bill_id = %s,
                    source_company_id = %s,
                    source_location_id = %s,
                    destination_location_id = %s,
                    season_id = %s,
                    currency_code = %s,
                    exchange_rate = %s,
                    gross_amount = %s,
                    costs_to_sell_amount = %s,
                    carrying_amount = %s,
                    reference = %s,
                    description = %s,
                    metadata = %s::jsonb,
                    updated_at = NOW(),
                    updated_by_user_id = %s
                WHERE company_id = %s
                AND id = %s
                AND status = 'draft'
                RETURNING *
                """,
                header_values + (
                    user_id,
                    company_id,
                    int(acquisition_id),
                ),
                cur=cur,
            )

            if not header:
                raise ValueError(
                    "Draft acquisition could not be updated."
                )

            self.execute_sql(
                f"""
                DELETE FROM {schema}.ias41_acquisition_lines
                WHERE company_id = %s
                AND acquisition_id = %s
                """,
                (
                    company_id,
                    int(acquisition_id),
                ),
                cur=cur,
            )

            acquisition_id = int(
                acquisition_id
            )

        else:
            header = self.fetch_one(
                f"""
                INSERT INTO {schema}.ias41_acquisitions (
                    company_id,
                    transaction_number,
                    transaction_type,
                    transaction_date,
                    recognition_date,
                    vendor_id,
                    bill_id,
                    source_company_id,
                    source_location_id,
                    destination_location_id,
                    season_id,
                    currency_code,
                    exchange_rate,
                    gross_amount,
                    costs_to_sell_amount,
                    carrying_amount,
                    status,
                    reference,
                    description,
                    metadata,
                    created_at,
                    created_by_user_id,
                    updated_at,
                    updated_by_user_id
                )
                VALUES (
                    %s,
                    %s, %s, %s, %s,
                    %s, %s, %s, %s, %s, %s,
                    %s, %s, %s, %s, %s,
                    'draft',
                    %s, %s, %s::jsonb,
                    NOW(), %s, NOW(), %s
                )
                RETURNING *
                """,
                (
                    company_id,
                ) + header_values + (
                    user_id,
                    user_id,
                ),
                cur=cur,
            )

            if not header:
                raise ValueError(
                    "IAS 41 acquisition could not be created."
                )

            acquisition_id = int(
                header["id"]
            )

        for line in normalized_lines:
            self.fetch_one(
                f"""
                INSERT INTO {schema}.ias41_acquisition_lines (
                    company_id,
                    acquisition_id,
                    line_number,
                    asset_class_id,
                    product_id,
                    location_id,
                    season_id,
                    tracking_method,
                    batch_id,
                    biological_asset_id,
                    proposed_batch_code,
                    proposed_batch_name,
                    proposed_asset_number,
                    proposed_asset_name,
                    identification_type,
                    identification_value,
                    biological_sex,
                    birth_or_planting_date,
                    expected_harvest_date,
                    maturity_date,
                    quantity,
                    quantity_unit,
                    weight,
                    weight_unit,
                    fair_value_per_unit,
                    gross_fair_value,
                    costs_to_sell_per_unit,
                    costs_to_sell_amount,
                    carrying_amount,
                    purchase_price,
                    direct_cost_amount,
                    biological_asset_account_code,
                    fair_value_gain_account_code,
                    fair_value_loss_account_code,
                    payable_account_code,
                    cash_account_code,
                    description,
                    metadata,
                    created_at,
                    created_by_user_id,
                    updated_at,
                    updated_by_user_id
                )
                VALUES (
                    %s, %s, %s,
                    %s, %s, %s, %s, %s,
                    %s, %s,
                    %s, %s, %s, %s,
                    %s, %s, %s,
                    %s, %s, %s,
                    %s, %s, %s, %s,
                    %s, %s, %s, %s, %s,
                    %s, %s,
                    %s, %s, %s, %s, %s,
                    %s, %s::jsonb,
                    NOW(), %s, NOW(), %s
                )
                RETURNING id
                """,
                (
                    company_id,
                    acquisition_id,
                    int(line["line_number"]),
                    int(line["asset_class_id"]),
                    line.get("product_id"),
                    line.get("location_id"),
                    line.get("season_id"),
                    line["tracking_method"],
                    self._ias41_optional_int(
                        line.get("batch_id")
                    ),
                    self._ias41_optional_int(
                        line.get(
                            "biological_asset_id"
                        )
                    ),
                    str(
                        line.get(
                            "proposed_batch_code"
                        )
                        or ""
                    ).strip() or None,
                    str(
                        line.get(
                            "proposed_batch_name"
                        )
                        or ""
                    ).strip() or None,
                    str(
                        line.get(
                            "proposed_asset_number"
                        )
                        or ""
                    ).strip() or None,
                    str(
                        line.get(
                            "proposed_asset_name"
                        )
                        or ""
                    ).strip() or None,
                    str(
                        line.get(
                            "identification_type"
                        )
                        or ""
                    ).strip() or None,
                    str(
                        line.get(
                            "identification_value"
                        )
                        or ""
                    ).strip() or None,
                    str(
                        line.get("biological_sex")
                        or ""
                    ).strip().lower() or None,
                    line.get(
                        "birth_or_planting_date"
                    ) or None,
                    line.get(
                        "expected_harvest_date"
                    ) or None,
                    line.get("maturity_date") or None,
                    line["quantity"],
                    str(
                        line.get("quantity_unit")
                        or ""
                    ).strip() or None,
                    self._ias41_optional_float(
                        line.get("weight")
                    ),
                    str(
                        line.get("weight_unit")
                        or ""
                    ).strip() or None,
                    line["fair_value_per_unit"],
                    line["gross_fair_value"],
                    line[
                        "costs_to_sell_per_unit"
                    ],
                    line[
                        "costs_to_sell_amount"
                    ],
                    line["carrying_amount"],
                    line["purchase_price"],
                    line["direct_cost_amount"],
                    line.get(
                        "biological_asset_account_code"
                    ),
                    line.get(
                        "fair_value_gain_account_code"
                    ),
                    line.get(
                        "fair_value_loss_account_code"
                    ),
                    line.get(
                        "payable_account_code"
                    ),
                    line.get(
                        "cash_account_code"
                    ),
                    str(
                        line.get("description")
                        or ""
                    ).strip() or None,
                    self._ias41_json_value(
                        line.get("metadata")
                    ),
                    user_id,
                    user_id,
                ),
                cur=cur,
            )

        self.execute_sql(
            f"""
            DELETE FROM {schema}.ias41_acquisition_journal_previews
            WHERE company_id = %s
            AND acquisition_id = %s
            """,
            (
                company_id,
                acquisition_id,
            ),
            cur=cur,
        )

        return (
            self.ias41_acquisition_get(
                company_id,
                acquisition_id,
                cur=cur,
            )
            or {}
        )

    def ias41_acquisition_delete(
        self,
        company_id: int,
        acquisition_id: int,
        *,
        cur=None,
    ) -> bool:
        company_id = int(company_id)
        schema = self._ias41_company_guard(
            company_id,
            cur=cur,
        )

        row = self.fetch_one(
            f"""
            DELETE FROM {schema}.ias41_acquisitions
            WHERE company_id = %s
            AND id = %s
            AND status = 'draft'
            RETURNING id
            """,
            (
                company_id,
                int(acquisition_id),
            ),
            cur=cur,
        )

        return bool(row)


    def ias41_acquisition_cancel(
        self,
        company_id: int,
        acquisition_id: int,
        *,
        user_id: int | None = None,
        cur=None,
    ) -> dict:
        company_id = int(company_id)
        schema = self._ias41_company_guard(
            company_id,
            cur=cur,
        )

        row = self.fetch_one(
            f"""
            UPDATE {schema}.ias41_acquisitions
            SET
                status = 'cancelled',
                updated_at = NOW(),
                updated_by_user_id = %s
            WHERE company_id = %s
            AND id = %s
            AND status IN (
                'draft',
                'approved'
            )
            RETURNING *
            """,
            (
                user_id,
                company_id,
                int(acquisition_id),
            ),
            cur=cur,
        )

        if not row:
            raise ValueError(
                "Only draft or approved acquisitions can be cancelled."
            )

        return self._ias41_serialise(
            row
        ) or {}


    def ias41_acquisition_return_to_draft(
        self,
        company_id: int,
        acquisition_id: int,
        *,
        user_id: int | None = None,
        cur=None,
    ) -> dict:
        company_id = int(company_id)
        schema = self._ias41_company_guard(
            company_id,
            cur=cur,
        )

        row = self.fetch_one(
            f"""
            UPDATE {schema}.ias41_acquisitions
            SET
                status = 'draft',
                approved_at = NULL,
                approved_by_user_id = NULL,
                updated_at = NOW(),
                updated_by_user_id = %s
            WHERE company_id = %s
            AND id = %s
            AND status = 'approved'
            AND journal_id IS NULL
            RETURNING *
            """,
            (
                user_id,
                company_id,
                int(acquisition_id),
            ),
            cur=cur,
        )

        if not row:
            raise ValueError(
                "Only unposted approved acquisitions can be returned to draft."
            )

        return self._ias41_serialise(
            row
        ) or {}

    def ias41_resolve_account(
        self,
        company_id: int,
        role_code: str,
        *,
        asset_class_id: int | None = None,
        product_id: int | None = None,
        override_code: str | None = None,
        cur=None,
    ) -> dict | None:
        company_id = int(company_id)
        schema = self._ias41_company_guard(
            company_id,
            cur=cur,
        )

        override_code = str(
            override_code
            or ""
        ).strip() or None

        if override_code:
            account = self._ias41_find_company_account(
                company_id,
                override_code,
                cur=cur,
            )

            if account:
                account["resolution_source"] = (
                    "transaction_override"
                )
                return account

        role_to_class_column = {
            "ias41_biological_asset_current":
                "biological_asset_account_code",

            "ias41_biological_asset_noncurrent":
                "biological_asset_account_code",

            "ias41_agricultural_produce_inventory":
                "produce_inventory_account_code",

            "ias41_fair_value_gain":
                "fair_value_gain_account_code",

            "ias41_fair_value_loss":
                "fair_value_loss_account_code",

            "ias41_costs_to_sell":
                "costs_to_sell_account_code",

            "ias41_mortality_loss":
                "mortality_loss_account_code",

            "ias41_government_grant_receivable":
                "grant_receivable_account_code",

            "ias41_government_grant_income":
                "grant_income_account_code",
        }

        class_column = role_to_class_column.get(
            role_code
        )

        if asset_class_id and class_column:
            row = self.fetch_one(
                f"""
                SELECT {class_column} AS account_code
                FROM {schema}.ias41_asset_classes
                WHERE company_id = %s
                AND id = %s
                LIMIT 1
                """,
                (
                    company_id,
                    int(asset_class_id),
                ),
                cur=cur,
            ) or {}

            class_code = str(
                row.get("account_code")
                or ""
            ).strip()

            if class_code:
                account = (
                    self._ias41_find_company_account(
                        company_id,
                        class_code,
                        cur=cur,
                    )
                )

                if account:
                    account[
                        "resolution_source"
                    ] = "asset_class"
                    return account

        mapping_conditions = [
            "m.company_id = %s",
            "m.role_code = %s",
            "m.is_active = TRUE",
        ]
        mapping_params = [
            company_id,
            role_code,
        ]

        if product_id:
            mapping_conditions.append(
                """
                (
                    (
                        m.mapping_scope = 'product'
                        AND m.product_id = %s
                    )
                    OR m.mapping_scope = 'company'
                )
                """
            )
            mapping_params.append(
                int(product_id)
            )

            order_sql = """
                CASE
                    WHEN m.mapping_scope = 'product'
                        THEN 1
                    ELSE 2
                END
            """

        elif asset_class_id:
            mapping_conditions.append(
                """
                (
                    (
                        m.mapping_scope = 'asset_class'
                        AND m.asset_class_id = %s
                    )
                    OR m.mapping_scope = 'company'
                )
                """
            )
            mapping_params.append(
                int(asset_class_id)
            )

            order_sql = """
                CASE
                    WHEN m.mapping_scope = 'asset_class'
                        THEN 1
                    ELSE 2
                END
            """

        else:
            mapping_conditions.append(
                "m.mapping_scope = 'company'"
            )
            order_sql = "m.id"

        mapping = self.fetch_one(
            f"""
            SELECT
                m.account_code,
                m.mapping_scope,
                c.*
            FROM {schema}.ias41_account_mappings m
            JOIN {schema}.coa c
            ON c.company_id = m.company_id
            AND c.code = m.account_code
            WHERE {" AND ".join(mapping_conditions)}
            AND COALESCE(c.posting, TRUE) = TRUE
            AND COALESCE(c.is_active, TRUE) = TRUE
            ORDER BY {order_sql}
            LIMIT 1
            """,
            tuple(mapping_params),
            cur=cur,
        )

        if mapping:
            account = self._ias41_serialise(
                mapping
            ) or {}

            account["resolution_source"] = (
                f"mapping_{account.get('mapping_scope')}"
            )
            return account

        account = self.fetch_one(
            f"""
            SELECT *
            FROM {schema}.coa
            WHERE company_id = %s
            AND role = %s
            AND COALESCE(posting, TRUE) = TRUE
            AND COALESCE(is_active, TRUE) = TRUE
            ORDER BY id
            LIMIT 1
            """,
            (
                company_id,
                role_code,
            ),
            cur=cur,
        )

        if account:
            out = self._ias41_serialise(
                account
            ) or {}

            out["resolution_source"] = (
                "company_coa_role"
            )
            return out

        return None

    def ias41_acquisition_journal_preview(
        self,
        company_id: int,
        acquisition_id: int,
        *,
        user_id: int | None = None,
        save_preview: bool = True,
        cur=None,
    ) -> dict:
        company_id = int(company_id)
        schema = self._ias41_company_guard(
            company_id,
            cur=cur,
        )

        acquisition = self.ias41_acquisition_get(
            company_id,
            acquisition_id,
            cur=cur,
        )

        if not acquisition:
            raise ValueError(
                "IAS 41 acquisition was not found."
            )

        if acquisition.get("status") in {
            "posted",
            "reversed",
            "cancelled",
        }:
            raise ValueError(
                "Journal preview is unavailable for this acquisition status."
            )

        lines = acquisition.get("lines") or []

        if not lines:
            raise ValueError(
                "The acquisition has no lines."
            )

        missing_mappings = []
        invalid_accounts = []
        journal_lines = []

        def add_line(
            account: dict,
            *,
            description: str,
            debit: float = 0,
            credit: float = 0,
            role_code: str,
            source_line_id: int | None = None,
        ) -> None:
            journal_lines.append({
                "role_code": role_code,
                "account_code": account.get("code"),
                "account_name": account.get("name"),
                "description": description,
                "debit": round(float(debit), 2),
                "credit": round(float(credit), 2),
                "resolution_source":
                    account.get("resolution_source"),
                "source_line_id": source_line_id,
            })

        transaction_type = acquisition.get(
            "transaction_type"
        )

        for line in lines:
            description = (
                line.get("description")
                or line.get("class_name")
                or acquisition.get(
                    "transaction_number"
                )
            )

            class_role = (
                "ias41_biological_asset_noncurrent"
                if str(
                    line.get(
                        "current_noncurrent"
                    )
                    or ""
                ).lower() == "noncurrent"
                else "ias41_biological_asset_current"
            )

            biological_account = (
                self.ias41_resolve_account(
                    company_id,
                    class_role,
                    asset_class_id=line.get(
                        "asset_class_id"
                    ),
                    product_id=line.get(
                        "product_id"
                    ),
                    override_code=line.get(
                        "biological_asset_account_code"
                    ),
                    cur=cur,
                )
            )

            if not biological_account:
                missing_mappings.append({
                    "line_id": line.get("id"),
                    "role_code": class_role,
                    "description": description,
                })
                continue

            carrying_amount = round(
                float(
                    line.get("carrying_amount")
                    or 0
                ),
                2,
            )

            if carrying_amount <= 0:
                invalid_accounts.append({
                    "line_id": line.get("id"),
                    "reason":
                        "Carrying amount must be greater than zero.",
                })
                continue

            add_line(
                biological_account,
                description=description,
                debit=carrying_amount,
                role_code=class_role,
                source_line_id=line.get("id"),
            )

            if transaction_type == "purchase":
                purchase_total = round(
                    float(
                        line.get("purchase_price")
                        or 0
                    )
                    + float(
                        line.get(
                            "direct_cost_amount"
                        )
                        or 0
                    ),
                    2,
                )

                settlement_account = None

                if line.get(
                    "payable_account_code"
                ):
                    settlement_account = (
                        self._ias41_find_company_account(
                            company_id,
                            line.get(
                                "payable_account_code"
                            ),
                            cur=cur,
                        )
                    )

                if not settlement_account:
                    settlement_account = (
                        self.ias41_resolve_account(
                            company_id,
                            "ap",
                            override_code=line.get(
                                "payable_account_code"
                            ),
                            cur=cur,
                        )
                    )

                if not settlement_account:
                    settlement_account = (
                        self.ias41_resolve_account(
                            company_id,
                            "cash_bank",
                            override_code=line.get(
                                "cash_account_code"
                            ),
                            cur=cur,
                        )
                    )

                if not settlement_account:
                    missing_mappings.append({
                        "line_id": line.get("id"),
                        "role_code": "ap_or_cash_bank",
                        "description": description,
                    })
                    continue

                settlement_account[
                    "resolution_source"
                ] = (
                    settlement_account.get(
                        "resolution_source"
                    )
                    or "transaction_settlement"
                )

                add_line(
                    settlement_account,
                    description=description,
                    credit=purchase_total,
                    role_code="ap_or_cash_bank",
                    source_line_id=line.get("id"),
                )

                difference = round(
                    carrying_amount
                    - purchase_total,
                    2,
                )

                if difference > 0:
                    gain_account = (
                        self.ias41_resolve_account(
                            company_id,
                            "ias41_fair_value_gain",
                            asset_class_id=line.get(
                                "asset_class_id"
                            ),
                            override_code=line.get(
                                "fair_value_gain_account_code"
                            ),
                            cur=cur,
                        )
                    )

                    if not gain_account:
                        missing_mappings.append({
                            "line_id": line.get("id"),
                            "role_code":
                                "ias41_fair_value_gain",
                            "description": description,
                        })
                    else:
                        add_line(
                            gain_account,
                            description=description,
                            credit=difference,
                            role_code=
                                "ias41_fair_value_gain",
                            source_line_id=line.get("id"),
                        )

                elif difference < 0:
                    loss_account = (
                        self.ias41_resolve_account(
                            company_id,
                            "ias41_fair_value_loss",
                            asset_class_id=line.get(
                                "asset_class_id"
                            ),
                            override_code=line.get(
                                "fair_value_loss_account_code"
                            ),
                            cur=cur,
                        )
                    )

                    if not loss_account:
                        missing_mappings.append({
                            "line_id": line.get("id"),
                            "role_code":
                                "ias41_fair_value_loss",
                            "description": description,
                        })
                    else:
                        add_line(
                            loss_account,
                            description=description,
                            debit=abs(difference),
                            role_code=
                                "ias41_fair_value_loss",
                            source_line_id=line.get("id"),
                        )

            else:
                gain_account = (
                    self.ias41_resolve_account(
                        company_id,
                        "ias41_fair_value_gain",
                        asset_class_id=line.get(
                            "asset_class_id"
                        ),
                        override_code=line.get(
                            "fair_value_gain_account_code"
                        ),
                        cur=cur,
                    )
                )

                if not gain_account:
                    missing_mappings.append({
                        "line_id": line.get("id"),
                        "role_code":
                            "ias41_fair_value_gain",
                        "description": description,
                    })
                else:
                    add_line(
                        gain_account,
                        description=description,
                        credit=carrying_amount,
                        role_code=
                            "ias41_fair_value_gain",
                        source_line_id=line.get("id"),
                    )

        total_debit = round(
            sum(
                float(row.get("debit") or 0)
                for row in journal_lines
            ),
            2,
        )
        total_credit = round(
            sum(
                float(row.get("credit") or 0)
                for row in journal_lines
            ),
            2,
        )

        balanced = (
            abs(
                total_debit
                - total_credit
            )
            < 0.01
        )

        ready_to_post = bool(
            journal_lines
            and not missing_mappings
            and not invalid_accounts
            and balanced
        )

        preview = {
            "company_id": company_id,
            "acquisition_id": int(
                acquisition_id
            ),
            "transaction_number":
                acquisition.get(
                    "transaction_number"
                ),
            "transaction_type":
                transaction_type,
            "transaction_date":
                acquisition.get(
                    "recognition_date"
                ),
            "description": (
                acquisition.get("description")
                or (
                    "IAS 41 "
                    + str(transaction_type).replace(
                        "_",
                        " ",
                    )
                )
            ),
            "ready_to_post": ready_to_post,
            "missing_mappings":
                missing_mappings,
            "invalid_accounts":
                invalid_accounts,
            "journal_lines":
                journal_lines,
            "total_debit": total_debit,
            "total_credit": total_credit,
            "balanced": balanced,
        }

        if save_preview:
            version_row = self.fetch_one(
                f"""
                SELECT
                    COALESCE(
                        MAX(preview_version),
                        0
                    ) + 1 AS next_version
                FROM {schema}.ias41_acquisition_journal_previews
                WHERE company_id = %s
                AND acquisition_id = %s
                """,
                (
                    company_id,
                    int(acquisition_id),
                ),
                cur=cur,
            ) or {}

            preview_version = int(
                version_row.get("next_version")
                or 1
            )

            saved = self.fetch_one(
                f"""
                INSERT INTO {schema}.ias41_acquisition_journal_previews (
                    company_id,
                    acquisition_id,
                    preview_version,
                    transaction_date,
                    description,
                    ready_to_post,
                    total_debit,
                    total_credit,
                    missing_mappings,
                    invalid_accounts,
                    journal_lines,
                    generated_at,
                    generated_by_user_id
                )
                VALUES (
                    %s, %s, %s,
                    %s, %s, %s, %s, %s,
                    %s::jsonb,
                    %s::jsonb,
                    %s::jsonb,
                    NOW(), %s
                )
                RETURNING id
                """,
                (
                    company_id,
                    int(acquisition_id),
                    preview_version,
                    acquisition.get(
                        "recognition_date"
                    ),
                    preview["description"],
                    ready_to_post,
                    total_debit,
                    total_credit,
                    self._ias41_json_value(
                        missing_mappings
                    ),
                    self._ias41_json_value(
                        invalid_accounts
                    ),
                    self._ias41_json_value(
                        journal_lines
                    ),
                    user_id,
                ),
                cur=cur,
            ) or {}

            preview["preview_id"] = (
                saved.get("id")
            )
            preview["preview_version"] = (
                preview_version
            )

        return preview

    def ias41_acquisition_approve(
        self,
        company_id: int,
        acquisition_id: int,
        *,
        user_id: int | None = None,
        cur=None,
    ) -> dict:
        company_id = int(company_id)
        schema = self._ias41_company_guard(
            company_id,
            cur=cur,
        )

        acquisition = (
            self.ias41_acquisition_get(
                company_id,
                acquisition_id,
                cur=cur,
            )
        )

        if not acquisition:
            raise ValueError(
                "IAS 41 acquisition was not found."
            )

        if acquisition.get("status") != "draft":
            raise ValueError(
                "Only draft acquisitions can be approved."
            )

        preview = (
            self.ias41_acquisition_journal_preview(
                company_id,
                acquisition_id,
                user_id=user_id,
                save_preview=True,
                cur=cur,
            )
        )

        if not preview.get("ready_to_post"):
            raise ValueError(
                "The acquisition cannot be approved because its journal preview is incomplete."
            )

        row = self.fetch_one(
            f"""
            UPDATE {schema}.ias41_acquisitions
            SET
                status = 'approved',
                approved_at = NOW(),
                approved_by_user_id = %s,
                updated_at = NOW(),
                updated_by_user_id = %s
            WHERE company_id = %s
            AND id = %s
            AND status = 'draft'
            RETURNING *
            """,
            (
                user_id,
                user_id,
                company_id,
                int(acquisition_id),
            ),
            cur=cur,
        )

        if not row:
            raise ValueError(
                "IAS 41 acquisition approval failed."
            )

        return {
            "acquisition":
                self._ias41_serialise(row),
            "preview": preview,
        }

    def _ias41_next_batch_code(
        self,
        company_id: int,
        *,
        transaction_date=None,
        cur=None,
    ) -> str:
        company_id = int(company_id)
        schema = self.company_schema(
            company_id
        )

        year = str(
            transaction_date
            or date.today().isoformat()
        )[:4]

        prefix = f"IAS41-BATCH-{year}-"

        row = self.fetch_one(
            f"""
            SELECT
                COALESCE(
                    MAX(
                        CASE
                            WHEN batch_code ~ %s
                            THEN SUBSTRING(
                                batch_code
                                FROM '([0-9]+)$'
                            )::INTEGER
                            ELSE 0
                        END
                    ),
                    0
                ) + 1 AS next_number
            FROM {schema}.ias41_batches
            WHERE company_id = %s
            AND batch_code LIKE %s
            """,
            (
                f"^{prefix}[0-9]+$",
                company_id,
                f"{prefix}%",
            ),
            cur=cur,
        ) or {}

        return (
            f"{prefix}"
            f"{int(row.get('next_number') or 1):05d}"
        )


    def _ias41_next_asset_number(
        self,
        company_id: int,
        *,
        transaction_date=None,
        cur=None,
    ) -> str:
        company_id = int(company_id)
        schema = self.company_schema(
            company_id
        )

        year = str(
            transaction_date
            or date.today().isoformat()
        )[:4]

        prefix = f"IAS41-ASSET-{year}-"

        row = self.fetch_one(
            f"""
            SELECT
                COALESCE(
                    MAX(
                        CASE
                            WHEN asset_number ~ %s
                            THEN SUBSTRING(
                                asset_number
                                FROM '([0-9]+)$'
                            )::INTEGER
                            ELSE 0
                        END
                    ),
                    0
                ) + 1 AS next_number
            FROM {schema}.ias41_biological_assets
            WHERE company_id = %s
            AND asset_number LIKE %s
            """,
            (
                f"^{prefix}[0-9]+$",
                company_id,
                f"{prefix}%",
            ),
            cur=cur,
        ) or {}

        return (
            f"{prefix}"
            f"{int(row.get('next_number') or 1):05d}"
        )

    def _ias41_create_journal_from_preview(
        self,
        company_id: int,
        acquisition: dict,
        preview: dict,
        *,
        cur=None,
    ) -> int:
        company_id = int(company_id)
        schema = self.company_schema(
            company_id
        )

        if not preview.get(
            "ready_to_post"
        ):
            raise ValueError(
                "The IAS 41 journal preview is not ready to post."
            )

        journal = self.fetch_one(
            f"""
            INSERT INTO {schema}.journals (
                company_id,
                date,
                ref,
                description,
                gross_amount,
                net_amount,
                vat_amount,
                is_reversal,
                reversal_of_journal_id,
                reversed_by_journal_id,
                source,
                source_id,
                created_at,
                currency
            )
            VALUES (
                %s,
                %s,
                %s,
                %s,
                %s,
                %s,
                0,
                FALSE,
                NULL,
                NULL,
                'ias41_acquisition',
                %s,
                NOW(),
                %s
            )
            RETURNING id
            """,
            (
                company_id,
                acquisition.get(
                    "recognition_date"
                ),
                acquisition.get(
                    "transaction_number"
                ),
                preview.get(
                    "description"
                ),
                preview.get(
                    "total_debit"
                ),
                preview.get(
                    "total_debit"
                ),
                int(acquisition["id"]),
                acquisition.get(
                    "currency_code"
                ),
            ),
            cur=cur,
        )

        if not journal:
            raise ValueError(
                "IAS 41 journal could not be created."
            )

        journal_id = int(
            journal["id"]
        )

        for line_number, line in enumerate(
            preview.get(
                "journal_lines"
            ) or [],
            start=1,
        ):
            self.execute_sql(
                f"""
                INSERT INTO {schema}.journal_lines (
                    company_id,
                    journal_id,
                    line_no,
                    account_code,
                    description,
                    debit,
                    credit,
                    source,
                    source_id,
                    created_at
                )
                VALUES (
                    %s,
                    %s,
                    %s,
                    %s,
                    %s,
                    %s,
                    %s,
                    'ias41_acquisition',
                    %s,
                    NOW()
                )
                """,
                (
                    company_id,
                    journal_id,
                    line_number,
                    line.get(
                        "account_code"
                    ),
                    line.get(
                        "description"
                    ),
                    float(
                        line.get(
                            "debit"
                        )
                        or 0
                    ),
                    float(
                        line.get(
                            "credit"
                        )
                        or 0
                    ),
                    int(
                        acquisition["id"]
                    ),
                ),
                cur=cur,
            )

        return journal_id

    def _ias41_create_batch_from_acquisition_line(
        self,
        company_id: int,
        acquisition: dict,
        line: dict,
        journal_id: int,
        *,
        user_id: int | None = None,
        cur=None,
    ) -> int:
        company_id = int(company_id)
        schema = self.company_schema(
            company_id
        )

        batch_code = str(
            line.get(
                "proposed_batch_code"
            )
            or ""
        ).strip()

        if not batch_code:
            batch_code = (
                self._ias41_next_batch_code(
                    company_id,
                    transaction_date=(
                        acquisition.get(
                            "transaction_date"
                        )
                    ),
                    cur=cur,
                )
            )

        batch_name = str(
            line.get(
                "proposed_batch_name"
            )
            or line.get(
                "class_name"
            )
            or batch_code
        ).strip()

        type_by_nature = {
            "animal": "herd",
            "plant": "crop_block",
            "aquatic": "aquaculture_stock",
            "insect": "colony",
            "wildlife":
                "wildlife_population",
        }

        batch_type = type_by_nature.get(
            str(
                line.get(
                    "asset_nature"
                )
                or ""
            ).lower(),
            "population",
        )

        row = self.fetch_one(
            f"""
            INSERT INTO {schema}.ias41_batches (
                company_id,
                batch_code,
                batch_name,
                asset_class_id,
                location_id,
                season_id,
                batch_type,
                start_date,
                expected_harvest_date,
                opening_quantity,
                current_quantity,
                quantity_unit,
                opening_weight,
                current_weight,
                weight_unit,
                opening_fair_value,
                opening_costs_to_sell,
                opening_carrying_amount,
                current_fair_value,
                current_costs_to_sell,
                current_carrying_amount,
                opening_journal_id,
                status,
                source_type,
                source_reference,
                description,
                metadata,
                is_active,
                created_at,
                created_by_user_id,
                updated_at,
                updated_by_user_id
            )
            VALUES (
                %s,
                %s,
                %s,
                %s,
                %s,
                %s,
                %s,
                %s,
                %s,
                %s,
                %s,
                %s,
                %s,
                %s,
                %s,
                %s,
                %s,
                %s,
                %s,
                %s,
                %s,
                %s,
                'active',
                'ias41_acquisition',
                %s,
                %s,
                %s::jsonb,
                TRUE,
                NOW(),
                %s,
                NOW(),
                %s
            )
            RETURNING id
            """,
            (
                company_id,
                batch_code,
                batch_name,
                int(
                    line[
                        "asset_class_id"
                    ]
                ),
                line.get(
                    "location_id"
                ),
                line.get(
                    "season_id"
                ),
                batch_type,
                line.get(
                    "birth_or_planting_date"
                )
                or acquisition.get(
                    "transaction_date"
                ),
                line.get(
                    "expected_harvest_date"
                ),
                float(
                    line.get(
                        "quantity"
                    )
                    or 0
                ),
                float(
                    line.get(
                        "quantity"
                    )
                    or 0
                ),
                line.get(
                    "quantity_unit"
                ),
                line.get(
                    "weight"
                ),
                line.get(
                    "weight"
                ),
                line.get(
                    "weight_unit"
                ),
                float(
                    line.get(
                        "gross_fair_value"
                    )
                    or 0
                ),
                float(
                    line.get(
                        "costs_to_sell_amount"
                    )
                    or 0
                ),
                float(
                    line.get(
                        "carrying_amount"
                    )
                    or 0
                ),
                float(
                    line.get(
                        "gross_fair_value"
                    )
                    or 0
                ),
                float(
                    line.get(
                        "costs_to_sell_amount"
                    )
                    or 0
                ),
                float(
                    line.get(
                        "carrying_amount"
                    )
                    or 0
                ),
                int(journal_id),
                acquisition.get(
                    "transaction_number"
                ),
                line.get(
                    "description"
                ),
                self._ias41_json_value({
                    "acquisition_id":
                        acquisition.get(
                            "id"
                        ),
                    "acquisition_line_id":
                        line.get("id"),
                }),
                user_id,
                user_id,
            ),
            cur=cur,
        )

        if not row:
            raise ValueError(
                "Biological asset batch could not be created."
            )

        return int(row["id"])

    def _ias41_create_asset_from_acquisition_line(
        self,
        company_id: int,
        acquisition: dict,
        line: dict,
        journal_id: int,
        *,
        batch_id: int | None = None,
        user_id: int | None = None,
        cur=None,
    ) -> int:
        company_id = int(company_id)
        schema = self.company_schema(
            company_id
        )

        quantity = float(
            line.get("quantity")
            or 0
        )

        if quantity != 1:
            raise ValueError(
                "Individual tracking currently requires a quantity of exactly 1 per acquisition line."
            )

        asset_number = str(
            line.get(
                "proposed_asset_number"
            )
            or ""
        ).strip()

        if not asset_number:
            asset_number = (
                self._ias41_next_asset_number(
                    company_id,
                    transaction_date=(
                        acquisition.get(
                            "transaction_date"
                        )
                    ),
                    cur=cur,
                )
            )

        asset_name = str(
            line.get(
                "proposed_asset_name"
            )
            or line.get(
                "class_name"
            )
            or asset_number
        ).strip()

        row = self.fetch_one(
            f"""
            INSERT INTO {schema}.ias41_biological_assets (
                company_id,
                asset_number,
                asset_name,
                asset_class_id,
                batch_id,
                location_id,
                identification_type,
                identification_value,
                biological_sex,
                birth_or_planting_date,
                acquisition_date,
                maturity_date,
                expected_harvest_date,
                quantity,
                quantity_unit,
                current_weight,
                weight_unit,
                status,
                ownership_status,
                source_type,
                source_reference,
                opening_journal_id,
                initial_fair_value,
                initial_costs_to_sell,
                initial_carrying_amount,
                current_fair_value,
                current_costs_to_sell,
                current_carrying_amount,
                description,
                metadata,
                is_active,
                created_at,
                created_by_user_id,
                updated_at,
                updated_by_user_id
            )
            VALUES (
                %s,
                %s,
                %s,
                %s,
                %s,
                %s,
                %s,
                %s,
                %s,
                %s,
                %s,
                %s,
                %s,
                1,
                %s,
                %s,
                %s,
                'active',
                'owned',
                'ias41_acquisition',
                %s,
                %s,
                %s,
                %s,
                %s,
                %s,
                %s,
                %s,
                %s,
                %s::jsonb,
                TRUE,
                NOW(),
                %s,
                NOW(),
                %s
            )
            RETURNING id
            """,
            (
                company_id,
                asset_number,
                asset_name,
                int(
                    line[
                        "asset_class_id"
                    ]
                ),
                batch_id,
                line.get(
                    "location_id"
                ),
                line.get(
                    "identification_type"
                ),
                line.get(
                    "identification_value"
                ),
                line.get(
                    "biological_sex"
                ),
                line.get(
                    "birth_or_planting_date"
                ),
                acquisition.get(
                    "transaction_date"
                ),
                line.get(
                    "maturity_date"
                ),
                line.get(
                    "expected_harvest_date"
                ),
                line.get(
                    "quantity_unit"
                ),
                line.get(
                    "weight"
                ),
                line.get(
                    "weight_unit"
                ),
                acquisition.get(
                    "transaction_number"
                ),
                int(journal_id),
                float(
                    line.get(
                        "gross_fair_value"
                    )
                    or 0
                ),
                float(
                    line.get(
                        "costs_to_sell_amount"
                    )
                    or 0
                ),
                float(
                    line.get(
                        "carrying_amount"
                    )
                    or 0
                ),
                float(
                    line.get(
                        "gross_fair_value"
                    )
                    or 0
                ),
                float(
                    line.get(
                        "costs_to_sell_amount"
                    )
                    or 0
                ),
                float(
                    line.get(
                        "carrying_amount"
                    )
                    or 0
                ),
                line.get(
                    "description"
                ),
                self._ias41_json_value({
                    "acquisition_id":
                        acquisition.get(
                            "id"
                        ),
                    "acquisition_line_id":
                        line.get("id"),
                }),
                user_id,
                user_id,
            ),
            cur=cur,
        )

        if not row:
            raise ValueError(
                "Individual biological asset could not be created."
            )

        return int(row["id"])

    def ias41_acquisition_post(
        self,
        company_id: int,
        acquisition_id: int,
        *,
        user_id: int | None = None,
        cur=None,
    ) -> dict:
        company_id = int(company_id)
        schema = self._ias41_company_guard(
            company_id,
            cur=cur,
        )

        acquisition = (
            self.ias41_acquisition_get(
                company_id,
                acquisition_id,
                cur=cur,
            )
        )

        if not acquisition:
            raise ValueError(
                "IAS 41 acquisition was not found."
            )

        if (
            acquisition.get("status")
            != "approved"
        ):
            raise ValueError(
                "Only approved IAS 41 acquisitions can be posted."
            )

        if acquisition.get(
            "journal_id"
        ):
            raise ValueError(
                "This IAS 41 acquisition has already been posted."
            )

        preview = (
            self.ias41_acquisition_journal_preview(
                company_id,
                acquisition_id,
                user_id=user_id,
                save_preview=True,
                cur=cur,
            )
        )

        if not preview.get(
            "ready_to_post"
        ):
            raise ValueError(
                "The IAS 41 journal preview is not ready to post."
            )

        journal_id = self._ias41_post_preview_journal(
            company_id,
            posting_date=acquisition.get("recognition_date"),
            ref=acquisition.get("transaction_number"),
            description=preview.get("description") or "IAS 41 acquisition",
            source="ias41_acquisition",
            source_id=int(acquisition_id),
            preview=preview,
            currency=acquisition.get("currency_code"),
            user_id=user_id,
            cur=cur,
        )

        created_batches = []
        created_assets = []

        for line in (
            acquisition.get("lines")
            or []
        ):
            tracking_method = str(
                line.get(
                    "tracking_method"
                )
                or "batch"
            ).lower()

            batch_id = None
            asset_id = None

            if tracking_method in {
                "batch",
                "both",
            }:
                batch_id = (
                    self._ias41_create_batch_from_acquisition_line(
                        company_id,
                        acquisition,
                        line,
                        journal_id,
                        user_id=user_id,
                        cur=cur,
                    )
                )

                created_batches.append(
                    batch_id
                )

            if tracking_method in {
                "individual",
                "both",
            }:
                asset_id = (
                    self._ias41_create_asset_from_acquisition_line(
                        company_id,
                        acquisition,
                        line,
                        journal_id,
                        batch_id=batch_id,
                        user_id=user_id,
                        cur=cur,
                    )
                )

                created_assets.append(
                    asset_id
                )

            self.execute_sql(
                f"""
                UPDATE {schema}.ias41_acquisition_lines
                SET
                    batch_id = %s,
                    biological_asset_id = %s,
                    updated_at = NOW(),
                    updated_by_user_id = %s
                WHERE company_id = %s
                AND acquisition_id = %s
                AND id = %s
                """,
                (
                    batch_id,
                    asset_id,
                    user_id,
                    company_id,
                    int(acquisition_id),
                    int(line["id"]),
                ),
                cur=cur,
            )

        posted = self.fetch_one(
            f"""
            UPDATE {schema}.ias41_acquisitions
            SET
                status = 'posted',
                journal_id = %s,
                posted_at = NOW(),
                posted_by_user_id = %s,
                updated_at = NOW(),
                updated_by_user_id = %s
            WHERE company_id = %s
            AND id = %s
            AND status = 'approved'
            AND journal_id IS NULL
            RETURNING *
            """,
            (
                journal_id,
                user_id,
                user_id,
                company_id,
                int(acquisition_id),
            ),
            cur=cur,
        )

        if not posted:
            raise ValueError(
                "IAS 41 acquisition status could not be updated."
            )

        return {
            "acquisition":
                self._ias41_serialise(
                    posted
                ),
            "journal_id":
                journal_id,
            "created_batch_ids":
                created_batches,
            "created_asset_ids":
                created_assets,
            "preview":
                preview,
        }

    IAS41_EVENT_TYPES = {
        "growth_measurement", "quantity_adjustment", "health_inspection",
        "treatment", "vaccination", "disease", "mortality",
        "location_transfer", "maturity_change", "general_note",
    }


    def _ias41_next_event_number(self, company_id: int, *, event_date=None, cur=None) -> str:
        company_id = int(company_id)
        schema = self._ias41_company_guard(company_id, cur=cur)
        year = str(event_date or date.today().isoformat())[:4]
        prefix = f"IAS41-EVT-{year}-"

        row = self.fetch_one(
            f"""
            SELECT COALESCE(MAX(
                CASE WHEN event_number ~ %s
                    THEN SUBSTRING(event_number FROM '([0-9]+)$')::INTEGER
                    ELSE 0 END
            ), 0) + 1 AS next_number
            FROM {schema}.ias41_events
            WHERE company_id = %s
            AND event_number LIKE %s
            """,
            (f"^{prefix}[0-9]+$", company_id, f"{prefix}%"),
            cur=cur,
        ) or {}

        return f"{prefix}{int(row.get('next_number') or 1):05d}"


    def _ias41_event_target(self, company_id: int, *, batch_id=None, asset_id=None, cur=None) -> dict:
        company_id = int(company_id)
        schema = self._ias41_company_guard(company_id, cur=cur)
        batch_id = self._ias41_optional_int(batch_id)
        asset_id = self._ias41_optional_int(asset_id)

        if bool(batch_id) == bool(asset_id):
            raise ValueError("Select either one batch or one biological asset.")

        if batch_id:
            row = self.fetch_one(
                f"""
                SELECT b.*, ac.class_name, ac.current_noncurrent
                FROM {schema}.ias41_batches b
                JOIN {schema}.ias41_asset_classes ac
                ON ac.company_id = b.company_id
                AND ac.id = b.asset_class_id
                WHERE b.company_id = %s AND b.id = %s
                """,
                (company_id, batch_id),
                cur=cur,
            )
            target_type = "batch"
        else:
            row = self.fetch_one(
                f"""
                SELECT a.*, ac.class_name, ac.current_noncurrent
                FROM {schema}.ias41_biological_assets a
                JOIN {schema}.ias41_asset_classes ac
                ON ac.company_id = a.company_id
                AND ac.id = a.asset_class_id
                WHERE a.company_id = %s AND a.id = %s
                """,
                (company_id, asset_id),
                cur=cur,
            )
            target_type = "asset"

        if not row:
            raise ValueError("Biological event target was not found.")

        out = self._ias41_serialise(row) or {}
        out["target_type"] = target_type
        return out

    def ias41_events_list(
        self,
        company_id: int,
        *,
        event_group: str | None = None,
        event_type: str | None = None,
        status: str | None = None,
        date_from=None,
        date_to=None,
        cur=None,
    ) -> list[dict]:
        company_id = int(company_id)
        schema = self._ias41_company_guard(company_id, cur=cur)
        conditions, params = ["e.company_id = %s"], [company_id]

        if event_group == "growth":
            conditions.append(
                "e.event_type IN ('growth_measurement','quantity_adjustment',"
                "'location_transfer','maturity_change','general_note')"
            )
        elif event_group == "health":
            conditions.append(
                "e.event_type IN ('health_inspection','treatment','vaccination',"
                "'disease','mortality')"
            )

        if event_type:
            conditions.append("e.event_type = %s")
            params.append(str(event_type).strip().lower())
        if status:
            conditions.append("e.status = %s")
            params.append(str(status).strip().lower())
        if date_from:
            conditions.append("e.event_date >= %s")
            params.append(date_from)
        if date_to:
            conditions.append("e.event_date <= %s")
            params.append(date_to)

        rows = self.fetch_all(
            f"""
            SELECT e.*,
                ac.class_code, ac.class_name,
                b.batch_code, b.batch_name,
                a.asset_number, a.asset_name,
                l.location_name,
                dl.location_name AS destination_location_name
            FROM {schema}.ias41_events e
            JOIN {schema}.ias41_asset_classes ac
            ON ac.company_id = e.company_id
            AND ac.id = e.asset_class_id
            LEFT JOIN {schema}.ias41_batches b
            ON b.company_id = e.company_id
            AND b.id = e.batch_id
            LEFT JOIN {schema}.ias41_biological_assets a
            ON a.company_id = e.company_id
            AND a.id = e.biological_asset_id
            LEFT JOIN {schema}.ias41_locations l
            ON l.company_id = e.company_id
            AND l.id = e.location_id
            LEFT JOIN {schema}.ias41_locations dl
            ON dl.company_id = e.company_id
            AND dl.id = e.destination_location_id
            WHERE {" AND ".join(conditions)}
            ORDER BY e.event_date DESC, e.id DESC
            """,
            tuple(params),
            cur=cur,
        )
        return self._ias41_serialise_many(rows)


    def ias41_event_get(self, company_id: int, event_id: int, *, cur=None) -> dict | None:
        company_id = int(company_id)
        schema = self._ias41_company_guard(company_id, cur=cur)

        row = self.fetch_one(
            f"""
            SELECT e.*,
                ac.class_code, ac.class_name, ac.current_noncurrent,
                b.batch_code, b.batch_name,
                a.asset_number, a.asset_name,
                l.location_name,
                dl.location_name AS destination_location_name
            FROM {schema}.ias41_events e
            JOIN {schema}.ias41_asset_classes ac
            ON ac.company_id = e.company_id
            AND ac.id = e.asset_class_id
            LEFT JOIN {schema}.ias41_batches b
            ON b.company_id = e.company_id
            AND b.id = e.batch_id
            LEFT JOIN {schema}.ias41_biological_assets a
            ON a.company_id = e.company_id
            AND a.id = e.biological_asset_id
            LEFT JOIN {schema}.ias41_locations l
            ON l.company_id = e.company_id
            AND l.id = e.location_id
            LEFT JOIN {schema}.ias41_locations dl
            ON dl.company_id = e.company_id
            AND dl.id = e.destination_location_id
            WHERE e.company_id = %s AND e.id = %s
            LIMIT 1
            """,
            (company_id, int(event_id)),
            cur=cur,
        )
        return self._ias41_serialise(row)

    def ias41_event_save(
        self,
        company_id: int,
        payload: dict,
        *,
        event_id: int | None = None,
        user_id: int | None = None,
        cur=None,
    ) -> dict:
        company_id = int(company_id)
        schema = self._ias41_company_guard(company_id, cur=cur)
        payload = payload or {}

        existing = self.ias41_event_get(company_id, event_id, cur=cur) if event_id else None
        if event_id and not existing:
            raise ValueError("Biological event was not found.")
        if existing and existing.get("status") != "draft":
            raise ValueError("Only draft biological events can be changed.")

        event_type = str(payload.get("event_type") or "growth_measurement").strip().lower()
        if event_type not in self.IAS41_EVENT_TYPES:
            raise ValueError("Invalid biological event type.")

        event_date = payload.get("event_date") or date.today().isoformat()
        batch_id = self._ias41_optional_int(payload.get("batch_id"))
        asset_id = self._ias41_optional_int(payload.get("biological_asset_id"))
        target = self._ias41_event_target(
            company_id, batch_id=batch_id, asset_id=asset_id, cur=cur
        )

        quantity_before = float(target.get(
            "current_quantity" if target["target_type"] == "batch" else "quantity"
        ) or 0)
        weight_before = self._ias41_optional_float(target.get("current_weight"))
        quantity_change = float(payload.get("quantity_change") or 0)
        weight_change = float(payload.get("weight_change") or 0)
        mortality_quantity = float(payload.get("mortality_quantity") or 0)

        if event_type == "mortality":
            if mortality_quantity <= 0:
                raise ValueError("Mortality quantity must be greater than zero.")
            quantity_change = -abs(mortality_quantity)

        quantity_after = quantity_before + quantity_change
        weight_after = (
            None if weight_before is None and not weight_change
            else float(weight_before or 0) + weight_change
        )

        if quantity_after < 0:
            raise ValueError("Event quantity would make the target quantity negative.")
        if weight_after is not None and weight_after < 0:
            raise ValueError("Event weight would make the target weight negative.")

        destination_id = self._ias41_optional_int(payload.get("destination_location_id"))
        if event_type == "location_transfer" and not destination_id:
            raise ValueError("Destination location is required for a transfer.")

        carrying_released = float(payload.get("carrying_amount_released") or 0)
        if event_type == "mortality" and carrying_released <= 0:
            current_value = float(target.get("current_carrying_amount") or 0)
            carrying_released = round(
                current_value * (mortality_quantity / quantity_before), 2
            ) if quantity_before else 0

        number = str(
            payload.get("event_number")
            or (existing or {}).get("event_number")
            or self._ias41_next_event_number(
                company_id, event_date=event_date, cur=cur
            )
        ).strip()

        values = (
            number, event_type, event_date,
            batch_id, asset_id, int(target["asset_class_id"]),
            self._ias41_optional_int(target.get("location_id")),
            destination_id,
            self._ias41_optional_int(payload.get("season_id")),
            quantity_before, quantity_change, quantity_after,
            str(payload.get("quantity_unit") or target.get("quantity_unit") or "").strip() or None,
            weight_before, weight_change, weight_after,
            str(payload.get("weight_unit") or target.get("weight_unit") or "").strip() or None,
            str(payload.get("maturity_status_before") or target.get("status") or "").strip() or None,
            str(payload.get("maturity_status_after") or "").strip() or None,
            str(payload.get("health_status_before") or "").strip() or None,
            str(payload.get("health_status_after") or "").strip() or None,
            str(payload.get("diagnosis") or "").strip() or None,
            str(payload.get("treatment") or "").strip() or None,
            str(payload.get("medicine") or "").strip() or None,
            str(payload.get("dosage") or "").strip() or None,
            str(payload.get("veterinarian") or "").strip() or None,
            payload.get("next_review_date") or None,
            mortality_quantity, carrying_released,
            str(payload.get("biological_asset_account_code") or "").strip() or None,
            str(payload.get("mortality_loss_account_code") or "").strip() or None,
            str(payload.get("reference") or "").strip() or None,
            str(payload.get("description") or "").strip() or None,
            self._ias41_json_value(payload.get("metadata")),
        )

        for code in (values[-5], values[-4]):
            if code:
                self._ias41_validate_account_code(company_id, code, cur=cur)

        if event_id:
            row = self.fetch_one(
                f"""
                UPDATE {schema}.ias41_events SET
                    event_number=%s, event_type=%s, event_date=%s,
                    batch_id=%s, biological_asset_id=%s, asset_class_id=%s,
                    location_id=%s, destination_location_id=%s, season_id=%s,
                    quantity_before=%s, quantity_change=%s, quantity_after=%s,
                    quantity_unit=%s, weight_before=%s, weight_change=%s,
                    weight_after=%s, weight_unit=%s,
                    maturity_status_before=%s, maturity_status_after=%s,
                    health_status_before=%s, health_status_after=%s,
                    diagnosis=%s, treatment=%s, medicine=%s, dosage=%s,
                    veterinarian=%s, next_review_date=%s,
                    mortality_quantity=%s, carrying_amount_released=%s,
                    biological_asset_account_code=%s,
                    mortality_loss_account_code=%s,
                    reference=%s, description=%s, metadata=%s::jsonb,
                    updated_at=NOW(), updated_by_user_id=%s
                WHERE company_id=%s AND id=%s AND status='draft'
                RETURNING *
                """,
                values + (user_id, company_id, int(event_id)),
                cur=cur,
            )
        else:
            row = self.fetch_one(
                f"""
                INSERT INTO {schema}.ias41_events (
                    company_id, event_number, event_type, event_date,
                    batch_id, biological_asset_id, asset_class_id,
                    location_id, destination_location_id, season_id,
                    quantity_before, quantity_change, quantity_after, quantity_unit,
                    weight_before, weight_change, weight_after, weight_unit,
                    maturity_status_before, maturity_status_after,
                    health_status_before, health_status_after,
                    diagnosis, treatment, medicine, dosage, veterinarian,
                    next_review_date, mortality_quantity, carrying_amount_released,
                    biological_asset_account_code, mortality_loss_account_code,
                    status, reference, description, metadata,
                    created_at, created_by_user_id, updated_at, updated_by_user_id
                )
                VALUES (
                    %s, %s, %s, %s, %s, %s, %s, %s, %s, %s,
                    %s, %s, %s, %s, %s, %s, %s, %s, %s, %s,
                    %s, %s, %s, %s, %s, %s, %s, %s, %s, %s,
                    %s, %s, 'draft', %s, %s, %s::jsonb,
                    NOW(), %s, NOW(), %s
                )
                RETURNING *
                """,
                (company_id,) + values + (user_id, user_id),
                cur=cur,
            )

        if not row:
            raise ValueError("Biological event was not saved.")

        self.execute_sql(
            f"""
            DELETE FROM {schema}.ias41_event_journal_previews
            WHERE company_id=%s AND event_id=%s
            """,
            (company_id, int(row["id"])),
            cur=cur,
        )
        return self.ias41_event_get(company_id, int(row["id"]), cur=cur) or {}
        
    def ias41_event_delete(self, company_id: int, event_id: int, *, cur=None) -> bool:
        schema = self._ias41_company_guard(int(company_id), cur=cur)
        row = self.fetch_one(
            f"""
            DELETE FROM {schema}.ias41_events
            WHERE company_id=%s AND id=%s AND status='draft'
            RETURNING id
            """,
            (int(company_id), int(event_id)),
            cur=cur,
        )
        return bool(row)


    def ias41_event_cancel(
        self, company_id: int, event_id: int, *, user_id=None, cur=None
    ) -> dict:
        schema = self._ias41_company_guard(int(company_id), cur=cur)
        row = self.fetch_one(
            f"""
            UPDATE {schema}.ias41_events
            SET status='cancelled', updated_at=NOW(), updated_by_user_id=%s
            WHERE company_id=%s AND id=%s AND status IN ('draft','approved')
            RETURNING *
            """,
            (user_id, int(company_id), int(event_id)),
            cur=cur,
        )
        if not row:
            raise ValueError("Only draft or approved events can be cancelled.")
        return self._ias41_serialise(row) or {}


    def ias41_event_approve(
        self, company_id: int, event_id: int, *, user_id=None, cur=None
    ) -> dict:
        company_id = int(company_id)
        schema = self._ias41_company_guard(company_id, cur=cur)
        event = self.ias41_event_get(company_id, event_id, cur=cur)

        if not event or event.get("status") != "draft":
            raise ValueError("Only draft biological events can be approved.")

        preview = self.ias41_event_journal_preview(
            company_id, event_id, user_id=user_id, save_preview=True, cur=cur
        )

        if event.get("event_type") == "mortality" and not preview.get("ready_to_post"):
            raise ValueError("Mortality event journal preview is incomplete.")

        row = self.fetch_one(
            f"""
            UPDATE {schema}.ias41_events
            SET status='approved', approved_at=NOW(), approved_by_user_id=%s,
                updated_at=NOW(), updated_by_user_id=%s
            WHERE company_id=%s AND id=%s AND status='draft'
            RETURNING *
            """,
            (user_id, user_id, company_id, int(event_id)),
            cur=cur,
        )
        return {
            "event": self._ias41_serialise(row),
            "preview": preview,
        }

    def ias41_event_journal_preview(
        self,
        company_id: int,
        event_id: int,
        *,
        user_id=None,
        save_preview=True,
        cur=None,
    ) -> dict:
        company_id = int(company_id)
        schema = self._ias41_company_guard(company_id, cur=cur)
        event = self.ias41_event_get(company_id, event_id, cur=cur)

        if not event:
            raise ValueError("Biological event was not found.")
        if event.get("status") in {"posted", "cancelled", "reversed"}:
            raise ValueError("Preview is unavailable for this event status.")

        lines, missing, invalid = [], [], []
        event_type = event.get("event_type")

        if event_type == "mortality":
            amount = round(float(event.get("carrying_amount_released") or 0), 2)
            role = (
                "ias41_biological_asset_noncurrent"
                if event.get("current_noncurrent") == "noncurrent"
                else "ias41_biological_asset_current"
            )

            asset_account = self.ias41_resolve_account(
                company_id, role,
                asset_class_id=event.get("asset_class_id"),
                override_code=event.get("biological_asset_account_code"),
                cur=cur,
            )
            loss_account = self.ias41_resolve_account(
                company_id, "ias41_mortality_loss",
                asset_class_id=event.get("asset_class_id"),
                override_code=event.get("mortality_loss_account_code"),
                cur=cur,
            )

            if amount <= 0:
                invalid.append({"reason": "Carrying amount released must exceed zero."})
            if not asset_account:
                missing.append({"role_code": role})
            if not loss_account:
                missing.append({"role_code": "ias41_mortality_loss"})

            if amount > 0 and asset_account and loss_account:
                description = event.get("description") or "IAS 41 mortality"
                lines = [
                    {
                        "role_code": "ias41_mortality_loss",
                        "account_code": loss_account.get("code"),
                        "account_name": loss_account.get("name"),
                        "description": description,
                        "debit": amount,
                        "credit": 0,
                        "resolution_source": loss_account.get("resolution_source"),
                    },
                    {
                        "role_code": role,
                        "account_code": asset_account.get("code"),
                        "account_name": asset_account.get("name"),
                        "description": description,
                        "debit": 0,
                        "credit": amount,
                        "resolution_source": asset_account.get("resolution_source"),
                    },
                ]

        debit = round(sum(float(x.get("debit") or 0) for x in lines), 2)
        credit = round(sum(float(x.get("credit") or 0) for x in lines), 2)
        financial = event_type == "mortality"
        ready = (
            not missing and not invalid
            and (not financial or (lines and abs(debit - credit) < 0.01))
        )

        preview = {
            "event_id": int(event_id),
            "event_number": event.get("event_number"),
            "event_type": event_type,
            "financial_event": financial,
            "ready_to_post": ready,
            "total_debit": debit,
            "total_credit": credit,
            "balanced": abs(debit - credit) < 0.01,
            "missing_mappings": missing,
            "invalid_accounts": invalid,
            "journal_lines": lines,
        }

        if save_preview:
            version = self.fetch_one(
                f"""
                SELECT COALESCE(MAX(preview_version),0)+1 AS next_version
                FROM {schema}.ias41_event_journal_previews
                WHERE company_id=%s AND event_id=%s
                """,
                (company_id, int(event_id)),
                cur=cur,
            ) or {}

            self.execute_sql(
                f"""
                INSERT INTO {schema}.ias41_event_journal_previews (
                    company_id, event_id, preview_version, ready_to_post,
                    total_debit, total_credit, missing_mappings,
                    invalid_accounts, journal_lines,
                    generated_at, generated_by_user_id
                )
                VALUES (
                    %s,%s,%s,%s,%s,%s,%s::jsonb,%s::jsonb,%s::jsonb,NOW(),%s
                )
                """,
                (
                    company_id, int(event_id),
                    int(version.get("next_version") or 1),
                    ready, debit, credit,
                    self._ias41_json_value(missing),
                    self._ias41_json_value(invalid),
                    self._ias41_json_value(lines),
                    user_id,
                ),
                cur=cur,
            )

        return preview

    def ias41_event_post(
        self, company_id: int, event_id: int, *, user_id=None, cur=None
    ) -> dict:
        company_id = int(company_id)
        schema = self._ias41_company_guard(company_id, cur=cur)
        event = self.ias41_event_get(company_id, event_id, cur=cur)

        if not event or event.get("status") != "approved":
            raise ValueError("Only approved biological events can be posted.")
        if event.get("journal_id"):
            raise ValueError("Biological event is already posted.")

        preview = self.ias41_event_journal_preview(
            company_id, event_id, user_id=user_id, save_preview=True, cur=cur
        )
        if not preview.get("ready_to_post"):
            raise ValueError("Biological event is not ready to post.")

        journal_id = None

        if preview.get("financial_event"):
            journal_id = self._ias41_post_preview_journal(
                company_id,
                posting_date=event.get("event_date"),
                ref=event.get("event_number"),
                description=event.get("description") or "IAS 41 biological event",
                source="ias41_event",
                source_id=int(event_id),
                preview=preview,
                user_id=user_id,
                cur=cur,
            )

        if event.get("batch_id"):
            self.execute_sql(
                f"""
                UPDATE {schema}.ias41_batches
                SET current_quantity=%s, current_weight=%s,
                    location_id=COALESCE(%s,location_id),
                    status=COALESCE(%s,status),
                    current_carrying_amount=current_carrying_amount-%s,
                    updated_at=NOW(), updated_by_user_id=%s
                WHERE company_id=%s AND id=%s
                """,
                (
                    event.get("quantity_after"), event.get("weight_after"),
                    event.get("destination_location_id"),
                    event.get("maturity_status_after"),
                    float(event.get("carrying_amount_released") or 0),
                    user_id, company_id, int(event["batch_id"]),
                ),
                cur=cur,
            )
        else:
            new_status = event.get("maturity_status_after")
            if event.get("event_type") == "mortality" and float(event.get("quantity_after") or 0) == 0:
                new_status = "deceased"

            self.execute_sql(
                f"""
                UPDATE {schema}.ias41_biological_assets
                SET quantity=%s, current_weight=%s,
                    location_id=COALESCE(%s,location_id),
                    status=COALESCE(%s,status),
                    current_carrying_amount=current_carrying_amount-%s,
                    updated_at=NOW(), updated_by_user_id=%s
                WHERE company_id=%s AND id=%s
                """,
                (
                    event.get("quantity_after"), event.get("weight_after"),
                    event.get("destination_location_id"), new_status,
                    float(event.get("carrying_amount_released") or 0),
                    user_id, company_id, int(event["biological_asset_id"]),
                ),
                cur=cur,
            )

        row = self.fetch_one(
            f"""
            UPDATE {schema}.ias41_events
            SET status='posted', journal_id=%s, posted_at=NOW(),
                posted_by_user_id=%s, updated_at=NOW(), updated_by_user_id=%s
            WHERE company_id=%s AND id=%s AND status='approved'
            RETURNING *
            """,
            (journal_id, user_id, user_id, company_id, int(event_id)),
            cur=cur,
        )

        return {
            "event": self._ias41_serialise(row),
            "journal_id": journal_id,
            "preview": preview,
        }

    def _ias41_post_preview_journal(
        self,
        company_id: int,
        *,
        posting_date,
        ref: str,
        description: str,
        source: str,
        source_id: int,
        preview: dict,
        currency: str | None = None,
        user_id: int | None = None,
        cur=None,
    ) -> int:
        if not preview.get("ready_to_post"):
            raise ValueError("IAS 41 journal preview is not ready to post.")

        lines = [{
            "account_code": row.get("account_code"),
            "description": row.get("description") or description,
            "memo": row.get("description") or description,
            "debit": float(row.get("debit") or 0),
            "credit": float(row.get("credit") or 0),
        } for row in preview.get("journal_lines") or []]

        if not lines:
            raise ValueError("IAS 41 journal preview has no journal lines.")

        return self.post_journal(
            int(company_id),
            {
                "date": posting_date,
                "ref": ref,
                "description": description,
                "source": source,
                "source_id": int(source_id),
                "module_name": "ias41",
                "currency": currency or "USD",
                "gross_amount": float(preview.get("total_debit") or 0),
                "prepared_by_user_id": user_id,
                "created_by_user_id": user_id,
                "updated_by_user_id": user_id,
                "lines": lines,
            },
            cur=cur,
        )

    IAS41_VALUATION_METHODS = {
        "market_price", "recent_transaction", "sector_benchmark",
        "discounted_cash_flow", "cost_approach", "manual",
    }


    def _ias41_next_valuation_number(
        self, company_id: int, *, valuation_date=None, cur=None
    ) -> str:
        company_id = int(company_id)
        schema = self._ias41_company_guard(company_id, cur=cur)
        year = str(valuation_date or date.today().isoformat())[:4]
        prefix = f"IAS41-VAL-{year}-"

        row = self.fetch_one(
            f"""
            SELECT COALESCE(MAX(
                CASE WHEN run_number ~ %s
                    THEN SUBSTRING(run_number FROM '([0-9]+)$')::INTEGER
                    ELSE 0 END
            ),0)+1 AS next_number
            FROM {schema}.ias41_valuation_runs
            WHERE company_id=%s AND run_number LIKE %s
            """,
            (f"^{prefix}[0-9]+$", company_id, f"{prefix}%"),
            cur=cur,
        ) or {}

        return f"{prefix}{int(row.get('next_number') or 1):05d}"


    def _ias41_valuation_target(
        self, company_id: int, *, batch_id=None, asset_id=None, cur=None
    ) -> dict:
        return self._ias41_event_target(
            company_id,
            batch_id=batch_id,
            asset_id=asset_id,
            cur=cur,
        )


    def _ias41_calculate_valuation_line(self, target: dict, payload: dict) -> dict:
        quantity = float(payload.get("quantity") or (
            target.get("current_quantity")
            if target.get("target_type") == "batch"
            else target.get("quantity")
        ) or 0)

        fair_value_per_unit = float(payload.get("fair_value_per_unit") or 0)
        costs_per_unit = float(payload.get("costs_to_sell_per_unit") or 0)

        gross = round(
            float(payload.get("gross_fair_value"))
            if payload.get("gross_fair_value") not in (None, "")
            else quantity * fair_value_per_unit,
            2,
        )

        costs = round(
            float(payload.get("costs_to_sell_amount"))
            if payload.get("costs_to_sell_amount") not in (None, "")
            else quantity * costs_per_unit,
            2,
        )

        new_carrying = round(gross - costs, 2)
        previous = round(float(target.get("current_carrying_amount") or 0), 2)
        movement = round(new_carrying - previous, 2)

        if new_carrying < 0:
            raise ValueError("Valuation carrying amount cannot be negative.")

        return {
            "quantity": quantity,
            "fair_value_per_unit": fair_value_per_unit,
            "gross_fair_value": gross,
            "costs_to_sell_per_unit": costs_per_unit,
            "costs_to_sell_amount": costs,
            "new_carrying_amount": new_carrying,
            "previous_fair_value": round(float(target.get("current_fair_value") or 0), 2),
            "previous_costs_to_sell": round(float(target.get("current_costs_to_sell") or 0), 2),
            "previous_carrying_amount": previous,
            "gain_amount": max(movement, 0),
            "loss_amount": abs(min(movement, 0)),
        }

    def ias41_valuations_list(
        self, company_id: int, *, status=None, date_from=None, date_to=None, cur=None
    ) -> list[dict]:
        company_id = int(company_id)
        schema = self._ias41_company_guard(company_id, cur=cur)
        where, params = ["r.company_id=%s"], [company_id]

        if status:
            where.append("r.status=%s")
            params.append(str(status).strip().lower())
        if date_from:
            where.append("r.valuation_date>=%s")
            params.append(date_from)
        if date_to:
            where.append("r.valuation_date<=%s")
            params.append(date_to)

        rows = self.fetch_all(
            f"""
            SELECT r.*,
                (SELECT COUNT(*) FROM {schema}.ias41_valuation_lines l
                    WHERE l.company_id=r.company_id
                    AND l.valuation_run_id=r.id) AS line_count
            FROM {schema}.ias41_valuation_runs r
            WHERE {" AND ".join(where)}
            ORDER BY r.valuation_date DESC,r.id DESC
            """,
            tuple(params),
            cur=cur,
        )
        return self._ias41_serialise_many(rows)


    def ias41_valuation_get(
        self, company_id: int, valuation_id: int, *, cur=None
    ) -> dict | None:
        company_id = int(company_id)
        schema = self._ias41_company_guard(company_id, cur=cur)

        run = self.fetch_one(
            f"""
            SELECT * FROM {schema}.ias41_valuation_runs
            WHERE company_id=%s AND id=%s
            """,
            (company_id, int(valuation_id)),
            cur=cur,
        )
        if not run:
            return None

        lines = self.fetch_all(
            f"""
            SELECT l.*,ac.class_code,ac.class_name,ac.current_noncurrent,
                b.batch_code,b.batch_name,a.asset_number,a.asset_name
            FROM {schema}.ias41_valuation_lines l
            JOIN {schema}.ias41_asset_classes ac
            ON ac.company_id=l.company_id AND ac.id=l.asset_class_id
            LEFT JOIN {schema}.ias41_batches b
            ON b.company_id=l.company_id AND b.id=l.batch_id
            LEFT JOIN {schema}.ias41_biological_assets a
            ON a.company_id=l.company_id AND a.id=l.biological_asset_id
            WHERE l.company_id=%s AND l.valuation_run_id=%s
            ORDER BY l.line_number,l.id
            """,
            (company_id, int(valuation_id)),
            cur=cur,
        )

        out = self._ias41_serialise(run) or {}
        out["lines"] = self._ias41_serialise_many(lines)
        return out

    def ias41_valuation_save(
        self,
        company_id: int,
        payload: dict,
        *,
        valuation_id: int | None = None,
        user_id: int | None = None,
        cur=None,
    ) -> dict:
        company_id = int(company_id)
        schema = self._ias41_company_guard(company_id, cur=cur)
        payload = payload or {}

        existing = self.ias41_valuation_get(
            company_id, valuation_id, cur=cur
        ) if valuation_id else None

        if valuation_id and not existing:
            raise ValueError("Valuation run was not found.")
        if existing and existing.get("status") not in {"draft", "calculated"}:
            raise ValueError("Only draft or calculated valuations can be changed.")

        valuation_date = payload.get("valuation_date") or date.today().isoformat()
        reporting_date = payload.get("reporting_date") or valuation_date
        method = str(payload.get("valuation_method") or "market_price").strip().lower()

        if method not in self.IAS41_VALUATION_METHODS:
            raise ValueError("Invalid valuation method.")

        source_lines = payload.get("lines") or []
        if not isinstance(source_lines, list) or not source_lines:
            raise ValueError("At least one valuation line is required.")

        lines = []
        for index, source in enumerate(source_lines, 1):
            source = source or {}
            batch_id = self._ias41_optional_int(source.get("batch_id"))
            asset_id = self._ias41_optional_int(source.get("biological_asset_id"))
            target = self._ias41_valuation_target(
                company_id, batch_id=batch_id, asset_id=asset_id, cur=cur
            )
            calc = self._ias41_calculate_valuation_line(target, source)

            lines.append({
                **source,
                **calc,
                "line_number": index,
                "batch_id": batch_id,
                "biological_asset_id": asset_id,
                "asset_class_id": int(target["asset_class_id"]),
                "location_id": self._ias41_optional_int(target.get("location_id")),
                "quantity_unit": source.get("quantity_unit") or target.get("quantity_unit"),
            })

        totals = {
            "previous": round(sum(float(x["previous_carrying_amount"]) for x in lines), 2),
            "fair_value": round(sum(float(x["gross_fair_value"]) for x in lines), 2),
            "costs": round(sum(float(x["costs_to_sell_amount"]) for x in lines), 2),
            "new": round(sum(float(x["new_carrying_amount"]) for x in lines), 2),
            "gain": round(sum(float(x["gain_amount"]) for x in lines), 2),
            "loss": round(sum(float(x["loss_amount"]) for x in lines), 2),
        }

        number = str(
            payload.get("run_number")
            or (existing or {}).get("run_number")
            or self._ias41_next_valuation_number(
                company_id, valuation_date=valuation_date, cur=cur
            )
        ).strip()

        values = (
            number, valuation_date, reporting_date,
            str(payload.get("valuation_scope") or "selected").strip().lower(),
            method,
            str(payload.get("currency_code") or "").strip() or None,
            float(payload.get("exchange_rate") or 1),
            totals["previous"], totals["fair_value"], totals["costs"],
            totals["new"], totals["gain"], totals["loss"],
            str(payload.get("reference") or "").strip() or None,
            str(payload.get("description") or "").strip() or None,
            self._ias41_json_value(payload.get("metadata")),
        )

        if valuation_id:
            run = self.fetch_one(
                f"""
                UPDATE {schema}.ias41_valuation_runs SET
                    run_number=%s,valuation_date=%s,reporting_date=%s,
                    valuation_scope=%s,valuation_method=%s,currency_code=%s,
                    exchange_rate=%s,total_previous_carrying_amount=%s,
                    total_fair_value=%s,total_costs_to_sell=%s,
                    total_new_carrying_amount=%s,total_gain=%s,total_loss=%s,
                    status='calculated',reference=%s,description=%s,
                    metadata=%s::jsonb,updated_at=NOW(),updated_by_user_id=%s
                WHERE company_id=%s AND id=%s
                AND status IN ('draft','calculated')
                RETURNING *
                """,
                values + (user_id, company_id, int(valuation_id)),
                cur=cur,
            )

            self.execute_sql(
                f"""
                DELETE FROM {schema}.ias41_valuation_lines
                WHERE company_id=%s AND valuation_run_id=%s
                """,
                (company_id, int(valuation_id)),
                cur=cur,
            )
            run_id = int(valuation_id)
        else:
            run = self.fetch_one(
                f"""
                INSERT INTO {schema}.ias41_valuation_runs (
                    company_id,run_number,valuation_date,reporting_date,
                    valuation_scope,valuation_method,currency_code,exchange_rate,
                    total_previous_carrying_amount,total_fair_value,
                    total_costs_to_sell,total_new_carrying_amount,
                    total_gain,total_loss,status,reference,description,metadata,
                    created_at,created_by_user_id,updated_at,updated_by_user_id
                )
                VALUES (
                    %s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,
                    'calculated',%s,%s,%s::jsonb,NOW(),%s,NOW(),%s
                )
                RETURNING *
                """,
                (company_id,) + values + (user_id, user_id),
                cur=cur,
            )
            run_id = int(run["id"])

        for line in lines:
            self.execute_sql(
                f"""
                INSERT INTO {schema}.ias41_valuation_lines (
                    company_id,valuation_run_id,line_number,batch_id,
                    biological_asset_id,asset_class_id,location_id,
                    quantity,quantity_unit,previous_fair_value,
                    previous_costs_to_sell,previous_carrying_amount,
                    fair_value_per_unit,gross_fair_value,
                    costs_to_sell_per_unit,costs_to_sell_amount,
                    new_carrying_amount,gain_amount,loss_amount,
                    market_source,market_reference,observable_input,
                    biological_asset_account_code,fair_value_gain_account_code,
                    fair_value_loss_account_code,notes,metadata,
                    created_at,created_by_user_id,updated_at,updated_by_user_id
                )
                VALUES (
                    %s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,
                    %s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s::jsonb,
                    NOW(),%s,NOW(),%s
                )
                """,
                (
                    company_id,run_id,line["line_number"],line["batch_id"],
                    line["biological_asset_id"],line["asset_class_id"],
                    line["location_id"],line["quantity"],line.get("quantity_unit"),
                    line["previous_fair_value"],line["previous_costs_to_sell"],
                    line["previous_carrying_amount"],line["fair_value_per_unit"],
                    line["gross_fair_value"],line["costs_to_sell_per_unit"],
                    line["costs_to_sell_amount"],line["new_carrying_amount"],
                    line["gain_amount"],line["loss_amount"],
                    str(line.get("market_source") or "").strip() or None,
                    str(line.get("market_reference") or "").strip() or None,
                    self._ias41_bool(line.get("observable_input"), True),
                    str(line.get("biological_asset_account_code") or "").strip() or None,
                    str(line.get("fair_value_gain_account_code") or "").strip() or None,
                    str(line.get("fair_value_loss_account_code") or "").strip() or None,
                    str(line.get("notes") or "").strip() or None,
                    self._ias41_json_value(line.get("metadata")),
                    user_id,user_id,
                ),
                cur=cur,
            )

        self.execute_sql(
            f"""
            DELETE FROM {schema}.ias41_valuation_previews
            WHERE company_id=%s AND valuation_run_id=%s
            """,
            (company_id, run_id),
            cur=cur,
        )

        return self.ias41_valuation_get(company_id, run_id, cur=cur) or {}

    def ias41_valuation_preview(
        self,
        company_id: int,
        valuation_id: int,
        *,
        user_id=None,
        save_preview=True,
        cur=None,
    ) -> dict:
        company_id = int(company_id)
        schema = self._ias41_company_guard(company_id, cur=cur)
        run = self.ias41_valuation_get(company_id, valuation_id, cur=cur)

        if not run:
            raise ValueError("Valuation run was not found.")
        if run.get("status") in {"posted", "cancelled", "reversed"}:
            raise ValueError("Preview is unavailable for this valuation status.")

        journals, missing = {}, []

        def add(account, description, debit=0, credit=0, role=None):
            if not account:
                missing.append({"role_code": role})
                return

            key = (
                account.get("code"),
                description,
                role,
                account.get("resolution_source"),
            )

            row = journals.setdefault(key, {
                "role_code": role,
                "account_code": account.get("code"),
                "account_name": account.get("name"),
                "description": description,
                "debit": 0,
                "credit": 0,
                "resolution_source": account.get("resolution_source"),
            })
            row["debit"] = round(row["debit"] + float(debit or 0), 2)
            row["credit"] = round(row["credit"] + float(credit or 0), 2)

        for line in run.get("lines") or []:
            role = (
                "ias41_biological_asset_noncurrent"
                if line.get("current_noncurrent") == "noncurrent"
                else "ias41_biological_asset_current"
            )

            asset_account = self.ias41_resolve_account(
                company_id, role,
                asset_class_id=line.get("asset_class_id"),
                override_code=line.get("biological_asset_account_code"),
                cur=cur,
            )
            description = (
                line.get("notes")
                or f"IAS 41 valuation {run.get('run_number')}"
            )

            if float(line.get("gain_amount") or 0) > 0:
                gain_account = self.ias41_resolve_account(
                    company_id, "ias41_fair_value_gain",
                    asset_class_id=line.get("asset_class_id"),
                    override_code=line.get("fair_value_gain_account_code"),
                    cur=cur,
                )
                add(asset_account, description, debit=line["gain_amount"], role=role)
                add(
                    gain_account, description,
                    credit=line["gain_amount"],
                    role="ias41_fair_value_gain",
                )

            if float(line.get("loss_amount") or 0) > 0:
                loss_account = self.ias41_resolve_account(
                    company_id, "ias41_fair_value_loss",
                    asset_class_id=line.get("asset_class_id"),
                    override_code=line.get("fair_value_loss_account_code"),
                    cur=cur,
                )
                add(
                    loss_account, description,
                    debit=line["loss_amount"],
                    role="ias41_fair_value_loss",
                )
                add(asset_account, description, credit=line["loss_amount"], role=role)

        lines = list(journals.values())
        debit = round(sum(float(x["debit"]) for x in lines), 2)
        credit = round(sum(float(x["credit"]) for x in lines), 2)
        ready = bool(lines and not missing and abs(debit - credit) < 0.01)

        preview = {
            "valuation_id": int(valuation_id),
            "run_number": run.get("run_number"),
            "ready_to_post": ready,
            "total_debit": debit,
            "total_credit": credit,
            "balanced": abs(debit - credit) < 0.01,
            "missing_mappings": missing,
            "invalid_accounts": [],
            "journal_lines": lines,
        }

        if save_preview:
            version = self.fetch_one(
                f"""
                SELECT COALESCE(MAX(preview_version),0)+1 AS next_version
                FROM {schema}.ias41_valuation_previews
                WHERE company_id=%s AND valuation_run_id=%s
                """,
                (company_id, int(valuation_id)),
                cur=cur,
            ) or {}

            self.execute_sql(
                f"""
                INSERT INTO {schema}.ias41_valuation_previews (
                    company_id,valuation_run_id,preview_version,
                    ready_to_post,total_debit,total_credit,
                    missing_mappings,invalid_accounts,journal_lines,
                    generated_at,generated_by_user_id
                )
                VALUES (
                    %s,%s,%s,%s,%s,%s,%s::jsonb,%s::jsonb,%s::jsonb,NOW(),%s
                )
                """,
                (
                    company_id,int(valuation_id),
                    int(version.get("next_version") or 1),
                    ready,debit,credit,
                    self._ias41_json_value(missing),
                    self._ias41_json_value([]),
                    self._ias41_json_value(lines),
                    user_id,
                ),
                cur=cur,
            )

        return preview

    def ias41_valuation_approve(
        self, company_id: int, valuation_id: int, *, user_id=None, cur=None
    ) -> dict:
        company_id = int(company_id)
        schema = self._ias41_company_guard(company_id, cur=cur)
        run = self.ias41_valuation_get(company_id, valuation_id, cur=cur)

        if not run or run.get("status") != "calculated":
            raise ValueError("Only calculated valuations can be approved.")

        preview = self.ias41_valuation_preview(
            company_id, valuation_id, user_id=user_id, cur=cur
        )
        if not preview.get("ready_to_post"):
            raise ValueError("Valuation journal preview is incomplete.")

        row = self.fetch_one(
            f"""
            UPDATE {schema}.ias41_valuation_runs
            SET status='approved',approved_at=NOW(),approved_by_user_id=%s,
                updated_at=NOW(),updated_by_user_id=%s
            WHERE company_id=%s AND id=%s AND status='calculated'
            RETURNING *
            """,
            (user_id,user_id,company_id,int(valuation_id)),
            cur=cur,
        )
        return {"valuation": self._ias41_serialise(row), "preview": preview}


    def ias41_valuation_post(
        self, company_id: int, valuation_id: int, *, user_id=None, cur=None
    ) -> dict:
        company_id = int(company_id)
        schema = self._ias41_company_guard(company_id, cur=cur)
        run = self.ias41_valuation_get(company_id, valuation_id, cur=cur)

        if not run or run.get("status") != "approved":
            raise ValueError("Only approved valuations can be posted.")
        if run.get("journal_id"):
            raise ValueError("Valuation is already posted.")

        preview = self.ias41_valuation_preview(
            company_id, valuation_id, user_id=user_id, cur=cur
        )

        journal_id = self._ias41_post_preview_journal(
            company_id,
            posting_date=run.get("valuation_date"),
            ref=run.get("run_number"),
            description=run.get("description") or "IAS 41 fair-value valuation",
            source="ias41_valuation",
            source_id=int(valuation_id),
            preview=preview,
            currency=run.get("currency_code"),
            user_id=user_id,
            cur=cur,
        )

        for line in run.get("lines") or []:
            if line.get("batch_id"):
                self.execute_sql(
                    f"""
                    UPDATE {schema}.ias41_batches
                    SET current_fair_value=%s,current_costs_to_sell=%s,
                        current_carrying_amount=%s,updated_at=NOW(),
                        updated_by_user_id=%s
                    WHERE company_id=%s AND id=%s
                    """,
                    (
                        line["gross_fair_value"],line["costs_to_sell_amount"],
                        line["new_carrying_amount"],user_id,company_id,
                        int(line["batch_id"]),
                    ),
                    cur=cur,
                )
            else:
                self.execute_sql(
                    f"""
                    UPDATE {schema}.ias41_biological_assets
                    SET current_fair_value=%s,current_costs_to_sell=%s,
                        current_carrying_amount=%s,last_valuation_date=%s,
                        last_valuation_run_id=%s,updated_at=NOW(),
                        updated_by_user_id=%s
                    WHERE company_id=%s AND id=%s
                    """,
                    (
                        line["gross_fair_value"],line["costs_to_sell_amount"],
                        line["new_carrying_amount"],run["valuation_date"],
                        int(valuation_id),user_id,company_id,
                        int(line["biological_asset_id"]),
                    ),
                    cur=cur,
                )

        row = self.fetch_one(
            f"""
            UPDATE {schema}.ias41_valuation_runs
            SET status='posted',journal_id=%s,posted_at=NOW(),
                posted_by_user_id=%s,updated_at=NOW(),updated_by_user_id=%s
            WHERE company_id=%s AND id=%s
            AND status='approved' AND journal_id IS NULL
            RETURNING *
            """,
            (journal_id,user_id,user_id,company_id,int(valuation_id)),
            cur=cur,
        )

        return {
            "valuation": self._ias41_serialise(row),
            "journal_id": journal_id,
            "preview": preview,
        }

    IAS41_HARVEST_STATUSES = {
        "draft", "calculated", "approved",
        "posted", "cancelled", "reversed",
    }


    def _ias41_next_harvest_number(
        self,
        company_id: int,
        *,
        harvest_date=None,
        cur=None,
    ) -> str:
        company_id = int(company_id)
        schema = self._ias41_company_guard(company_id, cur=cur)
        year = str(harvest_date or date.today().isoformat())[:4]
        prefix = f"IAS41-HRV-{year}-"

        row = self.fetch_one(
            f"""
            SELECT COALESCE(MAX(
                CASE
                    WHEN harvest_number ~ %s
                    THEN SUBSTRING(
                        harvest_number FROM '([0-9]+)$'
                    )::INTEGER
                    ELSE 0
                END
            ),0)+1 AS next_number
            FROM {schema}.ias41_harvests
            WHERE company_id=%s
            AND harvest_number LIKE %s
            """,
            (f"^{prefix}[0-9]+$", company_id, f"{prefix}%"),
            cur=cur,
        ) or {}

        return f"{prefix}{int(row.get('next_number') or 1):05d}"


    def _ias41_harvest_product(
        self,
        company_id: int,
        product_id: int,
        *,
        cur=None,
    ) -> dict:
        company_id = int(company_id)
        schema = self._ias41_company_guard(company_id, cur=cur)

        row = self.fetch_one(
            f"""
            SELECT p.*,i.sku AS inventory_sku,i.name AS inventory_item_name,
                i.unit AS inventory_unit,i.is_active AS inventory_item_active
            FROM {schema}.ias41_products p
            LEFT JOIN {schema}.inventory_items i
            ON i.company_id=p.company_id
            AND i.id=p.inventory_item_id
            WHERE p.company_id=%s
            AND p.id=%s
            AND p.is_active=TRUE
            LIMIT 1
            """,
            (company_id, int(product_id)),
            cur=cur,
        )

        if not row:
            raise ValueError("Agricultural product was not found.")

        out = self._ias41_serialise(row) or {}

        if not out.get("inventory_item_id"):
            raise ValueError(
                "Agricultural product must be linked to an inventory item."
            )

        if out.get("inventory_item_active") is False:
            raise ValueError("Linked inventory item is inactive.")

        return out

    def ias41_harvests_list(
        self,
        company_id: int,
        *,
        status=None,
        date_from=None,
        date_to=None,
        cur=None,
    ) -> list[dict]:
        company_id = int(company_id)
        schema = self._ias41_company_guard(company_id, cur=cur)
        where, params = ["h.company_id=%s"], [company_id]

        if status:
            where.append("h.status=%s")
            params.append(str(status).strip().lower())
        if date_from:
            where.append("h.harvest_date>=%s")
            params.append(date_from)
        if date_to:
            where.append("h.harvest_date<=%s")
            params.append(date_to)

        rows = self.fetch_all(
            f"""
            SELECT h.*,
                ac.class_code,ac.class_name,ac.current_noncurrent,
                p.product_code,p.product_name,
                b.batch_code,b.batch_name,
                a.asset_number,a.asset_name,
                l.location_name
            FROM {schema}.ias41_harvests h
            JOIN {schema}.ias41_asset_classes ac
            ON ac.company_id=h.company_id
            AND ac.id=h.asset_class_id
            JOIN {schema}.ias41_products p
            ON p.company_id=h.company_id
            AND p.id=h.product_id
            LEFT JOIN {schema}.ias41_batches b
            ON b.company_id=h.company_id
            AND b.id=h.batch_id
            LEFT JOIN {schema}.ias41_biological_assets a
            ON a.company_id=h.company_id
            AND a.id=h.biological_asset_id
            LEFT JOIN {schema}.ias41_locations l
            ON l.company_id=h.company_id
            AND l.id=h.location_id
            WHERE {" AND ".join(where)}
            ORDER BY h.harvest_date DESC,h.id DESC
            """,
            tuple(params),
            cur=cur,
        )

        return self._ias41_serialise_many(rows)


    def ias41_harvest_get(
        self,
        company_id: int,
        harvest_id: int,
        *,
        cur=None,
    ) -> dict | None:
        company_id = int(company_id)
        schema = self._ias41_company_guard(company_id, cur=cur)

        row = self.fetch_one(
            f"""
            SELECT h.*,
                ac.class_code,ac.class_name,ac.current_noncurrent,
                p.product_code,p.product_name,
                b.batch_code,b.batch_name,
                a.asset_number,a.asset_name,
                l.location_name
            FROM {schema}.ias41_harvests h
            JOIN {schema}.ias41_asset_classes ac
            ON ac.company_id=h.company_id
            AND ac.id=h.asset_class_id
            JOIN {schema}.ias41_products p
            ON p.company_id=h.company_id
            AND p.id=h.product_id
            LEFT JOIN {schema}.ias41_batches b
            ON b.company_id=h.company_id
            AND b.id=h.batch_id
            LEFT JOIN {schema}.ias41_biological_assets a
            ON a.company_id=h.company_id
            AND a.id=h.biological_asset_id
            LEFT JOIN {schema}.ias41_locations l
            ON l.company_id=h.company_id
            AND l.id=h.location_id
            WHERE h.company_id=%s AND h.id=%s
            LIMIT 1
            """,
            (company_id, int(harvest_id)),
            cur=cur,
        )

        return self._ias41_serialise(row)

    def ias41_harvest_save(
        self,
        company_id: int,
        payload: dict,
        *,
        harvest_id: int | None = None,
        user_id: int | None = None,
        cur=None,
    ) -> dict:
        company_id = int(company_id)
        schema = self._ias41_company_guard(company_id, cur=cur)
        payload = payload or {}

        existing = self.ias41_harvest_get(
            company_id,
            harvest_id,
            cur=cur,
        ) if harvest_id else None

        if harvest_id and not existing:
            raise ValueError("Harvest was not found.")

        if existing and existing.get("status") not in {"draft", "calculated"}:
            raise ValueError("Only draft or calculated harvests can be changed.")

        batch_id = self._ias41_optional_int(payload.get("batch_id"))
        asset_id = self._ias41_optional_int(payload.get("biological_asset_id"))

        target = self._ias41_event_target(
            company_id,
            batch_id=batch_id,
            asset_id=asset_id,
            cur=cur,
        )

        product_id = self._ias41_optional_int(payload.get("product_id"))
        if not product_id:
            raise ValueError("Agricultural product is required.")

        product = self._ias41_harvest_product(
            company_id,
            product_id,
            cur=cur,
        )

        quantity = float(payload.get("harvested_quantity") or 0)
        if quantity <= 0:
            raise ValueError("Harvested quantity must be greater than zero.")

        available = float(
            target.get("current_quantity")
            if target.get("target_type") == "batch"
            else target.get("quantity")
            or 0
        )

        if quantity > available:
            raise ValueError(
                f"Harvest quantity exceeds available biological quantity: {available:g}."
            )

        fair_value_per_unit = float(payload.get("fair_value_per_unit") or 0)
        costs_per_unit = float(payload.get("costs_to_sell_per_unit") or 0)

        gross = payload.get("gross_fair_value")
        if gross in (None, ""):
            gross = quantity * fair_value_per_unit

        costs = payload.get("costs_to_sell_amount")
        if costs in (None, ""):
            costs = quantity * costs_per_unit

        gross = round(float(gross), 2)
        costs = round(float(costs), 2)
        inventory_value = round(gross - costs, 2)

        if inventory_value < 0:
            raise ValueError("Harvest inventory value cannot be negative.")

        current_carrying = float(target.get("current_carrying_amount") or 0)

        released = payload.get("biological_value_released")
        if released in (None, ""):
            released = round(
                current_carrying * (quantity / available),
                2,
            ) if available else 0

        released = round(float(released), 2)
        movement = round(inventory_value - released, 2)

        gain = max(movement, 0)
        loss = abs(min(movement, 0))

        harvest_date = payload.get("harvest_date") or date.today().isoformat()
        recognition_date = payload.get("recognition_date") or harvest_date

        number = str(
            payload.get("harvest_number")
            or (existing or {}).get("harvest_number")
            or self._ias41_next_harvest_number(
                company_id,
                harvest_date=harvest_date,
                cur=cur,
            )
        ).strip()

        account_fields = (
            "biological_asset_account_code",
            "produce_inventory_account_code",
            "fair_value_gain_account_code",
            "fair_value_loss_account_code",
        )

        accounts = []
        for field_name in account_fields:
            code = str(payload.get(field_name) or "").strip() or None
            if code:
                self._ias41_validate_account_code(company_id, code, cur=cur)
            accounts.append(code)

        values = (
            number,
            harvest_date,
            recognition_date,
            batch_id,
            asset_id,
            int(target["asset_class_id"]),
            product_id,
            int(product["inventory_item_id"]),
            self._ias41_optional_int(
                payload.get("location_id")
                or target.get("location_id")
            ),
            self._ias41_optional_int(payload.get("season_id")),
            quantity,
            str(
                payload.get("quantity_unit")
                or product.get("quantity_unit")
                or target.get("quantity_unit")
                or ""
            ).strip() or None,
            self._ias41_optional_float(payload.get("harvested_weight")),
            str(payload.get("weight_unit") or "").strip() or None,
            fair_value_per_unit,
            gross,
            costs_per_unit,
            costs,
            inventory_value,
            released,
            gain,
            loss,
            *accounts,
            str(payload.get("reference") or "").strip() or None,
            str(payload.get("description") or "").strip() or None,
            self._ias41_json_value(payload.get("metadata")),
        )

        if harvest_id:
            row = self.fetch_one(
                f"""
                UPDATE {schema}.ias41_harvests SET
                    harvest_number=%s,harvest_date=%s,recognition_date=%s,
                    batch_id=%s,biological_asset_id=%s,asset_class_id=%s,
                    product_id=%s,inventory_item_id=%s,location_id=%s,season_id=%s,
                    harvested_quantity=%s,quantity_unit=%s,
                    harvested_weight=%s,weight_unit=%s,
                    fair_value_per_unit=%s,gross_fair_value=%s,
                    costs_to_sell_per_unit=%s,costs_to_sell_amount=%s,
                    inventory_value=%s,biological_value_released=%s,
                    harvest_gain=%s,harvest_loss=%s,
                    biological_asset_account_code=%s,
                    produce_inventory_account_code=%s,
                    fair_value_gain_account_code=%s,
                    fair_value_loss_account_code=%s,
                    status='calculated',reference=%s,description=%s,
                    metadata=%s::jsonb,updated_at=NOW(),updated_by_user_id=%s
                WHERE company_id=%s AND id=%s
                AND status IN ('draft','calculated')
                RETURNING *
                """,
                values + (user_id, company_id, int(harvest_id)),
                cur=cur,
            )
        else:
            row = self.fetch_one(
                f"""
                INSERT INTO {schema}.ias41_harvests (
                    company_id,harvest_number,harvest_date,recognition_date,
                    batch_id,biological_asset_id,asset_class_id,
                    product_id,inventory_item_id,location_id,season_id,
                    harvested_quantity,quantity_unit,harvested_weight,weight_unit,
                    fair_value_per_unit,gross_fair_value,
                    costs_to_sell_per_unit,costs_to_sell_amount,
                    inventory_value,biological_value_released,
                    harvest_gain,harvest_loss,
                    biological_asset_account_code,produce_inventory_account_code,
                    fair_value_gain_account_code,fair_value_loss_account_code,
                    status,reference,description,metadata,
                    created_at,created_by_user_id,updated_at,updated_by_user_id
                )
                VALUES (
                    %s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,
                    %s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,
                    'calculated',%s,%s,%s::jsonb,NOW(),%s,NOW(),%s
                )
                RETURNING *
                """,
                (company_id,) + values + (user_id, user_id),
                cur=cur,
            )

        if not row:
            raise ValueError("Harvest was not saved.")

        self.execute_sql(
            f"""
            DELETE FROM {schema}.ias41_harvest_previews
            WHERE company_id=%s AND harvest_id=%s
            """,
            (company_id, int(row["id"])),
            cur=cur,
        )

        return self.ias41_harvest_get(
            company_id,
            int(row["id"]),
            cur=cur,
        ) or {}

    def ias41_harvest_preview(
        self,
        company_id: int,
        harvest_id: int,
        *,
        user_id=None,
        save_preview=True,
        cur=None,
    ) -> dict:
        company_id = int(company_id)
        schema = self._ias41_company_guard(company_id, cur=cur)
        harvest = self.ias41_harvest_get(company_id, harvest_id, cur=cur)

        if not harvest:
            raise ValueError("Harvest was not found.")

        if harvest.get("status") in {"posted", "cancelled", "reversed"}:
            raise ValueError("Preview is unavailable for this harvest status.")

        role = (
            "ias41_biological_asset_noncurrent"
            if harvest.get("current_noncurrent") == "noncurrent"
            else "ias41_biological_asset_current"
        )

        asset_account = self.ias41_resolve_account(
            company_id,
            role,
            asset_class_id=harvest.get("asset_class_id"),
            override_code=harvest.get("biological_asset_account_code"),
            cur=cur,
        )

        inventory_account = self.ias41_resolve_account(
            company_id,
            "ias41_agricultural_produce_inventory",
            asset_class_id=harvest.get("asset_class_id"),
            product_id=harvest.get("product_id"),
            override_code=harvest.get("produce_inventory_account_code"),
            cur=cur,
        )

        missing, lines = [], []
        description = (
            harvest.get("description")
            or f"IAS 41 harvest {harvest.get('harvest_number')}"
        )

        if not asset_account:
            missing.append({"role_code": role})
        if not inventory_account:
            missing.append({
                "role_code": "ias41_agricultural_produce_inventory"
            })

        inventory_value = round(float(harvest.get("inventory_value") or 0), 2)
        released = round(
            float(harvest.get("biological_value_released") or 0),
            2,
        )
        gain = round(float(harvest.get("harvest_gain") or 0), 2)
        loss = round(float(harvest.get("harvest_loss") or 0), 2)

        if inventory_account and inventory_value:
            lines.append({
                "role_code": "ias41_agricultural_produce_inventory",
                "account_code": inventory_account.get("code"),
                "account_name": inventory_account.get("name"),
                "description": description,
                "debit": inventory_value,
                "credit": 0,
                "resolution_source": inventory_account.get("resolution_source"),
            })

        if asset_account and released:
            lines.append({
                "role_code": role,
                "account_code": asset_account.get("code"),
                "account_name": asset_account.get("name"),
                "description": description,
                "debit": 0,
                "credit": released,
                "resolution_source": asset_account.get("resolution_source"),
            })

        if gain:
            gain_account = self.ias41_resolve_account(
                company_id,
                "ias41_fair_value_gain",
                asset_class_id=harvest.get("asset_class_id"),
                override_code=harvest.get("fair_value_gain_account_code"),
                cur=cur,
            )

            if not gain_account:
                missing.append({"role_code": "ias41_fair_value_gain"})
            else:
                lines.append({
                    "role_code": "ias41_fair_value_gain",
                    "account_code": gain_account.get("code"),
                    "account_name": gain_account.get("name"),
                    "description": description,
                    "debit": 0,
                    "credit": gain,
                    "resolution_source": gain_account.get("resolution_source"),
                })

        if loss:
            loss_account = self.ias41_resolve_account(
                company_id,
                "ias41_fair_value_loss",
                asset_class_id=harvest.get("asset_class_id"),
                override_code=harvest.get("fair_value_loss_account_code"),
                cur=cur,
            )

            if not loss_account:
                missing.append({"role_code": "ias41_fair_value_loss"})
            else:
                lines.append({
                    "role_code": "ias41_fair_value_loss",
                    "account_code": loss_account.get("code"),
                    "account_name": loss_account.get("name"),
                    "description": description,
                    "debit": loss,
                    "credit": 0,
                    "resolution_source": loss_account.get("resolution_source"),
                })

        debit = round(sum(float(x.get("debit") or 0) for x in lines), 2)
        credit = round(sum(float(x.get("credit") or 0) for x in lines), 2)
        ready = bool(lines and not missing and abs(debit - credit) < 0.01)

        preview = {
            "harvest_id": int(harvest_id),
            "harvest_number": harvest.get("harvest_number"),
            "ready_to_post": ready,
            "total_debit": debit,
            "total_credit": credit,
            "balanced": abs(debit - credit) < 0.01,
            "missing_mappings": missing,
            "invalid_accounts": [],
            "journal_lines": lines,
        }

        if save_preview:
            version = self.fetch_one(
                f"""
                SELECT COALESCE(MAX(preview_version),0)+1 AS next_version
                FROM {schema}.ias41_harvest_previews
                WHERE company_id=%s AND harvest_id=%s
                """,
                (company_id, int(harvest_id)),
                cur=cur,
            ) or {}

            self.execute_sql(
                f"""
                INSERT INTO {schema}.ias41_harvest_previews (
                    company_id,harvest_id,preview_version,
                    ready_to_post,total_debit,total_credit,
                    missing_mappings,invalid_accounts,journal_lines,
                    generated_at,generated_by_user_id
                )
                VALUES (
                    %s,%s,%s,%s,%s,%s,
                    %s::jsonb,%s::jsonb,%s::jsonb,NOW(),%s
                )
                """,
                (
                    company_id,
                    int(harvest_id),
                    int(version.get("next_version") or 1),
                    ready,
                    debit,
                    credit,
                    self._ias41_json_value(missing),
                    self._ias41_json_value([]),
                    self._ias41_json_value(lines),
                    user_id,
                ),
                cur=cur,
            )

        return preview

    def ias41_harvest_approve(
        self,
        company_id: int,
        harvest_id: int,
        *,
        user_id=None,
        cur=None,
    ) -> dict:
        company_id = int(company_id)
        schema = self._ias41_company_guard(company_id, cur=cur)
        harvest = self.ias41_harvest_get(company_id, harvest_id, cur=cur)

        if not harvest or harvest.get("status") != "calculated":
            raise ValueError("Only calculated harvests can be approved.")

        preview = self.ias41_harvest_preview(
            company_id,
            harvest_id,
            user_id=user_id,
            cur=cur,
        )

        if not preview.get("ready_to_post"):
            raise ValueError("Harvest journal preview is incomplete.")

        row = self.fetch_one(
            f"""
            UPDATE {schema}.ias41_harvests
            SET status='approved',
                approved_at=NOW(),
                approved_by_user_id=%s,
                updated_at=NOW(),
                updated_by_user_id=%s
            WHERE company_id=%s
            AND id=%s
            AND status='calculated'
            RETURNING *
            """,
            (user_id, user_id, company_id, int(harvest_id)),
            cur=cur,
        )

        return {
            "harvest": self._ias41_serialise(row),
            "preview": preview,
        }

    def _ias41_post_harvest_inventory(
        self,
        company_id: int,
        harvest: dict,
        *,
        user_id=None,
        cur=None,
    ) -> int | None:
        entry = {
            "item_id": int(harvest["inventory_item_id"]),
            "movement_date": harvest["recognition_date"],
            "movement_type": "receipt",
            "quantity": float(harvest["harvested_quantity"]),
            "unit_cost": (
                float(harvest["inventory_value"])
                / float(harvest["harvested_quantity"])
            ),
            "total_cost": float(harvest["inventory_value"]),
            "reference": harvest["harvest_number"],
            "source": "ias41_harvest",
            "source_id": int(harvest["id"]),
            "description": harvest.get("description") or "IAS 41 harvest",
            "created_by_user_id": user_id,
        }

        if hasattr(self, "record_inventory_movement"):
            return int(self.record_inventory_movement(
                company_id,
                entry,
                cur=cur,
            ))

        if hasattr(self, "create_inventory_movement"):
            return int(self.create_inventory_movement(
                company_id,
                entry,
                cur=cur,
            ))

        return None

    def ias41_harvest_post(
        self,
        company_id: int,
        harvest_id: int,
        *,
        user_id=None,
        cur=None,
    ) -> dict:
        company_id = int(company_id)
        schema = self._ias41_company_guard(company_id, cur=cur)
        harvest = self.ias41_harvest_get(company_id, harvest_id, cur=cur)

        if not harvest or harvest.get("status") != "approved":
            raise ValueError("Only approved harvests can be posted.")

        if harvest.get("journal_id"):
            raise ValueError("Harvest is already posted.")

        preview = self.ias41_harvest_preview(
            company_id,
            harvest_id,
            user_id=user_id,
            cur=cur,
        )

        journal_id = self._ias41_post_preview_journal(
            company_id,
            posting_date=harvest.get("recognition_date"),
            ref=harvest.get("harvest_number"),
            description=harvest.get("description") or "IAS 41 harvest",
            source="ias41_harvest",
            source_id=int(harvest_id),
            preview=preview,
            user_id=user_id,
            cur=cur,
        )

        movement_id = self._ias41_post_harvest_inventory(
            company_id,
            harvest,
            user_id=user_id,
            cur=cur,
        )

        quantity = float(harvest.get("harvested_quantity") or 0)
        released = float(harvest.get("biological_value_released") or 0)

        if harvest.get("batch_id"):
            target = self.fetch_one(
                f"""
                UPDATE {schema}.ias41_batches
                SET current_quantity=current_quantity-%s,
                    current_fair_value=GREATEST(current_fair_value-%s,0),
                    current_costs_to_sell=GREATEST(
                        current_costs_to_sell-%s,
                        0
                    ),
                    current_carrying_amount=GREATEST(
                        current_carrying_amount-%s,
                        0
                    ),
                    status=CASE
                        WHEN current_quantity-%s=0 THEN 'harvested'
                        ELSE status
                    END,
                    updated_at=NOW(),
                    updated_by_user_id=%s
                WHERE company_id=%s
                AND id=%s
                AND current_quantity>=%s
                RETURNING id
                """,
                (
                    quantity,
                    float(harvest.get("gross_fair_value") or 0),
                    float(harvest.get("costs_to_sell_amount") or 0),
                    released,
                    quantity,
                    user_id,
                    company_id,
                    int(harvest["batch_id"]),
                    quantity,
                ),
                cur=cur,
            )
        else:
            target = self.fetch_one(
                f"""
                UPDATE {schema}.ias41_biological_assets
                SET quantity=quantity-%s,
                    current_fair_value=GREATEST(current_fair_value-%s,0),
                    current_costs_to_sell=GREATEST(
                        current_costs_to_sell-%s,
                        0
                    ),
                    current_carrying_amount=GREATEST(
                        current_carrying_amount-%s,
                        0
                    ),
                    status=CASE
                        WHEN quantity-%s=0 THEN 'harvested'
                        ELSE status
                    END,
                    updated_at=NOW(),
                    updated_by_user_id=%s
                WHERE company_id=%s
                AND id=%s
                AND quantity>=%s
                RETURNING id
                """,
                (
                    quantity,
                    float(harvest.get("gross_fair_value") or 0),
                    float(harvest.get("costs_to_sell_amount") or 0),
                    released,
                    quantity,
                    user_id,
                    company_id,
                    int(harvest["biological_asset_id"]),
                    quantity,
                ),
                cur=cur,
            )

        if not target:
            raise ValueError(
                "Biological quantity changed and the harvest could not be posted."
            )

        row = self.fetch_one(
            f"""
            UPDATE {schema}.ias41_harvests
            SET status='posted',
                journal_id=%s,
                inventory_movement_id=%s,
                posted_at=NOW(),
                posted_by_user_id=%s,
                updated_at=NOW(),
                updated_by_user_id=%s
            WHERE company_id=%s
            AND id=%s
            AND status='approved'
            AND journal_id IS NULL
            RETURNING *
            """,
            (
                journal_id,
                movement_id,
                user_id,
                user_id,
                company_id,
                int(harvest_id),
            ),
            cur=cur,
        )

        return {
            "harvest": self._ias41_serialise(row),
            "journal_id": journal_id,
            "inventory_movement_id": movement_id,
            "preview": preview,
        }

    def ias41_harvest_delete(
        self,
        company_id: int,
        harvest_id: int,
        *,
        cur=None,
    ) -> bool:
        company_id = int(company_id)
        schema = self._ias41_company_guard(company_id, cur=cur)

        row = self.fetch_one(
            f"""
            DELETE FROM {schema}.ias41_harvests
            WHERE company_id=%s
            AND id=%s
            AND status IN ('draft','calculated')
            RETURNING id
            """,
            (company_id, int(harvest_id)),
            cur=cur,
        )

        return bool(row)


    def ias41_harvest_cancel(
        self,
        company_id: int,
        harvest_id: int,
        *,
        user_id=None,
        cur=None,
    ) -> dict:
        company_id = int(company_id)
        schema = self._ias41_company_guard(company_id, cur=cur)

        row = self.fetch_one(
            f"""
            UPDATE {schema}.ias41_harvests
            SET status='cancelled',
                updated_at=NOW(),
                updated_by_user_id=%s
            WHERE company_id=%s
            AND id=%s
            AND status IN ('draft','calculated','approved')
            RETURNING *
            """,
            (user_id, company_id, int(harvest_id)),
            cur=cur,
        )

        if not row:
            raise ValueError("Harvest cannot be cancelled.")

        return self._ias41_serialise(row) or {}

    IAS41_GRANT_TYPES={
        "unconditional","conditional","asset_related",
        "income_related","compensation",
    }


    def _ias41_next_grant_number(self,company_id:int,*,recognition_date=None,cur=None)->str:
        company_id=int(company_id)
        schema=self._ias41_company_guard(company_id,cur=cur)
        year=str(recognition_date or date.today().isoformat())[:4]
        prefix=f"IAS41-GRT-{year}-"

        row=self.fetch_one(
            f"""
            SELECT COALESCE(MAX(
                CASE WHEN grant_number~%s
                    THEN SUBSTRING(grant_number FROM '([0-9]+)$')::INTEGER
                    ELSE 0 END
            ),0)+1 AS next_number
            FROM {schema}.ias41_government_grants
            WHERE company_id=%s AND grant_number LIKE %s
            """,
            (f"^{prefix}[0-9]+$",company_id,f"{prefix}%"),
            cur=cur,
        ) or {}

        return f"{prefix}{int(row.get('next_number') or 1):05d}"


    def _ias41_next_grant_receipt_number(self,company_id:int,*,receipt_date=None,cur=None)->str:
        company_id=int(company_id)
        schema=self._ias41_company_guard(company_id,cur=cur)
        year=str(receipt_date or date.today().isoformat())[:4]
        prefix=f"IAS41-GRC-{year}-"

        row=self.fetch_one(
            f"""
            SELECT COALESCE(MAX(
                CASE WHEN receipt_number~%s
                    THEN SUBSTRING(receipt_number FROM '([0-9]+)$')::INTEGER
                    ELSE 0 END
            ),0)+1 AS next_number
            FROM {schema}.ias41_grant_receipts
            WHERE company_id=%s AND receipt_number LIKE %s
            """,
            (f"^{prefix}[0-9]+$",company_id,f"{prefix}%"),
            cur=cur,
        ) or {}

        return f"{prefix}{int(row.get('next_number') or 1):05d}"  

    def ias41_grants_list(
        self,company_id:int,*,status=None,date_from=None,date_to=None,cur=None,
    )->list[dict]:
        company_id=int(company_id)
        schema=self._ias41_company_guard(company_id,cur=cur)
        where,params=["g.company_id=%s"],[company_id]

        if status:
            where.append("g.status=%s")
            params.append(str(status).strip().lower())
        if date_from:
            where.append("g.recognition_date>=%s")
            params.append(date_from)
        if date_to:
            where.append("g.recognition_date<=%s")
            params.append(date_to)

        rows=self.fetch_all(
            f"""
            SELECT g.*,
                ac.class_code,ac.class_name,
                b.batch_code,b.batch_name,
                a.asset_number,a.asset_name,
                l.location_name,s.season_name,
                (
                    SELECT COUNT(*)
                    FROM {schema}.ias41_grant_receipts r
                    WHERE r.company_id=g.company_id
                        AND r.grant_id=g.id
                        AND r.status='posted'
                ) AS receipt_count
            FROM {schema}.ias41_government_grants g
            LEFT JOIN {schema}.ias41_asset_classes ac
            ON ac.company_id=g.company_id AND ac.id=g.asset_class_id
            LEFT JOIN {schema}.ias41_batches b
            ON b.company_id=g.company_id AND b.id=g.batch_id
            LEFT JOIN {schema}.ias41_biological_assets a
            ON a.company_id=g.company_id AND a.id=g.biological_asset_id
            LEFT JOIN {schema}.ias41_locations l
            ON l.company_id=g.company_id AND l.id=g.location_id
            LEFT JOIN {schema}.ias41_seasons s
            ON s.company_id=g.company_id AND s.id=g.season_id
            WHERE {" AND ".join(where)}
            ORDER BY COALESCE(g.recognition_date,g.approval_date) DESC,g.id DESC
            """,
            tuple(params),
            cur=cur,
        )
        return self._ias41_serialise_many(rows)


    def ias41_grant_get(self,company_id:int,grant_id:int,*,cur=None)->dict|None:
        company_id=int(company_id)
        schema=self._ias41_company_guard(company_id,cur=cur)

        grant=self.fetch_one(
            f"""
            SELECT g.*,
                ac.class_code,ac.class_name,
                b.batch_code,b.batch_name,
                a.asset_number,a.asset_name,
                l.location_name,s.season_name
            FROM {schema}.ias41_government_grants g
            LEFT JOIN {schema}.ias41_asset_classes ac
            ON ac.company_id=g.company_id AND ac.id=g.asset_class_id
            LEFT JOIN {schema}.ias41_batches b
            ON b.company_id=g.company_id AND b.id=g.batch_id
            LEFT JOIN {schema}.ias41_biological_assets a
            ON a.company_id=g.company_id AND a.id=g.biological_asset_id
            LEFT JOIN {schema}.ias41_locations l
            ON l.company_id=g.company_id AND l.id=g.location_id
            LEFT JOIN {schema}.ias41_seasons s
            ON s.company_id=g.company_id AND s.id=g.season_id
            WHERE g.company_id=%s AND g.id=%s
            LIMIT 1
            """,
            (company_id,int(grant_id)),
            cur=cur,
        )
        if not grant:
            return None

        receipts=self.fetch_all(
            f"""
            SELECT *
            FROM {schema}.ias41_grant_receipts
            WHERE company_id=%s AND grant_id=%s
            ORDER BY receipt_date DESC,id DESC
            """,
            (company_id,int(grant_id)),
            cur=cur,
        )

        out=self._ias41_serialise(grant) or {}
        out["receipts"]=self._ias41_serialise_many(receipts)
        return out

    def ias41_grant_save(
        self,
        company_id:int,
        payload:dict,
        *,
        grant_id:int|None=None,
        user_id:int|None=None,
        cur=None,
    )->dict:
        company_id=int(company_id)
        schema=self._ias41_company_guard(company_id,cur=cur)
        payload=payload or {}

        existing=self.ias41_grant_get(company_id,grant_id,cur=cur) if grant_id else None

        if grant_id and not existing:
            raise ValueError("Government grant was not found.")
        if existing and existing.get("status")!="draft":
            raise ValueError("Only draft government grants can be changed.")

        grant_type=str(payload.get("grant_type") or "conditional").strip().lower()
        if grant_type not in self.IAS41_GRANT_TYPES:
            raise ValueError("Invalid government grant type.")

        approved_amount=round(float(payload.get("approved_amount") or 0),2)
        if approved_amount<=0:
            raise ValueError("Approved grant amount must be greater than zero.")

        conditions_met=self._ias41_bool(payload.get("conditions_met"),False)

        if grant_type=="unconditional":
            conditions_met=True

        recognition_date=payload.get("recognition_date") or None
        approval_date=payload.get("approval_date") or date.today().isoformat()

        number=str(
            payload.get("grant_number")
            or (existing or {}).get("grant_number")
            or self._ias41_next_grant_number(
                company_id,
                recognition_date=recognition_date or approval_date,
                cur=cur,
            )
        ).strip()

        recognised_amount=round(float(
            (existing or {}).get("recognised_amount") or 0
        ),2)
        received_amount=round(float(
            (existing or {}).get("received_amount") or 0
        ),2)
        outstanding=max(round(recognised_amount-received_amount,2),0)

        accounts=[]
        for field_name in (
            "grant_receivable_account_code",
            "grant_income_account_code",
            "cash_account_code",
        ):
            code=str(payload.get(field_name) or "").strip() or None
            if code:
                self._ias41_validate_account_code(company_id,code,cur=cur)
            accounts.append(code)

        values=(
            number,
            str(payload.get("grant_name") or "").strip(),
            grant_type,
            str(payload.get("grantor_name") or "").strip() or None,
            str(payload.get("grantor_reference") or "").strip() or None,
            approval_date,
            recognition_date,
            payload.get("expected_receipt_date") or None,
            payload.get("expiry_date") or None,
            self._ias41_optional_int(payload.get("asset_class_id")),
            self._ias41_optional_int(payload.get("batch_id")),
            self._ias41_optional_int(payload.get("biological_asset_id")),
            self._ias41_optional_int(payload.get("location_id")),
            self._ias41_optional_int(payload.get("season_id")),
            str(payload.get("currency_code") or "").strip() or None,
            float(payload.get("exchange_rate") or 1),
            approved_amount,
            recognised_amount,
            received_amount,
            outstanding,
            conditions_met,
            payload.get("conditions_met_date") or None,
            str(payload.get("conditions_description") or "").strip() or None,
            *accounts,
            str(payload.get("reference") or "").strip() or None,
            str(payload.get("description") or "").strip() or None,
            self._ias41_json_value(payload.get("metadata")),
        )

        if not values[1]:
            raise ValueError("Government grant name is required.")

        if grant_id:
            row=self.fetch_one(
                f"""
                UPDATE {schema}.ias41_government_grants SET
                    grant_number=%s,grant_name=%s,grant_type=%s,
                    grantor_name=%s,grantor_reference=%s,
                    approval_date=%s,recognition_date=%s,
                    expected_receipt_date=%s,expiry_date=%s,
                    asset_class_id=%s,batch_id=%s,biological_asset_id=%s,
                    location_id=%s,season_id=%s,currency_code=%s,
                    exchange_rate=%s,approved_amount=%s,
                    recognised_amount=%s,received_amount=%s,outstanding_amount=%s,
                    conditions_met=%s,conditions_met_date=%s,
                    conditions_description=%s,
                    grant_receivable_account_code=%s,
                    grant_income_account_code=%s,cash_account_code=%s,
                    reference=%s,description=%s,metadata=%s::jsonb,
                    updated_at=NOW(),updated_by_user_id=%s
                WHERE company_id=%s AND id=%s AND status='draft'
                RETURNING *
                """,
                values+(user_id,company_id,int(grant_id)),
                cur=cur,
            )
        else:
            row=self.fetch_one(
                f"""
                INSERT INTO {schema}.ias41_government_grants (
                    company_id,grant_number,grant_name,grant_type,
                    grantor_name,grantor_reference,approval_date,
                    recognition_date,expected_receipt_date,expiry_date,
                    asset_class_id,batch_id,biological_asset_id,
                    location_id,season_id,currency_code,exchange_rate,
                    approved_amount,recognised_amount,received_amount,
                    outstanding_amount,conditions_met,conditions_met_date,
                    conditions_description,grant_receivable_account_code,
                    grant_income_account_code,cash_account_code,
                    status,reference,description,metadata,
                    created_at,created_by_user_id,updated_at,updated_by_user_id
                )
                VALUES (
                    %s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,
                    %s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,
                    'draft',%s,%s,%s::jsonb,NOW(),%s,NOW(),%s
                )
                RETURNING *
                """,
                (company_id,)+values+(user_id,user_id),
                cur=cur,
            )

        if not row:
            raise ValueError("Government grant was not saved.")

        self.execute_sql(
            f"""
            DELETE FROM {schema}.ias41_grant_previews
            WHERE company_id=%s AND grant_id=%s
            """,
            (company_id,int(row["id"])),
            cur=cur,
        )

        return self.ias41_grant_get(company_id,int(row["id"]),cur=cur) or {}

    def ias41_grant_approve(
        self,company_id:int,grant_id:int,*,user_id=None,cur=None,
    )->dict:
        company_id=int(company_id)
        schema=self._ias41_company_guard(company_id,cur=cur)
        grant=self.ias41_grant_get(company_id,grant_id,cur=cur)

        if not grant or grant.get("status")!="draft":
            raise ValueError("Only draft government grants can be approved.")

        row=self.fetch_one(
            f"""
            UPDATE {schema}.ias41_government_grants
            SET status='approved',
                approved_at=NOW(),approved_by_user_id=%s,
                updated_at=NOW(),updated_by_user_id=%s
            WHERE company_id=%s AND id=%s AND status='draft'
            RETURNING *
            """,
            (user_id,user_id,company_id,int(grant_id)),
            cur=cur,
        )

        if not row:
            raise ValueError("Government grant approval failed.")

        return self._ias41_serialise(row) or {}   

    def ias41_grant_recognition_preview(
        self,
        company_id:int,
        grant_id:int,
        *,
        user_id=None,
        save_preview=True,
        cur=None,
    )->dict:
        company_id=int(company_id)
        schema=self._ias41_company_guard(company_id,cur=cur)
        grant=self.ias41_grant_get(company_id,grant_id,cur=cur)

        if not grant:
            raise ValueError("Government grant was not found.")
        if grant.get("status") not in {"approved"}:
            raise ValueError("Only approved grants can be recognised.")
        if grant.get("grant_type")=="conditional" and not grant.get("conditions_met"):
            raise ValueError("Conditional grant conditions have not been met.")

        amount=round(float(grant.get("approved_amount") or 0),2)
        if amount<=0:
            raise ValueError("Grant recognition amount must be greater than zero.")

        receivable=self.ias41_resolve_account(
            company_id,
            "ias41_government_grant_receivable",
            asset_class_id=grant.get("asset_class_id"),
            override_code=grant.get("grant_receivable_account_code"),
            cur=cur,
        )
        income=self.ias41_resolve_account(
            company_id,
            "ias41_government_grant_income",
            asset_class_id=grant.get("asset_class_id"),
            override_code=grant.get("grant_income_account_code"),
            cur=cur,
        )

        missing=[]
        if not receivable:
            missing.append({"role_code":"ias41_government_grant_receivable"})
        if not income:
            missing.append({"role_code":"ias41_government_grant_income"})

        description=grant.get("description") or f"IAS 41 grant {grant.get('grant_number')}"
        lines=[]

        if receivable and income:
            lines=[
                {
                    "role_code":"ias41_government_grant_receivable",
                    "account_code":receivable.get("code"),
                    "account_name":receivable.get("name"),
                    "description":description,
                    "debit":amount,
                    "credit":0,
                    "resolution_source":receivable.get("resolution_source"),
                },
                {
                    "role_code":"ias41_government_grant_income",
                    "account_code":income.get("code"),
                    "account_name":income.get("name"),
                    "description":description,
                    "debit":0,
                    "credit":amount,
                    "resolution_source":income.get("resolution_source"),
                },
            ]

        debit=round(sum(float(x.get("debit") or 0) for x in lines),2)
        credit=round(sum(float(x.get("credit") or 0) for x in lines),2)
        ready=bool(lines and not missing and abs(debit-credit)<0.01)

        preview={
            "grant_id":int(grant_id),
            "grant_number":grant.get("grant_number"),
            "preview_type":"recognition",
            "ready_to_post":ready,
            "total_debit":debit,
            "total_credit":credit,
            "balanced":abs(debit-credit)<0.01,
            "missing_mappings":missing,
            "invalid_accounts":[],
            "journal_lines":lines,
        }

        if save_preview:
            version=self.fetch_one(
                f"""
                SELECT COALESCE(MAX(preview_version),0)+1 AS next_version
                FROM {schema}.ias41_grant_previews
                WHERE company_id=%s AND grant_id=%s
                AND preview_type='recognition'
                """,
                (company_id,int(grant_id)),
                cur=cur,
            ) or {}

            self.execute_sql(
                f"""
                INSERT INTO {schema}.ias41_grant_previews (
                    company_id,grant_id,receipt_id,preview_type,
                    preview_version,ready_to_post,total_debit,total_credit,
                    missing_mappings,invalid_accounts,journal_lines,
                    generated_at,generated_by_user_id
                )
                VALUES (
                    %s,%s,NULL,'recognition',%s,%s,%s,%s,
                    %s::jsonb,%s::jsonb,%s::jsonb,NOW(),%s
                )
                """,
                (
                    company_id,int(grant_id),int(version.get("next_version") or 1),
                    ready,debit,credit,
                    self._ias41_json_value(missing),
                    self._ias41_json_value([]),
                    self._ias41_json_value(lines),
                    user_id,
                ),
                cur=cur,
            )

        return preview

    def ias41_grant_recognise(
        self,company_id:int,grant_id:int,*,user_id=None,cur=None,
    )->dict:
        company_id=int(company_id)
        schema=self._ias41_company_guard(company_id,cur=cur)
        grant=self.ias41_grant_get(company_id,grant_id,cur=cur)

        if not grant or grant.get("status")!="approved":
            raise ValueError("Only approved grants can be recognised.")
        if grant.get("recognition_journal_id"):
            raise ValueError("Government grant is already recognised.")

        preview=self.ias41_grant_recognition_preview(
            company_id,grant_id,user_id=user_id,cur=cur
        )

        journal_id=self._ias41_post_preview_journal(
            company_id,
            posting_date=grant.get("recognition_date") or date.today().isoformat(),
            ref=grant.get("grant_number"),
            description=grant.get("description") or "IAS 41 government grant",
            source="ias41_grant",
            source_id=int(grant_id),
            preview=preview,
            currency=grant.get("currency_code"),
            user_id=user_id,
            cur=cur,
        )

        amount=round(float(grant.get("approved_amount") or 0),2)

        row=self.fetch_one(
            f"""
            UPDATE {schema}.ias41_government_grants
            SET status='recognised',
                recognised_amount=%s,
                outstanding_amount=%s,
                recognition_journal_id=%s,
                recognition_date=COALESCE(recognition_date,%s),
                recognised_at=NOW(),recognised_by_user_id=%s,
                updated_at=NOW(),updated_by_user_id=%s
            WHERE company_id=%s AND id=%s
            AND status='approved'
            AND recognition_journal_id IS NULL
            RETURNING *
            """,
            (
                amount,amount,journal_id,date.today().isoformat(),
                user_id,user_id,company_id,int(grant_id),
            ),
            cur=cur,
        )

        if not row:
            raise ValueError("Government grant recognition failed.")

        return {
            "grant":self._ias41_serialise(row),
            "journal_id":journal_id,
            "preview":preview,
        }

    def ias41_grant_receipt_save(
        self,
        company_id:int,
        grant_id:int,
        payload:dict,
        *,
        receipt_id:int|None=None,
        user_id=None,
        cur=None,
    )->dict:
        company_id=int(company_id)
        schema=self._ias41_company_guard(company_id,cur=cur)
        grant=self.ias41_grant_get(company_id,grant_id,cur=cur)
        payload=payload or {}

        if not grant:
            raise ValueError("Government grant was not found.")
        if grant.get("status") not in {"recognised","partially_received"}:
            raise ValueError("Grant must be recognised before receipt.")

        existing=None
        if receipt_id:
            existing=self.fetch_one(
                f"""
                SELECT *
                FROM {schema}.ias41_grant_receipts
                WHERE company_id=%s AND grant_id=%s AND id=%s
                """,
                (company_id,int(grant_id),int(receipt_id)),
                cur=cur,
            )
            if not existing:
                raise ValueError("Grant receipt was not found.")
            if existing.get("status")!="draft":
                raise ValueError("Only draft grant receipts can be changed.")

        amount=round(float(payload.get("amount") or 0),2)
        outstanding=round(float(grant.get("outstanding_amount") or 0),2)

        if amount<=0:
            raise ValueError("Receipt amount must be greater than zero.")
        if amount>outstanding:
            raise ValueError(
                f"Receipt exceeds outstanding grant amount: {outstanding:.2f}."
            )

        receipt_date=payload.get("receipt_date") or date.today().isoformat()
        number=str(
            payload.get("receipt_number")
            or (existing or {}).get("receipt_number")
            or self._ias41_next_grant_receipt_number(
                company_id,receipt_date=receipt_date,cur=cur
            )
        ).strip()

        cash_code=str(
            payload.get("cash_account_code")
            or grant.get("cash_account_code")
            or ""
        ).strip() or None

        receivable_code=str(
            payload.get("grant_receivable_account_code")
            or grant.get("grant_receivable_account_code")
            or ""
        ).strip() or None

        for code in (cash_code,receivable_code):
            if code:
                self._ias41_validate_account_code(company_id,code,cur=cur)

        values=(
            number,receipt_date,amount,
            str(payload.get("currency_code") or grant.get("currency_code") or "").strip() or None,
            float(payload.get("exchange_rate") or grant.get("exchange_rate") or 1),
            cash_code,receivable_code,
            str(payload.get("reference") or "").strip() or None,
            str(payload.get("description") or "").strip() or None,
            self._ias41_json_value(payload.get("metadata")),
        )

        if receipt_id:
            row=self.fetch_one(
                f"""
                UPDATE {schema}.ias41_grant_receipts SET
                    receipt_number=%s,receipt_date=%s,amount=%s,
                    currency_code=%s,exchange_rate=%s,
                    cash_account_code=%s,grant_receivable_account_code=%s,
                    reference=%s,description=%s,metadata=%s::jsonb,
                    updated_at=NOW(),updated_by_user_id=%s
                WHERE company_id=%s AND grant_id=%s AND id=%s AND status='draft'
                RETURNING *
                """,
                values+(user_id,company_id,int(grant_id),int(receipt_id)),
                cur=cur,
            )
        else:
            row=self.fetch_one(
                f"""
                INSERT INTO {schema}.ias41_grant_receipts (
                    company_id,grant_id,receipt_number,receipt_date,
                    amount,currency_code,exchange_rate,
                    cash_account_code,grant_receivable_account_code,
                    status,reference,description,metadata,
                    created_at,created_by_user_id,updated_at,updated_by_user_id
                )
                VALUES (
                    %s,%s,%s,%s,%s,%s,%s,%s,%s,
                    'draft',%s,%s,%s::jsonb,NOW(),%s,NOW(),%s
                )
                RETURNING *
                """,
                (company_id,int(grant_id))+values+(user_id,user_id),
                cur=cur,
            )

        return self._ias41_serialise(row) or {}

    def ias41_grant_receipt_preview(
        self,
        company_id:int,
        receipt_id:int,
        *,
        user_id=None,
        save_preview=True,
        cur=None,
    )->dict:
        company_id=int(company_id)
        schema=self._ias41_company_guard(company_id,cur=cur)

        receipt=self.fetch_one(
            f"""
            SELECT r.*,g.asset_class_id,g.grant_number,g.grant_name,
                g.grant_receivable_account_code AS grant_receivable_override,
                g.cash_account_code AS grant_cash_override
            FROM {schema}.ias41_grant_receipts r
            JOIN {schema}.ias41_government_grants g
            ON g.company_id=r.company_id AND g.id=r.grant_id
            WHERE r.company_id=%s AND r.id=%s
            """,
            (company_id,int(receipt_id)),
            cur=cur,
        )

        if not receipt:
            raise ValueError("Grant receipt was not found.")
        if receipt.get("status")!="draft":
            raise ValueError("Only draft grant receipts can be previewed.")

        amount=round(float(receipt.get("amount") or 0),2)

        cash=self.ias41_resolve_account(
            company_id,
            "cash_bank",
            override_code=receipt.get("cash_account_code")
                or receipt.get("grant_cash_override"),
            cur=cur,
        )
        receivable=self.ias41_resolve_account(
            company_id,
            "ias41_government_grant_receivable",
            asset_class_id=receipt.get("asset_class_id"),
            override_code=receipt.get("grant_receivable_account_code")
                or receipt.get("grant_receivable_override"),
            cur=cur,
        )

        missing=[]
        if not cash:
            missing.append({"role_code":"cash_bank"})
        if not receivable:
            missing.append({"role_code":"ias41_government_grant_receivable"})

        description=receipt.get("description") or f"Grant receipt {receipt.get('receipt_number')}"
        lines=[]

        if cash and receivable:
            lines=[
                {
                    "role_code":"cash_bank",
                    "account_code":cash.get("code"),
                    "account_name":cash.get("name"),
                    "description":description,
                    "debit":amount,
                    "credit":0,
                    "resolution_source":cash.get("resolution_source"),
                },
                {
                    "role_code":"ias41_government_grant_receivable",
                    "account_code":receivable.get("code"),
                    "account_name":receivable.get("name"),
                    "description":description,
                    "debit":0,
                    "credit":amount,
                    "resolution_source":receivable.get("resolution_source"),
                },
            ]

        debit=round(sum(float(x.get("debit") or 0) for x in lines),2)
        credit=round(sum(float(x.get("credit") or 0) for x in lines),2)
        ready=bool(lines and not missing and abs(debit-credit)<0.01)

        preview={
            "receipt_id":int(receipt_id),
            "receipt_number":receipt.get("receipt_number"),
            "grant_id":receipt.get("grant_id"),
            "preview_type":"receipt",
            "ready_to_post":ready,
            "total_debit":debit,
            "total_credit":credit,
            "balanced":abs(debit-credit)<0.01,
            "missing_mappings":missing,
            "invalid_accounts":[],
            "journal_lines":lines,
        }

        if save_preview:
            version=self.fetch_one(
                f"""
                SELECT COALESCE(MAX(preview_version),0)+1 AS next_version
                FROM {schema}.ias41_grant_previews
                WHERE company_id=%s AND receipt_id=%s
                AND preview_type='receipt'
                """,
                (company_id,int(receipt_id)),
                cur=cur,
            ) or {}

            self.execute_sql(
                f"""
                INSERT INTO {schema}.ias41_grant_previews (
                    company_id,grant_id,receipt_id,preview_type,
                    preview_version,ready_to_post,total_debit,total_credit,
                    missing_mappings,invalid_accounts,journal_lines,
                    generated_at,generated_by_user_id
                )
                VALUES (
                    %s,NULL,%s,'receipt',%s,%s,%s,%s,
                    %s::jsonb,%s::jsonb,%s::jsonb,NOW(),%s
                )
                """,
                (
                    company_id,int(receipt_id),int(version.get("next_version") or 1),
                    ready,debit,credit,
                    self._ias41_json_value(missing),
                    self._ias41_json_value([]),
                    self._ias41_json_value(lines),
                    user_id,
                ),
                cur=cur,
            )

        return preview


    def ias41_grant_receipt_post(
        self,company_id:int,receipt_id:int,*,user_id=None,cur=None,
    )->dict:
        company_id=int(company_id)
        schema=self._ias41_company_guard(company_id,cur=cur)

        receipt=self.fetch_one(
            f"""
            SELECT r.*,g.grant_number,g.grant_name,
                g.recognised_amount,g.received_amount,g.outstanding_amount
            FROM {schema}.ias41_grant_receipts r
            JOIN {schema}.ias41_government_grants g
            ON g.company_id=r.company_id AND g.id=r.grant_id
            WHERE r.company_id=%s AND r.id=%s
            """,
            (company_id,int(receipt_id)),
            cur=cur,
        )

        if not receipt or receipt.get("status")!="draft":
            raise ValueError("Only draft grant receipts can be posted.")

        preview=self.ias41_grant_receipt_preview(
            company_id,receipt_id,user_id=user_id,cur=cur
        )

        journal_id=self._ias41_post_preview_journal(
            company_id,
            posting_date=receipt.get("receipt_date"),
            ref=receipt.get("receipt_number"),
            description=receipt.get("description") or "IAS 41 grant receipt",
            source="ias41_grant_receipt",
            source_id=int(receipt_id),
            preview=preview,
            currency=receipt.get("currency_code"),
            user_id=user_id,
            cur=cur,
        )

        amount=round(float(receipt.get("amount") or 0),2)
        received=round(float(receipt.get("received_amount") or 0)+amount,2)
        recognised=round(float(receipt.get("recognised_amount") or 0),2)
        outstanding=max(round(recognised-received,2),0)
        grant_status="received" if outstanding<=0 else "partially_received"

        posted=self.fetch_one(
            f"""
            UPDATE {schema}.ias41_grant_receipts
            SET status='posted',journal_id=%s,
                posted_at=NOW(),posted_by_user_id=%s,
                updated_at=NOW(),updated_by_user_id=%s
            WHERE company_id=%s AND id=%s
            AND status='draft' AND journal_id IS NULL
            RETURNING *
            """,
            (journal_id,user_id,user_id,company_id,int(receipt_id)),
            cur=cur,
        )

        if not posted:
            raise ValueError("Grant receipt posting failed.")

        grant=self.fetch_one(
            f"""
            UPDATE {schema}.ias41_government_grants
            SET received_amount=%s,outstanding_amount=%s,status=%s,
                receipt_journal_id=%s,
                received_at=CASE WHEN %s='received' THEN NOW() ELSE received_at END,
                received_by_user_id=CASE
                    WHEN %s='received' THEN %s
                    ELSE received_by_user_id
                END,
                updated_at=NOW(),updated_by_user_id=%s
            WHERE company_id=%s AND id=%s
            RETURNING *
            """,
            (
                received,outstanding,grant_status,journal_id,
                grant_status,grant_status,user_id,user_id,
                company_id,int(receipt["grant_id"]),
            ),
            cur=cur,
        )

        return {
            "receipt":self._ias41_serialise(posted),
            "grant":self._ias41_serialise(grant),
            "journal_id":journal_id,
            "preview":preview,
        }

    def ias41_grant_delete(self,company_id:int,grant_id:int,*,cur=None)->bool:
        company_id=int(company_id)
        schema=self._ias41_company_guard(company_id,cur=cur)

        row=self.fetch_one(
            f"""
            DELETE FROM {schema}.ias41_government_grants
            WHERE company_id=%s AND id=%s AND status='draft'
            RETURNING id
            """,
            (company_id,int(grant_id)),
            cur=cur,
        )
        return bool(row)


    def ias41_grant_cancel(
        self,company_id:int,grant_id:int,*,user_id=None,cur=None,
    )->dict:
        company_id=int(company_id)
        schema=self._ias41_company_guard(company_id,cur=cur)

        row=self.fetch_one(
            f"""
            UPDATE {schema}.ias41_government_grants
            SET status='cancelled',updated_at=NOW(),updated_by_user_id=%s
            WHERE company_id=%s AND id=%s
            AND status IN ('draft','approved')
            RETURNING *
            """,
            (user_id,company_id,int(grant_id)),
            cur=cur,
        )

        if not row:
            raise ValueError("Government grant cannot be cancelled.")

        return self._ias41_serialise(row) or {}

    IAS41_REPORT_KEYS={
        "dashboard_summary",
        "biological_asset_register",
        "movement_reconciliation",
        "fair_value_gain_loss",
        "valuation_history",
        "harvest_report",
        "government_grants",
        "event_history",
        "ias41_disclosure",
    }


    def _ias41_report_dates(
        self,
        *,
        date_from=None,
        date_to=None,
        as_of=None,
    )->dict:
        as_of=str(as_of or date_to or date.today().isoformat())
        date_to=str(date_to or as_of)
        date_from=str(date_from or f"{date_to[:4]}-01-01")

        if date_from>date_to:
            raise ValueError("Report start date cannot be after end date.")

        return {
            "date_from":date_from,
            "date_to":date_to,
            "as_of":as_of,
        }

    def ias41_biological_asset_register_report(
        self,
        company_id:int,
        *,
        as_of=None,
        asset_class_id=None,
        location_id=None,
        status=None,
        cur=None,
    )->dict:
        company_id=int(company_id)
        schema=self._ias41_company_guard(company_id,cur=cur)
        as_of=str(as_of or date.today().isoformat())

        where=["x.company_id=%s"]
        params=[company_id]

        if asset_class_id:
            where.append("x.asset_class_id=%s")
            params.append(int(asset_class_id))

        if location_id:
            where.append("x.location_id=%s")
            params.append(int(location_id))

        if status:
            where.append("x.status=%s")
            params.append(str(status).strip().lower())

        rows=self.fetch_all(
            f"""
            SELECT *
            FROM(
                SELECT
                    'batch'::text AS record_type,
                    b.id,
                    b.batch_code AS record_number,
                    b.batch_name AS record_name,
                    b.asset_class_id,
                    ac.class_code,
                    ac.class_name,
                    ac.asset_nature,
                    ac.current_noncurrent,
                    b.location_id,
                    l.location_code,
                    l.location_name,
                    b.season_id,
                    s.season_code,
                    s.season_name,
                    b.current_quantity AS quantity,
                    b.quantity_unit,
                    b.current_weight AS weight,
                    b.weight_unit,
                    b.current_fair_value,
                    b.current_costs_to_sell,
                    b.current_carrying_amount,
                    b.status,
                    b.start_date AS recognition_date
                FROM {schema}.ias41_batches b
                JOIN {schema}.ias41_asset_classes ac
                ON ac.company_id=b.company_id
                AND ac.id=b.asset_class_id
                LEFT JOIN {schema}.ias41_locations l
                ON l.company_id=b.company_id
                AND l.id=b.location_id
                LEFT JOIN {schema}.ias41_seasons s
                ON s.company_id=b.company_id
                AND s.id=b.season_id
                WHERE b.company_id=%s
                AND b.start_date<=%s

                UNION ALL

                SELECT
                    'individual'::text AS record_type,
                    a.id,
                    a.asset_number AS record_number,
                    a.asset_name AS record_name,
                    a.asset_class_id,
                    ac.class_code,
                    ac.class_name,
                    ac.asset_nature,
                    ac.current_noncurrent,
                    a.location_id,
                    l.location_code,
                    l.location_name,
                    NULL::integer AS season_id,
                    NULL::text AS season_code,
                    NULL::text AS season_name,
                    a.quantity,
                    a.quantity_unit,
                    a.current_weight AS weight,
                    a.weight_unit,
                    a.current_fair_value,
                    a.current_costs_to_sell,
                    a.current_carrying_amount,
                    a.status,
                    a.acquisition_date AS recognition_date
                FROM {schema}.ias41_biological_assets a
                JOIN {schema}.ias41_asset_classes ac
                ON ac.company_id=a.company_id
                AND ac.id=a.asset_class_id
                LEFT JOIN {schema}.ias41_locations l
                ON l.company_id=a.company_id
                AND l.id=a.location_id
                WHERE a.company_id=%s
                AND a.acquisition_date<=%s
            )x
            WHERE {" AND ".join(where)}
            ORDER BY x.class_name,x.record_number
            """,
            (
                company_id,as_of,
                company_id,as_of,
                *params,
            ),
            cur=cur,
        )

        items=self._ias41_serialise_many(rows)

        return {
            "report_key":"biological_asset_register",
            "report_name":"Biological Asset Register",
            "as_of":as_of,
            "items":items,
            "totals":{
                "record_count":len(items),
                "quantity":sum(float(x.get("quantity") or 0) for x in items),
                "fair_value":round(sum(
                    float(x.get("current_fair_value") or 0) for x in items
                ),2),
                "costs_to_sell":round(sum(
                    float(x.get("current_costs_to_sell") or 0) for x in items
                ),2),
                "carrying_amount":round(sum(
                    float(x.get("current_carrying_amount") or 0) for x in items
                ),2),
            },
        }

    def ias41_movement_reconciliation_report(
        self,
        company_id:int,
        *,
        date_from=None,
        date_to=None,
        cur=None,
    )->dict:
        company_id=int(company_id)
        schema=self._ias41_company_guard(company_id,cur=cur)
        period=self._ias41_report_dates(date_from=date_from,date_to=date_to)

        opening=self.fetch_one(
            f"""
            SELECT COALESCE(SUM(amount),0) AS amount
            FROM(
                SELECT l.new_carrying_amount AS amount
                FROM {schema}.ias41_valuation_lines l
                JOIN {schema}.ias41_valuation_runs r
                ON r.company_id=l.company_id
                AND r.id=l.valuation_run_id
                WHERE r.company_id=%s
                AND r.status='posted'
                AND r.valuation_date<%s

                UNION ALL

                SELECT a.carrying_amount
                FROM {schema}.ias41_acquisition_lines a
                JOIN {schema}.ias41_acquisitions h
                ON h.company_id=a.company_id
                AND h.id=a.acquisition_id
                WHERE h.company_id=%s
                AND h.status='posted'
                AND h.recognition_date<%s
            )x
            """,
            (
                company_id,period["date_from"],
                company_id,period["date_from"],
            ),
            cur=cur,
        ) or {}

        acquisitions=self.fetch_one(
            f"""
            SELECT
                COALESCE(SUM(CASE
                    WHEN transaction_type='purchase'
                    THEN carrying_amount ELSE 0 END),0) AS purchases,
                COALESCE(SUM(CASE
                    WHEN transaction_type='birth'
                    THEN carrying_amount ELSE 0 END),0) AS births,
                COALESCE(SUM(CASE
                    WHEN transaction_type='planting'
                    THEN carrying_amount ELSE 0 END),0) AS planting,
                COALESCE(SUM(CASE
                    WHEN transaction_type IN(
                        'donation','transfer_in','opening_balance','other'
                    )
                    THEN carrying_amount ELSE 0 END),0) AS other_additions
            FROM {schema}.ias41_acquisitions
            WHERE company_id=%s
            AND status='posted'
            AND recognition_date BETWEEN %s AND %s
            """,
            (
                company_id,
                period["date_from"],
                period["date_to"],
            ),
            cur=cur,
        ) or {}

        valuations=self.fetch_one(
            f"""
            SELECT
                COALESCE(SUM(total_gain),0) AS fair_value_gains,
                COALESCE(SUM(total_loss),0) AS fair_value_losses
            FROM {schema}.ias41_valuation_runs
            WHERE company_id=%s
            AND status='posted'
            AND valuation_date BETWEEN %s AND %s
            """,
            (
                company_id,
                period["date_from"],
                period["date_to"],
            ),
            cur=cur,
        ) or {}

        harvest=self.fetch_one(
            f"""
            SELECT
                COALESCE(SUM(biological_value_released),0) AS harvest_transfer,
                COALESCE(SUM(harvest_gain),0) AS harvest_gain,
                COALESCE(SUM(harvest_loss),0) AS harvest_loss
            FROM {schema}.ias41_harvests
            WHERE company_id=%s
            AND status='posted'
            AND recognition_date BETWEEN %s AND %s
            """,
            (
                company_id,
                period["date_from"],
                period["date_to"],
            ),
            cur=cur,
        ) or {}

        events=self.fetch_one(
            f"""
            SELECT
                COALESCE(SUM(CASE
                    WHEN event_type='mortality'
                    THEN carrying_amount_released ELSE 0 END),0) AS mortality_loss
            FROM {schema}.ias41_events
            WHERE company_id=%s
            AND status='posted'
            AND event_date BETWEEN %s AND %s
            """,
            (
                company_id,
                period["date_from"],
                period["date_to"],
            ),
            cur=cur,
        ) or {}

        closing=self.fetch_one(
            f"""
            SELECT
                COALESCE((
                    SELECT SUM(current_carrying_amount)
                    FROM {schema}.ias41_batches
                    WHERE company_id=%s
                ),0)
                +
                COALESCE((
                    SELECT SUM(current_carrying_amount)
                    FROM {schema}.ias41_biological_assets
                    WHERE company_id=%s
                ),0) AS amount
            """,
            (company_id,company_id),
            cur=cur,
        ) or {}

        movement={
            "opening_carrying_amount":round(float(opening.get("amount") or 0),2),
            "purchases":round(float(acquisitions.get("purchases") or 0),2),
            "births":round(float(acquisitions.get("births") or 0),2),
            "planting":round(float(acquisitions.get("planting") or 0),2),
            "other_additions":round(float(
                acquisitions.get("other_additions") or 0
            ),2),
            "fair_value_gains":round(float(
                valuations.get("fair_value_gains") or 0
            ),2),
            "fair_value_losses":round(float(
                valuations.get("fair_value_losses") or 0
            ),2),
            "harvest_transfer":round(float(
                harvest.get("harvest_transfer") or 0
            ),2),
            "harvest_gain":round(float(harvest.get("harvest_gain") or 0),2),
            "harvest_loss":round(float(harvest.get("harvest_loss") or 0),2),
            "mortality_loss":round(float(events.get("mortality_loss") or 0),2),
            "closing_carrying_amount":round(float(closing.get("amount") or 0),2),
        }

        calculated_closing=round(
            movement["opening_carrying_amount"]
            +movement["purchases"]
            +movement["births"]
            +movement["planting"]
            +movement["other_additions"]
            +movement["fair_value_gains"]
            +movement["harvest_gain"]
            -movement["fair_value_losses"]
            -movement["harvest_loss"]
            -movement["harvest_transfer"]
            -movement["mortality_loss"],
            2,
        )

        movement["calculated_closing_amount"]=calculated_closing
        movement["reconciliation_difference"]=round(
            movement["closing_carrying_amount"]-calculated_closing,
            2,
        )

        return {
            "report_key":"movement_reconciliation",
            "report_name":"Biological Asset Movement Reconciliation",
            **period,
            "movement":movement,
        }

    def ias41_fair_value_gain_loss_report(
        self,
        company_id:int,
        *,
        date_from=None,
        date_to=None,
        cur=None,
    )->dict:
        company_id=int(company_id)
        schema=self._ias41_company_guard(company_id,cur=cur)
        period=self._ias41_report_dates(date_from=date_from,date_to=date_to)

        rows=self.fetch_all(
            f"""
            SELECT
                r.id AS valuation_run_id,
                r.run_number,
                r.valuation_date,
                r.valuation_method,
                l.id AS valuation_line_id,
                l.batch_id,
                l.biological_asset_id,
                ac.class_code,
                ac.class_name,
                b.batch_code,
                b.batch_name,
                a.asset_number,
                a.asset_name,
                l.previous_carrying_amount,
                l.new_carrying_amount,
                l.gain_amount,
                l.loss_amount,
                l.market_source,
                l.market_reference,
                l.observable_input
            FROM {schema}.ias41_valuation_lines l
            JOIN {schema}.ias41_valuation_runs r
            ON r.company_id=l.company_id
            AND r.id=l.valuation_run_id
            JOIN {schema}.ias41_asset_classes ac
            ON ac.company_id=l.company_id
            AND ac.id=l.asset_class_id
            LEFT JOIN {schema}.ias41_batches b
            ON b.company_id=l.company_id
            AND b.id=l.batch_id
            LEFT JOIN {schema}.ias41_biological_assets a
            ON a.company_id=l.company_id
            AND a.id=l.biological_asset_id
            WHERE r.company_id=%s
            AND r.status='posted'
            AND r.valuation_date BETWEEN %s AND %s
            ORDER BY r.valuation_date,r.id,l.line_number
            """,
            (
                company_id,
                period["date_from"],
                period["date_to"],
            ),
            cur=cur,
        )

        items=self._ias41_serialise_many(rows)

        return {
            "report_key":"fair_value_gain_loss",
            "report_name":"Fair-Value Gain and Loss Report",
            **period,
            "items":items,
            "totals":{
                "previous_carrying_amount":round(sum(
                    float(x.get("previous_carrying_amount") or 0)
                    for x in items
                ),2),
                "new_carrying_amount":round(sum(
                    float(x.get("new_carrying_amount") or 0)
                    for x in items
                ),2),
                "gain_amount":round(sum(
                    float(x.get("gain_amount") or 0)
                    for x in items
                ),2),
                "loss_amount":round(sum(
                    float(x.get("loss_amount") or 0)
                    for x in items
                ),2),
            },
        }

    def ias41_valuation_history_report(
        self,
        company_id:int,
        *,
        date_from=None,
        date_to=None,
        status=None,
        cur=None,
    )->dict:
        company_id=int(company_id)
        schema=self._ias41_company_guard(company_id,cur=cur)
        period=self._ias41_report_dates(date_from=date_from,date_to=date_to)

        where=[
            "r.company_id=%s",
            "r.valuation_date BETWEEN %s AND %s",
        ]
        params=[
            company_id,
            period["date_from"],
            period["date_to"],
        ]

        if status:
            where.append("r.status=%s")
            params.append(str(status).strip().lower())

        rows=self.fetch_all(
            f"""
            SELECT r.*,
                (
                    SELECT COUNT(*)
                    FROM {schema}.ias41_valuation_lines l
                    WHERE l.company_id=r.company_id
                        AND l.valuation_run_id=r.id
                ) AS line_count
            FROM {schema}.ias41_valuation_runs r
            WHERE {" AND ".join(where)}
            ORDER BY r.valuation_date DESC,r.id DESC
            """,
            tuple(params),
            cur=cur,
        )

        items=self._ias41_serialise_many(rows)

        return {
            "report_key":"valuation_history",
            "report_name":"Valuation History",
            **period,
            "items":items,
            "totals":{
                "run_count":len(items),
                "fair_value":round(sum(
                    float(x.get("total_fair_value") or 0) for x in items
                ),2),
                "costs_to_sell":round(sum(
                    float(x.get("total_costs_to_sell") or 0) for x in items
                ),2),
                "gain":round(sum(
                    float(x.get("total_gain") or 0) for x in items
                ),2),
                "loss":round(sum(
                    float(x.get("total_loss") or 0) for x in items
                ),2),
            },
        }

    def ias41_harvest_report(
        self,
        company_id:int,
        *,
        date_from=None,
        date_to=None,
        product_id=None,
        cur=None,
    )->dict:
        company_id=int(company_id)
        schema=self._ias41_company_guard(company_id,cur=cur)
        period=self._ias41_report_dates(date_from=date_from,date_to=date_to)

        where=[
            "h.company_id=%s",
            "h.status='posted'",
            "h.recognition_date BETWEEN %s AND %s",
        ]
        params=[
            company_id,
            period["date_from"],
            period["date_to"],
        ]

        if product_id:
            where.append("h.product_id=%s")
            params.append(int(product_id))

        rows=self.fetch_all(
            f"""
            SELECT
                h.*,
                p.product_code,
                p.product_name,
                ac.class_code,
                ac.class_name,
                b.batch_code,
                b.batch_name,
                a.asset_number,
                a.asset_name,
                i.sku AS inventory_sku,
                i.name AS inventory_item_name
            FROM {schema}.ias41_harvests h
            JOIN {schema}.ias41_products p
            ON p.company_id=h.company_id
            AND p.id=h.product_id
            JOIN {schema}.ias41_asset_classes ac
            ON ac.company_id=h.company_id
            AND ac.id=h.asset_class_id
            LEFT JOIN {schema}.ias41_batches b
            ON b.company_id=h.company_id
            AND b.id=h.batch_id
            LEFT JOIN {schema}.ias41_biological_assets a
            ON a.company_id=h.company_id
            AND a.id=h.biological_asset_id
            LEFT JOIN {schema}.inventory_items i
            ON i.company_id=h.company_id
            AND i.id=h.inventory_item_id
            WHERE {" AND ".join(where)}
            ORDER BY h.recognition_date,h.id
            """,
            tuple(params),
            cur=cur,
        )

        items=self._ias41_serialise_many(rows)

        return {
            "report_key":"harvest_report",
            "report_name":"Harvest and IAS 2 Transfer Report",
            **period,
            "items":items,
            "totals":{
                "harvest_count":len(items),
                "quantity":sum(float(
                    x.get("harvested_quantity") or 0
                ) for x in items),
                "gross_fair_value":round(sum(
                    float(x.get("gross_fair_value") or 0) for x in items
                ),2),
                "costs_to_sell":round(sum(
                    float(x.get("costs_to_sell_amount") or 0) for x in items
                ),2),
                "inventory_value":round(sum(
                    float(x.get("inventory_value") or 0) for x in items
                ),2),
                "harvest_gain":round(sum(
                    float(x.get("harvest_gain") or 0) for x in items
                ),2),
                "harvest_loss":round(sum(
                    float(x.get("harvest_loss") or 0) for x in items
                ),2),
            },
        }

    def ias41_government_grants_report(
        self,
        company_id:int,
        *,
        date_from=None,
        date_to=None,
        status=None,
        cur=None,
    )->dict:
        company_id=int(company_id)
        schema=self._ias41_company_guard(company_id,cur=cur)
        period=self._ias41_report_dates(date_from=date_from,date_to=date_to)

        where=[
            "g.company_id=%s",
            "COALESCE(g.recognition_date,g.approval_date) BETWEEN %s AND %s",
        ]
        params=[
            company_id,
            period["date_from"],
            period["date_to"],
        ]

        if status:
            where.append("g.status=%s")
            params.append(str(status).strip().lower())

        rows=self.fetch_all(
            f"""
            SELECT
                g.*,
                ac.class_code,
                ac.class_name,
                b.batch_code,
                b.batch_name,
                a.asset_number,
                a.asset_name,
                (
                    SELECT COUNT(*)
                    FROM {schema}.ias41_grant_receipts r
                    WHERE r.company_id=g.company_id
                    AND r.grant_id=g.id
                    AND r.status='posted'
                ) AS receipt_count
            FROM {schema}.ias41_government_grants g
            LEFT JOIN {schema}.ias41_asset_classes ac
            ON ac.company_id=g.company_id
            AND ac.id=g.asset_class_id
            LEFT JOIN {schema}.ias41_batches b
            ON b.company_id=g.company_id
            AND b.id=g.batch_id
            LEFT JOIN {schema}.ias41_biological_assets a
            ON a.company_id=g.company_id
            AND a.id=g.biological_asset_id
            WHERE {" AND ".join(where)}
            ORDER BY COALESCE(g.recognition_date,g.approval_date),g.id
            """,
            tuple(params),
            cur=cur,
        )

        items=self._ias41_serialise_many(rows)

        return {
            "report_key":"government_grants",
            "report_name":"Government Grants Report",
            **period,
            "items":items,
            "totals":{
                "grant_count":len(items),
                "approved_amount":round(sum(
                    float(x.get("approved_amount") or 0) for x in items
                ),2),
                "recognised_amount":round(sum(
                    float(x.get("recognised_amount") or 0) for x in items
                ),2),
                "received_amount":round(sum(
                    float(x.get("received_amount") or 0) for x in items
                ),2),
                "outstanding_amount":round(sum(
                    float(x.get("outstanding_amount") or 0) for x in items
                ),2),
            },
        }

    def ias41_event_history_report(
        self,
        company_id:int,
        *,
        date_from=None,
        date_to=None,
        event_type=None,
        cur=None,
    )->dict:
        company_id=int(company_id)
        schema=self._ias41_company_guard(company_id,cur=cur)
        period=self._ias41_report_dates(date_from=date_from,date_to=date_to)

        where=[
            "e.company_id=%s",
            "e.event_date BETWEEN %s AND %s",
        ]
        params=[
            company_id,
            period["date_from"],
            period["date_to"],
        ]

        if event_type:
            where.append("e.event_type=%s")
            params.append(str(event_type).strip().lower())

        rows=self.fetch_all(
            f"""
            SELECT
                e.*,
                ac.class_code,
                ac.class_name,
                b.batch_code,
                b.batch_name,
                a.asset_number,
                a.asset_name,
                l.location_name,
                dl.location_name AS destination_location_name
            FROM {schema}.ias41_events e
            JOIN {schema}.ias41_asset_classes ac
            ON ac.company_id=e.company_id
            AND ac.id=e.asset_class_id
            LEFT JOIN {schema}.ias41_batches b
            ON b.company_id=e.company_id
            AND b.id=e.batch_id
            LEFT JOIN {schema}.ias41_biological_assets a
            ON a.company_id=e.company_id
            AND a.id=e.biological_asset_id
            LEFT JOIN {schema}.ias41_locations l
            ON l.company_id=e.company_id
            AND l.id=e.location_id
            LEFT JOIN {schema}.ias41_locations dl
            ON dl.company_id=e.company_id
            AND dl.id=e.destination_location_id
            WHERE {" AND ".join(where)}
            ORDER BY e.event_date,e.id
            """,
            tuple(params),
            cur=cur,
        )

        items=self._ias41_serialise_many(rows)

        return {
            "report_key":"event_history",
            "report_name":"Biological Transformation and Health Events",
            **period,
            "items":items,
            "totals":{
                "event_count":len(items),
                "quantity_change":sum(
                    float(x.get("quantity_change") or 0) for x in items
                ),
                "weight_change":sum(
                    float(x.get("weight_change") or 0) for x in items
                ),
                "mortality_quantity":sum(
                    float(x.get("mortality_quantity") or 0) for x in items
                ),
                "mortality_carrying_amount":round(sum(
                    float(x.get("carrying_amount_released") or 0)
                    for x in items
                ),2),
            },
        }

    def ias41_disclosure_report(
        self,
        company_id:int,
        *,
        date_from=None,
        date_to=None,
        as_of=None,
        cur=None,
    )->dict:
        company_id=int(company_id)
        period=self._ias41_report_dates(
            date_from=date_from,
            date_to=date_to,
            as_of=as_of,
        )

        register=self.ias41_biological_asset_register_report(
            company_id,
            as_of=period["as_of"],
            cur=cur,
        )

        reconciliation=self.ias41_movement_reconciliation_report(
            company_id,
            date_from=period["date_from"],
            date_to=period["date_to"],
            cur=cur,
        )

        fair_value=self.ias41_fair_value_gain_loss_report(
            company_id,
            date_from=period["date_from"],
            date_to=period["date_to"],
            cur=cur,
        )

        harvest=self.ias41_harvest_report(
            company_id,
            date_from=period["date_from"],
            date_to=period["date_to"],
            cur=cur,
        )

        grants=self.ias41_government_grants_report(
            company_id,
            date_from=period["date_from"],
            date_to=period["date_to"],
            cur=cur,
        )

        classes={}
        for row in register.get("items") or []:
            name=row.get("class_name") or "Unclassified"

            group=classes.setdefault(name,{
                "class_code":row.get("class_code"),
                "class_name":name,
                "asset_nature":row.get("asset_nature"),
                "current_noncurrent":row.get("current_noncurrent"),
                "record_count":0,
                "quantity":0,
                "fair_value":0,
                "costs_to_sell":0,
                "carrying_amount":0,
            })

            group["record_count"]+=1
            group["quantity"]+=float(row.get("quantity") or 0)
            group["fair_value"]+=float(row.get("current_fair_value") or 0)
            group["costs_to_sell"]+=float(
                row.get("current_costs_to_sell") or 0
            )
            group["carrying_amount"]+=float(
                row.get("current_carrying_amount") or 0
            )

        for group in classes.values():
            for key in ("fair_value","costs_to_sell","carrying_amount"):
                group[key]=round(group[key],2)

        return {
            "report_key":"ias41_disclosure",
            "report_name":"IAS 41 Agriculture Disclosure Note",
            **period,
            "basis":{
                "measurement":"Fair value less costs to sell",
                "harvest_measurement":
                    "Agricultural produce measured at fair value less costs to sell at harvest",
                "post_harvest_standard":"IAS 2 Inventories",
                "government_grants":"IAS 41 agricultural government grants",
            },
            "biological_asset_classes":list(classes.values()),
            "carrying_amount_reconciliation":
                reconciliation.get("movement") or {},
            "fair_value_gain_loss":
                fair_value.get("totals") or {},
            "harvest":
                harvest.get("totals") or {},
            "government_grants":
                grants.get("totals") or {},
            "closing_balance":
                register.get("totals") or {},
            "report_sections":{
                "biological_asset_register":register,
                "movement_reconciliation":reconciliation,
                "fair_value_gain_loss":fair_value,
                "harvest_report":harvest,
                "government_grants":grants,
            },
        }

    def ias41_report_build(
        self,
        company_id:int,
        report_key:str,
        *,
        filters:dict|None=None,
        save_snapshot:bool=False,
        user_id=None,
        cur=None,
    )->dict:
        company_id=int(company_id)
        schema=self._ias41_company_guard(company_id,cur=cur)
        report_key=str(report_key or "").strip().lower()
        filters=filters or {}

        if report_key not in self.IAS41_REPORT_KEYS:
            raise ValueError("Unsupported IAS 41 report.")

        builders={
            "biological_asset_register":
                self.ias41_biological_asset_register_report,

            "movement_reconciliation":
                self.ias41_movement_reconciliation_report,

            "fair_value_gain_loss":
                self.ias41_fair_value_gain_loss_report,

            "valuation_history":
                self.ias41_valuation_history_report,

            "harvest_report":
                self.ias41_harvest_report,

            "government_grants":
                self.ias41_government_grants_report,

            "event_history":
                self.ias41_event_history_report,

            "ias41_disclosure":
                self.ias41_disclosure_report,
        }

        if report_key=="dashboard_summary":
            data=self.ias41_dashboard_get(company_id,cur=cur)
        else:
            data=builders[report_key](
                company_id,
                **filters,
                cur=cur,
            )

        if save_snapshot:
            row=self.fetch_one(
                f"""
                INSERT INTO {schema}.ias41_report_runs(
                    company_id,report_key,report_name,
                    date_from,date_to,as_of_date,
                    status,filters,report_data,
                    generated_at,generated_by_user_id,metadata
                )
                VALUES(
                    %s,%s,%s,%s,%s,%s,
                    'generated',%s::jsonb,%s::jsonb,
                    NOW(),%s,'{{}}'::jsonb
                )
                RETURNING id
                """,
                (
                    company_id,
                    report_key,
                    data.get("report_name") or report_key,
                    filters.get("date_from"),
                    filters.get("date_to"),
                    filters.get("as_of"),
                    self._ias41_json_value(filters),
                    self._ias41_json_value(data),
                    user_id,
                ),
                cur=cur,
            ) or {}

            data["report_run_id"]=row.get("id")

        return data

    def ias41_report_runs_list(
        self,
        company_id:int,
        *,
        report_key=None,
        cur=None,
    )->list[dict]:
        company_id=int(company_id)
        schema=self._ias41_company_guard(company_id,cur=cur)
        where=["company_id=%s"]
        params=[company_id]

        if report_key:
            where.append("report_key=%s")
            params.append(str(report_key).strip().lower())

        rows=self.fetch_all(
            f"""
            SELECT
                id,company_id,report_key,report_name,
                date_from,date_to,as_of_date,status,
                filters,generated_at,generated_by_user_id
            FROM {schema}.ias41_report_runs
            WHERE {" AND ".join(where)}
            ORDER BY generated_at DESC,id DESC
            LIMIT 100
            """,
            tuple(params),
            cur=cur,
        )

        return self._ias41_serialise_many(rows)


    def ias41_report_run_get(
        self,
        company_id:int,
        report_run_id:int,
        *,
        cur=None,
    )->dict|None:
        company_id=int(company_id)
        schema=self._ias41_company_guard(company_id,cur=cur)

        row=self.fetch_one(
            f"""
            SELECT *
            FROM {schema}.ias41_report_runs
            WHERE company_id=%s AND id=%s
            LIMIT 1
            """,
            (company_id,int(report_run_id)),
            cur=cur,
        )

        return self._ias41_serialise(row)

    # ============================================================
    # FinSage Nexus — SETTINGS
    # ============================================================

    def get_ops_settings(self, company_id:int):
        company_id=int(company_id)
        schema=self.company_schema(company_id)
        return self.fetch_one(
            f"SELECT * FROM {schema}.ops_settings WHERE company_id=%s LIMIT 1;",
            (company_id,),
        ) or {}

    def get_ops_governance_rules(self,company_id:int):
        settings=self.get_ops_settings(company_id) or {}
        settings_json=settings.get("settings_json") or {}

        if not isinstance(settings_json,dict):
            settings_json={}

        governance=settings_json.get("governance") or {}

        if not isinstance(governance,dict):
            governance={}

        mode=(settings.get("governance_mode") or "structured").strip().lower()

        return {
            "mode":mode,
            "allow_owner_override":bool(settings.get("allow_owner_override")),
            "require_override_reason":bool(settings.get("require_override_reason")),
            "prevent_self_approval":bool(
                governance.get(
                    "prevent_self_approval",
                    mode in {"structured","controlled"}
                )
            ),
            "prevent_consecutive_approval":bool(
                governance.get(
                    "prevent_consecutive_approval",
                    mode in {"structured","controlled"}
                )
            ),
            "require_finance_review":bool(
                governance.get(
                    "require_finance_review",
                    mode in {"structured","controlled"}
                )
            ),
            "require_budget_validation":bool(
                governance.get(
                    "require_budget_validation",
                    mode in {"structured","controlled"}
                )
            ),
            "invalidate_approvals_on_change":bool(
                governance.get(
                    "invalidate_approvals_on_change",
                    mode=="controlled"
                )
            ),
        }

    def update_ops_settings(self, company_id:int, payload:dict):
        company_id=int(company_id)
        schema=self.company_schema(company_id)
        payload=payload or {}

        allowed={
            "ops_enabled","governance_mode","allow_owner_override",
            "require_override_reason","setup_completed","setup_step",
            "settings_json",
        }

        data={k:v for k,v in payload.items() if k in allowed}
        if not data:
            return self.get_ops_settings(company_id)

        cols=[]
        vals=[]

        for k,v in data.items():
            cols.append(f"{k}=%s")
            vals.append(psycopg2.extras.Json(v) if k=="settings_json" else v)

        vals.append(company_id)

        with self._conn_cursor() as (_conn,cur):
            cur.execute(
                f"""
                UPDATE {schema}.ops_settings
                SET {", ".join(cols)}, updated_at=NOW()
                WHERE company_id=%s
                RETURNING *;
                """,
                tuple(vals),
            )
            return dict(cur.fetchone() or {})


    # ============================================================
    # FinSage Nexus — DEPARTMENTS
    # ============================================================

    def list_company_departments(self, company_id:int, *, include_inactive=False):
        company_id=int(company_id)
        return self.fetch_all(
            """
            SELECT
                d.*,
                p.name AS parent_department_name,
                b.name AS branch_name,
                trim(concat_ws(' ',u.first_name,u.last_name)) AS manager_name
            FROM public.company_departments d
            LEFT JOIN public.company_departments p ON p.id=d.parent_department_id
            LEFT JOIN public.company_branches b ON b.id=d.branch_id
            LEFT JOIN public.users u ON u.id=d.manager_user_id
            WHERE d.company_id=%s
            AND (%s=TRUE OR d.is_active=TRUE)
            ORDER BY d.sort_order,d.name;
            """,
            (company_id,bool(include_inactive)),
        ) or []

    def create_company_department(self, company_id:int, payload:dict, *, actor_user_id=None):
        company_id=int(company_id)
        payload=payload or {}
        name=str(payload.get("name") or "").strip()
        if not name:
            raise ValueError("Department name is required.")

        with self._conn_cursor() as (_conn,cur):
            cur.execute(
                """
                INSERT INTO public.company_departments(
                    company_id,code,name,description,parent_department_id,
                    manager_user_id,branch_id,sort_order,created_by_user_id
                )
                VALUES(%s,%s,%s,%s,%s,%s,%s,%s,%s)
                RETURNING *;
                """,
                (
                    company_id,
                    (payload.get("code") or "").strip() or None,
                    name,
                    (payload.get("description") or "").strip() or None,
                    payload.get("parent_department_id"),
                    payload.get("manager_user_id"),
                    payload.get("branch_id"),
                    int(payload.get("sort_order") or 0),
                    int(actor_user_id) if actor_user_id else None,
                ),
            )
            return dict(cur.fetchone() or {})

    def update_company_department(self, company_id:int, department_id:int, payload:dict):
        company_id=int(company_id)
        department_id=int(department_id)
        payload=payload or {}

        allowed={
            "code","name","description","parent_department_id",
            "manager_user_id","branch_id","sort_order","is_active",
        }

        data={k:v for k,v in payload.items() if k in allowed}
        if not data:
            return self.fetch_one(
                "SELECT * FROM public.company_departments WHERE company_id=%s AND id=%s;",
                (company_id,department_id),
            )

        cols=[]
        vals=[]

        for k,v in data.items():
            cols.append(f"{k}=%s")
            vals.append(v)

        vals.extend([company_id,department_id])

        with self._conn_cursor() as (_conn,cur):
            cur.execute(
                f"""
                UPDATE public.company_departments
                SET {", ".join(cols)},updated_at=NOW()
                WHERE company_id=%s AND id=%s
                RETURNING *;
                """,
                tuple(vals),
            )
            return dict(cur.fetchone() or {})


    # ============================================================
    # FinSage Nexus — POSITIONS
    # ============================================================

    def list_company_positions(self, company_id:int, *, include_inactive=False):
        company_id=int(company_id)
        return self.fetch_all(
            """
            SELECT
                p.*,
                d.name AS department_name,
                rp.title AS reports_to_position_title
            FROM public.company_positions p
            LEFT JOIN public.company_departments d ON d.id=p.department_id
            LEFT JOIN public.company_positions rp ON rp.id=p.reports_to_position_id
            WHERE p.company_id=%s
            AND (%s=TRUE OR p.is_active=TRUE)
            ORDER BY d.name NULLS LAST,p.approval_level DESC,p.title;
            """,
            (company_id,bool(include_inactive)),
        ) or []

    def create_company_position(self,company_id:int,payload:dict,*,actor_user_id=None):
        company_id=int(company_id)
        payload=payload or {}
        title=str(payload.get("title") or "").strip()
        approval_level=int(payload.get("approval_level") or 0)

        if not title:
            raise ValueError("Position title is required.")
        if approval_level not in range(6):
            raise ValueError("Authority level must be between 0 and 5.")

        with self._conn_cursor() as (_conn,cur):
            cur.execute(
                """
                INSERT INTO public.company_positions(
                    company_id,department_id,code,title,description,
                    reports_to_position_id,approval_level,is_department_head,
                    created_by_user_id
                )
                VALUES(%s,%s,%s,%s,%s,%s,%s,%s,%s)
                RETURNING *;
                """,
                (
                    company_id,
                    payload.get("department_id"),
                    (payload.get("code") or "").strip() or None,
                    title,
                    (payload.get("description") or "").strip() or None,
                    payload.get("reports_to_position_id"),
                    approval_level,
                    bool(payload.get("is_department_head")),
                    int(actor_user_id) if actor_user_id else None,
                ),
            )
            return dict(cur.fetchone() or {})
        
    def update_company_position(self,company_id:int,position_id:int,payload:dict):
        company_id=int(company_id)
        position_id=int(position_id)
        payload=payload or {}

        current=self.fetch_one(
            """
            SELECT *
            FROM public.company_positions
            WHERE company_id=%s AND id=%s;
            """,
            (company_id,position_id),
        )

        if not current:
            raise ValueError("Position not found.")

        title=str(
            payload.get("title")
            if "title" in payload
            else current.get("title")
            or ""
        ).strip()

        if not title:
            raise ValueError("Position title is required.")

        approval_level=int(
            payload.get("approval_level")
            if "approval_level" in payload
            else current.get("approval_level")
            or 0
        )

        if approval_level not in range(6):
            raise ValueError("Authority level must be between 0 and 5.")

        department_id=(
            payload.get("department_id")
            if "department_id" in payload
            else current.get("department_id")
        )

        code=(
            payload.get("code")
            if "code" in payload
            else current.get("code")
        )

        description=(
            payload.get("description")
            if "description" in payload
            else current.get("description")
        )

        reports_to_position_id=(
            payload.get("reports_to_position_id")
            if "reports_to_position_id" in payload
            else current.get("reports_to_position_id")
        )

        is_department_head=bool(
            payload.get("is_department_head")
            if "is_department_head" in payload
            else current.get("is_department_head")
        )

        with self._conn_cursor() as (_conn,cur):
            cur.execute(
                """
                UPDATE public.company_positions
                SET
                    department_id=%s,
                    code=%s,
                    title=%s,
                    description=%s,
                    reports_to_position_id=%s,
                    approval_level=%s,
                    is_department_head=%s,
                    updated_at=NOW()
                WHERE company_id=%s
                AND id=%s
                RETURNING *;
                """,
                (
                    department_id,
                    str(code).strip() if code else None,
                    title,
                    str(description).strip() if description else None,
                    reports_to_position_id,
                    approval_level,
                    is_department_head,
                    company_id,
                    position_id,
                ),
            )

            row=cur.fetchone()

        if not row:
            raise ValueError("Position not found.")

        return dict(row)

    # ============================================================
    # FinSage Nexus — ROLES
    # ============================================================

    def list_ops_roles(self, company_id:int):
        company_id=int(company_id)
        schema=self.company_schema(company_id)

        return self.fetch_all(
            f"""
            SELECT
                r.*,
                ARRAY(
                    SELECT p.code
                    FROM {schema}.ops_role_permissions rp
                    JOIN {schema}.ops_permissions p ON p.id=rp.permission_id
                    WHERE rp.role_id=r.id
                    ORDER BY p.code
                ) AS permissions
            FROM {schema}.ops_roles r
            WHERE r.is_active=TRUE
            ORDER BY r.authority_rank DESC,r.name;
            """
        ) or []

    def get_ops_user_permissions(self, company_id:int, user_id:int):
        company_id=int(company_id)
        user_id=int(user_id)
        schema=self.company_schema(company_id)

        owner=self.fetch_val(
            """
            SELECT 1
            FROM public.companies
            WHERE id=%s AND owner_user_id=%s
            LIMIT 1;
            """,
            (company_id,user_id),
        )

        if owner:
            rows=self.fetch_all(
                f"SELECT code FROM {schema}.ops_permissions ORDER BY code;"
            ) or []
            return [r["code"] for r in rows]

        rows=self.fetch_all(
            f"""
            SELECT DISTINCT p.code
            FROM public.company_users cu
            JOIN {schema}.ops_user_roles ur
            ON ur.company_user_id=cu.id
            AND ur.is_active=TRUE
            JOIN {schema}.ops_roles r
            ON r.id=ur.role_id
            AND r.is_active=TRUE
            JOIN {schema}.ops_role_permissions rp
            ON rp.role_id=r.id
            JOIN {schema}.ops_permissions p
            ON p.id=rp.permission_id
            WHERE cu.company_id=%s
            AND cu.user_id=%s
            AND cu.is_active=TRUE
            AND cu.ops_is_active=TRUE
            ORDER BY p.code;
            """,
            (company_id,user_id),
        ) or []

        return [r["code"] for r in rows]

    def user_has_ops_access(self, company_id:int, user_id:int)->bool:
        company_id=int(company_id)
        user_id=int(user_id)

        return bool(self.fetch_val(
            """
            SELECT 1
            FROM public.company_users cu
            JOIN public.companies c ON c.id=cu.company_id
            WHERE cu.company_id=%s
            AND cu.user_id=%s
            AND cu.is_active=TRUE
            AND (
                c.owner_user_id=cu.user_id
                OR (
                    cu.ops_is_active=TRUE
                    AND COALESCE((cu.product_access->>'FinSage Nexus')::boolean,FALSE)=TRUE
                )
            )
            LIMIT 1;
            """,
            (company_id,user_id),
        ))


    # ============================================================
    # FinSage Nexus — TEAM
    # ============================================================

    def list_ops_team(self, company_id:int):
        company_id=int(company_id)
        schema=self.company_schema(company_id)

        return self.fetch_all(
            f"""
            SELECT
                cu.id AS company_user_id,
                cu.user_id,
                cu.role AS company_role,
                cu.is_active,
                cu.ops_is_active,
                cu.product_access,

                u.email,
                u.first_name,
                u.last_name,

                a.department_id,
                d.name AS department_name,

                a.position_id,
                p.title AS position_title,

                a.branch_id,
                b.name AS branch_name,

                a.manager_user_id,

                ARRAY(
                    SELECT r.code
                    FROM {schema}.ops_user_roles ur
                    JOIN {schema}.ops_roles r ON r.id=ur.role_id
                    WHERE ur.company_user_id=cu.id
                    AND ur.is_active=TRUE
                    ORDER BY r.authority_rank DESC
                ) AS ops_roles

            FROM public.company_users cu
            JOIN public.users u ON u.id=cu.user_id

            LEFT JOIN public.company_user_assignments a
            ON a.company_user_id=cu.id
            AND a.company_id=cu.company_id
            AND a.is_primary=TRUE
            AND a.is_active=TRUE

            LEFT JOIN public.company_departments d ON d.id=a.department_id
            LEFT JOIN public.company_positions p ON p.id=a.position_id
            LEFT JOIN public.company_branches b ON b.id=a.branch_id

            WHERE cu.company_id=%s
            AND cu.is_active=TRUE

            ORDER BY u.first_name,u.last_name,u.email;
            """,
            (company_id,),
        ) or []

    def set_ops_user_access(
        self,
        company_id:int,
        user_id:int,
        payload:dict,
        *,
        actor_user_id:int,
    ):
        company_id=int(company_id)
        user_id=int(user_id)
        actor_user_id=int(actor_user_id)
        schema=self.company_schema(company_id)
        payload=payload or {}

        with self.transaction() as (_conn,cur):
            cur.execute(
                """
                SELECT
                    cu.id AS company_user_id,
                    c.owner_user_id
                FROM public.company_users cu
                JOIN public.companies c ON c.id=cu.company_id
                WHERE cu.company_id=%s
                AND cu.user_id=%s
                AND cu.is_active=TRUE
                LIMIT 1;
                """,
                (company_id,user_id),
            )
            member=cur.fetchone()

            if not member:
                raise ValueError("Company user not found.")

            company_user_id=int(member["company_user_id"])
            is_owner=int(member.get("owner_user_id") or 0)==user_id

            product_access=payload.get("product_access")
            if not isinstance(product_access,dict):
                product_access={}

            if is_owner:
                product_access["FinSage Nexus"]=True
                product_access.setdefault("finsage",True)

            ops_enabled=bool(product_access.get("FinSage Nexus"))

            cur.execute(
                """
                UPDATE public.company_users
                SET product_access=%s,
                    ops_is_active=%s
                WHERE id=%s
                """,
                (
                    psycopg2.extras.Json(product_access),
                    ops_enabled,
                    company_user_id,
                ),
            )

            if any(k in payload for k in (
                "department_id","position_id","branch_id","manager_user_id"
            )):
                cur.execute(
                    """
                    UPDATE public.company_user_assignments
                    SET is_primary=FALSE,
                        is_active=FALSE,
                        effective_to=CURRENT_DATE,
                        updated_at=NOW()
                    WHERE company_id=%s
                    AND company_user_id=%s
                    AND is_primary=TRUE
                    AND is_active=TRUE;
                    """,
                    (company_id,company_user_id),
                )

                cur.execute(
                    """
                    INSERT INTO public.company_user_assignments(
                        company_id,company_user_id,
                        department_id,position_id,branch_id,manager_user_id,
                        is_primary,effective_from,is_active,created_by_user_id
                    )
                    VALUES(%s,%s,%s,%s,%s,%s,TRUE,CURRENT_DATE,TRUE,%s);
                    """,
                    (
                        company_id,
                        company_user_id,
                        payload.get("department_id"),
                        payload.get("position_id"),
                        payload.get("branch_id"),
                        payload.get("manager_user_id"),
                        actor_user_id,
                    ),
                )

            role_codes=[
                str(x).strip().upper()
                for x in (payload.get("ops_role_codes") or [])
                if str(x).strip()
            ]

            if is_owner and "OWNER" not in role_codes:
                role_codes.append("OWNER")

            if "ops_role_codes" in payload:
                cur.execute(
                    f"""
                    UPDATE {schema}.ops_user_roles
                    SET is_active=FALSE,revoked_at=NOW()
                    WHERE company_user_id=%s
                    AND scope_type='company'
                    AND scope_id=0;
                    """,
                    (company_user_id,),
                )

                for code in role_codes:
                    cur.execute(
                        f"""
                        INSERT INTO {schema}.ops_user_roles(
                            company_user_id,role_id,
                            scope_type,scope_id,assigned_by_user_id
                        )
                        SELECT %s,r.id,'company',0,%s
                        FROM {schema}.ops_roles r
                        WHERE r.code=%s
                        AND r.is_active=TRUE
                        ON CONFLICT(company_user_id,role_id,scope_type,scope_id)
                        DO UPDATE SET
                            is_active=TRUE,
                            revoked_at=NULL,
                            assigned_by_user_id=EXCLUDED.assigned_by_user_id,
                            assigned_at=NOW();
                        """,
                        (company_user_id,actor_user_id,code),
                    )

            event_uuid=str(uuid.uuid4())

            cur.execute(
                f"""
                INSERT INTO {schema}.ops_events(
                    event_uuid,event_type,module,
                    entity_type,entity_id,actor_user_id,
                    action,after_json
                )
                VALUES(
                    %s,'team.access.updated','security',
                    'company_user',%s,%s,
                    'update_access',%s
                );
                """,
                (
                    event_uuid,
                    str(company_user_id),
                    actor_user_id,
                    psycopg2.extras.Json(payload),
                ),
            )

        rows=self.list_ops_team(company_id)
        return next(
            (r for r in rows if int(r["user_id"])==user_id),
            None,
        )


    # ============================================================
    # FinSage Nexus — INVITE CONTEXT
    # ============================================================

    def set_company_invite_ops_context(
        self,
        *,
        token:str,
        department_id=None,
        position_id=None,
        branch_id=None,
        manager_user_id=None,
        ops_role_code=None,
        product_access=None,
    ):
        self.execute_sql(
            """
            UPDATE public.company_invites
            SET department_id=%s,
                position_id=%s,
                branch_id=%s,
                manager_user_id=%s,
                ops_role_code=%s,
                product_access=%s
            WHERE token=%s;
            """,
            (
                department_id,
                position_id,
                branch_id,
                manager_user_id,
                (ops_role_code or "").strip().upper() or None,
                psycopg2.extras.Json(product_access or {}),
                token,
            ),
        )

    def apply_ops_invite_context(self, *, token:str, user_id:int):
        rec=self.fetch_one(
            """
            SELECT *
            FROM public.company_invites
            WHERE token=%s
            LIMIT 1;
            """,
            (token,),
        ) or {}

        company_id=int(rec.get("company_id") or 0)
        if not company_id:
            return None

        schema=self.company_schema(company_id)

        cu=self.fetch_one(
            """
            SELECT id
            FROM public.company_users
            WHERE company_id=%s AND user_id=%s
            LIMIT 1;
            """,
            (company_id,int(user_id)),
        ) or {}

        company_user_id=cu.get("id")
        if not company_user_id:
            return None

        product_access=rec.get("product_access") or {}
        ops_role_code=(rec.get("ops_role_code") or "").strip().upper()

        with self.transaction() as (_conn,cur):
            if product_access:
                cur.execute(
                    """
                    UPDATE public.company_users
                    SET product_access=%s,
                        ops_is_active=%s
                    WHERE id=%s;
                    """,
                    (
                        psycopg2.extras.Json(product_access),
                        bool(product_access.get("FinSage Nexus")),
                        int(company_user_id),
                    ),
                )

            if any(rec.get(k) is not None for k in (
                "department_id","position_id","branch_id","manager_user_id"
            )):
                cur.execute(
                    """
                    UPDATE public.company_user_assignments
                    SET is_primary=FALSE,is_active=FALSE,
                        effective_to=CURRENT_DATE,updated_at=NOW()
                    WHERE company_id=%s
                    AND company_user_id=%s
                    AND is_primary=TRUE
                    AND is_active=TRUE;
                    """,
                    (company_id,int(company_user_id)),
                )

                cur.execute(
                    """
                    INSERT INTO public.company_user_assignments(
                        company_id,company_user_id,
                        department_id,position_id,branch_id,manager_user_id,
                        is_primary,effective_from,is_active
                    )
                    VALUES(%s,%s,%s,%s,%s,%s,TRUE,CURRENT_DATE,TRUE);
                    """,
                    (
                        company_id,
                        int(company_user_id),
                        rec.get("department_id"),
                        rec.get("position_id"),
                        rec.get("branch_id"),
                        rec.get("manager_user_id"),
                    ),
                )

            if ops_role_code:
                cur.execute(
                    f"""
                    INSERT INTO {schema}.ops_user_roles(
                        company_user_id,role_id,
                        scope_type,scope_id,assigned_by_user_id
                    )
                    SELECT %s,r.id,'company',0,%s
                    FROM {schema}.ops_roles r
                    WHERE r.code=%s
                    ON CONFLICT(company_user_id,role_id,scope_type,scope_id)
                    DO UPDATE SET is_active=TRUE,revoked_at=NULL;
                    """,
                    (
                        int(company_user_id),
                        rec.get("created_by"),
                        ops_role_code,
                    ),
                )

        return True


    # ============================================================
    # FinSage Nexus — SESSION
    # ============================================================

    def get_ops_session_context(self, company_id:int, user_id:int):
        company_id=int(company_id)
        user_id=int(user_id)
        schema=self.company_schema(company_id)

        member=self.fetch_one(
            """
            SELECT
                cu.id AS company_user_id,
                cu.role AS company_role,
                cu.product_access,
                cu.ops_is_active,

                u.id AS user_id,
                u.email,
                u.first_name,
                u.last_name,

                c.name AS company_name,
                c.owner_user_id,
                c.currency,
                c.logo_url,
                c.company_reg_no,
                c.tin,
                c.vat,
                c.company_email,
                c.company_phone,
                c.physical_address,

                a.department_id,
                d.name AS department_name,

                a.position_id,
                p.title AS position_title,

                a.branch_id,
                b.name AS branch_name,

                a.manager_user_id

            FROM public.company_users cu
            JOIN public.users u ON u.id=cu.user_id
            JOIN public.companies c ON c.id=cu.company_id

            LEFT JOIN public.company_user_assignments a
            ON a.company_id=cu.company_id
            AND a.company_user_id=cu.id
            AND a.is_primary=TRUE
            AND a.is_active=TRUE

            LEFT JOIN public.company_departments d ON d.id=a.department_id
            LEFT JOIN public.company_positions p ON p.id=a.position_id
            LEFT JOIN public.company_branches b ON b.id=a.branch_id

            WHERE cu.company_id=%s
            AND cu.user_id=%s
            AND cu.is_active=TRUE
            LIMIT 1;
            """,
            (company_id,user_id),
        ) or {}

        if not member:
            return None

        roles=self.fetch_all(
            f"""
            SELECT r.code,r.name,r.authority_rank,ur.scope_type,ur.scope_id
            FROM {schema}.ops_user_roles ur
            JOIN {schema}.ops_roles r ON r.id=ur.role_id
            WHERE ur.company_user_id=%s
            AND ur.is_active=TRUE
            AND r.is_active=TRUE
            ORDER BY r.authority_rank DESC;
            """,
            (member["company_user_id"],),
        ) or []

        member["ops_roles"]=roles
        member["permissions"]=self.get_ops_user_permissions(company_id,user_id)
        member["settings"]=self.get_ops_settings(company_id)
        member["is_owner"]=int(member.get("owner_user_id") or 0)==user_id

        return member


