    def append_ops_event(
        self,
        company_id:int,
        *,
        event_type:str,
        module:str,
        entity_type:str,
        action:str,
        actor_user_id=None,
        entity_id=None,
        entity_ref=None,
        before_json=None,
        after_json=None,
        metadata_json=None,
        ip_address=None,
        user_agent=None,
    ):
        company_id=int(company_id)
        schema=self.company_schema(company_id)

        event_uuid=str(uuid.uuid4())

        self.execute_sql(
            f"""
            INSERT INTO {schema}.ops_events(
                event_uuid,event_type,module,
                entity_type,entity_id,entity_ref,
                actor_user_id,action,
                before_json,after_json,metadata_json,
                ip_address,user_agent
            )
            VALUES(%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s);
            """,
            (
                event_uuid,
                event_type,
                module,
                entity_type,
                str(entity_id) if entity_id is not None else None,
                entity_ref,
                int(actor_user_id) if actor_user_id else None,
                action,
                psycopg2.extras.Json(before_json or {},dumps=lambda obj: json.dumps(obj,default=str)),
                psycopg2.extras.Json(after_json or {},dumps=lambda obj: json.dumps(obj,default=str)),
                psycopg2.extras.Json(metadata_json or {},dumps=lambda obj: json.dumps(obj,default=str)),
                ip_address,
                user_agent,
            ),
        )

        return event_uuid
        
    def next_ops_request_no(self,company_id:int,*,cur=None)->str:
        company_id=int(company_id)
        schema=self.company_schema(company_id)
        prefix="REQ"
        year=date.today().year

        owns_cur=cur is None

        if owns_cur:
            with self.transaction() as (_conn,tx):
                return self.next_ops_request_no(company_id,cur=tx)

        cur.execute(
            f"""
            SELECT COALESCE(MAX(
                CASE
                    WHEN request_no ~ %s
                    THEN split_part(request_no,'-',3)::int
                    ELSE 0
                END
            ),0)+1 AS next_no
            FROM {schema}.ops_requests
            WHERE company_id=%s;
            """,
            (
                rf"^{prefix}-{year}-[0-9]+$",
                company_id,
            ),
        )

        n=int((cur.fetchone() or {}).get("next_no") or 1)

        return f"{prefix}-{year}-{n:05d}"

    def create_ops_request(
        self,
        company_id:int,
        payload:dict,
        *,
        actor_user_id:int,
    ):
        company_id=int(company_id)
        actor_user_id=int(actor_user_id)
        schema=self.company_schema(company_id)
        payload=payload or {}

        request_type_id=int(payload.get("request_type_id") or 0)
        title=str(payload.get("title") or "").strip()

        if not request_type_id:
            raise ValueError("Request type is required.")

        if not title:
            raise ValueError("Request title is required.")

        request_type=self.fetch_one(
            f"""
            SELECT code,name
            FROM {schema}.ops_request_types
            WHERE company_id=%s AND id=%s
            LIMIT 1;
            """,
            (company_id,request_type_id),
        ) or {}

        document_types={
            "PURCHASE":"PURCHASE_REQUISITION",
            "SERVICE":"SERVICE_REQUISITION",
            "ASSET":"CAPEX_REQUISITION",
            "LEASE":"LEASE_REQUISITION",
            "PAYMENT":"PAYMENT_REQUEST",
            "TRAVEL":"TRAVEL_AUTHORISATION",
            "GENERAL":"GENERAL_REQUISITION",
        }

        document_type=document_types.get(
            request_type.get("code"),
            "GENERAL_REQUISITION",
        )

        assignment=self.fetch_one(
            """
            SELECT
                a.department_id,
                a.branch_id
            FROM public.company_users cu
            LEFT JOIN public.company_user_assignments a
            ON a.company_user_id=cu.id
            AND a.company_id=cu.company_id
            AND a.is_primary=TRUE
            AND a.is_active=TRUE
            WHERE cu.company_id=%s
            AND cu.user_id=%s
            AND cu.is_active=TRUE
            LIMIT 1;
            """,
            (company_id,actor_user_id),
        ) or {}

        items=payload.get("items") or []

        with self.transaction() as (_conn,cur):
            request_no=self.next_ops_request_no(
                company_id,
                cur=cur,
            )

            cur.execute(
                f"""
                INSERT INTO {schema}.ops_requests(
                    company_id,
                    request_no,
                    request_type_id,
                    title,
                    description,
                    requested_by_user_id,
                    department_id,
                    branch_id,
                    project_id,
                    cost_center_id,
                    document_type
                    business_purpose
                    primary_gl_account_code
                    primary_gl_account_name
                    gl_account_id,
                    currency_code,
                    estimated_amount,
                    required_date,
                    priority,
                    emergency,
                    emergency_reason,
                    status,
                    created_by_user_id,
                    metadata_json
                )
                VALUES(
                    %s,%s,%s,%s,%s,%s,%s,
                    %s,%s,%s,%s,%s,%s,%s,
                    %s,%s,%s,%s,%s,%s,%s
                    'draft',%s,%s
                )
                RETURNING *;
                """,
                (
                    company_id,
                    request_no,
                    request_type_id,
                    title,
                    (payload.get("description") or "").strip() or None,
                    actor_user_id,

                    payload.get("department_id")
                        or assignment.get("department_id"),

                    payload.get("branch_id")
                        or assignment.get("branch_id"),

                    payload.get("project_id"),
                    payload.get("cost_center_id"),
                    document_type,
                    (payload.get("business_purpose") or "").strip() or None,
                    (payload.get("primary_gl_account_code") or "").strip() or None,
                    (payload.get("primary_gl_account_name") or "").strip() or None,
                    payload.get("gl_account_id"),
                    payload.get("currency_code"),

                    float(payload.get("estimated_amount") or 0),
                    payload.get("required_date"),
                    payload.get("priority") or "normal",
                    bool(payload.get("emergency")),
                    (payload.get("emergency_reason") or "").strip() or None,

                    actor_user_id,
                    psycopg2.extras.Json(
                        payload.get("metadata_json") or {}
                    ),
                ),
            )

            request_row=dict(cur.fetchone())
            request_id=int(request_row["id"])

            for idx,item in enumerate(items,1):
                qty=float(item.get("quantity") or 1)
                unit=float(item.get("estimated_unit_cost") or 0)
                total=float(
                    item.get("estimated_total")
                    if item.get("estimated_total") is not None
                    else qty*unit
                )

                cur.execute(
                    f"""
                    INSERT INTO {schema}.ops_request_items(
                        request_id,
                        line_no,
                        item_type,
                        item_id,
                        description,
                        quantity,
                        unit_of_measure,
                        estimated_unit_cost,
                        estimated_total,
                        preferred_vendor_id,
                        gl_account_id,
                        metadata_json
                    )
                    VALUES(%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s);
                    """,
                    (
                        request_id,
                        idx,
                        item.get("item_type"),
                        item.get("item_id"),
                        (item.get("description") or "").strip(),
                        qty,
                        item.get("unit_of_measure"),
                        unit,
                        total,
                        item.get("preferred_vendor_id"),
                        item.get("gl_account_id"),
                        psycopg2.extras.Json(
                            item.get("metadata_json") or {}
                        ),
                    ),
                )

            cur.execute(
                f"""
                INSERT INTO {schema}.ops_events(
                    event_uuid,event_type,module,
                    entity_type,entity_id,entity_ref,
                    actor_user_id,action,after_json
                )
                VALUES(
                    %s,'request.created','requests',
                    'request',%s,%s,%s,'create',%s
                );
                """,
                (
                    str(uuid.uuid4()),
                    str(request_id),
                    request_no,
                    actor_user_id,
                    psycopg2.extras.Json(request_row),
                ),
            )

        return self.get_ops_request(
            company_id,
            request_id,
        )

    def update_ops_request(
        self,
        company_id:int,
        request_id:int,
        payload:dict,
        *,
        actor_user_id:int,
    ):
        company_id=int(company_id)
        request_id=int(request_id)
        actor_user_id=int(actor_user_id)
        schema=self.company_schema(company_id)
        payload=payload or {}

        with self.transaction() as (_conn,cur):
            cur.execute(
                f"""
                SELECT *
                FROM {schema}.ops_requests
                WHERE company_id=%s
                AND id=%s
                FOR UPDATE;
                """,
                (company_id,request_id),
            )

            req=cur.fetchone()

            if not req:
                raise ValueError("Request not found.")

            req=dict(req)

            if req["status"] not in {"draft","returned"}:
                raise ValueError(
                    "Only draft or returned requests can be edited."
                )

            if req.get("locked_at"):
                raise ValueError(
                    "This request is locked and cannot be edited."
                )

            if int(req["requested_by_user_id"])!=actor_user_id:
                permissions=set(
                    self.get_ops_user_permissions(
                        company_id,
                        actor_user_id,
                    )
                )

                if "requests.view_all" not in permissions:
                    raise PermissionError(
                        "You cannot edit this request."
                    )

            before=dict(req)

            title=str(
                payload.get("title",req.get("title") or "")
            ).strip()

            if not title:
                raise ValueError("Request title is required.")

            request_type_id=int(
                payload.get("request_type_id")
                or req["request_type_id"]
            )

            cur.execute(
                f"""
                SELECT id,code,name,document_type,template_code
                FROM {schema}.ops_request_types
                WHERE company_id=%s
                AND id=%s
                AND is_active=TRUE
                LIMIT 1;
                """,
                (company_id,request_type_id),
            )

            request_type=cur.fetchone()

            if not request_type:
                raise ValueError("Invalid request type.")

            items=payload.get("items")

            if items is None:
                cur.execute(
                    f"""
                    SELECT *
                    FROM {schema}.ops_request_items
                    WHERE request_id=%s
                    ORDER BY line_no,id;
                    """,
                    (request_id,),
                )
                items=[dict(x) for x in cur.fetchall()]

            clean_items=[]

            for index,item in enumerate(items,1):
                item=item or {}
                description=str(
                    item.get("description") or ""
                ).strip()

                if not description:
                    continue

                qty=float(item.get("quantity") or 1)
                unit_cost=float(
                    item.get("estimated_unit_cost") or 0
                )

                clean_items.append({
                    "line_no":index,
                    "description":description,
                    "quantity":qty,
                    "unit_of_measure":
                        (item.get("unit_of_measure") or "").strip() or None,
                    "estimated_unit_cost":unit_cost,
                    "estimated_total":qty*unit_cost,

                    "item_type":item.get("item_type"),
                    "item_id":item.get("item_id"),

                    "preferred_vendor_id":
                        item.get("preferred_vendor_id"),

                    "gl_account_id":
                        item.get("gl_account_id"),

                    "gl_account_code":
                        (item.get("gl_account_code") or "").strip() or None,

                    "gl_account_name":
                        (item.get("gl_account_name") or "").strip() or None,

                    "cost_centre_id":
                        item.get("cost_centre_id"),

                    "financial_classification":
                        item.get("financial_classification"),

                    "tax_treatment":
                        item.get("tax_treatment"),

                    "metadata_json":
                        item.get("metadata_json") or {},
                })

            estimated_amount=sum(
                float(item["estimated_total"] or 0)
                for item in clean_items
            )

            was_returned=req["status"]=="returned"

            revision_changed=was_returned

            if revision_changed:
                revision_no+=1

            cur.execute(
                f"""
                UPDATE {schema}.ops_requests
                SET request_type_id=%s,
                    document_type=%s,
                    title=%s,
                    business_purpose=%s,
                    description=%s,
                    required_date=%s,
                    priority=%s,
                    estimated_amount=%s,
                    currency_code=COALESCE(%s,currency_code),

                    status='draft',
                    revision_no=%s,

                    submitted_at=NULL,
                    approved_at=NULL,
                    rejected_at=NULL,
                    cancelled_at=NULL,
                    completed_at=NULL,

                    current_workflow_instance_id=NULL,

                    updated_by_user_id=%s,
                    updated_at=NOW()
                WHERE id=%s
                RETURNING *;
                """,
                (
                    request_type_id,
                    request_type.get("document_type"),
                    title,
                    (payload.get("business_purpose") or "").strip() or None,
                    (payload.get("description") or "").strip() or None,
                    payload.get("required_date"),
                    payload.get("priority") or "normal",
                    estimated_amount,
                    payload.get("currency_code"),
                    revision_no,
                    actor_user_id,
                    request_id,
                ),
            )

            updated=dict(cur.fetchone())

            cur.execute(
                f"""
                DELETE FROM {schema}.ops_request_items
                WHERE request_id=%s;
                """,
                (request_id,),
            )

            if revision_changed:
                cur.execute(
                    f"""
                    UPDATE {schema}.ops_finance_reviews
                    SET status='superseded',
                        updated_at=NOW()
                    WHERE request_id=%s
                    AND status='pending';
                    """,
                    (request_id,),
                )

            for item in clean_items:
                cur.execute(
                    f"""
                    INSERT INTO {schema}.ops_request_items(
                        request_id,
                        line_no,
                        item_type,
                        item_id,
                        description,
                        quantity,
                        unit_of_measure,
                        estimated_unit_cost,
                        estimated_total,
                        preferred_vendor_id,
                        gl_account_id,
                        gl_account_code,
                        gl_account_name,
                        cost_centre_id,
                        financial_classification,
                        tax_treatment,
                        metadata_json
                    )
                    VALUES(
                        %s,%s,%s,%s,%s,%s,%s,%s,%s,
                        %s,%s,%s,%s,%s,%s,%s,%s
                    );
                    """,
                    (
                        request_id,
                        item["line_no"],
                        item["item_type"],
                        item["item_id"],
                        item["description"],
                        item["quantity"],
                        item["unit_of_measure"],
                        item["estimated_unit_cost"],
                        item["estimated_total"],
                        item["preferred_vendor_id"],
                        item["gl_account_id"],
                        item["gl_account_code"],
                        item["gl_account_name"],
                        item["cost_centre_id"],
                        item["financial_classification"],
                        item["tax_treatment"],
                        psycopg2.extras.Json(
                            item["metadata_json"]
                        ),
                    ),
                )

            cur.execute(
                f"""
                INSERT INTO {schema}.ops_events(
                    event_uuid,event_type,module,
                    entity_type,entity_id,entity_ref,
                    actor_user_id,action,
                    before_json,after_json
                )
                VALUES(
                    %s,%s,'requests',
                    'request',%s,%s,
                    %s,'update',
                    %s,%s
                );
                """,
                (
                    str(uuid.uuid4()),
                    (
                        "request.corrected"
                        if was_returned
                        else "request.updated"
                    ),
                    str(request_id),
                    req["request_no"],
                    actor_user_id,
                    psycopg2.extras.Json(before),
                    psycopg2.extras.Json({
                        **updated,
                        "items":clean_items,
                    }),
                ),
            )

        return self.get_ops_request(
            company_id,
            request_id,
        )

    def get_ops_request(self,company_id:int,request_id:int):
        company_id=int(company_id)
        request_id=int(request_id)
        schema=self.company_schema(company_id)

        row=self.fetch_one(
            f"""
            SELECT
                r.*,
                rt.code AS request_type_code,
                rt.name AS request_type_name,
                d.name AS department_name,
                b.name AS branch_name,
                cc.code AS cost_centre_code,
                cc.name AS cost_centre_name
                trim(concat_ws(
                    ' ',
                    u.first_name,
                    u.last_name
                )) AS requester_name

            FROM {schema}.ops_requests r

            JOIN {schema}.ops_request_types rt
            ON rt.id=r.request_type_id

            LEFT JOIN public.company_departments d
            ON d.id=r.department_id

            LEFT JOIN public.company_branches b
            ON b.id=r.branch_id
            LEFT JOIN public.company_cost_centres cc
            ON cc.id=r.cost_centre_id

            LEFT JOIN public.users u
            ON u.id=r.requested_by_user_id

            WHERE r.company_id=%s
            AND r.id=%s
            LIMIT 1;
            """,
            (company_id,request_id),
        )

        if not row:
            return None

        row["items"]=self.fetch_all(
            f"""
            SELECT *
            FROM {schema}.ops_request_items
            WHERE request_id=%s
            ORDER BY line_no,id;
            """,
            (request_id,),
        ) or []

        row["approvals"]=self.fetch_all(
            f"""
            SELECT
                t.*,
                ws.name AS step_name,
                trim(concat_ws(
                    ' ',
                    u.first_name,
                    u.last_name
                )) AS assignee_name
            FROM {schema}.ops_approval_tasks t
            JOIN {schema}.ops_workflow_steps ws
            ON ws.id=t.workflow_step_id
            LEFT JOIN public.users u
            ON u.id=t.assigned_to_user_id
            WHERE t.request_id=%s
            ORDER BY t.id;
            """,
            (request_id,),
        ) or []

        return row

    def list_ops_requests(
        self,
        company_id:int,
        *,
        user_id:int,
        status=None,
        limit=100,
    ):
        company_id=int(company_id)
        user_id=int(user_id)
        schema=self.company_schema(company_id)

        permissions=set(
            self.get_ops_user_permissions(
                company_id,
                user_id,
            )
        )

        where=["r.company_id=%s"]
        params=[company_id]

        if "requests.view_all" not in permissions:
            if "requests.view_department" in permissions:
                assignment=self.fetch_one(
                    """
                    SELECT a.department_id
                    FROM public.company_users cu
                    LEFT JOIN public.company_user_assignments a
                    ON a.company_user_id=cu.id
                    AND a.company_id=cu.company_id
                    AND a.is_primary=TRUE
                    AND a.is_active=TRUE
                    WHERE cu.company_id=%s
                    AND cu.user_id=%s
                    LIMIT 1;
                    """,
                    (company_id,user_id),
                ) or {}

                department_id=assignment.get("department_id")

                if department_id:
                    where.append(
                        "(r.requested_by_user_id=%s OR r.department_id=%s)"
                    )
                    params.extend([user_id,department_id])
                else:
                    where.append("r.requested_by_user_id=%s")
                    params.append(user_id)
            else:
                where.append("r.requested_by_user_id=%s")
                params.append(user_id)

        if status:
            where.append("r.status=%s")
            params.append(status)

        params.append(min(max(int(limit),1),500))

        return self.fetch_all(
            f"""
            SELECT
                r.*,
                rt.name AS request_type_name,
                rt.code AS request_type_code,
                d.name AS department_name,
                trim(concat_ws(
                    ' ',
                    u.first_name,
                    u.last_name
                )) AS requester_name

            FROM {schema}.ops_requests r

            JOIN {schema}.ops_request_types rt
            ON rt.id=r.request_type_id

            LEFT JOIN public.company_departments d
            ON d.id=r.department_id

            LEFT JOIN public.users u
            ON u.id=r.requested_by_user_id

            WHERE {" AND ".join(where)}

            ORDER BY r.created_at DESC,r.id DESC
            LIMIT %s;
            """,
            tuple(params),
        ) or []

    def _ops_workflow_step_matches(
        self,
        company_id:int,
        *,
        workflow_step_id:int,
        request_row:dict,
    ):
        company_id=int(company_id)
        schema=self.company_schema(company_id)

        conditions=self.fetch_all(
            f"""
            SELECT *
            FROM {schema}.ops_workflow_conditions
            WHERE workflow_step_id=%s
            AND is_active=TRUE
            ORDER BY sort_order,id;
            """,
            (int(workflow_step_id),),
        ) or []

        if not conditions:
            return True

        for condition in conditions:
            field=condition["field_name"]
            operator=condition["operator"]
            expected=condition.get("comparison_value")
            actual=request_row.get(field)

            if field=="estimated_amount":
                try:
                    actual=float(actual or 0)
                    expected=float(expected or 0)
                except Exception:
                    return False

            if operator=="eq" and actual!=expected:
                return False
            if operator=="neq" and actual==expected:
                return False
            if operator=="gt" and not actual>expected:
                return False
            if operator=="gte" and not actual>=expected:
                return False
            if operator=="lt" and not actual<expected:
                return False
            if operator=="lte" and not actual<=expected:
                return False

            if operator=="in":
                values=[
                    x.strip()
                    for x in str(expected or "").split(",")
                    if x.strip()
                ]
                if str(actual) not in values:
                    return False

            if operator=="not_in":
                values=[
                    x.strip()
                    for x in str(expected or "").split(",")
                    if x.strip()
                ]
                if str(actual) in values:
                    return False

            if operator=="contains":
                if str(expected or "") not in str(actual or ""):
                    return False

        return True

    def resolve_ops_approver(
        self,
        company_id:int,
        *,
        request_row:dict,
        workflow_step:dict,
    ):
        company_id=int(company_id)
        schema=self.company_schema(company_id)

        approver_type=(
            workflow_step.get("approver_type")
            or ""
        ).strip().lower()

        requester_id=int(
            request_row.get("requested_by_user_id")
            or 0
        )

        if approver_type=="requester_manager":
            row=self.fetch_one(
                """
                SELECT a.manager_user_id
                FROM public.company_users cu
                JOIN public.company_user_assignments a
                ON a.company_user_id=cu.id
                AND a.company_id=cu.company_id
                AND a.is_primary=TRUE
                AND a.is_active=TRUE
                WHERE cu.company_id=%s
                AND cu.user_id=%s
                LIMIT 1;
                """,
                (company_id,requester_id),
            ) or {}

            return row.get("manager_user_id")

        if approver_type=="department_head":
            department_id=request_row.get("department_id")

            if not department_id:
                return None

            row=self.fetch_one(
                """
                SELECT COALESCE(
                    d.manager_user_id,
                    cua_user.user_id
                ) AS user_id
                FROM public.company_departments d

                LEFT JOIN public.company_positions p
                ON p.department_id=d.id
                AND p.company_id=d.company_id
                AND p.is_department_head=TRUE
                AND p.is_active=TRUE

                LEFT JOIN public.company_user_assignments cua
                ON cua.position_id=p.id
                AND cua.company_id=d.company_id
                AND cua.is_primary=TRUE
                AND cua.is_active=TRUE

                LEFT JOIN public.company_users cua_user
                ON cua_user.id=cua.company_user_id
                AND cua_user.is_active=TRUE

                WHERE d.company_id=%s
                AND d.id=%s
                AND d.is_active=TRUE
                LIMIT 1;
                """,
                (
                    company_id,
                    int(department_id),
                ),
            ) or {}

            return row.get("user_id")

        if approver_type=="role":
            role_code=(
                workflow_step.get("approver_role_code")
                or ""
            ).strip().upper()

            if not role_code:
                return None

            row=self.fetch_one(
                f"""
                SELECT cu.user_id
                FROM {schema}.ops_user_roles ur
                JOIN {schema}.ops_roles r
                ON r.id=ur.role_id
                AND r.is_active=TRUE
                JOIN public.company_users cu
                ON cu.id=ur.company_user_id
                AND cu.company_id=%s
                AND cu.is_active=TRUE
                AND cu.ops_is_active=TRUE
                WHERE r.code=%s
                AND ur.is_active=TRUE
                ORDER BY
                    CASE WHEN cu.user_id=%s THEN 1 ELSE 0 END,
                    cu.id
                LIMIT 1;
                """,
                (
                    company_id,
                    role_code,
                    requester_id,
                ),
            ) or {}

            return row.get("user_id")

        if approver_type=="position":
            position_id=workflow_step.get("approver_position_id")

            if not position_id:
                return None

            row=self.fetch_one(
                """
                SELECT cu.user_id
                FROM public.company_user_assignments a
                JOIN public.company_users cu
                ON cu.id=a.company_user_id
                AND cu.company_id=a.company_id
                AND cu.is_active=TRUE
                AND cu.ops_is_active=TRUE
                WHERE a.company_id=%s
                AND a.position_id=%s
                AND a.is_primary=TRUE
                AND a.is_active=TRUE
                ORDER BY
                    CASE WHEN cu.user_id=%s THEN 1 ELSE 0 END,
                    a.id
                LIMIT 1;
                """,
                (
                    company_id,
                    int(position_id),
                    requester_id,
                ),
            ) or {}

            return row.get("user_id")

        if approver_type=="owner":
            return self.fetch_val(
                """
                SELECT owner_user_id
                FROM public.companies
                WHERE id=%s;
                """,
                (company_id,),
            )

        if approver_type=="user":
            return workflow_step.get("approver_user_id")

        return None

    def get_ops_governance_config(self,company_id:int):
        company_id=int(company_id)
        schema=self.company_schema(company_id)

        settings=self.get_ops_settings(company_id)

        workflow=self.fetch_one(
            f"""
            SELECT
                w.id AS workflow_id,
                w.code,
                w.name,
                w.description,
                w.request_type_id,
                v.id AS workflow_version_id,
                v.version_no
            FROM {schema}.ops_workflows w
            JOIN {schema}.ops_workflow_versions v
            ON v.workflow_id=w.id
            AND v.status='active'
            WHERE w.company_id=%s
            AND w.status='active'
            AND w.is_default=TRUE
            ORDER BY v.version_no DESC
            LIMIT 1;
            """,
            (company_id,),
        ) or {}

        steps=[]

        if workflow:
            rows=self.fetch_all(
                f"""
                SELECT
                    s.*,
                    p.title AS approver_position_title,
                    r.name AS approver_role_name
                FROM {schema}.ops_workflow_steps s
                LEFT JOIN public.company_positions p
                ON p.id=s.approver_position_id
                LEFT JOIN {schema}.ops_roles r
                ON r.code=s.approver_role_code
                WHERE s.workflow_version_id=%s
                AND s.is_active=TRUE
                ORDER BY s.step_no;
                """,
                (workflow["workflow_version_id"],),
            ) or []

            for row in rows:
                row=dict(row)

                conditions=self.fetch_all(
                    f"""
                    SELECT *
                    FROM {schema}.ops_workflow_conditions
                    WHERE workflow_step_id=%s
                    AND is_active=TRUE
                    ORDER BY sort_order,id;
                    """,
                    (row["id"],),
                ) or []

                row["conditions"]=conditions
                steps.append(row)

        return {
            "mode":settings.get("governance_mode") or "structured",
            "allow_owner_override":bool(settings.get("allow_owner_override")),
            "require_override_reason":bool(settings.get("require_override_reason")),
            "settings_json":settings.get("settings_json") or {},
            "workflow":workflow or None,
            "steps":steps,
        }

    def save_ops_governance_config(
        self,
        company_id:int,
        payload:dict,
        *,
        actor_user_id:int,
    ):
        company_id=int(company_id)
        actor_user_id=int(actor_user_id)
        schema=self.company_schema(company_id)
        payload=payload or {}

        mode=str(payload.get("mode") or "structured").strip().lower()

        if mode not in {"flexible","structured","controlled"}:
            raise ValueError("Invalid governance mode.")

        steps=payload.get("steps") or []

        if not isinstance(steps,list) or not steps:
            raise ValueError("At least one approval step is required.")

        require_finance_review=bool(payload.get("require_finance_review"))

        if require_finance_review:
            has_finance_step=any(
                (
                    str(step.get("approver_role_code") or "").strip().upper()
                    in {"FINANCE_REVIEWER","FINANCE_MANAGER","CFO","ACCOUNTANT"}
                )
                or (
                    "finance" in str(step.get("name") or "").strip().lower()
                )
                for step in steps
            )

            if not has_finance_step:
                raise ValueError(
                    "Finance review is required, but the workflow has no Finance approval stage."
                )

        allow_owner_override=bool(payload.get("allow_owner_override"))
        require_override_reason=bool(payload.get("require_override_reason"))

        governance_rules={
            "prevent_self_approval":bool(payload.get("prevent_self_approval")),
            "prevent_consecutive_approval":bool(payload.get("prevent_consecutive_approval")),
            "require_finance_review":require_finance_review,
            "require_budget_validation":bool(payload.get("require_budget_validation")),
            "invalidate_approvals_on_change":bool(payload.get("invalidate_approvals_on_change")),
        }

        with self.transaction() as (_conn,cur):
            cur.execute(
                f"""
                SELECT *
                FROM {schema}.ops_workflows
                WHERE company_id=%s
                AND is_default=TRUE
                ORDER BY id
                LIMIT 1
                FOR UPDATE;
                """,
                (company_id,),
            )

            workflow=cur.fetchone()

            if not workflow:
                cur.execute(
                    f"""
                    INSERT INTO {schema}.ops_workflows(
                        company_id,code,name,description,
                        status,is_default,is_system,
                        created_by_user_id
                    )
                    VALUES(
                        %s,'STANDARD_REQUEST',
                        'Standard Request Approval',
                        'Default FinSage Nexus governance workflow',
                        'active',TRUE,TRUE,%s
                    )
                    RETURNING *;
                    """,
                    (company_id,actor_user_id),
                )
                workflow=cur.fetchone()

            workflow_id=int(workflow["id"])

            cur.execute(
                f"""
                SELECT COALESCE(MAX(version_no),0)
                FROM {schema}.ops_workflow_versions
                WHERE workflow_id=%s;
                """,
                (workflow_id,),
            )

            version_no=int(cur.fetchone()[0] or 0)+1

            cur.execute(
                f"""
                UPDATE {schema}.ops_workflow_versions
                SET status='retired',
                    effective_to=NOW()
                WHERE workflow_id=%s
                AND status='active';
                """,
                (workflow_id,),
            )

            cur.execute(
                f"""
                INSERT INTO {schema}.ops_workflow_versions(
                    workflow_id,version_no,status,
                    effective_from,created_by_user_id
                )
                VALUES(%s,%s,'active',NOW(),%s)
                RETURNING id;
                """,
                (
                    workflow_id,
                    version_no,
                    actor_user_id,
                ),
            )

            workflow_version_id=int(cur.fetchone()["id"])

            for index,item in enumerate(steps,1):
                item=item or {}

                name=str(
                    item.get("name")
                    or f"Approval {index}"
                ).strip()

                approver_type=str(
                    item.get("approver_type")
                    or ""
                ).strip().lower()

                if approver_type not in {
                    "requester_manager",
                    "department_head",
                    "role",
                    "position",
                    "user",
                    "owner",
                }:
                    raise ValueError(
                        f"Invalid approver type for step {index}."
                    )

                role_code=(
                    str(item.get("approver_role_code") or "")
                    .strip()
                    .upper()
                    or None
                )

                position_id=item.get("approver_position_id")
                user_id=item.get("approver_user_id")

                if approver_type=="role" and not role_code:
                    raise ValueError(
                        f"Choose a role for '{name}'."
                    )

                if approver_type=="position" and not position_id:
                    raise ValueError(
                        f"Choose a position for '{name}'."
                    )

                if approver_type=="user" and not user_id:
                    raise ValueError(
                        f"Choose a user for '{name}'."
                    )

                if position_id:
                    cur.execute(
                        """
                        SELECT 1
                        FROM public.company_positions
                        WHERE company_id=%s
                        AND id=%s
                        AND is_active=TRUE;
                        """,
                        (company_id,int(position_id)),
                    )

                    if not cur.fetchone():
                        raise ValueError(
                            f"Invalid position for '{name}'."
                        )

                if role_code:
                    cur.execute(
                        f"""
                        SELECT 1
                        FROM {schema}.ops_roles
                        WHERE code=%s
                        AND is_active=TRUE;
                        """,
                        (role_code,),
                    )

                    if not cur.fetchone():
                        raise ValueError(
                            f"Invalid role for '{name}'."
                        )

                finance_roles={
                    "FINANCE_REVIEWER",
                    "FINANCE_MANAGER",
                    "CFO",
                    "ACCOUNTANT",
                }

                is_finance_step=(
                    role_code in finance_roles
                    or "finance" in name.lower()
                )

                cur.execute(
                    f"""
                    INSERT INTO {schema}.ops_workflow_steps(
                        workflow_version_id,
                        step_no,
                        code,
                        name,
                        step_type,
                        approver_type,
                        approver_role_code,
                        approver_position_id,
                        approver_user_id,
                        approval_mode,
                        required_approvals,
                        allow_delegation,
                        allow_reassignment,
                        settings_json,
                        is_active
                    )
                    VALUES(
                        %s,%s,%s,%s,%s,
                        %s,%s,%s,%s,
                        'single',1,
                        %s,%s,%s,TRUE
                    )
                    RETURNING id;
                    """,
                    (
                        workflow_version_id,
                        index,
                        f"GOV_APPROVAL_{index}",
                        name,
                        "review" if is_finance_step else "approval",
                        approver_type,
                        role_code,
                        int(position_id) if position_id else None,
                        int(user_id) if user_id else None,
                        bool(item.get("allow_delegation",mode!="controlled")),
                        bool(item.get("allow_reassignment",mode=="flexible")),
                        psycopg2.extras.Json({
                            "required":bool(item.get("required",True)),
                        }),
                    ),
                )

                step_id=int(cur.fetchone()["id"])

                min_amount=item.get("min_amount")
                max_amount=item.get("max_amount")

                if min_amount not in (None,""):
                    cur.execute(
                        f"""
                        INSERT INTO {schema}.ops_workflow_conditions(
                            workflow_step_id,
                            field_name,
                            operator,
                            comparison_value,
                            sort_order
                        )
                        VALUES(%s,'estimated_amount','gte',%s,10);
                        """,
                        (
                            step_id,
                            str(float(min_amount)),
                        ),
                    )

                if max_amount not in (None,""):
                    cur.execute(
                        f"""
                        INSERT INTO {schema}.ops_workflow_conditions(
                            workflow_step_id,
                            field_name,
                            operator,
                            comparison_value,
                            sort_order
                        )
                        VALUES(%s,'estimated_amount','lte',%s,20);
                        """,
                        (
                            step_id,
                            str(float(max_amount)),
                        ),
                    )

            current_settings=self.get_ops_settings(company_id)
            current_json=current_settings.get("settings_json") or {}

            governance_json={
                **current_json,
                "governance":{
                    **governance_rules,
                    "workflow_version":version_no,
                }
            }

            cur.execute(
                f"""
                UPDATE {schema}.ops_settings
                SET governance_mode=%s,
                    allow_owner_override=%s,
                    require_override_reason=%s,
                    settings_json=%s,
                    setup_step=4,
                    updated_at=NOW()
                WHERE company_id=%s;
                """,
                (
                    mode,
                    allow_owner_override,
                    require_override_reason,
                    psycopg2.extras.Json(governance_json),
                    company_id,
                ),
            )

            cur.execute(
                f"""
                INSERT INTO {schema}.ops_events(
                    event_uuid,event_type,module,
                    entity_type,entity_id,entity_ref,
                    actor_user_id,action,after_json
                )
                VALUES(
                    %s,'governance.updated','governance',
                    'workflow',%s,'STANDARD_REQUEST',
                    %s,'configure',%s
                );
                """,
                (
                    str(uuid.uuid4()),
                    str(workflow_id),
                    actor_user_id,
                    psycopg2.extras.Json({
                        "mode":mode,
                        "workflow_version":version_no,
                        "steps":steps,
                        **governance_rules,
                    }),
                ),
            )

        return self.get_ops_governance_config(company_id)

    def _start_next_ops_workflow_step(
        self,
        company_id:int,
        *,
        request_id:int,
        workflow_instance_id:int,
        after_step_no:int,
        actor_user_id:int,
        cur,
    ):
        company_id=int(company_id)
        request_id=int(request_id)
        workflow_instance_id=int(workflow_instance_id)
        actor_user_id=int(actor_user_id)
        schema=self.company_schema(company_id)

        cur.execute(
            f"""
            SELECT
                wi.workflow_version_id,
                wi.request_revision_no
            FROM {schema}.ops_workflow_instances wi
            WHERE wi.id=%s
            LIMIT 1;
            """,
            (workflow_instance_id,),
        )

        instance=cur.fetchone()

        if not instance:
            raise ValueError("Workflow instance not found.")

        cur.execute(
            f"""
            SELECT *
            FROM {schema}.ops_requests
            WHERE company_id=%s
            AND id=%s
            LIMIT 1;
            """,
            (
                company_id,
                request_id,
            ),
        )

        request_row=dict(cur.fetchone() or {})

        if not request_row:
            raise ValueError("Request not found.")

        revision_no=int(
            request_row.get("revision_no")
            or instance.get("request_revision_no")
            or 1
        )

        cur.execute(
            f"""
            SELECT *
            FROM {schema}.ops_workflow_steps
            WHERE workflow_version_id=%s
            AND step_no>%s
            AND is_active=TRUE
            ORDER BY step_no
            LIMIT 1;
            """,
            (
                instance["workflow_version_id"],
                int(after_step_no),
            ),
        )

        step=cur.fetchone()

        # ========================================================
        # WORKFLOW COMPLETE
        # ========================================================

        if not step:
            governance=self.get_ops_governance_rules(company_id)

            if governance["require_budget_validation"]:
                cur.execute(
                    f"""
                    SELECT bc.*
                    FROM {schema}.ops_budget_checks bc
                    JOIN {schema}.ops_requests r
                    ON r.id=bc.request_id
                    WHERE bc.request_id=%s
                    AND bc.request_revision_no=r.revision_no
                    ORDER BY bc.checked_at DESC,bc.id DESC
                    LIMIT 1;
                    """,
                    (request_id,),
                )

                latest_budget=dict(cur.fetchone() or {})

                if not latest_budget:
                    raise ValueError(
                        "Final approval is blocked because budget validation has not been completed."
                    )

                if latest_budget.get("result") not in {
                    "pass",
                    "warn",
                    "not_required",
                }:
                    raise ValueError(
                        latest_budget.get("message")
                        or "Final approval is blocked by budget control."
                    )

            cur.execute(
                f"""
                UPDATE {schema}.ops_workflow_instances
                SET status='approved',
                    completed_at=NOW(),
                    current_step_no=NULL
                WHERE id=%s;
                """,
                (workflow_instance_id,),
            )

            cur.execute(
                f"""
                UPDATE {schema}.ops_requests
                SET status='approved',
                    approved_at=NOW(),
                    final_approval_revision_no=%s,
                    locked_at=NOW(),
                    locked_by_user_id=%s,
                    updated_at=NOW(),
                    updated_by_user_id=%s
                WHERE id=%s;
                """,
                (
                    revision_no,
                    actor_user_id,
                    actor_user_id,
                    request_id,
                ),
            )

            self.reserve_ops_request_budget(
                company_id,
                request_id,
                actor_user_id=actor_user_id,
                cur=cur,
            )

            procurement_case=self.create_ops_procurement_case(
                company_id,
                request_id,
                actor_user_id=actor_user_id,
                cur=cur,
            )

            document=self.snapshot_ops_requisition(
                company_id,
                request_id,
                actor_user_id=actor_user_id,
                document_status="approved",
                cur=cur,
            )

            return {
                "completed":True,
                "step":None,
                "document_id":document["id"],
                "procurement_case_id":procurement_case["id"],
                "procurement_case_no":procurement_case["case_no"],
            }

        # ========================================================
        # CHECK WHETHER NEXT STEP APPLIES
        # ========================================================

        if not self._ops_workflow_step_matches(
            company_id,
            workflow_step_id=int(step["id"]),
            request_row=request_row,
        ):
            cur.execute(
                f"""
                INSERT INTO {schema}.ops_approval_tasks(
                    workflow_instance_id,
                    workflow_step_id,
                    request_id,
                    request_revision_no,
                    assigned_to_user_id,
                    assigned_by_user_id,
                    status,
                    acted_at
                )
                SELECT
                    %s,%s,%s,
                    request_revision_no,
                    %s,%s,
                    'skipped',NOW()
                FROM {schema}.ops_workflow_instances
                WHERE id=%s;
                """,
                (
                    workflow_instance_id,
                    step["id"],
                    request_id,
                    actor_user_id,
                    actor_user_id,
                    workflow_instance_id,
                ),
            )

            return self._start_next_ops_workflow_step(
                company_id,
                request_id=request_id,
                workflow_instance_id=workflow_instance_id,
                after_step_no=int(step["step_no"]),
                actor_user_id=actor_user_id,
                cur=cur,
            )

        # ========================================================
        # RESOLVE APPROVER
        # ========================================================

        approver_id=self.resolve_ops_approver(
            company_id,
            request_row=request_row,
            workflow_step=dict(step),
        )

        governance=self.get_ops_governance_rules(company_id)

        if not approver_id and governance["mode"]=="flexible":
            approver_id=self.fetch_val(
                """
                SELECT owner_user_id
                FROM public.companies
                WHERE id=%s;
                """,
                (company_id,),
            )

        if not approver_id:
            raise ValueError(
                f"No approver could be resolved for step '{step['name']}'. Check the Governance setup."
            )

        approver_id=int(approver_id)

        # ========================================================
        # SEPARATION OF DUTIES
        # ========================================================

        cur.execute(
            f"""
            SELECT assigned_to_user_id
            FROM {schema}.ops_approval_tasks
            WHERE workflow_instance_id=%s
            AND status='approved'
            ORDER BY id DESC
            LIMIT 1;
            """,
            (workflow_instance_id,),
        )

        previous=cur.fetchone()

        if (
            governance["prevent_consecutive_approval"]
            and previous
            and int(previous["assigned_to_user_id"])==approver_id
        ):
            raise ValueError(
                f"Governance prevents the same person from approving consecutive stages. "
                f"Step '{step['name']}' must be assigned to another approver."
            )

        if (
            governance["prevent_self_approval"]
            and approver_id==int(
                request_row.get("requested_by_user_id")
                or 0
            )
        ):
            raise ValueError(
                f"Governance prevents self-approval. "
                f"Step '{step['name']}' resolves to the requester."
            )

        # ========================================================
        # CREATE APPROVAL TASK
        # ========================================================

        cur.execute(
            f"""
            INSERT INTO {schema}.ops_approval_tasks(
                workflow_instance_id,
                workflow_step_id,
                request_id,
                request_revision_no,
                assigned_to_user_id,
                assigned_by_user_id
            )
            SELECT
                %s,%s,%s,
                request_revision_no,
                %s,%s
            FROM {schema}.ops_workflow_instances
            WHERE id=%s
            RETURNING *;
            """,
            (
                workflow_instance_id,
                step["id"],
                request_id,
                approver_id,
                actor_user_id,
                workflow_instance_id,
            ),
        )

        task=dict(cur.fetchone())

        cur.execute(
            f"""
            UPDATE {schema}.ops_workflow_instances
            SET current_step_no=%s
            WHERE id=%s;
            """,
            (
                step["step_no"],
                workflow_instance_id,
            ),
        )

        return {
            "completed":False,
            "step":dict(step),
            "task":task,
        }

    def validate_ops_workflow_for_request(
        self,
        company_id:int,
        request_id:int,
    ):
        company_id=int(company_id)
        request_id=int(request_id)
        schema=self.company_schema(company_id)

        request_row=self.fetch_one(
            f"""
            SELECT *
            FROM {schema}.ops_requests
            WHERE company_id=%s
            AND id=%s
            LIMIT 1;
            """,
            (company_id,request_id),
        ) or {}

        if not request_row:
            raise ValueError("Request not found.")

        governance=self.get_ops_governance_rules(company_id)

        workflow=self.fetch_one(
            f"""
            SELECT
                w.id AS workflow_id,
                v.id AS workflow_version_id,
                v.version_no
            FROM {schema}.ops_workflows w
            JOIN {schema}.ops_workflow_versions v
            ON v.workflow_id=w.id
            AND v.status='active'
            WHERE w.company_id=%s
            AND w.status='active'
            AND (
                w.request_type_id=%s
                OR w.is_default=TRUE
            )
            ORDER BY
                CASE
                    WHEN w.request_type_id=%s THEN 0
                    ELSE 1
                END,
                v.version_no DESC
            LIMIT 1;
            """,
            (
                company_id,
                request_row["request_type_id"],
                request_row["request_type_id"],
            ),
        ) or {}

        if not workflow:
            raise ValueError(
                "No active approval workflow is configured for this request."
            )

        steps=self.fetch_all(
            f"""
            SELECT *
            FROM {schema}.ops_workflow_steps
            WHERE workflow_version_id=%s
            AND is_active=TRUE
            ORDER BY step_no;
            """,
            (workflow["workflow_version_id"],),
        ) or []

        if not steps:
            raise ValueError(
                "The active approval workflow has no approval stages."
            )

        applicable=[]
        previous_approver_id=None

        for step in steps:
            step=dict(step)

            if not self._ops_workflow_step_matches(
                company_id,
                workflow_step_id=int(step["id"]),
                request_row=request_row,
            ):
                continue

            approver_id=self.resolve_ops_approver(
                company_id,
                request_row=request_row,
                workflow_step=step,
            )

            if not approver_id:
                if governance["mode"]=="flexible":
                    approver_id=self.fetch_val(
                        """
                        SELECT owner_user_id
                        FROM public.companies
                        WHERE id=%s;
                        """,
                        (company_id,),
                    )

                if not approver_id:
                    raise ValueError(
                        f"Governance configuration error: no approver is assigned for '{step['name']}'."
                    )

            approver_id=int(approver_id)

            if (
                governance["prevent_self_approval"]
                and approver_id==int(request_row["requested_by_user_id"])
            ):
                raise ValueError(
                    f"Governance configuration error: '{step['name']}' resolves to the requester, but self-approval is prohibited."
                )

            if (
                governance["prevent_consecutive_approval"]
                and previous_approver_id is not None
                and previous_approver_id==approver_id
            ):
                raise ValueError(
                    f"Governance configuration error: '{step['name']}' resolves to the same person as the preceding approval stage."
                )

            applicable.append({
                "step_id":step["id"],
                "step_no":step["step_no"],
                "step_name":step["name"],
                "step_type":step["step_type"],
                "approver_id":approver_id,
            })

            previous_approver_id=approver_id

        if not applicable:
            raise ValueError(
                "No approval stage applies to this request."
            )

        if governance["require_finance_review"]:
            has_finance_review=any(
                step["step_type"]=="review"
                for step in applicable
            )

            if not has_finance_review:
                raise ValueError(
                    "Governance requires Finance review, but no Finance review stage applies to this request."
                )

        return {
            "governance":governance,
            "workflow":workflow,
            "steps":applicable,
        }

    def submit_ops_request(
        self,
        company_id:int,
        request_id:int,
        *,
        actor_user_id:int,
    ):
        company_id=int(company_id)
        request_id=int(request_id)
        actor_user_id=int(actor_user_id)
        schema=self.company_schema(company_id)

        validation=self.validate_ops_workflow_for_request(
            company_id,
            request_id,
        )

        governance=validation["governance"]

        with self.transaction() as (_conn,cur):
            cur.execute(
                f"""
                SELECT *
                FROM {schema}.ops_requests
                WHERE company_id=%s
                AND id=%s
                FOR UPDATE;
                """,
                (company_id,request_id),
            )

            req=cur.fetchone()

            if not req:
                raise ValueError("Request not found.")

            if req["status"] not in {"draft","returned"}:
                raise ValueError(
                    "Only draft or returned requests can be submitted."
                )

            if int(req["requested_by_user_id"])!=actor_user_id:
                raise PermissionError(
                    "Only the requester can submit this request."
                )

            wf=validation["workflow"]

            cur.execute(
                f"""
                INSERT INTO {schema}.ops_workflow_instances(
                    workflow_id,
                    workflow_version_id,
                    request_id,
                    request_revision_no,
                    status,
                    current_step_no,
                    started_by_user_id
                )
                VALUES(
                    %s,%s,%s,%s,
                    'active',NULL,%s
                )
                RETURNING id;
                """,
                (
                    wf["workflow_id"],
                    wf["workflow_version_id"],
                    request_id,
                    int(req.get("revision_no") or 1),
                    actor_user_id,
                ),
            )

            workflow_instance_id=int(
                cur.fetchone()["id"]
            )

            cur.execute(
                f"""
                UPDATE {schema}.ops_requests
                SET status='pending_approval',
                    submitted_at=NOW(),
                    last_submitted_revision_no=revision_no,
                    current_workflow_instance_id=%s,
                    returned_at=NULL,
                    returned_by_user_id=NULL,
                    last_return_comment=NULL,
                    updated_by_user_id=%s,
                    updated_at=NOW()
                WHERE id=%s;
                """,
                (
                    workflow_instance_id,
                    actor_user_id,
                    request_id,
                ),
            )

            result=self._start_next_ops_workflow_step(
                company_id,
                request_id=request_id,
                workflow_instance_id=workflow_instance_id,
                after_step_no=0,
                actor_user_id=actor_user_id,
                cur=cur,
            )

            document=self.snapshot_ops_requisition(
                company_id,
                request_id,
                actor_user_id=actor_user_id,
                document_status="submitted",
                cur=cur,
            )

            cur.execute(
                f"""
                INSERT INTO {schema}.ops_events(
                    event_uuid,event_type,module,
                    entity_type,entity_id,entity_ref,
                    actor_user_id,action,after_json
                )
                VALUES(
                    %s,'request.submitted','requests',
                    'request',%s,%s,%s,'submit',%s
                );
                """,
                (
                    str(uuid.uuid4()),
                    str(request_id),
                    req["request_no"],
                    actor_user_id,
                    psycopg2.extras.Json({
                        "workflow_instance_id":workflow_instance_id,
                        "workflow_version_id":wf["workflow_version_id"],
                        "governance_mode":governance["mode"],
                        "governance_rules":governance,
                        "validated_steps":validation["steps"],
                        "document_snapshot_id":document["id"],
                        "request_revision_no":int(req.get("revision_no") or 1),
                        "next":result,
                    }),
                ),
            )

        return self.get_ops_request(
            company_id,
            request_id,
        )

    def list_ops_approval_tasks(
        self,
        company_id:int,
        user_id:int,
        *,
        status="pending",
    ):
        company_id=int(company_id)
        user_id=int(user_id)
        schema=self.company_schema(company_id)

        return self.fetch_all(
            f"""
            SELECT
                t.*,

                r.request_no,
                r.title,
                r.description,
                r.business_purpose,
                r.estimated_amount,
                r.currency_code,
                r.priority,
                r.status AS request_status,
                r.submitted_at,
                r.required_date,
                r.department_id,
                r.branch_id,

                rt.code AS request_type_code,
                rt.name AS request_type_name,

                ws.step_no,
                ws.code AS step_code,
                ws.name AS step_name,
                ws.step_type,
                ws.approver_type,
                ws.approval_mode,
                ws.required_approvals,

                wi.current_step_no,
                wi.status AS workflow_status,

                d.name AS department_name,
                b.name AS branch_name,

                trim(concat_ws(
                    ' ',
                    u.first_name,
                    u.last_name
                )) AS requester_name,

                pos.title AS requester_position,

                (
                    SELECT bc.result
                    FROM {schema}.ops_budget_checks bc
                    WHERE bc.request_id=r.id
                    ORDER BY bc.checked_at DESC,bc.id DESC
                    LIMIT 1
                ) AS budget_result,

                (
                    SELECT bc.available_after
                    FROM {schema}.ops_budget_checks bc
                    WHERE bc.request_id=r.id
                    ORDER BY bc.checked_at DESC,bc.id DESC
                    LIMIT 1
                ) AS budget_available_after,

                (
                    SELECT bc.message
                    FROM {schema}.ops_budget_checks bc
                    WHERE bc.request_id=r.id
                    ORDER BY bc.checked_at DESC,bc.id DESC
                    LIMIT 1
                ) AS budget_message,

                (
                    SELECT COUNT(*)
                    FROM {schema}.ops_approval_tasks ta
                    WHERE ta.workflow_instance_id=t.workflow_instance_id
                    AND ta.status='approved'
                ) AS completed_approval_count,

                (
                    SELECT COUNT(*)
                    FROM {schema}.ops_workflow_steps wsa
                    WHERE wsa.workflow_version_id=wi.workflow_version_id
                    AND wsa.is_active=TRUE
                    AND wsa.step_type='approval'
                ) AS total_approval_count

            FROM {schema}.ops_approval_tasks t

            JOIN {schema}.ops_requests r
            ON r.id=t.request_id

            JOIN {schema}.ops_request_types rt
            ON rt.id=r.request_type_id

            JOIN {schema}.ops_workflow_steps ws
            ON ws.id=t.workflow_step_id

            JOIN {schema}.ops_workflow_instances wi
            ON wi.id=t.workflow_instance_id

            LEFT JOIN public.company_departments d
            ON d.id=r.department_id

            LEFT JOIN public.company_branches b
            ON b.id=r.branch_id

            LEFT JOIN public.users u
            ON u.id=r.requested_by_user_id

            LEFT JOIN public.company_users cu
            ON cu.company_id=%s
            AND cu.user_id=r.requested_by_user_id
            AND cu.is_active=TRUE

            LEFT JOIN public.company_user_assignments cua
            ON cua.company_id=%s
            AND cua.company_user_id=cu.id
            AND cua.is_primary=TRUE
            AND cua.is_active=TRUE

            LEFT JOIN public.company_positions pos
            ON pos.id=cua.position_id

            WHERE t.company_id=%s
            AND t.assigned_to_user_id=%s
            AND (%s IS NULL OR t.status=%s)

            ORDER BY
                CASE r.priority
                    WHEN 'urgent' THEN 1
                    WHEN 'high' THEN 2
                    WHEN 'normal' THEN 3
                    ELSE 4
                END,
                t.created_at;
            """,
            (
                company_id,
                company_id,
                company_id,
                user_id,
                status,
                status,
            ),
        ) or []

    def decide_ops_approval(
        self,
        company_id:int,
        task_id:int,
        *,
        actor_user_id:int,
        decision:str,
        comment=None,
    ):
        company_id=int(company_id)
        task_id=int(task_id)
        actor_user_id=int(actor_user_id)
        schema=self.company_schema(company_id)

        decision=(decision or "").strip().lower()
        comment=(comment or "").strip() or None

        if decision not in {"approve","return","reject"}:
            raise ValueError("Invalid approval decision.")

        if decision in {"return","reject"} and not comment:
            raise ValueError(
                "A comment is required when returning or rejecting a request."
            )

        with self.transaction() as (_conn,cur):
            cur.execute(
                f"""
                SELECT
                    t.*,
                    ws.step_no,
                    ws.name AS step_name,
                    ws.step_type,
                    ws.approver_role_code,
                    r.request_no,
                    r.requested_by_user_id
                FROM {schema}.ops_approval_tasks t
                JOIN {schema}.ops_workflow_steps ws
                ON ws.id=t.workflow_step_id
                JOIN {schema}.ops_requests r
                ON r.id=t.request_id
                WHERE t.id=%s
                AND t.company_id=%s
                FOR UPDATE;
                """,
                (task_id,company_id),
            )

            task=cur.fetchone()

            if not task:
                raise ValueError("Approval task not found.")

            request_id=int(task["request_id"])
            workflow_instance_id=int(task["workflow_instance_id"])

            if int(task["assigned_to_user_id"])!=actor_user_id:
                raise PermissionError(
                    "This approval is not assigned to you."
                )

            if task["status"]!="pending":
                raise ValueError(
                    "This approval has already been actioned."
                )

            current_revision=self.fetch_val(
                f"""
                SELECT revision_no
                FROM {schema}.ops_requests
                WHERE id=%s;
                """,
                (request_id,),
            )

            if int(current_revision or 0)!=int(task.get("request_revision_no") or 0):
                raise ValueError(
                    "This Finance review belongs to an older request revision."
                )

            governance=self.get_ops_governance_rules(company_id)

            is_finance_review=(
                task.get("step_type")=="review"
                or str(task.get("approver_role_code") or "").upper()
                in {
                    "FINANCE_REVIEWER",
                    "FINANCE_MANAGER",
                    "CFO",
                    "ACCOUNTANT",
                }
            )

            if decision=="approve" and is_finance_review:
                self.validate_ops_finance_review(
                    company_id,
                    int(task["request_id"]),
                    approval_task_id=task_id,
                )

            if (
                decision=="approve"
                and is_finance_review
                and governance["require_budget_validation"]
            ):
                budget_check=self.check_ops_request_budget(
                    company_id,
                    int(task["request_id"]),
                    actor_user_id=actor_user_id,
                )

                if budget_check.get("result")=="fail":
                    raise ValueError(
                        budget_check.get("message")
                        or "Budget validation failed."
                    )

                if budget_check.get("result")=="unavailable":
                    raise ValueError(
                        "Finance cannot approve this request until financial coding and an approved budget are available."
                    )

                self.execute_sql(
                    f"""
                    UPDATE {schema}.ops_finance_reviews
                    SET budget_result=%s,
                        budget_verified=TRUE,
                        updated_at=NOW()
                    WHERE approval_task_id=%s;
                    """,
                    (
                        budget_check.get("result"),
                        task_id,
                    ),
                    cur=cur,
                )

            if int(task.get("requested_by_user_id") or 0)==actor_user_id:
                settings=self.get_ops_settings(company_id)
                governance_mode=(
                    settings.get("governance_mode")
                    or "structured"
                ).strip().lower()

                if governance_mode in {"structured","controlled"}:
                    raise PermissionError(
                        "You cannot approve your own request under this governance mode."
                    )

            task_status={
                "approve":"approved",
                "return":"returned",
                "reject":"rejected",
            }[decision]

            cur.execute(
                f"""
                UPDATE {schema}.ops_approval_tasks
                SET status=%s,
                    acted_at=NOW()
                WHERE id=%s;
                """,
                (task_status,task_id),
            )

            cur.execute(
                f"""
                INSERT INTO {schema}.ops_approval_decisions(
                    approval_task_id,
                    request_id,
                    request_revision_no,
                    decision,
                    decided_by_user_id,
                    comment,
                    metadata_json
                )
                VALUES(
                    %s,%s,%s,
                    %s,%s,%s,%s
                );
                """,
                (
                    task_id,
                    task["request_id"],
                    int(task.get("request_revision_no") or 1),
                    decision,
                    actor_user_id,
                    comment,
                    psycopg2.extras.Json({
                        "step_no":task["step_no"],
                        "step_name":task["step_name"],
                    }),
                ),
            )

            if decision=="return":
                cur.execute(
                    f"""
                    UPDATE {schema}.ops_workflow_instances
                    SET status='cancelled',
                        cancelled_at=NOW()
                    WHERE id=%s;
                    """,
                    (task["workflow_instance_id"],),
                )

                cur.execute(
                    f"""
                    UPDATE {schema}.ops_approval_tasks
                    SET status='cancelled',
                        acted_at=COALESCE(acted_at,NOW())
                    WHERE workflow_instance_id=%s
                    AND id<>%s
                    AND status='pending';
                    """,
                    (
                        task["workflow_instance_id"],
                        task_id,
                    ),
                )

                cur.execute(
                    f"""
                    UPDATE {schema}.ops_requests
                    SET status='returned',
                        current_workflow_instance_id=NULL,
                        returned_at=NOW(),
                        returned_by_user_id=%s,
                        last_return_comment=%s,
                        updated_by_user_id=%s,
                        updated_at=NOW()
                    WHERE id=%s;
                    """,
                    (
                        actor_user_id,
                        comment,
                        actor_user_id,
                        task["request_id"],
                    ),
                )

            elif decision=="reject":
                cur.execute(
                    f"""
                    UPDATE {schema}.ops_workflow_instances
                    SET status='rejected',
                        completed_at=NOW()
                    WHERE id=%s;
                    """,
                    (task["workflow_instance_id"],),
                )

                cur.execute(
                    f"""
                    UPDATE {schema}.ops_approval_tasks
                    SET status='cancelled',
                        acted_at=COALESCE(acted_at,NOW())
                    WHERE workflow_instance_id=%s
                    AND id<>%s
                    AND status='pending';
                    """,
                    (
                        task["workflow_instance_id"],
                        task_id,
                    ),
                )

                cur.execute(
                    f"""
                    UPDATE {schema}.ops_requests
                    SET status='rejected',
                        rejected_at=NOW(),
                        updated_by_user_id=%s,
                        updated_at=NOW()
                    WHERE id=%s;
                    """,
                    (
                        actor_user_id,
                        task["request_id"],
                    ),
                )

            else:
                self._start_next_ops_workflow_step(
                    company_id,
                    request_id=int(task["request_id"]),
                    workflow_instance_id=int(
                        task["workflow_instance_id"]
                    ),
                    after_step_no=int(task["step_no"]),
                    actor_user_id=actor_user_id,
                    cur=cur,
                )

            event_type={
                "approve":"approval.approved",
                "return":"approval.returned",
                "reject":"approval.rejected",
            }[decision]

            cur.execute(
                f"""
                INSERT INTO {schema}.ops_events(
                    event_uuid,event_type,module,
                    entity_type,entity_id,entity_ref,
                    actor_user_id,action,after_json
                )
                VALUES(
                    %s,%s,'approvals',
                    'request',%s,%s,%s,%s,%s
                );
                """,
                (
                    str(uuid.uuid4()),
                    event_type,
                    str(task["request_id"]),
                    task["request_no"],
                    actor_user_id,
                    decision,
                    psycopg2.extras.Json({
                        "approval_task_id":task_id,
                        "step_no":task["step_no"],
                        "step_name":task["step_name"],
                        "comment":comment,
                    }),
                ),
            )

        return self.get_ops_request(
            company_id,
            int(task["request_id"]),
        )
        
    def resolve_ops_budget_rule(self,company_id:int,request_row:dict):
        company_id=int(company_id)
        schema=self.company_schema(company_id)

        return self.fetch_one(
            f"""
            SELECT *
            FROM {schema}.ops_budget_rules
            WHERE company_id=%s
            AND is_active=TRUE
            AND (request_type_id IS NULL OR request_type_id=%s)
            AND (department_id IS NULL OR department_id=%s)
            AND (branch_id IS NULL OR branch_id=%s)
            AND (account_code IS NULL OR account_code=%s)
            ORDER BY
                CASE WHEN request_type_id IS NOT NULL THEN 1 ELSE 0 END DESC,
                CASE WHEN department_id IS NOT NULL THEN 1 ELSE 0 END DESC,
                CASE WHEN branch_id IS NOT NULL THEN 1 ELSE 0 END DESC,
                CASE WHEN account_code IS NOT NULL THEN 1 ELSE 0 END DESC,
                priority,id
            LIMIT 1;
            """,
            (
                company_id,
                request_row.get("request_type_id"),
                request_row.get("department_id"),
                request_row.get("branch_id"),
                request_row.get("primary_gl_account_code"),
            ),
        )

    def get_ops_financial_budget_position(
        self,
        company_id:int,
        *,
        account_code=None,
        department_id=None,
        branch_id=None,
        project_id=None,
        cost_center_id=None,
        as_of=None,
        basis="ytd",
    ):
        company_id=int(company_id)
        as_of=as_of or date.today()

        if not account_code:
            return {
                "budget_amount":0.0,
                "actual_amount":0.0,
                "financial_commitments":0.0,
                "source":"missing_account",
            }

        budget=self.get_ops_budget_amount(
            company_id,
            account_code=account_code,
            as_of=as_of,
            basis=basis,
        )

        if not budget:
            return {
                "budget_amount":0.0,
                "actual_amount":0.0,
                "financial_commitments":0.0,
                "source":"no_approved_budget",
            }

        actual=self.get_ops_actual_amount(
            company_id,
            account_code=account_code,
            date_from=budget["period_start"],
            date_to=budget["period_end"],
        )

        return {
            "budget_id":budget["id"],
            "budget_name":budget["name"],
            "currency":budget.get("currency"),
            "period_start":budget["period_start"],
            "period_end":budget["period_end"],
            "budget_amount":float(budget.get("budget_amount") or 0),
            "actual_amount":actual,
            "financial_commitments":0.0,
            "basis":basis,
            "source":"finsage_budget_gl",
        }

    def get_ops_active_commitments(
        self,
        company_id:int,
        *,
        account_code=None,
        department_id=None,
        branch_id=None,
        project_id=None,
        cost_center_id=None,
    ):
        company_id=int(company_id)
        schema=self.company_schema(company_id)

        where=[
            "r.company_id=%s",
            "br.status='active'",
        ]
        params=[company_id]

        if account_code:
            where.append("br.account_code=%s")
            params.append(account_code)

        if department_id:
            where.append("r.department_id=%s")
            params.append(department_id)

        if branch_id:
            where.append("r.branch_id=%s")
            params.append(branch_id)

        if project_id:
            where.append("r.project_id=%s")
            params.append(project_id)

        if cost_center_id:
            where.append("r.cost_center_id=%s")
            params.append(cost_center_id)

        value=self.fetch_val(
            f"""
            SELECT COALESCE(SUM(br.amount),0)
            FROM {schema}.ops_budget_reservations br
            JOIN {schema}.ops_requests r ON r.id=br.request_id
            WHERE {" AND ".join(where)};
            """,
            tuple(params),
        )

        return float(value or 0)

    def check_ops_request_budget(
        self,
        company_id:int,
        request_id:int,
        *,
        actor_user_id:int,
    ):
        company_id=int(company_id)
        request_id=int(request_id)
        actor_user_id=int(actor_user_id)
        schema=self.company_schema(company_id)

        req=self.fetch_one(
            f"""
            SELECT *
            FROM {schema}.ops_requests
            WHERE company_id=%s AND id=%s
            LIMIT 1;
            """,
            (company_id,request_id),
        )

        if not req:
            raise ValueError("Request not found.")

        account_code=(req.get("primary_gl_account_code") or "").strip()

        if not account_code:
            item_accounts=self.fetch_all(
                f"""
                SELECT DISTINCT gl_account_code
                FROM {schema}.ops_request_items
                WHERE request_id=%s
                AND COALESCE(gl_account_code,'')<>'';
                """,
                (request_id,),
            ) or []

            if len(item_accounts)==1:
                account_code=item_accounts[0]["gl_account_code"]

        rule=self.resolve_ops_budget_rule(company_id,req)

        if not rule or not bool(rule.get("require_budget_check")):
            result="not_required"
            financial={
                "budget_amount":0,
                "actual_amount":0,
                "financial_commitments":0,
                "source":"not_required",
            }
            ops_commitments=0.0

        elif not account_code:
            result="unavailable"
            financial={
                "budget_amount":0,
                "actual_amount":0,
                "financial_commitments":0,
                "source":"missing_account_code",
            }
            ops_commitments=0.0

        else:
            financial=self.get_ops_financial_budget_position(
                company_id,
                account_code=account_code,
                department_id=req.get("department_id"),
                branch_id=req.get("branch_id"),
                project_id=req.get("project_id"),
                cost_center_id=req.get("cost_center_id"),
                as_of=date.today(),
                basis=rule.get("budget_basis") or "ytd",
            )

            ops_commitments=self.get_ops_active_commitments(
                company_id,
                account_code=account_code,
                department_id=req.get("department_id"),
                branch_id=req.get("branch_id"),
                project_id=req.get("project_id"),
                cost_center_id=req.get("cost_centre_id"),
            )

            if financial.get("source")=="no_approved_budget":
                result="unavailable"
            else:
                budget=float(financial.get("budget_amount") or 0)
                actual=float(financial.get("actual_amount") or 0)
                financial_commitments=float(financial.get("financial_commitments") or 0)
                committed=financial_commitments+ops_commitments
                requested=float(req.get("estimated_amount") or 0)

                available_before=budget-actual-committed
                available_after=available_before-requested

                tolerance_amount=float(rule.get("tolerance_amount") or 0)
                tolerance_percent=float(rule.get("tolerance_percent") or 0)
                tolerance=max(tolerance_amount,budget*(tolerance_percent/100))

                mode=rule.get("control_mode") or "warn"

                if available_after>=-tolerance:
                    result="pass"
                elif mode=="block":
                    result="fail"
                elif mode in {"warn","escalate"}:
                    result="warn"
                else:
                    result="pass"

        budget=float(financial.get("budget_amount") or 0)
        actual=float(financial.get("actual_amount") or 0)
        financial_commitments=float(financial.get("financial_commitments") or 0)
        committed=financial_commitments+ops_commitments
        requested=float(req.get("estimated_amount") or 0)

        available_before=budget-actual-committed
        available_after=available_before-requested

        message={
            "pass":"Request is within available budget.",
            "warn":"Request exceeds available budget and requires review.",
            "fail":"Request exceeds available budget and is blocked.",
            "not_required":"Budget checking is not required for this request.",
            "unavailable":"No approved budget or financial coding is available for this request.",
        }[result]

        with self.transaction() as (_conn,cur):
            cur.execute(
                f"""
                INSERT INTO {schema}.ops_budget_checks(
                    company_id,request_id,budget_rule_id,
                    budget_id,budget_name,
                    account_code,account_name,
                    department_id,branch_id,project_id,cost_center_id,
                    period_start,period_end,
                    requested_amount,
                    budget_amount,actual_amount,
                    financial_commitments,ops_commitments,committed_amount,
                    available_before,available_after,
                    result,control_mode,override_required,message,
                    source_json,checked_by_user_id,
                    request_revision_no
                )
                VALUES(
                    %s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,
                    %s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s
                )
                RETURNING *;
                """,
                (
                    company_id,
                    request_id,
                    rule.get("id") if rule else None,
                    financial.get("budget_id"),
                    financial.get("budget_name"),
                    account_code or None,
                    req.get("primary_gl_account_name"),
                    req.get("department_id"),
                    req.get("branch_id"),
                    req.get("project_id"),
                    req.get("cost_center_id"),
                    financial.get("period_start"),
                    financial.get("period_end"),
                    requested,
                    budget,
                    actual,
                    financial_commitments,
                    ops_commitments,
                    committed,
                    available_before,
                    available_after,
                    result,
                    rule.get("control_mode") if rule else "none",
                    result=="fail",
                    message,
                    psycopg2.extras.Json(financial),
                    actor_user_id,
                ),
            )

            row=dict(cur.fetchone())

            cur.execute(
                f"""
                INSERT INTO {schema}.ops_events(
                    event_uuid,event_type,module,
                    entity_type,entity_id,entity_ref,
                    actor_user_id,action,after_json
                )
                VALUES(%s,'budget.checked','budget','request',%s,%s,%s,'budget_check',%s);
                """,
                (
                    str(uuid.uuid4()),
                    str(request_id),
                    req["request_no"],
                    actor_user_id,
                    psycopg2.extras.Json(row),
                    int(req.get("revision_no") or 1),
                ),
            )

        return row

    def get_ops_budget_amount(
        self,
        company_id:int,
        *,
        account_code:str,
        as_of:date,
        basis:str="ytd",
    ):
        company_id=int(company_id)
        schema=self.company_schema(company_id)

        account_code=str(account_code or "").strip()
        if not account_code:
            return {}

        as_of=as_of or date.today()
        month=as_of.replace(day=1)

        budget=self.fetch_one(
            f"""
            SELECT id,name,currency,period_start,period_end,status
            FROM {schema}.forecast_budgets
            WHERE company_id=%s
            AND status IN('approved','locked')
            AND %s BETWEEN period_start AND period_end
            ORDER BY CASE WHEN status='locked' THEN 0 ELSE 1 END,
                    updated_at DESC,id DESC
            LIMIT 1;
            """,
            (company_id,as_of),
        ) or {}

        if not budget:
            return {}

        if basis=="month":
            amount=self.fetch_val(
                f"""
                SELECT COALESCE(SUM(amount),0)
                FROM {schema}.forecast_budget_lines
                WHERE budget_id=%s
                AND account_code=%s
                AND period_month=%s;
                """,
                (budget["id"],account_code,month),
            )

            period_start=month

            if month.month==12:
                next_month=date(month.year+1,1,1)
            else:
                next_month=date(month.year,month.month+1,1)

            period_end=min(
                as_of,
                next_month-timedelta(days=1),
            )

        elif basis=="full_period":
            amount=self.fetch_val(
                f"""
                SELECT COALESCE(SUM(amount),0)
                FROM {schema}.forecast_budget_lines
                WHERE budget_id=%s
                AND account_code=%s;
                """,
                (budget["id"],account_code),
            )

            period_start=budget["period_start"]
            period_end=budget["period_end"]

        else:
            amount=self.fetch_val(
                f"""
                SELECT COALESCE(SUM(amount),0)
                FROM {schema}.forecast_budget_lines
                WHERE budget_id=%s
                AND account_code=%s
                AND period_month<=%s;
                """,
                (budget["id"],account_code,month),
            )

            period_start=budget["period_start"]
            period_end=as_of

        return {
            **budget,
            "budget_amount":float(amount or 0),
            "period_start":period_start,
            "period_end":period_end,
            "basis":basis,
        }

    def get_ops_actual_amount(
        self,
        company_id:int,
        *,
        account_code:str,
        date_from:date,
        date_to:date,
    ):
        company_id=int(company_id)
        schema=self.company_schema(company_id)

        value=self.fetch_val(
            f"""
            SELECT COALESCE(SUM(jl.debit-jl.credit),0)
            FROM {schema}.journal_lines jl
            JOIN {schema}.journal j ON j.id=jl.journal_id
            WHERE jl.company_id=%s
            AND jl.account_code=%s
            AND j.date BETWEEN %s AND %s
            AND COALESCE(j.is_reversal,FALSE)=FALSE;
            """,
            (
                company_id,
                account_code,
                date_from,
                date_to,
            ),
        )

        return float(value or 0)

    def reserve_ops_request_budget(
        self,
        company_id:int,
        request_id:int,
        *,
        actor_user_id:int,
        cur=None,
    ):
        company_id=int(company_id)
        request_id=int(request_id)
        schema=self.company_schema(company_id)

        if cur is None:
            with self.transaction() as (_conn,tx):
                return self.reserve_ops_request_budget(
                    company_id,
                    request_id,
                    actor_user_id=actor_user_id,
                    cur=tx,
                )

        cur.execute(
            f"""
            SELECT *
            FROM {schema}.ops_budget_checks
            WHERE request_id=%s
            AND result IN('pass','warn')
            ORDER BY checked_at DESC,id DESC
            LIMIT 1;
            """,
            (request_id,),
        )
        check=cur.fetchone()

        if not check:
            return None

        cur.execute(
            f"""
            SELECT id
            FROM {schema}.ops_budget_reservations
            WHERE request_id=%s
            AND reservation_type='requisition_commitment'
            AND status='active'
            LIMIT 1;
            """,
            (request_id,),
        )

        if cur.fetchone():
            return None

        cur.execute(
            f"""
            INSERT INTO {schema}.ops_budget_reservations(
                company_id,request_id,budget_check_id,
                account_code,reservation_type,amount,
                status,created_by_user_id
            )
            VALUES(
                %s,%s,%s,%s,
                'requisition_commitment',
                %s,'active',%s
            )
            RETURNING *;
            """,
            (
                company_id,
                request_id,
                check["id"],
                check.get("account_code"),
                check["requested_amount"],
                actor_user_id,
            ),
        )

        return dict(cur.fetchone())

    def build_ops_requisition_payload(
        self,
        company_id:int,
        request_id:int,
        *,
        cur=None,
    ):
        company_id=int(company_id)
        request_id=int(request_id)
        schema=self.company_schema(company_id)

        if cur is None:
            with self.transaction() as (_conn,tx):
                return self.build_ops_requisition_payload(
                    company_id,
                    request_id,
                    cur=tx,
                )

        cur.execute(
            f"""
            SELECT
                r.*,
                rt.code AS request_type_code,
                rt.name AS request_type_name,
                d.name AS department_name,
                b.name AS branch_name,
                cc.code AS cost_centre_code,
                cc.name AS cost_centre_name,
                trim(concat_ws(' ',u.first_name,u.last_name)) AS requester_name
            FROM {schema}.ops_requests r
            JOIN {schema}.ops_request_types rt
            ON rt.id=r.request_type_id
            LEFT JOIN public.company_departments d
            ON d.id=r.department_id
            LEFT JOIN public.company_branches b
            ON b.id=r.branch_id
            LEFT JOIN public.company_cost_centres cc
            ON cc.id=r.cost_centre_id
            LEFT JOIN public.users u
            ON u.id=r.requested_by_user_id
            WHERE r.company_id=%s
            AND r.id=%s
            LIMIT 1;
            """,
            (company_id,request_id),
        )

        request_row=cur.fetchone()

        if not request_row:
            raise ValueError("Request not found.")

        request_row=dict(request_row)

        cur.execute(
            f"""
            SELECT *
            FROM {schema}.ops_request_items
            WHERE request_id=%s
            ORDER BY line_no,id;
            """,
            (request_id,),
        )

        request_row["items"]=[
            dict(row)
            for row in cur.fetchall()
        ]

        cur.execute(
            """
            SELECT
                id,name,system_company_code,
                company_reg_no,tin,vat,
                company_email,company_phone,
                physical_address,currency,
                logo_url
            FROM public.companies
            WHERE id=%s
            LIMIT 1;
            """,
            (company_id,),
        )

        company=dict(cur.fetchone() or {})

        cur.execute(
            f"""
            SELECT bc.*
            FROM {schema}.ops_budget_checks bc
            WHERE bc.request_id=%s
            AND bc.request_revision_no=%s
            ORDER BY bc.checked_at DESC,bc.id DESC
            LIMIT 1;
            """,
            (
                request_id,
                int(request_row.get("revision_no") or 1),
            ),
        )

        budget=dict(cur.fetchone() or {})

        cur.execute(
            f"""
            SELECT
                fr.*,
                cc.code AS cost_centre_code,
                cc.name AS cost_centre_name,
                trim(concat_ws(' ',u.first_name,u.last_name)) AS reviewer_name
            FROM {schema}.ops_finance_reviews fr
            LEFT JOIN public.company_cost_centres cc
            ON cc.id=fr.cost_centre_id
            LEFT JOIN public.users u
            ON u.id=fr.reviewer_user_id
            WHERE fr.request_id=%s
            AND fr.request_revision_no=%s
            ORDER BY fr.updated_at DESC,fr.id DESC
            LIMIT 1;
            """,
            (request_id,),
            int(request_row.get("revision_no") or 1),
        )

        finance_review=dict(cur.fetchone() or {})

        cur.execute(
            f"""
            SELECT
                d.*,
                ws.name AS step_name,
                ws.step_no,
                trim(concat_ws(' ',u.first_name,u.last_name)) AS decided_by_name
            FROM {schema}.ops_approval_decisions d
            JOIN {schema}.ops_approval_tasks t
            ON t.id=d.approval_task_id
            JOIN {schema}.ops_workflow_steps ws
            ON ws.id=t.workflow_step_id
            LEFT JOIN public.users u
            ON u.id=d.decided_by_user_id
            WHERE d.request_id=%s
            AND d.request_revision_no=%s
            ORDER BY d.decided_at,d.id;
            """,
            (request_id,),
            int(request_row.get("revision_no") or 1),
        )

        approvals=[
            dict(row)
            for row in cur.fetchall()
        ]

        return {
            "document":{
                "type":
                    request_row.get("document_type")
                    or "GENERAL_REQUISITION",

                "number":request_row["request_no"],

                "revision_no":
                    int(request_row.get("revision_no") or 1),
            },
            "company":company,
            "request":request_row,
            "budget":budget,
            "finance_review":finance_review,
            "approvals":approvals,
        }

    def get_ops_request_audit_trail(
        self,
        company_id:int,
        request_id:int,
    ):
        company_id=int(company_id)
        request_id=int(request_id)
        schema=self.company_schema(company_id)

        return self.fetch_all(
            f"""
            SELECT
                e.*,
                trim(concat_ws(' ',u.first_name,u.last_name)) AS actor_name
            FROM {schema}.ops_events e
            LEFT JOIN public.users u
            ON u.id=e.actor_user_id
            WHERE e.entity_type='request'
            AND e.entity_id=%s
            ORDER BY e.created_at,e.id;
            """,
            (str(request_id),),
        ) or []

    def snapshot_ops_requisition(
        self,
        company_id:int,
        request_id:int,
        *,
        actor_user_id:int,
        document_status=None,
        cur=None,
    ):
        company_id=int(company_id)
        request_id=int(request_id)
        actor_user_id=int(actor_user_id)
        schema=self.company_schema(company_id)

        if cur is None:
            with self.transaction() as (_conn,tx):
                return self.snapshot_ops_requisition(
                    company_id,
                    request_id,
                    actor_user_id=actor_user_id,
                    document_status=document_status,
                    cur=tx,
                )

        payload=self.build_ops_requisition_payload(
            company_id,
            request_id,
            cur=cur,
        )

        document_type=payload["document"]["type"]
        revision_no=int(payload["document"]["revision_no"] or 1)

        request_status=payload["request"].get("status") or "draft"

        document_status=document_status or (
            "approved"
            if request_status=="approved"
            else "submitted"
            if request_status in {"submitted","pending_approval"}
            else "draft"
        )

        cur.execute(
            f"""
            SELECT COALESCE(MAX(version_no),0) AS version_no
            FROM {schema}.ops_documents
            WHERE entity_type='request'
            AND entity_id=%s
            AND document_type=%s
            AND request_revision_no=%s;
            """,
            (
                request_id,
                document_type,
                revision_no,
            ),
        )

        version_no=int(
            (cur.fetchone() or {}).get("version_no")
            or 0
        )+1

        cur.execute(
            f"""
            UPDATE {schema}.ops_documents
            SET is_current=FALSE,
                document_status=
                    CASE
                        WHEN document_status='approved'
                        THEN 'superseded'
                        ELSE document_status
                    END
            WHERE entity_type='request'
            AND entity_id=%s
            AND document_type=%s
            AND is_current=TRUE;
            """,
            (
                request_id,
                document_type,
            ),
        )

        cur.execute(
            f"""
            INSERT INTO {schema}.ops_documents(
                company_id,
                entity_type,
                entity_id,

                document_type,
                document_no,

                version_no,
                request_revision_no,

                template_code,
                format,
                document_status,

                generated_by_user_id,
                approved_at,
                approved_by_user_id,

                snapshot_json,
                is_current
            )
            VALUES(
                %s,'request',%s,
                %s,%s,
                %s,%s,
                %s,'snapshot',%s,
                %s,
                CASE WHEN %s='approved' THEN NOW() ELSE NULL END,
                CASE WHEN %s='approved' THEN %s ELSE NULL END,
                %s,TRUE
            )
            RETURNING *;
            """,
            (
                company_id,
                request_id,

                document_type,
                payload["document"]["number"],

                version_no,
                revision_no,

                f"{document_type}_V1",
                document_status,

                actor_user_id,

                document_status,
                document_status,
                actor_user_id,

                psycopg2.extras.Json(payload),
            ),
        )

        row=dict(cur.fetchone())

        cur.execute(
            f"""
            INSERT INTO {schema}.ops_events(
                event_uuid,event_type,module,
                entity_type,entity_id,entity_ref,
                actor_user_id,action,after_json
            )
            VALUES(
                %s,'document.snapshot.created','documents',
                'request',%s,%s,
                %s,'snapshot',%s
            );
            """,
            (
                str(uuid.uuid4()),
                str(request_id),
                payload["document"]["number"],
                actor_user_id,
                psycopg2.extras.Json({
                    "document_id":row["id"],
                    "document_type":document_type,
                    "revision_no":revision_no,
                    "version_no":version_no,
                    "document_status":document_status,
                }),
            ),
        )

        return row

    def generate_ops_requisition_document(
        self,
        company_id:int,
        request_id:int,
        *,
        actor_user_id:int,
        format:str,
        app_root:str,
    ):
        company_id=int(company_id)
        request_id=int(request_id)
        actor_user_id=int(actor_user_id)
        schema=self.company_schema(company_id)

        format=(format or "").strip().lower()

        if format not in {"pdf","xlsx"}:
            raise ValueError(
                "Document format must be PDF or XLSX."
            )

        request_row=self.get_ops_request(
            company_id,
            request_id,
        )

        if not request_row:
            raise ValueError("Request not found.")

        if request_row["status"] not in {
            "pending_approval",
            "approved",
        }:
            raise ValueError(
                "Only submitted or approved requisitions can be exported."
            )

        snapshot=self.snapshot_ops_requisition(
            company_id,
            request_id,
            actor_user_id=actor_user_id,
            document_status=(
                "approved"
                if request_row["status"]=="approved"
                else "submitted"
            ),
        )

        payload=snapshot["snapshot_json"]

        if isinstance(payload,str):
            payload=json.loads(payload)

        request_no=request_row["request_no"]
        revision_no=int(
            request_row.get("revision_no")
            or 1
        )

        safe_no="".join(
            c if c.isalnum() or c in "-_" else "_"
            for c in request_no
        )

        file_name=(
            f"{safe_no}_R{revision_no}."
            f"{format}"
        )

        output_dir=(
            Path(app_root)
            /"static"
            /"generated"
            /"ops"
            /f"company_{company_id}"
            /"requests"
            /str(request_id)
        )

        output_dir.mkdir(
            parents=True,
            exist_ok=True,
        )

        output_path=output_dir/file_name

        if format=="pdf":
            build_requisition_pdf(
                payload,
                output_path,
                root_path=app_root,
            )
            mime_type="application/pdf"

        else:
            build_requisition_xlsx(
                payload,
                output_path,
            )
            mime_type=(
                "application/"
                "vnd.openxmlformats-officedocument."
                "spreadsheetml.sheet"
            )

        file_bytes=output_path.read_bytes()
        checksum=hashlib.sha256(
            file_bytes
        ).hexdigest()

        relative_path=str(
            output_path.relative_to(
                Path(app_root)
            )
        ).replace("\\","/")

        file_url=(
            f"/api/companies/{company_id}"
            f"/ops/documents/{snapshot['id']}/download"
        )

        existing=self.fetch_one(
            f"""
            SELECT *
            FROM {schema}.ops_documents
            WHERE entity_type='request'
            AND entity_id=%s
            AND document_type=%s
            AND request_revision_no=%s
            AND format=%s
            AND is_current=TRUE
            ORDER BY id DESC
            LIMIT 1;
            """,
            (
                request_id,
                snapshot["document_type"],
                revision_no,
                format,
            ),
        )

        if existing:
            self.execute_sql(
                f"""
                UPDATE {schema}.ops_documents
                SET is_current=FALSE
                WHERE id=%s;
                """,
                (existing["id"],),
            )

        row=self.fetch_one(
            f"""
            INSERT INTO {schema}.ops_documents(
                company_id,
                entity_type,
                entity_id,

                document_type,
                document_no,

                version_no,
                request_revision_no,

                template_code,
                format,
                document_status,

                file_name,
                file_url,
                storage_path,
                mime_type,
                file_size,
                checksum_sha256,

                generated_by_user_id,
                approved_at,
                approved_by_user_id,

                snapshot_json,
                is_current
            )
            VALUES(
                %s,'request',%s,
                %s,%s,
                %s,%s,
                %s,%s,%s,
                %s,%s,%s,%s,%s,%s,
                %s,
                CASE WHEN %s='approved' THEN NOW() ELSE NULL END,
                CASE WHEN %s='approved' THEN %s ELSE NULL END,
                %s,TRUE
            )
            RETURNING *;
            """,
            (
                company_id,
                request_id,

                snapshot["document_type"],
                request_no,

                snapshot["version_no"],
                revision_no,

                snapshot["template_code"],
                format,
                snapshot["document_status"],

                file_name,
                file_url,
                relative_path,
                mime_type,
                len(file_bytes),
                checksum,

                actor_user_id,

                snapshot["document_status"],
                snapshot["document_status"],
                actor_user_id,

                psycopg2.extras.Json(payload),
            ),
        )

        return row

    def list_ops_request_documents(
        self,
        company_id:int,
        request_id:int,
    ):
        company_id=int(company_id)
        request_id=int(request_id)
        schema=self.company_schema(company_id)

        return self.fetch_all(
            f"""
            SELECT
                id,
                document_type,
                document_no,
                version_no,
                request_revision_no,
                format,
                document_status,
                file_name,
                file_url,
                mime_type,
                file_size,
                checksum_sha256,
                generated_by_user_id,
                generated_at,
                approved_at,
                is_current
            FROM {schema}.ops_documents
            WHERE company_id=%s
            AND entity_type='request'
            AND entity_id=%s
            ORDER BY
                request_revision_no DESC,
                generated_at DESC,
                id DESC;
            """,
            (
                company_id,
                request_id,
            ),
        ) or []
        
    def seed_ops_industry_organisation(self,company_id:int,*,actor_user_id=None,force=False):
        company_id=int(company_id)

        company=self.fetch_one(
            """
            SELECT id,industry,sub_industry
            FROM public.companies
            WHERE id=%s
            LIMIT 1;
            """,
            (company_id,),
        ) or {}

        if not company:
            raise ValueError("Company not found.")

        settings=self.get_ops_settings(company_id) or {}

        if settings.get("org_template_seeded_at") and not force:
            return {
                "seeded":False,
                "template_key":settings.get("org_template_key"),
                "template_version":settings.get("org_template_version"),
            }

        existing=int(self.fetch_val(
            """
            SELECT COUNT(*)
            FROM public.company_departments
            WHERE company_id=%s;
            """,
            (company_id,),
        ) or 0)

        if existing and not force:
            return {
                "seeded":False,
                "reason":"existing_departments",
                "count":existing,
            }

        template=get_ops_org_template(
            company.get("industry"),
            company.get("sub_industry"),
        )

        with self.transaction() as (_conn,cur):
            for sort_order,dept in enumerate(template["departments"],1):
                cur.execute(
                    """
                    INSERT INTO public.company_departments(
                        company_id,code,name,sort_order,is_active,created_by_user_id
                    )
                    VALUES(%s,%s,%s,%s,TRUE,%s)
                    ON CONFLICT(company_id,code)
                    DO UPDATE SET
                        name=EXCLUDED.name,
                        sort_order=EXCLUDED.sort_order,
                        updated_at=NOW()
                    RETURNING id;
                    """,
                    (
                        company_id,
                        dept["code"],
                        dept["name"],
                        sort_order,
                        actor_user_id,
                    ),
                )
                department_id=int(cur.fetchone()["id"])

                for code,title,authority_level,is_head in dept.get("positions",[]):
                    cur.execute(
                        """
                        INSERT INTO public.company_positions(
                            company_id,department_id,code,title,
                            approval_level,is_department_head,
                            is_active,created_by_user_id
                        )
                        VALUES(%s,%s,%s,%s,%s,%s,TRUE,%s)
                        ON CONFLICT(company_id,code)
                        DO UPDATE SET
                            department_id=EXCLUDED.department_id,
                            title=EXCLUDED.title,
                            approval_level=EXCLUDED.approval_level,
                            is_department_head=EXCLUDED.is_department_head,
                            updated_at=NOW();
                        """,
                        (
                            company_id,
                            department_id,
                            code,
                            title,
                            authority_level,
                            is_head,
                            actor_user_id,
                        ),
                    )

            schema=self.company_schema(company_id)

            cur.execute(
                f"""
                UPDATE {schema}.ops_settings
                SET org_template_key=%s,
                    org_template_version=%s,
                    org_template_seeded_at=NOW(),
                    updated_at=NOW()
                WHERE company_id=%s;
                """,
                (
                    template["key"],
                    template["version"],
                    company_id,
                ),
            )

            cur.execute(
                f"""
                INSERT INTO {schema}.ops_events(
                    event_uuid,event_type,module,
                    entity_type,entity_id,actor_user_id,
                    action,after_json
                )
                VALUES(
                    %s,'organisation.template.seeded','organisation',
                    'company',%s,%s,'seed_template',%s
                );
                """,
                (
                    str(uuid.uuid4()),
                    str(company_id),
                    actor_user_id,
                    psycopg2.extras.Json({
                        "template_key":template["key"],
                        "template_version":template["version"],
                        "departments":[d["code"] for d in template["departments"]],
                    }),
                ),
            )

        return {
            "seeded":True,
            "template_key":template["key"],
            "template_version":template["version"],
        }

    def list_company_cost_centres(self,company_id:int):
        company_id=int(company_id)

        return self.fetch_all(
            """
            SELECT
                cc.*,
                d.name AS department_name,
                b.name AS branch_name,
                p.name AS parent_name
            FROM public.company_cost_centres cc
            LEFT JOIN public.company_departments d
            ON d.id=cc.department_id
            LEFT JOIN public.company_branches b
            ON b.id=cc.branch_id
            LEFT JOIN public.company_cost_centres p
            ON p.id=cc.parent_cost_centre_id
            WHERE cc.company_id=%s
            AND cc.is_active=TRUE
            ORDER BY cc.sort_order,cc.name;
            """,
            (company_id,),
        ) or []


    def create_company_cost_centre(
        self,
        company_id:int,
        payload:dict,
        *,
        actor_user_id:int,
    ):
        company_id=int(company_id)
        payload=payload or {}

        code=str(payload.get("code") or "").strip().upper()
        name=str(payload.get("name") or "").strip()

        if not code:
            raise ValueError("Cost centre code is required.")

        if not name:
            raise ValueError("Cost centre name is required.")

        return self.fetch_one(
            """
            INSERT INTO public.company_cost_centres(
                company_id,code,name,description,
                department_id,branch_id,manager_user_id,
                parent_cost_centre_id,sort_order,
                created_by_user_id
            )
            VALUES(%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
            RETURNING *;
            """,
            (
                company_id,
                code,
                name,
                (payload.get("description") or "").strip() or None,
                payload.get("department_id"),
                payload.get("branch_id"),
                payload.get("manager_user_id"),
                payload.get("parent_cost_centre_id"),
                int(payload.get("sort_order") or 0),
                actor_user_id,
            ),
        )

    def get_ops_finance_metadata(self,company_id:int):
        company_id=int(company_id)
        schema=self.company_schema(company_id)

        accounts=self.fetch_all(
            f"""
            SELECT id,code,name,section,category,subcategory
            FROM {schema}.coa
            WHERE company_id=%s
            AND posting=TRUE
            ORDER BY code;
            """,
            (company_id,),
        ) or []

        cost_centres=self.list_company_cost_centres(company_id)

        return {
            "accounts":accounts,
            "cost_centres":cost_centres,
            "classifications":[
                {"code":"opex","name":"Operating expenditure"},
                {"code":"capex","name":"Capital expenditure"},
                {"code":"inventory","name":"Inventory / Stock"},
                {"code":"prepayment","name":"Prepayment"},
                {"code":"lease","name":"Lease"},
                {"code":"project_cost","name":"External project cost"},
                {"code":"other","name":"Other"},
            ],
            "tax_treatments":[
                {"code":"standard","name":"Standard VAT"},
                {"code":"zero_rated","name":"Zero-rated"},
                {"code":"exempt","name":"Exempt"},
                {"code":"no_vat","name":"No VAT"},
                {"code":"reverse_charge","name":"Reverse charge"},
                {"code":"review_required","name":"Further tax review required"},
            ],
        }

    def get_ops_finance_review(
        self,
        company_id:int,
        request_id:int,
        *,
        approval_task_id=None,
    ):
        company_id=int(company_id)
        request_id=int(request_id)
        schema=self.company_schema(company_id)

        params=[request_id]
        task_filter=""

        if approval_task_id:
            task_filter=" AND fr.approval_task_id=%s"
            params.append(int(approval_task_id))

        review=self.fetch_one(
            f"""
            SELECT
                fr.*,
                cc.code AS cost_centre_code,
                cc.name AS cost_centre_name,
                trim(concat_ws(' ',u.first_name,u.last_name)) AS reviewer_name
            FROM {schema}.ops_finance_reviews fr
            LEFT JOIN public.company_cost_centres cc
            ON cc.id=fr.cost_centre_id
            LEFT JOIN public.users u
            ON u.id=fr.reviewer_user_id
            WHERE fr.request_id=%
            AND fr.request_revision_no=rq.revision_no
            {task_filter}
            ORDER BY fr.created_at DESC
            LIMIT 1;
            """,
            tuple(params),
        )

        request_row=self.get_ops_request(company_id,request_id)

        if not request_row:
            raise ValueError("Request not found.")

        budget=self.fetch_one(
            f"""
            SELECT bc.*
            FROM {schema}.ops_budget_checks bc
            JOIN {schema}.ops_requests r
            ON r.id=bc.request_id
            WHERE bc.request_id=%s
            AND bc.request_revision_no=r.revision_no
            ORDER BY bc.checked_at DESC,bc.id DESC
            LIMIT 1;
            """,
            (request_id,),
        )
        return {
            "review":review,
            "request":request_row,
            "budget":budget,
            "metadata":self.get_ops_finance_metadata(company_id),
        }

    def save_ops_finance_review(
        self,
        company_id:int,
        request_id:int,
        payload:dict,
        *,
        actor_user_id:int,
        approval_task_id:int,
    ):
        company_id=int(company_id)
        request_id=int(request_id)
        actor_user_id=int(actor_user_id)
        approval_task_id=int(approval_task_id)
        schema=self.company_schema(company_id)
        payload=payload or {}

        classification=str(payload.get("classification") or "").strip().lower()
        account_code=str(payload.get("account_code") or "").strip()
        cost_centre_id=payload.get("cost_centre_id")
        project_id=payload.get("project_id")
        tax_treatment=str(payload.get("tax_treatment") or "").strip().lower()

        allowed_classifications={
            "opex","capex","inventory",
            "prepayment","lease",
            "project_cost","other",
        }

        allowed_tax={
            "standard","zero_rated","exempt",
            "no_vat","reverse_charge",
            "review_required",
        }

        if classification not in allowed_classifications:
            raise ValueError("Financial classification is required.")

        if not account_code:
            raise ValueError("GL account is required.")

        if tax_treatment not in allowed_tax:
            raise ValueError("Tax treatment is required.")

        task=self.fetch_one(
            f"""
            SELECT
                t.id,
                t.request_id,
                t.request_revision_no,
                t.workflow_instance_id,
                t.assigned_to_user_id,
                t.status,
                ws.step_type,
                ws.approver_role_code
            FROM {schema}.ops_approval_tasks t
            JOIN {schema}.ops_workflow_steps ws
            ON ws.id=t.workflow_step_id
            WHERE t.company_id=%s
            AND t.id=%s
            AND t.request_id=%s
            LIMIT 1;
            """,
            (
                company_id,
                approval_task_id,
                request_id,
            ),
        ) or {}

        if not task:
            raise ValueError("Finance approval task not found.")

        if int(task["assigned_to_user_id"])!=actor_user_id:
            raise PermissionError(
                "This Finance review is not assigned to you."
            )

        current_revision=self.fetch_val(
            f"""
            SELECT revision_no
            FROM {schema}.ops_requests
            WHERE id=%s;
            """,
            (task["request_id"],),
        )

        if int(current_revision or 0)!=int(task.get("request_revision_no") or 0):
            raise ValueError(
                "This approval belongs to an older request revision and can no longer be actioned."
            )

        is_finance=(
            task.get("step_type")=="review"
            or str(task.get("approver_role_code") or "").upper()
            in {
                "FINANCE_REVIEWER",
                "FINANCE_MANAGER",
                "CFO",
                "ACCOUNTANT",
            }
        )

        if not is_finance:
            raise ValueError(
                "This approval stage is not a Finance review."
            )

        account=self.fetch_one(
            f"""
            SELECT id,code,name
            FROM {schema}.coa
            WHERE company_id=%s
            AND code=%s
            AND posting=TRUE
            LIMIT 1;
            """,
            (company_id,account_code),
        ) or {}

        if not account:
            raise ValueError("Invalid posting GL account.")

        if cost_centre_id:
            valid_cost_centre=self.fetch_one(
                """
                SELECT id
                FROM public.company_cost_centres
                WHERE company_id=%s
                AND id=%s
                AND is_active=TRUE;
                """,
                (
                    company_id,
                    int(cost_centre_id),
                ),
            )

            if not valid_cost_centre:
                raise ValueError("Invalid cost centre.")

        before=self.fetch_one(
            f"""
            SELECT *
            FROM {schema}.ops_finance_reviews
            WHERE approval_task_id=%s
            LIMIT 1;
            """,
            (approval_task_id,),
        )

        with self.transaction() as (_conn,cur):
            cur.execute(
                f"""
                INSERT INTO {schema}.ops_finance_reviews(
                    company_id,
                    request_id,
                    request_revision_no,
                    workflow_instance_id,
                    approval_task_id,
                    reviewer_user_id,
                    status,

                    classification,
                    account_code,
                    account_name,
                    cost_centre_id,
                    project_id,
                    tax_treatment,

                    gl_verified,
                    tax_verified,
                    documents_verified,

                    coding_json,
                    updated_at
                )
                VALUES(
                    %s,%s,%s,%s,%s,%s,'pending',
                    %s,%s,%s,%s,%s,%s,
                    %s,%s,%s,
                    %s,NOW()
                )
                ON CONFLICT(approval_task_id)
                WHERE approval_task_id IS NOT NULL
                DO UPDATE SET
                    reviewer_user_id=EXCLUDED.reviewer_user_id,
                    classification=EXCLUDED.classification,
                    account_code=EXCLUDED.account_code,
                    account_name=EXCLUDED.account_name,
                    cost_centre_id=EXCLUDED.cost_centre_id,
                    project_id=EXCLUDED.project_id,
                    tax_treatment=EXCLUDED.tax_treatment,
                    gl_verified=EXCLUDED.gl_verified,
                    tax_verified=EXCLUDED.tax_verified,
                    documents_verified=EXCLUDED.documents_verified,
                    coding_json=EXCLUDED.coding_json,
                    updated_at=NOW()
                RETURNING *;
                """,
                (
                    company_id,
                    request_id,
                    int(task.get("request_revision_no") or 1),
                    task["workflow_instance_id"],
                    approval_task_id,
                    actor_user_id,

                    classification,
                    account["code"],
                    account["name"],
                    int(cost_centre_id) if cost_centre_id else None,
                    int(project_id) if project_id else None,
                    tax_treatment,

                    bool(payload.get("gl_verified")),
                    bool(payload.get("tax_verified")),
                    bool(payload.get("documents_verified")),

                    psycopg2.extras.Json({
                        "classification":classification,
                        "account_code":account["code"],
                        "account_name":account["name"],
                        "cost_centre_id":cost_centre_id,
                        "project_id":project_id,
                        "tax_treatment":tax_treatment,
                    }),
                ),
            )

            review=dict(cur.fetchone())

            cur.execute(
                f"""
                UPDATE {schema}.ops_requests
                SET financial_classification=%s,
                    primary_gl_account_code=%s,
                    primary_gl_account_name=%s,
                    cost_centre_id=%s,
                    project_id=%s,
                    tax_treatment=%s,
                    finance_coded_at=NOW(),
                    finance_coded_by_user_id=%s,
                    updated_by_user_id=%s,
                    updated_at=NOW()
                WHERE id=%s;
                """,
                (
                    classification,
                    account["code"],
                    account["name"],
                    int(cost_centre_id) if cost_centre_id else None,
                    int(project_id) if project_id else None,
                    tax_treatment,
                    actor_user_id,
                    actor_user_id,
                    request_id,
                ),
            )

            cur.execute(
                f"""
                UPDATE {schema}.ops_request_items
                SET gl_account_code=COALESCE(gl_account_code,%s),
                    gl_account_name=COALESCE(gl_account_name,%s),
                    cost_centre_id=COALESCE(cost_centre_id,%s),
                    financial_classification=COALESCE(financial_classification,%s),
                    tax_treatment=COALESCE(tax_treatment,%s)
                WHERE request_id=%s;
                """,
                (
                    account["code"],
                    account["name"],
                    int(cost_centre_id) if cost_centre_id else None,
                    classification,
                    tax_treatment,
                    request_id,
                ),
            )

            cur.execute(
                f"""
                INSERT INTO {schema}.ops_events(
                    event_uuid,event_type,module,
                    entity_type,entity_id,entity_ref,
                    actor_user_id,action,
                    before_json,after_json
                )
                SELECT
                    %s,'finance.coding.updated','finance',
                    'request',%s,r.request_no,
                    %s,'financial_classification',
                    %s,%s
                FROM {schema}.ops_requests r
                WHERE r.id=%s;
                """,
                (
                    str(uuid.uuid4()),
                    str(request_id),
                    actor_user_id,
                    psycopg2.extras.Json(before or {}),
                    psycopg2.extras.Json(review),
                    request_id,
                ),
            )

        return self.get_ops_finance_review(
            company_id,
            request_id,
            approval_task_id=approval_task_id,
        )


    def validate_ops_finance_review(
        self,
        company_id:int,
        request_id:int,
        *,
        approval_task_id:int,
    ):
        company_id=int(company_id)
        request_id=int(request_id)
        approval_task_id=int(approval_task_id)
        schema=self.company_schema(company_id)

        review=self.fetch_one(
            f"""
            SELECT *
            FROM {schema}.ops_finance_reviews
            WHERE request_id=%s
            AND approval_task_id=%s
            LIMIT 1;
            """,
            (
                request_id,
                approval_task_id,
            ),
        ) or {}

        if not review:
            raise ValueError(
                "Complete the Finance review before approval."
            )

        missing=[]

        if not review.get("classification"):
            missing.append("financial classification")

        if not review.get("account_code"):
            missing.append("GL account")

        if not review.get("tax_treatment"):
            missing.append("tax treatment")

        if not bool(review.get("gl_verified")):
            missing.append("GL verification")

        if not bool(review.get("tax_verified")):
            missing.append("tax review")

        if not bool(review.get("documents_verified")):
            missing.append("supporting-document review")

        if missing:
            raise ValueError(
                "Finance review is incomplete: "
                +", ".join(missing)+"."
            )

        return review

    def update_ops_procurement_settings(
        self,
        company_id:int,
        *,
        payload:dict,
        actor_user_id:int,
    ):
        company_id=int(company_id)
        actor_user_id=int(actor_user_id)
        schema=self.company_schema(company_id)

        return self.fetch_one(
            f"""
            UPDATE {schema}.ops_procurement_settings
            SET procurement_enabled=%s,
                default_currency=%s,
                require_approved_request=%s,
                allow_direct_purchase=%s,
                allow_emergency_override=%s,
                allow_sole_source=%s,
                vendor_compliance_required=%s,
                block_unverified_vendors=%s,
                default_quote_validity_days=%s,
                default_rfq_response_days=%s,
                procurement_sender_name=%s,
                procurement_sender_email=%s,
                procurement_reply_to=%s,
                email_provider=%s,
                smtp_host=%s,
                smtp_port=%s,
                smtp_security=%s,
                smtp_username=%s,
                auto_send_rfq=%s,
                auto_send_po=%s,
                send_quote_reminders=%s,
                updated_by_user_id=%s,
                updated_at=NOW()
            WHERE company_id=%s
            RETURNING *;
            """,
            (
                bool(payload.get("procurement_enabled",True)),
                payload.get("default_currency"),
                bool(payload.get("require_approved_request",True)),
                bool(payload.get("allow_direct_purchase")),
                bool(payload.get("allow_emergency_override",True)),
                bool(payload.get("allow_sole_source",True)),
                bool(payload.get("vendor_compliance_required")),
                bool(payload.get("block_unverified_vendors")),
                int(payload.get("default_quote_validity_days") or 30),
                int(payload.get("default_rfq_response_days") or 7),
                (payload.get("procurement_sender_name") or "").strip() or None,
                (payload.get("procurement_sender_email") or "").strip() or None,
                (payload.get("procurement_reply_to") or "").strip() or None,
                payload.get("email_provider") or "system",
                (payload.get("smtp_host") or "").strip() or None,
                payload.get("smtp_port"),
                payload.get("smtp_security"),
                (payload.get("smtp_username") or "").strip() or None,
                bool(payload.get("auto_send_rfq")),
                bool(payload.get("auto_send_po")),
                bool(payload.get("send_quote_reminders",True)),
                actor_user_id,
                company_id,
            ),
        )

    def list_ops_procurement_vendors(
        self,
        company_id:int,
        *,
        search=None,
        procurement_status=None,
        qualification_status=None,
        preferred=None,
    ):
        company_id=int(company_id)
        schema=self.company_schema(company_id)

        where=[
            "v.company_id=%s",
            "v.is_active=TRUE",
        ]

        params=[company_id]

        if search:
            where.append(
                """
                (
                    v.name ILIKE %s
                    OR COALESCE(v.external_code,'') ILIKE %s
                    OR COALESCE(v.email,'') ILIKE %s
                    OR COALESCE(v.phone,'') ILIKE %s
                    OR COALESCE(p.category_tags,'[]'::jsonb)::text ILIKE %s
                )
                """
            )

            q=f"%{search.strip()}%"

            params.extend([
                q,q,q,q,q
            ])

        if procurement_status:
            where.append(
                "COALESCE(p.procurement_status,'available')=%s"
            )
            params.append(procurement_status)

        if qualification_status:
            where.append(
                "COALESCE(p.qualification_status,'not_reviewed')=%s"
            )
            params.append(qualification_status)

        if preferred is not None:
            where.append(
                "COALESCE(p.preferred,FALSE)=%s"
            )
            params.append(bool(preferred))

        return self.fetch_all(
            f"""
            SELECT
                v.id AS vendor_id,
                v.external_code,
                v.name,
                v.email,
                v.phone,
                v.country,
                v.tax_number,
                v.vat_number,
                v.registration_no,
                v.payment_terms,
                v.vendor_status,
                v.on_hold,
                v.is_active,
                v.compliance_status,
                v.compliance_required,
                v.missing_docs,

                p.id AS procurement_profile_id,

                COALESCE(
                    p.procurement_status,
                    'available'
                ) AS procurement_status,

                COALESCE(
                    p.qualification_status,
                    'not_reviewed'
                ) AS qualification_status,

                COALESCE(
                    p.portal_status,
                    'not_invited'
                ) AS portal_status,

                COALESCE(
                    p.preferred,
                    FALSE
                ) AS preferred,

                COALESCE(
                    p.portal_enabled,
                    TRUE
                ) AS portal_enabled,

                COALESCE(
                    p.category_tags,
                    '[]'::jsonb
                ) AS category_tags,

                p.risk_rating,
                p.performance_score,
                p.default_lead_time_days,
                p.sourcing_notes,
                p.compliance_notes,
                p.last_reviewed_at,
                p.last_reviewed_by_user_id,

                (
                    SELECT COUNT(*)
                    FROM {schema}.ops_vendor_contacts c
                    WHERE c.vendor_id=v.id
                    AND c.is_active=TRUE
                ) AS procurement_contact_count,

                (
                    SELECT c.name
                    FROM {schema}.ops_vendor_contacts c
                    WHERE c.vendor_id=v.id
                    AND c.is_active=TRUE
                    AND c.is_primary=TRUE
                    ORDER BY c.id
                    LIMIT 1
                ) AS primary_contact_name,

                (
                    SELECT c.email
                    FROM {schema}.ops_vendor_contacts c
                    WHERE c.vendor_id=v.id
                    AND c.is_active=TRUE
                    AND c.is_primary=TRUE
                    ORDER BY c.id
                    LIMIT 1
                ) AS primary_contact_email

            FROM {schema}.vendors v

            LEFT JOIN {schema}.ops_vendor_profiles p
            ON p.vendor_id=v.id
            AND p.company_id=v.company_id

            WHERE {' AND '.join(where)}

            ORDER BY
                COALESCE(p.preferred,FALSE) DESC,
                CASE COALESCE(
                    p.qualification_status,
                    'not_reviewed'
                )
                    WHEN 'qualified' THEN 1
                    WHEN 'conditional' THEN 2
                    WHEN 'not_reviewed' THEN 3
                    ELSE 4
                END,
                v.name;
            """,
            tuple(params),
        ) or []

    def get_ops_procurement_vendor(
        self,
        company_id:int,
        vendor_id:int,
    ):
        company_id=int(company_id)
        vendor_id=int(vendor_id)
        schema=self.company_schema(company_id)

        vendor=self.fetch_one(
            f"""
            SELECT
                v.*,

                p.id AS procurement_profile_id,
                COALESCE(
                    p.procurement_status,
                    'available'
                ) AS procurement_status,

                COALESCE(
                    p.qualification_status,
                    'not_reviewed'
                ) AS qualification_status,

                COALESCE(
                    p.portal_status,
                    'not_invited'
                ) AS portal_status,

                COALESCE(
                    p.preferred,
                    FALSE
                ) AS preferred,

                COALESCE(
                    p.portal_enabled,
                    TRUE
                ) AS portal_enabled,

                COALESCE(
                    p.category_tags,
                    '[]'::jsonb
                ) AS category_tags,

                p.risk_rating,
                p.performance_score,
                p.default_lead_time_days,
                p.sourcing_notes,
                p.compliance_notes,
                p.last_sourced_at,
                p.last_awarded_at,
                p.last_reviewed_at,

                trim(concat_ws(
                    ' ',
                    ru.first_name,
                    ru.last_name
                )) AS reviewed_by_name

            FROM {schema}.vendors v

            LEFT JOIN {schema}.ops_vendor_profiles p
            ON p.vendor_id=v.id
            AND p.company_id=v.company_id

            LEFT JOIN public.users ru
            ON ru.id=p.last_reviewed_by_user_id

            WHERE v.company_id=%s
            AND v.id=%s
            LIMIT 1;
            """,
            (
                company_id,
                vendor_id,
            ),
        )

        if not vendor:
            raise ValueError("Vendor not found.")

        contacts=self.fetch_all(
            f"""
            SELECT *
            FROM {schema}.ops_vendor_contacts
            WHERE company_id=%s
            AND vendor_id=%s
            AND is_active=TRUE
            ORDER BY
                is_primary DESC,
                contact_type,
                name;
            """,
            (
                company_id,
                vendor_id,
            ),
        ) or []

        return {
            "vendor":vendor,
            "contacts":contacts,
        }

    def save_ops_vendor_profile(
        self,
        company_id:int,
        vendor_id:int,
        *,
        payload:dict,
        actor_user_id:int,
    ):
        company_id=int(company_id)
        vendor_id=int(vendor_id)
        actor_user_id=int(actor_user_id)
        schema=self.company_schema(company_id)
        payload=payload or {}

        vendor=self.fetch_one(
            f"""
            SELECT *
            FROM {schema}.vendors
            WHERE company_id=%s
            AND id=%s
            AND is_active=TRUE
            LIMIT 1;
            """,
            (
                company_id,
                vendor_id,
            ),
        )

        if not vendor:
            raise ValueError("Vendor not found.")

        procurement_status=(
            payload.get("procurement_status")
            or "available"
        )

        qualification_status=(
            payload.get("qualification_status")
            or "not_reviewed"
        )

        portal_status=(
            payload.get("portal_status")
            or "not_invited"
        )

        if procurement_status not in {
            "available",
            "preferred",
            "restricted",
            "blocked",
        }:
            raise ValueError(
                "Invalid procurement status."
            )

        if qualification_status not in {
            "not_reviewed",
            "qualified",
            "conditional",
            "disqualified",
        }:
            raise ValueError(
                "Invalid qualification status."
            )

        if portal_status not in {
            "not_invited",
            "invited",
            "active",
            "suspended",
        }:
            raise ValueError(
                "Invalid vendor portal status."
            )

        risk_rating=payload.get("risk_rating")

        if risk_rating not in {
            None,
            "",
            "low",
            "medium",
            "high",
        }:
            raise ValueError(
                "Invalid vendor risk rating."
            )

        before=self.fetch_one(
            f"""
            SELECT *
            FROM {schema}.ops_vendor_profiles
            WHERE company_id=%s
            AND vendor_id=%s
            LIMIT 1;
            """,
            (
                company_id,
                vendor_id,
            ),
        )

        with self.transaction() as (_conn,cur):
            cur.execute(
                f"""
                INSERT INTO {schema}.ops_vendor_profiles(
                    company_id,
                    vendor_id,

                    procurement_status,
                    qualification_status,
                    portal_status,

                    preferred,
                    portal_enabled,

                    category_tags,
                    risk_rating,
                    performance_score,
                    default_lead_time_days,

                    sourcing_notes,
                    compliance_notes,

                    last_reviewed_at,
                    last_reviewed_by_user_id,

                    created_by_user_id,
                    updated_by_user_id
                )
                VALUES(
                    %s,%s,
                    %s,%s,%s,
                    %s,%s,
                    %s,%s,%s,%s,
                    %s,%s,
                    NOW(),%s,
                    %s,%s
                )
                ON CONFLICT(company_id,vendor_id)
                DO UPDATE SET
                    procurement_status=
                        EXCLUDED.procurement_status,

                    qualification_status=
                        EXCLUDED.qualification_status,

                    portal_status=
                        EXCLUDED.portal_status,

                    preferred=
                        EXCLUDED.preferred,

                    portal_enabled=
                        EXCLUDED.portal_enabled,

                    category_tags=
                        EXCLUDED.category_tags,

                    risk_rating=
                        EXCLUDED.risk_rating,

                    performance_score=
                        EXCLUDED.performance_score,

                    default_lead_time_days=
                        EXCLUDED.default_lead_time_days,

                    sourcing_notes=
                        EXCLUDED.sourcing_notes,

                    compliance_notes=
                        EXCLUDED.compliance_notes,

                    last_reviewed_at=NOW(),

                    last_reviewed_by_user_id=
                        EXCLUDED.last_reviewed_by_user_id,

                    updated_by_user_id=
                        EXCLUDED.updated_by_user_id,

                    updated_at=NOW()

                RETURNING *;
                """,
                (
                    company_id,
                    vendor_id,

                    procurement_status,
                    qualification_status,
                    portal_status,

                    bool(payload.get("preferred")),
                    bool(payload.get("portal_enabled",True)),

                    psycopg2.extras.Json(
                        payload.get("category_tags")
                        or []
                    ),

                    risk_rating or None,

                    payload.get("performance_score"),

                    payload.get(
                        "default_lead_time_days"
                    ),

                    (
                        payload.get("sourcing_notes")
                        or ""
                    ).strip() or None,

                    (
                        payload.get("compliance_notes")
                        or ""
                    ).strip() or None,

                    actor_user_id,

                    actor_user_id,
                    actor_user_id,
                ),
            )

            profile=dict(cur.fetchone())

            cur.execute(
                f"""
                INSERT INTO {schema}.ops_events(
                    event_uuid,
                    event_type,
                    module,
                    entity_type,
                    entity_id,
                    entity_ref,
                    actor_user_id,
                    action,
                    before_json,
                    after_json
                )
                VALUES(
                    %s,
                    'procurement.vendor_profile.updated',
                    'procurement',
                    'vendor',
                    %s,%s,
                    %s,
                    'update_profile',
                    %s,%s
                );
                """,
                (
                    str(uuid.uuid4()),
                    str(vendor_id),
                    vendor.get("name"),
                    actor_user_id,
                    psycopg2.extras.Json(
                        dict(before or {})
                    ),
                    psycopg2.extras.Json(
                        profile
                    ),
                ),
            )

        return self.get_ops_procurement_vendor(
            company_id,
            vendor_id,
        )

    def create_ops_vendor_contact(
        self,
        company_id:int,
        vendor_id:int,
        *,
        payload:dict,
        actor_user_id:int,
    ):
        company_id=int(company_id)
        vendor_id=int(vendor_id)
        actor_user_id=int(actor_user_id)
        schema=self.company_schema(company_id)
        payload=payload or {}

        name=(payload.get("name") or "").strip()
        email=(payload.get("email") or "").strip() or None
        phone=(payload.get("phone") or "").strip() or None

        if not name:
            raise ValueError(
                "Contact name is required."
            )

        if not email and not phone:
            raise ValueError(
                "Provide an email address or phone number."
            )

        contact_type=(
            payload.get("contact_type")
            or "procurement"
        )

        if contact_type not in {
            "procurement",
            "sales",
            "accounts",
            "delivery",
            "general",
        }:
            raise ValueError(
                "Invalid contact type."
            )

        is_primary=bool(
            payload.get("is_primary")
        )

        with self.transaction() as (_conn,cur):
            cur.execute(
                f"""
                SELECT id,name
                FROM {schema}.vendors
                WHERE company_id=%s
                AND id=%s
                AND is_active=TRUE;
                """,
                (
                    company_id,
                    vendor_id,
                ),
            )

            vendor=cur.fetchone()

            if not vendor:
                raise ValueError("Vendor not found.")

            if is_primary:
                cur.execute(
                    f"""
                    UPDATE {schema}.ops_vendor_contacts
                    SET is_primary=FALSE,
                        updated_at=NOW()
                    WHERE company_id=%s
                    AND vendor_id=%s
                    AND contact_type=%s
                    AND is_active=TRUE;
                    """,
                    (
                        company_id,
                        vendor_id,
                        contact_type,
                    ),
                )

            cur.execute(
                f"""
                INSERT INTO {schema}.ops_vendor_contacts(
                    company_id,
                    vendor_id,
                    name,
                    job_title,
                    email,
                    phone,
                    contact_type,
                    is_primary,
                    created_by_user_id,
                    updated_by_user_id
                )
                VALUES(
                    %s,%s,%s,%s,%s,
                    %s,%s,%s,%s,%s
                )
                RETURNING *;
                """,
                (
                    company_id,
                    vendor_id,
                    name,
                    (
                        payload.get("job_title")
                        or ""
                    ).strip() or None,
                    email,
                    phone,
                    contact_type,
                    is_primary,
                    actor_user_id,
                    actor_user_id,
                ),
            )

            row=dict(cur.fetchone())

            cur.execute(
                f"""
                INSERT INTO {schema}.ops_events(
                    event_uuid,event_type,module,
                    entity_type,entity_id,entity_ref,
                    actor_user_id,action,after_json
                )
                VALUES(
                    %s,
                    'procurement.vendor_contact.created',
                    'procurement',
                    'vendor',
                    %s,%s,
                    %s,
                    'add_contact',
                    %s
                );
                """,
                (
                    str(uuid.uuid4()),
                    str(vendor_id),
                    vendor["name"],
                    actor_user_id,
                    psycopg2.extras.Json(row),
                ),
            )

        return row


    def update_ops_vendor_contact(
        self,
        company_id:int,
        vendor_id:int,
        contact_id:int,
        *,
        payload:dict,
        actor_user_id:int,
    ):
        company_id=int(company_id)
        vendor_id=int(vendor_id)
        contact_id=int(contact_id)
        actor_user_id=int(actor_user_id)
        schema=self.company_schema(company_id)
        payload=payload or {}

        current=self.fetch_one(
            f"""
            SELECT *
            FROM {schema}.ops_vendor_contacts
            WHERE company_id=%s
            AND vendor_id=%s
            AND id=%s
            LIMIT 1;
            """,
            (
                company_id,
                vendor_id,
                contact_id,
            ),
        )

        if not current:
            raise ValueError(
                "Vendor contact not found."
            )

        contact_type=payload.get(
            "contact_type",
            current["contact_type"],
        )

        is_primary=bool(
            payload.get(
                "is_primary",
                current.get("is_primary"),
            )
        )

        with self.transaction() as (_conn,cur):
            if is_primary:
                cur.execute(
                    f"""
                    UPDATE {schema}.ops_vendor_contacts
                    SET is_primary=FALSE,
                        updated_at=NOW()
                    WHERE company_id=%s
                    AND vendor_id=%s
                    AND contact_type=%s
                    AND id<>%s
                    AND is_active=TRUE;
                    """,
                    (
                        company_id,
                        vendor_id,
                        contact_type,
                        contact_id,
                    ),
                )

            cur.execute(
                f"""
                UPDATE {schema}.ops_vendor_contacts
                SET name=%s,
                    job_title=%s,
                    email=%s,
                    phone=%s,
                    contact_type=%s,
                    is_primary=%s,
                    is_active=%s,
                    updated_by_user_id=%s,
                    updated_at=NOW()
                WHERE company_id=%s
                AND vendor_id=%s
                AND id=%s
                RETURNING *;
                """,
                (
                    (
                        payload.get(
                            "name",
                            current["name"],
                        )
                        or ""
                    ).strip(),

                    payload.get(
                        "job_title",
                        current.get("job_title"),
                    ),

                    payload.get(
                        "email",
                        current.get("email"),
                    ),

                    payload.get(
                        "phone",
                        current.get("phone"),
                    ),

                    contact_type,
                    is_primary,

                    bool(
                        payload.get(
                            "is_active",
                            current.get("is_active",True),
                        )
                    ),

                    actor_user_id,
                    company_id,
                    vendor_id,
                    contact_id,
                ),
            )

            row=dict(cur.fetchone())

        return row

    def list_ops_procurement_policies(self,company_id:int):
        company_id=int(company_id)
        schema=self.company_schema(company_id)

        rows=self.fetch_all(
            f"""
            SELECT
                p.*,
                d.name AS department_name,
                b.name AS branch_name,
                rt.name AS request_type_name
            FROM {schema}.ops_procurement_policies p
            LEFT JOIN public.company_departments d
            ON d.id=p.department_id
            LEFT JOIN public.company_branches b
            ON b.id=p.branch_id
            LEFT JOIN {schema}.ops_request_types rt
            ON rt.id=p.request_type_id
            WHERE p.company_id=%s
            ORDER BY p.priority,p.name;
            """,
            (company_id,),
        ) or []

        for row in rows:
            row["rules"]=self.fetch_all(
                f"""
                SELECT *
                FROM {schema}.ops_procurement_policy_rules
                WHERE policy_id=%s
                ORDER BY min_amount,priority,id;
                """,
                (row["id"],),
            ) or []

        return rows

    def create_ops_procurement_policy(
        self,
        company_id:int,
        *,
        payload:dict,
        actor_user_id:int,
    ):
        company_id=int(company_id)
        actor_user_id=int(actor_user_id)
        schema=self.company_schema(company_id)

        name=(payload.get("name") or "").strip()
        code=(payload.get("code") or "").strip().upper()

        if not name:
            raise ValueError("Policy name is required.")

        if not code:
            raise ValueError("Policy code is required.")

        return self.fetch_one(
            f"""
            INSERT INTO {schema}.ops_procurement_policies(
                company_id,
                code,
                name,
                description,
                governance_mode,
                department_id,
                branch_id,
                request_type_id,
                currency_code,
                is_default,
                priority,
                created_by_user_id
            )
            VALUES(
                %s,%s,%s,%s,%s,%s,
                %s,%s,%s,%s,%s,%s
            )
            RETURNING *;
            """,
            (
                company_id,
                code,
                name,
                (payload.get("description") or "").strip() or None,
                payload.get("governance_mode"),
                payload.get("department_id"),
                payload.get("branch_id"),
                payload.get("request_type_id"),
                payload.get("currency_code"),
                bool(payload.get("is_default")),
                int(payload.get("priority") or 100),
                actor_user_id,
            ),
        )

    def update_ops_procurement_policy(
        self,
        company_id:int,
        policy_id:int,
        *,
        payload:dict,
        actor_user_id:int,
    ):
        company_id=int(company_id)
        policy_id=int(policy_id)
        actor_user_id=int(actor_user_id)
        schema=self.company_schema(company_id)
        payload=payload or {}

        current=self.fetch_one(
            f"""
            SELECT *
            FROM {schema}.ops_procurement_policies
            WHERE company_id=%s
            AND id=%s
            LIMIT 1;
            """,
            (
                company_id,
                policy_id,
            ),
        )

